      integer opti(90)
c ##A2,12##
c ##A3,13##
      real*8 rmin
c ##A3,13##
c ##A19,47##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      character*80 binfile(101)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
c ##A19,47##
c ##A20,15##
      real*8 treal,tuser,tsys
c ##A20,15##
c ##AN28,17##
      real*8 K2,AU,MSUN
c ##AN28,17##
c ##ANO29,28##
      real*8 maxjc
c ##ANO29,28##
c ##A35,10##
      integer idtag(NMAX)
c ##A35,10##
c
c Local
      integer i,j,k,n,itmp,nhit,ihit(CMAX),jhit(CMAX),chit(CMAX)
      integer dtflag,ejflag,nowflag,stopflag,nstored,ce(NMAX)
      integer nclo,iclo(CMAX),jclo(CMAX),nce,ice(NMAX),jce(NMAX)
      real*8 tmp0,h,hdid,tout,tdump,tfun,tlog,tsmall,dtdump,dtfun
      real*8 thit(CMAX),dhit(CMAX),thit1,x0(3,NMAX),v0(3,NMAX)
      real*8 rce(NMAX),rphys(NMAX),rcrit(NMAX),a(NMAX)
      real*8 dclo(CMAX),tclo(CMAX),epoch(NMAX)
      real*8 ixvclo(6,CMAX),jxvclo(6,CMAX)
      real*8 erre					  !NEW!
      integer ifl       			          !NEW!
c ##A5,6##
      integer nclo2,iclo2(CMAX),jclo2(CMAX)
      real*8 dclo2(CMAX),tclo2(CMAX)
      real*8 ixvclo2(6,CMAX),jxvclo2(6,CMAX)
      integer nbclo,bclo(nbod)
      character*1 aux(CMAX)
      character*107 cce(FMAX)
      integer flagce(2)
      integer nhit2
      integer index(NMAX)
c ##A5,6##
c ##E9,38##
      integer clflag
c ##E9,38##
c ##E11,1##
      real*8 mej(NMAX)
c ##E11,1##
c ##A19,48##
      real*8 x(3,NMAX),v(3,NMAX)
      external mfo_all,onestep,coord,bcoord
      real*8 xv0(nov),yv0(nov),zv0(nov)
      real*8 xc0(noc),yc0(noc),zc0(noc)
c ##A19,48##
c ##A22,31##
      integer nelim
c ##A22,31##
c ##E14,7##
      real*8 tcol
c ##E14,7##
c ##ANEO27,6##
      integer colflag
c ##ANEO27,6##
c ##ANO29,6##
      real*8 psflag(2,NMAX)
      real*8 xps(3,NMAX),vps(3,NMAX)
      integer nps,ps(NMAX)
      real*8 tly
c ##ANO29,6##
c ##A31,4##
      real*8 thcon
c ##A31,4##
c ##A32,8##
      real*8 msum,mlost0,mlost,omg0,per
      integer stopflag0(4)
c ##A32,8##
c ##A39,56##
      real*8 chk(3,nbod)
      integer nbod7,nbod0
      real*8 m7(nbod),x7(3,nbod),v7(3,nbod)
      real*8 s7(3,nbod),rho7(nbod),rceh7(nbod),ngf7(4,nbod)
      real*8 rcrit7(NMAX)
      integer stat7(nbod),idtag7(NMAX)
      character*8 id7(nbod)
      integer icek(2),ice0
      real*8 xk(3,nbod),vk(3,nbod)
      real*8 norm(3)
c ##A39,56##
c ##A44,5##
      integer rotflag
c ##A44,5##
c ##A43,3##
      integer lapla1(nbod)
      integer lapla2(nbod)
c ##A43,3##
c
c------------------------------------------------------------------------------
c
c Initialize variables. DTFLAG = 0 implies first ever call to ONESTEP
      dtout  = abs(dtout)
c ##ANO29,45##
      if (opti(42).eq.1) dtout = abs(optr(28))
c ##ANO29,45##
c ##E9,39##
c      dtdump = abs(h0) * ndump
      dtdump = abs(dtdump)
      clflag = 0
c ##E9,39##
      dtfun  = abs(h0) * nfun
      dtflag = 0
      nstored = 0
c ##A5,34##
      nbclo = 0
c ##A5,34##
      tsmall = h0 * 1.d-8
      h = h0
      do j = 2, nbod
        ce(j) = 0.d0
      end do
c ##A5,35##
      flagce(1) = 1
      flagce(2) = 0
c ##A5,35##
c ##E14,28##
      tcol = time
c ##E14,28##
c ##ANO29,17##
      maxjc = 0.d0
      optr(28) = dabs(optr(28))
c ##ANO29,17##
c ##A32,18##
      if (opti(62).eq.1) then
        mlost = HUGE
        do j = 1, nbod
          if (j.ge.opti(66).and.j.le.opti(67)) then
            if (m(j).lt.mlost) mlost = m(j)
          end if
        end do
        if (optr(46).ne.0.and.mlost.ne.0) optr(44) =
     %    1.d0/abs(optr(39)) * log(abs(optr(46)/mlost))
      end if
      if (opti(63).eq.1) then
        if (optr(47).ne.0) optr(45) =
     %    1.d0/abs(optr(39))*log(abs((TWOPI/optr(6))/optr(47)))
      end if
c ##A32,18##
c
c ##A43,4##
      do j = 1, nbod
        lapla1(j) = 0
        lapla2(j) = 0
      end do
c ##A43,4##
c
c Calculate close-encounter limits and physical radii for massive bodies
c ##A17,17##
c ##AN28,31##
      call mce_init (tstart,algor,h0,jcen,rcen,rmax,cefac,nbod,nbig,
     %  m,xh,vh,s,rho,rceh,rphys,rce,rcrit,id,opt,outfile(2),1,opti,
     %  K2,AU,MSUN,ngflag)
c ##AN28,31##
c ##A17,17##
c
c Set up time of next output, times of previous dump, log and periodic effect
      if (opflag.eq.-1) then
        tout = tstart
      else
        n = int (abs (time - tstart) / dtout) + 1
        tout = tstart  +  dtout * sign (dble(n), tstop - tstart)
        if ((tstop - tstart)*(tout - tstop).gt.0) tout = tstop
      end if
      tdump = time
      tfun  = time
      tlog  = time
c ##ANO29,31##
c      tly   = time
c ##ANO29,31##
c ##A31,5##
      n = int (abs (time - tstart) / h0) + 1
      thcon = tstart  +  h0 * sign (dble(n), tstop - tstart)
      if ((tstop - tstart)*(h0 - tstop).gt.0) thcon = tstop
c ##A31,5##
c
c ##A19,49##
c Convert to internal coordinates and velocities
c ##A38,77##
      call coord(time-tstart,jcen,nbod,2,optr(6),m,xh,vh,x,v,ngf,ngflag,
     %  opt,optr,opti,K2,AU,MSUN)
c ##A38,77##
c
c      if (algor.ge.13.and.opti(72).eq.1) then
c        do j = 1, nov
c          xv0(j) = xv(j)
c          yv0(j) = yv(j)
c          zv0(j) = zv(j)
c        end do
c      end if
c ##A19,49##
c
c ##A39,94##
      if (opti(80).eq.1) then
c        call coord(time-tstart,jcen,nbod,2,optr(6),m,chk,v0,xps,vps,ngf,ngflag,
c     %    opt,optr,opti,K2,AU,MSUN)
c        do j = opti(82)+1, nbod
c          chk(1,j) = xps(1,j)
c          chk(2,j) = xps(2,j)
c          chk(3,j) = xps(3,j)
c        end do
        nbod7 = nbod
        if (opti(81).ge.0.and.opti(81).lt.3) nbod = opti(82)
c        if (opti(81).eq.1) opti(81) = 0
      end if
      optr(66) = dtout
      optr(68) = h0
c ##A39,94##
c
c------------------------------------------------------------------------------
c
c  MAIN  LOOP  STARTS  HERE
c
 100  continue
c
c Is it time for output ?
c ##ANO29,35##
      if (abs(tout-time).lt.abs(tsmall).and.opflag.ge.-1) then
c      if ((abs(tout-time).lt.abs(tsmall).or.(abs(time-tly)
c     %  .ge.abs(optr(28)).and.opti(42).eq.1)).and.opflag.ge.-1) then
c ##ANO29,35##
c
c Beware: the integration may change direction at this point!!!!
        if (opflag.eq.-1) dtflag = 0
c ##A19,50##
c Convert to heliocentric coordinates and output data for all bodies
c ##A39,96##
        if (opti(80).eq.1.and.opti(81).eq.0) then
          nbod0 = nbod
          nbod  = nbod7
        end if
c ##A39,96##
c ##A38,78##
        call bcoord(time-tstart,jcen,nbod,2,optr(6),m,x,v,xh,vh,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,78##
c ##A19,50##
c ##E9,40##
        if (opflag.eq.-1) clflag = 1
c ##E9,40##
c
c ##A39,79##
        if (opti(81).eq.1) then
          nbod0 = nbod
          call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),x7,xps)
          call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),v7,vps)
          do j = 1, nbod7-opti(82)
            k = j + nbod
            xh(1,k) = xps(1,j)+xh(1,2)
            xh(2,k) = xps(2,j)+xh(2,2)
            xh(3,k) = xps(3,j)+xh(3,2)
            vh(1,k) = vps(1,j)+vh(1,2)
            vh(2,k) = vps(2,j)+vh(2,2)
            vh(3,k) = vps(3,j)+vh(3,2)
            m(k)   = m7(j)
            s(1,k) = s7(1,j)
            s(2,k) = s7(2,j)
            s(3,k) = s7(3,j)
            rho(k) = rho7(j)
            rceh(k) = rceh7(j)
            rcrit(k) = rcrit7(j)
            stat(k) = stat7(j)
            id(k) = id7(j)
            ngf(1,k) = ngf7(1,j)
            ngf(2,k) = ngf7(2,j)
            ngf(3,k) = ngf7(3,j)
            ngf(4,k) = ngf7(4,j)
            idtag(k) = idtag7(j)
            x(1,k) = xh(1,k)
            x(2,k) = xh(2,k)
            x(3,k) = xh(3,k)
            v(1,k) = vh(1,k)
            v(2,k) = vh(2,k)
            v(3,k) = vh(3,k)
          end do
          opti(82) = nbod0
          nbod = k
          nbod7 = nbod
          opti(81) = 0
          optr(63) = time
        end if
c ##A39,79##
c
c Output data for all bodies
c ##A13,20##
c ##AN28,39##
c ##A32,16##
c ##A35,35##
        call mio_out (time,jcen,rcen,rmax,nbod,nbig,m,xh,vh,s,rho,
     %    stat,id,opt,opflag,algor,outfile(1),tstart,K2,AU,MSUN,
     %    optr,idtag)
c ##A35,35##
c ##A32,16##
c ##AN28,39##
c ##A13,20##
c ##A2,9##
c ##A5,36##
c ##A24,17##
c ##AN28,74##
c ##A35,50##
        call mio_ce (time,tstart,rcen,rmax,nbod,nbig,m,stat,id,
     %    0,iclo,jclo,opt,stopflag,tclo,dclo,ixvclo,jxvclo,mem,lmem,
     %    outfile,nstored,0,opti(1),aux,cce,algor,jcen,s,rho,nbclo,
     %    bclo,flagce,opti,optr,K2,AU,MSUN,idtag)
c ##A35,50##
c ##AN28,74##
c ##A24,17##
c ##A5,36##
c ##A2,9##
        tmp0 = tstop - tout
        tout = tout + sign( min( abs(tmp0), abs(dtout) ), tmp0 )
c ##E9,41##
        if ((clflag.eq.1)
     %    .or.(abs(tstop-time).le.abs(tsmall).and.opflag.ne.-1)) then
c
c Update the data dump files
          do j = 2, nbod
            epoch(j) = time
          end do
c ##A1,27##
c ##A2,27##
c ##A3,25##
c ##A19,123##
c ##A20,25##
c ##AN28,10##
c ##A35,23##
c ##A38,138##
c ##A19,216##
          call mio_dump (time,tstart,tstop,dtout,algor,h,tol,jcen,rcen,
     %      rmax,en,am,cefac,ndump,nfun,nbod,nbig,m,xh,vh,s,rho,rceh,
     %      stat,id,ngf,epoch,opt,opflag,dumpfile,mem,lmem,optr,opti,
     %      rmin,dtdump,nov,nop,noc,dens,binfile,outfile,treal,tuser,
     %      tsys,K2,AU,MSUN,idtag,ngflag,xv,yv,zv,noe,kkk,mc,xc,yc,zc)
c ##A19,216##
c ##A38,138##
c ##A35,23##
c ##AN28,10##
c ##A20,25##
c ##A19,123##
c ##A3,25##
c ##A2,27##
c ##A1,27##
c ##A39,80##
          if (opti(80).eq.1.and.(opti(81).ge.0
     %      .and.opti(81).lt.3)) nbod = nbod0
c ##A39,80##
          tdump = time
          clflag = 0
        end if
c ##E9,41##
c ##ANO29,36##
        if (opti(42).eq.1) then
          call ren (nbod,id,x,v,optr)
c          tly = time
        end if
c ##ANO29,36##
      end if
c
c If integration has finished return to the main part of programme
c ##A19,51##
      if (abs(tstop-time).le.abs(tsmall).and.opflag.ne.-1) then
c ##A39,97##
        if (opti(80).eq.1.and.opti(81).eq.0) then
          nbod0 = nbod
          nbod  = nbod7
        end if
c ##A39,97##
c ##A38,79##
        call bcoord(time-tstart,jcen,nbod,2,optr(6),m,x,v,xh,vh,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,79##
c
c ##A39,81##
        if (opti(81).eq.1) then
          nbod0 = nbod
          call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),x7,xps)
          call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),v7,vps)
          do j = 1, nbod7-opti(82)
            k = j + nbod
            xh(1,k) = xps(1,j)+xh(1,2)
            xh(2,k) = xps(2,j)+xh(2,2)
            xh(3,k) = xps(3,j)+xh(3,2)
            vh(1,k) = vps(1,j)+vh(1,2)
            vh(2,k) = vps(2,j)+vh(2,2)
            vh(3,k) = vps(3,j)+vh(3,2)
            m(k)   = m7(j)
            s(1,k) = s7(1,j)
            s(2,k) = s7(2,j)
            s(3,k) = s7(3,j)
            rho(k) = rho7(j)
            rceh(k) = rceh7(j)
            rcrit(k) = rcrit7(j)
            stat(k) = stat7(j)
            id(k) = id7(j)
            ngf(1,k) = ngf7(1,j)
            ngf(2,k) = ngf7(2,j)
            ngf(3,k) = ngf7(3,j)
            ngf(4,k) = ngf7(4,j)
            idtag(k) = idtag7(j)
            x(1,k) = xh(1,k)
            x(2,k) = xh(2,k)
            x(3,k) = xh(3,k)
            v(1,k) = vh(1,k)
            v(2,k) = vh(2,k)
            v(3,k) = vh(3,k)
          end do
          opti(82) = nbod0
          nbod = k
          nbod7 = nbod
          opti(81) = 0
          optr(63) = time
        end if
c ##A39,81##
c
        return
      end if
c ##A19,51##
c
c Set the timestep
      if (opflag.eq.-1) tmp0 = tstart - time
      if (opflag.eq.-2) tmp0 = tstop  - time
      if (opflag.ge.0)  tmp0 = tout   - time
      h = sign ( max( min( abs(tmp0), abs(h) ), tsmall), tmp0 )
c
c ##A31,6##
      if (opti(51).eq.1) then
        tmp0 = thcon - time
        if (abs(h).gt.abs(tmp0)) then
          if (tmp0.ne.0) h = sign ( max( min( abs(tmp0), abs(h) ),
     %      tsmall), h )
          thcon = thcon + h0
        end if
      end if
c ##A31,6##
c
c ##A32,9##
      stopflag0(1) = opti(62)
      stopflag0(3) = opti(63)
      call mce_criteria2 (time,tstart,nbod,algor,opt(3),m,id,opti,optr,
     %  mem,lmem,K2)
      stopflag0(2) = opti(62)
      stopflag0(4) = opti(63)
      if (((stopflag0(1).gt.stopflag0(2)).or.(stopflag0(3)
     %  .gt.stopflag0(4))).and.opti(79).eq.1) then
        call bcoord(time-tstart,jcen,nbod,2,optr(6),m,x,v,xh,vh,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
        tstop = time
        return
      end if
      if (opti(62).eq.2) then
        msum = 0.d0
        mlost= 0.d0
        do j = 1, nbod
          if (j.ge.opti(66).and.j.le.opti(67)) then
            mlost0 = m(j)
            m(j) = m(j) * exp(optr(44)*abs(h))
            mlost = mlost + (mlost0 - m(j))
            if (j.eq.1) then
              if ((algor.eq.14.or.algor.eq.17.or.algor.eq.20)
     %          .or.(algor.eq.15.or.algor.eq.18.or.algor.eq.21)
     %          .or.algor.eq.22) then
                do i = 1, noc
                  if (mlost0.ne.0) then
                    mc(i) = mc(i) * (m(1) / mlost0)
                  else
                    mc(i) = HUGE
                  end if
                  if (mc(i).le.TINY) mc(i) = 0.d0
                  if (mc(i).ge.HUGE) mc(i) = HUGE
                end do
              end if
              do i = 1, opti(21)
                if (mlost0.ne.0) then
                  dens(i) = dens(i) * (m(1) / mlost0)
                else
                  dens(i) = HUGE
                end if
              end do
              if (opti(71).eq.1) then
                if (m(1).ne.0) then
                  optr(6) = optr(6) * (mlost0 / m(1))
                else
                  optr(6) = HUGE
                end if
              end if
            end if
            if (m(j).le.TINY) m(j) = 0.d0
            if (m(j).ge.HUGE) m(j) = HUGE
          end if
          if (j.ge.opti(69).and.j.le.opti(70)) msum = msum + m(j)
        end do
        if (opti(68).eq.1) then
          do j = 1, nbod
            if (j.ge.opti(69).and.j.le.opti(70)) then
              if (msum.ne.0) m(j) = m(j) + mlost * (m(j) / msum)
            end if
          end do
        end if
      end if
      if (opti(63).eq.2) then
        omg0 = optr(6)
        optr(6) = optr(6) * exp(optr(45)*abs(h))
        if (abs(optr(6)).le.TINY) optr(6) = 0.d0
        if (abs(optr(6)).ge.HUGE) optr(6) = HUGE
        if (opti(71).eq.1) then
          if (optr(6).ne.0) then
            m(1) = m(1) * abs(omg0 / optr(6))
          else
            m(1) = HUGE
          end if
          if ((algor.eq.14.or.algor.eq.17.or.algor.eq.20)
     %      .or.(algor.eq.15.or.algor.eq.18.or.algor.eq.21)
     %      .or.algor.eq.22) then
            do i = 1, noc
              if (optr(6).ne.0) then
                mc(i) = mc(i) * abs(omg0 / optr(6))
              else
                mc(i) = HUGE
              end if
              if (mc(i).le.TINY) mc(i) = 0.d0
              if (mc(i).ge.HUGE) mc(i) = HUGE
            end do
          end if
          do i = 1, opti(21)
            if (optr(6).ne.0) then
              dens(i) = dens(i) * abs(omg0 / optr(6))
            else
              dens(i) = HUGE
            end if
          end do
        end if
      end if
c ##A32,9##
c
c Save the current coordinates and velocities
c
c ##A39,120##
      if (opti(80).eq.1) then
        nbod0 = nbod
        if (opti(81).lt.3) nbod  = nbod7
      end if
c ##A39,120##
c
c ##A19,52##
c      call mco_iden (time,jcen,nbod,nbig,h,m,xh,vh,x0,v0,ngf,ngflag,opt)
c      call mco_iden (time,jcen,nbod,nbig,h,m,x,v,x0,v0,ngf,ngflag,opt)
c ##A38,80##
      call bcoord(time-tstart,jcen,nbod,2,optr(6),m,x,v,x0,v0,ngf,
     %  ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,80##
c ##A19,52##
c
c ##A39,121##
      if (opti(80).eq.1) nbod = nbod0
c ##A39,121##
c
c ##ANO29,7##
      if (opti(41).eq.1) then
        do j = nbig+1, nbod
          psflag(1,j) = -1
          if (j.lt.opti(47).or.j.gt.opti(48)) then
            psflag(1,j) = sign(1.d0,optr(29)*x0(1,j)+optr(30)*x0(2,j)
     %        +optr(31)*x0(3,j)+optr(32))
          end if
          ps(j) = 0
        end do
      end if
c ##ANO29,7##
c
c Advance one timestep
c
c ##ANEO27,5##
      colflag = 0
      if (algor.ne.6) then
c ##AN28,80##
