            ps(j) = 1
            nps = nps + 1
          end if
        end do
        if (nps.gt.0) then
          do j = nbig+1, nbod
            if (ps(j).ne.0) then
              xps(1,j) = x0(1,j)
              xps(2,j) = x0(2,j)
              xps(3,j) = x0(3,j)
              vps(1,j) = v0(1,j)
              vps(2,j) = v0(2,j)
              vps(3,j) = v0(3,j)
