          xv0(j) = xv(j)
          yv0(j) = yv(j)
          zv0(j) = zv(j)
        end do
        do j = 1, noc
          xc0(j) = xc(j)
          yc0(j) = yc(j)
          zc0(j) = zc(j)
        end do
        call mco_astrot (nov,hdid,optr(6),xv0,yv0,zv0,xv,yv,zv)
        call mco_astrot (noc,hdid,optr(6),xc0,yc0,zc0,xc,yc,zc)
