          do j = opti(82)+1, nbod7
            if (stat(j).eq.0) then
              k = k + 1
              x7(1,k) = x0(1,j)-x0(1,2)
              x7(2,k) = x0(2,j)-x0(2,2)
              x7(3,k) = x0(3,j)-x0(3,2)
              v7(1,k) = v0(1,j)-v0(1,2)
              v7(2,k) = v0(2,j)-v0(2,2)
              v7(3,k) = v0(3,j)-v0(3,2)
              m7(k)   = m(j)
              s7(1,k) = s(1,j)
              s7(2,k) = s(2,j)
              s7(3,k) = s(3,j)
              rho7(k) = rho(j)
              rcrit7(k) = rcrit(j)
              rceh7(k) = rceh(j)
              stat7(k) = stat(j)
              id7(k) = id(j)
              ngf7(1,k) = ngf(1,j)
              ngf7(2,k) = ngf(2,j)
              ngf7(3,k) = ngf(3,j)
              ngf7(4,k) = ngf(4,j)
              idtag7(k) = idtag(j)
            end if
          end do
          nbod = nbod7 - k
          opti(82) = nbod
