     %      ngf,ngflag,opt,optr,opti,K2,AU,MSUN)
          call mco_rot (time-hdid-optr(63),1,nbod7-opti(82),optr(6),
     %      x7,xps)
          call mco_rot (time-hdid-optr(63),1,nbod7-opti(82),optr(6),
     %      v7,vps)
          do j = 1, nbod
            xk(1,j) = x0(1,j)
            xk(2,j) = x0(2,j)
            xk(3,j) = x0(3,j)
            vk(1,j) = v0(1,j)
            vk(2,j) = v0(2,j)
            vk(3,j) = v0(3,j)
            chk(1,j) = x0(1,j)
            chk(2,j) = x0(2,j)
            chk(3,j) = x0(3,j)
          end do
