            xk(1,k) = xps(1,j)
            xk(2,k) = xps(2,j)
            xk(3,k) = xps(3,j)
            vk(1,k) = vps(1,j)
            vk(2,k) = vps(2,j)
            vk(3,k) = vps(3,j)
