c ##A5,18##
c        if (stopflag.eq.1) return
        if (stopflag.eq.1) then
c
c ##A39,89##
          if (opti(80).eq.1.and.opti(81).eq.0) then
            nbod0 = nbod
            nbod  = nbod7
          end if
