              k = j + nbod
              xh(1,k) = xps(1,j)+xh(1,2)
              xh(2,k) = xps(2,j)+xh(2,2)
              xh(3,k) = xps(3,j)+xh(3,2)
              vh(1,k) = vps(1,j)+vh(1,2)
              vh(2,k) = vps(2,j)+vh(2,2)
              vh(3,k) = vps(3,j)+vh(3,2)
              m(k)   = m7(j)
              s(1,k) = s7(1,j)
              s(2,k) = s7(2,j)
              s(3,k) = s7(3,j)
              rho(k) = rho7(j)
              rceh(k) = rceh7(j)
              rcrit(k) = rcrit7(j)
              stat(k) = stat7(j)
              id(k) = id7(j)
              ngf(1,k) = ngf7(1,j)
              ngf(2,k) = ngf7(2,j)
              ngf(3,k) = ngf7(3,j)
              ngf(4,k) = ngf7(4,j)
              idtag(k) = idtag7(j)
              x(1,k) = xh(1,k)
              x(2,k) = xh(2,k)
              x(3,k) = xh(3,k)
              v(1,k) = vh(1,k)
              v(2,k) = vh(2,k)
              v(3,k) = vh(3,k)
            end do
            opti(82) = nbod0
            nbod = k
            nbod7 = nbod
            opti(81) = 0
            optr(63) = time
          end if
c ##A39,89##
c
          tstop = tclo(1)
          return
        end if
      end if
