      call mce_cent (time,hdid,rcen,jcen,2,nbod,nbig,m,x0,v0,xh,vh,nhit,
     %  jhit,thit,dhit,algor,ngf,ngflag,optr,nbclo,bclo,rmax,opt,
     %  nstored,cce,flagce(2),tcol,opti,nov,nop,xv,yv,zv,noe,kkk,K2,AU,
     %  MSUN,coord,bcoord,xv0,yv0,zv0,tstart,lapla1,lapla2)
c ##A43,68##
c ##A38,111##
c ##A25,7##
c ##E14,34##
c ##A5,26##
c ##A1,20##
c ##A19,58##
c
c Resolve the collisions
      if (nhit.gt.0) then
c ##A24,9##
c ##AN28,125##
        call mce_criteria (tcol,tstart,nbod,algor,opt(3),m,id,
     %  opti,optr,mem,lmem,nbclo,nstored,K2)
c ##AN28,125##
c ##A24,9##
c ##A5,20##
c ##A23,7##
c ##AN28,48##
c ##A32,27##
c ##A35,42##
        call mce_header (tstart,algor,jcen,rcen,rmax,nbod,m,s,rho,
     %  id,opt,outfile(2),nbclo,bclo,nstored,nbig,K2,AU,MSUN,optr,
     %  idtag)
c ##A35,42##
c ##A32,27##
c ##AN28,48##
c ##A23,7##
        call mio_ceflush (opt(4),outfile(2),nstored,cce)
        flagce(1) = 1
        flagce(2) = 0
c ##A5,20##
        do k = 1, nhit
          i = 1
          j = jhit(k)
c ##A11,11##
c ##A22,17##
c ##A19,209##
          call mce_coll (thit(k),tstart,en(3),jcen,i,j,nbod,nbig,m,xh,
     %      vh,s,rphys,stat,id,opt,mem,lmem,outfile(3),opti,0,nov,nop,
     %      noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,algor,K2,rho)
c ##A19,209##
c ##A22,17##
c ##A11,11##
        end do
c
c Remove lost objects, reset flags and recompute Hill and physical radii
c ##A4,9##
c ##A7,13##
c ##A8,10##
c ##E14,35##
c ##AN28,42##
c ##A35,14##
c ##A43,60##
        call mxx_elim (nbod,nbig,m,xh,vh,s,rho,rceh,rcrit,ngf,stat,
     %    id,mem,lmem,outfile(3),itmp,opti,stopflag,algor,optr,time,
     %    tstop,tstart,opt(3),tcol,K2,idtag,lapla1,lapla2)
c ##A43,60##
c ##A35,14##
c ##AN28,42##
c ##E14,35##
c ##A8,10##
c        if (stopflag.eq.1) return
c ##A7,13##
c ##A4,9##
        dtflag = 1
        if (opflag.ge.0) opflag = 1
c ##A17,18##
c ##AN28,33##
        call mce_init (tstart,algor,h0,jcen,rcen,rmax,cefac,nbod,nbig,
     %    m,xh,vh,s,rho,rceh,rphys,rce,rcrit,id,opt,outfile(2),0,opti,
     %    K2,AU,MSUN,ngflag)
c ##AN28,33##
c ##A17,18##
c ##A19,60##
c ##A38,86##
        call coord(time-tstart,jcen,nbod,2,optr(6),m,xh,vh,x,v,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,86##
c ##A19,60##
c
c ##A43,72##
        if (algor.ge.13) then
        do j = 2, nbod
          lapla1(j) = lapla2(j)
        end do
        end if
c ##A43,72##
      end if
      endif							!NEW!
c
c------------------------------------------------------------------------------
c
c  DATA  DUMP  AND  PROGRESS  REPORT
c
c Do the data dump
      if (abs(time-tdump).ge.abs(dtdump).and.opflag.ge.-1) then
c ##A39,98##
        if (opti(80).eq.1.and.opti(81).eq.0) then
          nbod0 = nbod
          nbod  = nbod7
        end if
c ##A39,98##
c ##A19,61##
c ##A38,87##
        call bcoord(time-tstart,jcen,nbod,2,optr(6),m,x,v,xh,vh,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,87##
c ##A19,61##
c
c ##A39,82##
        if (opti(81).eq.1) then
          nbod0 = nbod
          call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),x7,xps)
          call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),v7,vps)
          do j = 1, nbod7-opti(82)
            k = j + nbod
            xh(1,k) = xps(1,j)+xh(1,2)
            xh(2,k) = xps(2,j)+xh(2,2)
            xh(3,k) = xps(3,j)+xh(3,2)
            vh(1,k) = vps(1,j)+vh(1,2)
            vh(2,k) = vps(2,j)+vh(2,2)
            vh(3,k) = vps(3,j)+vh(3,2)
            m(k)   = m7(j)
            s(1,k) = s7(1,j)
            s(2,k) = s7(2,j)
            s(3,k) = s7(3,j)
            rho(k) = rho7(j)
            rceh(k) = rceh7(j)
            rcrit(k) = rcrit7(j)
            stat(k) = stat7(j)
            id(k) = id7(j)
            ngf(1,k) = ngf7(1,j)
            ngf(2,k) = ngf7(2,j)
            ngf(3,k) = ngf7(3,j)
            ngf(4,k) = ngf7(4,j)
            idtag(k) = idtag7(j)
            x(1,k) = xh(1,k)
            x(2,k) = xh(2,k)
            x(3,k) = xh(3,k)
            v(1,k) = vh(1,k)
            v(2,k) = vh(2,k)
            v(3,k) = vh(3,k)
          end do
          opti(82) = nbod0
          nbod = k
          nbod7 = nbod
          opti(81) = 0
          optr(63) = time
        end if
c ##A39,82##
c
        do j = 2, nbod
          epoch(j) = time
        end do
c ##A2,11##
c ##A5,37##
c ##A24,19##
c ##AN28,76##
c ##A35,52##
        call mio_ce (time,tstart,rcen,rmax,nbod,nbig,m,stat,id,
     %    0,iclo,jclo,opt,stopflag,tclo,dclo,ixvclo,jxvclo,mem,lmem,
     %    outfile,nstored,0,opti(1),aux,cce,algor,jcen,s,rho,nbclo,
     %    bclo,flagce,opti,optr,K2,AU,MSUN,idtag)
c ##A35,52##
c ##AN28,76##
c ##A24,19##
c ##A5,37##
c ##A2,11##
c ##A1,28##
c ##A2,28##
c ##A3,26##
c ##E9,42##
c ##A19,124##
c ##A20,26##
c ##AN28,11##
c ##A35,24##
c ##A38,139##
c ##A19,218##
        call mio_dump (time,tstart,tstop,dtout,algor,h,tol,jcen,rcen,
     %    rmax,en,am,cefac,ndump,nfun,nbod,nbig,m,xh,vh,s,rho,rceh,stat,
     %    id,ngf,epoch,opt,opflag,dumpfile,mem,lmem,optr,opti,rmin,
     %    dtdump,nov,nop,noc,dens,binfile,outfile,treal,tuser,tsys,
     %    K2,AU,MSUN,idtag,ngflag,xv,yv,zv,noe,kkk,mc,xc,yc,zc)
c ##A19,218##
c ##A38,139##
c ##A35,24##
c ##AN28,11##
c ##A20,26##
c ##A19,124##
c ##E9,42##
c ##A3,26##
c ##A2,28##
c ##A1,28##
c ##A39,83##
        if (opti(80).eq.1.and.(opti(81).ge.0
     %    .and.opti(81).lt.3)) nbod = nbod0
c ##A39,83##
        tdump = time
      end if
c
c Write a progress report to the log file
c ##A30,9##
c      if (abs(time-tlog).ge.abs(dtdump).and.opflag.ge.0) then
c ##A19,62##
c        call bcoord(time-tstart,jcen,nbod,2,optr(6),m,x,v,xh,vh,ngf,ngflag,
c     %    opt)
c ##A19,62##
c        call mxx_en (jcen,nbod,nbig,m,xh,vh,s,en(2),am(2),nov,nop,noc,
c     %    xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,K2,rho)
c ##A9,1##
c        call mio_log (time,tstart,en,am,opt,mem,lmem,outfile(4))
c ##A9,1##
c        tlog = time
c      end if
c ##A30,9##
c
c------------------------------------------------------------------------------
c
c  CHECK  FOR  EJECTIONS  AND  DO  OTHER  PERIODIC  EFFECTS
c
      if (abs(time-tfun).ge.abs(dtfun).and.opflag.ge.-1) then
c ##A19,63##
c ##A38,88##
        call bcoord(time-tstart,jcen,nbod,2,optr(6),m,x,v,xh,vh,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,88##
c ##A19,63##
c ##ANO29,22##
        do j = 2, nbod
c ##A38,115##
          call jc (nbod,j,algor,opti,optr,mem,lmem,id,xh,vh,m,tstart,
     %      time,jcen,ngf,ngflag,opt,maxjc,nov,nop,noc,xv,yv,zv,noe,kkk,
     %      dens,mc,xc,yc,zc,K2,AU,MSUN)
c ##A38,115##
        end do
c ##ANO29,22##
c
c Recompute close encounter limits, to allow for changes in Hill radii
        call mce_hill (nbod,m,xh,vh,rce,a)
        do j = 2, nbod
c ##A17,25##
          if (opti(20).eq.0) then
            rce(j) = rce(j) * rceh(j)
          else if (opti(20).eq.1) then
            rce(j) = rceh(j)
          end if
c ##A17,25##
        end do
c
c Check for ejections
c ##A3,12##
c ##A4,17##
c ##A5,27##
c ##A7,3##
        itmp = 2
        if (opti(6).eq.1) itmp = 3
c ##AAR1,23##
c ##E11,2##
        do j = 1, nbod
          mej(j) = m(j)
        end do
c ##E11,2##
c ##E12,5##
c ##A34,7##
c ##A40,6##
c ##A19,224##
        call mxx_ejec (time,tstart,rmax,en,am,jcen,itmp,nbod,nbig,m,xh,
     %    vh,s,stat,id,opt,ejflag,outfile(3),mem,lmem,rmin,opti,nbclo,
     %    bclo,rcen,nstored,cce,flagce(2),algor,stopflag,optr,rce,nov,
     %    nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,K2,rho)
c ##A19,224##
c ##A40,6##
c ##A34,7##
c ##E12,5##
c ##AAR1,23##
c ##A7,3##
c ##A5,27##
c ##A4,17##
c ##A3,12##
c
c ##A44,4##
        if (opti(90).eq.1) then
        call mxx_rotbrup (time,tstart,en,am,jcen,nbod,nbig,m,xh,vh,s,
     %    rotflag,outfile(3),mem,lmem,opti,nbclo,bclo,nstored,cce,
     %    flagce(2),algor,stopflag,optr,nov,nop,noc,xv,yv,zv,noe,kkk,
     %    dens,mc,xc,yc,zc,K2,rphys,opt,stat,id,rho)
        end if
c
c Remove lost objects, reset flags and recompute Hill and physical radii
c        if (ejflag.ne.0) then
        if (ejflag.ne.0.or.rotflag.ne.0) then
c ##A44,4##
c ##A24,10##
c ##AN28,126##
          call mce_criteria (time,tstart,nbod,algor,opt(3),m,id,
     %    opti,optr,mem,lmem,nbclo,nstored,K2)
c ##AN28,126##
c ##A24,10##
c ##A5,32##
c ##E11,3##
c ##A23,8##
c ##AN28,49##
c ##A32,28##
c ##A35,43##
          call mce_header (tstart,algor,jcen,rcen,rmax,nbod,mej,s,rho,
     %    id,opt,outfile(2),nbclo,bclo,nstored,nbig,K2,AU,MSUN,optr,
     %    idtag)
c ##A35,43##
c ##A32,28##
c ##AN28,49##
c ##A23,8##
c ##E11,3##
c ##E2,2##
          call mio_ceflush (opt(4),outfile(2),nstored,cce)
c ##E2,2##
          flagce(1) = 1
          flagce(2) = 0
c ##A5,32##
c ##A4,10##
c ##A7,14##
c ##A8,11##
c ##E14,36##
          tcol = time
c ##AN28,43##
c ##A35,15##
c ##A43,61##
          call mxx_elim (nbod,nbig,m,xh,vh,s,rho,rceh,rcrit,ngf,stat,
     %      id,mem,lmem,outfile(3),itmp,opti,stopflag,algor,optr,time,
     %      tstop,tstart,opt(3),tcol,K2,idtag,lapla1,lapla2)
c ##A43,61##
c ##A35,15##
c ##AN28,43##
c ##E14,36##
c ##A8,11##
c          if (stopflag.eq.1) return
c ##E12,6##
c ajm 2013-03-19 and end integration if opt(1) is set
c          if (stopflag.eq.1) return
          if (stopflag.eq.1) then
c
c ##A39,90##
            if (opti(80).eq.1.and.opti(81).eq.0) then
              nbod0 = nbod
              nbod  = nbod7
            end if
            if (opti(81).eq.1) then
              nbod0 = nbod
              call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),x7,
     %          xps)
              call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),v7,
     %          vps)
              do j = 1, nbod7-opti(82)
                k = j + nbod
                xh(1,k) = xps(1,j)+xh(1,2)
                xh(2,k) = xps(2,j)+xh(2,2)
                xh(3,k) = xps(3,j)+xh(3,2)
                vh(1,k) = vps(1,j)+vh(1,2)
                vh(2,k) = vps(2,j)+vh(2,2)
                vh(3,k) = vps(3,j)+vh(3,2)
                m(k)   = m7(j)
                s(1,k) = s7(1,j)
                s(2,k) = s7(2,j)
                s(3,k) = s7(3,j)
                rho(k) = rho7(j)
                rceh(k) = rceh7(j)
                rcrit(k) = rcrit7(j)
                stat(k) = stat7(j)
                id(k) = id7(j)
                ngf(1,k) = ngf7(1,j)
                ngf(2,k) = ngf7(2,j)
                ngf(3,k) = ngf7(3,j)
                ngf(4,k) = ngf7(4,j)
                idtag(k) = idtag7(j)
                x(1,k) = xh(1,k)
                x(2,k) = xh(2,k)
                x(3,k) = xh(3,k)
                v(1,k) = vh(1,k)
                v(2,k) = vh(2,k)
                v(3,k) = vh(3,k)
              end do
              opti(82) = nbod0
              nbod = k
              nbod7 = nbod
              opti(81) = 0
              optr(63) = time
            end if
c ##A39,90##
c
            tstop = tcol
            return
          end if
c ajm end edit
c ##E12,6##
c ##A7,14##
c ##A4,10##
          dtflag = 1
c ##E2,1## antes da subrotina mce_init ser chamada para escrever os nomes dos
c corpos (suas massas, etc) no arquivo ce.out, os dados do vetor c devem ser
c descarregados (subrotina mio_ce), caso contrário os índices dos corpos que
c tiveram encontros próximos serão confundidos quando ocorrerem ejeções.
c ##E2,1##
          if (opflag.ge.0) opflag = 1
c ##A17,20##
c ##AN28,34##
          call mce_init (tstart,algor,h0,jcen,rcen,rmax,cefac,nbod,nbig,
     %      m,xh,vh,s,rho,rceh,rphys,rce,rcrit,id,opt,outfile(2),0,opti,
     %      K2,AU,MSUN,ngflag)
c ##AN28,34##
c ##A17,20##
c ##A19,64##
c ##A38,89##
          call coord(time-tstart,jcen,nbod,2,optr(6),m,xh,vh,x,v,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,89##
c ##A19,64##
        end if
        tfun = time
      end if
c
c ##ANO29,32##
c      if ((abs(time-tly).ge.abs(optr(28)).and.opti(42).eq.1)
c     %  .and.opflag.ge.-1) then
c        call ren (nbod,id,x,v,optr)
c        tly = time
c      end if
c ##ANO29,32##
c
c Go on to the next time step
      goto 100
c
c------------------------------------------------------------------------------
c
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MAL_HCON.FOR    (ErikSoft   28 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Does an integration using an integrator with a constant stepsize H.
c Input and output to this routine use coordinates XH, and velocities VH,
c with respect to the central body, but the integration algorithm uses
c its own internal coordinates X, and velocities V.
c
c The programme uses the transformation routines COORD and BCOORD to change
c to and from the internal coordinates, respectively.
c
c------------------------------------------------------------------------------
c
c ##A1,12##
c ##A2,19##
c ##A3,18##
c ##E9,43##
c ##A19,104##
c ##A20,16##
c ##AN28,18##
c ##ANO29,18##
c ##A35,11##
c ##A39,114##
c ##A43,47##
      subroutine mal_hcon (time,tstart,tstop,dtout,algor,h0,tol,jcen,
     %  rcen,rmax,en,am,cefac,ndump,nfun,nbod,nbig,m,xh,vh,s,rho,rceh,
     %  stat,id,ngf,opt,opflag,ngflag,outfile,dumpfile,mem,lmem,onestep,
     %  coord,bcoord,optr,opti,rmin,dtdump,nov,nop,noc,xv,yv,zv,noe,kkk,
     %  dens,mc,xc,yc,zc,apot,binfile,treal,tuser,tsys,K2,AU,MSUN,maxjc,
     %  idtag,chk)
c ##A43,47##
c ##A39,114##
c ##A35,11##
c ##ANO29,18##
c ##AN28,18##
c ##A20,16##
c ##A19,104##
c ##E9,43##
c ##A3,18##
c ##A2,19##
c ##A1,12##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer algor,nbod,nbig,stat(nbod),opt(9),opflag,ngflag
      integer lmem(NMESS),ndump,nfun
      real*8 time,tstart,tstop,dtout,h0,tol,jcen(3),rcen,rmax
      real*8 en(3),am(3),cefac,m(nbod),xh(3,nbod),vh(3,nbod)
      real*8 s(3,nbod),rho(nbod),rceh(nbod),ngf(4,nbod)
      character*8 id(nbod)
      character*80 outfile(4),dumpfile(5),mem(NMESS)
c ##A1,13##
      real*8 optr(76)
c ##A1,13##
c ##A2,18##
      integer opti(90)
c ##A2,18##
c ##A3,17##
      real*8 rmin
c ##A3,17##
c ##A19,105##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      character*80 binfile(101)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
c ##A19,105##
c ##A20,17##
      real*8 treal,tuser,tsys
c ##A20,17##
c ##AN28,19##
      real*8 K2,AU,MSUN
c ##AN28,19##
c ##ANO29,29##
      real*8 maxjc
c ##ANO29,29##
c ##A35,12##
      integer idtag(NMAX)
c ##A35,12##
c
c Local
      integer i,j,k,n,itmp,nclo,nhit,jhit(CMAX),iclo(CMAX),jclo(CMAX)
      integer dtflag,ejflag,stopflag,colflag,nstored
      real*8 x(3,NMAX),v(3,NMAX),xh0(3,NMAX),vh0(3,NMAX)
      real*8 rce(NMAX),rphys(NMAX),rcrit(NMAX),epoch(NMAX)
      real*8 hby2,tout,tmp0,tdump,tfun,tlog,dtdump,dtfun
      real*8 dclo(CMAX),tclo(CMAX),dhit(CMAX),thit(CMAX)
      real*8 ixvclo(6,CMAX),jxvclo(6,CMAX),a(NMAX)
      real*8 erre					  !NEW!
      integer ifl       			          !NEW!
c ##A6,22##
      integer nclo2,iclo2(CMAX),jclo2(CMAX)
      real*8 dclo2(CMAX),tclo2(CMAX)
      real*8 ixvclo2(6,CMAX),jxvclo2(6,CMAX)
      integer nbclo,bclo(nbod)
      character*1 aux(CMAX)
      character*107 cce(FMAX)
      integer flagce(2)
c ##A6,22##
c ##E9,44##
      integer clflag
c ##E9,44##
c ##AAR1,26##
      real*8 xu(3,NMAX),vu(3,NMAX)
c ##AAR1,26##
c ##E11,4##
      real*8 mej(NMAX)
c ##E11,4##
c ##A22,32##
      integer nelim
c ##A22,32##
c ##E14,27##
      real*8 tcol
c ##E14,27##
c ##ANO29,11##
      real*8 psflag(2,NMAX)
      real*8 xps(3,NMAX),vps(3,NMAX)
      integer nps,ps(NMAX)
      integer nce,ice(NMAX),jce(NMAX)
      real*8 tly
c ##ANO29,11##
c ##A32,10##
      real*8 msum,mlost0,mlost,omg0,per
      integer stopflag0(4)
c ##A32,10##
      external onestep,coord,bcoord
c ##ANO29,14##
      external mfo_hkce
c ##ANO29,14##
c ##A19,186##
      real*8 xv0(nov),yv0(nov),zv0(nov)
      real*8 xc0(noc),yc0(noc),zc0(noc)
