c ##A43,51##
          call pss (time,h0,tol,jcen,nbod,nbig,m,xps,vps,s,rphys,
     %      rcrit,ngf,stat,dtflag,ngflag,opt,0,ice,jce,mfo_hkce,
     %      nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,
     %      algor,apot,K2,AU,MSUN,ps,id,rce,0,nbclo,bclo,nstored,
     %      cce,flagce(2),mem,lmem,idtag,chk,lapla2,tstart)
c ##A43,51##
c ##A39,77##
c ##A35,85##
        end if
      end if
c ##ANO29,13##
c
      time = time + h0
c
c ##A19,185##
      if (algor.ge.13.and.opti(72).eq.1) then
        do j = 1, nov
          xv0(j) = xv(j)
          yv0(j) = yv(j)
          zv0(j) = zv(j)
        end do
        do j = 1, noc
          xc0(j) = xc(j)
          yc0(j) = yc(j)
          zc0(j) = zc(j)
        end do
        call mco_astrot (nov,h0,optr(6),xv0,yv0,zv0,xv,yv,zv)
        call mco_astrot (noc,h0,optr(6),xc0,yc0,zc0,xc,yc,zc)
      end if
c ##A19,185##
c
c ##A39,57##
      if (opti(80).eq.1) then
 9999   continue
        if (opti(81).eq.0) then
          k = 0
          do j = opti(82)+1, nbod7
            if (stat(j).eq.0) then
              k = k + 1
              x7(1,k) = xh0(1,j)-xh0(1,2)
              x7(2,k) = xh0(2,j)-xh0(2,2)
              x7(3,k) = xh0(3,j)-xh0(3,2)
              v7(1,k) = vh0(1,j)-vh0(1,2)
              v7(2,k) = vh0(2,j)-vh0(2,2)
              v7(3,k) = vh0(3,j)-vh0(3,2)
              m7(k)   = m(j)
              s7(1,k) = s(1,j)
              s7(2,k) = s(2,j)
              s7(3,k) = s(3,j)
              rho7(k) = rho(j)
              rcrit7(k) = rcrit(j)
              rceh7(k) = rceh(j)
              stat7(k) = stat(j)
              id7(k) = id(j)
              ngf7(1,k) = ngf(1,j)
              ngf7(2,k) = ngf(2,j)
              ngf7(3,k) = ngf(3,j)
              ngf7(4,k) = ngf(4,j)
              idtag7(k) = idtag(j)
            end if
          end do
          nbod = nbod7 - k
          opti(82) = nbod
          opti(81) = 1
        end if
        if (opti(81).ge.0) then
          call bcoord (time-tstart,jcen,nbod,nbig,h0,m,x,v,xu,vu,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
          call mce_criteria3 (h0,2,nbod,nbig,xh0,vh0,xu,vu,rce,stat,
     %      opti(81),icek)
        end if
        if (opti(81).eq.0) then
          dtout = optr(66)
          h0    = optr(68)
          tout  = time
          opti(82) = nbig
          nbod7 = nbod
          dtfun  = abs(h0) * nfun
          hby2 = 0.500001d0 * abs(h0)
          goto 9999
        end if
        if (opti(81).eq.2) then
          do j = 1, 2
            if (icek(j).ne.2) ice0 = icek(j)
          end do
          dtout = optr(65)
          h0    = optr(67)
          tout  = time
          dtfun  = abs(h0) * nfun
          hby2 = 0.500001d0 * abs(h0)
          call bcoord (time-tstart,jcen,nbod,nbig,h0,m,xu,vu,xh,vh,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
          call mco_rot (time-h0-optr(63),1,nbod7-opti(82),optr(6),x7,xu)
          call mco_rot (time-h0-optr(63),1,nbod7-opti(82),optr(6),v7,vu)
          do j = 1, nbod
            xk(1,j) = xh0(1,j)
            xk(2,j) = xh0(2,j)
            xk(3,j) = xh0(3,j)
            vk(1,j) = vh0(1,j)
            vk(2,j) = vh0(2,j)
            vk(3,j) = vh0(3,j)
            chk(1,j) = xh0(1,j)
            chk(2,j) = xh0(2,j)
            chk(3,j) = xh0(3,j)
          end do
          do j = 1, nbod7-opti(82)
            k = j + nbod
            xk(1,k) = xu(1,j)
            xk(2,k) = xu(2,j)
            xk(3,k) = xu(3,j)
            vk(1,k) = vu(1,j)
            vk(2,k) = vu(2,j)
            vk(3,k) = vu(3,j)
          end do
          call chk_rot (k,ice0,2,nbod+1,m,xk,vk,xu,vu,opti,optr,norm)
          nbod7 = k
          do j = 1, nbod7-nbod
            k = j + nbod
            chk(1,k) = xu(1,j)
            chk(2,k) = xu(2,j)
            chk(3,k) = xu(3,j)
            xh(1,k) = (xu(1,j)-xh0(1,2))+xh(1,2)
            xh(2,k) = (xu(2,j)-xh0(2,2))+xh(2,2)
            xh(3,k) = (xu(3,j)-xh0(3,2))+xh(3,2)
            vh(1,k) = (vu(1,j)-vh0(1,2))+vh(1,2)
            vh(2,k) = (vu(2,j)-vh0(2,2))+vh(2,2)
            vh(3,k) = (vu(3,j)-vh0(3,2))+vh(3,2)
            m(k)   = m7(j)
            s(1,k) = s7(1,j)
            s(2,k) = s7(2,j)
            s(3,k) = s7(3,j)
            rho(k) = rho7(j)
            rceh(k) = rceh7(j)
            rcrit(k) = rcrit7(j)
            stat(k) = stat7(j)
            id(k) = id7(j)
            ngf(1,k) = ngf7(1,j)
            ngf(2,k) = ngf7(2,j)
            ngf(3,k) = ngf7(3,j)
            ngf(4,k) = ngf7(4,j)
            idtag(k) = idtag7(j)
          end do
          opti(82) = nbod
          nbod = k
          nbod7 = nbod
          opti(81) = 3
          optr(64) = time-h0
          call chk_dump (nbod,chk,opti,optr,dumpfile)
          call coord (time-tstart,jcen,nbod,nbig,h0,m,xh,vh,x,v,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
c          do j = opti(82)+1, nbod
c            chk(1,j) = x(1,j)
c            chk(2,j) = x(2,j)
c            chk(3,j) = x(3,j)
c          end do
c ##A19,220##
          call mio_dump (time,tstart,tstop,dtout,algor,h0,tol,jcen,rcen,
     %      rmax,en,am,cefac,ndump,nfun,nbod,nbig,m,xh,vh,s,rho,rceh,
     %      stat,id,ngf,epoch,opt,opflag,dumpfile,mem,lmem,optr,opti,
     %      rmin,dtdump,nov,nop,noc,dens,binfile,outfile,treal,tuser,
     %      tsys,K2,AU,MSUN,idtag,ngflag,xv,yv,zv,noe,kkk,mc,xc,yc,zc)
c ##A19,220##
          tdump = time
        end if
        if (opti(81).eq.3) then
          call bcoord (time-tstart,jcen,nbod,nbig,h0,m,x,v,xu,vu,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
          call mfo_chk (time,nbod,nbig+1,2,m,xu,vu,vk,opt,optr,
     %      opti,chk,stat,norm)
          call coord (time-tstart,jcen,nbod,nbig,h0,m,xu,vu,x,v,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
        end if
      end if
c ##A39,57##
c
c------------------------------------------------------------------------------
c
c  CLOSE  ENCOUNTERS
c
c If encounter minima occurred, output details and decide whether to stop
c ##A6,12##
c ##A6,40##
c      if (nclo2.gt.0.and.opflag.ge.-1) then
c ##A22,54##
c      if (nclo.gt.0.and.opflag.ge.-1) then
c ##ANO29,41##
c      if ((nclo.gt.0.or.nelim.gt.0).and.opflag.ge.-1) then
      if ((nclo.gt.0.or.nelim.gt.0.or.nstored.ge.opti(1))
     %  .and.opflag.ge.-1) then
c ##ANO29,41##
c ##A22,54##
c ##A6,40##
c ##A6,12##
        itmp = 1
c ##A6,13##
c        if (colflag.ne.0) itmp = 0
        if (opt(1).eq.1) itmp = 0
c ##A2,16##
c ##A6,41##
c ##AN28,78##
c ##A35,54##
c        call mio_ce (time,tstart,rcen,rmax,nbod,nbig,m,stat,id,nclo2,
c     %    iclo2,jclo2,opt,stopflag,tclo2,dclo2,ixvclo2,jxvclo2,mem,lmem,
c     %    outfile,nstored,itmp,opti(1),aux,cce,algor,jcen,s,rho,nbclo,
c     %    bclo,flagce,opti,optr,K2,AU,MSUN,idtag)
c ##A24,21##
        call mio_ce (time,tstart,rcen,rmax,nbod,nbig,m,stat,id,nclo,
     %    iclo,jclo,opt,stopflag,tclo,dclo,ixvclo,jxvclo,mem,lmem,
     %    outfile,nstored,itmp,opti(1),aux,cce,algor,jcen,s,rho,nbclo,
     %    bclo,flagce,opti,optr,K2,AU,MSUN,idtag)
c ##A24,21##
c ##A35,54##
c ##AN28,78##
c ##A6,41##
c ##A2,16##
c ##A6,13##
c        if (stopflag.eq.1) return
        if (stopflag.eq.1) then
c ##A39,102##
          if (opti(80).eq.1.and.opti(81).eq.0) then
            nbod0 = nbod
            nbod  = nbod7
          end if
c ##A39,102##
          call bcoord (time-tstart,jcen,nbod,nbig,h0,m,x,v,xh,vh,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
c
c ##A39,91##
          if (opti(81).eq.1) then
            nbod0 = nbod
            call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),x7,xu)
            call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),v7,vu)
            do j = 1, nbod7-opti(82)
              k = j + nbod
              xh(1,k) = xu(1,j)+xh(1,2)
              xh(2,k) = xu(2,j)+xh(2,2)
              xh(3,k) = xu(3,j)+xh(3,2)
              vh(1,k) = vu(1,j)+vh(1,2)
              vh(2,k) = vu(2,j)+vh(2,2)
              vh(3,k) = vu(3,j)+vh(3,2)
              m(k)   = m7(j)
              s(1,k) = s7(1,j)
              s(2,k) = s7(2,j)
              s(3,k) = s7(3,j)
              rho(k) = rho7(j)
              rceh(k) = rceh7(j)
              rcrit(k) = rcrit7(j)
              stat(k) = stat7(j)
              id(k) = id7(j)
              ngf(1,k) = ngf7(1,j)
              ngf(2,k) = ngf7(2,j)
              ngf(3,k) = ngf7(3,j)
              ngf(4,k) = ngf7(4,j)
              idtag(k) = idtag7(j)
              x(1,k) = xh(1,k)
              x(2,k) = xh(2,k)
              x(3,k) = xh(3,k)
              v(1,k) = vh(1,k)
              v(2,k) = vh(2,k)
              v(3,k) = vh(3,k)
            end do
            opti(82) = nbod0
            nbod = k
            nbod7 = nbod
            opti(81) = 0
            optr(63) = time
          end if
c ##A39,91##
c
          tstop = tclo(1)
          return
        end if
      end if
c
c------------------------------------------------------------------------------
c
c  COLLISIONS
c
c If collisions occurred, output details and remove lost objects
c ##A22,55##
      if (colflag.ne.0.or.nelim.gt.0) then
c ##A22,55##
c ##A23,13##
        if (nclo.gt.0) nbclo = 0
c ##A23,13##
c
c Reindex the surviving objects
c ##A38,94##
        call bcoord (time-tstart,jcen,nbod,nbig,h0,m,x,v,xh,vh,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,94##
c ##A19,163##
c        if (algor.eq.22) then
c          call mco_iden (time,jcen,nbod,nbig,h0,m,xh,vh,xu,vu,ngf,
c     %      ngflag,opt)
c          call mco_ast2h (time,jcen,nbod,2,optr(6),m,xu,vu,xh,vh,
c     %      ngf,ngflag,opt)
c        end if
c ##A19,163##
c ##A4,11##
c ##A7,15##
c ##A8,12##
c ##E14,37##
c ##AN28,44##
c ##A35,16##
c ##A43,62##
        call mxx_elim (nbod,nbig,m,xh,vh,s,rho,rceh,rcrit,ngf,stat,
     %    id,mem,lmem,outfile(3),itmp,opti,stopflag,algor,optr,time,
     %    tstop,tstart,opt(3),tcol,K2,idtag,lapla1,lapla2)
c ##A43,62##
c ##A35,16##
c ##AN28,44##
c ##E14,37##
c ##A8,12##
c        if (stopflag.eq.1) return
c ##A7,15##
c ##A4,11##
c
c Reset flags, and calculate new Hill radii and physical radii
        dtflag = 1
        if (opflag.ge.0) opflag = 1
c ##A17,22##
c ##AN28,36##
        call mce_init (tstart,algor,h0,jcen,rcen,rmax,cefac,nbod,nbig,
     %    m,xh,vh,s,rho,rceh,rphys,rce,rcrit,id,opt,outfile(2),1,opti,
     %    K2,AU,MSUN,ngflag)
c ##AN28,36##
c ##A17,22##
c ##A19,164##
c        if (algor.eq.22) then
c          call mco_iden (time,jcen,nbod,nbig,h0,m,xh,vh,xu,vu,ngf,
c     %      ngflag,opt)
c          call mco_h2ast (time,jcen,nbod,2,optr(6),m,xu,vu,xh,vh,
c     %      ngf,ngflag,opt)
c        end if
c ##A19,164##
c ##A38,95##
        call coord (time-tstart,jcen,nbod,nbig,h0,m,xh,vh,x,v,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,95##
      end if
c
c------------------------------------------------------------------------------
c
c check if some object is too close the central body. (suggested value 2*rcen)
c
      ifl=0                                                     !NEW!
c ##AAR1,25##
      itmp = 2
      if (algor.eq.11.or.algor.eq.5) then
        itmp = 3
c ##A18,10##
        call mco_h2ub (algor,time,jcen,nbod,nbig,h0,m,xh0,vh0,xu,vu,ngf,
     %    ngflag,opt)
c ##A18,10##
      else
c ##A38,20##
        call mco_iden (time,jcen,nbod,nbig,h0,m,xh0,vh0,xu,vu,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,20##
      end if
      do i=itmp,nbod                                               !NEW!
      erre=dsqrt(xu(1,i)**2+xu(2,i)**2+xu(3,i)**2)              !NEW!
c ##AAR1,25##
c ##A1,16##
      if(erre.lt.optr(1))ifl=1                                 !NEW!
c ##A1,16##
      enddo                                                     !NEW!
c
c------------------------------------------------------------------------------
c
c  COLLISIONS  WITH  CENTRAL  BODY
c
c ##A37,5##
      if(ifl.eq.1.and.opti(76).eq.1) then					          !NEW!
c ##A37,5##
c Check for collisions with the central body
      if (algor.eq.1) then
c ##A38,21##
        call mco_iden(time,jcen,nbod,nbig,h0,m,x,v,xh,vh,ngf,ngflag,opt,
     %    optr,opti,K2,AU,MSUN)
      else
        call bcoord (time-tstart,jcen,nbod,nbig,h0,m,x,v,xh,vh,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,21##
c ##A19,165##
c        if (algor.eq.22) then
c          call mco_iden (time,jcen,nbod,nbig,h0,m,xh,vh,xu,vu,ngf,
c     %      ngflag,opt)
c          call mco_ast2h (time,jcen,nbod,2,optr(6),m,xu,vu,xh,vh,
c     %      ngf,ngflag,opt)
c        end if
c ##A19,165##
      end if
      itmp = 2
      if (algor.eq.11.or.algor.eq.12) itmp = 3
c ##AAR1,13##
      if (algor.eq.5) itmp = 4
c ##AAR1,13##
c ##A1,21##
c ##A6,14##
c ##A19,59##
c ##E14,38##
c ##A25,8##
c ##A38,112##
c ##A43,69##
      call mce_cent (time,h0,rcen,jcen,itmp,nbod,nbig,m,xh0,vh0,xh,vh,
     %  nhit,jhit,thit,dhit,algor,ngf,ngflag,optr,nbclo,bclo,rmax,
     %  opt,nstored,cce,flagce(2),tcol,opti,nov,nop,xv,yv,zv,noe,kkk,K2,
     %  AU,MSUN,coord,bcoord,xv0,yv0,zv0,tstart,lapla1,lapla2)
c ##A43,69##
c ##A38,112##
c ##A25,8##
c ##E14,38##
c ##A19,59##
c ##A6,14##
c ##A1,21##
c
c If something hit the central body, restore the coords prior to this step
      if (nhit.gt.0) then
c ##A24,11##
c ##AN28,127##
        call mce_criteria (tcol,tstart,nbod,algor,opt(3),m,id,
     %  opti,optr,mem,lmem,nbclo,nstored,K2)
c ##AN28,127##
c ##A24,11##
c ##A6,15##
c ##A23,9##
c ##AN28,50##
c ##A32,29##
c ##A35,44##
        call mce_header (tstart,algor,jcen,rcen,rmax,nbod,m,s,rho,
     %  id,opt,outfile(2),nbclo,bclo,nstored,nbig,K2,AU,MSUN,optr,
     %  idtag)
c ##A35,44##
c ##A32,29##
c ##AN28,50##
c ##A23,9##
        call mio_ceflush (opt(4),outfile(2),nstored,cce)
        flagce(1) = 1
        flagce(2) = 0
c ##A6,15##
c
c ##A38,22##
        call mco_iden (time,jcen,nbod,nbig,h0,m,xh0,vh0,xh,vh,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,22##
        time = time - h0
c
c Merge the object(s) with the central body
        do k = 1, nhit
          i = 1
          j = jhit(k)
c ##A11,12##
c ##A22,18##
c ##A19,210##
          call mce_coll (thit(k),tstart,en(3),jcen,i,j,nbod,nbig,m,xh,
     %      vh,s,rphys,stat,id,opt,mem,lmem,outfile(3),opti,0,nov,nop,
     %      noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,algor,K2,rho)
c ##A19,210##
c ##A22,18##
c ##A11,12##
        end do
c
c Remove lost objects, reset flags and recompute Hill and physical radii
c ##A4,12##
c ##A7,16##
c ##A8,13##
c ##E14,39##
c ##AN28,45##
c ##A35,17##
c ##A43,63##
        call mxx_elim (nbod,nbig,m,xh,vh,s,rho,rceh,rcrit,ngf,stat,
     %    id,mem,lmem,outfile(3),itmp,opti,stopflag,algor,optr,time,
     %    tstop,tstart,opt(3),tcol,K2,idtag,lapla1,lapla2)
c ##A43,63##
c ##A35,17##
c ##AN28,45##
c ##E14,39##
c ##A8,13##
c        if (stopflag.eq.1) return
c ##A7,16##
c ##A4,12##
        if (opflag.ge.0) opflag = 1
        dtflag = 1
c ##A17,23##
c ##AN28,37##
        call mce_init (tstart,algor,h0,jcen,rcen,rmax,cefac,nbod,nbig,
     %    m,xh,vh,s,rho,rceh,rphys,rce,rcrit,id,opt,outfile(2),0,opti,
     %    K2,AU,MSUN,ngflag)
c ##AN28,37##
c ##A17,23##
        if (algor.eq.1) then
c ##A38,23##
          call mco_iden (time,jcen,nbod,nbig,h0,m,xh,vh,x,v,ngf,ngflag,
     %      opt,optr,opti,K2,AU,MSUN)
        else
c ##A19,166##
c          if (algor.eq.22) then
c            call mco_iden (time,jcen,nbod,nbig,h0,m,xh,vh,xu,vu,ngf,
c     %        ngflag,opt)
c            call mco_h2ast (time,jcen,nbod,2,optr(6),m,xu,vu,xh,vh,
c     %        ngf,ngflag,opt)
c          end if
c ##A19,166##
          call coord (time-tstart,jcen,nbod,nbig,h0,m,xh,vh,x,v,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,23##
        end if
c
c ##A43,73##
        if (algor.ge.13) then
        do j = 2, nbod
          lapla1(j) = lapla2(j)
        end do
        end if
c ##A43,73##
c
c Redo that integration time step
        goto 150
      end if
      endif							!NEW!
