c  DATA  DUMP  AND  PROGRESS  REPORT
c
c Convert to heliocentric coords and do the data dump
      if (abs(time-tdump).ge.abs(dtdump).and.opflag.ge.-1) then
c ##A39,101##
        if (opti(80).eq.1.and.opti(81).eq.0) then
          nbod0 = nbod
          nbod  = nbod7
        end if
c ##A39,101##
c ##A38,96##
        call bcoord (time-tstart,jcen,nbod,nbig,h0,m,x,v,xh,vh,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,96##
c
c ##A39,87##
        if (opti(81).eq.1) then
          nbod0 = nbod
          call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),x7,xu)
          call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),v7,vu)
          do j = 1, nbod7-opti(82)
            k = j + nbod
            xh(1,k) = xu(1,j)+xh(1,2)
            xh(2,k) = xu(2,j)+xh(2,2)
            xh(3,k) = xu(3,j)+xh(3,2)
            vh(1,k) = vu(1,j)+vh(1,2)
            vh(2,k) = vu(2,j)+vh(2,2)
            vh(3,k) = vu(3,j)+vh(3,2)
            m(k)   = m7(j)
            s(1,k) = s7(1,j)
            s(2,k) = s7(2,j)
            s(3,k) = s7(3,j)
            rho(k) = rho7(j)
            rceh(k) = rceh7(j)
            rcrit(k) = rcrit7(j)
            stat(k) = stat7(j)
            id(k) = id7(j)
            ngf(1,k) = ngf7(1,j)
            ngf(2,k) = ngf7(2,j)
            ngf(3,k) = ngf7(3,j)
            ngf(4,k) = ngf7(4,j)
            idtag(k) = idtag7(j)
            x(1,k) = xh(1,k)
            x(2,k) = xh(2,k)
            x(3,k) = xh(3,k)
            v(1,k) = vh(1,k)
            v(2,k) = vh(2,k)
            v(3,k) = vh(3,k)
          end do
          opti(82) = nbod0
          nbod = k
          nbod7 = nbod
          opti(81) = 0
          optr(63) = time
        end if
c ##A39,87##
c
c ##A19,167##
c        if (algor.eq.22) then
c          call mco_iden (time,jcen,nbod,nbig,h0,m,xh,vh,xu,vu,ngf,
c     %      ngflag,opt)
c          call mco_ast2h (time,jcen,nbod,2,optr(6),m,xu,vu,xh,vh,
c     %      ngf,ngflag,opt)
c        end if
c ##A19,167##
        do j = 2, nbod
          epoch(j) = time
        end do
c ##A2,17##
c ##A6,16##
c ##A24,22##
c ##AN28,79##
c ##A35,55##
        call mio_ce (time,tstart,rcen,rmax,nbod,nbig,m,stat,id,
     %    0,iclo,jclo,opt,stopflag,tclo,dclo,ixvclo,jxvclo,mem,lmem,
     %    outfile,nstored,0,opti(1),aux,cce,algor,jcen,s,rho,nbclo,
     %    bclo,flagce,opti,optr,K2,AU,MSUN,idtag)
c ##A35,55##
c ##AN28,79##
c ##A24,22##
c ##A6,16##
c ##A2,17##
c ##A1,30##
c ##A2,30##
c ##A3,28##
c ##E9,48##
c ##A19,126##
c ##A20,28##
c ##AN28,13##
c ##A35,26##
c ##A38,141##
c ##A19,221##
        call mio_dump (time,tstart,tstop,dtout,algor,h0,tol,jcen,rcen,
     %    rmax,en,am,cefac,ndump,nfun,nbod,nbig,m,xh,vh,s,rho,rceh,stat,
     %    id,ngf,epoch,opt,opflag,dumpfile,mem,lmem,optr,opti,rmin,
     %    dtdump,nov,nop,noc,dens,binfile,outfile,treal,tuser,tsys,
     %    K2,AU,MSUN,idtag,ngflag,xv,yv,zv,noe,kkk,mc,xc,yc,zc)
c ##A19,221##
c ##A38,141##
c ##A35,26##
c ##AN28,13##
c ##A20,28##
c ##A19,126##
c ##E9,48##
c ##A3,28##
c ##A2,30##
c ##A1,30##
c ##A39,88##
        if (opti(80).eq.1.and.(opti(81).ge.0
     %    .and.opti(81).lt.3)) nbod = nbod0
c ##A39,88##
        tdump = time
      end if
c
c Convert to heliocentric coords and write a progress report to the log file
c ##A30,10##
c      if (abs(time-tlog).ge.abs(dtdump).and.opflag.ge.0) then
c        call bcoord (time-tstart,jcen,nbod,nbig,h0,m,x,v,xh,vh,ngf,ngflag,opt)
c ##A19,168##
c        if (algor.eq.22) then
c          call mco_iden (time,jcen,nbod,nbig,h0,m,xh,vh,xu,vu,ngf,
c     %      ngflag,opt)
c          call mco_ast2h (time,jcen,nbod,2,optr(6),m,xu,vu,xh,vh,
c     %      ngf,ngflag,opt)
c        end if
c ##A19,168##
c        call mxx_en (jcen,nbod,nbig,m,xh,vh,s,en(2),am(2),nov,nop,noc,
c     %    xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,K2,rho)
c ##A9,2##
c        call mio_log (time,tstart,en,am,opt,mem,lmem,outfile(4))
c ##A9,2##
c        tlog = time
c      end if
c ##A30,10##
c
c------------------------------------------------------------------------------
c
c  CHECK  FOR  EJECTIONS  AND  DO  OTHER  PERIODIC  EFFECTS
c
      if (abs(time-tfun).ge.abs(dtfun).and.opflag.ge.-1) then
        if (algor.eq.1) then
c ##A38,24##
          call mco_iden (time,jcen,nbod,nbig,h0,m,x,v,xh,vh,ngf,ngflag,
     %      opt,optr,opti,K2,AU,MSUN)
        else
          call bcoord(time-tstart,jcen,nbod,nbig,h0,m,x,v,xh,vh,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,24##
c ##A19,169##
c          if (algor.eq.22) then
c            call mco_iden (time,jcen,nbod,nbig,h0,m,xh,vh,xu,vu,ngf,
c     %        ngflag,opt)
c            call mco_ast2h (time,jcen,nbod,2,optr(6),m,xu,vu,xh,vh,
c     %        ngf,ngflag,opt)
c          end if
c ##A19,169##
        end if
c ##ANO29,23##
        do j = 2, nbod
c ##A38,116##
          call jc (nbod,j,algor,opti,optr,mem,lmem,id,xh,vh,m,tstart,
     %      time,jcen,ngf,ngflag,opt,maxjc,nov,nop,noc,xv,yv,zv,noe,kkk,
     %      dens,mc,xc,yc,zc,K2,AU,MSUN)
c ##A38,116##
        end do
c ##ANO29,23##
c
c Recompute close encounter limits, to allow for changes in Hill radii
        call mce_hill (nbod,m,xh,vh,rce,a)
        do j = 2, nbod
c ##A17,26##
          if (opti(20).eq.0) then
            rce(j) = rce(j) * rceh(j)
          else if (opti(20).eq.1) then
            rce(j) = rceh(j)
          end if
c ##A17,26##
        end do
c
c Check for ejections
        itmp = 2
        if (algor.eq.11.or.algor.eq.12) itmp = 3
c ##AAR1,14##
        if (algor.eq.5) itmp = 4
c ##AAR1,14##
c ##A7,4##
        if (opti(6).eq.1) itmp = itmp + 1
c ##A7,4##
c ##A3,16##
c ##A4,18##
c ##A6,17##
c ##AAR1,24##
c ##E11,5##
        do j = 1, nbod
          mej(j) = m(j)
        end do
c ##E11,5##
c ##E12,7##
c ##A34,8##
c ##A40,7##
c ##A19,225##
        call mxx_ejec (time,tstart,rmax,en,am,jcen,itmp,nbod,nbig,m,xh,
     %    vh,s,stat,id,opt,ejflag,outfile(3),mem,lmem,rmin,opti,nbclo,
     %    bclo,rcen,nstored,cce,flagce(2),algor,stopflag,optr,rce,nov,
     %    nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,K2,rho)
c ##A19,225##
c ##A40,7##
c ##A34,8##
c ##E12,7##
c ##AAR1,24##
c ##A6,17##
c ##A4,18##
c ##A3,16##
c
c ##A44,6##
        if (opti(90).eq.1) then
        call mxx_rotbrup (time,tstart,en,am,jcen,nbod,nbig,m,xh,vh,s,
     %    rotflag,outfile(3),mem,lmem,opti,nbclo,bclo,nstored,cce,
     %    flagce(2),algor,stopflag,optr,nov,nop,noc,xv,yv,zv,noe,kkk,
     %    dens,mc,xc,yc,zc,K2,rphys,opt,stat,id,rho)
        end if
c
c Remove ejected objects, reset flags, calculate new Hill and physical radii
c        if (ejflag.ne.0) then
        if (ejflag.ne.0.or.rotflag.ne.0) then
c ##A44,6##
c ##A24,12##
c ##AN28,128##
          call mce_criteria (time,tstart,nbod,algor,opt(3),m,id,
     %    opti,optr,mem,lmem,nbclo,nstored,K2)
c ##AN28,128##
c ##A24,12##
c ##A6,18##
c ##E11,6##
c ##A23,10##
c ##AN28,51##
c ##A32,30##
c ##A35,45##
          call mce_header (tstart,algor,jcen,rcen,rmax,nbod,mej,s,rho,
     %    id,opt,outfile(2),nbclo,bclo,nstored,nbig,K2,AU,MSUN,optr,
     %    idtag)
c ##A35,45##
c ##A32,30##
c ##AN28,51##
c ##A23,10##
c ##E11,6##
c ##E2,4##
          call mio_ceflush (opt(4),outfile(2),nstored,cce)
c ##E2,4##
          flagce(1) = 1
          flagce(2) = 0
c ##A6,18##
c ##A4,13##
c ##A7,17##
c ##A8,14##
c ##E14,40##
          tcol = time
c ##AN28,46##
c ##A35,18##
c ##A43,64##
          call mxx_elim (nbod,nbig,m,xh,vh,s,rho,rceh,rcrit,ngf,stat,
     %      id,mem,lmem,outfile(3),itmp,opti,stopflag,algor,optr,time,
     %      tstop,tstart,opt(3),tcol,K2,idtag,lapla1,lapla2)
c ##A43,64##
c ##A35,18##
c ##AN28,46##
c ##E14,40##
c ##A8,14##
c          if (stopflag.eq.1) return
c ##E12,8##
c ajm 2013-03-19 and end integration if opt(1) is set
c          if (stopflag.eq.1) return
          if (stopflag.eq.1) then
c
c ##A39,92##
            if (opti(80).eq.1.and.opti(81).eq.0) then
              nbod0 = nbod
              nbod  = nbod7
            end if
            if (opti(81).eq.1) then
              nbod0 = nbod
              call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),x7,
     %          xu)
              call mco_rot (time-optr(63),1,nbod7-opti(82),optr(6),v7,
     %          vu)
              do j = 1, nbod7-opti(82)
                k = j + nbod
                xh(1,k) = xu(1,j)+xh(1,2)
                xh(2,k) = xu(2,j)+xh(2,2)
                xh(3,k) = xu(3,j)+xh(3,2)
                vh(1,k) = vu(1,j)+vh(1,2)
                vh(2,k) = vu(2,j)+vh(2,2)
                vh(3,k) = vu(3,j)+vh(3,2)
                m(k)   = m7(j)
                s(1,k) = s7(1,j)
                s(2,k) = s7(2,j)
                s(3,k) = s7(3,j)
                rho(k) = rho7(j)
                rceh(k) = rceh7(j)
                rcrit(k) = rcrit7(j)
                stat(k) = stat7(j)
                id(k) = id7(j)
                ngf(1,k) = ngf7(1,j)
                ngf(2,k) = ngf7(2,j)
                ngf(3,k) = ngf7(3,j)
                ngf(4,k) = ngf7(4,j)
                idtag(k) = idtag7(j)
                x(1,k) = xh(1,k)
                x(2,k) = xh(2,k)
                x(3,k) = xh(3,k)
                v(1,k) = vh(1,k)
                v(2,k) = vh(2,k)
                v(3,k) = vh(3,k)
              end do
              opti(82) = nbod0
              nbod = k
              nbod7 = nbod
              opti(81) = 0
              optr(63) = time
            end if
c ##A39,92##
c
            tstop = tcol
            return
          end if
c ajm end edit
c ##E12,8##
c ##A7,17##
c ##A4,13##
          if (opflag.ge.0) opflag = 1
          dtflag = 1
c ##E2,3## antes da subrotina mce_init ser chamada para escrever os nomes dos
c corpos (suas massas, etc) no arquivo ce.out, os dados do vetor c devem ser
c descarregados (subrotina mio_ce), caso contrário os índices dos corpos que
c tiveram encontros próximos serão confundidos quando ocorrerem ejeções.
c ##E2,3##
c ##A17,24##
c ##AN28,38##
          call mce_init (tstart,algor,h0,jcen,rcen,rmax,cefac,nbod,nbig,
     %      m,xh,vh,s,rho,rceh,rphys,rce,rcrit,id,opt,outfile(2),0,opti,
     %      K2,AU,MSUN,ngflag)
c ##AN28,38##
c ##A17,24##
          if (algor.eq.1) then
c ##A38,25##
            call mco_iden (time,jcen,nbod,nbig,h0,m,xh,vh,x,v,ngf,
     %        ngflag,opt,optr,opti,K2,AU,MSUN)
          else
c ##A19,170##
c            if (algor.eq.22) then
c              call mco_iden (time,jcen,nbod,nbig,h0,m,xh,vh,xu,vu,ngf,
c     %          ngflag,opt)
c              call mco_h2ast (time,jcen,nbod,2,optr(6),m,xu,vu,xh,vh,
c     %          ngf,ngflag,opt)
c            end if
c ##A19,170##
            call coord (time-tstart,jcen,nbod,nbig,h0,m,xh,vh,x,v,ngf,
     %        ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,25##
          end if
        end if
        tfun = time
      end if
c
c ##ANO29,34##
c      if ((abs(time-tly).ge.abs(optr(28)).and.opti(42).eq.1)
c     %  .and.opflag.ge.-1) then
c        call ren (nbod,id,x,v,optr)
c        tly = time
c      end if
c ##ANO29,34##
c
c Go on to the next time step
      goto 100
c
c------------------------------------------------------------------------------
c
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c    MCE_BOX.FOR    (ErikSoft   30 September 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Given initial and final coordinates and velocities, the routine returns
c the X and Y coordinates of a box bounding the motion in between the
c end points.
c
c If the X or Y velocity changes sign, the routine performs a quadratic
c interpolation to estimate the corresponding extreme value of X or Y.
c
c------------------------------------------------------------------------------
c
      subroutine mce_box (nbod,h,x0,v0,x1,v1,xmin,xmax,ymin,ymax)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod
      real*8 h,x0(3,nbod), x1(3,nbod), v0(3,nbod),v1(3,nbod)
      real*8   xmin(nbod), xmax(nbod), ymin(nbod),ymax(nbod)
c
c Local
      integer j
      real*8 temp
c
c------------------------------------------------------------------------------
c
      do j = 2, nbod
        xmin(j) = min (x0(1,j), x1(1,j))
        xmax(j) = max (x0(1,j), x1(1,j))
        ymin(j) = min (x0(2,j), x1(2,j))
        ymax(j) = max (x0(2,j), x1(2,j))
c
c If velocity changes sign, do an interpolation
        if ((v0(1,j).lt.0.and.v1(1,j).gt.0).or.
     %      (v0(1,j).gt.0.and.v1(1,j).lt.0)) then
          temp = (v0(1,j)*x1(1,j) - v1(1,j)*x0(1,j) 
     %            - .5d0*h*v0(1,j)*v1(1,j)) / (v0(1,j) - v1(1,j))
          xmin(j) = min (xmin(j),temp)
          xmax(j) = max (xmax(j),temp)
        end if
c
        if ((v0(2,j).lt.0.and.v1(2,j).gt.0).or.
     %      (v0(2,j).gt.0.and.v1(2,j).lt.0)) then
          temp = (v0(2,j)*x1(2,j) - v1(2,j)*x0(2,j) 
     %            - .5d0*h*v0(2,j)*v1(2,j)) / (v0(2,j) - v1(2,j))
          ymin(j) = min (ymin(j),temp)
          ymax(j) = max (ymax(j),temp)
        end if
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c    MCE_CENT.FOR    (ErikSoft   4 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Checks all objects with index I >= I0, to see if they have had a collision
c with the central body in a time interval H, when given the initial and 
c final coordinates and velocities. The routine uses cubic interpolation
c to estimate the minimum separations.
c
c N.B. All coordinates & velocities must be with respect to the central body!!
c ===
c------------------------------------------------------------------------------
c
c ##A1,19##
c ##A5,25##
c ##A19,65##
c ##E14,30##
c ##A25,9##
c ##A38,109##
c ##A43,70##
      subroutine mce_cent (time,h,rcen,jcen,i0,nbod,nbig,m,x0,v0,x1,v1,
     %  nhit,jhit,thit,dhit,algor,ngf,ngflag,optr,nbclo,bclo,rmax,opt,
     %  nstored,cce,flagce,tcol,opti,nov,nop,xv,yv,zv,noe,k,K2,AU,MSUN,
     %  coord,bcoord,xv0,yv0,zv0,tstart,lapla1,lapla2)
c ##A43,70##
c ##A38,109##
c ##A25,9##
c ##E14,30##
c ##A19,65##
c ##A5,25##
c ##A1,19##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer i0, nbod, nbig, nhit, jhit(CMAX), algor, ngflag
      real*8 time,h,rcen,jcen(3),m(nbod),x0(3,nbod),v0(3,nbod)
      real*8 x1(3,nbod),v1(3,nbod),thit(CMAX),dhit(CMAX),ngf(4,nbod)
c ##A1,18##
c ##A19,66##
c      real*8 ltc
      real*8 optr(76)
c ##A19,66##
c ##A1,18##
c ##A5,23##
      integer nbclo,bclo(nbod)
      real*8 rmax
c      integer opt(8)
      integer nstored
      character*107 cce(FMAX)
      integer flagce
c ##A5,23##
c ##E14,31##
      real*8 tcol
c ##E14,31##
c ##A25,10##
      integer nov,nop,noe,k,noc
      real*8 xv(nov),yv(nov),zv(nov)
      integer opti(90)
      integer astflag,astflag1,astflag2
      dimension noe(nop)
      dimension k(nopmax,noed)
      real*8 xv0(nov),yv0(nov),zv0(nov)
      real*8 tstart
c ##A25,10##
c ##A38,110##
      real*8 K2,AU,MSUN
c ##A38,110##
c ##A43,71##
      integer lapla1(nbod)
      integer lapla2(nbod)
c ##A43,71##
c
c Local
      integer j,opt(9)
      real*8 rcen2,mco_acsh,a,q,u0,uhit,m0,mhit,mm,r0,mcen
      real*8 hx,hy,hz,h2,p,rr0,rr1,rv0,rv1,temp,e,v2
      real*8 xu0(3,NMAX),xu1(3,NMAX),vu0(3,NMAX),vu1(3,NMAX)
c ##A5,24##
      integer j2
c ##A5,24##
c ##E3,1##
      real*8 gm,x,y,z,u,v,w
      real*8 xc0,yc0,zc0,uc0,vc0,wc0
      real*8 xc1,yc1,zc1,uc1,vc1,wc1
      real*8 xc2,yc2,zc2,xc3,yc3,zc3
      real*8 r,true,bige
      real*8 ci,to,tmp2,ce
      real*8 i,n,pp,s,f,l,cf
c ##E3,1##
c ##A19,67##
      real*8 ltc,a2,b2,c2
      real*8 x0b(3,nbod),v0b(3,nbod)
      real*8 x1b(3,nbod),v1b(3,nbod)
      real*8 xh0(3,nbod),vh0(3,nbod)
      real*8 xh1(3,nbod),vh1(3,nbod)
      real*8 xh2(3,nbod),vh2(3,nbod)
      real*8 alpha0,alpha1
c ##A19,67##
c ##A25,15##
      real*8 el0,el1
c ##A25,15##
c ##A33,1##
      integer face
      real*8 x2,y2,z2
      real*8 prop,prop0,prop1
      external coord,bcoord
c ##A33,1##
c
c------------------------------------------------------------------------------
c
c ##A19,68##
      ltc = optr(1)
c      a2  = 1.d0 / optr(9)
c      b2  = 1.d0 / optr(10)
c      c2  = 1.d0 / optr(11)
      a2  = optr(9)
      b2  = optr(10)
      c2  = optr(11)
      alpha0 = optr(6) * (time - h)
      alpha1 = optr(6) * time
c ##A19,68##
c
      if (i0.le.0) i0 = 2
      nhit = 0
      rcen2 = rcen * rcen
      mcen = m(1)
c
c If using close-binary code, convert to coords with respect to the binary
c ##AAR1,4##
      if (algor.eq.11.or.algor.eq.5) then
c ##AAR1,4##
        mcen = m(1) + m(2)
c ##A18,11##
        call mco_h2ub (algor,temp,jcen,nbod,nbig,h,m,x0,v0,xu0,vu0,ngf,
     %    ngflag,opt)
        call mco_h2ub (algor,temp,jcen,nbod,nbig,h,m,x1,v1,xu1,vu1,ngf,
     %    ngflag,opt)
c ##A18,11##
      end if
c
c ##A19,179##
c      if (algor.ge.13) then
c ##A38,26##
c        call mco_iden (time,jcen,nbod,nbig,h,m,x0,v0,x0b,v0b,ngf,ngflag,
c     %    opt,optr,opti,K2,AU,MSUN)
c        call mco_iden (time,jcen,nbod,nbig,h,m,x1,v1,x1b,v1b,ngf,ngflag,
c     %    opt,optr,opti,K2,AU,MSUN)
c        call coord(time-tstart-h,jcen,nbod,2,optr(6),m,x0b,v0b,x0,v0,ngf,
c     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c        call coord(time-tstart,jcen,nbod,2,optr(6),m,x1b,v1b,x1,v1,ngf,
c     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,26##
c      end if
c ##A19,179##
c
c Check for collisions with the central body
      do j = i0, nbod
c ##A25,16##
        el0 = 0.d0
        el1 = 0.d0
c ##A25,16##
c ##AAR1,15##
        if (algor.eq.11.or.algor.eq.5) then
c ##AAR1,15##
          rr0 = xu0(1,j)*xu0(1,j) + xu0(2,j)*xu0(2,j) +xu0(3,j)*xu0(3,j)
          rr1 = xu1(1,j)*xu1(1,j) + xu1(2,j)*xu1(2,j) +xu1(3,j)*xu1(3,j)
          rv0 = vu0(1,j)*xu0(1,j) + vu0(2,j)*xu0(2,j) +vu0(3,j)*xu0(3,j)
          rv1 = vu1(1,j)*xu1(1,j) + vu1(2,j)*xu1(2,j) +vu1(3,j)*xu1(3,j)
        else
c ##A19,69##
          rr0 = x0(1,j)*x0(1,j) + x0(2,j)*x0(2,j) + x0(3,j)*x0(3,j)
          rr1 = x1(1,j)*x1(1,j) + x1(2,j)*x1(2,j) + x1(3,j)*x1(3,j)
c          if (algor.ge.13) then
c            el0 = x0(1,j)*x0(1,j) * a2 + x0(2,j)*x0(2,j) * b2 +
c     %        x0(3,j)*x0(3,j) * c2 -1.d0
c            el1 = x1(1,j)*x1(1,j) * a2 + x1(2,j)*x1(2,j) * b2 +
c     %        x1(3,j)*x1(3,j) * c2 -1.d0
c          end if
c          rr0 = x0(1,j)*x0(1,j) + x0(2,j)*x0(2,j) + x0(3,j)*x0(3,j)
c          rr1 = x1(1,j)*x1(1,j) + x1(2,j)*x1(2,j) + x1(3,j)*x1(3,j)
c ##A19,69##
          rv0 = v0(1,j)*x0(1,j) + v0(2,j)*x0(2,j) + v0(3,j)*x0(3,j)
          rv1 = v1(1,j)*x1(1,j) + v1(2,j)*x1(2,j) + v1(3,j)*x1(3,j)
        end if
c
c ##A19,179##
        if (algor.ge.13) then
c ##A38,26##
          call mco_iden2(time,jcen,j,j,h,m,x0,v0,x0b,v0b,ngf,
     %      ngflag,opt)
          call mco_iden2(time,jcen,j,j,h,m,x1,v1,x1b,v1b,ngf,
     %      ngflag,opt)
          call coord(time-tstart-h,jcen,j,j,optr(6),m,x0b,v0b,x0,v0,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
          call coord(time-tstart,jcen,j,j,optr(6),m,x1b,v1b,x1,v1,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,26##
          if (opti(72).eq.0) then
            el0 = x0(1,j)*x0(1,j) * a2 + x0(2,j)*x0(2,j) * b2 +
     %        x0(3,j)*x0(3,j) * c2 -1.d0
            el1 = x1(1,j)*x1(1,j) * a2 + x1(2,j)*x1(2,j) * b2 +
     %        x1(3,j)*x1(3,j) * c2 -1.d0
          else
            el0 = (x0(1,j)*cos(alpha0)+x0(2,j)*sin(alpha0)) *
     %        (x0(1,j)*cos(alpha0)+x0(2,j)*sin(alpha0)) * a2 +
     %        (x0(1,j)*sin(alpha0)-x0(2,j)*cos(alpha0)) *
     %        (x0(1,j)*sin(alpha0)-x0(2,j)*cos(alpha0)) * b2 +
     %        x0(3,j)*x0(3,j) * c2 -1.d0
            el1 = (x1(1,j)*cos(alpha1)+x1(2,j)*sin(alpha1)) *
     %        (x1(1,j)*cos(alpha1)+x1(2,j)*sin(alpha1)) * a2 +
     %        (x1(1,j)*sin(alpha1)-x1(2,j)*cos(alpha1)) *
     %        (x1(1,j)*sin(alpha1)-x1(2,j)*cos(alpha1)) * b2 +
     %        x1(3,j)*x1(3,j) * c2 -1.d0
          end if
        end if
c ##A19,179##
c
c If inside the central body, or passing through pericentre, use 2-body approx.
c ##A19,70##
c ##A25,11##
c        if ((rv0*h.le.0.and.rv1*h.ge.0).or.(min(rr0,rr1).le.rcen2
c     %    .or.((min(el0,el1).le.(0.d0).and.min(el0,el1).ne.-1.d0)
c     %    .and.algor.ge.13))) then
        astflag = 0
        astflag1= 0
        astflag2= 0
        if ((min(el0,el1).le.(0.d0).and.min(el0,el1).ne.-1.d0).and.
     %    algor.ge.13) then
          if (opti(40).eq.1) then
c            call raycasting (nov,nop,xv,yv,zv,noe,k,x0(1,j),x0(2,j),
c     %        x0(3,j),astflag)
c            if (astflag.eq.0) call raycasting (nov,nop,xv,yv,zv,noe,
c     %        k,x1(1,j),x1(2,j),x1(3,j),astflag)
c            call tetrah (nov,nop,xv,yv,zv,noe,k,x0(1,j),x0(2,j),
c     %        x0(3,j),astflag)
c ##A43,75##
            if (opti(87).eq.0) then
            if (opti(72).eq.0) then
            if (lapla1(1).eq.0) then
            call tetrah (nov,nop,xv,yv,zv,noe,k,x0(1,j),x0(2,j),
     %        x0(3,j),astflag1)
            lapla1(j) = astflag1
            end if
            astflag1 = lapla1(j)
c            if (astflag.eq.0) call tetrah (nov,nop,xv,yv,zv,noe,
c     %        k,x1(1,j),x1(2,j),x1(3,j),astflag)
            call tetrah (nov,nop,xv,yv,zv,noe,k,x1(1,j),x1(2,j),
     %        x1(3,j),astflag2)
            lapla2(j) = astflag2
c
            else
c
            if (lapla1(1).eq.0) then
            call tetrah (nov,nop,xv0,yv0,zv0,noe,k,x0(1,j),x0(2,j),
     %        x0(3,j),astflag1)
            lapla1(j) = astflag1
            end if
            astflag1 = lapla1(j)
            call tetrah (nov,nop,xv0,yv0,zv0,noe,k,x1(1,j),x1(2,j),
     %        x1(3,j),astflag2)
            lapla2(j) = astflag2
            end if
c
            else
c
            astflag1 = lapla1(j)
            astflag2 = lapla2(j)
            end if
c ##A43,75##
          else
            if (el0.gt.0.d0) then
              astflag1 = 0
            else
              astflag1 = 1
            end if
            if (el1.gt.0.d0) then
              astflag2 = 0
            else
              astflag2 = 1
            end if
          end if
          astflag = astflag1 + astflag2
        end if
        if ((rv0*h.le.0.and.rv1*h.ge.0).or.(min(rr0,rr1).le.rcen2
     %    .or.astflag.ge.1)) then
c ##A25,11##
c ##A19,70##
          xc2 = x0(1,j)
          yc2 = x0(2,j)
          zc2 = x0(3,j)
          xc3 = x1(1,j)
          yc3 = x1(2,j)
          zc3 = x1(3,j)
c          call bcoord(time-tstart-h,jcen,j,j,0.d0,m,x0,v0,xh0,vh0,ngf,
c     %      ngflag,opt)
c          call bcoord(time-tstart,jcen,j,j,0.d0,m,x1,v1,xh1,vh1,ngf,
c     %      ngflag,opt)
          call mco_iden2(time,jcen,j,j,h,m,x0,v0,xh0,vh0,ngf,
     %      ngflag,opt)
          call mco_iden2(time,jcen,j,j,h,m,x1,v1,xh1,vh1,ngf,
     %      ngflag,opt)
c ##A38,27##
          if (algor.ge.13) then
          call bcoord(time-tstart-h,jcen,j,j,optr(6),m,xh0,vh0,x0,v0,
     %      ngf,ngflag,opt,optr,opti,K2,AU,MSUN)
          call bcoord(time-tstart,jcen,j,j,optr(6),m,xh1,vh1,x1,v1,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
          else
          call mco_iden (time,jcen,nbod,nbig,h,m,x0,v0,xh0,vh0,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
          call mco_iden (time,jcen,nbod,nbig,h,m,x1,v1,xh1,vh1,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
          end if
c ##A38,27##
c
c ##AAR1,16##
          if (algor.eq.11.or.algor.eq.5) then
c ##AAR1,16##
            hx = xu0(2,j) * vu0(3,j)  -  xu0(3,j) * vu0(2,j)
            hy = xu0(3,j) * vu0(1,j)  -  xu0(1,j) * vu0(3,j)
            hz = xu0(1,j) * vu0(2,j)  -  xu0(2,j) * vu0(1,j)
            v2 = vu0(1,j)*vu0(1,j) +vu0(2,j)*vu0(2,j) +vu0(3,j)*vu0(3,j)
c ##E3,2##
            xc0 = xu0(1,j)
            yc0 = xu0(2,j)
            zc0 = xu0(3,j)
            uc0 = vu0(1,j)
            vc0 = vu0(2,j)
            wc0 = vu0(3,j)
            xc1 = xu1(1,j)
            yc1 = xu1(2,j)
            zc1 = xu1(3,j)
            uc1 = vu1(1,j)
            vc1 = vu1(2,j)
            wc1 = vu1(3,j)
c ##E3,2##
          else
            hx = x0(2,j) * v0(3,j)  -  x0(3,j) * v0(2,j)
            hy = x0(3,j) * v0(1,j)  -  x0(1,j) * v0(3,j)
            hz = x0(1,j) * v0(2,j)  -  x0(2,j) * v0(1,j)
            v2 = v0(1,j)*v0(1,j) + v0(2,j)*v0(2,j) + v0(3,j)*v0(3,j)
c ##E3,3##
            xc0 = x0(1,j)
            yc0 = x0(2,j)
            zc0 = x0(3,j)
            uc0 = v0(1,j)
            vc0 = v0(2,j)
            wc0 = v0(3,j)
            xc1 = x1(1,j)
            yc1 = x1(2,j)
            zc1 = x1(3,j)
            uc1 = v1(1,j)
            vc1 = v1(2,j)
            wc1 = v1(3,j)
c ##E3,3##
          end if
          h2 = hx*hx + hy*hy + hz*hz
          p = h2 / (mcen + m(j))
          r0 = sqrt(rr0)
          temp = 1.d0 + p*(v2/(mcen + m(j)) - 2.d0/r0)
          e = sqrt( max(temp,0.d0) )
          q = p / (1.d0 + e)
          rv0 = xc0 * uc0  +  yc0 * vc0  +  zc0 * wc0
c
c If the object hit the central body
c ##A1,17##
c ##A25,14##
          if (((q.le.rcen.or.min(rr0,rr1).le.rcen2).or.astflag.ge.1)
     %      .and.(min(r0,sqrt(rr1)).lt.ltc)) then				!NEW!
c ##A25,14##
c ##A1,17##
c ##E12,9##
c            nhit = nhit + 1
c            jhit(nhit) = j
c            dhit(nhit) = rcen
c ##E12,9##
c ##E3,4##
            gm = mcen + m(j)
            r = r0
c
c Inclination and node
            ci = hz / sqrt(h2)
c
            if (abs(ci).lt.1) then
              i = acos (ci)
c longitude do nodo medida a partir do momento angular perpendicular a órbita (projeção no plano XOY-inercial e no 4º quadrante (X,-Y)). Como a longitude do nodo é medida a partir do eixo +X, então a projeção no plano XOY-inercial do vetor momento angular (perpendicular ao plano de uma órbita com inclinação) se dará no 4º quadrante (X,-Y); Murray and Dermott (1999) - pg. 48, fig. 2.13; pg. 52, Eqs. 2.132 e 2.133; pg. 53, Eqs. 2.137 (dividir a primeira eq. pela segunda para aparecer tangente da longitude do nodo)
              n = atan2 (hx,-hy)
              if (n.lt.0) n = n + TWOPI
            else
              if (ci.gt.0) i = 0.d0
              if (ci.lt.0) i = PI
              n = 0.d0
            end if
c
c True longitude
            if (hy.ne.0) then
              to = -hx/hy
              temp = (1.d0 - ci) * to
              tmp2 = to * to
              true = atan2((yc0*(1.d0+tmp2*ci)-xc0*temp),
     %        (xc0*(tmp2+ci)-yc0*temp))
            else
              true = atan2(yc0 * ci, xc0)
            end if
            if (ci.lt.0) true = true + PI
c
            if (e.lt.3.d-8) then
c
              pp = 0.d0
              l = true
c
              mhit = 0.d0
              m0 = true
            else
c              ce = (v2*r - gm) / (e*gm)
c E=u0=uhit é a anomalia excêntrica e M=m0=mhit é a anomalia média. Logo, cos(E) = ce = 1/e*(1 - r/a) -> pág. 33, eq. 2.42 Murray. Mas, 1/a = 2/r - v2/gm -> pág. 53, eq. 2.134 Murray.
c Multiplicando os dois lados da equação 2.134 por r ficamos com r/a = 2 - v2*r/gm. Agora, substituindo na equação 2.42 temos que ce = 1/e*(1 -2 + v2*r/gm) = 1/e*(v2*r/gm - 1) => ce = (v2*r - gm) / (e*gm).
c
c Time of impact relative to the end of the timestep
c
c Mean anomaly for ellipse
              if (e.lt.1) then
                a = q / (1.d0 - e)
c
                ce = (1.d0 - rcen/a)/e
                if (abs(ce).gt.1) ce = sign(1.d0,ce)
c
                bige = acos(ce)
                if (rv0.lt.0) bige = TWOPI - bige
                l = bige - e*sin(bige)
c
c                uhit = sign (acos((1.d0 - rcen/a)/e), -h)
                uhit = sign (acos(ce), -h)
c
                ce = (1.d0 - r/a)/e
                if (abs(ce).gt.1) ce = sign(1.d0,ce)
c                u0   = sign (acos((1.d0 - r0/a  )/e), rv0)
                u0   = sign (acos(ce), rv0)
c
                mhit = mod (uhit - e*sin(uhit) + PI, TWOPI) - PI
                m0   = mod (u0   - e*sin(u0)   + PI, TWOPI) - PI
              else
c
c Mean anomaly for hyperbola
                a = q / (e - 1.d0)
c
                if (e.eq.1.d0) a = r
c
                ce = (1.d0 - rcen/a)/e
c                if (ce.lt.1) ce = 1.d0
c                uhit = sign (mco_acsh((1.d0 - rcen/a)/e), -h)
                uhit = sign (mco_acsh(ce), -h)
c
                ce = (1.d0 - r/a)/e
                if (ce.lt.1) ce = 1.d0
c
                bige = log( ce + sqrt(ce*ce-1.d0) )
                if (rv0.lt.0) bige = - bige
                l = e*sinh(bige) - bige
c
c                if (ce.lt.1) ce = 1.d0
c                u0   = sign (mco_acsh((1.d0 - r0/a  )/e), rv0)
                u0   = sign (mco_acsh(ce), rv0)
c
                mhit = mod (uhit - e*sinh(uhit) + PI, TWOPI) - PI
                m0   = mod (u0   - e*sinh(u0)   + PI, TWOPI) - PI
              end if
            end if
c ##E3,4##
            mm = sqrt((mcen + m(j)) / (a*a*a))
c ##E12,10##
c            thit(nhit) = (mhit - m0) / mm + time
c
c ajm 2012-05-28 edited this to check that collision occurs
c within the timestep
c
c ajm secundum andrew shannon 2014-08-28 added abs() to
c catch some leakers
c 
c dcarrera, ajm 2015-02-02 fixed an error in the calculation
c of uhit, u0, mhit, m0 for hyperbolic orbits.
c ##A25,17##
            if ((abs((mhit-m0)/mm).le.abs(h)).or.astflag.ge.1) then
c ##A25,17##
               nhit = nhit + 1
               jhit(nhit) = j
               dhit(nhit) = rcen
               thit(nhit) = (mhit - m0) / mm + time
c ##E14,32##
               tcol = thit(nhit)
c ##E14,32##
c ##E3,5##
c               s = p
               face = 0
c
c Longitude of perihelion
               if (e.ge.3.d-8) then
               cf = (p - r) / (e*r)
               if (abs(cf).gt.1) cf = sign(1.d0,cf)
               f = acos(cf)
               if (rv0.lt.0) f = TWOPI - f
               pp = true - f
               pp = mod (pp + TWOPI + TWOPI, TWOPI)
               end if
c
               if (l.lt.0) l = l + TWOPI
               if (l.gt.TWOPI) l = mod (l, TWOPI)
c
               call mco_el2x (gm,q,e,i,pp,n,l,x,y,z,u,v,w)
c
               if (rr0.le.rcen2) then
                 x = xc0
                 y = yc0
                 z = zc0
                 u = uc0
                 v = vc0
                 w = wc0
                 dhit(nhit) = dsqrt(rr0)
                 thit(nhit) = time - h
               else
                 if (rr1.le.rcen2) then
                   x = xc1
                   y = yc1
                   z = zc1
                   u = uc1
                   v = vc1
                   w = wc1
                   dhit(nhit) = dsqrt(rr1)
                   thit(nhit) = time
                 end if
               end if
               if((opti(40).eq.0.and.astflag.ge.1).and.algor.ge.13) then
                 if (astflag1.eq.1) then
                   x = xc0
                   y = yc0
                   z = zc0
                   u = uc0
                   v = vc0
                   w = wc0
                   dhit(nhit) = dsqrt(rr0)
                   thit(nhit) = time - h
                 else
                   if (astflag2.eq.1) then
                     x = xc1
                     y = yc1
                     z = zc1
                     u = uc1
                     v = vc1
                     w = wc1
                     dhit(nhit) = dsqrt(rr1)
                     thit(nhit) = time
                   end if
                 end if
               end if
               tcol = thit(nhit)
c
               xh0(1,j) = x
               xh0(2,j) = y
               xh0(3,j) = z
               vh0(1,j) = u
               vh0(2,j) = v
               vh0(3,j) = w
c
               if((opti(40).eq.1.and.astflag.ge.1).and.algor.ge.13) then
c ##A33,2##
                 if (astflag1.eq.0) then
                   call intersec (nov,nop,xv,yv,zv,noe,k,xc2,yc2,zc2,
     %               xc3,yc3,zc3,x,y,z,face)
                   prop0=(x-xc2)*(x-xc2)+(y-yc2)*(y-yc2)+(z-zc2)*(z-zc2)
                   prop1=(xc3-xc2)*(xc3-xc2)+(yc3-yc2)*(yc3-yc2)
     %               +(zc3-zc2)*(zc3-zc2)
                   prop = prop0 / prop1
                   prop = dsqrt(prop)
c                   thit(nhit) = (time - h) + h * prop
                   thit(nhit) = time + h * (prop - 1)
                 else
                   x = xc2
                   y = yc2
                   z = zc2
                   thit(nhit) = time - h
                 end if
                 r0 = dsqrt(x*x+y*y+z*z)
                 dhit(nhit) = r0
c Mean anomaly for ellipse
c                 if (e.lt.1) then
c                   a = q / (1.d0 - e)
c                   ce = (1.d0 - r0/a)/e
c                   if (abs(ce).gt.1) ce = sign(1.d0,ce)
c
c                   bige = acos(ce)
c                   if (rv0.lt.0) bige = TWOPI - bige
c                   l = bige - e*sin(bige)
c
c                   uhit = sign (acos(ce), -h)
c                   ce = (1.d0 - r/a)/e
c                   if (abs(ce).gt.1) ce = sign(1.d0,ce)
c                   u0   = sign (acos(ce), rv0)
c                   mhit = mod (uhit - e*sin(uhit) + PI, TWOPI) - PI
c                   m0   = mod (u0   - e*sin(u0)   + PI, TWOPI) - PI
c                 else
c
c Mean anomaly for hyperbola
c                   a = q / (e - 1.d0)
c                   if (e.eq.1.d0) a = r
c                   ce = (1.d0 - r0/a)/e
c                   if (ce.lt.1) ce = 1.d0
c
c                   bige = log( ce + sqrt(ce*ce-1.d0) )
c                   if (rv0.lt.0) bige = - bige
c                   l = e*sinh(bige) - bige
c
c                   uhit = sign (mco_acsh(ce), -h)
c                   ce = (1.d0 - r/a)/e
c                   u0   = sign (mco_acsh(ce), rv0)
c                   mhit = mod (uhit - e*sinh(uhit) + PI, TWOPI) - PI
c                   m0   = mod (u0   - e*sinh(u0)   + PI, TWOPI) - PI
c                 end if
c                 mm = sqrt((mcen + m(j)) / (a*a*a))
c
c                 if (l.lt.0) l = l + TWOPI
c                 if (l.gt.TWOPI) l = mod (l, TWOPI)
c
c                 call mco_el2x (gm,q,e,i,pp,n,l,x2,y2,z2,u,v,w)
c
c                 thit(nhit) = (mhit - m0) / mm + time
c                 tcol = thit(nhit)
c                 thit(nhit) = time
c                 tcol = time
c                 xh0(1,j) = x1(1,j)
c                 xh0(2,j) = x1(2,j)
c                 xh0(3,j) = x1(3,j)
c                 vh0(1,j) = v1(1,j)
c                 vh0(2,j) = v1(2,j)
c                 vh0(3,j) = v1(3,j)
                 tcol = thit(nhit)
                 xh1(1,j) = x
                 xh1(2,j) = y
                 xh1(3,j) = z
                 call mco_iden2(time,jcen,j,j,h,m,xh1,vh1,xh2,vh2,ngf,
     %             ngflag,opt)
c ##A38,28##
                 call bcoord(time-tstart,jcen,j,j,optr(6),m,xh2,vh2,xh0,
     %             vh0,ngf,ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,28##
c                 vh0(1,j) = u
c                 vh0(2,j) = v
c                 vh0(3,j) = w
                 vh0(1,j) = uc0
                 vh0(2,j) = vc0
                 vh0(3,j) = wc0
                 if (astflag1.eq.0) then
                 vh0(1,j) = uc0 + (uc1 - uc0) * prop
                 vh0(2,j) = vc0 + (vc1 - vc0) * prop
                 vh0(3,j) = wc0 + (wc1 - wc0) * prop
                 end if
c ##A33,2##
               end if
c ##E3,5##
c ##A5,22##
               call bcloo (nbclo,bclo,j,nbod,j2,flagce)
c ##E13,1##
c ##E3,6##
c ##A33,4##
c ##E19,11##
               call mio_cestored2 (nbod,m,j2,opt(4),thit(nhit),
     %         xh0,vh0,nstored,bclo,cce,'h',face,algor,optr)
c ##E19,11##
c ##A33,4##
c ##E3,6##
c ##E13,1##
c ##A5,22##
            endif
c ##E12,10##
          end if
c ##A19,180##
          call mco_iden2(time,jcen,j,j,h,m,x0,v0,xh0,vh0,ngf,
     %      ngflag,opt)
          call mco_iden2(time,jcen,j,j,h,m,x1,v1,xh1,vh1,ngf,
     %      ngflag,opt)
c ##A38,29##
          call coord(time-tstart-h,jcen,j,j,optr(6),m,xh0,vh0,x0,v0,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
          call coord(time-tstart,jcen,j,j,optr(6),m,xh1,vh1,x1,v1,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,29##
c ##A19,180##
        end if
      end do
c
c ##A19,181##
      if (algor.ge.13) then
c ##A38,30##
        call mco_iden (time,jcen,nbod,nbig,h,m,x0,v0,xh0,vh0,ngf,ngflag,
     %    opt,optr,opti,K2,AU,MSUN)
        call mco_iden (time,jcen,nbod,nbig,h,m,x1,v1,xh1,vh1,ngf,ngflag,
     %    opt,optr,opti,K2,AU,MSUN)
        call bcoord(time-tstart-h,jcen,nbod,2,optr(6),m,xh0,vh0,x0,v0,
     %    ngf,ngflag,opt,optr,opti,K2,AU,MSUN)
        call bcoord(time-tstart,jcen,nbod,2,optr(6),m,xh1,vh1,x1,v1,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,30##
        if (lapla1(1).eq.0) lapla1(1) = -1
      end if
c ##A19,181##
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCE_COLL.FOR    (ErikSoft   2 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Resolves a collision between two objects, using the collision model chosen
c by the user. Also writes a message to the information file, and updates the
c value of ELOST, the change in energy due to collisions and ejections.
c
c N.B. All coordinates and velocities must be with respect to central body.
c ===
c
c------------------------------------------------------------------------------
c
c ##A11,9##
c ##A22,22##
c ##A19,205##
c      subroutine mce_coll (time,tstart,elost,jcen,i,j,nbod,nbig,m,xh,
c     %  vh,s,rphys,stat,id,opt,mem,lmem,outfile,opti,icol,nov,nop,noc,
c     %  xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,algor,K2)
      subroutine mce_coll (time,tstart,elost,jcen,i,j,nbod,nbig,m,xh,
     %  vh,s,rphys,stat,id,opt,mem,lmem,outfile,opti,icol,nov,nop,noc,
     %  xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,algor,K2,rho)
c ##A19,205##
c ##A22,22##
c ##A11,9##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer i,j,nbod,nbig,stat(nbod),opt(9),lmem(NMESS)
      real*8 time,tstart,elost,jcen(3)
      real*8 m(nbod),xh(3,nbod),vh(3,nbod),s(3,nbod),rphys(nbod)
      character*80 outfile,mem(NMESS)
      character*8 id(nbod)
c ##A11,8##
      integer opti(90)
c ##A11,8##
c ##A22,23##
      integer icol
c ##A22,23##
c ##A19,207##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      integer algor
      real*8 optr(76)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      real*8 K2
      real*8 rho(nbod)
c ##A19,207##
c
c Local
      integer year,month,itmp
      real*8 t1
c ##A11,7##
      character*50 flost,fcol
c ##A11,7##
      character*6 tstring
c
c------------------------------------------------------------------------------
c
c If two bodies collided, check that the less massive one is removed
c (unless the more massive one is a Small body)
      if (i.ne.0) then
        if (m(j).gt.m(i).and.j.le.nbig) then
          itmp = i
          i = j
          j = itmp
        end if
      end if
c
c Write message to info file (I=0 implies collision with the central body)
c ##E9,7##
c  10  open (23, file=outfile, status='old', access='append', err=10)
c ##E9,7##
c
      if (opt(3).eq.1) then
        call mio_jd2y (time,year,month,t1)
        if (i.eq.0) then
c ##A11,1##
          opti(15) = opti(15) - 1
          opti(18) = opti(18) + 1
          flost = '(1x,a8,a,i10,1x,i2,1x,f8.5,3x,4(1x,i7))'
          write (23,flost) id(j),mem(67)(1:lmem(67)),year,month,t1,
     %      opti(15),opti(16),opti(17),opti(18)
c ##A11,1##
c ##A22,24##
        else if (icol.eq.1) then
c ##A11,2##
          opti(15) = opti(15) - 1
          opti(16) = opti(16) + 1
          fcol  = '(1x,a8,a,a8,a,i10,1x,i2,1x,f4.1,3x,4(1x,i7))'
          write (23,fcol) id(i),mem(69)(1:lmem(69)),id(j),
     %      mem(71)(1:lmem(71)),year,month,t1,
     %      opti(15),opti(16),opti(17),opti(18)
c ##A11,2##
        else if (icol.eq.2) then
          opti(15) = opti(15) - 1
          opti(16) = opti(16) + 1
          fcol  = '(1x,a8,a,a8,a,i10,1x,i2,1x,f4.1,3x,4(1x,i7))'
          write (23,fcol) id(i),mem(76)(1:lmem(76)),id(j),
     %      mem(71)(1:lmem(71)),year,month,t1,
     %      opti(15),opti(16),opti(17),opti(18)
c ##A22,24##
        end if
      else
        if (opt(3).eq.3) then
          t1 = (time - tstart) / 365.25d0
          tstring = mem(2)
c ##A11,3##
          flost = '(1x,a8,a,f18.7,a,3x,4(1x,i7))'
          fcol  = '(1x,a8,a,a8,a,1x,f14.3,a,3x,4(1x,i7))'
c ##A11,3##
        else
          if (opt(3).eq.0) t1 = time
          if (opt(3).eq.2) t1 = time - tstart
          tstring = mem(1)
c ##A11,4##
          flost = '(1x,a8,a,f18.5,a,3x,4(1x,i7))'
          fcol  = '(1x,a8,a,a8,a,1x,f14.1,a,3x,4(1x,i7))'
c ##A11,4##
        end if
        if (i.eq.0.or.i.eq.1) then
c ##A11,5##
          opti(15) = opti(15) - 1
          opti(18) = opti(18) + 1
          write (23,flost) id(j),mem(67)(1:lmem(67)),t1,tstring,
     %      opti(15),opti(16),opti(17),opti(18)
c ##A11,5##
c ##A22,25##
        else if (icol.eq.1) then
c ##A11,6##
          opti(15) = opti(15) - 1
          opti(16) = opti(16) + 1
          write (23,fcol) id(i),mem(69)(1:lmem(69)),id(j),
     %      mem(71)(1:lmem(71)),t1,tstring,
     %      opti(15),opti(16),opti(17),opti(18)
c ##A11,6##
        else if (icol.eq.2) then
          opti(15) = opti(15) - 1
          opti(16) = opti(16) + 1
          write (23,fcol) id(i),mem(76)(1:lmem(76)),id(j),
     %      mem(71)(1:lmem(71)),t1,tstring,
     %      opti(15),opti(16),opti(17),opti(18)
c ##A22,25##
        end if
      end if
c ##E9,8##
c      close (23)
c ##E9,8##
c
c Do the collision (inelastic merger)
c ##A19,206##
c      call mce_merg (jcen,i,j,nbod,nbig,m,xh,vh,s,stat,elost,
c     %  nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,
c     %  K2,rphys)
      call mce_merg (jcen,i,j,nbod,nbig,m,xh,vh,s,stat,elost,
     %  nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,
     %  K2,rho)
c ##A19,206##
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCE_HILL.FOR    (ErikSoft   4 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates the Hill radii for all objects given their masses, M,
c coordinates, X, and velocities, V; plus the mass of the central body, M(1)
c Where HILL = a * (m/3*m(1))^(1/3)
c
c If the orbit is hyperbolic or parabolic, the Hill radius is calculated using:
c       HILL = r * (m/3*m(1))^(1/3)
c where R is the current distance from the central body.
c
c The routine also gives the semi-major axis, A, of each object's orbit.
c
c N.B. Designed to use heliocentric coordinates, but should be adequate using
c ===  barycentric coordinates.
c
c------------------------------------------------------------------------------
c
      subroutine mce_hill (nbod,m,x,v,hill,a)
c
      implicit none
      include 'mercury.inc'
      real*8 THIRD
      parameter (THIRD = .3333333333333333d0)
c
c Input/Output
      integer nbod
      real*8 m(nbod),x(3,nbod),v(3,nbod),hill(nbod),a(nbod)
c
c Local
      integer j
      real*8 r, v2, gm
c
c------------------------------------------------------------------------------
c
      do j = 2, nbod
        gm = m(1) + m(j)
        call mco_x2a (gm,x(1,j),x(2,j),x(3,j),v(1,j),v(2,j),v(3,j),a(j),
     %    r,v2)
c If orbit is hyperbolic, use the distance rather than the semi-major axis
        if (a(j).le.0) a(j) = r
        hill(j) = a(j) * (THIRD * m(j) / m(1))**THIRD
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCE_INIT.FOR    (ErikSoft   28 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates close-approach limits RCE (in AU) and physical radii RPHYS
c (in AU) for all objects, given their masses M, coordinates X, velocities
c V, densities RHO, and close-approach limits RCEH (in Hill radii).
c
c Also calculates the changeover distance RCRIT, used by the hybrid
c symplectic integrator. RCRIT is defined to be the larger of N1*HILL and
c N2*H*VMAX, where HILL is the Hill radius, H is the timestep, VMAX is the
c largest expected velocity of any body, and N1, N2 are parameters (see
c section 4.2 of Chambers 1999, Monthly Notices, vol 304, p793-799).
c
c N.B. Designed to use heliocentric coordinates, but should be adequate using
c ===  barycentric coordinates.
c
c------------------------------------------------------------------------------
c
c ##A17,13##
c ##AN28,20##
      subroutine mce_init (tstart,algor,h,jcen,rcen,rmax,cefac,nbod,
     %  nbig,m,x,v,s,rho,rceh,rphys,rce,rcrit,id,opt,outfile,rcritflag,
     %  opti,K2,AU,MSUN,ngflag)
c ##AN28,20##
c ##A17,13##
c
      implicit none
      include 'mercury.inc'
c
      real*8 N2,THIRD
      parameter (N2=.4d0,THIRD=.3333333333333333d0)
c
c Input/Output
      integer nbod,nbig,algor,opt(9),rcritflag
      real*8 tstart,h,jcen(3),rcen,rmax,cefac,m(nbod),x(3,nbod)
      real*8 v(3,nbod),s(3,nbod),rho(nbod),rceh(nbod),rphys(nbod)
      real*8 rce(nbod),rcrit(nbod)
      character*8 id(nbod)
      character*80 outfile
c ##A17,14##
      integer opti(90)
c ##A17,14##
c ##AN28,21##
      real*8 K2,AU,MSUN
      integer ngflag
c ##AN28,21##
c
c Local
      integer j
      real*8 a(NMAX),hill(NMAX),temp,amin,vmax,k_2,rhocgs,rcen_2
      character*80 header,c(NMAX)
      character*8 mio_re2c, mio_fl2c
c
c------------------------------------------------------------------------------
c
      rhocgs = AU * AU * AU * K2 / MSUN
      k_2 = 1.d0 / K2
      rcen_2 = 1.d0 / (rcen * rcen)
      amin = HUGE
c
c Calculate the Hill radii
      call mce_hill (nbod,m,x,v,hill,a)
c
c Determine the maximum close-encounter distances, and the physical radii
      temp = 2.25d0 * m(1) / PI
      do j = 2, nbod
c ##A17,15##
c ##A40,5##
        if (opti(20).eq.0.or.opti(75).eq.0) then
          rce(j)   = hill(j) * rceh(j)
        else if (opti(20).eq.1.or.opti(75).eq.1) then
          rce(j)   = rceh(j)
        end if
c ##A40,5##
c ##A17,15##
c Ideia genial do Chambers para contornar o problema de encontrar o raio físico de um corpo esférico quando ele tem massa nula
c usando o raio de Hill ao invés da definição densidade = massa / volume.
c Se a massa do corpo é nula (m(j)=0) seu raio de Hill também será nulo (hill(j)=0) e daí seu raio físico também será nulo (rphys(j)=0).
c
c THIRD= 1/3
c temp = 2.25d0 * m(1) / PI = 9/4 * m(1) / PI
c hill(j) = a(j) * (THIRD * m(j) / m(1))**THIRD = a(j) * (1/3 * m(j) / m(1))**(1/3)
c
c rphys(j) = hill(j) / a(j) * (temp/rho(j))**(1/3) -> substituindo hill(j) ->
c rphys(j) = [a(j) * (1/3 * m(j) / m(1))**(1/3)] / a(j) * (temp/rho(j))**(1/3) ->
c rphys(j) = (1/3 * m(j) / m(1))**(1/3) * (temp/rho(j))**(1/3) -> agrupando termos de ( )**(1/3) ->
c rphys(j) = (1/3 * m(j) / m(1) * temp/rho(j))**(1/3) -> substituindo temp ->
c rphys(j) = (1/3 * m(j) / m(1) * [9/4 * m(1) / PI] /rho(j))**(1/3) ->
c rphys(j) = (1/3 * m(j) * 9/4 / PI /rho(j))**(1/3) ->
c rphys(j) = (m(j) * 3/4 / PI /rho(j))**(1/3) -> definição raio físico volumétrico de uma esfera -> densidade = massa / volume -> volume = massa / densidade -> 4/3*PI*R**3 = massa / densidade -> R = (massa * 3/4 / PI /densidade)**(1/3)
        rphys(j) = hill(j) / a(j) * (temp/rho(j))**THIRD
c ##A38,145##
        if (rphys(j).eq.0.d0.and.(ngflag.eq.2.or.ngflag.eq.3)) then
          rphys(j) = rho(j) / rhocgs / AU
        end if
c ##A38,145##
        amin = min (a(j), amin)
      end do
c
c If required, calculate the changeover distance used by hybrid algorithm
      if (rcritflag.eq.1) then
        vmax = sqrt (m(1) / amin)
        temp = N2 * h * vmax
        do j = 2, nbod
c ##A17,16##
c ##A40,13##
          if (opti(20).eq.0.or.opti(75).eq.0) then
            rcrit(j) = max(hill(j) * cefac, temp)
          else if (opti(20).eq.1.or.opti(75).eq.1) then
            rcrit(j) = max(cefac, temp)
          end if
c ##A40,13##
c ##A17,16##
        end do
      end if
c
c Write list of object's identities to close-encounter output file
c ##A5,11## se todas as linhas abaixo estiverem comentadas, então ao se usar o integrador híbrido poderá existir diferenças em duas simulações com as mesmas condições iniciais. Para corrigir este problema, ou seja, deixar as simulações idênticas como quando se usa o mercury original basta acrescentar qualquer linha de comando válida em fortran após esta linha. Como no mercury original estas linhas NÃO estão comentadas, então optei por escolher essa situação como a situação de simulação correta apesar de não entender o porquê de isso acontecer!
      header(1:8)   = mio_fl2c (tstart)
c      header(9:16)  = mio_re2c (dble(nbig - 1),   0.d0, 11239423.99d0)
c      header(12:19) = mio_re2c (dble(nbod - nbig),0.d0, 11239423.99d0)
c      header(15:22) = mio_fl2c (m(1) * k_2)
c      header(23:30) = mio_fl2c (jcen(1) * rcen_2)
c      header(31:38) = mio_fl2c (jcen(2) * rcen_2 * rcen_2)
c      header(39:46) = mio_fl2c (jcen(3) * rcen_2 * rcen_2 * rcen_2)
c      header(47:54) = mio_fl2c (rcen)
c      header(55:62) = mio_fl2c (rmax)
c
c      do j = 2, nbod
c        c(j)(1:8) = mio_re2c (dble(j - 1), 0.d0, 11239423.99d0)
c        c(j)(4:11) = id(j)
c        c(j)(12:19) = mio_fl2c (m(j) * k_2)
c        c(j)(20:27) = mio_fl2c (s(1,j) * k_2)
c        c(j)(28:35) = mio_fl2c (s(2,j) * k_2)
c        c(j)(36:43) = mio_fl2c (s(3,j) * k_2)
c        c(j)(44:51) = mio_fl2c (rho(j) / rhocgs)
c      end do
c
c Write compressed output to file
c  50  open (22, file=outfile, status='old', access='append', err=50)
c      write (22,'(a1,a2,i2,a62,i1)') char(12),'6a',algor,header(1:62),
c     %  opt(4)
c      do j = 2, nbod
c        write (22,'(a51)') c(j)(1:51)
c      end do
c      close (22)
c ##A5,11##
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCE_MERG.FOR    (ErikSoft   2 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% c
c Author: John E. Chambers
c
c Merges objects I and J inelastically to produce a single new body by 
c conserving mass and linear momentum.
c   If J <= NBIG, then J is a Big body
c   If J >  NBIG, then J is a Small body
c   If I = 0, then I is the central body
c
c N.B. All coordinates and velocities must be with respect to central body.
c ===
c
c------------------------------------------------------------------------------
c
c ##A19,204##
c      subroutine mce_merg (jcen,i,j,nbod,nbig,m,xh,vh,s,stat,elost,
c     %  nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,
c     %  K2,rphys)
      subroutine mce_merg (jcen,i,j,nbod,nbig,m,xh,vh,s,stat,elost,
     %  nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,
     %  K2,rho)
c ##A19,204##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer i, j, nbod, nbig, stat(nbod)
      real*8 jcen(3),m(nbod),xh(3,nbod),vh(3,nbod),s(3,nbod),elost
c ##A19,203##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      integer algor
      real*8 optr(76)
      integer opti(90)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      real*8 K2
c      real*8 rphys(nbod)
      real*8 rho(nbod)
c ##A19,203##
c
c Local
      integer k
      real*8 tmp1, tmp2, dx, dy, dz, du, dv, dw, msum, mredu, msum_1
      real*8 e0, e1, l2
c
c------------------------------------------------------------------------------
c
c If a body hits the central body
      if (i.le.1) then
c ##A19,198##
        call mxx_en (jcen,nbod,nbig,m,xh,vh,s,e0,l2,nov,nop,noc,
     %  xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,K2,rho)
c ##A19,198##
c
c If a body hit the central body...
        msum   = m(1) + m(j)
        msum_1 = 1.d0 / msum
        mredu  = m(1) * m(j) * msum_1
        dx = xh(1,j)
        dy = xh(2,j)
        dz = xh(3,j)
        du = vh(1,j)
        dv = vh(2,j)
        dw = vh(3,j)
c
c Calculate new spin angular momentum of the central body
        s(1,1) = s(1,1)  +  s(1,j)  +  mredu * (dy * dw  -  dz * dv)
        s(2,1) = s(2,1)  +  s(2,j)  +  mredu * (dz * du  -  dx * dw)
        s(3,1) = s(3,1)  +  s(3,j)  +  mredu * (dx * dv  -  dy * du)
c
c Calculate shift in barycentric coords and velocities of central body
        tmp2 = m(j) * msum_1
        xh(1,1) = tmp2 * xh(1,j)
        xh(2,1) = tmp2 * xh(2,j)
        xh(3,1) = tmp2 * xh(3,j)
        vh(1,1) = tmp2 * vh(1,j)
        vh(2,1) = tmp2 * vh(2,j)
        vh(3,1) = tmp2 * vh(3,j)
        m(1) = msum
        m(j) = 0.d0
        s(1,j) = 0.d0
        s(2,j) = 0.d0
        s(3,j) = 0.d0
c
c Shift the heliocentric coordinates and velocities of all bodies
        do k = 2, nbod
          xh(1,k) = xh(1,k) - xh(1,1)
          xh(2,k) = xh(2,k) - xh(2,1)
          xh(3,k) = xh(3,k) - xh(3,1)
          vh(1,k) = vh(1,k) - vh(1,1)
          vh(2,k) = vh(2,k) - vh(2,1)
          vh(3,k) = vh(3,k) - vh(3,1)
        end do
c
c Calculate energy loss due to the collision
c ##A19,199##
        call mxx_en (jcen,nbod,nbig,m,xh,vh,s,e1,l2,nov,nop,noc,
     %  xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,K2,rho)
c ##A19,199##
        elost = elost + (e0 - e1)
      else
c
c If two bodies collided...
        msum   = m(i) + m(j)
        msum_1 = 1.d0 / msum
        mredu  = m(i) * m(j) * msum_1
        dx = xh(1,i) - xh(1,j)
        dy = xh(2,i) - xh(2,j)
        dz = xh(3,i) - xh(3,j)
        du = vh(1,i) - vh(1,j)
        dv = vh(2,i) - vh(2,j)
        dw = vh(3,i) - vh(3,j)
c
c Calculate energy loss due to the collision
        elost = elost  +  .5d0 * mredu * (du*du + dv*dv + dw*dw)
     %        -  m(i) * m(j) / sqrt(dx*dx + dy*dy + dz*dz)
c
c Calculate spin angular momentum of the new body
        s(1,i) = s(1,i)  +  s(1,j)  +  mredu * (dy * dw  -  dz * dv)
        s(2,i) = s(2,i)  +  s(2,j)  +  mredu * (dz * du  -  dx * dw)
        s(3,i) = s(3,i)  +  s(3,j)  +  mredu * (dx * dv  -  dy * du)
c
c Calculate new coords and velocities by conserving centre of mass & momentum
        tmp1 = m(i) * msum_1
        tmp2 = m(j) * msum_1
        xh(1,i) = xh(1,i) * tmp1  +  xh(1,j) * tmp2
        xh(2,i) = xh(2,i) * tmp1  +  xh(2,j) * tmp2
        xh(3,i) = xh(3,i) * tmp1  +  xh(3,j) * tmp2
        vh(1,i) = vh(1,i) * tmp1  +  vh(1,j) * tmp2
        vh(2,i) = vh(2,i) * tmp1  +  vh(2,j) * tmp2
        vh(3,i) = vh(3,i) * tmp1  +  vh(3,j) * tmp2
        m(i) = msum
      end if
c
c Flag the lost body for removal, and move it away from the new body
      stat(j) = -2
      xh(1,j) = -xh(1,j)
      xh(2,j) = -xh(2,j)
      xh(3,j) = -xh(3,j)
      vh(1,j) = -vh(1,j)
      vh(2,j) = -vh(2,j)
      vh(3,j) = -vh(3,j)
      m(j)   = 0.d0
      s(1,j) = 0.d0
      s(2,j) = 0.d0
      s(3,j) = 0.d0
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCE_MIN.FOR    (ErikSoft  1 December 1998)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates minimum value of a quantity D, within an interval H, given initial
c and final values D0, D1, and their derivatives D0T, D1T, using third-order
c (i.e. cubic) interpolation.
c
c Also calculates the value of the independent variable T at which D is a
c minimum, with respect to the epoch of D1.
c
c N.B. The routine assumes that only one minimum is present in the interval H.
c ===
c------------------------------------------------------------------------------
c
      subroutine mce_min (d0,d1,d0t,d1t,h,d2min,tmin)
c
      implicit none
c
c Input/Output
      real*8 d0,d1,d0t,d1t,h,d2min,tmin
c
c Local
      real*8 a,b,c,temp,tau
c
c------------------------------------------------------------------------------
c
      if (d0t*h.gt.0.or.d1t*h.lt.0) then
        if (d0.le.d1) then
          d2min = d0
          tmin = -h
        else
          d2min = d1
          tmin = 0.d0
        end if
      else
        temp = 6.d0*(d0 - d1)
        a = temp + 3.d0*h*(d0t + d1t)
        b = temp + 2.d0*h*(d0t + 2.d0*d1t)
        c = h * d1t
c
        temp =-.5d0*(b + sign (sqrt(max(b*b - 4.d0*a*c,0.d0)), b) )
        if (temp.eq.0) then
          tau = 0.d0
        else
          tau = c / temp
        end if
c
c Make sure TAU falls in the interval -1 < TAU < 0
        tau = min(tau, 0.d0)
        tau = max(tau, -1.d0)
c
c Calculate TMIN and D2MIN
        tmin = tau * h
        temp = 1.d0 + tau
        d2min = tau*tau*((3.d0+2.d0*tau)*d0 + temp*h*d0t)
     %        + temp*temp*((1.d0-2.d0*tau)*d1 + tau*h*d1t)
c
c Make sure D2MIN is not negative
        d2min = max(d2min, 0.d0)
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c    MCE_SNIF.FOR    (ErikSoft   3 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Given initial and final coordinates and velocities X and V, and a timestep 
c H, the routine estimates which objects were involved in a close encounter
c during the timestep. The routine examines all objects with indices I >= I0.
c
c Returns an array CE, which for each object is: 
c                           0 if it will undergo no encounters
c                           2 if it will pass within RCRIT of a Big body
c
c Also returns arrays ICE and JCE, containing the indices of each pair of
c objects estimated to have undergone an encounter.
c
c N.B. All coordinates must be with respect to the central body!!!!
c ===
c
c------------------------------------------------------------------------------
c
      subroutine mce_snif (h,i0,nbod,nbig,x0,v0,x1,v1,rcrit,ce,nce,ice,
     %  jce)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer i0,nbod,nbig,ce(nbod),nce,ice(NMAX),jce(NMAX)
      real*8 x0(3,nbod),v0(3,nbod),x1(3,nbod),v1(3,nbod),h,rcrit(nbod)
c
c Local
      integer i,j
      real*8 d0,d1,d0t,d1t,d2min,temp,tmin,rc,rc2
      real*8 dx0,dy0,dz0,du0,dv0,dw0,dx1,dy1,dz1,du1,dv1,dw1
      real*8 xmin(NMAX),xmax(NMAX),ymin(NMAX),ymax(NMAX)
c
c------------------------------------------------------------------------------
c
      if (i0.le.0) i0 = 2
      nce = 0
      do j = 2, nbod
        ce(j) = 0
      end do
c
c Calculate maximum and minimum values of x and y coordinates
      call mce_box (nbod,h,x0,v0,x1,v1,xmin,xmax,ymin,ymax)
c
c Adjust values for the Big bodies by symplectic close-encounter distance
      do j = i0, nbig
        xmin(j) = xmin(j) - rcrit(j)
        xmax(j) = xmax(j) + rcrit(j)
        ymin(j) = ymin(j) - rcrit(j)
        ymax(j) = ymax(j) + rcrit(j)
      end do
c
c Identify pairs whose X-Y boxes overlap, and calculate minimum separation
      do i = i0, nbig
        do j = i + 1, nbod
          if (xmax(i).ge.xmin(j).and.xmax(j).ge.xmin(i)
     %      .and.ymax(i).ge.ymin(j).and.ymax(j).ge.ymin(i)) then
c
c Determine the maximum separation that would qualify as an encounter
            rc = max(rcrit(i), rcrit(j))
            rc2 = rc * rc
c
c Calculate initial and final separations
            dx0 = x0(1,i) - x0(1,j)
            dy0 = x0(2,i) - x0(2,j)
            dz0 = x0(3,i) - x0(3,j)
            dx1 = x1(1,i) - x1(1,j)
            dy1 = x1(2,i) - x1(2,j)
            dz1 = x1(3,i) - x1(3,j)
            d0 = dx0*dx0 + dy0*dy0 + dz0*dz0
            d1 = dx1*dx1 + dy1*dy1 + dz1*dz1
c
c Check for a possible minimum in between
            du0 = v0(1,i) - v0(1,j)
            dv0 = v0(2,i) - v0(2,j)
            dw0 = v0(3,i) - v0(3,j)
            du1 = v1(1,i) - v1(1,j)
            dv1 = v1(2,i) - v1(2,j)
            dw1 = v1(3,i) - v1(3,j)
            d0t = (dx0*du0 + dy0*dv0 + dz0*dw0) * 2.d0
            d1t = (dx1*du1 + dy1*dv1 + dz1*dw1) * 2.d0
c
c If separation derivative changes sign, find the minimum separation
            d2min = HUGE
            if (d0t*h.le.0.and.d1t*h.ge.0) call mce_min (d0,d1,d0t,d1t,
     %        h,d2min,tmin)
c
c If minimum separation is small enough, flag this as a possible encounter
            temp = min (d0,d1,d2min)
            if (temp.le.rc2) then
              ce(i) = 2
              ce(j) = 2
              nce = nce + 1
              ice(nce) = i
              jce(nce) = j
            end if
          end if
        end do
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c    MCE_STAT.FOR    (ErikSoft   1 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Returns details of all close-encounter minima involving at least one Big
c body during a timestep. The routine estimates minima using the initial
c and final coordinates X(0),X(1) and velocities V(0),V(1) of the step, and
c the stepsize H.
c
c  ICLO, JCLO contain the indices of the objects
c  DCLO is their minimum separation
c  TCLO is the time of closest approach relative to current time
c
c The routine also checks for collisions/near misses given the physical radii 
c RPHYS, and returns the time THIT of the collision/near miss closest to the
c start of the timestep, and the identities IHIT and JHIT of the objects
c involved.
c
c  NHIT = +1 implies a collision
c         -1    "    a near miss
c
c N.B. All coordinates & velocities must be with respect to the central body!!
c ===
c------------------------------------------------------------------------------
c
c ##A5,40##
c ##A22,6##
c ##E14,1##
      subroutine mce_stat (time,h,rcen,nbod,nbig,m,x0,v0,x1,v1,rce,
     %  rphys,nclo,iclo,jclo,dclo,tclo,ixvclo,jxvclo,nhit,ihit,jhit,
     %  chit,dhit,thit,thit1,nowflag,stat,outfile,mem,lmem,opti,
     %  nbclo,bclo,aux,flagce,index,nbod2,iflag,opt,tstart,id,nelim,
     %  tcol)
c ##E14,1##
c ##A22,6##
c ##A5,40##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,stat(nbod),nowflag
      integer nclo,iclo(CMAX),jclo(CMAX)
      integer nhit,ihit(CMAX),jhit(CMAX),chit(CMAX),lmem(NMESS)
      real*8 time,h,rcen,m(nbod),x0(3,nbod),v0(3,nbod)
      real*8 x1(3,nbod),v1(3,nbod),rce(nbod),rphys(nbod)
      real*8 dclo(CMAX),tclo(CMAX),thit(CMAX),dhit(CMAX),thit1
      real*8 ixvclo(6,CMAX),jxvclo(6,CMAX)
      character*80 outfile,mem(NMESS)
c ##A5,41##
      integer opti(90),nbclo,bclo(nbod)
      character*1 aux(CMAX)
      integer flagce
      integer index(NMAX)
      integer nbod2,iflag
c ##A5,41##
c ##A22,7##
      integer opt,nelim
      real*8 tstart
      character*8 id(nbod)
c ##A22,7##
c ##E14,2##
      real*8 tcol
c ##E14,2##
c
c Local
      integer i,j
      real*8 d0,d1,d0t,d1t,hm1,tmp0,tmp1
      real*8 dx0,dy0,dz0,du0,dv0,dw0,dx1,dy1,dz1,du1,dv1,dw1
      real*8 xmin(NMAX),xmax(NMAX),ymin(NMAX),ymax(NMAX)
      real*8 d2min,d2ce,d2near,d2hit,temp,tmin
c ##A17,10##
c      real*8 hill(nbod),a(nbod),rcei,rcej
c ##A17,10##
c ##A5,42##
      integer i0,j0,nbod0,i2,j2
c ##A5,42##
c ##A22,8##
      integer year, month
      real*8 t1,tempo
      character*42 flost
      character*6 tstring
c ##A22,8##
c ##E18,1##
      integer stat2(nbod)
c ##E18,1##
c
c------------------------------------------------------------------------------
c
      nhit = 0
      thit1 = sign(HUGE, h)
      hm1 = 1.d0 / h
c ##A22,56##
      nelim = 0
c ##A22,56##
c ##E18,2##
      do j = 1, nbod
        stat2(j) = 0
      end do
c ##E18,2##
c
c Calculate maximum and minimum values of x and y coords for each object
      call mce_box (nbod,h,x0,v0,x1,v1,xmin,xmax,ymin,ymax)
c
c Adjust values by the maximum close-encounter radius plus a fudge factor
      do j = 2, nbod
        temp = rce(j) * 1.2d0
        xmin(j) = xmin(j)  -  temp
        xmax(j) = xmax(j)  +  temp
        ymin(j) = ymin(j)  -  temp
        ymax(j) = ymax(j)  +  temp
      end do
c
c ##A17,11##
c      if (opti(20).eq.1) then
c        call mce_hill (nbod,m,x0,v0,hill,a)
c      end if
c ##A17,11##
c
c Check for close encounters between each pair of objects
      do i = 2, nbig
        do j = i + 1, nbod
c ##E18,3##
c          if (   xmax(i).ge.xmin(j).and.xmax(j).ge.xmin(i)
c     %      .and.ymax(i).ge.ymin(j).and.ymax(j).ge.ymin(i)
c     %      .and.stat(i).ge.0.and.stat(j).ge.0) then
          if (   xmax(i).ge.xmin(j).and.xmax(j).ge.xmin(i)
     %      .and.ymax(i).ge.ymin(j).and.ymax(j).ge.ymin(i)
     %      .and.(stat(i).ge.0.and.stat(j).ge.0)
     %      .and.(stat2(i).ge.0.and.stat2(j).ge.0)) then
c ##E18,3##
c
c If the X-Y boxes for this pair overlap, check circumstances more closely
            dx0 = x0(1,i) - x0(1,j)
            dy0 = x0(2,i) - x0(2,j)
            dz0 = x0(3,i) - x0(3,j)
            du0 = v0(1,i) - v0(1,j)
            dv0 = v0(2,i) - v0(2,j)
            dw0 = v0(3,i) - v0(3,j)
            d0t = (dx0*du0 + dy0*dv0 + dz0*dw0) * 2.d0
c
            dx1 = x1(1,i) - x1(1,j)
            dy1 = x1(2,i) - x1(2,j)
            dz1 = x1(3,i) - x1(3,j)
            du1 = v1(1,i) - v1(1,j)
            dv1 = v1(2,i) - v1(2,j)
            dw1 = v1(3,i) - v1(3,j)
            d1t = (dx1*du1 + dy1*dv1 + dz1*dw1) * 2.d0
c
c Estimate minimum separation during the time interval, using interpolation
            d0 = dx0*dx0 + dy0*dy0 + dz0*dz0
            d1 = dx1*dx1 + dy1*dy1 + dz1*dz1
            call mce_min (d0,d1,d0t,d1t,h,d2min,tmin)
            d2ce  = max (rce(i), rce(j))
c ##A17,12##
c            if (opti(20).eq.1) then
c              rcei = rce(i) / hill(i)
c              rcej = rce(j) / hill(j)
c              d2ce = max (rcei, rcej)
c            end if
c ##A17,12##
            d2hit = rphys(i) + rphys(j)
            d2ce   = d2ce  * d2ce
            d2hit  = d2hit * d2hit
            d2near = d2hit * 4.d0
c ##A5,43##
            if (iflag.eq.0) then
              i0 = i
              j0 = j
              nbod0 = nbod
            else if (iflag.eq.1) then
              i0 = index(i)
              j0 = index(j)
              nbod0 = nbod2
            end if
c ##A5,43##
c ##A22,57##
            tempo = time + tmin
c ##A22,57##
c
c If the minimum separation qualifies as an encounter or if a collision
c is in progress, store details
c ##A5,44##
c            if ((d2min.le.d2ce.and.d0t*h.le.0.and.d1t*h.ge.0)
c     %        .or.(d2min.le.d2hit)) then
            if (((d2min.le.d2ce.and.d0t*h.le.0.and.d1t*h.ge.0)
     %        .and.((i0.ge.opti(4).and.i0.le.opti(5))
     %        .or.(j0.ge.opti(4).and.j0.le.opti(5))))
     %        .or.(d2min.le.d2hit)) then
c ##A5,44##
              nclo = nclo + 1
              if (nclo.gt.CMAX) then
c ##E9,9##
c 230            open (23,file=outfile,status='old',access='append',
c     %            err=230)
c ##E9,9##
                write (23,'(/,2a,/,a)') mem(121)(1:lmem(121)),
     %            mem(132)(1:lmem(132)),mem(82)(1:lmem(82))
c ##E9,10##
c                close (23)
c ##E9,10##
c ##A12,18##
                write (*,'(/,2a,/,a)') mem(121)(1:lmem(121)),
     %            mem(132)(1:lmem(132)),mem(82)(1:lmem(82))
c ##A12,18##
              else
c ##A5,45##
c ##A22,9##
                if (opti(26).eq.1.and.((i0.ge.opti(29).and.i0
     %            .le.opti(30)).or.(j0.ge.opti(29).and.j0
     %            .le.opti(30)))) then
                  if (d2min.le.d2hit) then
                    aux(nclo) = 'c'
                  else
                    nelim = nelim + 1
                    aux(nclo) = 'f'
                    if (i0.ge.opti(29).and.i0.le.opti(30)) then
                      stat(j) = -4
c Check for Prune Ejections
                      opti(15) = opti(15) - 1
                      opti(17) = opti(17) + 1
                      if (opt.eq.1) then
                        call mio_jd2y (tempo,year,month,t1)
                        flost(1:30) = '(1x,2(a8,a),i10,1x,i2,1x,f8.5,'
                        flost(31:42) = '3x,4(1x,i7))'
                        write (23,flost) id(j),mem(70)(1:lmem(70)),
     %                    id(i),mem(71)(1:lmem(71)),year,month,t1,
     %                    opti(15),opti(16),opti(17),opti(18)
                      else
                        if (opt.eq.3) then
                          t1 = (tempo - tstart) / 365.25d0
                          tstring = mem(2)
                          flost = '(1x,2(a8,a),f18.7,a,3x,4(1x,i7))'
                        else
                          if (opt.eq.0) t1 = tempo
                          if (opt.eq.2) t1 = tempo - tstart
                          tstring = mem(1)
                          flost = '(1x,2(a8,a),f18.5,a,3x,4(1x,i7))'
                        end if
                        write (23,flost) id(j),mem(70)(1:lmem(70)),
     %                    id(i),mem(71)(1:lmem(71)),t1,tstring,
     %                    opti(15),opti(16),opti(17),opti(18)
                      end if
                    else if (j0.ge.opti(29).and.j0.le.opti(30)) then
                      stat(i) = -4
c Check for Prune Ejections
                      opti(15) = opti(15) - 1
                      opti(17) = opti(17) + 1
                      if (opt.eq.1) then
                        call mio_jd2y (tempo,year,month,t1)
                        flost(1:30) = '(1x,2(a8,a),i10,1x,i2,1x,f8.5,'
                        flost(31:42) = '3x,4(1x,i7))'
                        write (23,flost) id(i),mem(70)(1:lmem(70)),
     %                    id(j),mem(71)(1:lmem(71)),year,month,t1,
     %                    opti(15),opti(16),opti(17),opti(18)
                      else
                        if (opt.eq.3) then
                          t1 = (tempo - tstart) / 365.25d0
                          tstring = mem(2)
                          flost = '(1x,2(a8,a),f18.7,a,3x,4(1x,i7))'
                        else
                          if (opt.eq.0) t1 = tempo
                          if (opt.eq.2) t1 = tempo - tstart
                          tstring = mem(1)
                          flost = '(1x,2(a8,a),f18.5,a,3x,4(1x,i7))'
                        end if
                        write (23,flost) id(i),mem(70)(1:lmem(70)),
     %                    id(j),mem(71)(1:lmem(71)),t1,tstring,
     %                    opti(15),opti(16),opti(17),opti(18)
                      end if
                    end if
                  end if
c ##E14,3##
                  tcol = time + tmin
c ##E14,3##
c
c                else if (opti(25).eq.1.and.((i0.lt.opti(27)
c     %            .or.i0.gt.opti(28)).and.(j0.lt.opti(27).or.j0
c     %            .gt.opti(28)))) then
                else if (opti(25).eq.1.and.((i0.ge.opti(27)
     %            .or.i0.le.opti(28)).and.(j0.ge.opti(27).or.j0
     %            .le.opti(28)))) then
                  aux(nclo) = 'd'
                  nhit = nhit + 1
                  ihit(nhit) = i
                  jhit(nhit) = j
                  thit(nhit) = tmin + time
                  dhit(nhit) = sqrt(d2min)
                  chit(nhit) = 2
c Make sure the more massive body is listed first
                  if (m(jhit(nhit)).gt.m(ihit(nhit)).and.j.le.nbig) then
                    ihit(nhit) = j
                    jhit(nhit) = i
                  end if
c ##E18,5##
                  stat2(jhit(nhit)) = -1
c ##E18,5##
                  if (d2min.le.d2hit) then
c ##E18,6##
                    stat2(jhit(nhit)) = 0
c ##E18,6##
                    nhit = nhit - 1
                    aux(nclo) = 'c'
                  end if
c ##E14,4##
                  tcol = time + tmin
c ##E14,4##
c
c ##A22,9##
                else if (d2min.le.d2hit) then
                  aux(nclo) = 'c'
c ##E14,5##
                  tcol = time + tmin
c ##E14,5##
c
                else
                  aux(nclo) = 'b'
                end if
c
                call bcloo (nbclo,bclo,i0,nbod0,i2,flagce)
                call bcloo (nbclo,bclo,j0,nbod0,j2,flagce)
c ##A5,45##
                tclo(nclo) = tmin + time
                dclo(nclo) = sqrt (max(0.d0,d2min))
c ##A5,46##
c                iclo(nclo) = i
c                jclo(nclo) = j
                iclo(nclo) = i2
                jclo(nclo) = j2
c ##A5,46##
c
c Make sure the more massive body is listed first
                if (m(j).gt.m(i).and.j.le.nbig) then
c ##A5,47##
c                  iclo(nclo) = j
c                  jclo(nclo) = i
                  iclo(nclo) = j2
                  jclo(nclo) = i2
c ##A5,47##
                end if
c
c Make linear interpolation to get coordinates at time of closest approach
                tmp0 = 1.d0 + tmin*hm1
                tmp1 = -tmin*hm1
                ixvclo(1,nclo) = tmp0 * x0(1,i)  +  tmp1 * x1(1,i)
                ixvclo(2,nclo) = tmp0 * x0(2,i)  +  tmp1 * x1(2,i)
                ixvclo(3,nclo) = tmp0 * x0(3,i)  +  tmp1 * x1(3,i)
                ixvclo(4,nclo) = tmp0 * v0(1,i)  +  tmp1 * v1(1,i)
                ixvclo(5,nclo) = tmp0 * v0(2,i)  +  tmp1 * v1(2,i)
                ixvclo(6,nclo) = tmp0 * v0(3,i)  +  tmp1 * v1(3,i)
                jxvclo(1,nclo) = tmp0 * x0(1,j)  +  tmp1 * x1(1,j)
                jxvclo(2,nclo) = tmp0 * x0(2,j)  +  tmp1 * x1(2,j)
                jxvclo(3,nclo) = tmp0 * x0(3,j)  +  tmp1 * x1(3,j)
                jxvclo(4,nclo) = tmp0 * v0(1,j)  +  tmp1 * v1(1,j)
                jxvclo(5,nclo) = tmp0 * v0(2,j)  +  tmp1 * v1(2,j)
                jxvclo(6,nclo) = tmp0 * v0(3,j)  +  tmp1 * v1(3,j)
              end if
            end if
c
c Check for a near miss or collision
c ##A22,10##
c            if (d2min.le.d2near) then
c            if ((d2min.le.d2near.and.((opti(25).eq.0.or.((i0.ge.opti(27)
c     %        .and.i0.le.opti(28)).or.(j0.ge.opti(27).and.j0
c     %        .le.opti(28)))).and.(opti(26).eq.0.or.((i0.lt.opti(29)
c     %        .or.i0.gt.opti(30)).and.(j0.lt.opti(29).or.j0
c     %        .gt.opti(30)))))).or.d2min.le.d2hit) then
            if ((d2min.le.d2near.and.((opti(25).eq.0.or.((i0.lt.opti(27)
     %        .and.i0.gt.opti(28)).or.(j0.lt.opti(27).and.j0
     %        .gt.opti(28)))).and.(opti(26).eq.0.or.((i0.lt.opti(29)
     %        .or.i0.gt.opti(30)).and.(j0.lt.opti(29).or.j0
     %        .gt.opti(30)))))).or.d2min.le.d2hit) then
c ##A22,10##
              nhit = nhit + 1
              ihit(nhit) = i
              jhit(nhit) = j
              thit(nhit) = tmin + time
              dhit(nhit) = sqrt(d2min)
              chit(nhit) = -1
              if (d2min.le.d2hit) chit(nhit) = 1
c
c Make sure the more massive body is listed first
              if (m(jhit(nhit)).gt.m(ihit(nhit)).and.j.le.nbig) then
                ihit(nhit) = j
                jhit(nhit) = i
              end if
c ##E18,4##
              if (chit(nhit).gt.0) stat2(jhit(nhit)) = -1
c ##E18,4##
c
c Is this the collision closest to the start of the time step?
              if ((tmin-thit1)*h.lt.0) then
                thit1 = tmin
                nowflag = 0
                if (d1.le.d2hit) nowflag = 1
              end if
            end if
          end if
c
c Move on to the next pair of objects
        end do
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_ACSH.FOR    (ErikSoft  2 March 1999)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates inverse hyperbolic cosine of an angle X (in radians).
c
c------------------------------------------------------------------------------
c
      function mco_acsh (x)
c
      implicit none
c
c Input/Output
      real*8 x,mco_acsh
c
c------------------------------------------------------------------------------
c
      if (x.ge.1.d0) then
        mco_acsh = log (x + sqrt(x*x - 1.d0))
      else
        mco_acsh = 0.d0
c ##E12,11##
c        write (*,*) 'INPUT: ',x
c
c dcarrera 2015-02-03 Write an error in info.out when the input is invalid.
c
c        call mio_err (6,' ',1,'ERROR: ',7,
c     %  'Domain error. Input to mco_acsh was less than 1.',49,' ',1)
c ##E12,11##
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_B2H.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Converts barycentric coordinates to coordinates with respect to the central
c body.
c
c------------------------------------------------------------------------------
c
      subroutine mco_b2h (time,jcen,nbod,nbig,h,m,x,v,xh,vh,ngf,ngflag,
     %  opt)
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod),ngf(4,nbod)
c
c Local
      integer j
c
c------------------------------------------------------------------------------
c
      do j = 2, nbod
        xh(1,j) = x(1,j) - x(1,1)
        xh(2,j) = x(2,j) - x(2,1)
        xh(3,j) = x(3,j) - x(3,1)
        vh(1,j) = v(1,j) - v(1,1)
        vh(2,j) = v(2,j) - v(2,1)
        vh(3,j) = v(3,j) - v(3,1)
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_CB2H.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Converts close-binary coordinates to coordinates with respect to the central
c body.
c
c------------------------------------------------------------------------------
c
c ##A38,64##
      subroutine mco_cb2h (time,jcen,nbod,nbig,h,m,x,v,xh,vh,ngf,ngflag,
     %  opt,optr,opti,K2,AU,MSUN)
c ##A38,64##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod),ngf(4,nbod)
c ##A38,65##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,65##
c
c Local
      integer j
      real*8 mvsum(3),temp,mbin,mbin_1,mcen_1
c
c------------------------------------------------------------------------------
c
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      mbin = m(1) + m(2)
      mcen_1 = 1.d0 / m(1)
      mbin_1 = 1.d0 / mbin
c
      xh(1,2) = x(1,2)
      xh(2,2) = x(2,2)
      xh(3,2) = x(3,2)
      temp = mbin * mcen_1
      vh(1,2) = temp * v(1,2)
      vh(2,2) = temp * v(2,2)
      vh(3,2) = temp * v(3,2)
c
      do j = 3, nbod
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
      temp = m(2) * mcen_1
      mvsum(1) = mbin_1 * mvsum(1)  +  temp * v(1,2)
      mvsum(2) = mbin_1 * mvsum(2)  +  temp * v(2,2)
      mvsum(3) = mbin_1 * mvsum(3)  +  temp * v(3,2)
c
      temp = m(2) * mbin_1
      do j = 3, nbod
        xh(1,j) = x(1,j)  +  temp * x(1,2)
        xh(2,j) = x(2,j)  +  temp * x(2,2)
        xh(3,j) = x(3,j)  +  temp * x(3,2)
        vh(1,j) = v(1,j)  +  mvsum(1)
        vh(2,j) = v(2,j)  +  mvsum(2)
        vh(3,j) = v(3,j)  +  mvsum(3)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_DH2H.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Converts democratic heliocentric coordinates to coordinates with respect
c to the central body.
c
c------------------------------------------------------------------------------
c
c ##A38,60##
      subroutine mco_dh2h (time,jcen,nbod,nbig,h,m,x,v,xh,vh,ngf,ngflag,
     %  opt,optr,opti,K2,AU,MSUN)
c ##A38,60##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod),ngf(4,nbod)
c ##A38,61##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,61##
c
c Local
      integer j
      real*8 mvsum(3),temp
c
c------------------------------------------------------------------------------
c
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
c
      do j = 2, nbod
        xh(1,j) = x(1,j)
        xh(2,j) = x(2,j)
        xh(3,j) = x(3,j)
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
c
      temp = 1.d0 / m(1)
      mvsum(1) = temp * mvsum(1)
      mvsum(2) = temp * mvsum(2)
      mvsum(3) = temp * mvsum(3)
c
      do j = 2, nbod
        vh(1,j) = v(1,j) + mvsum(1)
        vh(2,j) = v(2,j) + mvsum(2)
        vh(3,j) = v(3,j) + mvsum(3)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_IDEN.FOR    (ErikSoft   2 November 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Makes a new copy of a set of coordinates.
c
c------------------------------------------------------------------------------
c
c ##A38,31##
      subroutine mco_iden (time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,ngflag,
     %  opt,optr,opti,K2,AU,MSUN)
c ##A38,31##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod),ngf(4,nbod)
c ##A38,32##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,32##
c
c Local
      integer j
c
c------------------------------------------------------------------------------
c
      do j = 1, nbod
        x(1,j) = xh(1,j)
        x(2,j) = xh(2,j)
        x(3,j) = xh(3,j)
        v(1,j) = vh(1,j)
        v(2,j) = vh(2,j)
        v(3,j) = vh(3,j)
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_MVS2H.FOR    (ErikSoft   28 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Applies a symplectic corrector, which converts coordinates for a second-
c order mixed-variable symplectic integrator to ones with respect to the
c central body.
c
c------------------------------------------------------------------------------
c
c ##A38,15##
      subroutine mco_mvs2h (time,jcen,nbod,nbig,h,m,x,v,xh,vh,ngf,
     %  ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,15##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod),ngf(4,nbod)
c ##A38,16##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,16##
c
c Local
      integer j,k,iflag,stat(NMAX)
      real*8 minside,msofar,gm(NMAX),a(3,NMAX),xj(3,NMAX),vj(3,NMAX)
      real*8 ha(2),hb(2),rt10,angf(3,NMAX),ausr(3,NMAX)
c
c------------------------------------------------------------------------------
c
      rt10 = sqrt(10.d0)
      ha(1) =  h * rt10 * 3.d0 / 10.d0
      hb(1) = -h * rt10 / 72.d0
      ha(2) =  h * rt10 / 5.d0
      hb(2) =  h * rt10 / 24.d0
      do j = 2, nbod
        angf(1,j) = 0.d0
        angf(2,j) = 0.d0
        angf(3,j) = 0.d0
        ausr(1,j) = 0.d0
        ausr(2,j) = 0.d0
        ausr(3,j) = 0.d0
      end do
c ##A38,33##
      call mco_iden (time,jcen,nbod,nbig,h,m,x,v,xh,vh,ngf,ngflag,opt,
     %  optr,opti,K2,AU,MSUN)
c ##A38,33##
c
c Calculate effective central masses for Kepler drifts
      minside = m(1)
      do j = 2, nbig
        msofar = minside + m(j)
        gm(j) = m(1) * msofar / minside
        minside = msofar
      end do
c
c Two step corrector
      do k = 1, 2
c
c Advance Keplerian Hamiltonian (Jacobi/helio coords for Big/Small bodies)
        call mco_h2j(time,jcen,nbig,nbig,h,m,xh,vh,xj,vj,ngf,ngflag,opt)
        do j = 2, nbig
          iflag = 0
          call drift_one (gm(j),xj(1,j),xj(2,j),xj(3,j),vj(1,j),
     %      vj(2,j),vj(3,j),ha(k),iflag)
        end do
        do j = nbig + 1, nbod
          iflag = 0
          call drift_one (m(1),xh(1,j),xh(2,j),xh(3,j),vh(1,j),vh(2,j),
     %      vh(3,j),ha(k),iflag)
        end do
c
c Advance Interaction Hamiltonian
        call mco_j2h(time,jcen,nbig,nbig,h,m,xj,vj,xh,vh,ngf,ngflag,opt)
        call mfo_mvs (jcen,nbod,nbig,m,xh,xj,a,stat)
c
c If required, apply non-gravitational and user-defined forces
c ##A38,6##
        if (opt(8).eq.1) call mfo_user (time,jcen,nbod,nbig,m,xh,vh,
     %    ausr,opt,optr,ngf,opti,K2,AU,MSUN)
c ##A38,6##
        if (ngflag.eq.1.or.ngflag.eq.3) call mfo_ngf (nbod,xh,vh,angf,
     %    ngf)
c
        do j = 2, nbod
          vh(1,j) = vh(1,j)  -  hb(k) * (angf(1,j) + ausr(1,j) + a(1,j))
          vh(2,j) = vh(2,j)  -  hb(k) * (angf(2,j) + ausr(2,j) + a(2,j))
          vh(3,j) = vh(3,j)  -  hb(k) * (angf(3,j) + ausr(3,j) + a(3,j))
        end do
c
c Advance Keplerian Hamiltonian (Jacobi/helio coords for Big/Small bodies)
        call mco_h2j(time,jcen,nbig,nbig,h,m,xh,vh,xj,vj,ngf,ngflag,opt)
        do j = 2, nbig
          iflag = 0
          call drift_one (gm(j),xj(1,j),xj(2,j),xj(3,j),vj(1,j),
     %      vj(2,j),vj(3,j),-2.d0*ha(k),iflag)
        end do
        do j = nbig + 1, nbod
          iflag = 0
         call drift_one (m(1),xh(1,j),xh(2,j),xh(3,j),vh(1,j),vh(2,j),
     %     vh(3,j),-2.d0*ha(k),iflag)
        end do
c
c Advance Interaction Hamiltonian
        call mco_j2h(time,jcen,nbig,nbig,h,m,xj,vj,xh,vh,ngf,ngflag,opt)
        call mfo_mvs (jcen,nbod,nbig,m,xh,xj,a,stat)
c
c If required, apply non-gravitational and user-defined forces
c ##A38,7##
        if (opt(8).eq.1) call mfo_user (time,jcen,nbod,nbig,m,xh,vh,
     %    ausr,opt,optr,ngf,opti,K2,AU,MSUN)
c ##A38,7##
        if (ngflag.eq.1.or.ngflag.eq.3) call mfo_ngf (nbod,xh,vh,angf,
     %    ngf)
c
        do j = 2, nbod
          vh(1,j) = vh(1,j)  +  hb(k) * (angf(1,j) + ausr(1,j) + a(1,j))
          vh(2,j) = vh(2,j)  +  hb(k) * (angf(2,j) + ausr(2,j) + a(2,j))
          vh(3,j) = vh(3,j)  +  hb(k) * (angf(3,j) + ausr(3,j) + a(3,j))
        end do
c
c Advance Keplerian Hamiltonian (Jacobi/helio coords for Big/Small bodies)
        call mco_h2j(time,jcen,nbig,nbig,h,m,xh,vh,xj,vj,ngf,ngflag,opt)
        do j = 2, nbig
          iflag = 0
          call drift_one (gm(j),xj(1,j),xj(2,j),xj(3,j),vj(1,j),
     %      vj(2,j),vj(3,j),ha(k),iflag)
        end do
        do j = nbig + 1, nbod
          iflag = 0
          call drift_one (m(1),xh(1,j),xh(2,j),xh(3,j),vh(1,j),vh(2,j),
     %      vh(3,j),ha(k),iflag)
        end do
        call mco_j2h(time,jcen,nbig,nbig,h,m,xj,vj,xh,vh,ngf,ngflag,opt)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_UB2H.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 22 January 2015)
c
c Converts user coordinates for close binary systems to coordinates with
c respect to the central body.
c
c------------------------------------------------------------------------------
c
c ##A18,2##
      subroutine mco_ub2h (algor,time,jcen,nbod,nbig,h,m,x,v,xh,vh,ngf,
     %  ngflag,opt)
c ##A18,2##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod),ngf(4,nbod)
c ##A18,3##
      integer algor
c ##A18,3##
c
c Local
      integer j
      real*8 temp
c ##A18,4##
      integer i0
      real*8 msum,mbin,mbin_1,temp2
      real*8 mxsum(3),mxsum2(3),mvsum(3),mvsum2(3)
c ##A18,4##
c
c------------------------------------------------------------------------------
c
      temp = m(2) / (m(1) + m(2))
c
c ##A18,5##
      xh(1,2) = x(1,2) + temp * x(1,2)
      xh(2,2) = x(2,2) + temp * x(2,2)
      xh(3,2) = x(3,2) + temp * x(3,2)
      vh(1,2) = v(1,2) + temp * v(1,2)
      vh(2,2) = v(2,2) + temp * v(2,2)
      vh(3,2) = v(3,2) + temp * v(3,2)
c
      if (algor.eq.11.or.algor.eq.12) i0 = 3
      if (algor.eq.5) i0 = 4
c
      msum = 0.d0
      mxsum(1) = 0.d0
      mxsum(2) = 0.d0
      mxsum(3) = 0.d0
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      mbin = m(1) + m(2)
      mbin_1 = 1.d0 / mbin
c
      do j = i0, nbod
        msum = msum + m(j)
        mxsum(1) = mxsum(1)  +  m(j) * x(1,j)
        mxsum(2) = mxsum(2)  +  m(j) * x(2,j)
        mxsum(3) = mxsum(3)  +  m(j) * x(3,j)
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
c
      temp2 = 1.d0 / (msum + mbin)
c
      mxsum2(1) = temp2 * (mxsum(1) + m(2) * x(1,2))
      mxsum2(2) = temp2 * (mxsum(2) + m(2) * x(2,2))
      mxsum2(3) = temp2 * (mxsum(3) + m(2) * x(3,2))
      mvsum2(1) = temp2 * (mvsum(1) + m(2) * v(1,2))
      mvsum2(2) = temp2 * (mvsum(2) + m(2) * v(2,2))
      mvsum2(3) = temp2 * (mvsum(3) + m(2) * v(3,2))
c
      xh(1,3) = x(1,3)  +  mxsum2(1)
      xh(2,3) = x(2,3)  +  mxsum2(2)
      xh(3,3) = x(3,3)  +  mxsum2(3)
      vh(1,3) = v(1,3)  +  mvsum2(1)
      vh(2,3) = v(2,3)  +  mvsum2(2)
      vh(3,3) = v(3,3)  +  mvsum2(3)
c
      if (algor.eq.12) then
        i0 = nbod + 1
        temp = 1.d0 / (msum + m(1))
        xh(1,2) = x(1,2)  +  temp * mxsum(1)
        xh(2,2) = x(2,2)  +  temp * mxsum(2)
        xh(3,2) = x(3,2)  +  temp * mxsum(3)
        vh(1,2) = v(1,2)  +  temp * mvsum(1)
        vh(2,2) = v(2,2)  +  temp * mvsum(2)
        vh(3,2) = v(3,2)  +  temp * mvsum(3)
      end if
c
      do j = i0, nbod
c ##A18,5##
        xh(1,j) = x(1,j)  +  temp * x(1,2)
        xh(2,j) = x(2,j)  +  temp * x(2,2)
        xh(3,j) = x(3,j)  +  temp * x(3,2)
        vh(1,j) = v(1,j)  +  temp * v(1,2)
        vh(2,j) = v(2,j)  +  temp * v(2,2)
        vh(3,j) = v(3,j)  +  temp * v(3,2)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_WB2H.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Converts wide-binary coordinates to coordinates with respect to the central
c body.
c
c------------------------------------------------------------------------------
c
c ##A38,69##
      subroutine mco_wb2h (time,jcen,nbod,nbig,h,m,x,v,xh,vh,ngf,ngflag,
     %  opt,optr,opti,K2,AU,MSUN)
c ##A38,69##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod),ngf(4,nbod)
c ##A38,70##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,70##
c
c Local
      integer j
      real*8 msum,mvsum(3),mxsum(3),temp,tmp2,tmp3
c
c------------------------------------------------------------------------------
c
      mxsum(1) = 0.d0
      mxsum(2) = 0.d0
      mxsum(3) = 0.d0
      msum = 0.d0
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
c
      do j = 3, nbod
        xh(1,j) = x(1,j)
        xh(2,j) = x(2,j)
        xh(3,j) = x(3,j)
        mxsum(1) = mxsum(1)  +  m(j) * x(1,j)
        mxsum(2) = mxsum(2)  +  m(j) * x(2,j)
        mxsum(3) = mxsum(3)  +  m(j) * x(3,j)
        msum = msum + m(j)
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
c
      temp = 1.d0 / (msum + m(1))
      tmp2 = 1.d0 / m(1)
      tmp3 = (m(1) + msum + m(2)) * temp
c
      xh(1,2) = x(1,2)  +  temp * mxsum(1)
      xh(2,2) = x(2,2)  +  temp * mxsum(2)
      xh(3,2) = x(3,2)  +  temp * mxsum(3)
      vh(1,2) = tmp3 * v(1,2)  +  tmp2 * mvsum(1)
      vh(2,2) = tmp3 * v(2,2)  +  tmp2 * mvsum(2)
      vh(3,2) = tmp3 * v(3,2)  +  tmp2 * mvsum(3)
c
      mvsum(1) = mvsum(1) * tmp2
      mvsum(2) = mvsum(2) * tmp2
      mvsum(3) = mvsum(3) * tmp2
      do j = 3, nbod
        vh(1,j) = v(1,j) + mvsum(1)
        vh(2,j) = v(2,j) + mvsum(2)
        vh(3,j) = v(3,j) + mvsum(3)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_EL2X.FOR    (ErikSoft  7 July 1999)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates Cartesian coordinates and velocities given Keplerian orbital
c elements (for elliptical, parabolic or hyperbolic orbits).
c
c Based on a routine from Levison and Duncan's SWIFT integrator.
c
c  gm = grav const * (central + secondary mass)
c  q = perihelion distance
c  e = eccentricity
c  i = inclination                 )
c  p = longitude of perihelion !!! )   in
c  n = longitude of ascending node ) radians
c  l = mean anomaly                )
c
c  x,y,z = Cartesian positions  ( units the same as a )
c  u,v,w =     "     velocities ( units the same as sqrt(gm/a) )
c
c------------------------------------------------------------------------------
c
      subroutine mco_el2x (gm,q,e,i,p,n,l,x,y,z,u,v,w)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      real*8 gm,q,e,i,p,n,l,x,y,z,u,v,w
c
c Local
      real*8 g,a,ci,si,cn,sn,cg,sg,ce,se,romes,temp
      real*8 z1,z2,z3,z4,d11,d12,d13,d21,d22,d23
      real*8 mco_kep, orbel_fhybrid, orbel_zget
c
c------------------------------------------------------------------------------
c
c Change from longitude of perihelion to argument of perihelion
      g = p - n
c
c Rotation factors
      call mco_sine (i,si,ci)
      call mco_sine (g,sg,cg)
      call mco_sine (n,sn,cn)
      z1 = cg * cn
      z2 = cg * sn
      z3 = sg * cn
      z4 = sg * sn
      d11 =  z1 - z4*ci
      d12 =  z2 + z3*ci
      d13 = sg * si
      d21 = -z3 - z2*ci
      d22 = -z4 + z1*ci
      d23 = cg * si
c
c Semi-major axis
      a = q / (1.d0 - e)
c
c Ellipse
      if (e.lt.1.d0) then
        romes = sqrt(1.d0 - e*e)
        temp = mco_kep (e,l)
        call mco_sine (temp,se,ce)
        z1 = a * (ce - e)
        z2 = a * romes * se
        temp = sqrt(gm/a) / (1.d0 - e*ce)
        z3 = -se * temp
        z4 = romes * ce * temp
      else
c Parabola
        if (e.eq.1.d0) then
          ce = orbel_zget(l)
          z1 = q * (1.d0 - ce*ce)
          z2 = 2.d0 * q * ce
          z4 = sqrt(2.d0*gm/q) / (1.d0 + ce*ce)
          z3 = -ce * z4
        else
c Hyperbola
          romes = sqrt(e*e - 1.d0)
          temp = orbel_fhybrid(e,l)
          call mco_sinh (temp,se,ce)
          z1 = a * (ce - e)
          z2 = -a * romes * se
          temp = sqrt(gm/abs(a)) / (e*ce - 1.d0)
          z3 = -se * temp
          z4 = romes * ce * temp
        end if
      endif
c
      x = d11 * z1  +  d21 * z2
      y = d12 * z1  +  d22 * z2
      z = d13 * z1  +  d23 * z2
      u = d11 * z3  +  d21 * z4
      v = d12 * z3  +  d22 * z4
      w = d13 * z3  +  d23 * z4
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_H2B.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Converts coordinates with respect to the central body to barycentric
c coordinates.
c
c------------------------------------------------------------------------------
c
      subroutine mco_h2b (time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,ngflag,
     %  opt)
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),xh(3,nbod),vh(3,nbod),x(3,nbod)
      real*8 v(3,nbod),ngf(4,nbod)
c
c Local
      integer j
      real*8 mtot,temp
c
c------------------------------------------------------------------------------
c
      mtot = 0.d0
      x(1,1) = 0.d0
      x(2,1) = 0.d0
      x(3,1) = 0.d0
      v(1,1) = 0.d0
      v(2,1) = 0.d0
      v(3,1) = 0.d0
c
c Calculate coordinates and velocities of the central body
      do j = 2, nbod
        mtot = mtot  +  m(j)
        x(1,1) = x(1,1)  +  m(j) * xh(1,j)
        x(2,1) = x(2,1)  +  m(j) * xh(2,j)
        x(3,1) = x(3,1)  +  m(j) * xh(3,j)
        v(1,1) = v(1,1)  +  m(j) * vh(1,j)
        v(2,1) = v(2,1)  +  m(j) * vh(2,j)
        v(3,1) = v(3,1)  +  m(j) * vh(3,j)
      enddo
c
      temp = -1.d0 / (mtot + m(1))
      x(1,1) = temp * x(1,1)
      x(2,1) = temp * x(2,1)
      x(3,1) = temp * x(3,1)
      v(1,1) = temp * v(1,1)
      v(2,1) = temp * v(2,1)
      v(3,1) = temp * v(3,1)
c
c Calculate the barycentric coordinates and velocities
      do j = 2, nbod
        x(1,j) = xh(1,j) + x(1,1)
        x(2,j) = xh(2,j) + x(2,1)
        x(3,j) = xh(3,j) + x(3,1)
        v(1,j) = vh(1,j) + v(1,1)
        v(2,j) = vh(2,j) + v(2,1)
        v(3,j) = vh(3,j) + v(3,1)
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_H2MVS.FOR    (ErikSoft   28 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Applies an inverse symplectic corrector, which converts coordinates with
c respect to the central body to integrator coordinates for a second-order
c mixed-variable symplectic integrator.
c
c------------------------------------------------------------------------------
c
c ##A38,17##
      subroutine mco_h2mvs (time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,
     %  ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,17##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),xh(3,nbod),vh(3,nbod),x(3,nbod)
      real*8 v(3,nbod),ngf(4,nbod)
c ##A38,18##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,18##
c
c Local
      integer j,k,iflag,stat(NMAX)
      real*8 minside,msofar,gm(NMAX),a(3,NMAX),xj(3,NMAX),vj(3,NMAX)
      real*8 ha(2),hb(2),rt10,angf(3,NMAX),ausr(3,NMAX)
c
c------------------------------------------------------------------------------
c
      rt10 = sqrt(10.d0)
      ha(1) = -h * rt10 / 5.d0
      hb(1) = -h * rt10 / 24.d0
      ha(2) = -h * rt10 * 3.d0 / 10.d0
      hb(2) =  h * rt10 / 72.d0
      do j = 2, nbod
        angf(1,j) = 0.d0
        angf(2,j) = 0.d0
        angf(3,j) = 0.d0
        ausr(1,j) = 0.d0
        ausr(2,j) = 0.d0
        ausr(3,j) = 0.d0
      end do
c ##A38,34##
      call mco_iden (time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,ngflag,opt,
     %  optr,opti,K2,AU,MSUN)
c ##A38,34##
c
c Calculate effective central masses for Kepler drifts
      minside = m(1)
      do j = 2, nbig
        msofar = minside + m(j)
        gm(j) = m(1) * msofar / minside
        minside = msofar
      end do
c
      do k = 1, 2
c
c Advance Keplerian Hamiltonian (Jacobi/helio coords for Big/Small bodies)
        call mco_h2j (time,jcen,nbig,nbig,h,m,x,v,xj,vj,ngf,ngflag,opt)
        do j = 2, nbig
          iflag = 0
          call drift_one (gm(j),xj(1,j),xj(2,j),xj(3,j),vj(1,j),
     %      vj(2,j),vj(3,j),ha(k),iflag)
        end do
        do j = nbig + 1, nbod
          iflag = 0
          call drift_one (m(1),x(1,j),x(2,j),x(3,j),v(1,j),v(2,j),
     %      v(3,j),ha(k),iflag)
        end do
c
c Advance Interaction Hamiltonian
        call mco_j2h (time,jcen,nbig,nbig,h,m,xj,vj,x,v,ngf,ngflag,opt)
        call mfo_mvs (jcen,nbod,nbig,m,x,xj,a,stat)
c
c If required, apply non-gravitational and user-defined forces
c ##A38,8##
        if (opt(8).eq.1) call mfo_user (time,jcen,nbod,nbig,m,x,v,ausr,
     %    opt,optr,ngf,opti,K2,AU,MSUN)
c ##A38,8##
        if (ngflag.eq.1.or.ngflag.eq.3) call mfo_ngf (nbod,x,v,angf,ngf)
c
        do j = 2, nbod
          v(1,j) = v(1,j)  +  hb(k) * (angf(1,j) + ausr(1,j) + a(1,j))
          v(2,j) = v(2,j)  +  hb(k) * (angf(2,j) + ausr(2,j) + a(2,j))
          v(3,j) = v(3,j)  +  hb(k) * (angf(3,j) + ausr(3,j) + a(3,j))
        end do
c
c Advance Keplerian Hamiltonian (Jacobi/helio coords for Big/Small bodies)
        call mco_h2j (time,jcen,nbig,nbig,h,m,x,v,xj,vj,ngf,ngflag,opt)
        do j = 2, nbig
          iflag = 0
          call drift_one (gm(j),xj(1,j),xj(2,j),xj(3,j),vj(1,j),
     %      vj(2,j),vj(3,j),-2.d0*ha(k),iflag)
        end do
        do j = nbig + 1, nbod
          iflag = 0
          call drift_one (m(1),x(1,j),x(2,j),x(3,j),v(1,j),v(2,j),
     %      v(3,j),-2.d0*ha(k),iflag)
        end do
c
c Advance Interaction Hamiltonian
        call mco_j2h (time,jcen,nbig,nbig,h,m,xj,vj,x,v,ngf,ngflag,opt)
        call mfo_mvs (jcen,nbod,nbig,m,x,xj,a,stat)
c
c If required, apply non-gravitational and user-defined forces
c ##A38,9##
        if (opt(8).eq.1) call mfo_user (time,jcen,nbod,nbig,m,x,v,ausr,
     %    opt,optr,ngf,opti,K2,AU,MSUN)
c ##A38,9##
        if (ngflag.eq.1.or.ngflag.eq.3) call mfo_ngf (nbod,x,v,angf,ngf)
c
        do j = 2, nbod
          v(1,j) = v(1,j)  -  hb(k) * (angf(1,j) + ausr(1,j) + a(1,j))
          v(2,j) = v(2,j)  -  hb(k) * (angf(2,j) + ausr(2,j) + a(2,j))
          v(3,j) = v(3,j)  -  hb(k) * (angf(3,j) + ausr(3,j) + a(3,j))
        end do
c
c Advance Keplerian Hamiltonian (Jacobi/helio coords for Big/Small bodies)
        call mco_h2j (time,jcen,nbig,nbig,h,m,x,v,xj,vj,ngf,ngflag,opt)
        do j = 2, nbig
          iflag = 0
          call drift_one (gm(j),xj(1,j),xj(2,j),xj(3,j),vj(1,j),
     %      vj(2,j),vj(3,j),ha(k),iflag)
        end do
        do j = nbig + 1, nbod
          iflag = 0
          call drift_one (m(1),x(1,j),x(2,j),x(3,j),v(1,j),v(2,j),
     %      v(3,j),ha(k),iflag)
        end do
        call mco_j2h (time,jcen,nbig,nbig,h,m,xj,vj,x,v,ngf,ngflag,opt)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_H2DH.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Convert coordinates with respect to the central body to democratic
c heliocentric coordinates.
c
c------------------------------------------------------------------------------
c
c ##A38,58##
      subroutine mco_h2dh (time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,ngflag,
     %  opt,optr,opti,K2,AU,MSUN)
c ##A38,58##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),xh(3,nbod),vh(3,nbod),x(3,nbod)
      real*8 v(3,nbod),ngf(4,nbod)
c ##A38,59##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,59##
c
c Local
      integer j
      real*8 mtot,temp,mvsum(3)
c
c------------------------------------------------------------------------------
c
      mtot = 0.d0
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
c
      do j = 2, nbod
        x(1,j) = xh(1,j)
        x(2,j) = xh(2,j)
        x(3,j) = xh(3,j)
        mtot = mtot + m(j)
        mvsum(1) = mvsum(1)  +  m(j) * vh(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * vh(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * vh(3,j)
      end do
c
      temp = 1.d0 / (m(1) + mtot)
c
      mvsum(1) = temp * mvsum(1)
      mvsum(2) = temp * mvsum(2)
      mvsum(3) = temp * mvsum(3)
c
      do j = 2, nbod
        v(1,j) = vh(1,j) - mvsum(1)
        v(2,j) = vh(2,j) - mvsum(2)
        v(3,j) = vh(3,j) - mvsum(3)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_H2CB.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Convert coordinates with respect to the central body to close-binary
c coordinates.
c
c------------------------------------------------------------------------------
c
c ##A38,62##
      subroutine mco_h2cb (time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,ngflag,
     %  opt,optr,opti,K2,AU,MSUN)
c ##A38,62##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),xh(3,nbod),vh(3,nbod),x(3,nbod)
      real*8 v(3,nbod),ngf(4,nbod)
c ##A38,63##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,63##
c
c Local
      integer j
      real*8 msum,mvsum(3),temp,mbin,mbin_1,mtot_1
c
c------------------------------------------------------------------------------
c
      msum = 0.d0
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      mbin = m(1) + m(2)
      mbin_1 = 1.d0 / mbin
c
      x(1,2) = xh(1,2)
      x(2,2) = xh(2,2)
      x(3,2) = xh(3,2)
      temp = m(1) * mbin_1
      v(1,2) = temp * vh(1,2)
      v(2,2) = temp * vh(2,2)
      v(3,2) = temp * vh(3,2)
c
      do j = 3, nbod
        msum = msum + m(j)
        mvsum(1) = mvsum(1)  +  m(j) * vh(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * vh(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * vh(3,j)
      end do
      mtot_1 = 1.d0 / (msum + mbin)
      mvsum(1) = mtot_1 * (mvsum(1) + m(2)*vh(1,2))
      mvsum(2) = mtot_1 * (mvsum(2) + m(2)*vh(2,2))
      mvsum(3) = mtot_1 * (mvsum(3) + m(2)*vh(3,2))
c
      temp = m(2) * mbin_1
      do j = 3, nbod
        x(1,j) = xh(1,j)  -  temp * xh(1,2)
        x(2,j) = xh(2,j)  -  temp * xh(2,2)
        x(3,j) = xh(3,j)  -  temp * xh(3,2)
        v(1,j) = vh(1,j)  -  mvsum(1)
        v(2,j) = vh(2,j)  -  mvsum(2)
        v(3,j) = vh(3,j)  -  mvsum(3)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_H2WB.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Convert coordinates with respect to the central body to wide-binary
c coordinates.
c
c------------------------------------------------------------------------------
c
c ##A38,67##
      subroutine mco_h2wb (time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,ngflag,
     %  opt,optr,opti,K2,AU,MSUN)
c ##A38,67##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),xh(3,nbod),vh(3,nbod),x(3,nbod)
      real*8 v(3,nbod),ngf(4,nbod)
c ##A38,68##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,68##
c
c Local
      integer j
      real*8 msum,mxsum(3),mvsum(3),temp,tmp2,tmp3
c
c------------------------------------------------------------------------------
c
      mxsum(1) = 0.d0
      mxsum(2) = 0.d0
      mxsum(3) = 0.d0
      msum = 0.d0
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
c
      do j = 3, nbod
        x(1,j) = xh(1,j)
        x(2,j) = xh(2,j)
        x(3,j) = xh(3,j)
        mxsum(1) = mxsum(1)  +  m(j) * xh(1,j)
        mxsum(2) = mxsum(2)  +  m(j) * xh(2,j)
        mxsum(3) = mxsum(3)  +  m(j) * xh(3,j)
        msum = msum + m(j)
        mvsum(1) = mvsum(1)  +  m(j) * vh(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * vh(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * vh(3,j)
      end do
c
      temp = 1.d0 / (m(1) + msum)
      tmp3 = 1.d0 / (m(1) + msum + m(2))
      tmp2 = (m(1) + msum) * tmp3
c
      x(1,2) = xh(1,2)  -  temp * mxsum(1)
      x(2,2) = xh(2,2)  -  temp * mxsum(2)
      x(3,2) = xh(3,2)  -  temp * mxsum(3)
      v(1,2) = tmp2 * vh(1,2)  -  tmp3 * mvsum(1)
      v(2,2) = tmp2 * vh(2,2)  -  tmp3 * mvsum(2)
      v(3,2) = tmp2 * vh(3,2)  -  tmp3 * mvsum(3)
c
      mvsum(1) = temp * mvsum(1)
      mvsum(2) = temp * mvsum(2)
      mvsum(3) = temp * mvsum(3)
      do j = 3, nbod
        v(1,j) = vh(1,j) - mvsum(1)
        v(2,j) = vh(2,j) - mvsum(2)
        v(3,j) = vh(3,j) - mvsum(3)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_H2J.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Converts coordinates with respect to the central body to Jacobi coordinates.
c
c N.B. The coordinates respect to the central body for the small bodies
c ===  are assumed to be equal to their Jacobi coordinates.
c
c------------------------------------------------------------------------------
c
      subroutine mco_h2j (time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,ngflag,
     %  opt)
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbig),xh(3,nbig),vh(3,nbig),x(3,nbig)
      real*8 v(3,nbig),ngf(4,nbod)
c
c Local
      integer j
      real*8 mtot, mx, my, mz, mu, mv, mw, temp
c
c------------------------------------------------------------------------------c
      mtot = m(2)
      x(1,2) = xh(1,2)
      x(2,2) = xh(2,2)
      x(3,2) = xh(3,2)
      v(1,2) = vh(1,2)
      v(2,2) = vh(2,2)
      v(3,2) = vh(3,2)
      mx = m(2) * xh(1,2)
      my = m(2) * xh(2,2)
      mz = m(2) * xh(3,2)
      mu = m(2) * vh(1,2)
      mv = m(2) * vh(2,2)
      mw = m(2) * vh(3,2)
c
      do j = 3, nbig - 1
        temp = 1.d0 / (mtot + m(1))
        mtot = mtot + m(j)
        x(1,j) = xh(1,j)  -  temp * mx
        x(2,j) = xh(2,j)  -  temp * my
        x(3,j) = xh(3,j)  -  temp * mz
        v(1,j) = vh(1,j)  -  temp * mu
        v(2,j) = vh(2,j)  -  temp * mv
        v(3,j) = vh(3,j)  -  temp * mw
        mx = mx  +  m(j) * xh(1,j)
        my = my  +  m(j) * xh(2,j)
        mz = mz  +  m(j) * xh(3,j)
        mu = mu  +  m(j) * vh(1,j)
        mv = mv  +  m(j) * vh(2,j)
        mw = mw  +  m(j) * vh(3,j)
      enddo
c
      if (nbig.gt.2) then
        temp = 1.d0 / (mtot + m(1))
        x(1,nbig) = xh(1,nbig)  -  temp * mx
        x(2,nbig) = xh(2,nbig)  -  temp * my
        x(3,nbig) = xh(3,nbig)  -  temp * mz
        v(1,nbig) = vh(1,nbig)  -  temp * mu
        v(2,nbig) = vh(2,nbig)  -  temp * mv
        v(3,nbig) = vh(3,nbig)  -  temp * mw
      end if
c
      do j = nbig + 1, nbod
        x(1,j) = xh(1,j)
        x(2,j) = xh(2,j)
        x(3,j) = xh(3,j)
        v(1,j) = vh(1,j)
        v(2,j) = vh(2,j)
        v(3,j) = vh(3,j)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_H2UB.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 22 January 2015)
c
c Convert coordinates with respect to the central body to user coordinates
c for close-binary systems.
c
c------------------------------------------------------------------------------
c
c ##A18,6##
      subroutine mco_h2ub (algor,time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,
     %  ngflag,opt)
c ##A18,6##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),xh(3,nbod),vh(3,nbod),x(3,nbod)
      real*8 v(3,nbod),ngf(4,nbod)
c ##A18,7##
      integer algor
c ##A18,7##
c
c Local
      integer j
      real*8 temp
c ##A18,8##
      integer i0
      real*8 msum,mbin,mbin_1,temp2
      real*8 mxsum(3),mxsum2(3),mvsum(3),mvsum2(3)
c ##A18,8##
c
c------------------------------------------------------------------------------
c
      temp = m(2) / (m(1) + m(2))
c
c ##A18,9##
      x(1,2) = xh(1,2) - temp * xh(1,2)
      x(2,2) = xh(2,2) - temp * xh(2,2)
      x(3,2) = xh(3,2) - temp * xh(3,2)
      v(1,2) = vh(1,2) - temp * vh(1,2)
      v(2,2) = vh(2,2) - temp * vh(2,2)
      v(3,2) = vh(3,2) - temp * vh(3,2)
c
      if (algor.eq.11.or.algor.eq.12) i0 = 3
      if (algor.eq.5) i0 = 4
c
      msum = 0.d0
      mxsum(1) = 0.d0
      mxsum(2) = 0.d0
      mxsum(3) = 0.d0
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      mbin = m(1) + m(2)
      mbin_1 = 1.d0 / mbin
c
      do j = i0, nbod
        msum = msum + m(j)
        mxsum(1) = mxsum(1)  +  m(j) * xh(1,j)
        mxsum(2) = mxsum(2)  +  m(j) * xh(2,j)
        mxsum(3) = mxsum(3)  +  m(j) * xh(3,j)
        mvsum(1) = mvsum(1)  +  m(j) * vh(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * vh(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * vh(3,j)
      end do
c
      temp2 = 1.d0 / (msum + mbin)
c
      mxsum2(1) = temp2 * (mxsum(1) + m(2) * xh(1,2))
      mxsum2(2) = temp2 * (mxsum(2) + m(2) * xh(2,2))
      mxsum2(3) = temp2 * (mxsum(3) + m(2) * xh(3,2))
      mvsum2(1) = temp2 * (mvsum(1) + m(2) * vh(1,2))
      mvsum2(2) = temp2 * (mvsum(2) + m(2) * vh(2,2))
      mvsum2(3) = temp2 * (mvsum(3) + m(2) * vh(3,2))
c
      x(1,3) = xh(1,3)  -  mxsum2(1)
      x(2,3) = xh(2,3)  -  mxsum2(2)
      x(3,3) = xh(3,3)  -  mxsum2(3)
      v(1,3) = vh(1,3)  -  mvsum2(1)
      v(2,3) = vh(2,3)  -  mvsum2(2)
      v(3,3) = vh(3,3)  -  mvsum2(3)
c
      if (algor.eq.12) then
        i0 = nbod + 1
        temp = 1.d0 / (msum + m(1))
        x(1,2) = xh(1,2)  -  temp * mxsum(1)
        x(2,2) = xh(2,2)  -  temp * mxsum(2)
        x(3,2) = xh(3,2)  -  temp * mxsum(3)
        v(1,2) = vh(1,2)  -  temp * mvsum(1)
        v(2,2) = vh(2,2)  -  temp * mvsum(2)
        v(3,2) = vh(3,2)  -  temp * mvsum(3)
      end if
c
      do j = i0, nbod
c ##A18,9##
        x(1,j) = xh(1,j)  -  temp * xh(1,2)
        x(2,j) = xh(2,j)  -  temp * xh(2,2)
        x(3,j) = xh(3,j)  -  temp * xh(3,2)
        v(1,j) = vh(1,j)  -  temp * vh(1,2)
        v(2,j) = vh(2,j)  -  temp * vh(2,2)
        v(3,j) = vh(3,j)  -  temp * vh(3,2)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_J2H.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Converts Jacobi coordinates to coordinates with respect to the central
c body.
c
c N.B. The Jacobi coordinates of the small bodies are assumed to be equal
c ===  to their coordinates with respect to the central body.
c
c------------------------------------------------------------------------------
c
      subroutine mco_j2h (time,jcen,nbod,nbig,h,m,x,v,xh,vh,ngf,ngflag,
     %  opt)
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod),ngf(4,nbod)
c
c Local
      integer j
      real*8 mtot, mx, my, mz, mu, mv, mw, temp
c
c------------------------------------------------------------------------------
c
      xh(1,2) = x(1,2)
      xh(2,2) = x(2,2)
      xh(3,2) = x(3,2)
      vh(1,2) = v(1,2)
      vh(2,2) = v(2,2)
      vh(3,2) = v(3,2)
      mtot = m(2)
      temp = m(2) / (mtot + m(1))
      mx = temp * x(1,2)
      my = temp * x(2,2)
      mz = temp * x(3,2)
      mu = temp * v(1,2)
      mv = temp * v(2,2)
      mw = temp * v(3,2)
c
      do j = 3, nbig - 1
        xh(1,j) = x(1,j) + mx
        xh(2,j) = x(2,j) + my
        xh(3,j) = x(3,j) + mz
        vh(1,j) = v(1,j) + mu
        vh(2,j) = v(2,j) + mv
        vh(3,j) = v(3,j) + mw
        mtot = mtot + m(j)
        temp = m(j) / (mtot + m(1))
        mx = mx  +  temp * x(1,j)
        my = my  +  temp * x(2,j)
        mz = mz  +  temp * x(3,j)
        mu = mu  +  temp * v(1,j)
        mv = mv  +  temp * v(2,j)
        mw = mw  +  temp * v(3,j)
      enddo
c
      if (nbig.gt.2) then
        xh(1,nbig) = x(1,nbig) + mx
        xh(2,nbig) = x(2,nbig) + my
        xh(3,nbig) = x(3,nbig) + mz
        vh(1,nbig) = v(1,nbig) + mu
        vh(2,nbig) = v(2,nbig) + mv
        vh(3,nbig) = v(3,nbig) + mw
      end if
c
      do j = nbig + 1, nbod
        xh(1,j) = x(1,j)
        xh(2,j) = x(2,j)
        xh(3,j) = x(3,j)
        vh(1,j) = v(1,j)
        vh(2,j) = v(2,j)
        vh(3,j) = v(3,j)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_KEP.FOR    (ErikSoft  7 July 1999)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Solves Kepler's equation for eccentricities less than one.
c Algorithm from A. Nijenhuis (1991) Cel. Mech. Dyn. Astron. 51, 319-330.
c
c  e = eccentricity
c  l = mean anomaly      (radians)
c  u = eccentric anomaly (   "   )
c
c------------------------------------------------------------------------------
c
      function mco_kep (e,oldl)
      implicit none
c
c Input/Outout
      real*8 oldl,e,mco_kep
c
c Local
      real*8 l,pi,twopi,piby2,u1,u2,ome,sign
      real*8 x,x2,sn,dsn,z1,z2,z3,f0,f1,f2,f3
      real*8 p,q,p2,ss,cc
      logical flag,big,bigg
c
c------------------------------------------------------------------------------
c
      pi = 3.141592653589793d0
      twopi = 2.d0 * pi
      piby2 = .5d0 * pi
c
c Reduce mean anomaly to lie in the range 0 < l < pi
      if (oldl.ge.0) then
        l = mod(oldl, twopi)
      else
        l = mod(oldl, twopi) + twopi
      end if
      sign = 1.d0
      if (l.gt.pi) then
        l = twopi - l
        sign = -1.d0
      end if
c
      ome = 1.d0 - e
c
      if (l.ge..45d0.or.e.lt..55d0) then
c
c Regions A,B or C in Nijenhuis
c -----------------------------
c
c Rough starting value for eccentric anomaly
        if (l.lt.ome) then
          u1 = ome
        else
          if (l.gt.(pi-1.d0-e)) then
            u1 = (l+e*pi)/(1.d0+e)
          else
            u1 = l + e
          end if
        end if
c
c Improved value using Halley's method
        flag = u1.gt.piby2
        if (flag) then
          x = pi - u1
        else
          x = u1
        end if
        x2 = x*x
        sn = x*(1.d0 + x2*(-.16605 + x2*.00761) )
        dsn = 1.d0 + x2*(-.49815 + x2*.03805)
        if (flag) dsn = -dsn
        f2 = e*sn
        f0 = u1 - f2 - l
        f1 = 1.d0 - e*dsn
        u2 = u1 - f0/(f1 - .5d0*f0*f2/f1)
      else
c
c Region D in Nijenhuis
c ---------------------
c
c Rough starting value for eccentric anomaly
        z1 = 4.d0*e + .5d0
        p = ome / z1
        q = .5d0 * l / z1
        p2 = p*p
        z2 = exp( log( dsqrt( p2*p + q*q ) + q )/1.5 )
        u1 = 2.d0*q / ( z2 + p + p2/z2 )
c
c Improved value using Newton's method
        z2 = u1*u1
        z3 = z2*z2
        u2 = u1 - .075d0*u1*z3 / (ome + z1*z2 + .375d0*z3)
        u2 = l + e*u2*( 3.d0 - 4.d0*u2*u2 )
      end if
c
c Accurate value using 3rd-order version of Newton's method
c N.B. Keep cos(u2) rather than sqrt( 1-sin^2(u2) ) to maintain accuracy!
c
c First get accurate values for u2 - sin(u2) and 1 - cos(u2)
      bigg = (u2.gt.piby2)
      if (bigg) then
        z3 = pi - u2
      else
        z3 = u2
      end if
c
      big = (z3.gt.(.5d0*piby2))
      if (big) then
        x = piby2 - z3
      else
        x = z3
      end if
c
      x2 = x*x
      ss = 1.d0
      cc = 1.d0
c
      ss = x*x2/6.*(1. - x2/20.*(1. - x2/42.*(1. - x2/72.*(1. -
     %   x2/110.*(1. - x2/156.*(1. - x2/210.*(1. - x2/272.)))))))
      cc =   x2/2.*(1. - x2/12.*(1. - x2/30.*(1. - x2/56.*(1. -
     %   x2/ 90.*(1. - x2/132.*(1. - x2/182.*(1. - x2/240.*(1. -
     %   x2/306.))))))))
c
      if (big) then
        z1 = cc + z3 - 1.d0
        z2 = ss + z3 + 1.d0 - piby2
      else
        z1 = ss
        z2 = cc
      end if
c
      if (bigg) then
        z1 = 2.d0*u2 + z1 - pi
        z2 = 2.d0 - z2
      end if
c
      f0 = l - u2*ome - e*z1
      f1 = ome + e*z2
      f2 = .5d0*e*(u2-z1)
      f3 = e/6.d0*(1.d0-z2)
      z1 = f0/f1
      z2 = f0/(f2*z1+f1)
      mco_kep = sign*( u2 + f0/((f3*z1+f2)*z2+f1) )
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_SINE.FOR    (ErikSoft  17 April 1997)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates sin and cos of an angle X (in radians).
c
c------------------------------------------------------------------------------
c
      subroutine mco_sine (x,sx,cx)
c
      implicit none
c
c Input/Output
      real*8 x,sx,cx
c
c Local
      real*8 pi,twopi
c
c------------------------------------------------------------------------------
c
      pi = 3.141592653589793d0
      twopi = 2.d0 * pi
c
      if (x.gt.0) then
        x = mod(x,twopi)
      else
        x = mod(x,twopi) + twopi
      end if
c
      cx = cos(x)
c
      if (x.gt.pi) then
        sx = -sqrt(1.d0 - cx*cx)
      else
        sx =  sqrt(1.d0 - cx*cx)
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_SINH.FOR    (ErikSoft  12 June 1998)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Calculates sinh and cosh of an angle X (in radians)
c
c------------------------------------------------------------------------------
c
      subroutine mco_sinh (x,sx,cx)
c
      implicit none
c
c Input/Output
      real*8 x,sx,cx
c
c------------------------------------------------------------------------------
c
      sx = sinh(x)
      cx = sqrt (1.d0 + sx*sx)
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_X2A.FOR    (ErikSoft   4 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates an object's orbital semi-major axis given its Cartesian coords.
c
c------------------------------------------------------------------------------
c
      subroutine mco_x2a (gm,x,y,z,u,v,w,a,r,v2)
c
      implicit none
c
c Input/Output
      real*8 gm,x,y,z,u,v,w,a,r,v2
c
c------------------------------------------------------------------------------
c
      r  = sqrt(x * x  +  y * y  +  z * z)
      v2 =      u * u  +  v * v  +  w * w
      a  = gm * r / (2.d0 * gm  -  r * v2)
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_X2OV.FOR    (ErikSoft   20 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates output variables for an object given its coordinates and
c velocities. The output variables are:
c  r = the radial distance
c  theta = polar angle
c  phi = azimuthal angle
c  fv = 1 / [1 + 2(ke/be)^2], where be and ke are the object's binding and
c                             kinetic energies. (Note that 0 < fv < 1).
c  vtheta = polar angle of velocity vector
c  vphi = azimuthal angle of the velocity vector
c
c------------------------------------------------------------------------------
c
      subroutine mco_x2ov (rcen,rmax,mcen,m,x,y,z,u,v,w,fr,theta,phi,fv,
     %  vtheta,vphi)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      real*8 rcen,rmax,mcen,m,x,y,z,u,v,w,fr,theta,phi,fv,vtheta,vphi
c
c Local
      real*8 r,v2,v1,be,ke,temp
c
c------------------------------------------------------------------------------
c
        r = sqrt(x*x + y*y + z*z)
        v2 =     u*u + v*v + w*w
        v1 = sqrt(v2)
        be = (mcen + m) / r
        ke = .5d0 * v2
c
        fr = log10 (min(max(r, rcen), rmax) / rcen)
        temp = ke / be
        fv = 1.d0 / (1.d0 + 2.d0*temp*temp)
c
        theta  = mod (acos (z / r) + TWOPI, TWOPI)
        vtheta = mod (acos (w / v1) + TWOPI, TWOPI)
        phi  = mod (atan2 (y, x) + TWOPI, TWOPI)
        vphi = mod (atan2 (v, u) + TWOPI, TWOPI)
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_X2EL.FOR    (ErikSoft  23 January 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates Keplerian orbital elements given relative coordinates and
c velocities, and GM = G times the sum of the masses.
c
c The elements are: q = perihelion distance
c                   e = eccentricity
c                   i = inclination
c                   p = longitude of perihelion (NOT argument of perihelion!!)
c                   n = longitude of ascending node
c                   l = mean anomaly (or mean longitude if e < 1.e-8)
c
c------------------------------------------------------------------------------
c
      subroutine mco_x2el (gm,x,y,z,u,v,w,q,e,i,p,n,l)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      real*8 gm,q,e,i,p,n,l,x,y,z,u,v,w
c
c Local
      real*8 hx,hy,hz,h2,h,v2,r,rv,s,true
      real*8 ci,to,temp,tmp2,bige,f,cf,ce
c
c------------------------------------------------------------------------------
c
      hx = y * w  -  z * v
      hy = z * u  -  x * w
      hz = x * v  -  y * u
      h2 = hx*hx + hy*hy + hz*hz
      v2 = u * u  +  v * v  +  w * w
      rv = x * u  +  y * v  +  z * w
      r = sqrt(x*x + y*y + z*z)
      h = sqrt(h2)
      s = h2 / gm
c
c Inclination and node
      ci = hz / h
      if (abs(ci).lt.1) then
        i = acos (ci)
c longitude do nodo medida a partir do momento angular perpendicular a órbita (projeção no plano XOY-inercial e no 4º quadrante (X,-Y)). Como a longitude do nodo é medida a partir do eixo +X, então a projeção no plano XOY-inercial do vetor momento angular (perpendicular ao plano de uma órbita com inclinação) se dará no 4º quadrante (X,-Y); Murray and Dermott (1999) - pg. 48, fig. 2.13; pg. 52, Eqs. 2.132 e 2.133; pg. 53, Eqs. 2.137 (dividir a primeira eq. pela segunda para aparecer tangente da longitude do nodo)
        n = atan2 (hx,-hy)
        if (n.lt.0) n = n + TWOPI
      else
        if (ci.gt.0) i = 0.d0
        if (ci.lt.0) i = PI
        n = 0.d0
      end if
c
c Eccentricity and perihelion distance
      temp = 1.d0  +  s * (v2 / gm  -  2.d0 / r)
      if (temp.le.0) then
        e = 0.d0
      else
        e = sqrt (temp)
      end if
      q = s / (1.d0 + e)
c
c True longitude
      if (hy.ne.0) then
        to = -hx/hy
        temp = (1.d0 - ci) * to
        tmp2 = to * to
        true = atan2((y*(1.d0+tmp2*ci)-x*temp),(x*(tmp2+ci)-y*temp))
      else
        true = atan2(y * ci, x)
      end if
      if (ci.lt.0) true = true + PI
c
      if (e.lt.3.d-8) then
        p = 0.d0
        l = true
      else
        ce = (v2*r - gm) / (e*gm)
c
c Mean anomaly for ellipse
        if (e.lt.1) then
          if (abs(ce).gt.1) ce = sign(1.d0,ce)
          bige = acos(ce)
          if (rv.lt.0) bige = TWOPI - bige
          l = bige - e*sin(bige)
        else
c
c Mean anomaly for hyperbola
          if (ce.lt.1) ce = 1.d0
          bige = log( ce + sqrt(ce*ce-1.d0) )
          if (rv.lt.0) bige = - bige
          l = e*sinh(bige) - bige
        end if
c
c Longitude of perihelion
        cf = (s - r) / (e*r)
        if (abs(cf).gt.1) cf = sign(1.d0,cf)
        f = acos(cf)
        if (rv.lt.0) f = TWOPI - f
        p = true - f
        p = mod (p + TWOPI + TWOPI, TWOPI)
      end if
c
      if (l.lt.0) l = l + TWOPI
      if (l.gt.TWOPI) l = mod (l, TWOPI)
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MDT_BS1.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Integrates NBOD bodies (of which NBIG are Big) for one timestep H0
c using the Bulirsch-Stoer method. The accelerations are calculated using the 
c subroutine FORCE. The accuracy of the step is approximately determined 
c by the tolerance parameter TOL.
c
c N.B. Input/output must be in coordinates with respect to the central body.
c ===
c
c------------------------------------------------------------------------------
c
c ##A19,71##
c ##AN28,82##
c ##A35,60##
c ##A39,13##
c ##A43,6##
      subroutine mdt_bs1 (time,h0,hdid,tol,jcen,nbod,nbig,mass,x0,v0,s,
     %  rphys,rcrit,ngf,stat,dtflag,ngflag,opt,nce,ice,jce,force,nov,
     %  nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,apot,
     %  K2,AU,MSUN,idtag,chk,lapla2,tstart)
c ##A43,6##
c ##A39,13##
c ##A35,60##
c ##AN28,82##
c ##A19,71##
c
      implicit none
      include 'mercury.inc'
c
      real*8 SHRINK,GROW
      parameter (SHRINK=.55d0,GROW=1.3d0)
c
c Input/Output
      integer nbod, nbig, opt(9), stat(nbod), dtflag, ngflag
      integer nce, ice(nce), jce(nce)
      real*8 time,h0,hdid,tol,jcen(3),mass(nbod),x0(3,nbod),v0(3,nbod)
      real*8 s(3,nbod),ngf(4,nbod),rphys(nbod),rcrit(nbod)
c ##A19,72##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      integer algor
      real*8 optr(76)
      integer opti(90)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
c ##A19,72##
c ##AN28,83##
      real*8 K2,AU,MSUN
c ##AN28,83##
c ##A35,61##
      integer idtag(nbod)
c ##A35,61##
      external force
c ##A39,14##
      real*8 chk(3,nbod)
c ##A39,14##
c ##A43,7##
      integer lapla2(nbod)
      real*8 tstart
c ##A43,7##
c
c Local
      integer j, j1, k, n
      real*8 tmp0,tmp1,tmp2,errmax,tol2,h,hx2,h2(8)
      real*8 x(3,NMAX),v(3,NMAX),xend(3,NMAX),vend(3,NMAX)
      real*8 a(3,NMAX),a0(3,NMAX),d(6,NMAX,8),xscal(NMAX),vscal(NMAX)
c ##A19,147##
c      integer firstflag
c ##A19,147##
c
c------------------------------------------------------------------------------
c
c ##A19,148##
c      firstflag = 0
c
c1234  tol2 = tol * tol
c ##A19,148##
c
      tol2 = tol * tol
c
c Calculate arrays used to scale the relative error (R^2 for position and
c V^2 for velocity).
      do k = 2, nbod
        tmp1 = x0(1,k)*x0(1,k) + x0(2,k)*x0(2,k) + x0(3,k)*x0(3,k)
        tmp2 = v0(1,k)*v0(1,k) + v0(2,k)*v0(2,k) + v0(3,k)*v0(3,k)
c ##A19,149##
c        if ((tmp1.eq.0.d0.or.tmp2.eq.0.d0).and.firstflag.eq.0) then
c          firstflag = 1
c          goto 1234
c        end if
c        if (firstflag.eq.1) then
c          tmp1 = 1.d0
c          tmp2 = 1.d0
c        end if
c ##A19,149##
c ##EAN15,1##
        xscal(k) = 1.d0 / (tmp1 + TINY*TINY)
        vscal(k) = 1.d0 / (tmp2 + TINY*TINY)
c ##EAN15,1##
      end do
c
c Calculate accelerations at the start of the step
c ##A19,73##
c ##AN28,97##
c ##A38,117##
c ##A39,35##
c ##A43,24##
      call force (time,jcen,nbod,nbig,mass,x0,v0,s,rcrit,a0,stat,ngf,
     %  ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,
     %  xc,yc,zc,optr,opti,algor,apot,K2,AU,MSUN,chk,lapla2,tstart)
c ##A43,24##
c ##A39,35##
c ##A38,117##
c ##AN28,97##
c ##A19,73##
c
 100  continue
c
c For each value of N, do a modified-midpoint integration with 2N substeps
      do n = 1, 8
        h = h0 / (2.d0 * float(n))
        h2(n) = .25d0 / (n*n)
        hx2 = h * 2.d0
c
        do k = 2, nbod
          x(1,k) = x0(1,k) + h*v0(1,k)
          x(2,k) = x0(2,k) + h*v0(2,k)
          x(3,k) = x0(3,k) + h*v0(3,k)
          v(1,k) = v0(1,k) + h*a0(1,k)
          v(2,k) = v0(2,k) + h*a0(2,k)
          v(3,k) = v0(3,k) + h*a0(3,k)
        end do
c ##A19,74##
c ##AN28,98##
c ##A38,118##
c ##A39,36##
c ##A43,25##
        call force (time,jcen,nbod,nbig,mass,x,v,s,rcrit,a,stat,ngf,
     %    ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,
     %    xc,yc,zc,optr,opti,algor,apot,K2,AU,MSUN,chk,lapla2,tstart)
c ##A43,25##
c ##A39,36##
c ##A38,118##
c ##AN28,98##
c ##A19,74##
        do k = 2, nbod
          xend(1,k) = x0(1,k) + hx2*v(1,k)
          xend(2,k) = x0(2,k) + hx2*v(2,k)
          xend(3,k) = x0(3,k) + hx2*v(3,k)
          vend(1,k) = v0(1,k) + hx2*a(1,k)
          vend(2,k) = v0(2,k) + hx2*a(2,k)
          vend(3,k) = v0(3,k) + hx2*a(3,k)
        end do
c
        do j = 2, n
c ##A19,75##
c ##AN28,99##
c ##A38,119##
c ##A39,37##
c ##A43,26##
          call force (time,jcen,nbod,nbig,mass,xend,vend,s,rcrit,a,stat,
     %      ngf,ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,
     %      dens,mc,xc,yc,zc,optr,opti,algor,apot,K2,AU,MSUN,chk,lapla2,
     %      tstart)
c ##A43,26##
c ##A39,37##
c ##A38,119##
c ##AN28,99##
c ##A19,75##
          do k = 2, nbod
            x(1,k) = x(1,k) + hx2*vend(1,k)
            x(2,k) = x(2,k) + hx2*vend(2,k)
            x(3,k) = x(3,k) + hx2*vend(3,k)
            v(1,k) = v(1,k) + hx2*a(1,k)
            v(2,k) = v(2,k) + hx2*a(2,k)
            v(3,k) = v(3,k) + hx2*a(3,k)
          end do
c ##A19,76##
c ##AN28,100##
c ##A38,120##
c ##A39,38##
c ##A43,27##
          call force (time,jcen,nbod,nbig,mass,x,v,s,rcrit,a,stat,ngf,
     %      ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,
     %      xc,yc,zc,optr,opti,algor,apot,K2,AU,MSUN,chk,lapla2,tstart)
c ##A43,27##
c ##A39,38##
c ##A38,120##
c ##AN28,100##
c ##A19,76##
          do k = 2, nbod
            xend(1,k) = xend(1,k) + hx2*v(1,k)
            xend(2,k) = xend(2,k) + hx2*v(2,k)
            xend(3,k) = xend(3,k) + hx2*v(3,k)
            vend(1,k) = vend(1,k) + hx2*a(1,k)
            vend(2,k) = vend(2,k) + hx2*a(2,k)
            vend(3,k) = vend(3,k) + hx2*a(3,k)
          end do
        end do
c
c ##A19,77##
c ##AN28,101##
c ##A38,121##
c ##A39,39##
c ##A43,28##
        call force (time,jcen,nbod,nbig,mass,xend,vend,s,rcrit,a,stat,
     %    ngf,ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,
     %    mc,xc,yc,zc,optr,opti,algor,apot,K2,AU,MSUN,chk,lapla2,tstart)
c ##A43,28##
c ##A39,39##
c ##A38,121##
c ##AN28,101##
c ##A19,77##
c
        do k = 2, nbod
          d(1,k,n) = .5d0*(xend(1,k) + x(1,k) + h*vend(1,k))
          d(2,k,n) = .5d0*(xend(2,k) + x(2,k) + h*vend(2,k))
          d(3,k,n) = .5d0*(xend(3,k) + x(3,k) + h*vend(3,k))
          d(4,k,n) = .5d0*(vend(1,k) + v(1,k) + h*a(1,k))
          d(5,k,n) = .5d0*(vend(2,k) + v(2,k) + h*a(2,k))
          d(6,k,n) = .5d0*(vend(3,k) + v(3,k) + h*a(3,k))
        end do
c
c Update the D array, used for polynomial extrapolation
        do j = n - 1, 1, -1
          j1 = j + 1
          tmp0 = 1.d0 / (h2(j) - h2(n))
          tmp1 = tmp0 * h2(j1)
          tmp2 = tmp0 * h2(n)
          do k = 2, nbod
            d(1,k,j) = tmp1 * d(1,k,j1)  -  tmp2 * d(1,k,j)
            d(2,k,j) = tmp1 * d(2,k,j1)  -  tmp2 * d(2,k,j)
            d(3,k,j) = tmp1 * d(3,k,j1)  -  tmp2 * d(3,k,j)
            d(4,k,j) = tmp1 * d(4,k,j1)  -  tmp2 * d(4,k,j)
            d(5,k,j) = tmp1 * d(5,k,j1)  -  tmp2 * d(5,k,j)
            d(6,k,j) = tmp1 * d(6,k,j1)  -  tmp2 * d(6,k,j)
          end do
        end do
c
c After several integrations, test the relative error on extrapolated values
        if (n.gt.3) then
          errmax = 0.d0
c
c Maximum relative position and velocity errors (last D term added)
          do k = 2, nbod
            tmp1 = max( d(1,k,1)*d(1,k,1), d(2,k,1)*d(2,k,1),
     %                  d(3,k,1)*d(3,k,1) )
            tmp2 = max( d(4,k,1)*d(4,k,1), d(5,k,1)*d(5,k,1),
     %                  d(6,k,1)*d(6,k,1) )
            errmax = max(errmax, tmp1*xscal(k), tmp2*vscal(k))
          end do
c
c If error is smaller than TOL, update position and velocity arrays, and exit
          if (errmax.le.tol2) then
            do k = 2, nbod
              x0(1,k) = d(1,k,1)
              x0(2,k) = d(2,k,1)
              x0(3,k) = d(3,k,1)
              v0(1,k) = d(4,k,1)
              v0(2,k) = d(5,k,1)
              v0(3,k) = d(6,k,1)
            end do
c
            do j = 2, n
              do k = 2, nbod
                x0(1,k) = x0(1,k) + d(1,k,j)
                x0(2,k) = x0(2,k) + d(2,k,j)
                x0(3,k) = x0(3,k) + d(3,k,j)
                v0(1,k) = v0(1,k) + d(4,k,j)
                v0(2,k) = v0(2,k) + d(5,k,j)
                v0(3,k) = v0(3,k) + d(6,k,j)
              end do
            end do
c
c Save the actual stepsize used
            hdid = h0
c
c Recommend a new stepsize for the next call to this subroutine
            if (n.eq.8) h0 = h0 * SHRINK
            if (n.lt.7) h0 = h0 * GROW
            return
          end if
        end if
c
      end do
c
c If errors were too large, redo the step with half the previous step size.
      h0 = h0 * .5d0
      goto 100
c
c------------------------------------------------------------------------------
c
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MDT_BS2.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Integrates NBOD bodies (of which NBIG are Big) for one timestep H0
c using the Bulirsch-Stoer method. The accelerations are calculated using the 
c subroutine FORCE. The accuracy of the step is approximately determined 
c by the tolerance parameter TOL.
c
c N.B. This version only works for conservative systems (i.e. force is a
c ===  function of position only) !!!! Hence, non-gravitational forces
c      and post-Newtonian corrections cannot be used.
c
c N.B. Input/output must be in coordinates with respect to the central body.
c ===
c
c------------------------------------------------------------------------------
c
c ##A19,78##
c ##AN28,84##
c ##A35,64##
c ##A39,20## 
c ##A43,8##
      subroutine mdt_bs2 (time,h0,hdid,tol,jcen,nbod,nbig,mass,x0,v0,s,
     %  rphys,rcrit,ngf,stat,dtflag,ngflag,opt,nce,ice,jce,force,nov,
     %  nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,apot,
     %  K2,AU,MSUN,idtag,chk,lapla2,tstart)
c ##A43,8##
c ##A39,20## 
c ##A35,64##
c ##AN28,84##
c ##A19,78##
c
      implicit none
      include 'mercury.inc'
c
      real*8 SHRINK,GROW
      parameter (SHRINK=.55d0,GROW=1.3d0)
c
c Input/Output
      integer nbod, nbig, opt(9), stat(nbod), dtflag, ngflag
      real*8 time,h0,hdid,tol,jcen(3),mass(nbod),x0(3,nbod),v0(3,nbod)
      real*8 s(3,nbod),ngf(4,nbod),rphys(nbod),rcrit(nbod)
      integer nce,ice(nce),jce(nce)
c ##A19,79##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      integer algor
      real*8 optr(76)
      integer opti(90)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
c ##A19,79##
c ##AN28,85##
      real*8 K2,AU,MSUN
c ##AN28,85##
c ##A35,65##
      integer idtag(nbod)
c ##A35,65##
      external force
c ##A39,21## 
      real*8 chk(3,nbod)
c ##A39,21## 
c ##A43,9##
      integer lapla2(nbod)
      real*8 tstart
c ##A43,9##
c
c Local
      integer j,j1,k,n
      real*8 tmp0,tmp1,tmp2,errmax,tol2,h,h2(12),hby2,h2by2
      real*8 xend(3,NMAX),b(3,NMAX),c(3,NMAX)
      real*8 a(3,NMAX),a0(3,NMAX),d(6,NMAX,12),xscal(NMAX),vscal(NMAX)
c ##A19,150##
c      integer firstflag
c ##A19,150##
c
c------------------------------------------------------------------------------
c
c ##A19,151##
c      firstflag = 0
c
c1234  tol2 = tol * tol
c ##A19,151##
c
      tol2 = tol * tol
c
c Calculate arrays used to scale the relative error (R^2 for position and
c V^2 for velocity).
      do k = 2, nbod
        tmp1 = x0(1,k)*x0(1,k) + x0(2,k)*x0(2,k) + x0(3,k)*x0(3,k)
        tmp2 = v0(1,k)*v0(1,k) + v0(2,k)*v0(2,k) + v0(3,k)*v0(3,k)
c ##A19,152##
c        if ((tmp1.eq.0.d0.or.tmp2.eq.0.d0).and.firstflag.eq.0) then
c          firstflag = 1
c          goto 1234
c        end if
c        if (firstflag.eq.1) then
c          tmp1 = 1.d0
c          tmp2 = 1.d0
c        end if
c ##A19,152##
c ##EAN15,2##
        xscal(k) = 1.d0 / (tmp1 + TINY*TINY)
        vscal(k) = 1.d0 / (tmp2 + TINY*TINY)
c ##EAN15,2##
      end do
c
c Calculate accelerations at the start of the step
c ##A19,80##
c ##AN28,102##
c ##A38,122##
c ##A39,40##
c ##A43,29##
      call force (time,jcen,nbod,nbig,mass,x0,v0,s,rcrit,a0,stat,ngf,
     %  ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,
     %  xc,yc,zc,optr,opti,algor,apot,K2,AU,MSUN,chk,lapla2,tstart)
c ##A43,29##
c ##A39,40##
c ##A38,122##
c ##AN28,102##
c ##A19,80##
c
 100  continue
c
c For each value of N, do a modified-midpoint integration with N substeps
      do n = 1, 12
        h = h0 / (dble(n))
        hby2  = .5d0 * h
        h2(n) = h * h
        h2by2 = .5d0 * h2(n)
c
        do k = 2, nbod
          b(1,k) = .5d0*a0(1,k)
          b(2,k) = .5d0*a0(2,k)
          b(3,k) = .5d0*a0(3,k)
          c(1,k) = 0.d0
          c(2,k) = 0.d0
          c(3,k) = 0.d0
          xend(1,k) = h2by2 * a0(1,k)  +  h * v0(1,k)  +  x0(1,k)
          xend(2,k) = h2by2 * a0(2,k)  +  h * v0(2,k)  +  x0(2,k)
          xend(3,k) = h2by2 * a0(3,k)  +  h * v0(3,k)  +  x0(3,k)
        end do
c
        do j = 2, n
c ##A19,81##
c ##AN28,103##
c ##A38,123##
c ##A39,41##
c ##A43,30##
          call force (time,jcen,nbod,nbig,mass,xend,v0,s,rcrit,a,stat,
     %      ngf,ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,
     %      dens,mc,xc,yc,zc,optr,opti,algor,apot,K2,AU,MSUN,chk,lapla2,
     %      tstart)
c ##A43,30##
c ##A39,41##
c ##A38,123##
c ##AN28,103##
c ##A19,81##
          tmp0 = h * dble(j)
          do k = 2, nbod
            b(1,k) = b(1,k) + a(1,k)
            b(2,k) = b(2,k) + a(2,k)
            b(3,k) = b(3,k) + a(3,k)
            c(1,k) = c(1,k) + b(1,k)
            c(2,k) = c(2,k) + b(2,k)
            c(3,k) = c(3,k) + b(3,k)
            xend(1,k) = h2(n)*c(1,k) + h2by2*a0(1,k) + tmp0*v0(1,k)
     %                + x0(1,k)
            xend(2,k) = h2(n)*c(2,k) + h2by2*a0(2,k) + tmp0*v0(2,k)
     %                + x0(2,k)
            xend(3,k) = h2(n)*c(3,k) + h2by2*a0(3,k) + tmp0*v0(3,k)
     %                + x0(3,k)
          end do
        end do
c
c ##A19,82##
c ##AN28,104##
c ##A38,124##
c ##A39,42##
c ##A43,31##
        call force (time,jcen,nbod,nbig,mass,xend,v0,s,rcrit,a,stat,ngf,
     %    ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,
     %    xc,yc,zc,optr,opti,algor,apot,K2,AU,MSUN,chk,lapla2,tstart)
c ##A43,31##
c ##A39,42##
c ##A38,124##
c ##AN28,104##
c ##A19,82##
c
        do k = 2, nbod
          d(1,k,n) = xend(1,k)
          d(2,k,n) = xend(2,k)
          d(3,k,n) = xend(3,k)
          d(4,k,n) = h*b(1,k) + hby2*a(1,k) + v0(1,k)
          d(5,k,n) = h*b(2,k) + hby2*a(2,k) + v0(2,k)
          d(6,k,n) = h*b(3,k) + hby2*a(3,k) + v0(3,k)
        end do
c
c Update the D array, used for polynomial extrapolation
        do j = n - 1, 1, -1
          j1 = j + 1
          tmp0 = 1.d0 / (h2(j) - h2(n))
          tmp1 = tmp0 * h2(j1)
          tmp2 = tmp0 * h2(n)
          do k = 2, nbod
            d(1,k,j) = tmp1 * d(1,k,j1)  -  tmp2 * d(1,k,j)
            d(2,k,j) = tmp1 * d(2,k,j1)  -  tmp2 * d(2,k,j)
            d(3,k,j) = tmp1 * d(3,k,j1)  -  tmp2 * d(3,k,j)
            d(4,k,j) = tmp1 * d(4,k,j1)  -  tmp2 * d(4,k,j)
            d(5,k,j) = tmp1 * d(5,k,j1)  -  tmp2 * d(5,k,j)
            d(6,k,j) = tmp1 * d(6,k,j1)  -  tmp2 * d(6,k,j)
          end do
        end do
c
c After several integrations, test the relative error on extrapolated values
        if (n.gt.3) then
          errmax = 0.d0
c
c Maximum relative position and velocity errors (last D term added)
          do k = 2, nbod
            tmp1 = max( d(1,k,1)*d(1,k,1), d(2,k,1)*d(2,k,1),
     %                  d(3,k,1)*d(3,k,1) )
            tmp2 = max( d(4,k,1)*d(4,k,1), d(5,k,1)*d(2,k,1),
     %                  d(6,k,1)*d(6,k,1) )
            errmax = max( errmax, tmp1*xscal(k), tmp2*vscal(k) )
          end do
c
c If error is smaller than TOL, update position and velocity arrays and exit
          if (errmax.le.tol2) then
            do k = 2, nbod
              x0(1,k) = d(1,k,1)
              x0(2,k) = d(2,k,1)
              x0(3,k) = d(3,k,1)
              v0(1,k) = d(4,k,1)
              v0(2,k) = d(5,k,1)
              v0(3,k) = d(6,k,1)
            end do
c
            do j = 2, n
              do k = 2, nbod
                x0(1,k) = x0(1,k) + d(1,k,j)
                x0(2,k) = x0(2,k) + d(2,k,j)
                x0(3,k) = x0(3,k) + d(3,k,j)
                v0(1,k) = v0(1,k) + d(4,k,j)
                v0(2,k) = v0(2,k) + d(5,k,j)
                v0(3,k) = v0(3,k) + d(6,k,j)
              end do
            end do
c
c Save the actual stepsize used
            hdid = h0
c
c Recommend a new stepsize for the next call to this subroutine
            if (n.ge.8) h0 = h0 * SHRINK
            if (n.lt.7) h0 = h0 * GROW
            return
          end if
        end if
c
      end do
c
c If errors were too large, redo the step with half the previous step size.
      h0 = h0 * .5d0
      goto 100
c
c------------------------------------------------------------------------------
c
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MDT_HY.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Integrates NBOD bodies (of which NBIG are Big) for one timestep H
c using a second-order hybrid-symplectic integrator algorithm
c
c DTFLAG = 0 implies first ever call to this subroutine, 
c        = 1 implies first call since number/masses of objects changed.
c        = 2 normal call
c
c N.B. Input/output must be in democratic heliocentric coordinates.
c ===
c
c------------------------------------------------------------------------------
c
c ##A6,10##
c ##A19,109##
c ##E14,16##
c ##AN28,60##
c ##A35,74##
c ##A39,27## 
c ##A43,12##
      subroutine mdt_hy (time,tstart,h0,tol,rmax,en,am,jcen,rcen,nbod,
     %  nbig,m,x,v,s,rphys,rcrit,rce,stat,id,ngf,algor,opt,dtflag,
     %  ngflag,opflag,colflag,nclo,iclo,jclo,dclo,tclo,ixvclo,jxvclo,
     %  outfile,mem,lmem,nclo2,iclo2,jclo2,dclo2,tclo2,ixvclo2,jxvclo2,
     %  nstored,nbclo,bclo,aux,cce,opti,rho,flagce,nov,nop,noc,xv,yv,zv,
     %  noe,kkk,dens,mc,xc,yc,zc,optr,apot,nelim,tcol,K2,AU,MSUN,coord,
     %  bcoord,idtag,chk,lapla2)
c ##A43,12##
c ##A39,27## 
c ##A35,74##
c ##AN28,60##
c ##E14,16##
c ##A19,109##
c ##A6,10##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,stat(nbod),algor,opt(9),dtflag,ngflag,opflag
      integer colflag,lmem(NMESS),nclo,iclo(CMAX),jclo(CMAX)
      real*8 time,tstart,h0,tol,rmax,en(3),am(3),jcen(3),rcen
      real*8 m(nbod),x(3,nbod),v(3,nbod),s(3,nbod),rphys(nbod)
      real*8 rce(nbod),rcrit(nbod),ngf(4,nbod),tclo(CMAX),dclo(CMAX)
      real*8 ixvclo(6,CMAX),jxvclo(6,CMAX)
      character*80 outfile(4),mem(NMESS)
      character*8 id(nbod)
c ##A6,8##
      integer nclo2,iclo2(CMAX),jclo2(CMAX)
      real*8 dclo2(CMAX),tclo2(CMAX)
      real*8 ixvclo2(6,CMAX),jxvclo2(6,CMAX)
      integer nstored
      integer nbclo,bclo(nbod)
      character*1 aux(CMAX)
      character*107 cce(FMAX)
      integer opti(90)
      real*8 rho(nbod)
      integer flagce(2)
c ##A6,8##
c ##A19,110##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      real*8 optr(76)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      external coord,bcoord
c ##A19,110##
c ##A22,36##
      integer nelim
c ##A22,36##
c ##E14,15##
      real*8 tcol
c ##E14,15##
c ##AN28,59##
      real*8 K2,AU,MSUN
c ##AN28,59##
c ##A35,75##
      integer idtag(nbod)
c ##A35,75##
c ##A39,16## 
      real*8 chk(3,nbod)
c ##A39,16## 
c ##A43,13##
      integer lapla2(nbod)
c ##A43,13##
c
c Local
      integer j,nce,ice(NMAX),jce(NMAX),ce(NMAX),iflag
      real*8 a(3,NMAX),hby2,hrec,x0(3,NMAX),v0(3,NMAX),mvsum(3),temp
      real*8 angf(3,NMAX),ausr(3,NMAX)
c ##A19,155##
      real*8 x1(3,NMAX),v1(3,NMAX)
c ##A19,155##
      external mfo_hkce
c ##A19,156##
      external mfo_all
      external mco_h2dh, mco_dh2h
      external mco_h2ast,mco_ast2h
      integer i
      real*8 dx, dy, dz, tmp1, tmp2, s_1, s2, s_3, r3(NMAX)
      integer novl,nopl,noel,kl
      real*8 xl(nov),yl(nov),zl(nov)
      integer i0,ilay,l
      real*8 vx,vy,vz,del,inc
      real*8 xp,yp,zp
      integer ix,iy,iz
      real*8 a2,b2,c2
      dimension noel(nop)
      dimension kl(nopmax,noed)
c ##A19,156##
c ##A39,47##
      real*8 acen(3,NMAX)
c ##A39,47##
c
c------------------------------------------------------------------------------
c
c ##A39,48##
      save a, hrec, angf, ausr, acen
c ##A39,48##
      hby2 = h0 * .5d0
      nclo = 0
      colflag = 0
c ##A19,157##
c
c Save the current coordinates and velocities
c ##A38,35##
      if (algor.eq.22) call mco_iden (time,jcen,nbod,nbig,h0,m,x,v,
     %  x1,v1,ngf,ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,35##
c ##A19,157##
c
c If accelerations from previous call are not valid, calculate them now
      if (dtflag.ne.2) then
        if (dtflag.eq.0) hrec = h0
        call mfo_hy (jcen,nbod,nbig,m,x,rcrit,a,stat)
        dtflag = 2
        do j = 2, nbod
          angf(1,j) = 0.d0
          angf(2,j) = 0.d0
          angf(3,j) = 0.d0
          ausr(1,j) = 0.d0
          ausr(2,j) = 0.d0
          ausr(3,j) = 0.d0
c ##A39,49##
c          acen(1,j) = 0.d0
c          acen(2,j) = 0.d0
c          acen(3,j) = 0.d0
c ##A39,49##
        end do
c If required, apply non-gravitational and user-defined forces
c ##A38,10##
        if (opt(8).eq.1) call mfo_user (time,jcen,nbod,nbig,m,x,v,ausr,
     %    opt,optr,ngf,opti,K2,AU,MSUN)
c ##A38,10##
        if (ngflag.eq.1.or.ngflag.eq.3) call mfo_ngf (nbod,x,v,angf,ngf)
c ##A39,50##
c Include centrifugal accelerations if required
c        if (opti(80).eq.1) call mfo_chk (time,nbod,nbig+1,m,x,v,acen,
c     %    opt,optr,opti,chk,stat)
c ##A39,50##
      end if
c
c Advance interaction Hamiltonian for H/2
      do j = 2, nbod
c ##A39,51##
c        v(1,j) = v(1,j)  +  hby2 * (angf(1,j) + ausr(1,j) + a(1,j)
c     %    + acen(1,j))
c        v(2,j) = v(2,j)  +  hby2 * (angf(2,j) + ausr(2,j) + a(2,j)
c     %    + acen(2,j))
c        v(3,j) = v(3,j)  +  hby2 * (angf(3,j) + ausr(3,j) + a(3,j)
c     %    + acen(3,j))
c ##A39,51##
        v(1,j) = v(1,j)  +  hby2 * (angf(1,j) + ausr(1,j) + a(1,j))
        v(2,j) = v(2,j)  +  hby2 * (angf(2,j) + ausr(2,j) + a(2,j))
        v(3,j) = v(3,j)  +  hby2 * (angf(3,j) + ausr(3,j) + a(3,j))
      end do
c
c Advance solar Hamiltonian for H/2
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      do j = 2, nbod
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
c
      temp = hby2 / m(1)
      mvsum(1) = temp * mvsum(1)
      mvsum(2) = temp * mvsum(2)
      mvsum(3) = temp * mvsum(3)
      do j = 2, nbod
        x(1,j) = x(1,j)  +  mvsum(1)
        x(2,j) = x(2,j)  +  mvsum(2)
        x(3,j) = x(3,j)  +  mvsum(3)
      end do
c
c Save the current coordinates and velocities
c ##A38,36##
      call mco_iden (time,jcen,nbod,nbig,h0,m,x,v,x0,v0,ngf,ngflag,opt,
     %  optr,opti,K2,AU,MSUN)
c ##A38,36##
c
c ##A19,191##
      if (algor.eq.22) then
        do i = 2, nbod
          a(1,i) = 0.d0
          a(2,i) = 0.d0
          a(3,i) = 0.d0
        end do
      end if
c ##A19,191##
c
c Advance H_K for H
      do i = 2, nbod
c ##A19,190##
        if (algor.lt.22) then
          iflag = 0
          call drift_one (m(1),x(1,i),x(2,i),x(3,i),v(1,i),v(2,i),
     %      v(3,i),h0,iflag)
        else
c
c------------------------------------------------------------------------------
c
c hybrid method
          if (opti(23).eq.0.or.(opti(86).eq.1.and.opti(23).eq.1)) then
          tmp1 = x(1,i)*x(1,i) + x(2,i)*x(2,i) + x(3,i)*x(3,i)
c newtonian method
          if (tmp1.ge.optr(7)) then
c            tmp1 = m(1) * r3(i)
c            a(1,i) = a(1,i)  -  tmp1 * x(1,i)
c            a(2,i) = a(2,i)  -  tmp1 * x(2,i)
c            a(3,i) = a(3,i)  -  tmp1 * x(3,i)
            iflag = 0
            call drift_one (m(1),x(1,i),x(2,i),x(3,i),v(1,i),v(2,i),
     %        v(3,i),h0,iflag)
          else
c mascon method
            if (tmp1.ge.optr(8)) then
              do j = 1, noc
                dx = x(1,i) - xc(j)
                dy = x(2,i) - yc(j)
                dz = x(3,i) - zc(j)
                s2 = dx*dx + dy*dy + dz*dz
                s_1 = 1.d0 / sqrt(s2)
                s_3 = s_1 * s_1 * s_1
                tmp1 = s_3 * mc(j)
                a(1,i) = a(1,i)  -  tmp1 * dx
                a(2,i) = a(2,i)  -  tmp1 * dy
                a(3,i) = a(3,i)  -  tmp1 * dz
              end do
c
            else
c polyhedron method
              call polyhedron (nov,nop,xv,yv,zv,noe,kkk,
     %          dens(opti(21)),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
                a(1,i) = a(1,i)  -  vx
                a(2,i) = a(2,i)  -  vy
                a(3,i) = a(3,i)  -  vz
            end if
          end if
c
c------------------------------------------------------------------------------
c
c binary method
          else if (opti(23).eq.1) then
            tmp1=x(1,i)*x(1,i)*a2+x(2,i)*x(2,i)*b2+x(3,i)*x(3,i)*c2-1.0
            if (((x(1,i).ge.optr(17).and.x(1,i).le.optr(18))
     %        .and.(x(2,i).ge.optr(19).and.x(2,i).le.optr(20))
     %        .and.(x(3,i).ge.optr(21).and.x(3,i).le.optr(22)))
     %        .and.(tmp1.gt.0.d0.or.tmp1.eq.-1.0)) then
              xp = x(1,i) * optr(14)
              ix = ceiling (dabs(xp))
              yp = x(2,i) * optr(15)
              iy = ceiling (dabs(yp))
              zp = x(3,i) * optr(16)
              iz = ceiling (dabs(zp))
              if (ix.eq.0) ix = 1
              if (iy.eq.0) iy = 1
              if (iz.eq.0) iz = 1
              if (x(1,i).ge.0.d0.and.x(2,i).ge.0.d0.and.x(3,i)
     %          .ge.0.d0) then
                a(1,i) = a(1,i) + apot(1,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(1,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(1,ix,iy,iz,3)
              else if (x(1,i).lt.0.d0.and.x(2,i).ge.0.d0.and.x(3,i)
     %          .ge.0.d0) then
                a(1,i) = a(1,i) + apot(2,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(2,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(2,ix,iy,iz,3)
              else if (x(1,i).lt.0.d0.and.x(2,i).lt.0.d0.and.x(3,i)
     %          .ge.0.d0) then
                a(1,i) = a(1,i) + apot(3,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(3,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(3,ix,iy,iz,3)
              else if (x(1,i).ge.0.d0.and.x(2,i).lt.0.d0.and.x(3,i)
     %          .ge.0.d0) then
                a(1,i) = a(1,i) + apot(4,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(4,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(4,ix,iy,iz,3)
              else if (x(1,i).ge.0.d0.and.x(2,i).ge.0.d0.and.x(3,i)
     %          .lt.0.d0) then
                a(1,i) = a(1,i) + apot(5,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(5,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(5,ix,iy,iz,3)
              else if (x(1,i).lt.0.d0.and.x(2,i).ge.0.d0.and.x(3,i)
     %          .lt.0.d0) then
                a(1,i) = a(1,i) + apot(6,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(6,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(6,ix,iy,iz,3)
              else if (x(1,i).lt.0.d0.and.x(2,i).lt.0.d0.and.x(3,i)
     %          .lt.0.d0) then
                a(1,i) = a(1,i) + apot(7,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(7,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(7,ix,iy,iz,3)
              else if (x(1,i).ge.0.d0.and.x(2,i).lt.0.d0.and.x(3,i)
     %          .lt.0.d0) then
                a(1,i) = a(1,i) + apot(8,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(8,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(8,ix,iy,iz,3)
              end if
            else
c
c hybrid method
              tmp1 = x(1,i)*x(1,i) + x(2,i)*x(2,i) + x(3,i)*x(3,i)
c newtonian method
              if (tmp1.ge.optr(7)) then
c                tmp1 = m(1) * r3(i)
c                a(1,i) = a(1,i)  -  tmp1 * x(1,i)
c                a(2,i) = a(2,i)  -  tmp1 * x(2,i)
c                a(3,i) = a(3,i)  -  tmp1 * x(3,i)
                iflag = 0
                call drift_one (m(1),x(1,i),x(2,i),x(3,i),v(1,i),v(2,i),
     %            v(3,i),h0,iflag)
              else
c mascon method
                if (tmp1.ge.optr(8)) then
                  do j = 1, noc
                    dx = x(1,i) - xc(j)
                    dy = x(2,i) - yc(j)
                    dz = x(3,i) - zc(j)
                    s2 = dx*dx + dy*dy + dz*dz
                    s_1 = 1.d0 / sqrt(s2)
                    s_3 = s_1 * s_1 * s_1
                    tmp1 = s_3 * mc(j)
                    a(1,i) = a(1,i)  -  tmp1 * dx
                    a(2,i) = a(2,i)  -  tmp1 * dy
                    a(3,i) = a(3,i)  -  tmp1 * dz
                  end do
c
                else
c
                  call polyhedron (nov,nop,xv,yv,zv,noe,kkk,
     %              dens(opti(21)),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
                  a(1,i) = a(1,i)  -  vx
                  a(2,i) = a(2,i)  -  vy
                  a(3,i) = a(3,i)  -  vz
                end if
c
              end if
            end if
c
c------------------------------------------------------------------------------
c
          end if
c          a(1,i) = a(1,i)  +  sx
c          a(2,i) = a(2,i)  +  sy
c          a(3,i) = a(3,i)  +  sz
          if (opti(72).eq.0) then
          a(1,i) = a(1,i)+2.0d0*optr(6)*v(2,i) + optr(6)*optr(6)*x(1,i)
          a(2,i) = a(2,i)-2.0d0*optr(6)*v(1,i) + optr(6)*optr(6)*x(2,i)
          end if
          if (tmp1.lt.optr(7)) then
            v(1,i) = v(1,i)  +  h0 * a(1,i)
            v(2,i) = v(2,i)  +  h0 * a(2,i)
            v(3,i) = v(3,i)  +  h0 * a(3,i)
            x(1,i) = x(1,i)  +  h0 * v(1,i)
            x(2,i) = x(2,i)  +  h0 * v(2,i)
            x(3,i) = x(3,i)  +  h0 * v(3,i)
          end if
        end if
c ##A19,190##
      end do
c
c Check whether any object separations were < R_CRIT whilst advancing H_K
      call mce_snif (h0,2,nbod,nbig,x0,v0,x,v,rcrit,ce,nce,ice,jce)
c
c If objects had close encounters, advance H_K using Bulirsch-Stoer instead
      if (nce.gt.0) then
        do j = 2, nbod
          if (ce(j).ne.0) then
            x(1,j) = x0(1,j)
            x(2,j) = x0(2,j)
            x(3,j) = x0(3,j)
            v(1,j) = v0(1,j)
            v(2,j) = v0(2,j)
            v(3,j) = v0(3,j)
          end if
        end do
c ##A6,7##
c ##A19,117##
c ##A22,37##
c ##E14,14##
c ##ANEO27,12##
c ##AN28,58##
c ##A35,88##
c ##A39,65##
c ##A43,32##
        call mdt_hkce (time,tstart,h0,hrec,tol,rmax,en(3),jcen,rcen,
     %    nbod,nbig,m,x,v,s,rphys,rcrit,rce,stat,id,ngf,algor,opt,
     %    ngflag,colflag,ce,nce,ice,jce,nclo,iclo,jclo,dclo,tclo,ixvclo,
     %    jxvclo,outfile,mem,lmem,mfo_hkce,nclo2,iclo2,jclo2,dclo2,
     %    tclo2,ixvclo2,jxvclo2,nstored,nbclo,bclo,aux,cce,opti,rho,
     %    flagce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,
     %    apot,nelim,tcol,0,K2,AU,MSUN,coord,bcoord,idtag,chk,lapla2)
c ##A43,32##
c ##A39,65##
c ##A35,88##
c ##AN28,58##
c ##ANEO27,12##
c ##E14,14##
c ##A22,37##
c ##A19,117##
c ##A6,7##
      end if
c
c Advance solar Hamiltonian for H/2
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      do j = 2, nbod
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
c
      temp = hby2 / m(1)
      mvsum(1) = temp * mvsum(1)
      mvsum(2) = temp * mvsum(2)
      mvsum(3) = temp * mvsum(3)
      do j = 2, nbod
        x(1,j) = x(1,j)  +  mvsum(1)
        x(2,j) = x(2,j)  +  mvsum(2)
        x(3,j) = x(3,j)  +  mvsum(3)
      end do
c
c Advance interaction Hamiltonian for H/2
      call mfo_hy (jcen,nbod,nbig,m,x,rcrit,a,stat)
c ##A38,11##
      if (opt(8).eq.1) call mfo_user (time,jcen,nbod,nbig,m,x,v,ausr,
     %  opt,optr,ngf,opti,K2,AU,MSUN)
c ##A38,11##
      if (ngflag.eq.1.or.ngflag.eq.3) call mfo_ngf (nbod,x,v,angf,ngf)
c ##A39,52##
c Include centrifugal accelerations if required
c      if (opti(80).eq.1) call mfo_chk (time,nbod,nbig+1,m,x,v,acen,opt,
c     %  optr,opti,chk,stat)
c ##A39,52##
c
      do j = 2, nbod
c ##A39,53##
c        v(1,j) = v(1,j)  +  hby2 * (angf(1,j) + ausr(1,j) + a(1,j)
c     %    + acen(1,j))
c        v(2,j) = v(2,j)  +  hby2 * (angf(2,j) + ausr(2,j) + a(2,j)
c     %    + acen(2,j))
c        v(3,j) = v(3,j)  +  hby2 * (angf(3,j) + ausr(3,j) + a(3,j)
c     %    + acen(3,j))
c ##A39,53##
        v(1,j) = v(1,j)  +  hby2 * (angf(1,j) + ausr(1,j) + a(1,j))
        v(2,j) = v(2,j)  +  hby2 * (angf(2,j) + ausr(2,j) + a(2,j))
        v(3,j) = v(3,j)  +  hby2 * (angf(3,j) + ausr(3,j) + a(3,j))
      end do
c
c------------------------------------------------------------------------------
c
c ##A19,158##
c      if (algor.eq.22) then
c        nce = 0
c        do j = 2, nbod
c          temp = x1(1,j)*x1(1,j)+x1(2,j)*x1(2,j)+x1(3,j)*x1(3,j)
c          if (temp.le.optr(26)) then
c            ce(j) = 1
c            nce = nce + 1
c            ice(nce) = 1
c            jce(nce) = j
c          end if
c        end do
c
c If objects had close encounters, advance H_K using Bulirsch-Stoer instead
c        if (nce.gt.0) then
c          do j = 2, nbod
c            if (ce(j).ne.0) then
c              x(1,j) = x1(1,j)
c              x(2,j) = x1(2,j)
c              x(3,j) = x1(3,j)
c              v(1,j) = v1(1,j)
c              v(2,j) = v1(2,j)
c              v(3,j) = v1(3,j)
c            end if
c          end do
c
c ##A38,51## - for rotating frame
c          call mco_dh2h (time,jcen,nbod,nbig,h0,m,x,v,x0,v0,ngf,ngflag,
c     %      opt,optr,opti,K2,AU,MSUN)
c          call mco_h2ast (time,jcen,nbod,2,optr(6),m,x0,v0,x,v,ngf,
c     %      ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,51##
c
c ##A35,89##
c ##A39,66##
c          call mdt_hkce (time,tstart,h0,hrec,tol,rmax,en(3),jcen,rcen,
c     %      nbod,nbig,m,x,v,s,rphys,rcrit,rce,stat,id,ngf,algor,opt,
c     %      ngflag,colflag,ce,nce,ice,jce,nclo,iclo,jclo,dclo,tclo,
c     %      ixvclo,jxvclo,outfile,mem,lmem,mfo_all,nclo2,iclo2,jclo2,
c     %      dclo2,tclo2,ixvclo2,jxvclo2,nstored,nbclo,bclo,aux,cce,opti,
c     %      rho,flagce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,
c     %      optr,apot,nelim,tcol,1,K2,AU,MSUN,coord,bcoord,idtag,chk)
c ##A39,66##
c ##A35,89##
c
c ##A38,55##
c          call mco_ast2h (time,jcen,nbod,2,optr(6),m,x,v,x0,v0,ngf,
c     %      ngflag,opt,optr,opti,K2,AU,MSUN)
c          call mco_h2dh (time,jcen,nbod,nbig,h0,m,x0,v0,x,v,ngf,ngflag,
c     %      opt,optr,opti,K2,AU,MSUN)
c ##A38,55##
c
c        end if
c      end if
c ##A19,158##
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MDT_HKCE.FOR    (ErikSoft   1 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Integrates NBOD bodies (of which NBIG are Big) for one timestep H under
c the Hamiltonian H_K, including close-encounter terms.
c
c------------------------------------------------------------------------------
c
c ##A6,6##
c ##A19,121##
c ##A22,47##
c ##E14,13##
c ##ANEO27,16##
c ##AN28,57##
c ##A35,87##
c ##A39,64##
c ##A43,33##
      subroutine mdt_hkce (time,tstart,h0,hrec,tol,rmax,elost,jcen,
     %  rcen,nbod,nbig,m,x,v,s,rphy,rcrit,rce,stat,id,ngf,algor,opt,
     %  ngflag,colflag,ce,nce,ice,jce,nclo,iclo,jclo,dclo,tclo,ixvclo,
     %  jxvclo,outfile,mem,lmem,force,nclo2,iclo2,jclo2,dclo2,tclo2,
     %  ixvclo2,jxvclo2,nstored,nbclo,bclo,aux,cce,opti,rho,flagce,nov,
     %  nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,apot,nelim,tcol,
     %  bsflag,K2,AU,MSUN,coord,bcoord,idtag,chk,lapla2)
c ##A43,33##
c ##A39,64##
c ##A35,87##
c ##AN28,57##
c ##ANEO27,16##
c ##E14,13##
c ##A22,47##
c ##A19,121##
c ##A6,6##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,nce,ice(nce),jce(nce),stat(nbod),ngflag,ce(nbod)
      integer algor,opt(9),colflag,lmem(NMESS),nclo,iclo(CMAX)
      integer jclo(CMAX)
      real*8 time,tstart,h0,hrec,tol,rmax,elost,jcen(3),rcen
      real*8 m(nbod),x(3,nbod),v(3,nbod),s(3,nbod)
      real*8 rce(nbod),rphy(nbod),rcrit(nbod),ngf(4,nbod)
      real*8 tclo(CMAX),dclo(CMAX),ixvclo(6,CMAX),jxvclo(6,CMAX)
      character*80 outfile(4),mem(NMESS)
      character*8 id(nbod)
c ##A6,3##
      integer nclo2,iclo2(CMAX),jclo2(CMAX)
      real*8 dclo2(CMAX),tclo2(CMAX)
      real*8 ixvclo2(6,CMAX),jxvclo2(6,CMAX)
      integer nstored
      integer nbclo,bclo(nbod)
      character*1 aux(CMAX)
      character*107 cce(FMAX)
      integer opti(90)
      real*8 rho(nbod)
      integer flagce(2)
c ##A6,3##
c ##A19,83##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      real*8 optr(76)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      external coord,bcoord
c ##A19,83##
c ##A22,48##
      integer nelim
c ##A22,48##
c ##E14,12##
      real*8 tcol
c ##E14,12##
c ##ANEO27,17##
      integer bsflag
c ##ANEO27,17##
c ##AN28,56##
      real*8 K2,AU,MSUN
c ##AN28,56##
c ##A35,86##
      integer idtag(nbod)
c ##A35,86##
      external force
c ##A39,63##
      real*8 chk(3,nbod)
c ##A39,63##
c ##A43,34##
      integer lapla2(nbod)
c ##A43,34##
c
c Local
      integer iback(NMAX),index(NMAX),ibs(NMAX),jbs(NMAX),nclo_old
      integer i,j,k,nbs,nbsbig,statbs(NMAX)
      integer nhit,ihit(CMAX),jhit(CMAX),chit(CMAX),nowflag,dtflag
      real*8 tlocal,hlocal,hdid,tmp0
      real*8 mbs(NMAX),xbs(3,NMAX),vbs(3,NMAX),sbs(3,NMAX)
      real*8 rcritbs(NMAX),rcebs(NMAX),rphybs(NMAX)
c      real*8 ngfbs(4,NMAX),x0(3,NMAX),v0(3,NMAX)
      real*8 ngfbs(4,NMAX)
      real*8 thit(CMAX),dhit(CMAX),thit1,temp
      character*8 idbs(NMAX)
c ##A6,4##
      integer nhit2
c ##A6,4##
c ##A19,177##
      real*8 xh0(3,NMAX),vh0(3,NMAX)
      real*8 xhbs(3,NMAX),vhbs(3,NMAX)
      real*8 rhobs(NMAX)
c ##A19,177##
c ##A39,61##
      real*8 chks(3,NMAX)
c ##A39,61##
c ##A43,35##
      integer lapla2s(NMAX)
c ##A43,35##
c
c------------------------------------------------------------------------------
c
c N.B. Don't set nclo to zero!!
      nbs = 1
      nbsbig = 0
      mbs(1) = m(1)
c ##AAR1,17##
      if (algor.eq.11.or.algor.eq.5) mbs(1) = m(1) + m(2)
c ##AAR1,17##
      sbs(1,1) = s(1,1)
      sbs(2,1) = s(2,1)
      sbs(3,1) = s(3,1)
c
c Put data for close-encounter bodies into local arrays for use with BS routine
      do j = 2, nbod
        if (ce(j).ne.0) then
          nbs = nbs + 1
          if (j.le.nbig) nbsbig = nbs
          mbs(nbs)   = m(j)
          xbs(1,nbs) = x(1,j)
          xbs(2,nbs) = x(2,j)
          xbs(3,nbs) = x(3,j)
          vbs(1,nbs) = v(1,j)
          vbs(2,nbs) = v(2,j)
          vbs(3,nbs) = v(3,j)
          sbs(1,nbs) = s(1,j)
          sbs(2,nbs) = s(2,j)
          sbs(3,nbs) = s(3,j)
          rcebs(nbs) = rce(j)
          rphybs(nbs) = rphy(j)
          statbs(nbs) = stat(j)
          rcritbs(nbs) = rcrit(j)
          idbs(nbs) = id(j)
          index(nbs) = j
          iback(j) = nbs
          rhobs(nbs) = rho(j)
c ##A39,62##
          chks(1,nbs) = chk(1,j)
          chks(2,nbs) = chk(2,j)
          chks(3,nbs) = chk(3,j)
c ##A39,62##
c ##A43,36##
          lapla2s(nbs) = lapla2(j)
c ##A43,36##
        end if
      end do
c
      do k = 1, nce
        ibs(k) = iback(ice(k))
        jbs(k) = iback(jce(k))
      end do
c
      tlocal = 0.d0
      hlocal = sign(hrec,h0)
c
c Begin the Bulirsch-Stoer integration
  50  continue
        tmp0 = abs(h0) - abs(tlocal)
        hrec = hlocal
        if (abs(hlocal).gt.tmp0) hlocal = sign (tmp0, h0)
c
c Save old coordinates and integrate
c ##A19,84##
c        call mco_iden (time,jcen,nbs,0,h0,mbs,xbs,vbs,x0,v0,ngf,ngflag,
c     %    opt)
c ##A38,37##
        call bcoord(time-tstart,jcen,nbs,2,optr(6),mbs,xbs,vbs,xh0,vh0,
     %    ngf,ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,37##
c
c ##ANEO27,18##
        if (bsflag.eq.0) then
c ##AN28,88##
c ##A35,62##
c ##A39,15##
c ##A43,37##
          call mdt_bs2 (time,hlocal,hdid,tol,jcen,nbs,nbsbig,mbs,xbs,
     %      vbs,sbs,rphybs,rcritbs,ngfbs,statbs,dtflag,ngflag,opt,nce,
     %      ibs,jbs,force,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,
     %      zc,optr,opti,algor,apot,K2,AU,MSUN,idtag,chks,lapla2s,
     %      tstart)
        else if (bsflag.eq.1) then
          call mdt_bs1 (time,hlocal,hdid,tol,jcen,nbs,nbsbig,mbs,xbs,
     %      vbs,sbs,rphybs,rcritbs,ngfbs,statbs,dtflag,ngflag,opt,nce,
     %      ibs,jbs,force,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,
     %      zc,optr,opti,algor,apot,K2,AU,MSUN,idtag,chks,lapla2s,
     %      tstart)
c ##A43,37##
c ##A39,15##
c ##A35,62##
c ##AN28,88##
        end if
c ##ANEO27,18##
c
c ##A38,97##
        call bcoord(time-tstart,jcen,nbs,2,optr(6),mbs,xbs,vbs,xhbs,
     %    vhbs,ngf,ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,97##
c ##A19,84##
        tlocal = tlocal + hdid
c
c Check for close-encounter minima
        nclo_old = nclo
        temp = time + tlocal
c ##A6,35##
c ##A22,12##
c ##E14,11##
        call mce_stat (temp,hdid,rcen,nbs,nbsbig,mbs,xh0,vh0,xhbs,vhbs,
     %    rcebs,rphybs,nclo,iclo,jclo,dclo,tclo,ixvclo,jxvclo,nhit,ihit,
     %    jhit,chit,dhit,thit,thit1,nowflag,statbs,outfile(3),mem,lmem,
     %    opti,nbclo,bclo,aux,flagce(2),index,nbod,1,opt(3),tstart,idbs,
     %    nelim,tcol)
c ##E14,11##
c ##A22,12##
c ##A6,35##
c ##A6,2##
c        call mce_stat3 (temp,hdid,nbs,nbsbig,mbs,x0,v0,xbs,vbs,rcebs,
c     %    rphybs,nclo2,iclo2,jclo2,dclo2,tclo2,ixvclo2,jxvclo2,statbs,
c     %    mem,lmem,opti,nbclo,bclo,aux,flagce(2),index,nbod)
c ##A6,2##
c
c If collisions occurred, resolve the collision and return a flag
c ##A22,49##
c        if (nhit.gt.0.and.opt(2).ne.0) then
        if ((nhit.gt.0.and.opt(2).ne.0).or.nelim.gt.0) then
c ##A22,49##
c ##A6,5##
          nhit2 = 0
          do k = 1, nhit
c ##A22,19##
c            if (chit(k).eq.1) nhit2 = 1
            if (chit(k).gt.0) nhit2 = 1
c ##A22,19##
          end do
c ##A22,50##
c          if (nhit2.gt.0) then
          if (nhit2.gt.0.or.nelim.gt.0) then
c ##A22,50##
            if (opt(1).eq.1) return
c ##E5,5##
c ##A6,36##
c            call mio_cestored (rcen,rmax,nbod,m,nclo2,iclo2,jclo2,
c     %      opt(4),tclo2,dclo2,ixvclo2,jxvclo2,nstored,aux,cce,bclo)
c ##E19,12##
            call mio_cestored (rcen,rmax,nbod,m,nclo,iclo,jclo,opt(4),
     %      tclo,dclo,ixvclo,jxvclo,nstored,aux,cce,bclo,algor,optr)
c ##E19,12##
c ##A6,36##
c ##E5,5##
c ##A24,13##
c ##AN28,129##
            call mce_criteria (tcol,tstart,nbod,algor,opt(3),m,id,
     %      opti,optr,mem,lmem,nbclo,nstored,K2)
c ##AN28,129##
c ##A24,13##
c ##A23,11##
c ##AN28,52##
c ##A32,31##
c ##A35,46##
            call mce_header (tstart,algor,jcen,rcen,rmax,nbod,m,s,rho,
     %      id,opt,outfile(2),nbclo,bclo,nstored,nbig,K2,AU,MSUN,optr,
     %      idtag)
c ##A35,46##
c ##A32,31##
c ##AN28,52##
c ##A23,11##
            call mio_ceflush (opt(4),outfile(2),nstored,cce)
c ##A6,37##
c            nclo2 = 0
            nclo = 0
c ##A6,37##
            flagce(1) = 1
            flagce(2) = 0
          end if
c ##A6,5##
          do k = 1, nhit
c ##A22,20##
c            if (chit(k).eq.1) then
            if (chit(k).gt.0) then
c ##A22,20##
              i = ihit(k)
              j = jhit(k)
c ##A11,13##
c ##A22,21##
c ##A19,178##
c              call mce_coll (thit(k),tstart,elost,jcen,i,j,nbs,nbsbig,
c     %          mbs,xbs,vbs,sbs,rphybs,statbs,idbs,opt,mem,lmem,
c     %          outfile(3),opti,chit(k))
c ##A19,211##
              call mce_coll (thit(k),tstart,elost,jcen,i,j,nbs,nbsbig,
     %          mbs,xhbs,vhbs,sbs,rphybs,statbs,idbs,opt,mem,lmem,
     %          outfile(3),opti,chit(k),nov,nop,noc,xv,yv,zv,noe,kkk,
     %          dens,mc,xc,yc,zc,optr,algor,K2,rhobs)
c ##A19,211##
c ##A19,178##
c ##A22,21##
c ##A11,13##
              colflag = colflag + 1
            end if
          end do
        end if
c
c If necessary, continue integrating objects undergoing close encounters
      if ((tlocal - h0)*h0.lt.0) goto 50
c
c Return data for the close-encounter objects to global arrays
      do k = 2, nbs
        j = index(k)
        m(j)   = mbs(k)
        x(1,j) = xbs(1,k)
        x(2,j) = xbs(2,k)
        x(3,j) = xbs(3,k)
        v(1,j) = vbs(1,k)
        v(2,j) = vbs(2,k)
        v(3,j) = vbs(3,k)
        s(1,j) = sbs(1,k)
        s(2,j) = sbs(2,k)
        s(3,j) = sbs(3,k)
        stat(j) = statbs(k)
c ##A43,38##
        lapla2(j) = lapla2s(k)
c ##A43,38##
      end do
c ##A6,38##
c ##E12,12##
c
c dcarrera 2014-10-29
c          Replace nclo -> min(nclo,CMAX) to avoid segmentation faults.
c
c      do k = 1, min(nclo,CMAX)
c ##E12,12##
c        iclo(k) = index(iclo(k))
c        jclo(k) = index(jclo(k))
c      end do
c ##A6,38##
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MDT_MVS.FOR    (ErikSoft   1 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Integrates NBOD bodies (of which NBIG are Big) for one timestep H
c using a second-order mixed-variable symplectic integrator.
c
c DTFLAG = 0 implies first ever call to this subroutine, 
c        = 1 implies first call since number/masses of objects changed.
c        = 2 normal call
c
c N.B. Input/output must be in coordinates with respect to the central body.
c ===
c
c------------------------------------------------------------------------------
c
c ##A6,26##
c ##A19,107##
c ##A22,34##
c ##E14,10##
c ##AN28,86##
c ##A35,58##
c ##A39,11##
c ##A43,22##
      subroutine mdt_mvs (time,tstart,h0,tol,rmax,en,am,jcen,rcen,nbod,
     %  nbig,m,x,v,s,rphys,rcrit,rce,stat,id,ngf,algor,opt,dtflag,
     %  ngflag,opflag,colflag,nclo,iclo,jclo,dclo,tclo,ixvclo,jxvclo,
     %  outfile,mem,lmem,nclo2,iclo2,jclo2,dclo2,tclo2,ixvclo2,jxvclo2,
     %  nstored,nbclo,bclo,aux,cce,opti,rho,flagce,nov,nop,noc,xv,yv,zv,
     %  noe,kkk,dens,mc,xc,yc,zc,optr,apot,nelim,tcol,K2,AU,MSUN,idtag,
     %  chk,lapla2)
c ##A43,22##
c ##A39,11##
c ##A35,58##
c ##AN28,86##
c ##E14,10##
c ##A22,34##
c ##A19,107##
c ##A6,26##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,stat(nbod),algor,opt(9),dtflag,ngflag,opflag
      integer colflag,lmem(NMESS),nclo,iclo(CMAX),jclo(CMAX)
      real*8 time,tstart,h0,tol,rmax,en(3),am(3),jcen(3),rcen
      real*8 m(nbod),x(3,nbod),v(3,nbod),s(3,nbod),rphys(nbod)
      real*8 rce(nbod),rcrit(nbod),ngf(4,nbod),tclo(CMAX),dclo(CMAX)
      real*8 ixvclo(6,CMAX),jxvclo(6,CMAX)
      character*80 outfile(4),mem(NMESS)
      character*8 id(nbod)
c ##A6,25##
      integer nclo2,iclo2(CMAX),jclo2(CMAX)
      real*8 dclo2(CMAX),tclo2(CMAX)
      real*8 ixvclo2(6,CMAX),jxvclo2(6,CMAX)
      integer nstored
      integer nbclo,bclo(nbod)
      character*1 aux(CMAX)
      character*107 cce(FMAX)
      integer opti(90)
      real*8 rho(nbod)
      integer flagce(2)
      integer index(NMAX)
c ##A6,25##
c ##A19,108##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      real*8 optr(76)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
c ##A19,108##
c ##A22,35##
      integer nelim
c ##A22,35##
c ##E14,9##
      real*8 tcol
c ##E14,9##
c ##AN28,87##
      real*8 K2,AU,MSUN
c ##AN28,87##
c ##A35,59##
      integer idtag(nbod)
c ##A35,59##
c ##A39,12##
      real*8 chk(3,nbod)
c ##A39,12##
c ##A43,23##
      integer lapla2(nbod)
c ##A43,23##
c
c Local
      integer j,iflag,nhit,ihit(CMAX),jhit(CMAX),chit(CMAX),nowflag
      real*8 xj(3,NMAX),vj(3,NMAX),a(3,NMAX),gm(NMAX),hby2,thit1,temp
      real*8 msofar,minside,x0(3,NMAX),v0(3,NMAX),dhit(CMAX),thit(CMAX)
      real*8 angf(3,NMAX),ausr(3,NMAX)
c ##A36,2##
      integer k,i
      integer nhit2
c ##A36,2##
c
c------------------------------------------------------------------------------
c
      save a, xj, gm, angf, ausr
      hby2 = .5d0 * h0
      nclo = 0
c ##A6,24##
c      nclo2 = 0
c ##A6,24##
c ##E4,1##
      colflag = 0
c ##E4,1##
c
c If accelerations from previous call are not valid, calculate them now,
c and also the Jacobi coordinates XJ, and effective central masses GM.
      if (dtflag.ne.2) then
        dtflag = 2
        call mco_h2j (time,jcen,nbig,nbig,h0,m,x,v,xj,vj,ngf,ngflag,opt)
        call mfo_mvs (jcen,nbod,nbig,m,x,xj,a,stat)
c
        minside = m(1)
        do j = 2, nbig
          msofar = minside + m(j)
          gm(j) = m(1) * msofar / minside
          minside = msofar
          angf(1,j) = 0.d0
          angf(2,j) = 0.d0
          angf(3,j) = 0.d0
          ausr(1,j) = 0.d0
          ausr(2,j) = 0.d0
          ausr(3,j) = 0.d0
        end do
c If required, apply non-gravitational and user-defined forces
c ##A38,12##
        if (opt(8).eq.1) call mfo_user (time,jcen,nbod,nbig,m,x,v,ausr,
     %    opt,optr,ngf,opti,K2,AU,MSUN)
c ##A38,12##
        if (ngflag.eq.1.or.ngflag.eq.3) call mfo_ngf (nbod,x,v,angf,ngf)
      end if
c
c Advance interaction Hamiltonian for H/2
      do j = 2, nbod
        v(1,j) = v(1,j)  +  hby2 * (angf(1,j) + ausr(1,j) + a(1,j))
        v(2,j) = v(2,j)  +  hby2 * (angf(2,j) + ausr(2,j) + a(2,j))
        v(3,j) = v(3,j)  +  hby2 * (angf(3,j) + ausr(3,j) + a(3,j))
      end do
c
c Save current coordinates and velocities
c ##A38,38##
      call mco_iden (time,jcen,nbod,nbig,h0,m,x,v,x0,v0,ngf,ngflag,opt,
     %  optr,opti,K2,AU,MSUN)
c ##A38,38##
c
c Advance Keplerian Hamiltonian (Jacobi/helio coords for Big/Small bodies)
      call mco_h2j (time,jcen,nbig,nbig,h0,m,x,v,xj,vj,ngf,ngflag,opt)
      do j = 2, nbig
        iflag = 0
        call drift_one (gm(j),xj(1,j),xj(2,j),xj(3,j),vj(1,j),
     %    vj(2,j),vj(3,j),h0,iflag)
      end do
      do j = nbig + 1, nbod
        iflag = 0
        call drift_one (m(1),x(1,j),x(2,j),x(3,j),v(1,j),v(2,j),
     %    v(3,j),h0,iflag)
      end do
      call mco_j2h (time,jcen,nbig,nbig,h0,m,xj,vj,x,v,ngf,ngflag,opt)
c
c Check for close-encounter minima during drift step
      temp = time + h0
c ##A6,39##
c ##A22,13##
c ##E14,8##
      call mce_stat (temp,h0,rcen,nbod,nbig,m,x0,v0,x,v,rce,rphys,nclo,
     %  iclo,jclo,dclo,tclo,ixvclo,jxvclo,nhit,ihit,jhit,chit,dhit,thit,
     %  thit1,nowflag,stat,outfile(3),mem,lmem,opti,nbclo,bclo,aux,
     %  flagce(2),index,nbod,0,opt(3),tstart,id,nelim,tcol)
c ##E14,8##
c ##A22,13##
c ##A6,39##
c ##A6,23##
c      call mce_stat2 (time,h0,nbod,nbig,m,x0,v0,x,v,rce,rphys,nclo2,
c     %  iclo2,jclo2,dclo2,tclo2,ixvclo2,jxvclo2,stat,mem,lmem,opti,
c     %  nbclo,bclo,aux,flagce(2))
c ##A6,23##
c
c ##A36,1##
c
c If collisions occurred, resolve the collision and return a flag
c ##A22,49##
        if ((nhit.gt.0.and.opt(2).ne.0).or.nelim.gt.0) then
c ##A22,49##
c ##A6,5##
          nhit2 = 0
          do k = 1, nhit
c ##A22,19##
            if (chit(k).gt.0) nhit2 = 1
c ##A22,19##
          end do
c ##A22,50##
          if (nhit2.gt.0.or.nelim.gt.0) then
c ##A22,50##
            if (opt(1).eq.1) return
c ##E5,5##
c ##A6,36##
c ##E19,13##
            call mio_cestored (rcen,rmax,nbod,m,nclo,iclo,jclo,opt(4),
     %      tclo,dclo,ixvclo,jxvclo,nstored,aux,cce,bclo,algor,optr)
c ##E19,13##
c ##A6,36##
c ##E5,5##
c ##A24,13##
c ##AN28,129##
            call mce_criteria (tcol,tstart,nbod,algor,opt(3),m,id,
     %      opti,optr,mem,lmem,nbclo,nstored,K2)
c ##AN28,129##
c ##A24,13##
c ##A23,11##
c ##AN28,52##
c ##A32,31##
c ##A35,46##
            call mce_header (tstart,algor,jcen,rcen,rmax,nbod,m,s,rho,
     %      id,opt,outfile(2),nbclo,bclo,nstored,nbig,K2,AU,MSUN,optr,
     %      idtag)
c ##A35,46##
c ##A32,31##
c ##AN28,52##
c ##A23,11##
            call mio_ceflush (opt(4),outfile(2),nstored,cce)
c ##A6,37##
            nclo = 0
c ##A6,37##
            flagce(1) = 1
            flagce(2) = 0
          end if
c ##A6,5##
          do k = 1, nhit
c ##A22,20##
            if (chit(k).gt.0) then
c ##A22,20##
              i = ihit(k)
              j = jhit(k)
c ##A11,13##
c ##A22,21##
c ##A19,178##
c ##A19,212##
              call mce_coll (thit(k),tstart,en(3),jcen,i,j,nbod,nbig,
     %          m,x,v,s,rphys,stat,id,opt,mem,lmem,outfile(3),opti,
     %          chit(k),nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,
     %          optr,algor,K2,rho)
c ##A19,212##
c ##A19,178##
c ##A22,21##
c ##A11,13##
              colflag = colflag + 1
            end if
          end do
        end if
c ##A36,1##
c
c Advance interaction Hamiltonian for H/2
      call mfo_mvs (jcen,nbod,nbig,m,x,xj,a,stat)
c ##A38,13##
      if (opt(8).eq.1) call mfo_user (time,jcen,nbod,nbig,m,x,v,ausr,
     %  opt,optr,ngf,opti,K2,AU,MSUN)
c ##A38,13##
      if (ngflag.eq.1.or.ngflag.eq.3) call mfo_ngf (nbod,x,v,angf,ngf)
c
      do j = 2, nbod
        v(1,j) = v(1,j)  +  hby2 * (angf(1,j) + ausr(1,j) + a(1,j))
        v(2,j) = v(2,j)  +  hby2 * (angf(2,j) + ausr(2,j) + a(2,j))
        v(3,j) = v(3,j)  +  hby2 * (angf(3,j) + ausr(3,j) + a(3,j))
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MDT_RA15.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Integrates NBOD bodies (of which NBIG are Big) for one timestep H0 using
c Everhart's RA15 integrator algorithm. The accelerations are calculated
c using the subroutine FORCE. The accuracy of the step is approximately 
c determined by the tolerance parameter TOL.
c
c Based on RADAU by E. Everhart, Physics Department, University of Denver.
c Comments giving equation numbers refer to Everhart (1985) ``An Efficient
c Integrator that Uses Gauss-Radau Spacings'', in The Dynamics of Comets:
c Their Origin and Evolution, p185-202, eds. A. Carusi & G. B. Valsecchi,
c pub Reidel. (A listing of the original subroutine is also given in this 
c paper.)
c
c DTFLAG = 0 implies first ever call to this subroutine, 
c        = 1 implies first call since number/masses of objects changed.
c        = 2 normal call
c
c N.B. Input/output must be in coordinates with respect to the central body.
c ===
c
c------------------------------------------------------------------------------
c
c ##A19,85##
c ##AN28,89##
c ##A35,66##
c ##A39,23## 
c ##A43,10##
      subroutine mdt_ra15 (time,t,tdid,tol,jcen,nbod,nbig,mass,x1,v1,
     %  spin,rphys,rcrit,ngf,stat,dtflag,ngflag,opt,nce,ice,jce,force,
     %  nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xvc,yvc,zvc,optr,opti,
     %  algor,apot,K2,AU,MSUN,idtag,chk,lapla2,tstart)
c ##A43,10##
c ##A39,23## 
c ##A35,66##
c ##AN28,89##
c ##A19,85##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,dtflag,ngflag,opt(9),stat(nbod)
      integer nce,ice(nce),jce(nce)
      real*8 time,t,tdid,tol,jcen(3),mass(nbod)
      real*8 x1(3*nbod),v1(3*nbod),spin(3*nbod)
      real*8 ngf(4,nbod),rphys(nbod),rcrit(nbod)
c ##A19,86##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xvc(noc),yvc(noc),zvc(noc),mc(noc),dens(noc)
      integer algor
      real*8 optr(76)
      integer opti(90)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
c ##A19,86##
c ##AN28,90##
      real*8 K2,AU,MSUN
c ##AN28,90##
c ##A35,67##
      integer idtag(nbod)
c ##A35,67##
      external force
c ##A39,24## 
      real*8 chk(3,nbod)
c ##A39,24## 
c ##A43,11##
      integer lapla2(nbod)
      real*8 tstart
c ##A43,11##
c
c Local
      integer nv,niter,j,k,n
      real*8 x(3*NMAX),v(3*NMAX),a(3*NMAX),a1(3*NMAX)
      real*8 g(7,3*NMAX),b(7,3*NMAX),e(7,3*NMAX)
      real*8 h(8),xc(8),vc(7),c(21),d(21),r(28),s(9)
      real*8 q,q2,q3,q4,q5,q6,q7,temp,gk
c
c------------------------------------------------------------------------------
c
      save h,xc,vc,c,d,r,b,e
c
c Gauss-Radau spacings for substeps within a sequence, for the 15th order 
c integrator. The sum of the H values should be 3.733333333333333
c
      data h/          0.d0,.0562625605369221d0,.1802406917368924d0,
     %  .3526247171131696d0,.5471536263305554d0,.7342101772154105d0,
     %  .8853209468390958d0,.9775206135612875d0/
c
c Constant coefficients used in series expansions for X and V
c  XC: 1/2,  1/6,  1/12, 1/20, 1/30, 1/42, 1/56, 1/72
c  VC: 1/2,  1/3,  1/4,  1/5,  1/6,  1/7,  1/8
      data xc/.5d0,.1666666666666667d0,.08333333333333333d0,.05d0,
     %  .03333333333333333d0,.02380952380952381d0,.01785714285714286d0,
     %  .01388888888888889d0/
      data vc/.5d0,.3333333333333333d0,.25d0,.2d0,
     %  .1666666666666667d0,.1428571428571429d0,.125d0/
c
c If this is first call to the subroutine, set values of the constant arrays
c (R = R21, R31, R32, R41, R42, R43 in Everhart's paper.)
      if (dtflag.eq.0) then
        n = 0
        do j = 2, 8
          do k = 1, j - 1
            n = n + 1
            r(n) = 1.d0 / (h(j) - h(k))
          end do
        end do
c
c Constants to convert between B and G arrays (C = C21, C31, C32, C41, C42...)
        c(1) = - h(2)
        d(1) =   h(2)
        n = 1
        do j = 3, 7
          n = n + 1
          c(n) = -h(j) * c(n-j+2)
          d(n) =  h(2) * d(n-j+2)
          do k = 3, j - 1
            n = n + 1
            c(n) = c(n-j+1)  -  h(j) * c(n-j+2)
            d(n) = d(n-j+1)  +  h(k) * d(n-j+2)
          end do
          n = n + 1
          c(n) = c(n-j+1) - h(j)
          d(n) = d(n-j+1) + h(j)
        end do
c
        dtflag = 1
      end if
c
      nv = 3 * nbod
  100 continue
c
c If this is first call to subroutine since number/masses of objects changed
c do 6 iterations and initialize B, E arrays, otherwise do 2 iterations.
      if (dtflag.eq.1) then
        niter = 6
        do j = 4, nv
          do k = 1, 7
            b (k,j) = 0.d0
            e (k,j) = 0.d0
          end do
        end do
      else
        niter = 2
      end if
c
c Calculate forces at the start of the sequence
c ##A19,87##
c ##AN28,105##
c ##A38,125##
c ##A39,43##
c ##A43,39##
      call force (time,jcen,nbod,nbig,mass,x1,v1,spin,rcrit,a1,stat,ngf,
     %  ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xvc,
     %  yvc,zvc,optr,opti,algor,apot,K2,AU,MSUN,chk,lapla2,tstart)
c ##A43,39##
c ##A39,43##
c ##A38,125##
c ##AN28,105##
c ##A19,87##
c
c Find G values from B values predicted at the last call (Eqs. 7 of Everhart)
      do k = 4, nv
        g(1,k) = b(7,k)*d(16) + b(6,k)*d(11) + b(5,k)*d(7)
     %         + b(4,k)*d(4)  + b(3,k)*d(2)  + b(2,k)*d(1)  + b(1,k)
        g(2,k) = b(7,k)*d(17) + b(6,k)*d(12) + b(5,k)*d(8)
     %         + b(4,k)*d(5)  + b(3,k)*d(3)  + b(2,k)
        g(3,k) = b(7,k)*d(18) + b(6,k)*d(13) + b(5,k)*d(9)
     %         + b(4,k)*d(6)  + b(3,k)
        g(4,k) = b(7,k)*d(19) + b(6,k)*d(14) + b(5,k)*d(10) + b(4,k)
        g(5,k) = b(7,k)*d(20) + b(6,k)*d(15) + b(5,k)
        g(6,k) = b(7,k)*d(21) + b(6,k)
        g(7,k) = b(7,k)
      end do
c
c------------------------------------------------------------------------------
c
c  MAIN  LOOP  STARTS  HERE
c
c For each iteration (six for first call to subroutine, two otherwise)...
      do n = 1, niter
c
c For each substep within a sequence...
        do j = 2, 8
c
c Calculate position predictors using Eqn. 9 of Everhart
          s(1) = t * h(j)
          s(2) = s(1) * s(1) * .5d0
          s(3) = s(2) * h(j) * .3333333333333333d0
          s(4) = s(3) * h(j) * .5d0
          s(5) = s(4) * h(j) * .6d0
          s(6) = s(5) * h(j) * .6666666666666667d0
          s(7) = s(6) * h(j) * .7142857142857143d0
          s(8) = s(7) * h(j) * .75d0
          s(9) = s(8) * h(j) * .7777777777777778d0
c
          do k = 4, nv
            x(k) = s(9)*b(7,k) + s(8)*b(6,k) + s(7)*b(5,k)
     %           + s(6)*b(4,k) + s(5)*b(3,k) + s(4)*b(2,k)
     %           + s(3)*b(1,k) + s(2)*a1(k)  + s(1)*v1(k) + x1(k)
          end do
c
c If necessary, calculate velocity predictors too, from Eqn. 10 of Everhart
          if (ngflag.ne.0) then
            s(1) = t * h(j)
            s(2) = s(1) * h(j) * .5d0
            s(3) = s(2) * h(j) * .6666666666666667d0
            s(4) = s(3) * h(j) * .75d0
            s(5) = s(4) * h(j) * .8d0
            s(6) = s(5) * h(j) * .8333333333333333d0
            s(7) = s(6) * h(j) * .8571428571428571d0
            s(8) = s(7) * h(j) * .875d0
c
            do k = 4, nv
              v(k) = s(8)*b(7,k) + s(7)*b(6,k) + s(6)*b(5,k)
     %             + s(5)*b(4,k) + s(4)*b(3,k) + s(3)*b(2,k)
     %             + s(2)*b(1,k) + s(1)*a1(k)  + v1(k)
            end do
          end if
c
c Calculate forces at the current substep
c ##A19,88##
c ##AN28,106##
c ##A38,126##
c ##A39,44##
c ##A43,40##
          call force (time,jcen,nbod,nbig,mass,x,v,spin,rcrit,a,stat,
     %      ngf,ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,
     %      dens,mc,xvc,yvc,zvc,optr,opti,algor,apot,K2,AU,MSUN,chk,
     %      lapla2,tstart)
c ##A43,40##
c ##A39,44##
c ##A38,126##
c ##AN28,106##
c ##A19,88##
c
c Update G values using Eqs. 4 of Everhart, and update B values using Eqs. 5
          if (j.eq.2) then
            do k = 4, nv
              temp = g(1,k)
              g(1,k) = (a(k) - a1(k)) * r(1)
              b(1,k) = b(1,k) + g(1,k) - temp
            end do
            goto 300
          end if
          if (j.eq.3) then
            do k = 4, nv
              temp = g(2,k)
              gk = a(k) - a1(k)
              g(2,k) = (gk*r(2) - g(1,k))*r(3)
              temp = g(2,k) - temp
              b(1,k) = b(1,k)  +  temp * c(1)
              b(2,k) = b(2,k)  +  temp
            end do
            goto 300
          end if
          if (j.eq.4) then
            do k = 4, nv
              temp = g(3,k)
              gk = a(k) - a1(k)
              g(3,k) = ((gk*r(4) - g(1,k))*r(5) - g(2,k))*r(6)
              temp = g(3,k) - temp
              b(1,k) = b(1,k)  +  temp * c(2)
              b(2,k) = b(2,k)  +  temp * c(3)
              b(3,k) = b(3,k)  +  temp
            end do
            goto 300
          end if
          if (j.eq.5) then
            do k = 4, nv
              temp = g(4,k)
              gk = a(k) - a1(k)
              g(4,k) = (((gk*r(7) - g(1,k))*r(8) - g(2,k))*r(9)
     %               - g(3,k))*r(10)
              temp = g(4,k) - temp
              b(1,k) = b(1,k)  +  temp * c(4)
              b(2,k) = b(2,k)  +  temp * c(5)
              b(3,k) = b(3,k)  +  temp * c(6)
              b(4,k) = b(4,k)  +  temp
            end do
            goto 300
          end if
          if (j.eq.6) then
            do k = 4, nv
              temp = g(5,k)
              gk = a(k) - a1(k)
              g(5,k) =  ((((gk*r(11) - g(1,k))*r(12) - g(2,k))*r(13)
     %               - g(3,k))*r(14) - g(4,k))*r(15)
              temp = g(5,k) - temp
              b(1,k) = b(1,k)  +  temp * c(7)
              b(2,k) = b(2,k)  +  temp * c(8)
              b(3,k) = b(3,k)  +  temp * c(9)
              b(4,k) = b(4,k)  +  temp * c(10)
              b(5,k) = b(5,k)  +  temp
            end do
            goto 300
          end if
          if (j.eq.7) then
            do k = 4, nv
              temp = g(6,k)
              gk = a(k) - a1(k)
              g(6,k) = (((((gk*r(16) - g(1,k))*r(17) - g(2,k))*r(18)
     %               - g(3,k))*r(19) - g(4,k))*r(20) - g(5,k))*r(21)
              temp = g(6,k) - temp
              b(1,k) = b(1,k)  +  temp * c(11)
              b(2,k) = b(2,k)  +  temp * c(12)
              b(3,k) = b(3,k)  +  temp * c(13)
              b(4,k) = b(4,k)  +  temp * c(14)
              b(5,k) = b(5,k)  +  temp * c(15)
              b(6,k) = b(6,k)  +  temp
            end do
            goto 300
          end if
          if (j.eq.8) then
            do k = 4, nv
              temp = g(7,k)
              gk = a(k) - a1(k)
              g(7,k) = ((((((gk*r(22) - g(1,k))*r(23) - g(2,k))*r(24)
     %                - g(3,k))*r(25) - g(4,k))*r(26) - g(5,k))*r(27)
     %                - g(6,k))*r(28)
              temp = g(7,k) - temp
              b(1,k) = b(1,k)  +  temp * c(16)
              b(2,k) = b(2,k)  +  temp * c(17)
              b(3,k) = b(3,k)  +  temp * c(18)
              b(4,k) = b(4,k)  +  temp * c(19)
              b(5,k) = b(5,k)  +  temp * c(20)
              b(6,k) = b(6,k)  +  temp * c(21)
              b(7,k) = b(7,k)  +  temp
            end do
          end if
 300      continue
        end do
      end do
c
c------------------------------------------------------------------------------
c
c  END  OF  MAIN  LOOP
c
c Estimate suitable sequence size for the next call to subroutine (Eqs. 15, 16)
      temp = 0.d0
      do k = 4, nv
        temp = max( temp, abs( b(7,k) ) )
      end do
      temp = temp / (72.d0 * abs(t)**7)
      tdid = t
      if (temp.eq.0) then
        t = tdid * 1.4d0
      else
        t = sign( (tol/temp)**(1.d0/9.d0), tdid )
      end if
c
c If sequence size for the first subroutine call is too big, go back and redo
c the sequence using a smaller size.
      if (dtflag.eq.1.and.abs(t/tdid).lt.1) then
        t = t * .8d0
        goto 100
      end if
c
c If new sequence size is much bigger than the current one, reduce it
      if (abs(t/tdid).gt.1.4d0) t = tdid * 1.4d0
c
c Find new position and velocity values at end of the sequence (Eqs. 11, 12)
      temp = tdid * tdid
      do k = 4 , nv
        x1(k) = (xc(8)*b(7,k) + xc(7)*b(6,k) + xc(6)*b(5,k)
     %        +  xc(5)*b(4,k) + xc(4)*b(3,k) + xc(3)*b(2,k)
     %        +  xc(2)*b(1,k) + xc(1)*a1(k))*temp + v1(k)*tdid + x1(k)
c
        v1(k) = (vc(7)*b(7,k) + vc(6)*b(6,k) + vc(5)*b(5,k)
     %        +  vc(4)*b(4,k) + vc(3)*b(3,k) + vc(2)*b(2,k)
     %        +  vc(1)*b(1,k) + a1(k))*tdid + v1(k)
      end do
c
c Predict new B values to use at the start of the next sequence. The predicted
c values from the last call are saved as E. The correction, BD, between the
c actual and predicted values of B is applied in advance as a correction.
      q = t / tdid
      q2 = q  * q
      q3 = q  * q2
      q4 = q2 * q2
      q5 = q2 * q3
      q6 = q3 * q3
      q7 = q3 * q4
c
      do k = 4, nv
        s(1) = b(1,k) - e(1,k)
        s(2) = b(2,k) - e(2,k)
        s(3) = b(3,k) - e(3,k)
        s(4) = b(4,k) - e(4,k)
        s(5) = b(5,k) - e(5,k)
        s(6) = b(6,k) - e(6,k)
        s(7) = b(7,k) - e(7,k)
c
c Estimate B values for the next sequence (Eqs. 13 of Everhart).
        e(1,k) = q* (b(7,k)* 7.d0 + b(6,k)* 6.d0 + b(5,k)* 5.d0
     %         +     b(4,k)* 4.d0 + b(3,k)* 3.d0 + b(2,k)*2.d0 + b(1,k))
        e(2,k) = q2*(b(7,k)*21.d0 + b(6,k)*15.d0 + b(5,k)*10.d0
     %         +     b(4,k)* 6.d0 + b(3,k)* 3.d0 + b(2,k))
        e(3,k) = q3*(b(7,k)*35.d0 + b(6,k)*20.d0 + b(5,k)*10.d0
     %         +     b(4,k)*4.d0  + b(3,k))
        e(4,k) = q4*(b(7,k)*35.d0 + b(6,k)*15.d0 + b(5,k)*5.d0 + b(4,k))
        e(5,k) = q5*(b(7,k)*21.d0 + b(6,k)*6.d0  + b(5,k))
        e(6,k) = q6*(b(7,k)*7.d0  + b(6,k))
        e(7,k) = q7* b(7,k)
c
        b(1,k) = e(1,k) + s(1)
        b(2,k) = e(2,k) + s(2)
        b(3,k) = e(3,k) + s(3)
        b(4,k) = e(4,k) + s(4)
        b(5,k) = e(5,k) + s(5)
        b(6,k) = e(6,k) + s(6)
        b(7,k) = e(7,k) + s(7)
      end do
      dtflag = 2
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MDT_CB.FOR    (ErikSoft   13 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Integrates NBOD bodies (of which NBIG are Big) for one timestep H
c using a second-order hybrid close-binary symplectic integrator. Uses
c different timesteps for the binary versus the planetary orbits.
c
c DTFLAG = 0 implies first ever call to this subroutine, 
c        = 1 implies first call since number/masses of objects changed.
c        = 2 normal call
c
c N.B. Input/output must be in close-binary coordinates.
c ===
c
c------------------------------------------------------------------------------
c
c ##A6,30##
c ##A19,111##
c ##A22,38##
c ##E14,19##
c ##AN28,63##
c ##A35,76##
c ##A39,30## 
c ##A43,14##
      subroutine mdt_cb (time,tstart,h0,tol,rmax,en,am,jcen,rcen,nbod,
     %  nbig,m,x,v,s,rphys,rcrit,rce,stat,id,ngf,algor,opt,dtflag,
     %  ngflag,opflag,colflag,nclo,iclo,jclo,dclo,tclo,ixvclo,jxvclo,
     %  outfile,mem,lmem,nclo2,iclo2,jclo2,dclo2,tclo2,ixvclo2,jxvclo2,
     %  nstored,nbclo,bclo,aux,cce,opti,rho,flagce,nov,nop,noc,xv,yv,zv,
     %  noe,kkk,dens,mc,xc,yc,zc,optr,apot,nelim,tcol,K2,AU,MSUN,coord,
     %  bcoord,idtag,chk,lapla2)
c ##A43,14##
c ##A39,30## 
c ##A35,76##
c ##AN28,63##
c ##E14,19##
c ##A22,38##
c ##A19,111##
c ##A6,30##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,stat(nbod),algor,opt(9),dtflag,ngflag,opflag
      integer colflag,lmem(NMESS),nclo,iclo(CMAX),jclo(CMAX)
      real*8 time,tstart,h0,tol,rmax,en(3),am(3),jcen(3),rcen
      real*8 m(nbod),x(3,nbod),v(3,nbod),s(3,nbod),rphys(nbod)
      real*8 rce(nbod),rcrit(nbod),ngf(4,nbod),tclo(CMAX),dclo(CMAX)
      real*8 ixvclo(6,CMAX),jxvclo(6,CMAX)
      character*80 outfile(4),mem(NMESS)
      character*8 id(nbod)
c ##A6,28##
      integer nclo2,iclo2(CMAX),jclo2(CMAX)
      real*8 dclo2(CMAX),tclo2(CMAX)
      real*8 ixvclo2(6,CMAX),jxvclo2(6,CMAX)
      integer nstored
      integer nbclo,bclo(nbod)
      character*1 aux(CMAX)
      character*107 cce(FMAX)
      integer opti(90)
      real*8 rho(nbod)
      integer flagce(2)
c ##A6,28##
c ##A19,112##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      real*8 optr(76)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      external coord,bcoord
c ##A19,112##
c ##A22,39##
      integer nelim
c ##A22,39##
c ##E14,18##
      real*8 tcol
c ##E14,18##
c ##AN28,62##
      real*8 K2,AU,MSUN
c ##AN28,62##
c ##A35,77##
      integer idtag(nbod)
c ##A35,77##
c ##A39,17## 
      real*8 chk(3,nbod)
c ##A39,17## 
c ##A43,15##
      integer lapla2(nbod)
c ##A43,15##
c
c Local
      integer j,nce,ice(NMAX),jce(NMAX),ce(NMAX),iflag,isub,nsub
      real*8 a(3,NMAX),hby2,hrec,x0(3,NMAX),v0(3,NMAX),mvsum(3),temp
      real*8 mbin,hbin,gmbin,hsub,tmp0,tmp1,tmp2,abin,amin
      external mfo_hkce
c
c------------------------------------------------------------------------------
c
      save a, hrec, nsub, hsub, hbin, gmbin
      nclo = 0
c ##A6,29##
c      nclo2 = 0
c ##A6,29##
      colflag = 0
      mbin = m(1) + m(2)
      gmbin = m(1) * m(1) / mbin 
c gmbin = m(1) * m(1) / mbin. Para deduzir a equação dessa constante que é usada nas subrotinas mco_x2a e drift_one com as coordenadas e velocidades do corpo 2 temos que relacionar suas coordenadas heliocêntricas com suas coordenadas em close-binary.
c Temos que a coordenada e a velocidade antigas do corpo 2 para a implementação no mercury são dadas por x(2)=X(2) e v(2)=mbin/m(1)*V(2) (essa coordenada e essa velocidade são do movimento kleperiano (2 corpos), logo qualquer outra coordenada ou velocidade com indíce diferente de 2 deve ser setada como 0) respectivamente, onde X(2) e V(2) são a coordenada e a velocidade do corpo 2 em coordenadas close-binary e x(2) e v(2) são a coordenada e a velocidade do corpo 2 em coordenadas heliocêntricas.
c Vamos ver agora como ficam na subrotina mco_x2a as equações para o raio-vetor r e o semi-eixo maior a nas novas coordenadas. O raciocício é análogo para a subrotina drift_one.
c r(2) = (x(2)*x(2)+y(2)*y(2)+z(2)*z(2))^(1/2) = (X(2)*X(2)+Y(2)*Y(2)+Z(2)*Z(2))^(1/2) => r(2) = R(2).
c v(2)^2 = v(2)x*v(2)x+v(2)y*v(2)y+v(2)z*v(2)z => v(2)^2 = (mbin/m(1))^2*V(2)^2.
c Para a equação do semi-eixo maior a temos que o gm antigo é dado por gm = m(1) + m(2) = mbin. Logo,
c a(2) = gm*r(2)/(2*gm-r(2)*v(2)^2) => A(2) = mbin*R(2)/(2*mbin-R(2)*(mbin/m(1))^2*V(2)^2) = mbin*R(2)/[(mbin/m(1))^2*(2*m(1)^2/mbin-R(2)*V(2)^2)] = m(1)^2/mbin*R(2)/(2*m(1)^2/mbin-R(2)*V(2)^2) => A(2) = gmbin*R(2)/(2*gmbin-R(2)*V(2)^2).
c O raciocínio é análogo para o caso do gmbin da subrotina mdt_wb, mas setando 0 nas coordenadas e velocidades dos corpos com índice diferente de 2.
      hby2 = h0 * .5d0
c
c Set the number of binary substeps per timestep
      if (dtflag.eq.0) then
        amin = HUGE
        call mco_x2a (gmbin,x(1,2),x(2,2),x(3,2),v(1,2),v(2,2),v(3,2),
     %    abin,tmp1,tmp2)
c
        do j = 3, nbod
          temp = m(1) + m(2) + m(j)
          call mco_x2a (temp,x(1,j),x(2,j),x(3,j),v(1,j),v(2,j),v(3,j),
     %      tmp0,tmp1,tmp2)
          amin = min(amin, tmp0)
        end do
c ##A14,1##
        if (nbod.eq.2) amin = min(amin, abin)
c ##A14,1##
        nsub = int(0.5d0 + (amin/abin)**1.5)
        hsub = hby2 / nsub
        hbin = hby2 / nsub * mbin / m(1)
      end if
c
c If accelerations from previous call are not valid, calculate them now
      if (dtflag.ne.2) then
        if (dtflag.eq.0) hrec = h0
        do j = 3, nbod
          a(1,j) = 0.d0
          a(2,j) = 0.d0
          a(3,j) = 0.d0
        end do
        call mfo_drct (3,nbod,nbig,m,x,rcrit,a,stat)
        dtflag = 2
      end if
c
c Advance direct-interaction Hamiltonian for H/2
      do j = 3, nbod
        v(1,j) = v(1,j)  +  hby2 * a(1,j)
        v(2,j) = v(2,j)  +  hby2 * a(2,j)
        v(3,j) = v(3,j)  +  hby2 * a(3,j)
      end do
c
c Advance Binary Kepler for H/(2N), then indirect Hamiltonian for H/(2N)
      do isub = 1, nsub
        call mfo_cb (jcen,nbod,nbig,m,x,rcrit,a,stat)
        do j = 2, nbod
          v(1,j) = v(1,j)  +  hsub * a(1,j)
          v(2,j) = v(2,j)  +  hsub * a(2,j)
          v(3,j) = v(3,j)  +  hsub * a(3,j)
        end do
        call drift_one (gmbin,x(1,2),x(2,2),x(3,2),v(1,2),v(2,2),v(3,2),
     %    hbin,iflag)
      end do
c
c Advance solar Hamiltonian for H/2
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      do j = 3, nbod
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
      temp = hby2 / mbin
      mvsum(1) = temp * mvsum(1)
      mvsum(2) = temp * mvsum(2)
      mvsum(3) = temp * mvsum(3)
      do j = 3, nbod
        x(1,j) = x(1,j) + mvsum(1)
        x(2,j) = x(2,j) + mvsum(2)
        x(3,j) = x(3,j) + mvsum(3)
      end do
c
c Save the current coordinates and velocities
c ##A38,39##
      call mco_iden (time,jcen,nbod,nbig,h0,m,x,v,x0,v0,ngf,ngflag,opt,
     %  optr,opti,K2,AU,MSUN)
c ##A38,39##
c
c Advance H_K for H
      do j = 3, nbod
        iflag = 0
        call drift_one (mbin,x(1,j),x(2,j),x(3,j),v(1,j),v(2,j),
     %    v(3,j),h0,iflag)
      end do
c
c Check whether any object separations were < R_CRIT whilst advancing H_K
      call mce_snif (h0,3,nbod,nbig,x0,v0,x,v,rcrit,ce,nce,ice,jce)
c
c If objects had close encounters, advance H_K using Bulirsch-Stoer instead
      if (nce.gt.0) then
        do j = 3, nbod
          if (ce(j).ne.0) then
            x(1,j) = x0(1,j)
            x(2,j) = x0(2,j)
            x(3,j) = x0(3,j)
            v(1,j) = v0(1,j)
            v(2,j) = v0(2,j)
            v(3,j) = v0(3,j)
          end if
        end do
c ##A6,27##
c ##A19,118##
c ##A22,40##
c ##E14,17##
c ##ANEO27,13##
c ##AN28,61##
c ##A35,90##
c ##A39,67##
c ##A43,41##
        call mdt_hkce (time,tstart,h0,hrec,tol,rmax,en(3),jcen,rcen,
     %    nbod,nbig,m,x,v,s,rphys,rcrit,rce,stat,id,ngf,algor,opt,
     %    ngflag,colflag,ce,nce,ice,jce,nclo,iclo,jclo,dclo,tclo,ixvclo,
     %    jxvclo,outfile,mem,lmem,mfo_hkce,nclo2,iclo2,jclo2,dclo2,
     %    tclo2,ixvclo2,jxvclo2,nstored,nbclo,bclo,aux,cce,opti,rho,
     %    flagce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,
     %    apot,nelim,tcol,0,K2,AU,MSUN,coord,bcoord,idtag,chk,lapla2)
c ##A43,41##
c ##A39,67##
c ##A35,90##
c ##AN28,61##
c ##ANEO27,13##
c ##E14,17##
c ##A22,40##
c ##A19,118##
c ##A6,27##
      end if
c
c Advance solar Hamiltonian for H/2
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      do j = 3, nbod
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
      temp = hby2 / mbin
      mvsum(1) = temp * mvsum(1)
      mvsum(2) = temp * mvsum(2)
      mvsum(3) = temp * mvsum(3)
      do j = 3, nbod
        x(1,j) = x(1,j) + mvsum(1)
        x(2,j) = x(2,j) + mvsum(2)
        x(3,j) = x(3,j) + mvsum(3)
      end do
c
c Advance Binary Kepler for H/(2N), then indirect Hamiltonian for H/(2N)
      do isub = 1, nsub
        call drift_one (gmbin,x(1,2),x(2,2),x(3,2),v(1,2),v(2,2),v(3,2),
     %    hbin,iflag)
        call mfo_cb (jcen,nbod,nbig,m,x,rcrit,a,stat)
        do j = 2, nbod
          v(1,j) = v(1,j)  +  hsub * a(1,j)
          v(2,j) = v(2,j)  +  hsub * a(2,j)
          v(3,j) = v(3,j)  +  hsub * a(3,j)
        end do
      end do
c
c Advance interaction Hamiltonian for H/2
      do j = 3, nbod
        a(1,j) = 0.d0
        a(2,j) = 0.d0
        a(3,j) = 0.d0
      end do
      call mfo_drct (3,nbod,nbig,m,x,rcrit,a,stat)
      do j = 3, nbod
        v(1,j) = v(1,j)  +  hby2 * a(1,j)
        v(2,j) = v(2,j)  +  hby2 * a(2,j)
        v(3,j) = v(3,j)  +  hby2 * a(3,j)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MDT_WB.FOR    (ErikSoft   13 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Integrates NBOD bodies (of which NBIG are Big) for one timestep H
c using a second-order hybrid wide-binary symplectic integrator.
c
c DTFLAG = 0 implies first ever call to this subroutine, 
c        = 1 implies first call since number/masses of objects changed.
c        = 2 normal call
c
c N.B. Input/output must be in wide-binary coordinates.
c ===
c
c------------------------------------------------------------------------------
c
c ##A6,34##
c ##A19,113##
c ##A22,41##
c ##E14,22##
c ##AN28,66##
c ##A35,78##
c ##A39,31## 
c ##A43,16##
      subroutine mdt_wb (time,tstart,h0,tol,rmax,en,am,jcen,rcen,nbod,
     %  nbig,m,x,v,s,rphys,rcrit,rce,stat,id,ngf,algor,opt,dtflag,
     %  ngflag,opflag,colflag,nclo,iclo,jclo,dclo,tclo,ixvclo,jxvclo,
     %  outfile,mem,lmem,nclo2,iclo2,jclo2,dclo2,tclo2,ixvclo2,jxvclo2,
     %  nstored,nbclo,bclo,aux,cce,opti,rho,flagce,nov,nop,noc,xv,yv,zv,
     %  noe,kkk,dens,mc,xc,yc,zc,optr,apot,nelim,tcol,K2,AU,MSUN,coord,
     %  bcoord,idtag,chk,lapla2)
c ##A43,16##
c ##A39,31## 
c ##A35,78##
c ##AN28,66##
c ##E14,22##
c ##A22,41##
c ##A19,113##
c ##A6,34##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,stat(nbod),algor,opt(9),dtflag,ngflag,opflag
      integer colflag,lmem(NMESS),nclo,iclo(CMAX),jclo(CMAX)
      real*8 time,tstart,h0,tol,rmax,en(3),am(3),jcen(3),rcen
      real*8 m(nbod),x(3,nbod),v(3,nbod),s(3,nbod),rphys(nbod)
      real*8 rce(nbod),rcrit(nbod),ngf(4,nbod),tclo(CMAX),dclo(CMAX)
      real*8 ixvclo(6,CMAX),jxvclo(6,CMAX)
      character*80 outfile(4),mem(NMESS)
      character*8 id(nbod)
c ##A6,32##
      integer nclo2,iclo2(CMAX),jclo2(CMAX)
      real*8 dclo2(CMAX),tclo2(CMAX)
      real*8 ixvclo2(6,CMAX),jxvclo2(6,CMAX)
      integer nstored
      integer nbclo,bclo(nbod)
      character*1 aux(CMAX)
      character*107 cce(FMAX)
      integer opti(90)
      real*8 rho(nbod)
      integer flagce(2)
c ##A6,32##
c ##A19,114##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      real*8 optr(76)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      external coord,bcoord
c ##A19,114##
c ##A22,42##
      integer nelim
c ##A22,42##
c ##E14,21##
      real*8 tcol
c ##E14,21##
c ##AN28,65##
      real*8 K2,AU,MSUN
c ##AN28,65##
c ##A35,79##
      integer idtag(nbod)
c ##A35,79##
c ##A39,18## 
      real*8 chk(3,nbod)
c ##A39,18##
c ##A43,17##
      integer lapla2(nbod)
c ##A43,17##
c
c Local
      integer j,nce,ice(NMAX),jce(NMAX),ce(NMAX),iflag
      real*8 a(3,NMAX),hby2,hrec,x0(3,NMAX),v0(3,NMAX),mvsum(3),temp
      real*8 msum,gmbin,hbin
      external mfo_hkce
c
c------------------------------------------------------------------------------
c
      save a, hrec, gmbin, hbin
      hby2 = h0 * .5d0
      nclo = 0
c ##A6,33##
c      nclo2 = 0
c ##A6,33##
      colflag = 0
c
c If accelerations from previous call are not valid, calculate them now,
c also the effective central mass and timestep for the binary Kepler drift
      if (dtflag.ne.2) then
        if (dtflag.eq.0) hrec = h0
        call mfo_wb (jcen,nbod,nbig,m,x,rcrit,a,stat)
        dtflag = 2
        msum = 0.d0
        do j = 3, nbod
          msum = msum + m(j)
        end do
        gmbin = (m(1) + msum) * (m(1) + msum) / (m(1) + msum + m(2)) 
        hbin = h0 * (m(1) + msum + m(2)) / (m(1) + msum)
      end if
c
c Advance interaction Hamiltonian for H/2
      do j = 2, nbod
        v(1,j) = v(1,j)  +  hby2 * a(1,j)
        v(2,j) = v(2,j)  +  hby2 * a(2,j)
        v(3,j) = v(3,j)  +  hby2 * a(3,j)
      end do
c
c Advance solar Hamiltonian for H/2
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      do j = 3, nbod
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
c
      temp = hby2 / m(1)
      mvsum(1) = mvsum(1) * temp
      mvsum(2) = mvsum(2) * temp
      mvsum(3) = mvsum(3) * temp
      do j = 3, nbod
        x(1,j) = x(1,j) + mvsum(1)
        x(2,j) = x(2,j) + mvsum(2)
        x(3,j) = x(3,j) + mvsum(3)
      end do
c
c Save the current coordinates and velocities
c ##A38,40##
      call mco_iden (time,jcen,nbod,nbig,h0,m,x,v,x0,v0,ngf,ngflag,opt,
     %  optr,opti,K2,AU,MSUN)
c ##A38,40##
c
c Advance H_K for H
      call drift_one (gmbin,x(1,2),x(2,2),x(3,2),v(1,2),v(2,2),
     %  v(3,2),hbin,iflag)
c
      do j = 3, nbod
        iflag = 0
        temp = m(1)
        call drift_one (temp,x(1,j),x(2,j),x(3,j),v(1,j),v(2,j),
     %    v(3,j),h0,iflag)
      end do
c
c Check whether any object separations were < R_CRIT whilst advancing H_K
      call mce_snif (h0,3,nbod,nbig,x0,v0,x,v,rcrit,ce,nce,ice,jce)
c
c If objects had close encounters, advance H_K using Bulirsch-Stoer instead
      if (nce.gt.0) then
        do j = 3, nbod
          if (ce(j).ne.0) then
            x(1,j) = x0(1,j)
            x(2,j) = x0(2,j)
            x(3,j) = x0(3,j)
            v(1,j) = v0(1,j)
            v(2,j) = v0(2,j)
            v(3,j) = v0(3,j)
          end if
        end do
c ##A6,31##
c ##A19,119##
c ##A22,43##
c ##E14,20##
c ##ANEO27,14##
c ##AN28,64##
c ##A35,91##
c ##A39,68##
c ##A43,42##
        call mdt_hkce (time,tstart,h0,hrec,tol,rmax,en(3),jcen,rcen,
     %    nbod,nbig,m,x,v,s,rphys,rcrit,rce,stat,id,ngf,algor,opt,
     %    ngflag,colflag,ce,nce,ice,jce,nclo,iclo,jclo,dclo,tclo,ixvclo,
     %    jxvclo,outfile,mem,lmem,mfo_hkce,nclo2,iclo2,jclo2,dclo2,
     %    tclo2,ixvclo2,jxvclo2,nstored,nbclo,bclo,aux,cce,opti,rho,
     %    flagce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,
     %    apot,nelim,tcol,0,K2,AU,MSUN,coord,bcoord,idtag,chk,lapla2)
c ##A43,42##
c ##A39,68##
c ##A35,91##
c ##AN28,64##
c ##ANEO27,14##
c ##E14,20##
c ##A22,43##
c ##A19,119##
c ##A6,31##
      end if
c
c Advance solar Hamiltonian for H/2
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      do j = 3, nbod
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
c
      temp = hby2 / m(1)
      mvsum(1) = mvsum(1) * temp
      mvsum(2) = mvsum(2) * temp
      mvsum(3) = mvsum(3) * temp
      do j = 3, nbod
        x(1,j) = x(1,j) + mvsum(1)
        x(2,j) = x(2,j) + mvsum(2)
        x(3,j) = x(3,j) + mvsum(3)
      end do
c
c Advance interaction Hamiltonian for H/2
      call mfo_wb (jcen,nbod,nbig,m,x,rcrit,a,stat)
      do j = 2, nbod
        v(1,j) = v(1,j)  +  hby2 * a(1,j)
        v(2,j) = v(2,j)  +  hby2 * a(2,j)
        v(3,j) = v(3,j)  +  hby2 * a(3,j)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MFO_ALL.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates accelerations on a set of NBOD bodies (of which NBIG are Big)
c due to Newtonian gravitational perturbations, post-Newtonian
c corrections (if required), cometary non-gravitational forces (if required)
c and user-defined forces (if required).
c
c N.B. Input/output must be in coordinates with respect to the central body.
c ===
c
c------------------------------------------------------------------------------
c
c ##A19,93##
c ##AN28,95##
c ##A38,102##
c ##A39,33##
c ##A43,43##
      subroutine mfo_all (time,jcen,nbod,nbig,m,x,v,s,rcrit,a,stat,ngf,
     %  ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,k,dens,mc,xc,
     %  yc,zc,optr,opti,algor,apot,K2,AU,MSUN,chk,lapla2,tstart)
c ##A43,43##
c ##A39,33##
c ##A38,102##
c ##AN28,95##
c ##A19,93##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,ngflag,stat(nbod),opt(9),nce,ice(nce),jce(nce)
      real*8 time,jcen(3),m(nbod),x(3,nbod),v(3,nbod),s(3,nbod)
      real*8 a(3,nbod),ngf(4,nbod),rcrit(nbod)
c ##A19,94##
      integer nov,nop,noc,noe,k
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      integer algor
      real*8 optr(76)
      integer opti(90)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension k(nopmax,noed)
c ##A19,94##
c ##AN28,96##
c ##A38,103##
      real*8 K2,AU,MSUN
c ##A38,103##
c ##AN28,96##
c ##A39,34##
      real*8 chk(3,nbod)
c ##A39,34##
c ##A43,44##
      integer lapla2(nbod)
      real*8 tstart
c ##A43,44##
c
c Local
      integer j
      real*8 acor(3,NMAX),acen(3)
c ##A19,95##
      real*8 tmp
c ##A19,95##
c
c------------------------------------------------------------------------------
c
c Newtonian gravitational forces
c ##A19,96##
c ##AN28,109##
c ##A43,45##
      call mfo_grav (nbod,nbig,m,x,v,a,stat,nov,nop,noc,xv,yv,zv,noe,
     %  k,dens,mc,xc,yc,zc,optr,opti,algor,apot,K2,lapla2)
c ##A43,45##
c ##AN28,109##
c ##A19,96##
c
c Correct for oblateness of the central body
      if (jcen(1).ne.0.or.jcen(2).ne.0.or.jcen(3).ne.0) then
        call mfo_obl (jcen,nbod,m,x,acor,acen)
        do j = 2, nbod
c ##A19,97##
          if (algor.ge.13) then
            tmp = x(1,j)*x(1,j) + x(2,j)*x(2,j) + x(3,j)*x(3,j)
            if (tmp.ge.optr(7)) then
              a(1,j) = a(1,j) + (acor(1,j) - acen(1))
              a(2,j) = a(2,j) + (acor(2,j) - acen(2))
              a(3,j) = a(3,j) + (acor(3,j) - acen(3))
            end if
          else
            a(1,j) = a(1,j) + (acor(1,j) - acen(1))
            a(2,j) = a(2,j) + (acor(2,j) - acen(2))
            a(3,j) = a(3,j) + (acor(3,j) - acen(3))
          end if
c ##A19,97##
        end do
      end if
c
c Include non-gravitational (cometary jet) accelerations if necessary
      if (ngflag.eq.1.or.ngflag.eq.3) then
        call mfo_ngf (nbod,x,v,acor,ngf)
        do j = 2, nbod
          a(1,j) = a(1,j) + acor(1,j)
          a(2,j) = a(2,j) + acor(2,j)
          a(3,j) = a(3,j) + acor(3,j)
        end do
      end if
c
c Include radiation pressure/Poynting-Robertson drag if necessary
      if (ngflag.eq.2.or.ngflag.eq.3) then
c ##A38,106##
c        call mfo_pr (nbod,nbig,m,x,v,acor,ngf)
        call mfo_pr (time,nbod,nbig,m,x,v,acor,ngf,opt,optr,opti,
     %    K2,AU,MSUN,tstart,algor)
c ##A38,106##
        do j = 2, nbod
          a(1,j) = a(1,j) + acor(1,j)
          a(2,j) = a(2,j) + acor(2,j)
          a(3,j) = a(3,j) + acor(3,j)
        end do
      end if
c
c Include post-Newtonian corrections if required
      if (opt(7).eq.1) then
        call mfo_pn (nbod,nbig,m,x,v,acor)
        do j = 2, nbod
          a(1,j) = a(1,j) + acor(1,j)
          a(2,j) = a(2,j) + acor(2,j)
          a(3,j) = a(3,j) + acor(3,j)
        end do
      end if
c
c Include user-defined accelerations if required
      if (opt(8).eq.1) then
c ##A38,14##
        call mfo_user (time,jcen,nbod,nbig,m,x,v,acor,opt,optr,
     %    ngf,opti,K2,AU,MSUN)
c ##A38,14##
        do j = 2, nbod
          a(1,j) = a(1,j) + acor(1,j)
          a(2,j) = a(2,j) + acor(2,j)
          a(3,j) = a(3,j) + acor(3,j)
        end do
      end if
c
c ##A39,7##
c Include centrifugal accelerations if required
c      if (opti(80).eq.1) then
c        call mfo_chk (time,nbod,nbig+1,m,x,v,acor,opt,optr,
c     %    opti,chk,stat)
c        do j = 2, nbod
c          a(1,j) = a(1,j) + acor(1,j)
c          a(2,j) = a(2,j) + acor(2,j)
c          a(3,j) = a(3,j) + acor(3,j)
c        end do
c      end if
c ##A39,7##
c
c ##A38,144##
      if (algor.ge.13) then
        do j = 2, nbod
          if (opti(72).eq.0) then
            a(1,j) = a(1,j)+2.0d0*optr(6)*v(2,j)+optr(6)*optr(6)*x(1,j)
            a(2,j) = a(2,j)-2.0d0*optr(6)*v(1,j)+optr(6)*optr(6)*x(2,j)
          end if
        end do
      end if
c ##A38,144##
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c     MFO_CB.FOR    (ErikSoft   16 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c
c------------------------------------------------------------------------------
c
      subroutine mfo_cb (jcen,nbod,nbig,m,x,rcrit,a,stat)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod, nbig, stat(nbod)
      real*8 jcen(3), m(nbod), x(3,nbod), a(3,nbod), rcrit(nbod)
c
c Local
      integer k
      real*8 dx,dy,dz,s_1,s2,s_3,tmp1,tmp2,mbin
c
c------------------------------------------------------------------------------
c
      mbin = m(1) + m(2)
c
c Initialize accelerations to zero
      do k = 2, nbod
        a(1,k) = 0.d0
        a(2,k) = 0.d0
        a(3,k) = 0.d0
      end do
c
c Add on terms due to the binary
      do k = 3, nbod
        s2 = x(1,k) * x(1,k)  +  x(2,k) * x(2,k)  +  x(3,k) * x(3,k)
        s_1 = 1.d0 / sqrt(s2)
        s_3 = s_1 * s_1 * s_1
        tmp1 = mbin * s_3
        a(1,k) = a(1,k)  +  tmp1 * x(1,k)
        a(2,k) = a(2,k)  +  tmp1 * x(2,k)
        a(3,k) = a(3,k)  +  tmp1 * x(3,k)
c
        dx = mbin * x(1,k)  +  m(2) * x(1,2)
        dy = mbin * x(2,k)  +  m(2) * x(2,2)
        dz = mbin * x(3,k)  +  m(2) * x(3,2)
        s2 = dx*dx + dy*dy + dz*dz
        s_1 = 1.d0 / sqrt(s2)
        s_3 = s_1 * s_1 * s_1
        tmp1 = mbin * mbin * m(1) * s_3
        tmp2 = mbin * m(1) * m(k) * s_3
        a(1,k) = a(1,k)  -  tmp1 * dx
        a(2,k) = a(2,k)  -  tmp1 * dy
        a(3,k) = a(3,k)  -  tmp1 * dz
        a(1,2) = a(1,2)  -  tmp2 * dx
        a(2,2) = a(2,2)  -  tmp2 * dy
        a(3,2) = a(3,2)  -  tmp2 * dz
c
        dx = mbin * x(1,k)  -  m(1) * x(1,2)
        dy = mbin * x(2,k)  -  m(1) * x(2,2)
        dz = mbin * x(3,k)  -  m(1) * x(3,2)
        s2 = dx*dx + dy*dy + dz*dz
        s_1 = 1.d0 / sqrt(s2)
        s_3 = s_1 * s_1 * s_1
        tmp1 = mbin * mbin * m(2) * s_3
        tmp2 = mbin * m(1) * m(k) * s_3
        a(1,k) = a(1,k)  -  tmp1 * dx
        a(2,k) = a(2,k)  -  tmp1 * dy
        a(3,k) = a(3,k)  -  tmp1 * dz
        a(1,2) = a(1,2)  +  tmp2 * dx
        a(2,2) = a(2,2)  +  tmp2 * dy
        a(3,2) = a(3,2)  +  tmp2 * dz
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MFO_GRAV.FOR    (ErikSoft   3 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates accelerations on a set of NBOD bodies (NBIG of which are Big)
c due to gravitational perturbations by all the other bodies, except that
c Small bodies do not interact with one another.
c
c The positions and velocities are stored in arrays X, V with the format
c (x,y,z) and (vx,vy,vz) for each object in succession. The accelerations 
c are stored in the array A (ax,ay,az).
c
c N.B. All coordinates and velocities must be with respect to central body!!!!
c ===
c------------------------------------------------------------------------------
c
c ##A19,97##
c ##AN28,110##
c ##A43,52##
      subroutine mfo_grav (nbod,nbig,m,x,v,a,stat,nov,nop,noc,xv,yv,zv,
     %  noe,k,d,mc,xc,yc,zc,optr,opti,algor,apot,K2,lapla2)
c ##A43,52##
c ##AN28,110##
c ##A19,97##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod, nbig, stat(nbod)
      real*8 m(nbod), x(3,nbod), v(3,nbod), a(3,nbod)
c ##A19,98##
      integer nov,nop,noc,noe,k
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),d(noc)
      integer algor
      real*8 optr(76)
      integer opti(90)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension k(nopmax,noed)
c ##A19,98##
c ##AN28,111##
      real*8 K2
c ##AN28,111##
c ##A43,53##
      integer lapla2(nbod)
c ##A43,53##
c
c Local
      integer i, j
      real*8 sx, sy, sz, dx, dy, dz, tmp1, tmp2, s_1, s2, s_3, r3(NMAX)
c ##A19,99##
      integer novl,nopl,noel,kl
      real*8 xl(nov),yl(nov),zl(nov)
      integer i0,ilay,l
      real*8 vx,vy,vz,del,inc
      real*8 xp,yp,zp
      integer ix,iy,iz
      real*8 a2,b2,c2
      dimension noel(nop)
      dimension kl(nopmax,noed)
c ##A19,99##
c
c------------------------------------------------------------------------------
c
c ##A19,100##
      del = 1.d0 / opti(21)
c central point (origin)
      xl(1) = 0.0
      yl(1) = 0.0
      zl(1) = 0.0
c
      a2  = optr(9)
      b2  = optr(10)
      c2  = optr(11)
c ##A19,100##
c
      sx = 0.d0
      sy = 0.d0
      sz = 0.d0
      do i = 2, nbod
        a(1,i) = 0.d0
        a(2,i) = 0.d0
        a(3,i) = 0.d0
        s2 = x(1,i)*x(1,i) + x(2,i)*x(2,i) + x(3,i)*x(3,i)
        s_1  = 1.d0 / sqrt(s2)
        r3(i) = s_1 * s_1 * s_1
      end do
c
      do i = 2, nbod
        tmp1 = m(i) * r3(i)
        sx = sx  -  tmp1 * x(1,i)
        sy = sy  -  tmp1 * x(2,i)
        sz = sz  -  tmp1 * x(3,i)
      end do
c
c Direct terms
      do i = 2, nbig
        do j = i + 1, nbod
          dx = x(1,j) - x(1,i)
          dy = x(2,j) - x(2,i)
          dz = x(3,j) - x(3,i)
          s2 = dx*dx + dy*dy + dz*dz
          s_1 = 1.d0 / sqrt(s2)
          s_3 = s_1 * s_1 * s_1
          tmp1 = s_3 * m(i)
          tmp2 = s_3 * m(j)
          a(1,j) = a(1,j)  -  tmp1 * dx
          a(2,j) = a(2,j)  -  tmp1 * dy
          a(3,j) = a(3,j)  -  tmp1 * dz
          a(1,i) = a(1,i)  +  tmp2 * dx
          a(2,i) = a(2,i)  +  tmp2 * dy
          a(3,i) = a(3,i)  +  tmp2 * dz
        end do
      end do
c
c Indirect terms (add these on last to reduce roundoff error)
      do i = 2, nbod
c ##A19,101##
        if (algor.lt.13) then
          tmp1 = m(1) * r3(i)
          a(1,i) = a(1,i)  +  sx  -  tmp1 * x(1,i)
          a(2,i) = a(2,i)  +  sy  -  tmp1 * x(2,i)
          a(3,i) = a(3,i)  +  sz  -  tmp1 * x(3,i)
        else
c
c------------------------------------------------------------------------------
c
c polyhedron method
          if (opti(23).eq.0.or.(opti(86).eq.1.and.opti(23).eq.1)) then
          if (algor.eq.13.or.algor.eq.16.or.algor.eq.19) then
c            if (opti(22).eq.0.and.opti(21).eq.1) then
c ##A43,55##
              if (opti(87).eq.0) then
c ##AN28,112##
              call polyhedron (nov,nop,xv,yv,zv,noe,k,
     %          d(opti(21)),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
c ##AN28,112##
              else
              call polyhedron3 (nov,nop,xv,yv,zv,noe,k,
     %          d(opti(21)),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2,lapla2(i))
              end if
c ##A43,55##
              a(1,i) = a(1,i)  -  vx
              a(2,i) = a(2,i)  -  vy
              a(3,i) = a(3,i)  -  vz
c            else
c              do i0 = 1, nop
c                l = 1
c compute new vertices
c                do ilay = 1, opti(21)
c                  inc = del * ilay
c                  do j = 1, noe(i0)
c                    l = l + 1
c                    xl(l) = xv(k(i0,j)) * inc
c                    yl(l) = yv(k(i0,j)) * inc
c                    zl(l) = zv(k(i0,j)) * inc
c                  enddo
c                enddo
c                novl = l
c compute new faces
c                l = 1
c compute top face of pyramid
c                do j = 1, noe(i0)
c                  kl(l,j) = j + 1
c                enddo
c                noel(l) = noe(i0)
c compute lateral faces of pyramid
c                do j = 1, noe(i0)-1
c                  l = l + 1
c                  kl(l,1) = 1
c                  kl(l,2) = j + 2
c                  kl(l,3) = j + 1
c                  noel(l) = 3
c                enddo
c compute last lateral face of pyramid
c                l = l + 1
c                kl(l,1) = 1
c                kl(l,2) = 2
c                kl(l,3) = noe(i0) + 1
c                noel(l) = 3
c compute pyramid's potential
c                nopl = l
c ##AN28,113##
c                call polyhedron (novl,nopl,xl,yl,zl,noel,kl,
c     %            d(1),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
c ##AN28,113##
c                a(1,i) = a(1,i)  -  vx
c                a(2,i) = a(2,i)  -  vy
c                a(3,i) = a(3,i)  -  vz
c compute faces of pyramidal frustums
c                do ilay = 2, opti(21)
c                  l = 1
c compute bottom face (reverse)
c                  do j = 1, noe(i0)
c                    kl(l,j) = (ilay-2)*noe(i0) + (noe(i0)-j) + 2
c                  enddo
c                  noel(l) = noe(i0)
c compute lateral faces
c                  do j = 1, noe(i0)-1
c                    l = l + 1
c                    kl(l,1) = (ilay-2)*noe(i0) + j + 1
c                    kl(l,2) = kl(l,1) + 1
c                    kl(l,3) = ((ilay-1)*noe(i0) + j) + 2
c                    kl(l,4) = kl(l,3) - 1
c                    noel(l) = 4
c                  enddo
c compute last lateral face
c                  l = l + 1
c                  kl(l,1) = (ilay-1)*noe(i0) + 1
c                  kl(l,2) = kl(l,1) - (noe(i0)-1)
c                  kl(l,3) = ilay*noe(i0) - (noe(i0)-1) + 1
c                  kl(l,4) = ilay*noe(i0) + 1
c                  noel(l) = 4
c compute top face (no reverse)
c                  l = l + 1
c                  do j = 1, noe(i0)
c                    kl(l,j) = (ilay-1)*noe(i0) + j + 1
c                  enddo
c                  noel(l) = noe(i0)
c compute pyramidal frustum's potential
c                  nopl = l
c ##AN28,114##
c                  call polyhedron (novl,nopl,xl,yl,zl,noel,kl,
c     %              d(ilay),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
c ##AN28,114##
c                  a(1,i) = a(1,i)  -  vx
c                  a(2,i) = a(2,i)  -  vy
c                  a(3,i) = a(3,i)  -  vz
c                enddo
c              enddo
c            end if
c
c------------------------------------------------------------------------------
c
c mascon method
          else if (algor.eq.14.or.algor.eq.17.or.algor.eq.20) then
            do j = 1, noc
              dx = x(1,i) - xc(j)
              dy = x(2,i) - yc(j)
              dz = x(3,i) - zc(j)
              s2 = dx*dx + dy*dy + dz*dz
              s_1 = 1.d0 / sqrt(s2)
              s_3 = s_1 * s_1 * s_1
              tmp1 = s_3 * mc(j)
              a(1,i) = a(1,i)  -  tmp1 * dx
              a(2,i) = a(2,i)  -  tmp1 * dy
              a(3,i) = a(3,i)  -  tmp1 * dz
            end do
c
c------------------------------------------------------------------------------
c
c hybrid method
          else if (algor.eq.15.or.algor.eq.18.or.algor.eq.21
     %      .or.algor.eq.22) then
            tmp1 = x(1,i)*x(1,i) + x(2,i)*x(2,i) + x(3,i)*x(3,i)
c newtonian method
            if (tmp1.ge.optr(7)) then
              tmp1 = m(1) * r3(i)
              a(1,i) = a(1,i)  -  tmp1 * x(1,i)
              a(2,i) = a(2,i)  -  tmp1 * x(2,i)
              a(3,i) = a(3,i)  -  tmp1 * x(3,i)
            else
c mascon method
              if (tmp1.ge.optr(8)) then
                do j = 1, noc
                  dx = x(1,i) - xc(j)
                  dy = x(2,i) - yc(j)
                  dz = x(3,i) - zc(j)
                  s2 = dx*dx + dy*dy + dz*dz
                  s_1 = 1.d0 / sqrt(s2)
                  s_3 = s_1 * s_1 * s_1
                  tmp1 = s_3 * mc(j)
                  a(1,i) = a(1,i)  -  tmp1 * dx
                  a(2,i) = a(2,i)  -  tmp1 * dy
                  a(3,i) = a(3,i)  -  tmp1 * dz
                end do
c
              else
c polyhedron method
c ##A38,130##
c                if (opti(22).eq.0.and.opti(21).eq.1) then
c ##A43,56##
                  if (opti(87).eq.0) then
c ##AN28,115##
                  call polyhedron (nov,nop,xv,yv,zv,noe,k,
     %              d(opti(21)),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
c ##AN28,115##
                  else
                  call polyhedron3 (nov,nop,xv,yv,zv,noe,k,
     %              d(opti(21)),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2,
     %              lapla2(i))
                  end if
c ##A43,56##
                  a(1,i) = a(1,i)  -  vx
                  a(2,i) = a(2,i)  -  vy
                  a(3,i) = a(3,i)  -  vz
c                else
c                  do i0 = 1, nop
c                    l = 1
c compute new vertices
c                    do ilay = 1, opti(21)
c                      inc = del * ilay
c                      do j = 1, noe(i0)
c                        l = l + 1
c                        xl(l) = xv(k(i0,j)) * inc
c                        yl(l) = yv(k(i0,j)) * inc
c                        zl(l) = zv(k(i0,j)) * inc
c                      enddo
c                    enddo
c                    novl = l
c compute new faces
c                    l = 1
c compute top face of pyramid
c                    do j = 1, noe(i0)
c                      kl(l,j) = j + 1
c                    enddo
c                    noel(l) = noe(i0)
c compute lateral faces of pyramid
c                    do j = 1, noe(i0)-1
c                      l = l + 1
c                      kl(l,1) = 1
c                      kl(l,2) = j + 2
c                      kl(l,3) = j + 1
c                      noel(l) = 3
c                    enddo
c compute last lateral face of pyramid
c                    l = l + 1
c                    kl(l,1) = 1
c                    kl(l,2) = 2
c                    kl(l,3) = noe(i0) + 1
c                    noel(l) = 3
c compute pyramid's potential
c                    nopl = l
c ##AN28,116##
c                    call polyhedron (novl,nopl,xl,yl,zl,noel,
c     %                kl,d(1),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
c ##AN28,116##
c                    a(1,i) = a(1,i)  -  vx
c                    a(2,i) = a(2,i)  -  vy
c                    a(3,i) = a(3,i)  -  vz
c compute faces of pyramidal frustums
c                    do ilay = 2, opti(21)
c                      l = 1
c compute bottom face (reverse)
c                      do j = 1, noe(i0)
c                        kl(l,j) = (ilay-2)*noe(i0) + (noe(i0)-j) + 2
c                      enddo
c                      noel(l) = noe(i0)
c compute lateral faces
c                      do j = 1, noe(i0)-1
c                        l = l + 1
c                        kl(l,1) = (ilay-2)*noe(i0) + j + 1
c                        kl(l,2) = kl(l,1) + 1
c                        kl(l,3) = ((ilay-1)*noe(i0) + j) + 2
c                        kl(l,4) = kl(l,3) - 1
c                        noel(l) = 4
c                      enddo
c compute last lateral face
c                      l = l + 1
c                      kl(l,1) = (ilay-1)*noe(i0) + 1
c                      kl(l,2) = kl(l,1) - (noe(i0)-1)
c                      kl(l,3) = ilay*noe(i0) - (noe(i0)-1) + 1
c                      kl(l,4) = ilay*noe(i0) + 1
c                      noel(l) = 4
c compute top face (no reverse)
c                      l = l + 1
c                      do j = 1, noe(i0)
c                        kl(l,j) = (ilay-1)*noe(i0) + j + 1
c                      enddo
c                      noel(l) = noe(i0)
c compute pyramidal frustum's potential
c                      nopl = l
c ##AN28,117##
c                      call polyhedron (novl,nopl,xl,yl,zl,noel,
c     %                  kl,d(ilay),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
c ##AN28,117##
c                      a(1,i) = a(1,i)  -  vx
c                      a(2,i) = a(2,i)  -  vy
c                      a(3,i) = a(3,i)  -  vz
c                    enddo
c                  enddo
c                end if
c ##A38,130##
              end if
            end if
c
          end if
c
c------------------------------------------------------------------------------
c
c binary method
          else if (opti(23).eq.1) then
            tmp1=x(1,i)*x(1,i)*a2+x(2,i)*x(2,i)*b2+x(3,i)*x(3,i)*c2-1.0
            if (((x(1,i).ge.optr(17).and.x(1,i).le.optr(18))
     %        .and.(x(2,i).ge.optr(19).and.x(2,i).le.optr(20))
     %        .and.(x(3,i).ge.optr(21).and.x(3,i).le.optr(22)))
     %        .and.(tmp1.gt.0.d0.or.tmp1.eq.-1.0)) then
              xp = x(1,i) * optr(14)
              ix = ceiling (dabs(xp))
              yp = x(2,i) * optr(15)
              iy = ceiling (dabs(yp))
              zp = x(3,i) * optr(16)
              iz = ceiling (dabs(zp))
              if (ix.eq.0) ix = 1
              if (iy.eq.0) iy = 1
              if (iz.eq.0) iz = 1
              if (x(1,i).ge.0.d0.and.x(2,i).ge.0.d0.and.x(3,i)
     %          .ge.0.d0) then
                a(1,i) = a(1,i) + apot(1,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(1,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(1,ix,iy,iz,3)
              else if (x(1,i).lt.0.d0.and.x(2,i).ge.0.d0.and.x(3,i)
     %          .ge.0.d0) then
                a(1,i) = a(1,i) + apot(2,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(2,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(2,ix,iy,iz,3)
              else if (x(1,i).lt.0.d0.and.x(2,i).lt.0.d0.and.x(3,i)
     %          .ge.0.d0) then
                a(1,i) = a(1,i) + apot(3,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(3,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(3,ix,iy,iz,3)
              else if (x(1,i).ge.0.d0.and.x(2,i).lt.0.d0.and.x(3,i)
     %          .ge.0.d0) then
                a(1,i) = a(1,i) + apot(4,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(4,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(4,ix,iy,iz,3)
              else if (x(1,i).ge.0.d0.and.x(2,i).ge.0.d0.and.x(3,i)
     %          .lt.0.d0) then
                a(1,i) = a(1,i) + apot(5,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(5,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(5,ix,iy,iz,3)
              else if (x(1,i).lt.0.d0.and.x(2,i).ge.0.d0.and.x(3,i)
     %          .lt.0.d0) then
                a(1,i) = a(1,i) + apot(6,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(6,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(6,ix,iy,iz,3)
              else if (x(1,i).lt.0.d0.and.x(2,i).lt.0.d0.and.x(3,i)
     %          .lt.0.d0) then
                a(1,i) = a(1,i) + apot(7,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(7,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(7,ix,iy,iz,3)
              else if (x(1,i).ge.0.d0.and.x(2,i).lt.0.d0.and.x(3,i)
     %          .lt.0.d0) then
                a(1,i) = a(1,i) + apot(8,ix,iy,iz,1)
                a(2,i) = a(2,i) + apot(8,ix,iy,iz,2)
                a(3,i) = a(3,i) + apot(8,ix,iy,iz,3)
              end if
            else
c
c polyhedron method
              if (algor.eq.13.or.algor.eq.16.or.algor.eq.19) then
c                if (opti(22).eq.0.and.opti(21).eq.1) then
c ##A43,57##
                  if (opti(87).eq.0) then
c ##AN28,118##
                  call polyhedron (nov,nop,xv,yv,zv,noe,k,
     %              d(opti(21)),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
c ##AN28,118##
                  else
                  call polyhedron3 (nov,nop,xv,yv,zv,noe,k,
     %              d(opti(21)),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2,
     %              lapla2(i))
                  end if
c ##A43,57##
                  a(1,i) = a(1,i)  -  vx
                  a(2,i) = a(2,i)  -  vy
                  a(3,i) = a(3,i)  -  vz
c                else
c                  do i0 = 1, nop
c                    l = 1
c compute new vertices
c                    do ilay = 1, opti(21)
c                      inc = del * ilay
c                      do j = 1, noe(i0)
c                        l = l + 1
c                        xl(l) = xv(k(i0,j)) * inc
c                        yl(l) = yv(k(i0,j)) * inc
c                        zl(l) = zv(k(i0,j)) * inc
c                      enddo
c                    enddo
c                    novl = l
c compute new faces
c                    l = 1
c compute top face of pyramid
c                    do j = 1, noe(i0)
c                      kl(l,j) = j + 1
c                    enddo
c                    noel(l) = noe(i0)
c compute lateral faces of pyramid
c                    do j = 1, noe(i0)-1
c                      l = l + 1
c                      kl(l,1) = 1
c                      kl(l,2) = j + 2
c                      kl(l,3) = j + 1
c                      noel(l) = 3
c                    enddo
c compute last lateral face of pyramid
c                    l = l + 1
c                    kl(l,1) = 1
c                    kl(l,2) = 2
c                    kl(l,3) = noe(i0) + 1
c                    noel(l) = 3
c compute pyramid's potential
c                    nopl = l
c ##AN28,119##
c                    call polyhedron (novl,nopl,xl,yl,zl,noel,kl,
c     %                d(1),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
c ##AN28,119##
c                    a(1,i) = a(1,i)  -  vx
c                    a(2,i) = a(2,i)  -  vy
c                    a(3,i) = a(3,i)  -  vz
c compute faces of pyramidal frustums
c                    do ilay = 2, opti(21)
c                      l = 1
c compute bottom face (reverse)
c                      do j = 1, noe(i0)
c                        kl(l,j) = (ilay-2)*noe(i0) + (noe(i0)-j) + 2
c                      enddo
c                      noel(l) = noe(i0)
c compute lateral faces
c                      do j = 1, noe(i0)-1
c                        l = l + 1
c                        kl(l,1) = (ilay-2)*noe(i0) + j + 1
c                        kl(l,2) = kl(l,1) + 1
c                        kl(l,3) = ((ilay-1)*noe(i0) + j) + 2
c                        kl(l,4) = kl(l,3) - 1
c                        noel(l) = 4
c                      enddo
c compute last lateral face
c                      l = l + 1
c                      kl(l,1) = (ilay-1)*noe(i0) + 1
c                      kl(l,2) = kl(l,1) - (noe(i0)-1)
c                      kl(l,3) = ilay*noe(i0) - (noe(i0)-1) + 1
c                      kl(l,4) = ilay*noe(i0) + 1
c                      noel(l) = 4
c compute top face (no reverse)
c                      l = l + 1
c                      do j = 1, noe(i0)
c                        kl(l,j) = (ilay-1)*noe(i0) + j + 1
c                      enddo
c                      noel(l) = noe(i0)
c compute pyramidal frustum's potential
c                      nopl = l
c ##AN28,120##
c                      call polyhedron (novl,nopl,xl,yl,zl,noel,kl,
c     %                  d(ilay),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
c ##AN28,120##
c                      a(1,i) = a(1,i)  -  vx
c                      a(2,i) = a(2,i)  -  vy
c                      a(3,i) = a(3,i)  -  vz
c                    enddo
c                  enddo
c                end if
c
c mascon method
              else if (algor.eq.14.or.algor.eq.17.or.algor.eq.20) then
                do j = 1, noc
                  dx = x(1,i) - xc(j)
                  dy = x(2,i) - yc(j)
                  dz = x(3,i) - zc(j)
                  s2 = dx*dx + dy*dy + dz*dz
                  s_1 = 1.d0 / sqrt(s2)
                  s_3 = s_1 * s_1 * s_1
                  tmp1 = s_3 * mc(j)
                  a(1,i) = a(1,i)  -  tmp1 * dx
                  a(2,i) = a(2,i)  -  tmp1 * dy
                  a(3,i) = a(3,i)  -  tmp1 * dz
                end do
c
c hybrid method
              else if (algor.eq.15.or.algor.eq.18.or.algor.eq.21
     %          .or.algor.eq.22) then
                tmp1 = x(1,i)*x(1,i) + x(2,i)*x(2,i) + x(3,i)*x(3,i)
c newtonian method
                if (tmp1.ge.optr(7)) then
                  tmp1 = m(1) * r3(i)
                  a(1,i) = a(1,i)  -  tmp1 * x(1,i)
                  a(2,i) = a(2,i)  -  tmp1 * x(2,i)
                  a(3,i) = a(3,i)  -  tmp1 * x(3,i)
                else
c mascon method
                  if (tmp1.ge.optr(8)) then
                    do j = 1, noc
                      dx = x(1,i) - xc(j)
                      dy = x(2,i) - yc(j)
                      dz = x(3,i) - zc(j)
                      s2 = dx*dx + dy*dy + dz*dz
                      s_1 = 1.d0 / sqrt(s2)
                      s_3 = s_1 * s_1 * s_1
                      tmp1 = s_3 * mc(j)
                      a(1,i) = a(1,i)  -  tmp1 * dx
                      a(2,i) = a(2,i)  -  tmp1 * dy
                      a(3,i) = a(3,i)  -  tmp1 * dz
                    end do
c
                  else
c
c ##A38,131##
c                    if (opti(22).eq.0.and.opti(21).eq.1) then
c ##A43,58##
                      if (opti(87).eq.0) then
c ##AN28,121##
                      call polyhedron (nov,nop,xv,yv,zv,noe,k,
     %                  d(opti(21)),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
c ##AN28,121##
                      else
                      call polyhedron3 (nov,nop,xv,yv,zv,noe,k,
     %                  d(opti(21)),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2,
     %                  lapla2(i))
                      end if
c ##A43,58##
                      a(1,i) = a(1,i)  -  vx
                      a(2,i) = a(2,i)  -  vy
                      a(3,i) = a(3,i)  -  vz
c                    else
c                      do i0 = 1, nop
c                        l = 1
c compute new vertices
c                        do ilay = 1, opti(21)
c                          inc = del * ilay
c                          do j = 1, noe(i0)
c                            l = l + 1
c                            xl(l) = xv(k(i0,j)) * inc
c                            yl(l) = yv(k(i0,j)) * inc
c                            zl(l) = zv(k(i0,j)) * inc
c                          enddo
c                        enddo
c                        novl = l
c compute new faces
c                        l = 1
c compute top face of pyramid
c                        do j = 1, noe(i0)
c                          kl(l,j) = j + 1
c                        enddo
c                        noel(l) = noe(i0)
c compute lateral faces of pyramid
c                        do j = 1, noe(i0)-1
c                          l = l + 1
c                          kl(l,1) = 1
c                          kl(l,2) = j + 2
c                          kl(l,3) = j + 1
c                          noel(l) = 3
c                        enddo
c compute last lateral face of pyramid
c                        l = l + 1
c                        kl(l,1) = 1
c                        kl(l,2) = 2
c                        kl(l,3) = noe(i0) + 1
c                        noel(l) = 3
c compute pyramid's potential
c                        nopl = l
c ##AN28,122##
c                        call polyhedron (novl,nopl,xl,yl,zl,noel,
c     %                    kl,d(1),x(1,i),x(2,i),x(3,i),vx,vy,vz,K2)
c ##AN28,122##
c                        a(1,i) = a(1,i)  -  vx
c                        a(2,i) = a(2,i)  -  vy
c                        a(3,i) = a(3,i)  -  vz
c compute faces of pyramidal frustums
c                        do ilay = 2, opti(21)
c                          l = 1
c compute bottom face (reverse)
c                          do j = 1, noe(i0)
c                            kl(l,j) = (ilay-2)*noe(i0) + (noe(i0)-j) + 2
c                          enddo
c                          noel(l) = noe(i0)
c compute lateral faces
c                          do j = 1, noe(i0)-1
c                            l = l + 1
c                            kl(l,1) = (ilay-2)*noe(i0) + j + 1
c                            kl(l,2) = kl(l,1) + 1
c                            kl(l,3) = ((ilay-1)*noe(i0) + j) + 2
c                            kl(l,4) = kl(l,3) - 1
c                           noel(l) = 4
c                         enddo
c compute last lateral face
c                          l = l + 1
c                          kl(l,1) = (ilay-1)*noe(i0) + 1
c                          kl(l,2) = kl(l,1) - (noe(i0)-1)
c                          kl(l,3) = ilay*noe(i0) - (noe(i0)-1) + 1
c                          kl(l,4) = ilay*noe(i0) + 1
c                          noel(l) = 4
c compute top face (no reverse)
c                          l = l + 1
c                          do j = 1, noe(i0)
c                            kl(l,j) = (ilay-1)*noe(i0) + j + 1
c                          enddo
c                          noel(l) = noe(i0)
c compute pyramidal frustum's potential
c                          nopl = l
c ##AN28,123##
c                          call polyhedron (novl,nopl,xl,yl,zl,noel,
c     %                      kl,d(ilay),x(1,i),x(2,i),x(3,i),vx,vy,vz,
c     %                      K2)
c ##AN28,123##
c                          a(1,i) = a(1,i)  -  vx
c                          a(2,i) = a(2,i)  -  vy
c                          a(3,i) = a(3,i)  -  vz
c                        enddo
c                      enddo
c                    end if
c ##A38,131##
                  end if
                end if
c
              end if
            end if
c
c------------------------------------------------------------------------------
c
          end if
          a(1,i) = a(1,i)  +  sx
          a(2,i) = a(2,i)  +  sy
          a(3,i) = a(3,i)  +  sz
c          if (opti(72).eq.0) then
c          a(1,i) = a(1,i)+2.0d0*optr(6)*v(2,i) + optr(6)*optr(6)*x(1,i)
c          a(2,i) = a(2,i)-2.0d0*optr(6)*v(1,i) + optr(6)*optr(6)*x(2,i)
c          end if
        end if
c ##A19,101##
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c

c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c     MFO_DRCT.FOR    (ErikSoft   27 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates direct accelerations between bodies in the interaction part
c of the Hamiltonian of a symplectic integrator that partitions close
c encounter terms (e.g. hybrid symplectic algorithms or SyMBA).
c The routine calculates accelerations between all pairs of bodies with
c indices I >= I0.
c
c------------------------------------------------------------------------------
c
      subroutine mfo_drct (i0,nbod,nbig,m,x,rcrit,a,stat)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer i0, nbod, nbig, stat(nbod)
      real*8 m(nbod), x(3,nbod), a(3,nbod), rcrit(nbod)
c
c Local
      integer i,j
      real*8 dx,dy,dz,s,s_1,s2,s_3,rc,rc2,q,q2,q3,q4,q5,tmp2,faci,facj
c
c------------------------------------------------------------------------------
c
      if (i0.le.0) i0 = 2
c
      do i = i0, nbig
        do j = i + 1, nbod
          dx = x(1,j) - x(1,i)
          dy = x(2,j) - x(2,i)
          dz = x(3,j) - x(3,i)
          s2 = dx * dx  +  dy * dy  +  dz * dz
          rc = max(rcrit(i), rcrit(j))
          rc2 = rc * rc
c
          if (s2.ge.rc2) then
            s_1 = 1.d0 / sqrt(s2)
            tmp2 = s_1 * s_1 * s_1
          else if (s2.le.0.01*rc2) then
            tmp2 = 0.d0
          else
            s_1 = 1.d0 / sqrt(s2)
            s   = 1.d0 / s_1
            s_3 = s_1 * s_1 * s_1
            q = (s - 0.1d0*rc) / (0.9d0 * rc)
            q2 = q  * q
            q3 = q  * q2
            q4 = q2 * q2
            q5 = q2 * q3
            tmp2 = (10.d0*q3 - 15.d0*q4 + 6.d0*q5) * s_3
          end if
c
          faci = tmp2 * m(i)
          facj = tmp2 * m(j)
          a(1,j) = a(1,j)  -  faci * dx
          a(2,j) = a(2,j)  -  faci * dy
          a(3,j) = a(3,j)  -  faci * dz
          a(1,i) = a(1,i)  +  facj * dx
          a(2,i) = a(2,i)  +  facj * dy
          a(3,i) = a(3,i)  +  facj * dz
        end do
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c     MFO_HY.FOR    (ErikSoft   2 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates accelerations due to the Interaction part of the Hamiltonian 
c of a hybrid symplectic integrator for a set of NBOD bodies (NBIG of which 
c are Big), where Small bodies do not interact with one another.
c
c------------------------------------------------------------------------------
c
      subroutine mfo_hy (jcen,nbod,nbig,m,x,rcrit,a,stat)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod, nbig, stat(nbod)
      real*8 jcen(3), m(nbod), x(3,nbod), a(3,nbod), rcrit(nbod)
c
c Local
      integer k
      real*8 aobl(3,NMAX),acen(3)
c
c------------------------------------------------------------------------------
c
c Initialize accelerations to zero
      do k = 1, nbod
        a(1,k) = 0.d0
        a(2,k) = 0.d0
        a(3,k) = 0.d0
      end do
c
c Calculate direct terms
      call mfo_drct (2,nbod,nbig,m,x,rcrit,a,stat)
c
c Add accelerations due to oblateness of the central body
      if (jcen(1).ne.0.or.jcen(2).ne.0.or.jcen(3).ne.0) then
        call mfo_obl (jcen,nbod,m,x,aobl,acen)
        do k = 2, nbod
          a(1,k) = a(1,k) + aobl(1,k) - acen(1)
          a(2,k) = a(2,k) + aobl(2,k) - acen(2)
          a(3,k) = a(3,k) + aobl(3,k) - acen(3)
        end do
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c     MFO_WB.FOR    (ErikSoft   2 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c
c------------------------------------------------------------------------------
c
      subroutine mfo_wb (jcen,nbod,nbig,m,x,rcrit,a,stat)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod, nbig, stat(nbod)
      real*8 jcen(3), m(nbod), x(3,nbod), a(3,nbod), rcrit(nbod)
c
c Local
      integer k
      real*8 dx, dy, dz, s_1, s2, s_3, temp, tmp2, tmp3
      real*8 aobl(3,NMAX), acen(3), msum, xs(3), xsm3, xxs(3)
c
c------------------------------------------------------------------------------
c
c Initialize accelerations to zero
      msum = 0
      a(1,2) = 0.d0
      a(2,2) = 0.d0
      a(3,2) = 0.d0
      xs(1) = 0.d0
      xs(2) = 0.d0
      xs(3) = 0.d0
      xxs(1) = 0.d0
      xxs(2) = 0.d0
      xxs(3) = 0.d0
c
      do k = 3, nbod
        a(1,k) = 0.d0
        a(2,k) = 0.d0
        a(3,k) = 0.d0
        msum = msum + m(k)
        xs(1) = xs(1)  +  m(k) * x(1,k)
        xs(2) = xs(2)  +  m(k) * x(2,k)
        xs(3) = xs(3)  +  m(k) * x(3,k)
      end do
c
      temp = 1.d0 / (m(1) + msum)
      xs(1) = xs(1) * temp  +  x(1,2)
      xs(2) = xs(2) * temp  +  x(2,2)
      xs(3) = xs(3) * temp  +  x(3,2)
      s2 = xs(1) * xs(1)  +  xs(2) * xs(2)  +  xs(3) * xs(3)
      s_1 = 1.d0 / sqrt(s2)
      xsm3 = s_1 * s_1 * s_1 
c
c Direct terms
      call mfo_drct (3,nbod,nbig,m,x,rcrit,a,stat)
c
c Add accelerations due to oblateness of the central body
      if (jcen(1).ne.0.or.jcen(2).ne.0.or.jcen(3).ne.0) then
        call mfo_obl (jcen,nbod,m,x,aobl,acen)
        do k = 2, nbod
          a(1,k) = a(1,k) + aobl(1,k) - acen(1)
          a(2,k) = a(2,k) + aobl(2,k) - acen(2)
          a(3,k) = a(3,k) + aobl(3,k) - acen(3)
        end do
      end if
c
c Add on terms due to the binary
      do k = 3, nbod
        dx = xs(1) - x(1,k)
        dy = xs(2) - x(2,k)
        dz = xs(3) - x(3,k)
        s2 = dx * dx  +  dy * dy  +  dz * dz
        s_1 = 1.d0 / sqrt(s2)
        s_3 = s_1 * s_1 * s_1
c
        temp = m(k) * s_3
        tmp2 = xsm3 * m(2) * m(1) / (m(1) + msum)
        tmp3 = m(2) * s_3
c
        xxs(1) = xxs(1)  +  temp * dx
        xxs(2) = xxs(2)  +  temp * dy
        xxs(3) = xxs(3)  +  temp * dz
        a(1,k) = a(1,k)  -  tmp2 * xs(1)  +  tmp3 * dx
        a(2,k) = a(2,k)  -  tmp2 * xs(2)  +  tmp3 * dy
        a(3,k) = a(3,k)  -  tmp2 * xs(3)  +  tmp3 * dz
      end do
c
      temp = m(2) / (m(1) + msum)
      do k = 3, nbod
        a(1,k) = a(1,k)  -  temp * xxs(1)
        a(2,k) = a(2,k)  -  temp * xxs(2)
        a(3,k) = a(3,k)  -  temp * xxs(3)
      end do
c
      s2 = x(1,2)*x(1,2) + x(2,2)*x(2,2) + x(3,2)*x(3,2)
      s_1 = 1.d0 / sqrt(s2)
      s_3 = s_1 * s_1 * s_1
      temp = (m(1) + msum) * s_3
      tmp2 = m(1) * xsm3
      a(1,2) = a(1,2)  +  temp * x(1,2) -  tmp2 * xs(1)  -  xxs(1)
      a(2,2) = a(2,2)  +  temp * x(2,2) -  tmp2 * xs(2)  -  xxs(2)
      a(3,2) = a(3,2)  +  temp * x(3,2) -  tmp2 * xs(3)  -  xxs(3)
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c     MFO_HKCE.FOR    (ErikSoft   27 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates accelerations due to the Keplerian part of the Hamiltonian 
c of a hybrid symplectic integrator, when close encounters are taking place,
c for a set of NBOD bodies (NBIG of which are Big). Note that Small bodies
c do not interact with one another.
c
c------------------------------------------------------------------------------
c
      subroutine mfo_hkce (time,jcen,nbod,nbig,m,x,v,spin,rcrit,a,stat,
     %  ngf,ngflag,opt,nce,ice,jce)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,stat(nbod),ngflag,opt(9),nce,ice(nce),jce(nce)
      real*8 time,jcen(3),rcrit(nbod),ngf(4,nbod),m(nbod)
      real*8 x(3,nbod),v(3,nbod),a(3,nbod),spin(3,nbod)
c
c Local
      integer i, j, k
      real*8 tmp2,dx,dy,dz,s,s_1,s2,s_3,faci,facj,rc,rc2,q,q2,q3,q4,q5
c
c------------------------------------------------------------------------------
c
c Initialize accelerations
      do j = 1, nbod
        a(1,j) = 0.d0
        a(2,j) = 0.d0
        a(3,j) = 0.d0
      end do
c
c Direct terms
      do k = 1, nce
        i = ice(k)
        j = jce(k)
        dx = x(1,j) - x(1,i)
        dy = x(2,j) - x(2,i)
        dz = x(3,j) - x(3,i)
        s2 = dx * dx  +  dy * dy  +  dz * dz
        rc = max (rcrit(i), rcrit(j))
        rc2 = rc * rc
c
        if (s2.lt.rc2) then
          s_1 = 1.d0 / sqrt(s2)
          s_3 = s_1 * s_1 * s_1
          if (s2.le.0.01*rc2) then
            tmp2 = s_3
          else
            s = 1.d0 / s_1
            q = (s - 0.1d0*rc) / (0.9d0 * rc)
            q2 = q * q
            q3 = q * q2
            q4 = q2 * q2
            q5 = q2 * q3
            tmp2 = (1.d0 - 10.d0*q3 + 15.d0*q4 - 6.d0*q5) * s_3
          end if
c
          faci = tmp2 * m(i)
          facj = tmp2 * m(j)
          a(1,j) = a(1,j)  -  faci * dx
          a(2,j) = a(2,j)  -  faci * dy
          a(3,j) = a(3,j)  -  faci * dz
          a(1,i) = a(1,i)  +  facj * dx
          a(2,i) = a(2,i)  +  facj * dy
          a(3,i) = a(3,i)  +  facj * dz
        end if
      end do
c
c Solar terms
      do i = 2, nbod
        s2 = x(1,i)*x(1,i) + x(2,i)*x(2,i) + x(3,i)*x(3,i)
        s_1 = 1.d0 / sqrt(s2)
        tmp2 = m(1) * s_1 * s_1 * s_1
        a(1,i) = a(1,i)  -  tmp2 * x(1,i)
        a(2,i) = a(2,i)  -  tmp2 * x(2,i)
        a(3,i) = a(3,i)  -  tmp2 * x(3,i)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c     MFO_MVS.FOR    (ErikSoft   2 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates accelerations on a set of NBOD bodies (of which NBIG are Big)
c due to gravitational perturbations by all the other bodies.
c This routine is designed for use with a mixed-variable symplectic
c integrator using Jacobi coordinates.
c
c Based upon routines from Levison and Duncan's SWIFT integrator.
c
c------------------------------------------------------------------------------
c
      subroutine mfo_mvs (jcen,nbod,nbig,m,x,xj,a,stat)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod, nbig, stat(nbod)
      real*8 jcen(3), m(nbod), x(3,nbod), xj(3,nbod), a(3,nbod)
c
c Local
      integer i,j,k,k1
      real*8 fac0,fac1,fac12,fac2,minside,dx,dy,dz,s_1,s2,s_3,faci,facj
      real*8 a0(3),a0tp(3),a1(3,NMAX),a2(3,NMAX),a3(3,NMAX),aobl(3,NMAX)
      real*8 r,r2,r3,rj,rj2,rj3,q,q2,q3,q4,q5,q6,q7,acen(3)
c
c------------------------------------------------------------------------------
c
c Initialize variables
      a0(1) = 0.d0
      a0(2) = 0.d0
      a0(3) = 0.d0
      a1(1,2) = 0.d0
      a1(2,2) = 0.d0
      a1(3,2) = 0.d0
      a2(1,2) = 0.d0
      a2(2,2) = 0.d0
      a2(3,2) = 0.d0
      minside = 0.d0
c
c Calculate acceleration terms
      do k = 3, nbig
        k1 = k - 1
        minside = minside + m(k1)
        r2   = x(1,k)  * x(1,k)  +  x(2,k) * x(2,k)  +  x(3,k) * x(3,k)
        rj2  = xj(1,k) * xj(1,k) + xj(2,k) * xj(2,k) + xj(3,k) * xj(3,k)
        r  = 1.d0 / sqrt(r2)
        rj = 1.d0 / sqrt(rj2)
        r3  = r  * r  * r
        rj3 = rj * rj * rj
c
        fac0 = m(k) * r3
        fac12 = m(1) * rj3
        fac2 = m(k) * fac12 / (minside + m(1))
        q = (r2 - rj2) * .5d0 / rj2
        q2 = q  * q
        q3 = q  * q2
        q4 = q2 * q2
        q5 = q2 * q3
        q6 = q3 * q3
        q7 = q3 * q4
        fac1 = 402.1875d0*q7 - 187.6875d0*q6 + 86.625d0*q5
     %       - 39.375d0*q4 + 17.5d0*q3 - 7.5d0*q2 + 3.d0*q - 1.d0
c
c Add to A0 term
        a0(1) = a0(1)  -  fac0 * x(1,k)
        a0(2) = a0(2)  -  fac0 * x(2,k)
        a0(3) = a0(3)  -  fac0 * x(3,k)
c
c Calculate A1 for this body
        a1(1,k) = fac12 * (xj(1,k) + fac1*x(1,k))
        a1(2,k) = fac12 * (xj(2,k) + fac1*x(2,k))
        a1(3,k) = fac12 * (xj(3,k) + fac1*x(3,k))
c
c Calculate A2 for this body
        a2(1,k) = a2(1,k1)  +  fac2 * xj(1,k)
        a2(2,k) = a2(2,k1)  +  fac2 * xj(2,k)
        a2(3,k) = a2(3,k1)  +  fac2 * xj(3,k)
      end do
c
      r2   = x(1,2)  * x(1,2)  +  x(2,2) * x(2,2)  +  x(3,2) * x(3,2)
      r  = 1.d0 / sqrt(r2)
      r3  = r  * r  * r
      fac0 = m(2) * r3
      a0tp(1) = a0(1)  -  fac0 * x(1,2)
      a0tp(2) = a0(2)  -  fac0 * x(2,2)
      a0tp(3) = a0(3)  -  fac0 * x(3,2)
c
c Calculate A3 (direct terms)
      do k = 2, nbod
        a3(1,k) = 0.d0
        a3(2,k) = 0.d0
        a3(3,k) = 0.d0
      end do
      do i = 2, nbig
        do j = i + 1, nbig
          dx = x(1,j) - x(1,i)
          dy = x(2,j) - x(2,i)
          dz = x(3,j) - x(3,i)
          s2 = dx*dx + dy*dy + dz*dz
          s_1 = 1.d0 / sqrt(s2)
          s_3 = s_1 * s_1 * s_1
          faci = m(i) * s_3
          facj = m(j) * s_3
          a3(1,j) = a3(1,j)  -  faci * dx
          a3(2,j) = a3(2,j)  -  faci * dy
          a3(3,j) = a3(3,j)  -  faci * dz
          a3(1,i) = a3(1,i)  +  facj * dx
          a3(2,i) = a3(2,i)  +  facj * dy
          a3(3,i) = a3(3,i)  +  facj * dz
        end do
c
        do j = nbig + 1, nbod
          dx = x(1,j) - x(1,i)
          dy = x(2,j) - x(2,i)
          dz = x(3,j) - x(3,i)
          s2 = dx*dx + dy*dy + dz*dz
          s_1 = 1.d0 / sqrt(s2)
          s_3 = s_1 * s_1 * s_1
          faci = m(i) * s_3
          a3(1,j) = a3(1,j)  -  faci * dx
          a3(2,j) = a3(2,j)  -  faci * dy
          a3(3,j) = a3(3,j)  -  faci * dz
        end do
      end do
c
c Big-body accelerations
      do k = 2, nbig
        a(1,k) = a0(1) + a1(1,k) + a2(1,k) + a3(1,k)
        a(2,k) = a0(2) + a1(2,k) + a2(2,k) + a3(2,k)
        a(3,k) = a0(3) + a1(3,k) + a2(3,k) + a3(3,k)
      end do
c
c Small-body accelerations
      do k = nbig + 1, nbod
        a(1,k) = a0tp(1) + a3(1,k)
        a(2,k) = a0tp(2) + a3(2,k)
        a(3,k) = a0tp(3) + a3(3,k)
      end do
c
c Correct for oblateness of the central body
      if (jcen(1).ne.0.or.jcen(2).ne.0.or.jcen(3).ne.0) then
        call mfo_obl (jcen,nbod,m,x,aobl,acen)
        do k = 2, nbod
          a(1,k) = a(1,k) + (aobl(1,k) - acen(1))
          a(2,k) = a(2,k) + (aobl(2,k) - acen(2))
          a(3,k) = a(3,k) + (aobl(3,k) - acen(3))
        end do
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MFO_NGF.FOR    (ErikSoft  29 November 1999)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates accelerations on a set of NBOD bodies due to cometary
c non-gravitational jet forces. The positions and velocities are stored in
c arrays X, V with the format (x,y,z) and (vx,vy,vz) for each object in
c succession. The accelerations are stored in the array A (ax,ay,az). The
c non-gravitational accelerations follow a force law described by Marsden
c et al. (1973) Astron. J. 211-225, with magnitude determined by the
c parameters NGF(1,2,3) for each object.
c
c N.B. All coordinates and velocities must be with respect to central body!!!!
c ===
c------------------------------------------------------------------------------
c
      subroutine mfo_ngf (nbod,x,v,a,ngf)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod
      real*8 x(3,nbod), v(3,nbod), a(3,nbod), ngf(4,nbod)
c
c Local
      integer j
      real*8 r2,r,rv,q,g,tx,ty,tz,nx,ny,nz,a1,a2,a3
c
c------------------------------------------------------------------------------
c
      do j = 1, nbod
        r2 = x(1,j)*x(1,j) + x(2,j)*x(2,j) +x(3,j)*x(3,j)
c
c Only calculate accelerations if body is close to the Sun (R < 9.36 AU), 
c or if the non-gravitational force parameters are exceptionally large.
        if (r2.lt.88.d0.or.abs(ngf(1,j)).gt.1d-7
     %    .or.abs(ngf(2,j)).gt.1d-7.or.abs(ngf(3,j)).gt.1d-7) then
          r = sqrt(r2)
          rv = x(1,j)*v(1,j) + x(2,j)*v(2,j) + x(3,j)*v(3,j)
c
c Calculate Q = R / R0, where R0 = 2.808 AU
          q = r * .3561253561253561d0
          g = .111262d0 * q**(-2.15d0) * (1.d0+q**5.093d0)**(-4.6142d0)
c
c Within-orbital-plane transverse vector components
          tx = r2*v(1,j) - rv*x(1,j)
          ty = r2*v(2,j) - rv*x(2,j)
          tz = r2*v(3,j) - rv*x(3,j)
c
c Orbit-normal vector components
          nx = x(2,j)*v(3,j) - x(3,j)*v(2,j)
          ny = x(3,j)*v(1,j) - x(1,j)*v(3,j)
          nz = x(1,j)*v(2,j) - x(2,j)*v(1,j)
c
c Multiplication factors
          a1 = ngf(1,j) * g / r
          a2 = ngf(2,j) * g / sqrt(tx*tx + ty*ty + tz*tz)
          a3 = ngf(3,j) * g / sqrt(nx*nx + ny*ny + nz*nz)
c
c X,Y and Z components of non-gravitational acceleration
          a(1,j) = a1*x(1,j) + a2*tx + a3*nx
          a(2,j) = a1*x(2,j) + a2*ty + a3*ny
          a(3,j) = a1*x(3,j) + a2*tz + a3*nz
        else
          a(1,j) = 0.d0
          a(2,j) = 0.d0
          a(3,j) = 0.d0
        end if
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c     MFO_OBL.FOR    (ErikSoft   2 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates barycentric accelerations of NBOD bodies due to oblateness of
c the central body. Also returns the corresponding barycentric acceleration
c of the central body.
c
c N.B. All coordinates must be with respect to the central body!!!!
c ===
c------------------------------------------------------------------------------
c
      subroutine mfo_obl (jcen,nbod,m,x,a,acen)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod
      real*8 jcen(3), m(nbod), x(3,nbod), a(3,nbod), acen(3)
c
c Local
      integer i
      real*8 jr2,jr4,jr6,r2,r_1,r_2,r_3,u2,u4,u6,tmp1,tmp2,tmp3,tmp4
c
c------------------------------------------------------------------------------
c
      acen(1) = 0.d0
      acen(2) = 0.d0
      acen(3) = 0.d0
c
      do i = 2, nbod
c
c Calculate barycentric accelerations on the objects
        r2 = x(1,i)*x(1,i) + x(2,i)*x(2,i) + x(3,i)*x(3,i)
        r_1 = 1.d0 / sqrt(r2)
        r_2 = r_1 * r_1
        r_3 = r_2 * r_1
        jr2 = jcen(1) * r_2
        jr4 = jcen(2) * r_2 * r_2
        jr6 = jcen(3) * r_2 * r_2 * r_2
        u2 = x(3,i) * x(3,i) * r_2
        u4 = u2 * u2
        u6 = u4 * u2
c
        tmp1 = m(1) * r_3
        tmp2 =jr2*(7.5d0*u2 - 1.5d0)
     %       +jr4*(39.375d0*u4 - 26.25d0*u2 + 1.875d0)
     %       +jr6*(187.6875d0*u6 -216.5625d0*u4 +59.0625d0*u2 -2.1875d0)
        tmp3 = jr2*3.d0 + jr4*(17.5d0*u2 - 7.5d0)
     %       + jr6*(86.625d0*u4 - 78.75d0*u2 + 13.125d0)
c
        a(1,i) = x(1,i) * tmp1 * tmp2
        a(2,i) = x(2,i) * tmp1 * tmp2
        a(3,i) = x(3,i) * tmp1 * (tmp2 - tmp3)
c
c Calculate barycentric accelerations on the central body
        tmp4 = m(i) / m(1)
        acen(1) = acen(1)  -  tmp4 * a(1,i)
        acen(2) = acen(2)  -  tmp4 * a(2,i)
        acen(3) = acen(3)  -  tmp4 * a(3,i)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MFO_PN.FOR    (ErikSoft   3 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c ****** To be completed at a later date ******
c
c Calculates post-Newtonian relativistic corrective accelerations for a set
c of NBOD bodies (NBIG of which are Big).
c
c This routine should not be called from the symplectic algorithm MAL_MVS
c or the conservative Bulirsch-Stoer algorithm MAL_BS2.
c
c N.B. All coordinates and velocities must be with respect to central body!!!!
c ===
c------------------------------------------------------------------------------
c
      subroutine mfo_pn (nbod,nbig,m,x,v,a)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod, nbig
      real*8 m(nbod), x(3,nbod), v(3,nbod), a(3,nbod)
c
c Local
      integer j
c
c------------------------------------------------------------------------------
c
      do j = 1, nbod
        a(1,j) = 0.d0
        a(2,j) = 0.d0
        a(3,j) = 0.d0
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MFO_PR.FOR    (ErikSoft   3 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c ****** To be completed at a later date ******
c
c Calculates radiation pressure and Poynting-Robertson drag for a set
c of NBOD bodies (NBIG of which are Big).
c
c This routine should not be called from the symplectic algorithm MAL_MVS
c or the conservative Bulirsch-Stoer algorithm MAL_BS2.
c
c N.B. All coordinates and velocities must be with respect to central body!!!!
c ===
c------------------------------------------------------------------------------
c
c ##A38,132##
c      subroutine mfo_pr (nbod,nbig,m,x,v,a,ngf)
      subroutine mfo_pr (time,nbod,nbig,m,x,v,a,ngf,opt,optr,opti,
     %  K2,AU,MSUN,tstart,algor)
c ##A38,132##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod, nbig
      real*8 m(nbod), x(3,nbod), v(3,nbod), a(3,nbod), ngf(4,nbod)
c ##A38,133##
      real*8 time
      integer opt(9)
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
      real*8 tstart
      integer algor
c ##A38,133##
c
c Local
      integer j
      real*8 c,r
      real*8 xs(3),vs(3),rs,r_s2,beta,dot,rsh,ns,temp,q,r_s,xs0(3),rs0
      real*8 coef,Ca,Cb,Cc,Cd,Ra,Rb,Rc
      integer sflag
      real*8 rhocgs
      real*8 ang,x1,x2
c
c------------------------------------------------------------------------------
c
      do j = 1, nbod
        a(1,j) = 0.d0
        a(2,j) = 0.d0
        a(3,j) = 0.d0
      end do
c
c------------------------------------------------------------------------------
c
!     Doing Solar Radiation Pressure and Poynting–Robertson drag with cylindrical shadow (see. (Burns et al., 1979); (Sfair and Giuliatti Winter, 2009))
      rhocgs = AU * AU * AU * K2 / MSUN
c      c = 29979219744.2722 !speed of light in cm/s
c      c = c / AU
c      c = 1.d0 / c
      c = 1.d0 / optr(61)
c      coef   = (optr(54)-m(1)) * optr(53)
c
c     SUN state vectors
c      xs(1) = -dcos(optr(52)*time)
c      xs(2) = -dcos(optr(51))*dsin(optr(52)*time)
c      xs(3) = -dsin(optr(51))*dsin(optr(52)*time)
c      vs(1) =  optr(52)*dsin(optr(52)*time)
c      vs(2) = -dcos(optr(51))*optr(52)*dcos(optr(52)*time)
c      vs(3) = -dsin(optr(51))*optr(52)*dcos(optr(52)*time)
c
      ns = mod(optr(52) * (time - tstart), TWOPI)
c      if (opti(72).eq.0.and.algor.ge.13) then
c        ns = mod((optr(52) - optr(6)) * (time - tstart), TWOPI)
c      end if
c      Ra = -dcos(ns)
c      Rb = -dcos(optr(51))*dsin(ns)
c      Rc = -dsin(optr(51))*dsin(ns)
c
      q = optr(55) * (1.d0 - optr(56))
      call mco_el2x (optr(54),q,optr(56),optr(57),optr(58),optr(59),
     %  ns,xs(1),xs(2),xs(3),vs(1),vs(2),vs(3))
c Sol no sentido horário
c      xs(1) = -xs(1)
c      xs(2) = -xs(2)
c      xs(3) = -xs(3)
c      vs(1) = -vs(1)
c      vs(2) = -vs(2)
c      vs(3) = -vs(3)
c
cc      r_s2 = xs(1)*xs(1)+xs(2)*xs(2)+xs(3)*xs(3)
cc      rs   = dsqrt(r_s2)
      if (opti(72).eq.0.and.algor.ge.13) then
        ang = atan2(xs(2),xs(1))
        if (ang.lt.0.d0) ang = ang + 2*PI
        ang = mod(optr(6) * (time - tstart) - ang, TWOPI)
c        x1 = xs(1)
c        x2 = xs(2)
        r_s2 = xs(1)*xs(1)+xs(2)*xs(2)+xs(3)*xs(3)
        rs   = dsqrt(r_s2)
        x1 = rs
        x2 = 0.d0
c        if (ang.lt.0.d0) ang = -ang
        xs(1) =  x1*cos(ang)+x2*sin(ang)
        xs(2) = -x1*sin(ang)+x2*cos(ang)
      end if
c
c Pressão de radiação no sentido contrário à posição do Sol
c      r_s2 = xs(1)*xs(1)+xs(2)*xs(2)+xs(3)*xs(3)
c      rs   = dsqrt(r_s2)
cc      r_s = 1.d0 / rs
cc      Ra = -xs(1) * r_s
cc      Rb = -xs(2) * r_s
cc      Rc = -xs(3) * r_s
cc      r_s2 = 1.d0 / r_s2
c
c      r_s2 = xs(1)*xs(1)+xs(2)*xs(2)+xs(3)*xs(3)
c      rs   = dsqrt(r_s2)
c      r_s2 = 1.d0 / r_s2
c      coef = (optr(54)-m(1)) * r_s2
cc      Ca   = xs(1) * xs(1) * r_s2
cc      Cb   = xs(2) * xs(2) * r_s2
cc      Cc   = xs(3) * xs(3) * r_s2
c      coef = 0.75 * c * r_s2
c      coef = 0.75 * r_s2 * (optr(54)-m(1))
cc      coef = 0.75 * r_s2 * c / rhocgs * K2
c
      xs0(1) = xs(1)
      xs0(2) = xs(2)
      xs0(3) = xs(3)
      rs0  = dsqrt(xs0(1)*xs0(1)+xs0(2)*xs0(2)+xs0(3)*xs0(3))
      do j = 2, nbod
        xs(1) = xs0(1)-x(1,j)
        xs(2) = xs0(2)-x(2,j)
        xs(3) = xs0(3)-x(3,j)
        r_s2 = xs(1)*xs(1)+xs(2)*xs(2)+xs(3)*xs(3)
        rs   = dsqrt(r_s2)
c
        r_s = 1.d0 / rs
        Ra = -xs(1) * r_s
        Rb = -xs(2) * r_s
        Rc = -xs(3) * r_s
        r_s2 = 1.d0 / r_s2
c
        Ca   = xs(1) * xs(1) * r_s2
        Cb   = xs(2) * xs(2) * r_s2
        Cc   = xs(3) * xs(3) * r_s2
c
        coef = 0.75 * r_s2 * c / rhocgs * K2
c shadow analysis
        if (j.lt.opti(77).or.j.gt.opti(78)) then
          sflag = 0
          r   = dsqrt(x(1,j)*x(1,j)+x(2,j)*x(2,j)+x(3,j)*x(3,j))
          dot = xs0(1)*x(1,j)+xs0(2)*x(2,j)+xs0(3)*x(3,j)
          beta= acos(dot / (r * rs0))
          if (beta.gt.PI*0.5) then
            rsh = r * dsin(PI-beta)
            if (rsh.le.optr(53)) sflag = 1
          end if
          if (sflag.eq.0) then
c SRP and P-R components
c            Cd = coef * ngf(4,j) * r * r
            Cd = coef * ngf(4,j)
c            a(1,j) = Cd*(Ra-c*(vs(1)+v(1,j))*(Ca+1))
c            a(2,j) = Cd*(Rb-c*(vs(2)+v(2,j))*(Cb+1))
c            a(3,j) = Cd*(Rc-c*(vs(3)+v(3,j))*(Cc+1))
            a(1,j) = Cd*Ra
            a(2,j) = Cd*Rb
            a(3,j) = Cd*Rc
          end if
        end if
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_C2FL.FOR    (ErikSoft  1 July 1999)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Converts a CHARACTER*8 ASCII string into a REAL*8 variable.
c
c N.B. X will lie in the range -1.e112 < X < 1.e112
c ===
c
c------------------------------------------------------------------------------
c
      function mio_c2fl (c)
c
      implicit none
c
c Input/Output
      real*8 mio_c2fl
      character*8 c
c
c Local
      integer ex
      real*8 x,mio_c2re
c
c------------------------------------------------------------------------------
c
      x = mio_c2re (c(1:8), 0.d0, 1.d0, 7)
      x = x * 2.d0 - 1.d0
      ex = ichar(c(8:8)) - 32 - 112
      mio_c2fl = x * (10.d0**dble(ex))
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_C2RE.FOR    (ErikSoft  1 July 1999)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Converts an ASCII string into a REAL*8 variable X, where XMIN <= X < XMAX,
c using the new format compression:
c
c X is assumed to be made up of NCHAR base-224 digits, each one represented
c by a character in the ASCII string. Each digit is given by the ASCII
c number of the character minus 32.
c The first 32 ASCII characters (CTRL characters) are avoided, because they
c cause problems when using some operating systems.
c
c------------------------------------------------------------------------------
c
      function mio_c2re (c,xmin,xmax,nchar)
c
      implicit none
c
c Input/output
      integer nchar
      real*8 xmin,xmax,mio_c2re
      character*8 c
c
c Local
      integer j
      real*8 y
c
c------------------------------------------------------------------------------
c
      y = 0
      do j = nchar, 1, -1
        y = (y + dble(ichar(c(j:j)) - 32)) / 224.d0
      end do
c
      mio_c2re = xmin  +  y * (xmax - xmin)
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_CE.FOR    (ErikSoft   1 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Writes details of close encounter minima to an output file, and decides how
c to continue the integration depending upon the close-encounter option
c chosen by the user. Close encounter details are stored until either 100
c have been accumulated, or a data dump is done, at which point the stored
c encounter details are also output.
c
c For each encounter, the routine outputs the time and distance of closest
c approach, the identities of the objects involved, and the output
c variables of the objects at this time. The output variables are:
c expressed as
c  r = the radial distance
c  theta = polar angle
c  phi = azimuthal angle
c  fv = 1 / [1 + 2(ke/be)^2], where be and ke are the object's binding and
c                             kinetic energies. (Note that 0 < fv < 1).
c  vtheta = polar angle of velocity vector
c  vphi = azimuthal angle of the velocity vector
c
c------------------------------------------------------------------------------
c
c ##A2,8##
c ##A5,17##
c ##A24,16##
c ##AN28,55##
c ##A35,48##
      subroutine mio_ce (time,tstart,rcen,rmax,nbod,nbig,m,stat,id,
     %  nclo,iclo,jclo,opt,stopflag,tclo,dclo,ixvclo,jxvclo,mem,
     %  lmem,outfile,nstored,ceflush,nflush,aux,cce,algor,jcen,s,rho,
     %  nbclo,bclo,flagce,opti,optr,K2,AU,MSUN,idtag)
c ##A35,48##
c ##AN28,55##
c ##A24,16##
c ##A5,17##
c ##A2,8##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,opt(9),stat(nbod),lmem(NMESS),stopflag
      integer nclo,iclo(nclo),jclo(nclo),nstored,ceflush
      real*8 time,tstart,rcen,rmax,m(nbod),tclo(nclo),dclo(nclo)
      real*8 ixvclo(6,nclo),jxvclo(6,nclo)
      character*80 outfile(4),mem(NMESS)
      character*8 id(nbod)
c ##A2,7##
      integer nflush
c ##A2,7##
c ##A5,10##
      integer algor
      real*8 jcen(3)
      real*8 s(3,nbod),rho(nbod)
      integer nbclo,bclo(nbod)
      character*1 aux(CMAX)
      character*107 cce(FMAX)
      integer flagce(2)
c ##A5,10##
c ##A24,15##
      integer opti(90)
      real*8 optr(76)
c ##A24,15##
c ##AN28,54##
      real*8 K2,AU,MSUN
c ##AN28,54##
c ##A35,49##
      integer idtag(nbod)
c ##A35,49##
c
c Local
      integer k,year,month
      real*8 tmp0,t1,rfac,fr,fv,theta,phi,vtheta,vphi
      character*80 c(200)
      character*38 fstop
      character*8 mio_fl2c, mio_re2c
      character*6 tstring
c
c------------------------------------------------------------------------------
c
c ##A5,9##
c      save c
c
c Scaling factor (maximum possible range) for distances
c      rfac = log10 (rmax / rcen)
c
c Store details of each new close-encounter minimum
c
c dcarrera 2014-10-29
c          Replace nclo -> min(nclo,CMAX) to avoid overflow errors.
c
c ##E12,13##
c      do k = 1, min(nclo,CMAX)
c ##E12,13##
c        nstored = nstored + 1
c        c(nstored)(1:8)   = mio_fl2c(tclo(k))
c        c(nstored)(9:16)  = mio_re2c(dble(iclo(k)-1),0.d0,11239423.99d0)
c        c(nstored)(12:19) = mio_re2c(dble(jclo(k)-1),0.d0,11239423.99d0)
c        c(nstored)(15:22) = mio_fl2c(dclo(k))
c
c        call mco_x2ov (rcen,rmax,m(1),0.d0,ixvclo(1,k),ixvclo(2,k),
c     %    ixvclo(3,k),ixvclo(4,k),ixvclo(5,k),ixvclo(6,k),fr,theta,phi,
c     %    fv,vtheta,vphi)
c        c(nstored)(23:30) = mio_re2c (fr    , 0.d0, rfac)
c        c(nstored)(27:34) = mio_re2c (theta , 0.d0, PI)
c        c(nstored)(31:38) = mio_re2c (phi   , 0.d0, TWOPI)
c        c(nstored)(35:42) = mio_re2c (fv    , 0.d0, 1.d0)
c        c(nstored)(39:46) = mio_re2c (vtheta, 0.d0, PI)
c        c(nstored)(43:50) = mio_re2c (vphi  , 0.d0, TWOPI)
c
c        call mco_x2ov (rcen,rmax,m(1),0.d0,jxvclo(1,k),jxvclo(2,k),
c     %    jxvclo(3,k),jxvclo(4,k),jxvclo(5,k),jxvclo(6,k),fr,theta,phi,
c     %    fv,vtheta,vphi)
c        c(nstored)(47:54) = mio_re2c (fr    , 0.d0, rfac)
c        c(nstored)(51:58) = mio_re2c (theta , 0.d0, PI)
c        c(nstored)(55:62) = mio_re2c (phi   , 0.d0, TWOPI)
c        c(nstored)(59:66) = mio_re2c (fv    , 0.d0, 1.d0)
c        c(nstored)(63:74) = mio_re2c (vtheta, 0.d0, PI)
c        c(nstored)(67:78) = mio_re2c (vphi  , 0.d0, TWOPI)
c      end do
c ##E5,6##
c ##ANO29,39##
c ##E19,14##
      if (opti(41).ne.1) call mio_cestored (rcen,rmax,nbod,m,nclo,iclo,
     %  jclo,opt(4),tclo,dclo,ixvclo,jxvclo,nstored,aux,cce,bclo,algor,
     %  optr)
c ##E19,14##
c ##ANO29,39##
c ##E5,6##
c ##A5,9##
c
c If required, output the stored close encounter details
c ##A2,6##
      if (nstored.ge.nflush.or.ceflush.eq.0) then
c ##A2,6##
c ##A24,14##
c ##AN28,130##
        call mce_criteria (time,tstart,nbod,algor,opt(3),m,id,
     %  opti,optr,mem,lmem,nbclo,nstored,K2)
c ##AN28,130##
c ##A24,14##
c ##A5,14##
  30    continue
c ##A23,12##
c ##AN28,53##
c ##A32,32##
c ##A35,47##
        call mce_header (tstart,algor,jcen,rcen,rmax,nbod,m,s,rho,
     %  id,opt,outfile(2),nbclo,bclo,nstored,nbig,K2,AU,MSUN,optr,
     %  idtag)
c ##A35,47##
c ##A32,32##
c ##AN28,53##
c ##A23,12##
        call mio_ceflush (opt(4),outfile(2),nstored,cce)
c  10    open (22, file=outfile(2), status='old', access='append',err=10)
c        do k = 1, nstored
c          write (22,'(a1,a2,a70)') char(12),'6b',c(k)(1:70)
c        end do
c        close (22)
c        nstored = 0
        if (flagce(1).eq.flagce(2).and.opt(1).ne.1) then
          flagce(2) = 1
          nbclo = nbod - 1
          do k = 1, nbclo
            bclo(k) = k + 1
          end do
          goto 30
        end if
        flagce(1) = 0
c ##A5,14##
      end if
c
c If new encounter minima have occurred, decide whether to stop integration
      stopflag = 0
      if (opt(1).eq.1.and.nclo.gt.0) then
c ##E9,11##
c  20    open (23, file=outfile(3), status='old', access='append',err=20)
c ##E9,11##
c If time style is Gregorian date then...
        tmp0 = tclo(1)
        if (opt(3).eq.1) then
          fstop = '(5a,/,9x,a,i10,1x,i2,1x,f4.1)'
          call mio_jd2y (tmp0,year,month,t1)
c ##A5,15##
          write (23,fstop) mem(121)(1:lmem(121)),mem(126)
     %      (1:lmem(126)),id(bclo(iclo(1))),',',id(bclo(jclo(1))),
     %      mem(71)(1:lmem(71)),year,month,t1
c ##A5,15##
c ##A12,1##
          write (*,fstop) mem(121)(1:lmem(121)),mem(126)
     %      (1:lmem(126)),id(bclo(iclo(1))),',',id(bclo(jclo(1))),
     %      mem(71)(1:lmem(71)),year,month,t1
c ##A12,1##
c Otherwise...
        else
          if (opt(3).eq.3) then
            tstring = mem(2)
            fstop = '(5a,/,9x,a,f14.3,a)'
            t1 = (tmp0 - tstart) / 365.25d0
          else
            tstring = mem(1)
            fstop = '(5a,/,9x,a,f14.1,a)'
            if (opt(3).eq.0) t1 = tmp0
            if (opt(3).eq.2) t1 = tmp0 - tstart
          end if
c ##A5,16##
          write (23,fstop) mem(121)(1:lmem(121)),mem(126)
     %      (1:lmem(126)),id(bclo(iclo(1))),',',id(bclo(jclo(1))),
     %      mem(71)(1:lmem(71)),t1,tstring
c ##A5,16##
c ##A12,2##
          write (*,fstop) mem(121)(1:lmem(121)),mem(126)
     %      (1:lmem(126)),id(bclo(iclo(1))),',',id(bclo(jclo(1))),
     %      mem(71)(1:lmem(71)),t1,tstring
c ##A12,2##
        end if
        stopflag = 1
c ##E9,12##
c        close(23)
c ##E9,12##
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_DUMP.FOR    (ErikSoft   21 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Writes masses, coordinates, velocities etc. of all objects, and integration
c parameters, to dump files. Also updates a restart file containing other
c variables used internally by MERCURY.
c
c------------------------------------------------------------------------------
c
c ##A1,25##
c ##A2,25##
c ##A3,23##
c ##E9,49##
c ##A19,127##
c ##A20,18##
c ##AN28,14##
c ##A35,27##
c ##A38,142##
c ##A19,214##
      subroutine mio_dump (time,tstart,tstop,dtout,algor,h0,tol,jcen,
     %  rcen,rmax,en,am,cefac,ndump,nfun,nbod,nbig,m,x,v,s,rho,rceh,
     %  stat,id,ngf,epoch,opt,opflag,dumpfile,mem,lmem,optr,opti,rmin,
     %  dtdump,nov,nop,noc,dens,binfile,outfile,treal,tuser,tsys,
     %  K2,AU,MSUN,idtag,ngflag,xv,yv,zv,noe,kkk,mc,xc,yc,zc)
c ##A19,214##
c ##A38,142##
c ##A35,27##
c ##AN28,14##
c ##A20,18##
c ##A19,127##
c ##E9,49##
c ##A3,23##
c ##A2,25##
c ##A1,25##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer algor,nbod,nbig,stat(nbod),opt(9),opflag,ndump,nfun
      integer lmem(NMESS)
      real*8 time,tstart,tstop,dtout,h0,tol,rmax,en(3),am(3)
      real*8 jcen(3),rcen,cefac,m(nbod),x(3,nbod),v(3,nbod)
      real*8 s(3,nbod),rho(nbod),rceh(nbod),ngf(4,nbod),epoch(nbod)
      character*80 dumpfile(5),mem(NMESS)
      character*8 id(nbod)
c ##A1,24##
      real*8 optr(76)
c ##A1,24##
c ##A2,24##
      integer opti(90)
c ##A2,24##
c ##A3,22##
      real*8 rmin
c ##A3,22##
c ##E9,50##
      real*8 dtdump
c ##E9,50##
c ##A19,128##
      integer nov,nop,noc
      real*8 dens(noc)
      character*80 binfile(101)
      real*8 a2,b2,c2
c ##A19,128##
c ##A20,19##
      character*80 outfile(4)
      real*8 treal,tuser,tsys
c ##A20,19##
c ##AN28,15##
      real*8 K2,AU,MSUN
c ##AN28,15##
c ##A35,28##
      integer idtag(nbod)
c ##A35,28##
c ##A19,213##
      integer noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
c ##A19,213##
c
c Local
      integer idp,i,j,k,len,j1,j2,ngflag
      real*8 rhocgs,k_2,rcen_2,rcen_4,rcen_6,x0(3,NMAX),v0(3,NMAX)
      character*150 c
c ##A20,20##
      real*4 dtime,etime,t(2)
      real*8 treal2,tuser2,tsys2
c ##A20,20##
c ##ANO29,43##
      real*8 tmpr27
c ##ANO29,43##
c
c------------------------------------------------------------------------------
c
      rhocgs = AU * AU * AU * K2 / MSUN
      k_2 = 1.d0 / K2
      rcen_2 = 1.d0 / (rcen * rcen)
      rcen_4 = rcen_2 * rcen_2
      rcen_6 = rcen_4 * rcen_2
c
c ##A19,146##
      if (optr(9).eq.0.d0) then
        a2 = optr(9)
      else
        a2 = 1.d0/dsqrt(optr(9))
      end if
      if (optr(10).eq.0.d0) then
        b2 = optr(10)
      else
        b2 = 1.d0/dsqrt(optr(10))
      end if
      if (optr(11).eq.0.d0) then
        c2 = optr(11)
      else
        c2 = 1.d0/dsqrt(optr(11))
      end if
c ##A19,146##
c ##ANO29,44##
      tmpr27 = optr(27)
      if (algor.ge.13) tmpr27 = tmpr27 * .5d0
c ##ANO29,44##
c
c If using close-binary star, convert to user coordinates
c ##AAR1,3##
c ##A15,6##
c      if (algor.eq.11.or.algor.eq.5) call mco_h2ub (time,jcen,nbod,nbig,h0,m,x,v,
c     %   x0,v0,ngf,ngflag,opt)
c ##A15,6##
c ##AAR1,3##
c
c ##A20,21##
      treal2 = dtime ( t )
      tuser2 = t(1)
      tsys2  = t(2)
      treal = treal + treal2
      tuser = tuser + tuser2
      tsys  = tsys  + tsys2
c ##A20,21##
c
c Dump to temporary files (idp=1) and real dump files (idp=2)
      do idp = 1, 2
c
c Dump data for the Big (i=1) and Small (i=2) bodies
        do i = 1, 2
          if (idp.eq.1) then
c ##A21,9##
            if (i.eq.1) c(1:15) = './dmp/big.tmp  '
            if (i.eq.2) c(1:15) = './dmp/small.tmp'
  20        open (31, file=c(1:15), status='unknown', err=20)
c ##A21,9##
          else
  25        open (31, file=dumpfile(i), status='old', err=25)
          end if
c
c Write header lines, data style (and epoch for Big bodies)
          write (31,'(a)') mem(151+i)(1:lmem(151+i))
          if (i.eq.1) then
            j1 = 2
            j2 = nbig
          else
            j1 = nbig + 1
            j2 = nbod
          end if
          write (31,'(a)') mem(154)(1:lmem(154))
          write (31,'(a)') mem(155)(1:lmem(155))
c ##A16,18##
c          write (31,*) mem(156)(1:lmem(156)),'Cartesian'
          if (i.eq.1) then
            write (31,*) mem(157)(1:lmem(157)),time
            write (31,'(a)') mem(155)(1:lmem(155))
          end if
c ##A16,18##
c
c For each body...
          do j = j1, j2
c ##A35,29##
            len = 47
c ##A35,29##
            c(1:8) = id(j)
c ##A35,30##
            write (c(9:18),'(a3,i7)') ' i=',idtag(j)
c
            write (c(19:47),'(1p,a3,e11.5,a3,e11.5)') ' r=',rceh(j),
     %        ' d=',rho(j)/rhocgs
            if (m(j).gt.0) then
              write (c(len+1:len+25),'(a3,e22.15)') ' m=',m(j)*k_2
              len = len + 25
            end if
            do k = 1, 3
              if (ngf(k,j).ne.0) then
                write (c(len+1:len+16),'(a2,i1,a1,e12.5)') ' a',k,'=',
     %            ngf(k,j)
                len = len + 16
              end if
            end do
            if (ngf(4,j).ne.0) then
              write (c(len+1:len+15),'(a3,e12.5)') ' b=',ngf(4,j)
              len = len + 15
            end if
c ##A35,30##
            write (31,'(a)') c(1:len)
c ##A16,19##
c ##A26,9##
            write (31,'(a3,1x,a8,1x,a3)') 'Car',id(1),'Ine'
c ##A26,9##
c ##A16,19##
c ##A15,7##
c ##AAR1,18##
c            if (algor.eq.11.or.algor.eq.5) then
c ##AAR1,18##
c              write (31,312) x0(1,j), x0(2,j), x0(3,j)
c              write (31,312) v0(1,j), v0(2,j), v0(3,j)
c            else
              write (31,312) x(1,j), x(2,j), x(3,j)
              write (31,312) v(1,j), v(2,j), v(3,j)
c            end if
c ##A15,7##
            write (31,312) s(1,j)*k_2, s(2,j)*k_2, s(3,j)*k_2
          enddo
          close (31)
        end do
c
c Dump the integration parameters
c ##A21,10##
  40    if (idp.eq.1) open (33,file='./dmp/param.tmp',status='unknown',
     %    err=40)
c ##A21,10##
  45    if (idp.eq.2) open (33, file=dumpfile(3), status='old', err=45)
c
c Important parameters
        write (33,'(a)') mem(151)(1:lmem(151))
        write (33,'(a)') mem(154)(1:lmem(154))
        write (33,'(a)') mem(155)(1:lmem(155))
        write (33,'(a)') mem(158)(1:lmem(158))
        write (33,'(a)') mem(155)(1:lmem(155))
        if (algor.eq.1) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'MVS'
        else if (algor.eq.2) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'BS'
        else if (algor.eq.3) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'BS2'
        else if (algor.eq.4) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'RAD'
        else if (algor.eq.10) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'HYB'
        else if (algor.eq.11) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'CLO'
        else if (algor.eq.12) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'WID'
c ##AAR1,19##
        else if (algor.eq.5) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'SABP'
c ##AAR1,19##
c ##A19,131##
        else if (algor.eq.13) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'POL'
        else if (algor.eq.14) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'MAS'
        else if (algor.eq.15) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'AST'
        else if (algor.eq.16) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'POLBS2'
        else if (algor.eq.17) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'MASBS2'
        else if (algor.eq.18) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'ASTBS2'
        else if (algor.eq.19) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'POLRAD'
        else if (algor.eq.20) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'MASRAD'
        else if (algor.eq.21) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'ASTRAD'
        else if (algor.eq.22) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'ASTHYB'
        else if (algor.eq.23) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'ASTHRA'
c ##A19,131##
c ##ANEO27,19##
        else if (algor.eq.6) then
          write (33,'(2a)') mem(159)(1:lmem(159)),'HYBRAD'
c ##ANEO27,19##
        else
          write (33,'(2a)') mem(159)(1:lmem(159)),'0'
        end if
        write (33,*) mem(160)(1:lmem(160)),tstart
        write (33,*) mem(161)(1:lmem(161)),tstop
        write (33,*) mem(162)(1:lmem(162)),dtout
c ##E9,51##
        write (33,*) mem(203)(1:lmem(203)),dtdump
c ##E9,51##
        write (33,*) mem(163)(1:lmem(163)),h0
        write (33,*) mem(164)(1:lmem(164)),tol
c ##A31,3##
        if (opti(51).eq.0) then
          write (33,'(2a)') mem(335)(1:lmem(335)),mem(5)(1:lmem(5))
        else
          write (33,'(2a)') mem(335)(1:lmem(335)),mem(6)(1:lmem(6))
        end if
c ##A31,3##
c ##A19,129##
c        write (33,*) mem(217)(1:lmem(217)),nov
c        write (33,*) mem(218)(1:lmem(218)),nop
        if (opti(72).eq.0) then
          write (33,'(2a)') mem(417)(1:lmem(417)),mem(5)(1:lmem(5))
        else
          write (33,'(2a)') mem(417)(1:lmem(417)),mem(6)(1:lmem(6))
        end if
c ##A19,129##
c ##A41,3##
        if (opti(86).eq.0) then
          write (33,'(2a)') mem(449)(1:lmem(449)),mem(5)(1:lmem(5))
        else
          write (33,'(2a)') mem(449)(1:lmem(449)),mem(6)(1:lmem(6))
        end if
c ##A41,3##
