        C20 = -1.d0/(2.d0*mcen)*(2.d0*JC(3,3)-JC(1,1)-JC(2,2))
        C22 =  1.d0/(4.d0*mcen)*(JC(2,2)-JC(1,1))
        massd = (JC(2,2)-JC(1,1))/(JC(3,3)-JC(1,1))
c
        if (.not.oldflag) then
          write(23,'(/,a,i7)') mem(370)(1:lmem(370)),nov
          write(23,'(a,i7)') mem(371)(1:lmem(371)),nop
