          write(23,'(a,1p,e22.15)') mem(237)(1:lmem(237)),mcen
          write(23,'(2a,3(1p,e22.15,a))') mem(235)(1:lmem(235)),
     %      mem(234)(1:lmem(234)),xct,mem(232)(1:lmem(232)),
