          write(23,'(a)') mem(236)(1:lmem(236))
          write(23,'(3(1x,1p,e22.15))') JC(1,1),JC(1,2),JC(1,3)
          write(23,'(3(1x,1p,e22.15))') JC(2,1),JC(2,2),JC(2,3)
          write(23,'(3(1x,1p,e22.15))') JC(3,1),JC(3,2),JC(3,3)
          write(23,'(a)') mem(251)(1:lmem(251))
          write(23,'(3(1x,1p,e22.15))') JC(1,1)/mcen,JC(2,2)/mcen,
     %      JC(3,3)/mcen
          write(23,'(a)') mem(254)(1:lmem(254))
          write(23,'(2(a,1p,e22.15))') mem(256)(1:lmem(256)),
     %      C20,mem(257)(1:lmem(257)),C22
          write(23,'(a,1p,e22.15)') mem(255)(1:lmem(255)),
     %      massd
        endif
c
        call EigenVectors (23,mem,lmem,JC,eigV,eigVa,oldflag)
c
        eA = sqrt(5.d0*(eigVa(2)+eigVa(3)-eigVa(1))/(2.d0*mcen))
        eB = sqrt(5.d0*(eigVa(1)+eigVa(3)-eigVa(2))/(2.d0*mcen))
        eC = sqrt(5.d0*(eigVa(1)+eigVa(2)-eigVa(3))/(2.d0*mcen))
c
        if (.not.oldflag) then
          write(23,'(3(a,1p,e22.15))') mem(252)(1:lmem(252)),
     %      eA,mem(253)(1:lmem(253)),eB,mem(253)(1:lmem(253)),eC
c
          write(23,'(a)') mem(258)(1:lmem(258))
          write(23,'(3(1x,1p,e22.15))') T1b(1),T1b(2),T1b(3)
          write(23,'(3(1x,1p,e22.15))') T2(1),T2(2),T2(3)
          write(23,'(3(1x,1p,e22.15))') TP(1),TP(2),TP(3)
        endif
c
c        call masc_rot (noc,xc,yc,zc,xct,yct,zct,eigV)
c        call masc_rot (nov,xv,yv,zv,xct,yct,zct,eigV)
c
        call masc_rot1 (nov,xv,yv,zv,xct,yct,zct)
        call cross_ast (nov,nop,noe,kkk,xv,yv,zv,face1)
        call masc_rot2 (nov,xv,yv,zv,eigV)
        call cross_ast (nov,nop,noe,kkk,xv,yv,zv,face2)
c
c        call reorientation (face1,face2,nov,nop,noe,kkk)
        call reorientation2 (face1,face2,nov,nop,noe,kkk)
c
      if (opti(86).eq.1.and.opti(23).eq.0) then
c        call masc_layer3 (nov,nop,xv,yv,zv,noe,k,dens(1),
c     %  mcenb,vc,xc,yc,zc,mem,lmem,noc,cubx,cuby,cubz,mc)
        call masc_layer4b (nov,nop,xv,yv,zv,noe,kkk,dens(1),
     %  mcenb,vc,xc,yc,zc,mem,lmem,noc,optr(14),optr(15),optr(16),mc)
        do j = 1, noc
          mc(j) = mc(j) * K2
        end do
        if (.not.oldflag) then
          write(23,'(a,i7)') mem(372)(1:lmem(372)),noc
          write(23,'(a,1p,e22.15)') mem(239)(1:lmem(239)),vc
          rcenv = ((3.0/(4.0*pi))*vc)**(1.0/3.0)
          write(23,'(a,1p,e22.15)') mem(238)(1:lmem(238)),rcenv
        end if
      end if
c
c        call masc_cen (nop,xv,yv,zv,noe,kkk,xc,yc,zc)
c        else if (opti(23).eq.1) then
c
