c     %        mc,mcen,vc,xc,yc,zc,mem,lmem,noc,T1b,T2,TP,J0)
c          else if (opti(86).eq.1) then
c            call masc_layer2 (nov,nop,xv,yv,zv,noe,kkk,dens,opti(21),
