c            write(23,'(a,i7)') mem(372)(1:lmem(372)),noc
c            write(23,'(a,1p,e22.15)') mem(239)(1:lmem(239)),vc
c            write(23,'(a,1p,e22.15)') mem(238)(1:lmem(238)),rcenv
c            write(23,'(a,1p,e22.15)') mem(237)(1:lmem(237)),mcen
c            write(23,'(2a,3(1p,e22.15,a))') mem(235)(1:lmem(235)),
c     %        mem(234)(1:lmem(234)),xct,mem(232)(1:lmem(232)),
c     %        yct,mem(232)(1:lmem(232)),zct,mem(233)(1:lmem(233))
c          end if
c        else if (opti(23).eq.0.and.giulia.eq.1) then
c          call masc_rot (noc,xc,yc,zc,xct,yct,zct,eigV)
c        end if
c        end if
c
c        if (.not.oldflag) then
c          write(23,'(a)') mem(258)(1:lmem(258))
c          write(23,'(3(1x,1p,e22.15))') T1b(1),T1b(2),T1b(3)
c          write(23,'(3(1x,1p,e22.15))') T2(1),T2(2),T2(3)
c          write(23,'(3(1x,1p,e22.15))') TP(1),TP(2),TP(3)
c        end if
c
        if (opti(86).eq.0.and.opti(23).eq.1) then
c
        write(6,'(3x,a35,a15)') 'Reading Polyhedron information from',
     %    ' binary file...'
c
          optr(14) = 1.d0/(optr(14)*optr(14))
          optr(15) = 1.d0/(optr(15)*optr(15))
          optr(16) = 1.d0/(optr(16)*optr(16))
        call readbinpol (binfile,mem,lmem,opti(24),optr(17),optr(18),
     %    optr(19),optr(20),optr(21),optr(22),optr(14),optr(15),
     %    optr(16),omg,apot,optr(9),optr(10),optr(11))
          optr(6) = omg
          optr(14) = dsqrt(1.d0/(optr(14)*optr(14)))
          optr(15) = dsqrt(1.d0/(optr(15)*optr(15)))
          optr(16) = dsqrt(1.d0/(optr(16)*optr(16)))
        end if
        if (rcen.eq.0) then
          rcen = rcenv
          optr(49) = 0.1d0 * dabs(rcen)
        end if
      end if
c ##A19,19##
c
c------------------------------------------------------------------------------
c
c Change quantities for central object to suitable units
      m(1) = abs(m(1)) * K2
      jcen(1) = jcen(1) * rcen * rcen
      jcen(2) = jcen(2) * rcen * rcen * rcen * rcen
      jcen(3) = jcen(3) * rcen * rcen * rcen * rcen * rcen * rcen
      s(1,1) = 0.d0
      s(2,1) = 0.d0
      s(3,1) = 0.d0
c
c Make sure that RCEN isn't too small, since it is used to scale the output
c (Minimum value corresponds to a central body with density 100g/cm^3).
      temp = 1.1235d-3 * m(1) ** .333333333333333d0
      if (rcen.lt.temp) then
        rcen = temp
c ##E10,1##
        write (23,'(/,2a)') mem(121)(1:lmem(121)),mem(131)(1:lmem(131))
c ##E10,1##
      end if
c
c ##A38,105##
      if (optr(53).eq.0) optr(53) = rcen
      optr(54) = abs(optr(54)) * K2 + m(1)
c ##A38,105##
c
c------------------------------------------------------------------------------
c
c  READ  IN  DATA  FOR  BIG  AND  SMALL  BODIES  FOR THE FIRST TIME
c
c ##A16,15##
      nbod = 1
      do j = 1, 2
c
c Check if the file containing data for Big bodies exists, and open it
        filename = infile(j)
        if (oldflag) filename = dumpfile(j)
        inquire (file=filename, exist=test)
        if (.not.test) call mio_err (23,mem(81),lmem(81),mem(88),
     %    lmem(88),' ',1,filename,80)
 111    open (11, file=filename, status='old', err=111)
c
c Read epoch of Big bodies
        if (j.eq.1) then 
 126      read (11,'(a150)') string
          if (string(1:1).eq.')') goto 126
c ##A26,11##
          call mio_spl (150,string,nsub,lim)
c ##EAN16,6##
          if (lim(1,1).eq.-1) goto 126
c ##EAN16,6##
          read (string(lim(1,nsub):lim(2,nsub)),*,err=667) time
c ##A26,11##
        end if
c
c Read information for each object
 131    read (11,'(a)',end=141) string
        if (string(1:1).eq.')') goto 131
c ##A38,134##
        call mio_spl (250,string,nsub,lim)
c ##A38,134##
c ##EAN16,4##
        if (lim(1,1).eq.-1) goto 131
c ##EAN16,4##
c
c Determine the name of the object
        nbod = nbod + 1
        if (nbod.gt.NMAX) call mio_err (23,mem(81),lmem(81),mem(90),
     %    lmem(90),' ',1,mem(82),lmem(82))
c
        if ((lim(2,1)-lim(1,1)).gt.7) then
          write (23,'(/,3a)') mem(121)(1:lmem(121)),
     %      mem(122)(1:lmem(122)),string( lim(1,1):lim(2,1) )
        end if
        id(nbod) = string( lim(1,1):min(7+lim(1,1),lim(2,1)) )
c Check if another object has the same name
        do k = 1, nbod - 1
          if (id(k).eq.id(nbod)) call mio_err (23,mem(81),lmem(81),
     %      mem(103),lmem(103),id(nbod),8,' ',1)
        end do
c
c Default values of mass, close-encounter limit, density etc.
        m(nbod) = 0.d0
c ##A35,2##
        idtag(nbod) = nbod
c ##A35,2##
c
c Read values of mass, close-encounter limit, density etc.
        do k = 3, nsub, 2
          c80 = string(lim(1,k-1):lim(2,k-1))
          read (string(lim(1,k):lim(2,k)),*,err=666) temp
          if (c80(1:1).eq.'m'.or.c80(1:1).eq.'M') then
            m(nbod) = temp * K2
          end if
        end do
c
c Read data style
 121    read (11,'(a150)') string
        if (string(1:1).eq.')') goto 121
c
c If required, read Cartesian coordinates, velocities and spins of the bodies
 136    read (11,'(a150)',end=666) string
        if (string(1:1).eq.')') goto 136
        backspace 11
        read (11,*,err=666) x(1,nbod),x(2,nbod),x(3,nbod),
     %    v(1,nbod),v(2,nbod),v(3,nbod),s(1,nbod),s(2,nbod),s(3,nbod)
        goto 131
 141    close (11)
      end do
      nbod0 = nbod
c
      if (informat(1).ne.1) then
        a = x(1,1)
        e = x(2,1)
        i = x(3,1)
        p = v(1,1)
        n = v(2,1)
        l = v(3,1)
c
        i = i * DR
        p = (p + n) * DR
        n = n * DR
        l = l * DR
c
c ##A38,107##
        optr(55) = a
        optr(56) = e
        i = i - optr(51)
        if (i.lt.0.d0) i = i + 2*PI
        if (i.gt.PI) then
          i = 2*PI - i
          n = n + PI
        end if
        optr(57) = i
        optr(58) = p
        optr(59) = n
        optr(60) = l
c ##A38,107##
c
        i0 = 2
        flagid = 0
        do k = 1, nbod0
          if (oid0(1:8).eq.id(k)(1:8)) then
            flagid = 1
            i0 = k
          end if
        end do
        if (oid0(1:1).eq.' ') flagid = 1
c Check if some object there isn't
        if (flagid.eq.0) call mio_err (23,mem(81),lmem(81),mem(116),
     %    lmem(116),oid0,8,mem(82+3),lmem(82+3))
        temp = m(1)  +  m(i0)
c ##AAR1,41##
c a1 = m2 / (m1 + m2) * a
        if (algor.eq.11.or.algor.eq.5) temp = m(2)**3 / (m(1) + m(2))**2
c ##AAR1,41##
c
c Alternatively, read Cometary or asteroidal elements
        if (informat(1).eq.3) then
          q = a
          a = q / (1.d0 - e)
          l = mod (sqrt(temp/(abs(a*a*a))) * (epoch(nbod) - l), TWOPI)
        else
          q = a * (1.d0 - e)
c          l = l * DR
        end if
        call mco_el2x (temp,q,e,i,p,n,l,x(1,1),x(2,1),x(3,1),
     %    v(1,1),v(2,1),v(3,1))
c ##A38,108##
      else
        call mco_x2el (optr(54),x(1,1),x(2,1),x(3,1),v(1,1),v(2,1),
     %    v(3,1),optr(55),optr(56),optr(57),optr(58),optr(59),optr(60))
        optr(55) = optr(55) / (1.d0 - optr(56))
        i = optr(57)
        n = optr(59)
        i = i - optr(51)
        if (i.lt.0.d0) i = i + 2*PI
        if (i.gt.PI) then
          i = 2*PI - i
          n = n + PI
        end if
        optr(57) = i
        optr(59) = n
c ##A38,108##
      end if
c ##A16,15##
c ##A26,4##
      if (informat2(1).eq.2) then
c ##A38,41##
        call mco_iden(time,jcen,1,nbig,h0,m,x,v,x0,v0,ngf,ngflag,
     %    opt,optr,opti,K2,AU,MSUN)
        call mco_ast2h (time,jcen,1,1,optr(6),m,x0,v0,x,v,ngf,
     %    ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,41##
      end if
c ##A26,4##
c
c------------------------------------------------------------------------------
c
c  READ  IN  DATA  FOR  BIG  AND  SMALL  BODIES
c
      nbod = 1
      do j = 1, 2
        if (j.eq.2) nbig = nbod
c
c Check if the file containing data for Big bodies exists, and open it
        filename = infile(j)
        if (oldflag) filename = dumpfile(j)
        inquire (file=filename, exist=test)
        if (.not.test) call mio_err (23,mem(81),lmem(81),mem(88),
     %    lmem(88),' ',1,filename,80)
 110    open (11, file=filename, status='old', err=110)
c
c Read data style
c ##A16,1##
c 120    read (11,'(a150)') string
c        if (string(1:1).eq.')') goto 120
c        call mio_spl (150,string,nsub,lim)
c        c3 = string(lim(1,nsub):(lim(1,nsub)+2))
c        if (c3.eq.'Car'.or.c3.eq.'car'.or.c3.eq.'CAR') then
c          informat = 1
c        else if (c3.eq.'Ast'.or.c3.eq.'ast'.or.c3.eq.'AST') then
c          informat = 2
c        else if (c3.eq.'Com'.or.c3.eq.'com'.or.c3.eq.'COM') then
c          informat = 3
c        else
c          call mio_err (23,mem(81),lmem(81),mem(91),lmem(91),' ',1,
c     %      mem(82+j),lmem(82+j))
c        end if
c ##A16,1##
c
c Read epoch of Big bodies
        if (j.eq.1) then 
 125      read (11,'(a150)') string
          if (string(1:1).eq.')') goto 125
          call mio_spl (150,string,nsub,lim)
c ##EAN16,2##
          if (lim(1,1).eq.-1) goto 125
c ##EAN16,2##
          read (string(lim(1,nsub):lim(2,nsub)),*,err=667) time
        end if
c
c Read information for each object
 130    read (11,'(a)',end=140) string
        if (string(1:1).eq.')') goto 130
c ##A38,135##
        call mio_spl (250,string,nsub,lim)
c ##A38,135##
c ##EAN16,1##
c        if (lim(1,1).eq.-1) goto 140
        if (lim(1,1).eq.-1) goto 130
c ##EAN16,1##
c
c Determine the name of the object
        nbod = nbod + 1
c ##A16,16##
c        if (nbod.gt.NMAX) call mio_err (23,mem(81),lmem(81),mem(90),
c     %    lmem(90),' ',1,mem(82),lmem(82))
c
c        if ((lim(2,1)-lim(1,1)).gt.7) then
c          write (23,'(/,3a)') mem(121)(1:lmem(121)),
c     %      mem(122)(1:lmem(122)),string( lim(1,1):lim(2,1) )
c        end if
c        id(nbod) = string( lim(1,1):min(7+lim(1,1),lim(2,1)) )
c Check if another object has the same name
c        do k = 1, nbod - 1
c          if (id(k).eq.id(nbod)) call mio_err (23,mem(81),lmem(81),
c     %      mem(103),lmem(103),id(nbod),8,' ',1)
c        end do
c ##A16,16##
c
c Default values of mass, close-encounter limit, density etc.
        m(nbod) = 0.d0
        rceh(nbod) = 1.d0
        rho(nbod) = rhocgs
        epoch(nbod) = time
        do k = 1, 4
          ngf(k,nbod) = 0.d0
        end do
c ##A35,3##
        idtag(nbod) = nbod
c ##A35,3##
c
c Read values of mass, close-encounter limit, density etc.
        do k = 3, nsub, 2
          c80 = string(lim(1,k-1):lim(2,k-1))
          read (string(lim(1,k):lim(2,k)),*,err=666) temp
          if (c80(1:1).eq.'m'.or.c80(1:1).eq.'M') then
            m(nbod) = temp * K2
          else if (c80(1:1).eq.'r'.or.c80(1:1).eq.'R') then
            rceh(nbod) = temp
          else if (c80(1:1).eq.'d'.or.c80(1:1).eq.'D') then
            rho(nbod) = temp * rhocgs
          else if (m(nbod).lt.0.or.rceh(nbod).lt.0.or.rho(nbod).lt.0)
     %      then
            call mio_err (23,mem(81),lmem(81),mem(97),lmem(97),id(nbod),
     %        8,mem(82+j),lmem(82+j))
          else if (c80(1:2).eq.'ep'.or.c80(1:2).eq.'EP'.or.c80(1:2)
     %        .eq.'Ep') then
            epoch (nbod) = temp
          else if (c80(1:2).eq.'a1'.or.c80(1:2).eq.'A1') then
            ngf (1,nbod) = temp
          else if (c80(1:2).eq.'a2'.or.c80(1:2).eq.'A2') then
            ngf (2,nbod) = temp
          else if (c80(1:2).eq.'a3'.or.c80(1:2).eq.'A3') then
            ngf (3,nbod) = temp
          else if (c80(1:1).eq.'b'.or.c80(1:1).eq.'B') then
            ngf (4,nbod) = temp
          else if (c80(1:1).eq.'i'.or.c80(1:1).eq.'I') then
c ##A35,4##
            idtag(nbod) = int(temp)
c ##A35,4##
          else
            goto 666
          end if
        end do
c
c ##A16,3##
c Read data style
 120    read (11,'(a150)') string
        if (string(1:1).eq.')') goto 120
        call mio_spl (150,string,nsub,lim)
c ##EAN16,5##
        if (lim(1,1).eq.-1) goto 120
c ##EAN16,5##
        c3 = string(lim(1,1):(lim(1,1)+2))
        if (c3.eq.'Car'.or.c3.eq.'car'.or.c3.eq.'CAR') then
          informat(nbod) = 1
        else if (c3.eq.'Ast'.or.c3.eq.'ast'.or.c3.eq.'AST') then
          informat(nbod) = 2
        else if (c3.eq.'Com'.or.c3.eq.'com'.or.c3.eq.'COM') then
          informat(nbod) = 3
        else if (nsub.eq.0) then
          informat(nbod) = 1
        else
          call mio_err (23,mem(81),lmem(81),mem(91),lmem(91),id(nbod),
     %      8,mem(82+j),lmem(82+j))
        end if
c
        oid(nbod-1)(1:8) = id(1)(1:8)
c Determine the name of the object
        if (nsub.gt.1) oid(nbod-1) = string( lim(1,2):min(7+lim(1,2),
     %    lim(2,2)) )
c ##A16,3##
c ##A26,5##
        informat2(nbod) = 1
        if (nsub.gt.2) then
          c3 = string(lim(1,3):(lim(1,3)+2))
          if (c3.eq.'Ine'.or.c3.eq.'ine'.or.c3.eq.'INE') then
            informat2(nbod) = 1
          else if (c3.eq.'Rot'.or.c3.eq.'rot'.or.c3.eq.'ROT') then
            informat2(nbod) = 2
          else
            call mio_err (23,mem(81),lmem(81),mem(143),lmem(143),
     %        id(nbod),8,mem(82+j),lmem(82+j))
          end if
        end if
c ##A26,5##
c
c If required, read Cartesian coordinates, velocities and spins of the bodies
        jtmp = 100
 135    read (11,'(a150)',end=666) string
        if (string(1:1).eq.')') goto 135
        backspace 11
c ##A16,17##
        i0 = 1
c        flagid = 0
        do k = 1, nbod0
          if (oid(nbod-1)(1:8).eq.id(k)(1:8)) then
c            flagid = 1
            i0 = k
          end if
        end do
c Check if some object there isn't
c        if (flagid.eq.0) call mio_err (23,mem(81),lmem(81),mem(116),
c     %    lmem(116),oid(nbod-1),8,mem(82+j),lmem(82+j))
c
        temp = m(nbod)  +  m(i0)
c ##A16,17##
c ##A16,5##
        if (informat(nbod).eq.1) then
c ##A16,5##
          read (11,*,err=666) x(1,nbod),x(2,nbod),x(3,nbod),
     %      v(1,nbod),v(2,nbod),v(3,nbod),s(1,nbod),s(2,nbod),s(3,nbod)
        else
          read (11,*,err=666) a,e,i,p,n,l,s(1,nbod),s(2,nbod),
     %      s(3,nbod)
          i = i * DR
          p = (p + n) * DR
          n = n * DR
c
c Alternatively, read Cometary or asteroidal elements
c ##A16,6##
          if (informat(nbod).eq.3) then
c ##A16,6##
            q = a
            a = q / (1.d0 - e)
            l = mod (sqrt(temp/(abs(a*a*a))) * (epoch(nbod) - l), TWOPI)
          else
            q = a * (1.d0 - e)
            l = l * DR
          end if
c ##A15,10##
c ##AAR1,6##
c          if ((algor.eq.11.or.algor.eq.5).and.nbod.ne.2)
c     %      temp = temp + m(2)
c ##AAR1,6##
c ##A16,20##
          if (i0.eq.1) then
c ##A16,20##
            if (centre.eq.4) then
              temp = temp + m(2)
              if (nbod.eq.2) temp = m(1) * m(1) / (m(1) + m(2))
            end if
            if (centre.eq.5.and.nbod.eq.2) then
              q2 = q
              e2 = e
              i2 = i
              p2 = p
              n2 = n
              l2 = l
            end if
            if (centre.eq.6) then
              temp = temp + m(2)
              if (nbod.eq.2) temp = m(1) * m(1) / (m(1) + m(2))
              if (nbod.eq.3) then
                q2 = q
                e2 = e
                i2 = i
                p2 = p
                n2 = n
                l2 = l
              end if
            end if
            if (centre.eq.7.and.nbod.ne.2) temp = temp + m(2)
c ##AAR1,42##
            if (centre.eq.0) then
              if (algor.eq.11.or.algor.eq.5) then
                temp = temp + m(2)
c a2 = m1 / (m1 + m2) * a
                if (nbod.eq.2) temp = m(1)**3 / (m(1) + m(2))**2
                if (nbod.eq.3) then
                  q2 = q
                  e2 = e
                  i2 = i
                  p2 = p
                  n2 = n
                  l2 = l
                end if
              end if
              if (algor.eq.12.and.nbod.eq.2) then
                q2 = q
                e2 = e
                i2 = i
                p2 = p
                n2 = n
                l2 = l
              end if
            end if
c ##AAR1,42##
c ##A16,21##
          end if
c ##A16,21##
c ##A15,10##
c ##A42,2##
          if (centre.ne.8) then
            call mco_el2x (temp,q,e,i,p,n,l,x(1,nbod),x(2,nbod),
     %        x(3,nbod),v(1,nbod),v(2,nbod),v(3,nbod))
          else if (centre.eq.8) then
            obla(1) = temp
            obla(2) = jcen(1)
            obla(3) = jcen(2)
            obla(4) = jcen(3)
            icoor(1) = a
            icoor(2) = e
            icoor(3) = i / DR
            icoor(4) = (p - n) / DR
            icoor(5) = n / DR
            icoor(6) = l / DR
            if (dabs(obla(2)).ge.EPS.or.dabs(obla(3)).ge.EPS
     %        .or.dabs(obla(4)).ge.EPS) then
              call geo_car (obla,icoor,ocoor)
            else
              icoor(4) = icoor(4) + icoor(5)            
              icoor(4) = mod (icoor(4), 360.d0)
              do k = 3, 6
                icoor(k) = icoor(k) * DR
              end do
              icoor(1) = icoor(1) * (1.0 - icoor(2))
              call mco_el2x (obla(1),icoor(1),icoor(2),icoor(3),
     %          icoor(4),icoor(5),icoor(6),ocoor(1),ocoor(2),ocoor(3),
     %          ocoor(4),ocoor(5),ocoor(6))
            end if
            x(1,nbod) = ocoor(1)
            x(2,nbod) = ocoor(2)
            x(3,nbod) = ocoor(3)
            v(1,nbod) = ocoor(4)
            v(2,nbod) = ocoor(5)
            v(3,nbod) = ocoor(6)
          end if
c ##A42,2##
        end if
c
c ##ANO29,5##
        if (opti(43).eq.1.and.(.not.oldflag)) then
c
          del = 1.d0 / opti(21)
c central point (origin)
          xl(1) = 0.0
          yl(1) = 0.0
          zl(1) = 0.0
c
          vpot = 0.d0
          if (algor.eq.11.or.algor.eq.5.and.nbod.ne.2) temp=temp + m(2)
          if (algor.ge.13) then
            nn = optr(6)*optr(6)
c
c------------------------------------------------------------------------------
c
c polyhedron method
          if (algor.eq.13.or.algor.eq.16.or.algor.eq.19) then
            if (opti(22).eq.0.and.opti(21).eq.1) then
              call polyhedron2 (nov,nop,xv,yv,zv,noe,kkk,
     %          dens(opti(21)),x(1,nbod),x(2,nbod),x(3,nbod),vpot,K2)
            else
              do i0 = 1, nop
                l0 = 1
c compute new vertices
                do ilay = 1, opti(21)
                  inc = del * ilay
                  do j1 = 1, noe(i0)
                    l0 = l0 + 1
                    xl(l0) = xv(kkk(i0,j1)) * inc
                    yl(l0) = yv(kkk(i0,j1)) * inc
                    zl(l0) = zv(kkk(i0,j1)) * inc
                  enddo
                enddo
                novl = l0
c compute new faces
                l0 = 1
c compute top face of pyramid
                do j1 = 1, noe(i0)
                  kl(l0,j1) = j1 + 1
                enddo
                noel(l0) = noe(i0)
c compute lateral faces of pyramid
                do j1 = 1, noe(i0)-1
                  l0 = l0 + 1
                  kl(l0,1) = 1
                  kl(l0,2) = j1 + 2
                  kl(l0,3) = j1 + 1
                  noel(l0) = 3
                enddo
c compute last lateral face of pyramid
                l0 = l0 + 1
                kl(l0,1) = 1
                kl(l0,2) = 2
                kl(l0,3) = noe(i0) + 1
                noel(l0) = 3
c compute pyramid's potential
                nopl = l0
                call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %            dens(1),x(1,nbod),x(2,nbod),x(3,nbod),vpot,K2)
c compute faces of pyramidal frustums
                do ilay = 2, opti(21)
                  l0 = 1
c compute bottom face (reverse)
                  do j1 = 1, noe(i0)
                    kl(l0,j1) = (ilay-2)*noe(i0) + (noe(i0)-j1) + 2
                  enddo
                  noel(l0) = noe(i0)
c compute lateral faces
                  do j1 = 1, noe(i0)-1
                    l0 = l0 + 1
                    kl(l0,1) = (ilay-2)*noe(i0) + j1 + 1
                    kl(l0,2) = kl(l0,1) + 1
                    kl(l0,3) = ((ilay-1)*noe(i0) + j1) + 2
                    kl(l0,4) = kl(l0,3) - 1
                    noel(l0) = 4
                  enddo
c compute last lateral face
                  l0 = l0 + 1
                  kl(l0,1) = (ilay-1)*noe(i0) + 1
                  kl(l0,2) = kl(l0,1) - (noe(i0)-1)
                  kl(l0,3) = ilay*noe(i0) - (noe(i0)-1) + 1
                  kl(l0,4) = ilay*noe(i0) + 1
                  noel(l0) = 4
c compute top face (no reverse)
                  l0 = l0 + 1
                  do j1 = 1, noe(i0)
                    kl(l0,j1) = (ilay-1)*noe(i0) + j1 + 1
                  enddo
                  noel(l0) = noe(i0)
c compute pyramidal frustum's potential
                  nopl = l0
                  call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %              dens(ilay),x(1,nbod),x(2,nbod),x(3,nbod),vpot,K2)
                enddo
              enddo
            end if
            Upot = -vpot
c
c------------------------------------------------------------------------------
c
c mascon method
          else if (algor.eq.14.or.algor.eq.17.or.algor.eq.20) then
            do j1 = 1, noc
              dx = x(1,nbod) - xc(j1)
              dy = x(2,nbod) - yc(j1)
              dz = x(3,nbod) - zc(j1)
              s2 = dx*dx + dy*dy + dz*dz
              s_1 = 1.d0 / sqrt(s2)
              temp = s_1 * mc(j1)
              vpot = vpot - temp
            end do
            Upot = vpot
c
c------------------------------------------------------------------------------
c
c hybrid method
          else if (algor.eq.15.or.algor.eq.18.or.algor.eq.21
     %      .or.algor.eq.22) then
            temp = x(1,nbod)*x(1,nbod) + x(2,nbod)*x(2,nbod) +
     %        x(3,nbod)*x(3,nbod)
c newtonian method
            if (temp.ge.optr(7)) then
              if (nbod.eq.2) goto 512
              a = dsqrt(x(1,nbod)*x(1,nbod)+x(2,nbod)*x(2,nbod)+
     %          x(3,nbod)*x(3,nbod))
              nn = temp / (a*a*a)
              mi = m(2)/(m(1)+m(2))
              if (informat2(nbod).eq.2) then
                r1 = (x(1,nbod)+mi)*(x(1,nbod)+mi)
     %            +x(2,nbod)*x(2,nbod)+x(3,nbod)*x(3,nbod)
                r2 = (x(1,nbod)-(1.d0-mi))*(x(1,nbod)-
     %            (1.d0-mi))+x(2,nbod)*x(2,nbod)+
     %            x(3,nbod)*x(3,nbod)
                Upot = (1.d0-mi)/r1 + mi/r2
              else if (informat2(nbod).eq.1) then
                r1 = x(1,nbod)*x(1,nbod)+x(2,nbod)*x(2,nbod)
     %            +x(3,nbod)*x(3,nbod)
                r2 = (x(1,2)-x(1,nbod))*(x(1,2)-x(1,nbod))
     %            +(x(2,2)-x(2,nbod))*(x(2,2)-x(2,nbod))
     %            +(x(3,2)-x(3,nbod))*(x(3,2)-x(3,nbod))
                Upot = (1.d0-mi)/r1+mi/r2
              end if
              Upot = -Upot
            else
c mascon method
              if (temp.ge.optr(8)) then
                do j1 = 1, noc
                  dx = x(1,nbod) - xc(j1)
                  dy = x(2,nbod) - yc(j1)
                  dz = x(3,nbod) - zc(j1)
                  s2 = dx*dx + dy*dy + dz*dz
                  s_1 = 1.d0 / sqrt(s2)
                  temp = s_1 * mc(j1)
                  vpot = vpot - temp
                end do
                Upot = vpot
c
              else
c polyhedron method
                if (opti(22).eq.0.and.opti(21).eq.1) then
                  call polyhedron2 (nov,nop,xv,yv,zv,noe,kkk,
     %              dens(opti(21)),x(1,nbod),x(2,nbod),x(3,nbod),vpot,
     %              K2)
                else
                  do i0 = 1, nop
                    l0 = 1
c compute new vertices
                    do ilay = 1, opti(21)
                      inc = del * ilay
                      do j1 = 1, noe(i0)
                        l0 = l0 + 1
                        xl(l0) = xv(kkk(i0,j1)) * inc
                        yl(l0) = yv(kkk(i0,j1)) * inc
                        zl(l0) = zv(kkk(i0,j1)) * inc
                      enddo
                    enddo
                    novl = l0
c compute new faces
                    l0 = 1
c compute top face of pyramid
                    do j1 = 1, noe(i0)
                      kl(l0,j1) = j1 + 1
                    enddo
                    noel(l0) = noe(i0)
c compute lateral faces of pyramid
                    do j1 = 1, noe(i0)-1
                      l0 = l0 + 1
                      kl(l0,1) = 1
                      kl(l0,2) = j1 + 2
                      kl(l0,3) = j1 + 1
                      noel(l0) = 3
                    enddo
c compute last lateral face of pyramid
                    l0 = l0 + 1
                    kl(l0,1) = 1
                    kl(l0,2) = 2
                    kl(l0,3) = noe(i0) + 1
                    noel(l0) = 3
c compute pyramid's potential
                    nopl = l0
                    call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %                dens(1),x(1,nbod),x(2,nbod),x(3,nbod),vpot,K2)
c compute faces of pyramidal frustums
                    do ilay = 2, opti(21)
                      l0 = 1
c compute bottom face (reverse)
                      do j1 = 1, noe(i0)
                        kl(l0,j1) = (ilay-2)*noe(i0) + (noe(i0)-j1) + 2
                      enddo
                      noel(l0) = noe(i0)
c compute lateral faces
                      do j1 = 1, noe(i0)-1
                        l0 = l0 + 1
                        kl(l0,1) = (ilay-2)*noe(i0) + j1 + 1
                        kl(l0,2) = kl(l0,1) + 1
                        kl(l0,3) = ((ilay-1)*noe(i0) + j1) + 2
                        kl(l0,4) = kl(l0,3) - 1
                        noel(l0) = 4
                      enddo
c compute last lateral face
                      l0 = l0 + 1
                      kl(l0,1) = (ilay-1)*noe(i0) + 1
                      kl(l0,2) = kl(l0,1) - (noe(i0)-1)
                      kl(l0,3) = ilay*noe(i0) - (noe(i0)-1) + 1

                      kl(l0,4) = ilay*noe(i0) + 1
                      noel(l0) = 4
c compute top face (no reverse)
                      l0 = l0 + 1
                      do j1 = 1, noe(i0)
                        kl(l0,j1) = (ilay-1)*noe(i0) + j1 + 1
                      enddo
                      noel(l0) = noe(i0)
c compute pyramidal frustum's potential
                      nopl = l0
                      call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %                  dens(ilay),x(1,nbod),x(2,nbod),x(3,nbod),vpot,
     %                  K2)
                    enddo
                  enddo
                end if
                Upot = -vpot
              end if
            end if
          end if
c
c------------------------------------------------------------------------------
c
          else
            if (nbod.eq.2) goto 512
            a = dsqrt(x(1,nbod)*x(1,nbod)+x(2,nbod)*x(2,nbod)+
     %        x(3,nbod)*x(3,nbod))
            nn = temp / (a*a*a)
            mi = m(2)/(m(1)+m(2))
            if (informat2(nbod).eq.2) then
              r1 = (x(1,nbod)+mi)*(x(1,nbod)+mi)
     %          +x(2,nbod)*x(2,nbod)+x(3,nbod)*x(3,nbod)
              r2 = (x(1,nbod)-(1.d0-mi))*(x(1,nbod)-
     %          (1.d0-mi))+x(2,nbod)*x(2,nbod)+
     %          x(3,nbod)*x(3,nbod)
              Upot = (1.d0-mi)/r1 + mi/r2
            else if (informat2(nbod).eq.1) then
              r1 = x(1,nbod)*x(1,nbod)+x(2,nbod)*x(2,nbod)
     %          +x(3,nbod)*x(3,nbod)
              r2 = (x(1,2)-x(1,nbod))*(x(1,2)-x(1,nbod))
     %          +(x(2,2)-x(2,nbod))*(x(2,2)-x(2,nbod))
     %          +(x(3,2)-x(3,nbod))*(x(3,2)-x(3,nbod))
              Upot = (1.d0-mi)/r1+mi/r2
            end if
            Upot = -Upot
          end if
          if (informat2(nbod).eq.2) then
c            call mco_x2a (temp,x(1,nbod),x(2,nbod),x(3,nbod),v(1,nbod),
c     %        v(2,nbod),v(3,nbod),a,r,v2)
c            if (a.le.0) a = r
c            a = dsqrt(x(1,nbod)*x(1,nbod)+x(2,nbod)*x(2,nbod)+
c     %        x(3,nbod)*x(3,nbod))
c            nn = temp / (a*a*a)
            if (opti(44).eq.0) then
              dC = -nn * (x(1,nbod) * x(1,nbod) + x(2,nbod) * x(2,nbod))
     %          + 2.d0*Upot -v(2,nbod)*v(2,nbod) -v(3,nbod)*v(3,nbod)
     %          -optr(27)
            else if (opti(44).eq.1) then
              dC = -nn * (x(1,nbod) * x(1,nbod) + x(2,nbod) * x(2,nbod))
     %          + 2.d0*Upot -v(1,nbod)*v(1,nbod) -v(3,nbod)*v(3,nbod)
     %          -optr(27)
            else if (opti(44).eq.2) then
              dC = -nn * (x(1,nbod) * x(1,nbod) + x(2,nbod) * x(2,nbod))
     %          + 2.d0*Upot -v(1,nbod)*v(1,nbod) -v(2,nbod)*v(2,nbod)
     %          -optr(27)
            end if
            if (dC.lt.0) call mio_err (23,mem(81),lmem(81),
     %        mem(147),lmem(147),id(nbod),8,' ',1)
            dC = dsqrt(dC)
            if (opti(45).eq.1) dC = -dC
          else if (informat2(nbod).eq.1) then
