     %        mem(150),lmem(150),id(nbod),8,' ',1)
c            call mco_x2a (temp,x(1,nbod),x(2,nbod),x(3,nbod),
c     %        v(1,nbod),v(2,nbod),v(3,nbod),a,r,v2)
