     %          -x(2,nbod)*v(1,nbod))-v(1,nbod)*v(1,nbod)
     %          -v(2,nbod)*v(2,nbod) -optr(27)
            end if
            if (opti(44).ne.2) then
              delta = cb*cb -4.0*ca*cc
              if (delta.lt.0) call mio_err (23,mem(81),lmem(81),
     %          mem(147),lmem(147),id(nbod),8,' ',1)
              cd(1) = (-cb-dsqrt(delta))/(2.0*ca)
              cd(2) = (-cb+dsqrt(delta))/(2.0*ca)
              if (opti(45).eq.0) then
