c
c Set non-gravitational-forces flag, NGFLAG
      ngflag = 0
      do j = 1, nbod
        if (ngf(1,j).ne.0.or.ngf(2,j).ne.0.or.ngf(3,j).ne.0) then
          if (ngflag.eq.0) ngflag = 1
          if (ngflag.eq.2) ngflag = 3
        else if (ngf(4,j).ne.0) then
          if (ngflag.eq.0) ngflag = 2
          if (ngflag.eq.1) ngflag = 3
c ##A38,104##
          m(j) = m(j) / MSUN
c ##A38,104##
        end if
      end do
c
c If using close-binary algorithm, convert to heliocentric coordinates
c ##A15,4##
c ##AAR1,5##
c      if (algor.eq.11.or.algor.eq.5) then
c ##AAR1,5##
c        call mco_ub2h (time,jcen,nbod,nbig,h0,m,x,v,x0,v0,ngf,ngflag,
c     %    opt)
c        call mco_iden(time,jcen,nbod,nbig,h0,m,x0,v0,x,v,ngf,ngflag,opt)
c      end if
c ##AAR1,48##
      if (.not.oldflag) then
c ##AAR1,43##
      if ((centre.ne.1.and.centre.ne.3).and.(algor.ne.11
     %  .and.algor.ne.5)) then
c ##AAR1,43##
        x(1,1) = 0.d0
        x(2,1) = 0.d0
        x(3,1) = 0.d0
        v(1,1) = 0.d0
        v(2,1) = 0.d0
        v(3,1) = 0.d0
      else
c ##AAR1,44##
        if (informat(1).eq.1.and.(centre.eq.1
     %    .or.centre.eq.3)) then
c ##AAR1,44##
          x(1,1) = -x(1,1)
          x(2,1) = -x(2,1)
          x(3,1) = -x(3,1)
          v(1,1) = -v(1,1)
          v(2,1) = -v(2,1)
          v(3,1) = -v(3,1)
        end if
      end if
c
      msum = 0.d0
c
c ##AAR1,45##
c ##A38,129##
      if (centre.eq.0.and.ngflag.lt.2.and.algor.lt.13) then
c ##A38,129##
        if (algor.eq.12.or.algor.eq.5) then
          do j = 1, nbod
            msum = msum + m(j)
          end do
          if (algor.eq.12.and.informat(2).ne.1) call mco_el2x (msum,
     %      q2,e2,i2,p2,n2,l2,x(1,2),x(2,2),x(3,2),v(1,2),v(2,2),v(3,2))
          if (algor.eq.5.and.informat(3).ne.1) call mco_el2x (msum,
     %      q2,e2,i2,p2,n2,l2,x(1,3),x(2,3),x(3,3),v(1,3),v(2,3),v(3,3))
        end if
c
        if (informat(1).ne.1) then
          if (algor.eq.11.or.algor.eq.5) then
            call mco_h2b2 (jcen,0,2,1,h0,m,x,v,x0,v0)
            x(1,1) = x(1,1) - x0(1,1)
            x(2,1) = x(2,1) - x0(2,1)
            x(3,1) = x(3,1) - x0(3,1)
            v(1,1) = v(1,1) - v0(1,1)
            v(2,1) = v(2,1) - v0(2,1)
            v(3,1) = v(3,1) - v0(3,1)
c
            x(1,2) = x(1,2) - x0(1,1)
            x(2,2) = x(2,2) - x0(2,1)
            x(3,2) = x(3,2) - x0(3,1)
            v(1,2) = v(1,2) - v0(1,1)
            v(2,2) = v(2,2) - v0(2,1)
            v(3,2) = v(3,2) - v0(3,1)
c
            if (algor.eq.5) then
              call mco_h2b2 (jcen,3,nbod,1,h0,m,x,v,x1,v1)
              x0(1,3) = (x(1,3) + x1(1,1)) - x(1,1)
              x0(2,3) = (x(2,3) + x1(2,1)) - x(2,1)
              x0(3,3) = (x(3,3) + x1(3,1)) - x(3,1)
              v0(1,3) = (v(1,3) + v1(1,1)) - v(1,1)
              v0(2,3) = (v(2,3) + v1(2,1)) - v(2,1)
              v0(3,3) = (v(3,3) + v1(3,1)) - v(3,1)
              call mco_b2h2 (jcen,3,nbod,1,h0,m,x,v,x0,v0)
            else if (algor.eq.11) then
              call mco_b2h2 (jcen,0,nbod,1,h0,m,x,v,x0,v0)
            end if
          end if
          if (algor.eq.12) then
            call mco_h2b2 (jcen,2,nbod,1,h0,m,x,v,x1,v1)
            x0(1,2) = x(1,2) - x1(1,1)
            x0(2,2) = x(2,2) - x1(2,1)
            x0(3,2) = x(3,2) - x1(3,1)
            v0(1,2) = v(1,2) - v1(1,1)
            v0(2,2) = v(2,2) - v1(2,1)
            v0(3,2) = v(3,2) - v1(3,1)
            call mco_b2h2 (jcen,2,nbod,1,h0,m,x,v,x0,v0)
          end if
c ##A38,43##
          call mco_iden(time,jcen,nbod,nbig,h0,m,x0,v0,x,v,ngf,ngflag,
     %      opt,optr,opti,K2,AU,MSUN)
c ##A38,43##
        end if
      end if
c ##AAR1,45##
c
c ##A16,7##
c      if (informat.ne.1) then
      if (centre.eq.5.and.informat(2).ne.1) then
c ##A16,7##
        do j = 3, nbod
          msum = msum + m(j)
        end do
        temp = (m(1) + msum) * (m(1) + msum) / (m(1) + msum + m(2)) 
        call mco_el2x (temp,q2,e2,i2,p2,n2,l2,x(1,2),x(2,2),x(3,2),
     %    v(1,2),v(2,2),v(3,2))
      end if
c ##A16,8##
      if (centre.eq.6.and.informat(3).ne.1) then
c ##A16,8##
        do j = 4, nbod
          msum = msum + m(j)
        end do
        temp = (m(1) + m(2) + msum) * (m(1) + m(2) + msum)
     %    / (m(1) + m(2) + m(3) + msum) 
        call mco_el2x (temp,q2,e2,i2,p2,n2,l2,x(1,3),x(2,3),x(3,3),
     %    v(1,3),v(2,3),v(3,3))
      end if
c ##A16,9##
c      end if
c
c ##A38,44##
      call mco_iden(time,jcen,nbod,nbig,h0,m,x,v,x0,v0,ngf,ngflag,
     %  opt,optr,opti,K2,AU,MSUN)
c ##A38,44##
      call mco_orbit2x (1,nbod,nbig,x,v,x0,v0,id,oid,lmem,mem)
c
      if (centre.eq.0) call mco_iden(time,jcen,nbod,nbig,h0,m,x0,v0,x,v,
     %  ngf,ngflag,opt,optr,opti,K2,AU,MSUN)
c
c      call mco_iden(time,jcen,nbod,nbig,h0,m,x,v,x0,v0,ngf,ngflag,
c     %  opt)
c ##A16,9##
c ##A42,4##
      if (centre.eq.1.or.centre.eq.8) call mco_b2h (time,jcen,nbod,nbig,
     %  h0,m,x0,v0,x,v,ngf,ngflag,opt)
c ##A42,4##
      if (centre.eq.2) call mco_j2h (time,jcen,nbod,nbig,h0,m,x0,v0,
     %  x,v,ngf,ngflag,opt)
c ##A38,66##
      if (centre.eq.4) call mco_cb2h (time,jcen,nbod,nbig,h0,m,x0,v0,
     %  x,v,ngf,ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,66##
      if (centre.eq.3) then
        itmp = 2
        if (algor.eq.11) itmp = 3
        if (algor.eq.5) itmp = 4
        synflag = 0
        call mco_syn2h (itmp,synflag,time,nbod,m,x0,v0,x,v,nn)
c ##A38,45##
        call mco_iden(time,jcen,nbod,nbig,h0,m,x,v,x0,v0,ngf,ngflag,
     %    opt,optr,opti,K2,AU,MSUN)
c ##A38,45##
        call mco_b2h (time,jcen,nbod,nbig,h0,m,x0,v0,x,v,ngf,ngflag,
     %    opt)
      end if
c ##A38,71##
      if (centre.eq.5) call mco_wb2h (time,jcen,nbod,nbig,h0,m,x0,v0,
     %  x,v,ngf,ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,71##
c ##A38,74##
      if (centre.eq.6) call mco_sabp2h (time,jcen,nbod,nbig,h0,m,x0,v0,
     %  x,v,ngf,ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,74##
c ##A18,1##
      if (centre.eq.7) call mco_ub2h (algor,time,jcen,nbod,nbig,h0,m,
     %  x0,v0,x,v,ngf,ngflag,opt)
c ##A18,1##
c ##A19,42##
c ##A26,10##
c      if (algor.ge.13) call mco_h2ast (time,jcen,nbod,nbig,optr(6),m,x0,
c     %  v0,x,v,ngf,ngflag,opt)
c ##A26,10##
c ##A19,42##
c
      x(1,1) = 0.d0
      x(2,1) = 0.d0
      x(3,1) = 0.d0
      v(1,1) = 0.d0
      v(2,1) = 0.d0
      v(3,1) = 0.d0
c ##A15,4##
      end if
c ##AAR1,48##
c
c------------------------------------------------------------------------------
c
c  IF  CONTINUING  AN  OLD  INTEGRATION
c
      if (oldflag) then
        if (opt(3).eq.1) then
          call mio_jd2y (time,year,month,t1)
          write (23,'(/,a,i10,i2,f8.5,/)') mem(62)(1:lmem(62)),year,
     %      month,t1
c ##A12,15##
          write (*,'(/,a,i10,i2,f8.5,/)') mem(62)(1:lmem(62)),year,
     %      month,t1
c ##A12,15##
        else if (opt(3).eq.3) then
          t1 = (time - tstart) / 365.25d0
          write (23,'(/,a,f18.7,a,/)') mem(62)(1:lmem(62)),t1,
     %      mem(2)(1:lmem(2))
c ##A12,16##
          write (*,'(/,a,f18.7,a,/)') mem(62)(1:lmem(62)),t1,
     %      mem(2)(1:lmem(2))
c ##A12,16##
        else
          if (opt(3).eq.0) t1 = time
          if (opt(3).eq.2) t1 = time - tstart
          write (23,'(/,a,f18.5,a,/)') mem(62)(1:lmem(62)),t1,
     %      mem(1)(1:lmem(1))
c ##A12,17##
          write (*,'(/,a,f18.5,a,/)') mem(62)(1:lmem(62)),t1,
     %      mem(1)(1:lmem(1))
c ##A12,17##
        end if
c
c Read in energy and angular momentum variables, and convert to internal units
 330    open (35, file=dumpfile(4), status='old', err=330)
          read (35,*) opflag
          read (35,*) en(1),am(1),en(3),am(3)
          en(1) = en(1) * K2
          en(3) = en(3) * K2
          am(1) = am(1) * K2
          am(3) = am(3) * K2
          read (35,*) s(1,1),s(2,1),s(3,1)
          s(1,1) = s(1,1) * K2
          s(2,1) = s(2,1) * K2
          s(3,1) = s(3,1) * K2
c ##A11,21##
          read (35,*) opti(16),opti(17),opti(18)
c ##A11,21##
c ##A20,6##
          read (35,*) treal,tuser,tsys
c ##A20,6##
c ##E19,24##
          read (35,*) optr(49),optr(50)
c ##E19,24##
c ##A39,59##
          read (35,*) opti(81),opti(82)
c ##A39,59##
c ##A19,231##
c          read (35,*) rho(1),optr(69),optr(70),optr(71),optr(72),
c     %      optr(73),optr(74),optr(75),optr(76)
          read (35,*) rho(1),optr(72),optr(73),optr(74),optr(75),
     %      optr(76)
          rho(1) = rho(1) * rhocgs
c ##A19,231##
        close (35)
        if (opflag.eq.0) opflag = 1
c ##E8,1##
c
c Check that element and close-encounter files don't exist, and create them
        do j = 1, 2
          inquire (file=outfile(j), exist=test)
          if (.not.test) then
            write (23,'(3a,/,a,/)') mem(121)(1:lmem(121)),mem(138)
     %        (1:lmem(138)),outfile(j),mem(139)(1:lmem(139))
c ##A12,14##
            write (*,'(3a,/,a,/)') mem(121)(1:lmem(121)),mem(138)
     %        (1:lmem(138)),outfile(j),mem(139)(1:lmem(139))
c ##A12,14##
 433        open  (20+j, file=outfile(j), status='new', err=433)
            close (20+j)
          end if
        end do
c ##E8,1##
c
c ##A39,106##
        if (opti(80).eq.1) then
          j = 0
          filename = dumpfile(5)
          inquire (file=filename, exist=test)
          if (.not.test) call mio_err (23,mem(81),lmem(81),mem(88),
     %      lmem(88),' ',1,filename,80)
 117      open (35, file=filename, status='old', err=117)
c
 127      read (35,'(a150)') string
          if (string(1:1).eq.')') goto 127
          call mio_spl (150,string,nsub,lim)
          if (lim(1,1).eq.-1) goto 127
          read (string(lim(1,nsub):lim(2,nsub)),*,err=667) optr(64)
c
 137      read (35,'(a)',end=147) string
          if (string(1:1).eq.')') goto 137
          call mio_spl (150,string,nsub,lim)
          if (lim(1,1).eq.-1) goto 137
          j = j + 1
          backspace 35
          read (35,*,err=666) chk(1,opti(82)+j),chk(2,opti(82)+j),
     %      chk(3,opti(82)+j)
          goto 137
 147      close(35)
        end if
c ##A39,106##
c
c------------------------------------------------------------------------------
c
c  IF  STARTING  A  NEW  INTEGRATION
c
      else
        opflag = -2
c
c Write integration parameters to information file
        write (23,'(/,a)') mem(11)(1:lmem(11))
        write (23,'(a)') mem(12)(1:lmem(12))
        j = algor + 13
        if (algor.ge.13) then
          j = algor + 287
          write (23,'(/,2a)') mem(13)(1:lmem(13)),mem(j)(1:lmem(j))
        else
          write (23,'(/,2a)') mem(13)(1:lmem(13)),mem(j)(1:lmem(j))
        end if
        if (tstart.ge.1.d11.or.tstart.le.-1.d10) then
          write (23,'(/,a,1p,e19.13,a)') mem(26)(1:lmem(26)),tstart,
     %    mem(1)(1:lmem(1))
        else
          write (23,'(/,a,f19.7,a)') mem(26)(1:lmem(26)),tstart,
     %    mem(1)(1:lmem(1))
        end if
        if (tstop.ge.1.d11.or.tstop.le.-1.d10) then
          write (23,'(a,1p,e19.13)') mem(27)(1:lmem(27)),tstop
        else
          write (23,'(a,f19.7)') mem(27)(1:lmem(27)),tstop
        end if
        write (23,'(a,f15.3)') mem(28)(1:lmem(28)),dtout
c ##E9,53##
        write (23,'(a,f15.3)') mem(208)(1:lmem(208)),dtdump
c ##E9,53##
        itmp = 5
        if (opti(51).eq.1) itmp = 6
        write (23,'(2a)') mem(400)(1:lmem(400)),mem(itmp)(1:lmem(itmp))
        itmp = 5
        if (opti(72).eq.1) itmp = 6
        write (23,'(2a)') mem(418)(1:lmem(418)),mem(itmp)(1:lmem(itmp))
        if (opt(4).eq.1) write (23,'(2a)') mem(40)(1:lmem(40)),
     %    mem(7)(1:lmem(7))
        if (opt(4).eq.2) write (23,'(2a)') mem(40)(1:lmem(40)),
     %    mem(8)(1:lmem(8))
        if (opt(4).eq.3) write (23,'(2a)') mem(40)(1:lmem(40)),
     %    mem(9)(1:lmem(9))
c
        write (23,'(/,a,f10.3,a)') mem(30)(1:lmem(30)),h0,
     %    mem(1)(1:lmem(1))
        write (23,'(a,1p1e10.4)') mem(31)(1:lmem(31)),tol
        write (23,'(a,1p1e10.4,a)') mem(32)(1:lmem(32)),m(1)/K2,
     %    mem(3)(1:lmem(3))
        write (23,'(a,a8)') mem(356)(1:lmem(356)),id(1)
        write (23,'(a,1p1e11.4)') mem(33)(1:lmem(33)),jcen(1)/rcen**2
        write (23,'(a,1p1e11.4)') mem(34)(1:lmem(34)),jcen(2)/rcen**4
        write (23,'(a,1p1e11.4)') mem(35)(1:lmem(35)),jcen(3)/rcen**6
c ##A10,1##
        write (23,'(a,1p1e10.4,a)') mem(43)(1:lmem(43)),rmin,
     %    mem (4)(1:lmem(4))
c ##A10,1##
        write (23,'(a,1p1e10.4,a)') mem(36)(1:lmem(36)),rmax,
     %    mem (4)(1:lmem(4))
        write (23,'(a,i7,a3,i7)') mem(293)(1:lmem(293)),opti(2)-1,
     %    ' - ',opti(3)-1
        itmp = 5
        if (opt(73).eq.1) itmp = 6
        write (23,'(2a)') mem(420)(1:lmem(420)),mem(itmp)(1:lmem(itmp))
        write (23,'(a,i7)') mem(422)(1:lmem(422)),opti(74)-1
        write (23,'(a,1p1e10.4)') mem(424)(1:lmem(424)),optr(48)
        if (opt(75).eq.1) itmp = 6
        write (23,'(2a)') mem(426)(1:lmem(426)),mem(itmp)(1:lmem(itmp))
        write (23,'(a,1p1e10.4,a)') mem(37)(1:lmem(37)),rcen,
     %    mem (4)(1:lmem(4))
        if (opti(19).eq.0)
     %      write (23,'(a,a5)') mem(357)(1:lmem(357)),'Cen'
        if (opti(19).eq.1)
     %      write (23,'(a,a5)') mem(357)(1:lmem(357)),'Bar'
        if (opti(19).eq.2)
     %      write (23,'(a,a5)') mem(357)(1:lmem(357)),'Jac'
        if (opti(19).eq.3)
     %      write (23,'(a,a5)') mem(357)(1:lmem(357)),'Syn'
        if (opti(19).eq.4)
     %      write (23,'(a,a5)') mem(357)(1:lmem(357)),'Clo'
        if (opti(19).eq.5)
     %      write (23,'(a,a5)') mem(357)(1:lmem(357)),'Wid'
        if (opti(19).eq.6)
     %      write (23,'(a,a5)') mem(357)(1:lmem(357)),'Sabp'
        if (opti(19).eq.7)
     %      write (23,'(a,a5)') mem(357)(1:lmem(357)),'Uclo'
        write (23,'(a,1p1e10.4)') mem(358)(1:lmem(358)),optr(5)
        write (23,'(a,1p1e10.4)') mem(359)(1:lmem(359)),cefac
c
        itmp = 5
        if (opt(2).eq.1.or.opt(2).eq.2) itmp = 6
        write (23,'(/,2a)') mem(41)(1:lmem(41)),mem(itmp)(1:lmem(itmp))
        itmp = 5
        if (opt(2).eq.2) itmp = 6
        write (23,'(2a)') mem(42)(1:lmem(42)),mem(itmp)(1:lmem(itmp))
        itmp = 5
        if (opti(76).eq.1) itmp = 6
        write (23,'(2a)') mem(429)(1:lmem(429)),mem(itmp)(1:lmem(itmp))
        itmp = 5
        if (opt(7).eq.1) itmp = 6
        write (23,'(2a)') mem(45)(1:lmem(45)),mem(itmp)(1:lmem(itmp))
        itmp = 5
        if (opt(8).eq.1) itmp = 6
        write (23,'(2a)') mem(46)(1:lmem(46)),mem(itmp)(1:lmem(itmp))
c ##A38,5##
c        itmp = 5
c        if (opt(9).eq.1) itmp = 6
c        write (23,'(2a)') mem(430)(1:lmem(430)),mem(itmp)(1:lmem(itmp))
        write (23,'(a,1p1e10.4)') mem(430)(1:lmem(430)),optr(51)
        write (23,'(a,1p1e10.4)') mem(432)(1:lmem(432)),optr(52)
        write (23,'(a,1p1e10.4)') mem(434)(1:lmem(434)),
     %    (optr(54)-m(1))/K2
        write (23,'(a,1p1e10.4)') mem(440)(1:lmem(440)),optr(61)
        write (23,'(a,i7,a3,i7)') mem(293)(1:lmem(293)),opti(77)-1,
     %    ' - ',opti(78)-1
        write (23,'(a,1p1e11.4)') mem(438)(1:lmem(438)),optr(53)
c ##A38,5##
c ##A39,6##
        itmp = 5
        if (opti(80).eq.1) itmp = 6
        write (23,'(2a)') mem(444)(1:lmem(444)),mem(itmp)(1:lmem(itmp))
c ##A39,6##
c ##A10,2##
        itmp = 5
        if (opt(1).eq.1) itmp = 6
        write (23,'(/,2a)') mem(210)(1:lmem(210)),
     %    mem(itmp)(1:lmem(itmp))
        itmp = 5
        if (opti(20).eq.1) itmp = 6
        write (23,'(2a)') mem(290)(1:lmem(290)),mem(itmp)(1:lmem(itmp))
