        s(1,1) = 0.d0
        s(2,1) = 0.d0
c ##A19,194##
c        s(3,1) = 0.d0
c        s(3,1) = 0.4d0 * m(1) * rcen * rcen * optr(6)
        optr(75) = rcen
        optr(76) = rcen
c momento de inércia de um elipsoide: Izz = 1/5 * m * (a^2 + b^2)
c velocidade de rotação: wz = 2 * pi / período
c momento angular: Lz = Izz * wz = 1/5 * m * (a^2 + b^2) * wz = s(3,1)
        s(3,1) =0.2d0*m(1)*(optr(75)*optr(75)+optr(76)*optr(76))*optr(6)
        rho(1) = .75d0 * m(1) / (PI*optr(75)*optr(75)*optr(75))
        if (algor.ge.13) then
          optr(72) = 0.d0
          optr(73) = 0.d0
          optr(74) = optr(6)
c momento angular: L = I w; I = matriz 3x3 (tensor de inércia) e w = vetor 3x1 (vetor velocidade de rotação)
          s(1,1) = JC(1,1)*optr(72)+JC(1,2)*optr(73)+JC(1,3)*optr(74)
          s(2,1) = JC(2,1)*optr(72)+JC(2,2)*optr(73)+JC(2,3)*optr(74)
          s(3,1) = JC(3,1)*optr(72)+JC(3,2)*optr(73)+JC(3,3)*optr(74)
          s(1,1) = s(1,1) * K2
          s(2,1) = s(2,1) * K2
          s(3,1) = s(3,1) * K2
c          optr(69) = (JC(1,1)+JC(2,1)+JC(3,1)) * K2
c          optr(70) = (JC(1,2)+JC(2,2)+JC(3,2)) * K2
c          optr(71) = (JC(1,3)+JC(2,3)+JC(3,3)) * K2
          rho(1) = dens(1) * K2
        end if 
        call mxx_en (jcen,nbod,nbig,m,x,v,s,en(1),am(1),nov,nop,noc,
     %  xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,K2,rho)
c ##A19,194##
        write (23,'(//,a)') mem(51)(1:lmem(51))
