      if (algor.eq.5.and.(jcen(1).ne.0.or.jcen(2).ne.0.or.jcen(3)
     %  .ne.0)) call mio_err (23,mem(81),lmem(81),mem(114),lmem(114),
     %  ' ',1,mem(85),lmem(85))
c ##AAR1,10##
c
c Check whether RCEN > RMAX or RMAX/RCEN is very large
      if (rcen.gt.rmax) call mio_err (23,mem(81),lmem(81),mem(105),
     %  lmem(105),' ',1,mem(85),lmem(85))
