c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_JD2Y.FOR    (ErikSoft  7 July 1999)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Converts from Julian day number to Julian/Gregorian Calendar dates, assuming
c the dates are those used by the English calendar.
c
c Algorithm taken from `Practical Astronomy with your calculator' (1988)
c by Peter Duffett-Smith, 3rd edition, C.U.P.
c
c Algorithm for negative Julian day numbers (Julian calendar assumed) by
c J. E. Chambers.
c
c N.B. The output date is with respect to the Julian Calendar on or before
c ===  4th October 1582, and with respect to the Gregorian Calendar on or 
c      after 15th October 1582.
c
c
c------------------------------------------------------------------------------
c
      subroutine mio_jd2y (jd0,year,month,day)
c
      implicit none
c
c Input/Output
      integer year,month
      real*8 jd0,day
c
c Local
      integer i,a,b,c,d,e,g
      real*8 jd,f,temp,x,y,z
c
c------------------------------------------------------------------------------
c
      if (jd0.le.0) goto 50
c
      jd = jd0 + 0.5d0
      i = sign( dint(dabs(jd)), jd )
      f = jd - 1.d0*i
c
c If on or after 15th October 1582
      if (i.gt.2299160) then
        temp = (1.d0*i - 1867216.25d0) / 36524.25d0
        a = sign( dint(dabs(temp)), temp )
        temp = .25d0 * a
        b = i + 1 + a - sign( dint(dabs(temp)), temp )
      else
        b = i
      end if
c
      c = b + 1524
      temp = (1.d0*c - 122.1d0) / 365.25d0
      d = sign( dint(dabs(temp)), temp )
      temp = 365.25d0 * d
      e = sign( dint(dabs(temp)), temp )
      temp = (c-e) / 30.6001d0
      g = sign( dint(dabs(temp)), temp )
c
      temp = 30.6001d0 * g
      day = 1.d0*(c-e) + f - 1.d0*sign( dint(dabs(temp)), temp )
c
      if (g.le.13) month = g - 1
      if (g.gt.13) month = g - 13
c
      if (month.gt.2) year = d - 4716
      if (month.le.2) year = d - 4715
c
      if (day.gt.32) then
        day = day - 32
        month = month + 1
      end if
c
      if (month.gt.12) then
        month = month - 12
        year = year + 1
      end if
      return
c
  50  continue
c
c Algorithm for negative Julian day numbers (Duffett-Smith doesn't work)
      x = jd0 - 2232101.5
      f = x - dint(x)
      if (f.lt.0) f = f + 1.d0
      y = dint(mod(x,1461.d0) + 1461.d0)
      z = dint(mod(y,365.25d0))
      month = int((z + 0.5d0) / 30.61d0)
      day = dint(z + 1.5d0 - 30.61d0*dble(month)) + f
      month = mod(month + 2, 12) + 1
c
      year = 1399 + int (x / 365.25d0)
      if (x.lt.0) year = year - 1
      if (month.lt.3) year = year + 1
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_LOG.FOR    (ErikSoft   25 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Writes a progress report to the log file (or the screen if you are running
c Mercury interactively).
c
c------------------------------------------------------------------------------
c
c ##A30,2##
      subroutine mio_log (time,tstart,en,am,opt,mem,lmem,outfile)
c ##A30,2##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer lmem(NMESS), opt(9)
      real*8 time, tstart, en(3), am(3)
      character*80 mem(NMESS)
c ##A30,3##
      character*80 outfile
c ##A30,3##
c
c Local
      integer year, month
      real*8 tmp0, tmp1, t1
      character*38 flog
      character*6 tstring
c ##A30,4##
      character*1000 string
      integer size
c ##A30,4##
c
c------------------------------------------------------------------------------
c
      if (opt(3).eq.0.or.opt(3).eq.2) then
        tstring = mem(1)
        flog = '(1x,a,f14.1,a,2(a,1p1e12.5))'
      else if (opt(3).eq.1) then
        flog = '(1x,a,i10,1x,i2,1x,f4.1,2(a,1p1e12.5))'
      else
        tstring = mem(2)
        flog = '(1x,a,f14.3,a,2(a,1p1e12.5))'
      end if
c
      tmp0 = 0.d0
      tmp1 = 0.d0
      if (en(1).ne.0) tmp0 = (en(2) + en(3) - en(1)) / abs(en(1))
      if (am(1).ne.0) tmp1 = (am(2) + am(3) - am(1)) / abs(am(1))
c
c ##A30,5##
      string(1:6) = 'echo '''
      size = 6
c ##A30,5##
      if (opt(3).eq.1) then
        call mio_jd2y (time,year,month,t1)
c ##A30,6##
c        write (*,flog) mem(64)(1:lmem(64)), year, month, t1,
c     %    mem(65)(1:lmem(65)), tmp0,mem(66)(1:lmem(66)), tmp1
        size = size+1+lmem(64)+10+3+5+lmem(65)+12+lmem(66)+12
        write(string(7:size),'(1x,a,i10,1x,i2,1x,f4.1,2(a,1p1e12.5))')
     %    mem(64)(1:lmem(64)),year,month,t1,mem(65)(1:lmem(65)),tmp0,
     %    mem(66)(1:lmem(66)), tmp1
c ##A30,6##
      else
        if (opt(3).eq.0) t1 = time
        if (opt(3).eq.2) t1 = time - tstart
        if (opt(3).eq.3) t1 = (time - tstart) / 365.25d0
c ##A30,7##
c        write (*,flog) mem(63)(1:lmem(63)), t1, tstring,
c     %    mem(65)(1:lmem(65)), tmp0, mem(66)(1:lmem(66)), tmp1
        size = size+1+lmem(63)+14+6+lmem(65)+12+lmem(66)+12
        if (opt(3).eq.0.or.opt(3).eq.2) then
          write(string(7:size),'(1x,a,f14.1,a,2(a,1p1e12.5))')
     %      mem(63)(1:lmem(63)),t1,tstring,mem(65)(1:lmem(65)),tmp0,
     %      mem(66)(1:lmem(66)), tmp1
        else
          write(string(7:size),'(1x,a,f14.3,a,2(a,1p1e12.5))')
     %      mem(63)(1:lmem(63)),t1,tstring,mem(65)(1:lmem(65)),tmp0,
     %      mem(66)(1:lmem(66)), tmp1
        end if
c ##A30,7##
      end if
c
c ##A30,8##
      string(size+1:5+size) = ''' >> '
      call command (string(1:5+size)//outfile, 5+size+79)
c ##A30,8##
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_OUT.FOR    (ErikSoft   13 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Writes output variables for each object to an output file. Each variable
c is scaled between the minimum and maximum possible values and then
c written in a compressed format using ASCII characters.
c The output variables are:
c  r = the radial distance
c  theta = polar angle
c  phi = azimuthal angle
c  fv = 1 / [1 + 2(ke/be)^2], where be and ke are the object's binding and
c                             kinetic energies. (Note that 0 < fv < 1).
c  vtheta = polar angle of velocity vector
c  vphi = azimuthal angle of the velocity vector
c
c If this is the first output (OPFLAG = -1), or the first output since the 
c number of the objects or their masses have changed (OPFLAG = 1), then 
c the names, masses and spin components of all the objects are also output.
c
c N.B. Each object's distance must lie between RCEN < R < RMAX
c ===  
c
c------------------------------------------------------------------------------
c
c ##A13,19##
c ##AN28,22##
c ##A32,15##
c ##A35,31##
      subroutine mio_out (time,jcen,rcen,rmax,nbod,nbig,m,xh,vh,s,rho,
     %  stat,id,opt,opflag,algor,outfile,tstart,K2,AU,MSUN,optr,idtag)
c ##A35,31##
c ##A32,15##
c ##AN28,22##
c ##A13,19##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod, nbig, stat(nbod), opt(9), opflag, algor
      real*8 time,jcen(3),rcen,rmax,m(nbod),xh(3,nbod),vh(3,nbod)
      real*8 s(3,nbod),rho(nbod)
      character*80 outfile
      character*8 id(nbod)
c ##A13,18##
      real*8 tstart
c ##A13,18##
c ##AN28,23##
      real*8 K2,AU,MSUN
c ##AN28,23##
c ##A32,14##
      real*8 optr(76)
c ##A32,14##
c ##A35,32##
      integer idtag(nbod)
c ##A35,32##
c
c Local
      integer k, len, nchar
      real*8 rhocgs,k_2,rfac,rcen_2,fr,fv,theta,phi,vtheta,vphi
      character*160 header,c(NMAX)
      character*8 mio_fl2c,mio_re2c
c ##A13,9##
      character*7 fout
c ##A13,9##
c ##E19,1##
c      real*8 dmin,dmax
c ##E19,1##
c
c------------------------------------------------------------------------------
c
      rhocgs = AU * AU * AU * K2 / MSUN
      k_2 = 1.d0 / K2
      rcen_2 = 1.d0 / (rcen * rcen)
c ##E19,2##
c      dmin = rcen
c      dmax = 1.d1 * rmax
c      if (algor.ge.13) dmin = 0.1 * rcen
c
c Scaling factor (maximum possible range) for distances
c      rfac = log10 (rmax / rcen)
c      rfac = log10 (dmax / dmin)
      rfac = log10 (optr(50) / optr(49))
c ##E19,2##
c
c Create the format list, FOUT, used when outputting the orbital elements
      if (opt(4).eq.1) nchar = 2
      if (opt(4).eq.2) nchar = 4
      if (opt(4).eq.3) nchar = 7
c ##A13,10##
      len = 1  +  6 * nchar - 1
      fout(1:7) = '(a  ,$)'
c      if (len.lt.10) write (fout(3:3),'(i1)') len
c ##A13,10##
      if (len.ge.10) write (fout(3:4),'(i2)') len
c
c Open the orbital-elements output file
c ##E9,1##
c  10  open (21, file=outfile, status='old', access='append', err=10)
c ##E9,1##
c
c------------------------------------------------------------------------------
c
c  SPECIAL  OUTPUT  PROCEDURE
c
c If this is a new integration or a complete output is required (e.g. because
c the number of objects has changed), then output object details & parameters.
      if (opflag.eq.-1.or.opflag.eq.1) then
c
c Compose a header line with time, number of objects and relevant parameters
c ##A13,11##
        header(1:8)   = mio_fl2c (tstart)
c ##A13,11##
        header(9:16)  = mio_re2c (dble(nbig - 1),   0.d0, 11239423.99d0)
        header(12:19) = mio_re2c (dble(nbod - nbig),0.d0, 11239423.99d0)
        header(15:22) = mio_fl2c (m(1) * k_2)
        header(23:30) = mio_fl2c (jcen(1) * rcen_2)
        header(31:38) = mio_fl2c (jcen(2) * rcen_2 * rcen_2)
        header(39:46) = mio_fl2c (jcen(3) * rcen_2 * rcen_2 * rcen_2)
c ##E19,22##
c        header(47:54) = mio_fl2c (rcen)
c        header(55:62) = mio_fl2c (rmax)
        header(47:54) = mio_fl2c (optr(49))
        header(55:62) = mio_fl2c (optr(50))
c ##E19,22##
c ##AN28,134##
        header(63:70) = mio_fl2c (K2)
        header(71:78) = mio_fl2c (AU)
        header(79:86) = mio_fl2c (MSUN)
c ##AN28,134##
c ##A32,12##
c        header(63:70) = mio_fl2c (TWOPI / optr(6))
c ##A32,12##
c
c For each object, compress its index number, name, mass, spin components
c and density (some of these need to be converted to normal units).
        do k = 2, nbod
c ##A13,12##
c          c(k)(1:8) = mio_re2c (dble(k - 1), 0.d0, 11239423.99d0)
          c(k)(1:8) = id(k)
          c(k)(9:16) = mio_fl2c (m(k) * k_2)
          c(k)(17:24) = mio_fl2c (s(1,k) * k_2)
          c(k)(25:32) = mio_fl2c (s(2,k) * k_2)
          c(k)(33:40) = mio_fl2c (s(3,k) * k_2)
          c(k)(41:48) = mio_fl2c (rho(k) / rhocgs)
c ##A13,12##
c ##A35,33##
          c(k)(49:56) = mio_re2c (dble(idtag(k)),   0.d0, 11239423.99d0)
c ##A35,33##
        end do
c
c Write compressed output to file
c ##A13,13##
c        write (21,'(a1,a2,i2,a62,i1)') char(12),'6a',algor,header(1:62),
c     %    opt(4)
c ##A32,13##
c ##AN28,135##
        write (21,'(2(a1),i2,a86,i1,$)') char(12),'a',algor,
     %    header(1:86),opt(4)
c        write (21,'(2(a1),i2,a62,i1,$)') char(12),'a',algor,
c     %    header(1:62),opt(4)
c        write (21,'(2(a1),i2,a70,i1,$)') char(12),'a',algor,
c     %    header(1:70),opt(4)
c ##AN28,135##
c ##A32,13##
c ##A13,13##
        do k = 2, nbod
c ##A13,14##
c ##A35,34##
c          write (21,'(a48,$)') c(k)(1:48)
          write (21,'(a56,$)') c(k)(1:56)
c ##A35,34##
c ##A13,14##
        end do
      end if
c
c------------------------------------------------------------------------------
c
c  NORMAL  OUTPUT  PROCEDURE
c
c Compose a header line containing the time and number of objects
      header(1:8)   = mio_fl2c (time)
c ##A32,20##
      header(9:16) = mio_fl2c (TWOPI / optr(6))
c ##A32,20##
c ##A13,15##
c      header(9:16)  = mio_re2c (dble(nbig - 1),    0.d0, 11239423.99d0)
c      header(12:19) = mio_re2c (dble(nbod - nbig), 0.d0, 11239423.99d0)
c ##A13,15##
c
c Calculate output variables for each body and convert to compressed format
      do k = 2, nbod
c ##E19,3##
c        call mco_x2ov (rcen,rmax,m(1),m(k),xh(1,k),xh(2,k),xh(3,k),
c     %    vh(1,k),vh(2,k),vh(3,k),fr,theta,phi,fv,vtheta,vphi)
c        call mco_x2ov (dmin,dmax,m(1),m(k),xh(1,k),xh(2,k),xh(3,k),
c     %    vh(1,k),vh(2,k),vh(3,k),fr,theta,phi,fv,vtheta,vphi)
        call mco_x2ov (optr(49),optr(50),m(1),m(k),xh(1,k),xh(2,k),
     %    xh(3,k),vh(1,k),vh(2,k),vh(3,k),fr,theta,phi,fv,vtheta,vphi)
c ##E19,3##
c
c Object's index number and output variables
c ##A13,16##
c        c(k)(1:8) = mio_re2c (dble(k - 1), 0.d0, 11239423.99d0)
        c(k)(1:8)                 = mio_re2c (fr,     0.d0, rfac)
        c(k)(1+  nchar:8+  nchar) = mio_re2c (theta,  0.d0, PI)
        c(k)(1+2*nchar:8+2*nchar) = mio_re2c (phi,    0.d0, TWOPI)
        c(k)(1+3*nchar:8+3*nchar) = mio_re2c (fv,     0.d0, 1.d0)
        c(k)(1+4*nchar:8+4*nchar) = mio_re2c (vtheta, 0.d0, PI)
        c(k)(1+5*nchar:8+5*nchar) = mio_re2c (vphi,   0.d0, TWOPI)
c ##A13,16##
      end do
c
c Write compressed output to file
c ##A13,17##
c      write (21,'(a1,a2,a14)') char(12),'6b',header(1:14)
c ##A32,21##
c      write (21,'(a1,a8,$)') 'b',header(1:8)
      write (21,'(a1,a16,$)') 'b',header(1:16)
c ##A32,21##
c ##A13,17##
      do k = 2, nbod
        write (21,fout) c(k)(1:len)
      end do
c
c ##E9,2##
c      close (21)
c ##E9,2##
      opflag = 0
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_RE2C.FOR    (ErikSoft  27 June 1999)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Converts a REAL*8 variable X, where XMIN <= X < XMAX, into an ASCII string
c of 8 characters, using the new format compression: 
c
c X is first converted to base 224, and then each base 224 digit is converted 
c to an ASCII character, such that 0 -> character 32, 1 -> character 33...
c and 223 -> character 255.
c
c ASCII characters 0 - 31 (CTRL characters) are not used, because they
c cause problems when using some operating systems.
c
c------------------------------------------------------------------------------
c
      function mio_re2c (x,xmin,xmax)
c
      implicit none
c
c Input/output
      real*8 x,xmin,xmax
      character*8 mio_re2c
c
c Local
      integer j
      real*8 y,z
c
c------------------------------------------------------------------------------
c
      mio_re2c(1:8) = '        '
      y = (x - xmin) / (xmax - xmin)
c
      if (y.ge.1) then
        do j = 1, 8
          mio_re2c(j:j) = char(255)
        end do
      else if (y.gt.0) then
        z = y
        do j = 1, 8
          z = mod(z, 1.d0) * 224.d0
          mio_re2c(j:j) = char(int(z) + 32)
        end do
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_SPL.FOR    (ErikSoft  14 November 1999)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Given a character string STRING, of length LEN bytes, the routine finds 
c the beginnings and ends of NSUB substrings present in the original, and 
c delimited by spaces. The positions of the extremes of each substring are 
c returned in the array DELIMIT.
c Substrings are those which are separated by spaces or the = symbol.
c
c------------------------------------------------------------------------------
c
      subroutine mio_spl (len,string,nsub,delimit)
c
      implicit none
c
c Input/Output
c ##A19,139##
      integer len,nsub,delimit(2,1000)
c ##A19,139##
      character*1 string(len)
c
c Local
      integer j,k
      character*1 c
c
c------------------------------------------------------------------------------
c
      nsub = 0
      j = 0
      c = ' '
      delimit(1,1) = -1
c
c Find the start of string
  10  j = j + 1
      if (j.gt.len) goto 99
      c = string(j)
      if (c.eq.' '.or.c.eq.'=') goto 10
c
c Find the end of string
      k = j
  20  k = k + 1
      if (k.gt.len) goto 30
      c = string(k)
      if (c.ne.' '.and.c.ne.'=') goto 20
c
c Store details for this string
  30  nsub = nsub + 1
      delimit(1,nsub) = j
      delimit(2,nsub) = k - 1
c
      if (k.lt.len) then
        j = k
        goto 10
      end if
c
  99  continue
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MXX_EJEC.FOR    (ErikSoft   2 November 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates the distance from the central body of each object with index
c I >= I0. If this distance exceeds RMAX, the object is flagged for ejection 
c (STAT set to -3). If any object is to be ejected, EJFLAG = 1 on exit,
c otherwise EJFLAG = 0.
c
c Also updates the values of EN(3) and AM(3)---the change in energy and
c angular momentum due to collisions and ejections.
c
c
c N.B. All coordinates must be with respect to the central body!!
c ===
c
c------------------------------------------------------------------------------
c
c ##A3,11##
c ##A4,16##
c ##A5,31##
c ##AAR1,22##
c ##E12,3##
c ##A34,9##
c ##A40,8##
c ##A19,223##
c      subroutine mxx_ejec (time,tstart,rmax,en,am,jcen,i0,nbod,nbig,m,x,
c     %  v,s,stat,id,opt,ejflag,outfile,mem,lmem,rmin,opti,nbclo,bclo,
c     %  rcen,nstored,cce,flagce,algor,stopflag,optr,rce,nov,nop,noc,
c     %  xv,yv,zv,noe,kkk,dens,mce,xc,yc,zc,K2,rphys)
      subroutine mxx_ejec (time,tstart,rmax,en,am,jcen,i0,nbod,nbig,m,x,
     %  v,s,stat,id,opt,ejflag,outfile,mem,lmem,rmin,opti,nbclo,bclo,
     %  rcen,nstored,cce,flagce,algor,stopflag,optr,rce,nov,nop,noc,
     %  xv,yv,zv,noe,kkk,dens,mce,xc,yc,zc,K2,rho)
c ##A19,223##
c ##A40,8##
c ##A34,9##
c ##E12,3##
c ##AAR1,22##
c ##A5,31##
c ##A4,16##
c ##A3,11##
c
      implicit none
      include 'mercury.inc'
c ##A34,6##
      real*8 THIRD
      parameter (THIRD = .3333333333333333d0)
c ##A34,6##
c
c Input/Output
      integer i0, nbod, nbig, stat(nbod), opt(9), ejflag, lmem(NMESS)
      real*8 time, tstart, rmax, en(3), am(3), jcen(3)
      real*8 m(nbod), x(3,nbod), v(3,nbod), s(3,nbod)
      character*80 outfile, mem(NMESS)
      character*8 id(nbod)
c ##A3,10##
      real*8 rmin
c ##A3,10##
c ##A4,15##
      integer opti(90)
c ##A4,15##
c ##A5,29##
      integer nbclo,bclo(nbod)
      real*8 rcen
      integer nstored
      character*107 cce(FMAX)
      integer flagce
c ##A5,29##
c ##AAR1,21##
      integer algor
c ##AAR1,21##
c ##E12,4##
      integer stopflag
c ##E12,4##
c ##A34,10##
      real*8 optr(76)
c ##A34,10##
c ##A19,222##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mce(noc),dens(noc)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      real*8 K2
c      real*8 rphys(nbod)
      real*8 rho(nbod)
c ##A19,222##
c
c Local
      integer j, year, month
      real*8 r2,rmax2,t1,e,l
c ##A11,19##
      character*40 flost
c ##A11,19##
      character*6 tstring
c ##A3,8##
      real*8 rmin2
c ##A3,8##
c ##A5,30##
      integer j2
c ##A5,30##
c ##A7,6##
      integer c
      real*8 gm,a,r,v2
      real*8 mc,deltac
c ##A7,6##
c ##E12,1##
      real*8 tmp0
      character*38 fstop
c ##E12,1##
c ##A40,9##
      real*8 rce(nbod),dx,dy,dz,r2s
      integer k,flags
c ##A40,9##
c
c------------------------------------------------------------------------------
c
      if (i0.le.0) i0 = 2
      ejflag = 0
      rmax2 = rmax * rmax
c ##A3,9##
      rmin2 = rmin * rmin
c ##A3,9##
c ##A40,10##
      flags = 0
c ##A40,10##
c
c Calculate initial energy and angular momentum
c ##A19,201##
      call mxx_en (jcen,nbod,nbig,m,x,v,s,e,l,nov,nop,noc,
     %  xv,yv,zv,noe,kkk,dens,mce,xc,yc,zc,optr,opti,algor,K2,rho)
c ##A19,201##
c ##A7,5##
      c = 2
      gm = m(1) + m(c)
      mc = m(c)
c ##AAR1,20##
      if (algor.eq.5) c = c + 1
c ##AAR1,20##
      if (i0.gt.3) then
        c = c + 1
        gm = gm + m(c)
        mc = m(c)
      end if
      call mco_x2a (gm,x(1,c),x(2,c),x(3,c),v(1,c),v(2,c),v(3,c),
     %  a,r,v2)
      deltac = 1.5d0*(mc/m(1))**(2.0d0/7)*a
      if (opti(6).eq.1) then
        rmin = r - deltac
        rmax = r + deltac
        rmin2 = rmin * rmin
        rmax2 = rmax * rmax
      end if
c ##A7,5##
c ##A34,5##
      if (opti(73).eq.1) then
        c = opti(74)
        gm = m(1) + m(c)
        call mco_x2a (gm,x(1,c),x(2,c),x(3,c),v(1,c),v(2,c),v(3,c),
     %    a,r,v2)
        if (a.le.0) a = r
        if (opti(75).eq.0) then
          deltac = .5d0 * optr(48) * a * (THIRD * m(c) / m(1))**THIRD
        else
          deltac = .5d0 * optr(48)
        end if
        rmin = r - deltac
        rmax = r + deltac
        rmin2 = rmin * rmin
        rmax2 = rmax * rmax
      end if
c ##A34,5##
c
c Flag each object which is ejected, and set its mass to zero
      do j = i0, nbod
        r2 = x(1,j)*x(1,j) + x(2,j)*x(2,j) + x(3,j)*x(3,j)
c ##A40,11##
        if (opti(83).eq.1) then
          flags = 0
          do k = i0, nbod
            if (k.ge.opti(84).and.k.le.opti(85)) then
              dx = x(1,j) - x(1,k)
              dy = x(2,j) - x(2,k)
              dz = x(3,j) - x(3,k)
              r2s = dsqrt(dx * dx + dy * dy + dz * dz)
              if (r2s.le.rce(k)) flags = 2
            end if
          end do
          if (flags.eq.0) flags = 1
        end if
c ##A40,11##
c ##A3,7##
c ##A4,14##
c ##A40,12##
        if (((r2.gt.rmax2.or.r2.lt.rmin2).or.flags.eq.1)
     %    .and.(j.lt.opti(2).or.j.gt.opti(3))) then
c ##A40,12##
c ##A4,14##
c ##A3,7##
c ##A5,28##
          call bcloo (nbclo,bclo,j,nbod,j2,flagce)
c ##E13,2##
c ##A33,5##
c ##E19,15##
          call mio_cestored2 (nbod,m,j2,opt(4),time,x,v,
     %    nstored,bclo,cce,'e',0,algor,optr)
c ##E19,15##
c ##A33,5##
c ##E13,2##
c ##A5,28##
          ejflag = 1
          stat(j) = -3
          m(j) = 0.d0
          s(1,j) = 0.d0
          s(2,j) = 0.d0
          s(3,j) = 0.d0
c
c ##E12,2##
c If new encounter minima have occurred, decide whether to stop integration
      stopflag = 0
      if (opt(1).eq.1) then
c  20    open (23, file=outfile(3), status='old', access='append',err=20)
c If time style is Gregorian date then...
        tmp0 = time
        if (opt(3).eq.1) then
          fstop = '(3a,/,9x,a,i10,1x,i2,1x,f4.1)'
          call mio_jd2y (tmp0,year,month,t1)
          write (23,fstop) mem(121)(1:lmem(121)),mem(142)
     %      (1:lmem(142)),id(j),mem(71)(1:lmem(71)),year,month,t1
          write (*,fstop) mem(121)(1:lmem(121)),mem(142)
     %      (1:lmem(142)),id(j),mem(71)(1:lmem(71)),year,month,t1
c Otherwise...
        else
          if (opt(3).eq.3) then
            tstring = mem(2)
            fstop = '(3a,/,9x,a,f14.3,a)'
            t1 = (tmp0 - tstart) / 365.25d0
          else
            tstring = mem(1)
            fstop = '(3a,/,9x,a,f14.1,a)'
            if (opt(3).eq.0) t1 = tmp0
            if (opt(3).eq.2) t1 = tmp0 - tstart
          end if
          write (23,fstop) mem(121)(1:lmem(121)),mem(142)
     %      (1:lmem(142)),id(j),mem(71)(1:lmem(71)),t1,tstring
          write (*,fstop) mem(121)(1:lmem(121)),mem(142)
     %      (1:lmem(142)),id(j),mem(71)(1:lmem(71)),t1,tstring
        end if
        stopflag = 1
c        close(23)
        return
      end if
c ##E12,2##
c
c Write message to information file
c ##E9,13##
c  20      open  (23,file=outfile,status='old',access='append',err=20)
c ##E9,13##
c ##A11,14##
          opti(15) = opti(15) - 1
          opti(17) = opti(17) + 1
c ##A11,14##
          if (opt(3).eq.1) then
            call mio_jd2y (time,year,month,t1)
c ##A11,15##
            flost = '(1x,a8,a,i10,1x,i2,1x,f8.5,3x,4(1x,i7))'
            if (opti(73).eq.0) then
            write (23,flost) id(j),mem(68)(1:lmem(68)),year,month,t1,
     %        opti(15),opti(16),opti(17),opti(18)
            else
            write (23,flost) id(j),mem(427)(1:lmem(427)),year,month,t1,
     %        opti(15),opti(16),opti(17),opti(18)
            end if
c ##A11,15##
          else
            if (opt(3).eq.3) then
              t1 = (time - tstart) / 365.25d0
              tstring = mem(2)
c ##A11,16##
              flost = '(1x,a8,a,f18.7,a,3x,4(1x,i7))'
c ##A11,16##
            else
              if (opt(3).eq.0) t1 = time
              if (opt(3).eq.2) t1 = time - tstart
              tstring = mem(1)
c ##A11,17##
              flost = '(1x,a8,a,f18.5,a,3x,4(1x,i7))'
c ##A11,17##
            end if
c ##A11,18##
            if (opti(73).eq.0) then
            write (23,flost) id(j),mem(68)(1:lmem(68)),t1,tstring,
     %        opti(15),opti(16),opti(17),opti(18)
            else
            write (23,flost) id(j),mem(427)(1:lmem(427)),t1,tstring,
     %        opti(15),opti(16),opti(17),opti(18)
            end if
c ##A11,18##
          end if
c ##E9,14##
c          close (23)
c ##E9,14##
        end if
      end do
c
c If ejections occurred, update ELOST and LLOST
      if (ejflag.ne.0) then
c ##A19,202##
        call mxx_en (jcen,nbod,nbig,m,x,v,s,en(2),am(2),nov,nop,noc,
     %    xv,yv,zv,noe,kkk,dens,mce,xc,yc,zc,optr,opti,algor,K2,rho)
c ##A19,202##
        en(3) = en(3) + (e - en(2))
        am(3) = am(3) + (l - am(2))
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MXX_ELIM.FOR    (ErikSoft   13 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Removes any objects with STAT < 0 (i.e. those that have been flagged for 
c removal) and reindexes all the appropriate arrays for the remaining objects.
c
c------------------------------------------------------------------------------
c
c ##A4,7##
c ##A7,11##
c ##A8,4##
c ##E14,41##
c ##AN28,24##
c ##A35,19##
c ##A43,65##
      subroutine mxx_elim (nbod,nbig,m,x,v,s,rho,rceh,rcrit,ngf,stat,
     %  id,mem,lmem,outfile,nelim,opti,stopflag,algor,optr,time,tstop,
     %  tstart,opt,tcol,K2,idtag,lapla1,lapla2)
c ##A43,65##
c ##A35,19##
c ##AN28,24##
c ##E14,41##
c ##A8,4##
c ##A7,11##
c ##A4,7##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod, nbig, nelim, stat(nbod), lmem(NMESS)
      real*8 m(nbod), x(3,nbod), v(3,nbod), s(3,nbod)
      real*8 rho(nbod), rceh(nbod), rcrit(nbod), ngf(4,nbod)
      character*8 id(nbod)
      character*80 outfile, mem(NMESS)
c ##A4,6##
      integer opti(90)
c ##A4,6##
c ##A7,9##
      integer stopflag
      integer algor
c ##A7,9##
c ##A8,5##
      real*8 optr(76)
      real*8 time,tstop,tstart
      integer opt
c ##A8,5##
c ##E14,42##
      real*8 tcol
c ##E14,42##
c ##AN28,25##
      real*8 K2
c ##AN28,25##
c ##A35,20##
      integer idtag(nbod)
c ##A35,20##
c ##A43,66##
      integer lapla1(nbod)
      integer lapla2(nbod)
c ##A43,66##
c
c Local
      integer j, k, l, nbigelim, elim(NMAX+1)
c ##A7,10##
      integer c
c ##A7,10##
c ##A8,6##
      real*8 k_2
      real*8 sum
      integer flag,i0
      integer year,month
      real*8 t1
c ##A8,6##
c
c------------------------------------------------------------------------------
c
c ##A8,7##
      k_2 = 1.d0 / K2
      flag = 0
      i0 = 2
      if (algor.eq.11.or.algor.eq.12) i0 = 3
c ##A8,7##
c ##AAR1,11##
      if (algor.eq.5) i0 = 4
c ##AAR1,11##
c
c ##A7,8##
c      stopflag = 0
      if (opti(6).gt.0) then
        c = 2
        if (algor.eq.11.or.algor.eq.12) c = c + 1
c ##AAR1,12##
        if (algor.eq.5) c = c + 2
c ##AAR1,12##
        if (stat(c).lt.0) then
c ##E9,15##
c  20      open (23,file=outfile,status='old',access='append',err=20)
c ##E9,15##
          write (23,'(/,4a,/)') mem(81)(1:lmem(81)),
     %      mem(133)(1:lmem(133)),id(c),mem(134)(1:lmem(134))
c ##E9,16##
c          close (23)
c ##E9,16##
c ##A12,3##
          write (*,'(/,4a,/)') mem(81)(1:lmem(81)),
     %      mem(133)(1:lmem(133)),id(c),mem(134)(1:lmem(134))
c ##A12,3##
c          stopflag = 1
          stop
        end if
      end if
c ##A7,8##
c
c Find out how many objects are to be removed
      nelim = 0
      nbigelim = 0
      do j = 2, nbod
        if (stat(j).lt.0) then
          nelim = nelim + 1
          elim(nelim) = j
          if (j.le.nbig) nbigelim = nbigelim + 1
        end if
      end do
      elim(nelim+1) = nbod + 1
c
c Eliminate unwanted objects
      do k = 1, nelim
        do j = elim(k) - k + 1, elim(k+1) - k - 1
          l = j + k
          x(1,j) = x(1,l)
          x(2,j) = x(2,l)
          x(3,j) = x(3,l)
          v(1,j) = v(1,l)
          v(2,j) = v(2,l)
          v(3,j) = v(3,l)
          m(j)   = m(l)
          s(1,j) = s(1,l)
          s(2,j) = s(2,l)
          s(3,j) = s(3,l)
          rho(j) = rho(l)
	  rcrit(j) = rcrit(l)    !NEW!
          rceh(j) = rceh(l)
          stat(j) = stat(l)
          id(j) = id(l)
          ngf(1,j) = ngf(1,l)
          ngf(2,j) = ngf(2,l)
          ngf(3,j) = ngf(3,l)
          ngf(4,j) = ngf(4,l)
c ##A35,21##
          idtag(j) = idtag(l)
c ##A35,21##
c ##A43,67##
          lapla1(j) = lapla1(l)
          lapla2(j) = lapla2(l)
c ##A43,67##
        end do
      end do
c
c Update total number of bodies and number of Big bodies
      nbod = nbod - nelim
      nbig = nbig - nbigelim
c
c If no massive bodies remain, stop the integration
c ##E6,2##
      if (nbig.lt.1) then
c ##E6,2##
c ##E9,17##
c  10    open (23,file=outfile,status='old',access='append',err=10)
c ##E9,17##
c ##E6,3##
        write (23,'(/,2a,/)') mem(81)(1:lmem(81)),mem(124)(1:lmem(124))
c ##E6,3##
c ##E9,18##
c        close (23)
c ##E9,18##
c ##A12,4##
        write (*,'(/,2a,/)') mem(81)(1:lmem(81)),mem(124)(1:lmem(124))
c ##A12,4##
        stop
      end if
c ##A4,5##
      call reindex (opti(2),opti(3),nelim,elim)
c ##A4,5##
c ##A5,33##
      call reindex (opti(4),opti(5),nelim,elim)
c ##A5,33##
c ##A22,30##
      call reindex (opti(27),opti(28),nelim,elim)
      call reindex (opti(29),opti(30),nelim,elim)
c ##A22,30##
c ##A24,5##
      call reindex (opti(35),opti(36),nelim,elim)
      call reindex (opti(37),opti(38),nelim,elim)
c ##A24,5##
c ##ANO29,27##
      call reindex (opti(47),opti(48),nelim,elim)
      call reindex (opti(49),opti(50),nelim,elim)
c ##ANO29,27##
c ##A32,7##
      call reindex (opti(56),opti(57),nelim,elim)
      call reindex (opti(58),opti(59),nelim,elim)
      call reindex (opti(66),opti(67),nelim,elim)
      call reindex (opti(69),opti(70),nelim,elim)
c ##A32,7##
c ##A38,101##
      call reindex (opti(77),opti(78),nelim,elim)
c ##A38,101##
c ##A8,8##
      call reindex (opti(11),opti(12),nelim,elim)
      call reindex (opti(13),opti(14),nelim,elim)
c ##A40,4##
      call reindex (opti(84),opti(85),nelim,elim)
c ##A40,4##
c ##A42,9##
      call reindex (opti(88),opti(89),nelim,elim)
c ##A42,9##
c
      if (opti(7).gt.0.and.nbod.le.opti(8)) then
c ##E9,19##
c  30    open (23,file=outfile,status='old',access='append',err=30)
c ##E9,19##
        if (opt.eq.1) then
c ##E14,43##
          call mio_jd2y (tcol+optr(4),year,month,t1)
c ##E14,43##
          write (23,'(/,2a,i7,a1,1x,a,i10,1x,i2,1x,f8.5,/)')
     %      mem(121)(1:lmem(121)),mem(135)(1:lmem(135)),nbod-1,',',
     %      mem(71)(1:lmem(71)),year,month,t1
c ##A12,5##
          write (*,'(/,2a,i7,a1,1x,a,i10,1x,i2,1x,f8.5,/)')
     %      mem(121)(1:lmem(121)),mem(135)(1:lmem(135)),nbod-1,',',
     %      mem(71)(1:lmem(71)),year,month,t1
c ##A12,5##
        else
          if (opt.eq.3) then
c ##E14,44##
            t1 = (tcol+optr(4) - tstart) / 365.25d0
c ##E14,44##
            write (23,'(/,2a,i7,a1,1x,a,f18.7,a,/)')
     %        mem(121)(1:lmem(121)),mem(135)(1:lmem(135)),nbod-1,',',
     %        mem(71)(1:lmem(71)),t1,mem(2)(1:lmem(2))
c ##A12,6##
            write (*,'(/,2a,i7,a1,1x,a,f18.7,a,/)')
     %        mem(121)(1:lmem(121)),mem(135)(1:lmem(135)),nbod-1,',',
     %        mem(71)(1:lmem(71)),t1,mem(2)(1:lmem(2))
c ##A12,6##
          else
c ##E14,45##
            if (opt.eq.0) t1 = tcol+optr(4)
            if (opt.eq.2) t1 = tcol+optr(4) - tstart
c ##E14,45##
            write (23,'(/,2a,i7,a1,1x,a,f18.5,a,/)')
     %        mem(121)(1:lmem(121)),mem(135)(1:lmem(135)),nbod-1,',',
     %        mem(71)(1:lmem(71)),t1,mem(1)(1:lmem(1))
c ##A12,7##
            write (*,'(/,2a,i7,a1,1x,a,f18.5,a,/)')
     %        mem(121)(1:lmem(121)),mem(135)(1:lmem(135)),nbod-1,',',
     %        mem(71)(1:lmem(71)),t1,mem(1)(1:lmem(1))
c ##A12,7##
          end if
        end if
c ##E9,20##
c        close (23)
c ##E9,20##
c        stopflag = 1
        opti(7) = 0
        flag = 1
      end if
      if (opti(9).gt.0) then
        do j = i0, nbod
          if ((m(j).ge.optr(2))
     %      .and.(j.lt.opti(11).or.j.gt.opti(12))) then
c ##E9,21##
c  40        open (23,file=outfile,status='old',access='append',err=40)
c ##E9,21##
            if (opt.eq.1) then
c ##E14,46##
              call mio_jd2y (tcol+optr(4),year,month,t1)
c ##E14,46##
              write (23,'(/,2a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,
     %          f8.5,/)') mem(121)(1:lmem(121)),mem(136)(1:lmem(136)),
     %          id(j),',',m(j)*k_2,mem(3)(1:lmem(3)),',',
     %          mem(71)(1:lmem(71)),year,month,t1
c ##A12,8##
              write (*,'(/,2a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,
     %          f8.5,/)') mem(121)(1:lmem(121)),mem(136)(1:lmem(136)),
     %          id(j),',',m(j)*k_2,mem(3)(1:lmem(3)),',',
     %          mem(71)(1:lmem(71)),year,month,t1
c ##A12,8##
            else
              if (opt.eq.3) then
c ##E14,47##
                t1 = (tcol+optr(4) - tstart) / 365.25d0
c ##E14,47##
                write (23,'(/,2a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.7,a,
     %            /)') mem(121)(1:lmem(121)),mem(136)(1:lmem(136)),
     %            id(j),',',m(j)*k_2,mem(3)(1:lmem(3)),',',
     %            mem(71)(1:lmem(71)),t1,mem(2)(1:lmem(2))
c ##A12,9##
                write (*,'(/,2a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.7,a,
     %            /)') mem(121)(1:lmem(121)),mem(136)(1:lmem(136)),
     %            id(j),',',m(j)*k_2,mem(3)(1:lmem(3)),',',
     %            mem(71)(1:lmem(71)),t1,mem(2)(1:lmem(2))
c ##A12,9##
              else
c ##E14,48##
                if (opt.eq.0) t1 = tcol+optr(4)
                if (opt.eq.2) t1 = tcol+optr(4) - tstart
c ##E14,48##
                write (23,'(/,2a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.5,a,
     %            /)') mem(121)(1:lmem(121)),mem(136)(1:lmem(136)),
     %            id(j),',',m(j)*k_2,mem(3)(1:lmem(3)),',',
     %            mem(71)(1:lmem(71)),t1,mem(1)(1:lmem(1))
c ##A12,10##
                write (*,'(/,2a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.5,a,
     %            /)') mem(121)(1:lmem(121)),mem(136)(1:lmem(136)),
     %            id(j),',',m(j)*k_2,mem(3)(1:lmem(3)),',',
     %            mem(71)(1:lmem(71)),t1,mem(1)(1:lmem(1))
c ##A12,10##
              end if
            end if
c ##E9,22##
c            close (23)
c ##E9,22##
c            stopflag = 1
            opti(9) = 0
            flag = 1
            exit
          end if
        end do
      end if
      if (opti(10).gt.0) then
        sum = 0
        do j = i0, nbod
          if (j.lt.opti(13).or.j.gt.opti(14)) sum = sum + m(j)
        end do
        if (sum.le.optr(3)) then
c ##E9,23##
c  50      open (23,file=outfile,status='old',access='append',err=50)
c ##E9,23##
          if (opt.eq.1) then
c ##E14,49##
            call mio_jd2y (tcol+optr(4),year,month,t1)
c ##E14,49##
            write (23,'(/,2a,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,f8.5,
     %        /)') mem(121)(1:lmem(121)),mem(137)(1:lmem(137)),sum*k_2,
     %        mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),year,month,t1
c ##A12,11##
            write (*,'(/,2a,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,f8.5,
     %        /)') mem(121)(1:lmem(121)),mem(137)(1:lmem(137)),sum*k_2,
     %        mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),year,month,t1
c ##A12,11##
          else
            if (opt.eq.3) then
c ##E14,50##
              t1 = (tcol+optr(4) - tstart) / 365.25d0
c ##E14,50##
              write (23,'(/,2a,1p1e12.6,0p,a,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(137)(1:lmem(137)),sum*k_2,
     %          mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %          mem(2)(1:lmem(2))
c ##A12,12##
              write (*,'(/,2a,1p1e12.6,0p,a,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(137)(1:lmem(137)),sum*k_2,
     %          mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %          mem(2)(1:lmem(2))
c ##A12,12##
            else
c ##E14,51##
              if (opt.eq.0) t1 = tcol+optr(4)
              if (opt.eq.2) t1 = tcol+optr(4) - tstart
c ##E14,51##
              write (23,'(/,2a,1p1e12.6,0p,a,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(137)(1:lmem(137)),sum*k_2,
     %          mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %          mem(1)(1:lmem(1))
c ##A12,13##
              write (*,'(/,2a,1p1e12.6,0p,a,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(137)(1:lmem(137)),sum*k_2,
     %          mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %          mem(1)(1:lmem(1))
c ##A12,13##
            end if
          end if
c ##E9,24##
c          close (23)
c ##E9,24##
c          stopflag = 1
          opti(10) = 0
          flag = 1
        end if
      end if
      if (flag.gt.0) then
c ##E14,52##
c        tstop = time + optr(4)
        tstop = tcol + optr(4)
c ##E14,52##
c        optr(4) = 0
      end if
c ##A8,8##
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c     MXX_EN.FOR    (ErikSoft   28 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates the total energy and angular-momentum for a system of objects
c with masses M, coordinates X, velocities V and spin angular momenta S.
c
c N.B. All coordinates and velocities must be with respect to the central
c ===  body.
c
c------------------------------------------------------------------------------
c
c ##A19,192##
c      subroutine mxx_en  (jcen,nbod,nbig,m,xh,vh,s,e,l2,nov,nop,noc,
c     %  xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,K2,rhophys,
c     %  flag)
      subroutine mxx_en  (jcen,nbod,nbig,m,xh,vh,s,e,l2,nov,nop,noc,
     %  xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,K2,rho)
c ##A19,192##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig
      real*8 jcen(3),m(nbod),xh(3,nbod),vh(3,nbod),s(3,nbod),e,l2
c ##A19,193##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      integer algor
      real*8 optr(76)
      integer opti(90)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      real*8 K2
      real*8 THIRD
      parameter (THIRD = .3333333333333333d0)
c      real*8 rhophys(nbod)
c      integer flag
      real*8 rho(nbod)
c ##A19,193##
c
c Local
      integer j,k,iflag,itmp(9)
      real*8 x(3,NMAX),v(3,NMAX),temp,dx,dy,dz,r2,tmp,ke,pe,l(3)
      real*8 r_1,r_2,r_4,r_6,u2,u4,u6,tmp2(4,NMAX)
c ##A19,196##
      real*8 vpot
      real*8 s_1, s2
      integer novl,nopl,noel,kl
      real*8 xl(novmax),yl(novmax),zl(novmax)
      integer ilay,l0,j1,i0
      real*8 vx,vy,vz,del,inc
      dimension noel(nopmax)
      dimension kl(nopmax,noed)
C      real*8 kr,radius,density,srate
      real*8 kr,radius,srate
      real*8 lat,lon,wx,wy,wz
c ##A19,196##
c
c------------------------------------------------------------------------------
c
      ke = 0.d0
      pe = 0.d0
      l(1) = 0.d0
      l(2) = 0.d0
      l(3) = 0.d0
c ##A19,226##
      kr = 0.d0
c ##A19,226##
c
c Convert to barycentric coordinates and velocities
      call mco_h2b(temp,jcen,nbod,nbig,temp,m,xh,vh,x,v,tmp2,iflag,itmp)
c
c Do the spin angular momenta first (probably the smallest terms)
      do j = 1, nbod
        l(1) = l(1) + s(1,j)
        l(2) = l(2) + s(2,j)
        l(3) = l(3) + s(3,j)
c ##A19,227##
        l2 = sqrt(s(1,j)*s(1,j) + s(2,j)*s(2,j) + s(3,j)*s(3,j))
c        if (flag.eq.0) then
cc          radius = rhophys(j)
c          density = .75d0 * m(j) / (PI*rhophys(j)*rhophys(j)*rhophys(j))
c        else if (flag.eq.1) then
cc          radius = (.75d0 / PI * m(j) / rhophys(j))**THIRD
c          density = rhophys(j)
c        end if
c        if (j.eq.1) then
c          density = .75d0 * m(j) / (PI*optr(75)*optr(75)*optr(75))
c          if (algor.ge.13) then
c            kr = kr + optr(69) * optr(72) * optr(72) +
c     %        optr(70) * optr(73) * optr(73) +
c     %        optr(71) * optr(74) * optr(74)
c          else
cc            kr = kr + 0.4d0 * m(1) *optr(75)*optr(75)*optr(6)*optr(6)
c            if (l2.gt.0) then
c              call mce_spin (1.d0,m(j),l2,density,srate)
c            else
c              srate = 0.d0
c            end if
c            srate = srate * TWOPI
c            kr = kr + 0.2d0*m(1)*(optr(75)*optr(75)+optr(76)*optr(76))*
c     %        srate*srate
c          end if        
c        else
cc          l2 = sqrt(s(1,j)*s(1,j) + s(2,j)*s(2,j) + s(3,j)*s(3,j))
c          if (flag.eq.0) then
c            radius = rhophys(j)
c          else if (flag.eq.1) then
c            radius = (.75d0 / PI * m(j) / rhophys(j))**THIRD
c          end if
cc          if (m(j).ne.0) kr=kr + 0.4d0*l2*l2 / (radius * radius * m(j))
c          if (l2.gt.0) then
c            call mce_spin (1.d0,m(j),l2,density,srate)
c          else
c            srate = 0.d0
c          end if
c          srate = srate * TWOPI
c          kr = kr + 0.4d0*m(j)*radius*radius*srate*srate
c        end if
c
        if (l2.gt.0) then
          call mce_spin (1.d0,m(j),l2,rho(j),srate)
          temp = s(3,j) / l2
          if (abs(temp).lt.1) then
c inclinação medida a partir do eixo Z
c            lat = acos (temp)
c latitude medida a partir do plano XOY-inercial
            lat = asin (temp)
c longitude medida a partir do momento angular perpendicular a órbita (projeção no plano XOY-inercial e no 4º quadrante (X,-Y)). Como a longitude é medida a partir do eixo +X, então a projeção no plano XOY-inercial do vetor momento angular (perpendicular ao plano de uma órbita com inclinação) se dará no 4º quadrante (X,-Y); Murray and Dermott (1999) - pg. 48, fig. 2.13; pg. 52, Eqs. 2.132 e 2.133; pg. 53, Eqs. 2.137 (dividir a primeira eq. pela segunda para aparecer tangente da longitude do nodo)
            lon = atan2 (s(1,j), -s(2,j))
          else
c lat = acos (temp)
c            if (temp.gt.0) lat = 0.d0
c            if (temp.lt.0) lat = PI
c lat = asin (temp)
            if (temp.gt.0) lat =  PI * 0.5d0
            if (temp.lt.0) lat = -PI * 0.5d0
            lon = 0.d0
          end if
        else
          srate = 0.d0
          lat   = 0.d0
          lon   = 0.d0
        end if
c na subrotina mce_spin, srate é a frequência (f=w/(2*pi)), aqui precisamos da velocidade de rotação (2*pi*f=w)
        srate = srate * TWOPI
c assume-se que o vetor velocidade de rotação tem a mesma direção e sentido do vetor momento angular (Mercury trabalha com corpos esféricos)
        wx = srate * cos(lat) * cos(lon)
        wy = srate * cos(lat) * sin(lon)
        wz = srate * sin(lat)
c energia rotacional: kr = 1/2 * w . L (= produto escalar entre o vetor velocidade de rotação e o vetor momento angular (Nivaldo Lemos, pg. 138)); w e L vetores 3x1. OBS: o 1/2 é colocado no final dessa subrotina
        kr = kr + s(1,j) * wx + s(2,j) * wy + s(3,j) * wz
c o correto seria atualizar também o vetor velocidade de rotação do corpo central toda vez que houvesse uma colisão com ele. Para isso, bastaria usar as linhas de comando abaixo:
c        if (j.eq.1) then
c          optr(72) = wx
c          optr(73) = wy
c          optr(74) = wz
c          optr(6)  = wz
c        end if
c
c        if (j.eq.1) then
c          if (algor.ge.13) then
cc            kr = kr + optr(69) * optr(72) * optr(72) +
cc     %        optr(70) * optr(73) * optr(73) +
cc     %        optr(71) * optr(74) * optr(74)
cc energia rotacional: kr = 1/2 * w . L (= produto escalar entre o vetor velocidade de rotação e o vetor momento angular (Nivaldo Lemos, pg. 138)); w e L vetores 3x1. OBS: o 1/2 é colocado no final dessa subrotina
c            kr = kr + s(1,j) * optr(72) + s(2,j) * optr(73) +
c     %        s(3,j) * optr(74)
c          else
cc momento de inércia de um elipsoide: Izz = 1/5 * m * (a^2 + b^2)
cc velocidade de rotação: srate (mce_spin)
cc energia rotacional: kr = 1/2 * Izz * srate^2 = 1/2 * 1/5 * m * (a^2 + b^2) * srate^2 = 1/10 * m * (a^2 + b^2) * srate^2. OBS: o 1/2 é colocado no final dessa subrotina
c            kr = kr + 0.2d0*m(j)*(optr(75)*optr(75)+optr(76)*optr(76))*
c     %        srate*srate
c          end if        
c        else
cc raio de uma esfera
c          radius = (.75d0 / PI * m(j) / rho(j))**THIRD
cc energia rotacional para uma esfera (a=b=r): kr = 1/2 * Izz * srate^2 = 1/2 * 1/5 * m * (a^2 + b^2) * srate^2 = 1/2 * 1/5 * m * 2 * r^2 * srate^2 = 1/5 * m * r^2 * srate^2. OBS: o 1/2 é colocado no final dessa subrotina
c          kr = kr + 0.4d0*m(j)*radius*radius*srate*srate
c        end if
c ##A19,227##
      end do
c
c Orbital angular momentum and kinetic energy terms
      do j = 1, nbod
        l(1) = l(1)  +  m(j)*(x(2,j) * v(3,j)  -  x(3,j) * v(2,j))
        l(2) = l(2)  +  m(j)*(x(3,j) * v(1,j)  -  x(1,j) * v(3,j))
        l(3) = l(3)  +  m(j)*(x(1,j) * v(2,j)  -  x(2,j) * v(1,j))
        ke = ke + m(j)*(v(1,j)*v(1,j)+v(2,j)*v(2,j)+v(3,j)*v(3,j))
      end do
c
c Potential energy terms due to pairs of bodies
      do j = 2, nbod
        tmp = 0.d0
        do k = j + 1, nbod
          dx = x(1,k) - x(1,j)
          dy = x(2,k) - x(2,j)
          dz = x(3,k) - x(3,j)
          r2 = dx*dx + dy*dy + dz*dz
          if (r2.ne.0) tmp = tmp + m(k) / sqrt(r2)
        end do
        pe = pe  -  tmp * m(j)
      end do
c
c Potential energy terms involving the central body
      do j = 2, nbod
c        dx = x(1,j) - x(1,1)
c        dy = x(2,j) - x(2,1)
c        dz = x(3,j) - x(3,1)
c        r2 = dx*dx + dy*dy + dz*dz
c        if (r2.ne.0) pe = pe  -  m(1) * m(j) / sqrt(r2)
c ##A19,195##
        dx = x(1,j) - x(1,1)
        dy = x(2,j) - x(2,1)
        dz = x(3,j) - x(3,1)
        r2 = dx*dx + dy*dy + dz*dz
        if (algor.lt.13) then
          if (r2.ne.0) pe = pe  -  m(1) * m(j) / sqrt(r2)
        else
          vpot = 0.d0
c
c------------------------------------------------------------------------------
c
c polyhedron method
          if (algor.eq.13.or.algor.eq.16.or.algor.eq.19) then
            if (opti(22).eq.0.and.opti(21).eq.1) then
              if (r2.ne.0) then
              call polyhedron2 (nov,nop,xv,yv,zv,noe,kkk,
     %          dens(opti(21)),dx,dy,dz,vpot,K2)
              endif
            else
              if (r2.ne.0) then
              do i0 = 1, nop
                l0 = 1
c compute new vertices
                do ilay = 1, opti(21)
                  inc = del * ilay
                  do j1 = 1, noe(i0)
                    l0 = l0 + 1
                    xl(l0) = xv(kkk(i0,j1)) * inc
                    yl(l0) = yv(kkk(i0,j1)) * inc
                    zl(l0) = zv(kkk(i0,j1)) * inc
                  enddo
                enddo
                novl = l0
c compute new faces
                l0 = 1
c compute top face of pyramid
                do j1 = 1, noe(i0)
                  kl(l0,j1) = j1 + 1
                enddo
                noel(l0) = noe(i0)
c compute lateral faces of pyramid
                do j1 = 1, noe(i0)-1
                  l0 = l0 + 1
                  kl(l0,1) = 1
                  kl(l0,2) = j1 + 2
                  kl(l0,3) = j1 + 1
                  noel(l0) = 3
                enddo
c compute last lateral face of pyramid
                l0 = l0 + 1
                kl(l0,1) = 1
                kl(l0,2) = 2
                kl(l0,3) = noe(i0) + 1
                noel(l0) = 3
c compute pyramid's potential
                nopl = l0
                call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %            dens(1),dx,dy,dz,vpot,K2)
c compute faces of pyramidal frustums
                do ilay = 2, opti(21)
                  l0 = 1
c compute bottom face (reverse)
                  do j1 = 1, noe(i0)
                    kl(l0,j1) = (ilay-2)*noe(i0) + (noe(i0)-j1) + 2
                  enddo
                  noel(l0) = noe(i0)
c compute lateral faces
                  do j1 = 1, noe(i0)-1
                    l0 = l0 + 1
                    kl(l0,1) = (ilay-2)*noe(i0) + j1 + 1
                    kl(l0,2) = kl(l0,1) + 1
                    kl(l0,3) = ((ilay-1)*noe(i0) + j1) + 2
                    kl(l0,4) = kl(l0,3) - 1
                    noel(l0) = 4
                  enddo
c compute last lateral face
                  l0 = l0 + 1
                  kl(l0,1) = (ilay-1)*noe(i0) + 1
                  kl(l0,2) = kl(l0,1) - (noe(i0)-1)
                  kl(l0,3) = ilay*noe(i0) - (noe(i0)-1) + 1
                  kl(l0,4) = ilay*noe(i0) + 1
                  noel(l0) = 4
c compute top face (no reverse)
                  l0 = l0 + 1
                  do j1 = 1, noe(i0)
                    kl(l0,j1) = (ilay-1)*noe(i0) + j1 + 1
                  enddo
                  noel(l0) = noe(i0)
c compute pyramidal frustum's potential
                  nopl = l0
                  call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %              dens(ilay),dx,dy,dz,vpot,K2)
                enddo
              enddo
              endif
            end if
            vpot = -m(j)*vpot
c
c------------------------------------------------------------------------------
c
c mascon method
          else if (algor.eq.14.or.algor.eq.17.or.algor.eq.20) then
            do j1 = 1, noc
              dx = x(1,j) - xc(j1)
              dy = x(2,j) - yc(j1)
              dz = x(3,j) - zc(j1)
              s2 = dx*dx + dy*dy + dz*dz
              s_1 = 1.d0 / sqrt(s2)
              temp = s_1 * mc(j1)
              if (s2.ne.0) vpot = vpot + temp
            end do
            vpot = -m(j)*vpot
c
c------------------------------------------------------------------------------
c
c hybrid method
          else if (algor.eq.15.or.algor.eq.18.or.algor.eq.21
     %      .or.algor.eq.22) then
            temp = x(1,j)*x(1,j) + x(2,j)*x(2,j) + x(3,j)*x(3,j)
c newtonian method
            if (temp.ge.optr(7)) then
              if (r2.ne.0) vpot = vpot  +  m(1) / sqrt(r2)
            else
c mascon method
              if (temp.ge.optr(8)) then
                do j1 = 1, noc
                  dx = x(1,j) - xc(j1)
                  dy = x(2,j) - yc(j1)
                  dz = x(3,j) - zc(j1)
                  s2 = dx*dx + dy*dy + dz*dz
                  s_1 = 1.d0 / sqrt(s2)
                  temp = s_1 * mc(j1)
                  if (s2.ne.0) vpot = vpot + temp
                end do
c
              else
c polyhedron method
                if (opti(22).eq.0.and.opti(21).eq.1) then
                  call polyhedron2 (nov,nop,xv,yv,zv,noe,kkk,
     %              dens(opti(21)),dx,dy,dz,vpot,K2)
                else
                  do i0 = 1, nop
                    l0 = 1
c compute new vertices
                    do ilay = 1, opti(21)
                      inc = del * ilay
                      do j1 = 1, noe(i0)
                        l0 = l0 + 1
                        xl(l0) = xv(kkk(i0,j1)) * inc
                        yl(l0) = yv(kkk(i0,j1)) * inc
                        zl(l0) = zv(kkk(i0,j1)) * inc
                      enddo
                    enddo
                    novl = l0
c compute new faces
                    l0 = 1
c compute top face of pyramid
                    do j1 = 1, noe(i0)
                      kl(l0,j1) = j1 + 1
                    enddo
                    noel(l0) = noe(i0)
c compute lateral faces of pyramid
                    do j1 = 1, noe(i0)-1
                      l0 = l0 + 1
                      kl(l0,1) = 1
                      kl(l0,2) = j1 + 2
                      kl(l0,3) = j1 + 1
                      noel(l0) = 3
                    enddo
c compute last lateral face of pyramid
                    l0 = l0 + 1
                    kl(l0,1) = 1
                    kl(l0,2) = 2
                    kl(l0,3) = noe(i0) + 1
                    noel(l0) = 3
c compute pyramid's potential
                    nopl = l0
                    call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %                dens(1),dx,dy,dz,vpot,K2)
c compute faces of pyramidal frustums
                    do ilay = 2, opti(21)
                      l0 = 1
c compute bottom face (reverse)
                      do j1 = 1, noe(i0)
                        kl(l0,j1) = (ilay-2)*noe(i0) + (noe(i0)-j1) + 2
                      enddo
                      noel(l0) = noe(i0)
c compute lateral faces
                      do j1 = 1, noe(i0)-1
                        l0 = l0 + 1
                        kl(l0,1) = (ilay-2)*noe(i0) + j1 + 1
                        kl(l0,2) = kl(l0,1) + 1
                        kl(l0,3) = ((ilay-1)*noe(i0) + j1) + 2
                        kl(l0,4) = kl(l0,3) - 1
                        noel(l0) = 4
                      enddo
c compute last lateral face
                      l0 = l0 + 1
                      kl(l0,1) = (ilay-1)*noe(i0) + 1
                      kl(l0,2) = kl(l0,1) - (noe(i0)-1)
                      kl(l0,3) = ilay*noe(i0) - (noe(i0)-1) + 1
                      kl(l0,4) = ilay*noe(i0) + 1
                      noel(l0) = 4
c compute top face (no reverse)
                      l0 = l0 + 1
                      do j1 = 1, noe(i0)
                        kl(l0,j1) = (ilay-1)*noe(i0) + j1 + 1
                      enddo
                      noel(l0) = noe(i0)
c compute pyramidal frustum's potential
                      nopl = l0
                      call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %                  dens(ilay),dx,dy,dz,vpot,K2)
                    enddo
                  enddo
                end if
              end if
            end if
c
            vpot = -m(j)*vpot
          end if
          pe = pe + vpot
        end if
c ##A19,195##
      end do
c
c Corrections for oblateness
      if (jcen(1).ne.0.or.jcen(2).ne.0.or.jcen(3).ne.0) then
        do j = 2, nbod
          r2 = xh(1,j)*xh(1,j) + xh(2,j)*xh(2,j) + xh(3,j)*xh(3,j)
          r_1 = 1.d0 / sqrt(r2)
          r_2 = r_1 * r_1
          r_4 = r_2 * r_2
          r_6 = r_4 * r_2
          u2 = xh(3,j) * xh(3,j) * r_2
          u4 = u2 * u2
          u6 = u4 * u2
          pe = pe + m(1) * m(j) * r_1
     %       * (jcen(1) * r_2 * (1.5d0*u2 - 0.5d0)
     %       +  jcen(2) * r_4 * (4.375d0*u4 - 3.75d0*u2 + .375d0)
     %       +  jcen(3) * r_6
     %       *(14.4375d0*u6 - 19.6875d0*u4 + 6.5625d0*u2 - .3125d0))
        end do
      end if
c
c ##A19,228##
c      e = .5d0 * ke  +  pe
      e = .5d0 * ke  +  pe + .5d0 * kr
c ##A19,228##
      l2 = sqrt(l(1)*l(1) + l(2)*l(2) + l(3)*l(3))
c
c------------------------------------------------------------------------------
c
      return	
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c     MXX_JAC.FOR    (ErikSoft   28 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates the Jacobi constant for massless particles. This assumes that
c there are only 2 massive bodies (including the central body) moving on
c circular orbits.
c
c N.B. All coordinates and velocities must be heliocentric!!
c ===
c
c------------------------------------------------------------------------------
c
      subroutine mxx_jac (jcen,nbod,nbig,m,xh,vh,jac)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig
      real*8 jcen(3),m(nbod),xh(3,nbod),vh(3,nbod)
c
c Local
      integer j,itmp(9),iflag
      real*8 x(3,NMAX),v(3,NMAX),temp,dx,dy,dz,r,d,a2,n,jac(NMAX)
      real*8 tmp2(4,NMAX)
c
c------------------------------------------------------------------------------
c
      call mco_h2b(temp,jcen,nbod,nbig,temp,m,xh,vh,x,v,tmp2,iflag,itmp)
      dx = x(1,2) - x(1,1)
      dy = x(2,2) - x(2,1)
      dz = x(3,2) - x(3,1)
      a2 = dx*dx + dy*dy + dz*dz
      n = sqrt((m(1)+m(2)) / (a2*sqrt(a2)))
c
      do j = nbig + 1, nbod
        dx = x(1,j) - x(1,1)
        dy = x(2,j) - x(2,1)
        dz = x(3,j) - x(3,1)
        r = sqrt(dx*dx + dy*dy + dz*dz)
        dx = x(1,j) - x(1,2)
        dy = x(2,j) - x(2,2)
        dz = x(3,j) - x(3,2)
        d = sqrt(dx*dx + dy*dy + dz*dz)
c
        jac(j) = .5d0*(v(1,j)*v(1,j) + v(2,j)*v(2,j) + v(3,j)*v(3,j))
     %         - m(1)/r - m(2)/d - n*(x(1,j)*v(2,j) - x(2,j)*v(1,j))
      end do
c
c------------------------------------------------------------------------------
c
      return	
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MXX_SORT.FOR    (ErikSoft 24 May 1997)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Sorts an array X, of size N, using Shell's method. Also returns an array
c INDEX that gives the original index of every item in the sorted array X.
c
c N.B. The maximum array size is 29523.
c ===
c
c------------------------------------------------------------------------------
c
      subroutine mxx_sort (n,x,index)
c
      implicit none
c
c Input/Output
      integer n,index(n)
      real*8 x(n)
c
c Local
      integer i,j,k,l,m,inc,incarr(9),iy
      real*8 y
      data incarr/1,4,13,40,121,364,1093,3280,9841/
c
c------------------------------------------------------------------------------
c
      do i = 1, n
        index(i) = i
      end do
c
      m = 0
  10  m = m + 1
      if (incarr(m).lt.n) goto 10
      m = m - 1
c
      do i = m, 1, -1
        inc = incarr(i)
        do j = 1, inc
          do k = inc, n - j, inc
            y = x(j+k)
            iy = index(j+k)
            do l = j + k - inc, j, -inc
              if (x(l).le.y) goto 20
              x(l+inc) = x(l)
              index(l+inc) = index(l)
            end do
  20        x(l+inc) = y
            index(l+inc) = iy
          end do
        end do
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MXX_SYNC.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Synchronizes the epochs of NBIG Big bodies (having a common epoch) and
c NBOD-NBIG Small bodies (possibly having differing epochs), for an 
c integration using MERCURY.
c The Small bodies are picked up in order starting with the one with epoch
c furthest from the time, TSTART, at which the main integration will begin
c producing output.
c
c N.B. The synchronization integrations use Everhart's RA15 routine.
c ---
c
c------------------------------------------------------------------------------
c
c ##A19,91##
c ##AN28,91##
c ##A35,70##
      subroutine mxx_sync (time,tstart,h0,tol,jcen,nbod,nbig,m,x,v,s,
     %  rho,rceh,stat,id,epoch,ngf,opt,ngflag,nov,nop,noc,xv,yv,zv,
     %  noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,apot,K2,AU,MSUN,
     %  idtag)
c ##A35,70##
c ##AN28,91##
c ##A19,91##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9),stat(nbod)
      real*8 time,tstart,h0,tol,jcen(3),m(nbod),x(3,nbod),v(3,nbod)
      real*8 s(3,nbod),rceh(nbod),rho(nbod),epoch(nbod),ngf(4,nbod)
      character*8 id(nbod)
c ##A19,89##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      integer algor
      real*8 optr(76)
      integer opti(90)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
c ##A19,89##
c ##AN28,92##
      real*8 K2,AU,MSUN
c ##AN28,92##
c ##A35,69##
      integer idtag(nbod)
c ##A35,69##
c
c Local
      integer j,k,l,nsml,nsofar,indx(NMAX),itemp,jtemp(NMAX)
      integer raflag,nce,ice(NMAX),jce(NMAX)
      real*8 temp,epsml(NMAX),rtemp(NMAX)
      real*8 h,hdid,tsmall,rphys(NMAX),rcrit(NMAX)
      character*8 ctemp(NMAX)
      external mfo_all
c ##A39,26## 
      real*8 chk(3,nbod)
c ##A39,26## 
c ##A43,76##
      integer lapla2(nbod)
c ##A43,76##
c
c------------------------------------------------------------------------------
c
c Reorder Small bodies by epoch so that ep(1) is furthest from TSTART
      nsml = nbod - nbig
      do j = nbig + 1, nbod
        epsml(j-nbig) = epoch(j)
      end do
      call mxx_sort (nsml,epsml,indx)
c
      if (abs(epsml(1)-tstart).lt.abs(epsml(nsml)-tstart)) then
        k = nsml + 1
        do j = 1, nsml / 2
          l = k - j
          temp = epsml(j)
          epsml(j) = epsml (l)
          epsml(l) = temp
          itemp = indx(j)
          indx(j) = indx (l)
          indx(l) = itemp
        end do
      end if
c
      do j = nbig + 1, nbod
        epoch(j) = epsml(j-nbig)
      end do
c
c Reorder the other arrays associated with each Small body
      do k = 1, 3
        do j = 1, nsml
          rtemp(j) = x(k,j+nbig)
        end do
        do j = 1, nsml
          x(k,j+nbig) = rtemp(indx(j))
        end do
        do j = 1, nsml
          rtemp(j) = v(k,j+nbig)
        end do
        do j = 1, nsml
          v(k,j+nbig) = rtemp(indx(j))
        end do
        do j = 1, nsml
          rtemp(j) = s(k,j+nbig)
        end do
        do j = 1, nsml
          s(k,j+nbig) = rtemp(indx(j))
        end do
      end do
c
      do j = 1, nsml
        rtemp(j) = m(j+nbig)
      end do
      do j = 1, nsml
        m(j+nbig) = rtemp(indx(j))
      end do
      do j = 1, nsml
        rtemp(j) = rceh(j+nbig)
      end do
      do j = 1, nsml
        rceh(j+nbig) = rtemp(indx(j))
      end do
      do j = 1, nsml
        rtemp(j) = rho(j+nbig)
      end do
      do j = 1, nsml
        rho(j+nbig) = rtemp(indx(j))
      end do
c
      do j = 1, nsml
        ctemp(j) = id(j+nbig)
        jtemp(j) = stat(j+nbig)
      end do
      do j = 1, nsml
        id(j+nbig) = ctemp(indx(j))
        stat(j+nbig) = jtemp(indx(j))
      end do
c
c Integrate Small bodies up to the same epoch
      h = h0
      tsmall = h0 * 1.d-12
      raflag = 0
c
      do j = nbig + 1, nbod
        nsofar = j - 1
        do while (abs(time-epoch(j)).gt.tsmall)
          temp = epoch(j) - time
          h = sign(max(min(abs(temp),abs(h)),tsmall),temp)
c ##A19,90##
c ##AN28,133##
c ##A35,68##
c ##A39,25## 
c ##A43,46##
          call mdt_ra15 (time,h,hdid,tol,jcen,nsofar,nbig,m,x,v,s,rphys,
     %      rcrit,ngf,stat,raflag,ngflag,opt,nce,ice,jce,mfo_all,nov,
     %      nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,
     %      apot,K2,AU,MSUN,idtag,chk,lapla2,tstart)
c ##A43,46##
c ##A39,25## 
c ##A35,68##
c ##AN28,133##
c ##A19,90##
          time = time + hdid
        end do
        raflag = 1
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c*************************************************************************
c                        DRIFT_DAN.F
c*************************************************************************
c This subroutine does the Danby and decides which vbles to use
c
c             Input:
c                 nbod          ==>  number of massive bodies (int scalar)
c                 mass          ==>  mass of bodies (real array)
c                 x0,y0,z0         ==>  initial position in jacobi coord 
c                                    (real scalar)
c                 vx0,vy0,vz0      ==>  initial position in jacobi coord 
c                                    (real scalar)
c                 dt0            ==>  time step
c             Output:
c                 x0,y0,z0         ==>  final position in jacobi coord 
c                                       (real scalars)
c                 vx0,vy0,vz0      ==>  final position in jacobi coord 
c                                       (real scalars)
c                 iflg             ==>  integer flag (zero if satisfactory)
c					      (non-zero if nonconvergence)
c
c Authors:  Hal Levison & Martin Duncan  
c Date:    2/10/93
c Last revision: April 6/93 - MD adds dt and keeps dt0 unchanged

      subroutine drift_dan(mu,x0,y0,z0,vx0,vy0,vz0,dt0,iflg)

      include 'swift.inc'

c...  Inputs Only: 
      real*8 mu,dt0

c...  Inputs and Outputs:
      real*8 x0,y0,z0
      real*8 vx0,vy0,vz0

c...  Output
      integer iflg

c...  Internals:
      real*8 x,y,z,vx,vy,vz,dt
      real*8 f,g,fdot,c1,c2
      real*8 c3,gdot
      real*8 u,alpha,fp,r0,v0s
      real*8 a,asq,en
      real*8 dm,ec,es,esq,xkep
      real*8 fchk,s,c

c----
c...  Executable code 

c...  Set dt = dt0 to be sure timestep is not altered while solving
c...  for new coords.
	dt = dt0
	iflg = 0
        r0 = sqrt(x0*x0 + y0*y0 + z0*z0)
        v0s = vx0*vx0 + vy0*vy0 + vz0*vz0
        u = x0*vx0 + y0*vy0 + z0*vz0
        alpha = 2.0*mu/r0 - v0s
        
	if (alpha.gt.0.d0) then
           a = mu/alpha
           asq = a*a
           en = sqrt(mu/(a*asq))
           ec = 1.0d0 - r0/a
           es = u/(en*asq)
	   esq = ec*ec + es*es
	   dm = dt*en - int(dt*en/TWOPI)*TWOPI
	   dt = dm/en
	   if((dm*dm .gt. 0.16d0) .or. (esq.gt.0.36d0)) goto 100

	   if(esq*dm*dm .lt. 0.0016) then

               call drift_kepmd(dm,es,ec,xkep,s,c)
	       fchk = (xkep - ec*s +es*(1.-c) - dm)

	       if(fchk*fchk .gt. DANBYB) then
		  iflg = 1
		  return
	       endif

               fp = 1. - ec*c + es*s
               f = (a/r0) * (c-1.) + 1.
               g = dt + (s-xkep)/en
               fdot = - (a/(r0*fp))*en*s
               gdot = (c-1.)/fp + 1.

               x = x0*f + vx0*g
               y = y0*f + vy0*g
               z = z0*f + vz0*g
               vx = x0*fdot + vx0*gdot
               vy = y0*fdot + vy0*gdot
               vz = z0*fdot + vz0*gdot

               x0 = x
               y0 = y
               z0 = z
               vx0 = vx
               vy0 = vy
               vz0 = vz

	       iflg = 0
	       return

	   endif

         endif
             
100      call drift_kepu(dt,r0,mu,alpha,u,fp,c1,c2,c3,iflg)

         if(iflg .eq.0) then
           f = 1.0 - (mu/r0)*c2
           g = dt - mu*c3
           fdot = -(mu/(fp*r0))*c1
           gdot = 1. - (mu/fp)*c2

           x = x0*f + vx0*g
           y = y0*f + vy0*g
           z = z0*f + vz0*g
           vx = x0*fdot + vx0*gdot
           vy = y0*fdot + vy0*gdot
           vz = z0*fdot + vz0*gdot

           x0 = x
           y0 = y
           z0 = z
           vx0 = vx
           vy0 = vy
           vz0 = vz
	endif

        return
        end   ! drift_dan
c
c********************************************************************#
c                  DRIFT_KEPMD
c********************************************************************#
c  Subroutine for solving kepler's equation in difference form for an
c  ellipse, given SMALL dm and SMALL eccentricity.  See DRIFT_DAN.F
c  for the criteria.
c  WARNING - BUILT FOR SPEED : DOES NOT CHECK HOW WELL THE ORIGINAL
c  EQUATION IS SOLVED! (CAN DO THAT IN THE CALLING ROUTINE BY
c  CHECKING HOW CLOSE (x - ec*s +es*(1.-c) - dm) IS TO ZERO.
c
c	Input:
c	    dm		==> increment in mean anomaly M (real*8 scalar)
c	    es,ec       ==> ecc. times sin and cos of E_0 (real*8 scalars)
c
c       Output:
c            x          ==> solution to Kepler's difference eqn (real*8 scalar)
c            s,c        ==> sin and cosine of x (real*8 scalars)
c

        subroutine drift_kepmd(dm,es,ec,x,s,c)

	implicit none

c...    Inputs
	real*8 dm,es,ec
	
c...	Outputs
	real*8 x,s,c

c...    Internals
	real*8 A0, A1, A2, A3, A4
        parameter(A0 = 39916800.d0, A1 = 6652800.d0, A2 = 332640.d0)
	parameter(A3 = 7920.d0, A4 = 110.d0)
	real*8 dx
	real*8 fac1,fac2,q,y
	real*8 f,fp,fpp,fppp


c...    calc initial guess for root
	fac1 = 1.d0/(1.d0 - ec)
	q = fac1*dm
	fac2 = es*es*fac1 - ec/3.d0
	x = q*(1.d0 -0.5d0*fac1*q*(es -q*fac2))

c...  excellent approx. to sin and cos of x for small x.
	y = x*x
	s = x*(A0-y*(A1-y*(A2-y*(A3-y*(A4-y)))))/A0
        c = sqrt(1.d0 - s*s)

c...    Compute better value for the root using quartic Newton method
        f = x - ec*s + es*(1.-c) - dm
        fp = 1. - ec*c + es*s
        fpp = ec*s + es*c
        fppp = ec*c - es*s
        dx = -f/fp
        dx = -f/(fp + 0.5*dx*fpp)
        dx = -f/(fp + 0.5*dx*fpp + 0.16666666666666666*dx*dx*fppp)
        x = x + dx
     
c...  excellent approx. to sin and cos of x for small x.
	y = x*x
	s = x*(A0-y*(A1-y*(A2-y*(A3-y*(A4-y)))))/A0
        c = sqrt(1.d0 - s*s)

	return
	end
c-----------------------------------------------------------------------------
c
c*************************************************************************
c                        DRIFT_KEPU.F
c*************************************************************************
c subroutine for solving kepler's equation using universal variables.
c
c             Input:
c                 dt            ==>  time step (real scalor)
c                 r0            ==>  Distance between `Sun' and paritcle
c                                     (real scalor)
c                 mu            ==>  Reduced mass of system (real scalor)
c                 alpha         ==>  energy (real scalor)
c                 u             ==>  angular momentun  (real scalor)
c             Output:
c                 fp            ==>  f' from p170  
c                                       (real scalors)
c                 c1,c2,c3      ==>  c's from p171-172
c                                       (real scalors)
c                 iflg          ==>  =0 if converged; !=0 if not
c
c Author:  Hal Levison  
c Date:    2/3/93
c Last revision: 2/3/93

      subroutine drift_kepu(dt,r0,mu,alpha,u,fp,c1,c2,c3,iflg)

      include 'swift.inc'

c...  Inputs: 
      real*8 dt,r0,mu,alpha,u

c...  Outputs:
      real*8 fp,c1,c2,c3
      integer iflg

c...  Internals:
      real*8 s,st,fo,fn

c----
c...  Executable code 

        call drift_kepu_guess(dt,r0,mu,alpha,u,s)
         
        st = s
c..     store initial guess for possible use later in
c..     laguerre's method, in case newton's method fails.

        call drift_kepu_new(s,dt,r0,mu,alpha,u,fp,c1,c2,c3,iflg)
        if(iflg.ne.0) then
           call drift_kepu_fchk(dt,r0,mu,alpha,u,st,fo)
           call drift_kepu_fchk(dt,r0,mu,alpha,u,s,fn)
           if(abs(fo).lt.abs(fn)) then
               s = st 
           endif
           call drift_kepu_lag(s,dt,r0,mu,alpha,u,fp,c1,c2,c3,iflg)
        endif

        return
        end    ! drift_kepu
c----------------------------------------------------------------------
c
c*************************************************************************
c                        DRIFT_KEPU_FCHK.F
c*************************************************************************
c Returns the value of the function f of which we are trying to find the root
c in universal variables.
c
c             Input:
c                 dt            ==>  time step (real scalar)
c                 r0            ==>  Distance between `Sun' and particle
c                                     (real scalar)
c                 mu            ==>  Reduced mass of system (real scalar)
c                 alpha         ==>  Twice the binding energy (real scalar)
c                 u             ==>  Vel. dot radial vector (real scalar)
c                 s             ==>  Approx. root of f 
c             Output:
c                 f             ==>  function value ( = 0 if O.K.) (integer)
c
c Author:  Martin Duncan  
c Date:    March 12/93
c Last revision: March 12/93

      subroutine drift_kepu_fchk(dt,r0,mu,alpha,u,s,f)

c...  Inputs: 
      real*8 dt,r0,mu,alpha,u,s

c...  Outputs:
      real*8 f

c...  Internals:
      real*8  x,c0,c1,c2,c3

c----
c...  Executable code 

        x=s*s*alpha
        call drift_kepu_stumpff(x,c0,c1,c2,c3)
        c1=c1*s
        c2 = c2*s*s
        c3 = c3*s*s*s
        f = r0*c1 + u*c2 + mu*c3 - dt

        return
        end     !   drift_kepu_fchk
c-------------------------------------------------------------------
c
c*************************************************************************
c                        DRIFT_KEPU_GUESS.F
c*************************************************************************
c Initial guess for solving kepler's equation using universal variables.
c
c             Input:
c                 dt            ==>  time step (real scalor)
c                 r0            ==>  Distance between `Sun' and paritcle
c                                     (real scalor)
c                 mu            ==>  Reduced mass of system (real scalor)
c                 alpha         ==>  energy (real scalor)
c                 u             ==>  angular momentun  (real scalor)
c             Output:
c                 s             ==>  initial guess for the value of 
c                                    universal variable
c
c Author:  Hal Levison & Martin Duncan 
c Date:    3/12/93
c Last revision: April 6/93
c Modified by JEC: 8/6/98

      subroutine drift_kepu_guess(dt,r0,mu,alpha,u,s)

      include 'swift.inc'

c...  Inputs: 
      real*8 dt,r0,mu,alpha,u

c...  Inputs and Outputs:
      real*8 s

c...  Internals:
      integer iflg
      real*8 y,sy,cy,sigma,es
      real*8 x,a
      real*8 en,ec,e

c----
c...  Executable code 

        if (alpha.gt.0.0) then 
c...       find initial guess for elliptic motion

            if( dt/r0 .le. 0.4)  then
              s = dt/r0 - (dt*dt*u)/(2.0*r0*r0*r0)
	      return
            else
              a = mu/alpha
              en = sqrt(mu/(a*a*a))
              ec = 1.0 - r0/a
              es = u/(en*a*a)
              e = sqrt(ec*ec + es*es)
              y = en*dt - es
c
              call mco_sine (y,sy,cy)
c
              sigma = dsign(1.d0,(es*cy + ec*sy))
              x = y + sigma*.85*e
              s = x/sqrt(alpha)
	    endif

        else
c...       find initial guess for hyperbolic motion.
	   call drift_kepu_p3solve(dt,r0,mu,alpha,u,s,iflg)
	   if(iflg.ne.0) then
	      s = dt/r0
	   endif
        endif

        return
        end     !   drift_kepu_guess
c-------------------------------------------------------------------
c
c*************************************************************************
c                        DRIFT_KEPU_LAG.F
c*************************************************************************
c subroutine for solving kepler's equation in universal variables.
c using LAGUERRE'S METHOD
c
c             Input:
c                 s             ==>  inital value of universal variable
c                 dt            ==>  time step (real scalor)
c                 r0            ==>  Distance between `Sun' and paritcle
c                                     (real scalor)
c                 mu            ==>  Reduced mass of system (real scalor)
c                 alpha         ==>  energy (real scalor)
c                 u             ==>  angular momentun  (real scalor)
c             Output:
c                 s             ==>  final value of universal variable
c                 fp            ==>  f' from p170  
c                                       (real scalors)
c                 c1,c2,c3      ==>  c's from p171-172
c                                       (real scalors)
c                 iflgn          ==>  =0 if converged; !=0 if not
c
c Author:  Hal Levison  
c Date:    2/3/93
c Last revision: 4/21/93

      subroutine drift_kepu_lag(s,dt,r0,mu,alpha,u,fp,c1,c2,c3,iflg)

      include 'swift.inc'

c...  Inputs: 
      real*8 s,dt,r0,mu,alpha,u

c...  Outputs:
      real*8 fp,c1,c2,c3
      integer iflg

c...  Internals:
      integer nc,ncmax
      real*8 ln
      real*8 x,fpp,ds,c0,f
      real*8 fdt

      integer NTMP
      parameter(NTMP=NLAG2+1)

c----
c...  Executable code 

c...    To get close approch needed to take lots of iterations if alpha<0
        if(alpha.lt.0.0) then
           ncmax = NLAG2
        else
           ncmax = NLAG2
        endif

        ln = 5.0
c...    start laguere's method
        do nc =0,ncmax
           x = s*s*alpha
           call drift_kepu_stumpff(x,c0,c1,c2,c3)
           c1 = c1*s 
           c2 = c2*s*s 
           c3 = c3*s*s*s
           f = r0*c1 + u*c2 + mu*c3 - dt
           fp = r0*c0 + u*c1 + mu*c2
           fpp = (-40.0*alpha + mu)*c1 + u*c0
           ds = - ln*f/(fp + dsign(1.d0,fp)*sqrt(abs((ln - 1.0)*
     &       (ln - 1.0)*fp*fp - (ln - 1.0)*ln*f*fpp)))
           s = s + ds

           fdt = f/dt

c..        quartic convergence
           if( fdt*fdt.lt.DANBYB*DANBYB) then 
             iflg = 0
             return
           endif
c...      Laguerre's method succeeded
        enddo

        iflg = 2

        return

        end    !    drift_kepu_leg
c-----------------------------------------------------------------------
c
c*************************************************************************
c                        DRIFT_KEPU_NEW.F
c*************************************************************************
c subroutine for solving kepler's equation in universal variables.
c using NEWTON'S METHOD
c
c             Input:
c                 s             ==>  inital value of universal variable
c                 dt            ==>  time step (real scalor)
c                 r0            ==>  Distance between `Sun' and paritcle
c                                     (real scalor)
c                 mu            ==>  Reduced mass of system (real scalor)
c                 alpha         ==>  energy (real scalor)
c                 u             ==>  angular momentun  (real scalor)
c             Output:
c                 s             ==>  final value of universal variable
c                 fp            ==>  f' from p170  
c                                       (real scalors)
c                 c1,c2,c3      ==>  c's from p171-172
c                                       (real scalors)
c                 iflgn          ==>  =0 if converged; !=0 if not
c
c Author:  Hal Levison  
c Date:    2/3/93
c Last revision: 4/21/93
c Modified by JEC: 31/3/98

      subroutine drift_kepu_new(s,dt,r0,mu,alpha,u,fp,c1,c2,c3,iflgn)

      include 'swift.inc'

c...  Inputs: 
      real*8 s,dt,r0,mu,alpha,u

c...  Outputs:
      real*8 fp,c1,c2,c3
      integer iflgn

c...  Internals:
      integer nc
      real*8 x,c0,ds,s2
      real*8 f,fpp,fppp,fdt

c----
c...  Executable code 

      do nc=0,6
         s2 = s * s
         x = s2*alpha
         call drift_kepu_stumpff(x,c0,c1,c2,c3)
         c1 = c1*s 
         c2 = c2*s2 
         c3 = c3*s*s2
         f = r0*c1 + u*c2 + mu*c3 - dt
         fp = r0*c0 + u*c1 + mu*c2
         fpp = (mu - r0*alpha)*c1 + u*c0
         fppp = (mu - r0*alpha)*c0 - u*alpha*c1
         ds = - f/fp
         ds = - f/(fp + .5d0*ds*fpp)
         ds = -f/(fp + .5d0*ds*fpp + ds*ds*fppp*.1666666666666667d0)
         s = s + ds
         fdt = f/dt

c..      quartic convergence
         if( fdt*fdt.lt.DANBYB*DANBYB) then 
             iflgn = 0
             return
         endif
c...     newton's method succeeded

        enddo

c..     newton's method failed
        iflgn = 1
        return

        end  ! drift_kepu_new
c----------------------------------------------------------------------
c
c*************************************************************************
c                        DRIFT_KEPU_P3SOLVE.F
c*************************************************************************
c Returns the real root of cubic often found in solving kepler
c problem in universal variables.
c
c             Input:
c                 dt            ==>  time step (real scalar)
c                 r0            ==>  Distance between `Sun' and paritcle
c                                     (real scalar)
c                 mu            ==>  Reduced mass of system (real scalar)
c                 alpha         ==>  Twice the binding energy (real scalar)
c                 u             ==>  Vel. dot radial vector (real scalar)
c             Output:
c                 s             ==>  solution of cubic eqn for the  
c                                    universal variable
c                 iflg          ==>  success flag ( = 0 if O.K.) (integer)
c
c Author:  Martin Duncan  
c Date:    March 12/93
c Last revision: March 12/93

      subroutine drift_kepu_p3solve(dt,r0,mu,alpha,u,s,iflg)

c...  Inputs: 
      real*8 dt,r0,mu,alpha,u

c...  Outputs:
      integer iflg
      real*8 s

c...  Internals:
      real*8 denom,a0,a1,a2,q,r,sq2,sq,p1,p2

c----
c...  Executable code 

	denom = (mu - alpha*r0)/6.d0
	a2 = 0.5*u/denom
	a1 = r0/denom
	a0 =-dt/denom

	q = (a1 - a2*a2/3.d0)/3.d0
	r = (a1*a2 -3.d0*a0)/6.d0 - (a2**3)/27.d0
	sq2 = q**3 + r**2

	if( sq2 .ge. 0.d0) then
	   sq = sqrt(sq2)

	   if ((r+sq) .le. 0.d0) then
	      p1 =  -(-(r + sq))**(1.d0/3.d0)
	   else
	      p1 = (r + sq)**(1.d0/3.d0)
	   endif
	   if ((r-sq) .le. 0.d0) then
	      p2 =  -(-(r - sq))**(1.d0/3.d0)
	   else
	      p2 = (r - sq)**(1.d0/3.d0)
	   endif

	   iflg = 0
	   s = p1 + p2 - a2/3.d0

	else
	   iflg = 1
	   s = 0
	endif

        return
        end     !   drift_kepu_p3solve
c-------------------------------------------------------------------
c
c*************************************************************************
c                        DRIFT_KEPU_STUMPFF.F
c*************************************************************************
c subroutine for the calculation of stumpff functions
c see Danby p.172  equations 6.9.15
c
c             Input:
c                 x             ==>  argument
c             Output:
c                 c0,c1,c2,c3   ==>  c's from p171-172
c                                       (real scalors)
c Author:  Hal Levison  
c Date:    2/3/93
c Last revision: 2/3/93
c Modified by JEC: 31/3/98
c
      subroutine drift_kepu_stumpff(x,c0,c1,c2,c3)

      include 'swift.inc'

c...  Inputs: 
      real*8 x

c...  Outputs:
      real*8 c0,c1,c2,c3

c...  Internals:
      integer n,i
      real*8 xm,x2,x3,x4,x5,x6

c----
c...  Executable code 

      n = 0
      xm = 0.1
      do while(abs(x).ge.xm)
         n = n + 1
         x = x * .25d0
      enddo
c
      x2 = x  * x
      x3 = x  * x2
      x4 = x2 * x2
      x5 = x2 * x3
      x6 = x3 * x3
c
      c2 = 1.147074559772972d-11*x6 - 2.087675698786810d-9*x5
     %   + 2.755731922398589d-7*x4  - 2.480158730158730d-5*x3
     %   + 1.388888888888889d-3*x2  - 4.166666666666667d-2*x + .5d0
c
      c3 = 7.647163731819816d-13*x6 - 1.605904383682161d-10*x5
     %   + 2.505210838544172d-8*x4  - 2.755731922398589d-6*x3
     %   + 1.984126984126984d-4*x2  - 8.333333333333333d-3*x
     %   + 1.666666666666667d-1
c
      c1 = 1. - x*c3
      c0 = 1. - x*c2
c
      if(n.ne.0) then
         do i=n,1,-1
            c3 = (c2 + c0*c3)*.25d0
            c2 = c1*c1*.5d0
            c1 = c0*c1
            c0 = 2.*c0*c0 - 1.
            x = x * 4.
          enddo
       endif

       return
       end     !   drift_kepu_stumpff
c------------------------------------------------------------------
c
c*************************************************************************
c                        DRIFT_ONE.F
c*************************************************************************
c This subroutine does the danby-type drift for one particle, using 
c appropriate vbles and redoing a drift if the accuracy is too poor 
c (as flagged by the integer iflg).
c
c             Input:
c                 nbod          ==>  number of massive bodies (int scalar)
c                 mass          ==>  mass of bodies (real array)
c                 x,y,z         ==>  initial position in jacobi coord 
c                                    (real scalar)
c                 vx,vy,vz      ==>  initial position in jacobi coord 
c                                    (real scalar)
c                 dt            ==>  time step
c             Output:
c                 x,y,z         ==>  final position in jacobi coord 
c                                       (real scalars)
c                 vx,vy,vz      ==>  final position in jacobi coord 
c                                       (real scalars)
c                 iflg          ==>  integer (zero for successful step)
c
c Authors:  Hal Levison & Martin Duncan 
c Date:    2/10/93
c Last revision: 2/10/93
c

      subroutine drift_one(mu,x,y,z,vx,vy,vz,dt,iflg)

      include 'swift.inc'

c...  Inputs Only: 
      real*8 mu,dt

c...  Inputs and Outputs:
      real*8 x,y,z
      real*8 vx,vy,vz

c...  Output
	integer iflg
	
c...  Internals:
	integer i
	real*8 dttmp

c----
c...  Executable code 

           call drift_dan(mu,x,y,z,vx,vy,vz,dt,iflg)

	   if(iflg .ne. 0) then
	    
	     do i = 1,10
	       dttmp = dt/10.d0
               call drift_dan(mu,x,y,z,vx,vy,vz,dttmp,iflg)
	       if(iflg .ne. 0) return
	     enddo

	   endif

        return
        end    ! drift_one
c-------------------------------------------------------------------
c
***********************************************************************
c                    ORBEL_FGET.F
***********************************************************************
*     PURPOSE:  Solves Kepler's eqn. for hyperbola using hybrid approach.  
*
*             Input:
*                           e ==> eccentricity anomaly. (real scalar)
*                        capn ==> hyperbola mean anomaly. (real scalar)
*             Returns:
*                  orbel_fget ==>  eccentric anomaly. (real scalar)
*
*     ALGORITHM: Based on pp. 70-72 of Fitzpatrick's book "Principles of
*           Cel. Mech. ".  Quartic convergence from Danby's book.
*     REMARKS: 
*     AUTHOR: M. Duncan 
*     DATE WRITTEN: May 11, 1992.
*     REVISIONS: 2/26/93 hfl
*     Modified by JEC
***********************************************************************

	real*8 function orbel_fget(e,capn)

      include 'swift.inc'

c...  Inputs Only: 
	real*8 e,capn

c...  Internals:
	integer i,IMAX
	real*8 tmp,x,shx,chx
	real*8 esh,ech,f,fp,fpp,fppp,dx
	PARAMETER (IMAX = 10)

c----
c...  Executable code 

c Function to solve "Kepler's eqn" for F (here called
c x) for given e and CAPN. 

c  begin with a guess proposed by Danby	
	if( capn .lt. 0.d0) then
	   tmp = -2.d0*capn/e + 1.8d0
	   x = -log(tmp)
	else
	   tmp = +2.d0*capn/e + 1.8d0
	   x = log( tmp)
	endif

	orbel_fget = x

	do i = 1,IMAX
          call mco_sinh (x,shx,chx)
	  esh = e*shx
	  ech = e*chx
	  f = esh - x - capn
c	  write(6,*) 'i,x,f : ',i,x,f
	  fp = ech - 1.d0  
	  fpp = esh 
	  fppp = ech 
	  dx = -f/fp
	  dx = -f/(fp + dx*fpp/2.d0)
	  dx = -f/(fp + dx*fpp/2.d0 + dx*dx*fppp/6.d0)
	  orbel_fget = x + dx
c   If we have converged here there's no point in going on
	  if(abs(dx) .le. TINY) RETURN
	  x = orbel_fget
	enddo	

	write(6,*) 'FGET : RETURNING WITHOUT COMPLETE CONVERGENCE' 
	return
	end   ! orbel_fget
c------------------------------------------------------------------
c
***********************************************************************
c                    ORBEL_FHYBRID.F
***********************************************************************
*     PURPOSE:  Solves Kepler's eqn. for hyperbola using hybrid approach.  
*
*             Input:
*                           e ==> eccentricity anomaly. (real scalar)
*                           n ==> hyperbola mean anomaly. (real scalar)
*             Returns:
*               orbel_fhybrid ==>  eccentric anomaly. (real scalar)
*
*     ALGORITHM: For abs(N) < 0.636*ecc -0.6 , use FLON 
*	         For larger N, uses FGET
*     REMARKS: 
*     AUTHOR: M. Duncan 
*     DATE WRITTEN: May 26,1992.
*     REVISIONS: 
*     REVISIONS: 2/26/93 hfl
***********************************************************************

	real*8 function orbel_fhybrid(e,n)

      include 'swift.inc'

c...  Inputs Only: 
	real*8 e,n

c...  Internals:
	real*8 abn
        real*8 orbel_flon,orbel_fget

c----
c...  Executable code 

	abn = n
	if(n.lt.0.d0) abn = -abn

	if(abn .lt. 0.636d0*e -0.6d0) then
	  orbel_fhybrid = orbel_flon(e,n)
	else 
	  orbel_fhybrid = orbel_fget(e,n)
	endif   

	return
	end  ! orbel_fhybrid
c-------------------------------------------------------------------
c
***********************************************************************
c                    ORBEL_FLON.F
***********************************************************************
*     PURPOSE:  Solves Kepler's eqn. for hyperbola using hybrid approach.  
*
*             Input:
*                           e ==> eccentricity anomaly. (real scalar)
*                        capn ==> hyperbola mean anomaly. (real scalar)
*             Returns:
*                  orbel_flon ==>  eccentric anomaly. (real scalar)
*
*     ALGORITHM: Uses power series for N in terms of F and Newton,s method
*     REMARKS: ONLY GOOD FOR LOW VALUES OF N (N < 0.636*e -0.6)
*     AUTHOR: M. Duncan 
*     DATE WRITTEN: May 26, 1992.
*     REVISIONS: 
***********************************************************************

	real*8 function orbel_flon(e,capn)

      include 'swift.inc'

c...  Inputs Only: 
	real*8 e,capn

c...  Internals:
	integer iflag,i,IMAX
	real*8 a,b,sq,biga,bigb
	real*8 x,x2
	real*8 f,fp,dx
	real*8 diff
	real*8 a0,a1,a3,a5,a7,a9,a11
	real*8 b1,b3,b5,b7,b9,b11
	PARAMETER (IMAX = 10)
	PARAMETER (a11 = 156.d0,a9 = 17160.d0,a7 = 1235520.d0)
	PARAMETER (a5 = 51891840.d0,a3 = 1037836800.d0)
	PARAMETER (b11 = 11.d0*a11,b9 = 9.d0*a9,b7 = 7.d0*a7)
	PARAMETER (b5 = 5.d0*a5, b3 = 3.d0*a3)

c----
c...  Executable code 


c Function to solve "Kepler's eqn" for F (here called
c x) for given e and CAPN. Only good for smallish CAPN 

	iflag = 0
	if( capn .lt. 0.d0) then
	   iflag = 1
	   capn = -capn
	endif

	a1 = 6227020800.d0 * (1.d0 - 1.d0/e)
	a0 = -6227020800.d0*capn/e
	b1 = a1

c  Set iflag nonzero if capn < 0., in which case solve for -capn
c  and change the sign of the final answer for F.
c  Begin with a reasonable guess based on solving the cubic for small F	


	a = 6.d0*(e-1.d0)/e
	b = -6.d0*capn/e
	sq = sqrt(0.25*b*b +a*a*a/27.d0)
	biga = (-0.5*b + sq)**0.3333333333333333d0
	bigb = -(+0.5*b + sq)**0.3333333333333333d0
	x = biga + bigb
c	write(6,*) 'cubic = ',x**3 +a*x +b
	orbel_flon = x
c If capn is tiny (or zero) no need to go further than cubic even for
c e =1.
	if( capn .lt. TINY) go to 100

	do i = 1,IMAX
	  x2 = x*x
	  f = a0 +x*(a1+x2*(a3+x2*(a5+x2*(a7+x2*(a9+x2*(a11+x2))))))
	  fp = b1 +x2*(b3+x2*(b5+x2*(b7+x2*(b9+x2*(b11 + 13.d0*x2)))))   
	  dx = -f/fp
c	  write(6,*) 'i,dx,x,f : '
c	  write(6,432) i,dx,x,f
432	  format(1x,i3,3(2x,1p1e22.15))
	  orbel_flon = x + dx
c   If we have converged here there's no point in going on
	  if(abs(dx) .le. TINY) go to 100
	  x = orbel_flon
	enddo	

c Abnormal return here - we've gone thru the loop 
c IMAX times without convergence
	if(iflag .eq. 1) then
	   orbel_flon = -orbel_flon
	   capn = -capn
	endif
	write(6,*) 'FLON : RETURNING WITHOUT COMPLETE CONVERGENCE' 
	  diff = e*sinh(orbel_flon) - orbel_flon - capn
	  write(6,*) 'N, F, ecc*sinh(F) - F - N : '
	  write(6,*) capn,orbel_flon,diff
	return

c  Normal return here, but check if capn was originally negative
100	if(iflag .eq. 1) then
	   orbel_flon = -orbel_flon
	   capn = -capn
	endif

	return
	end     ! orbel_flon
c
***********************************************************************
c                    ORBEL_ZGET.F
***********************************************************************
*     PURPOSE:  Solves the equivalent of Kepler's eqn. for a parabola 
*          given Q (Fitz. notation.)
*
*             Input:
*                           q ==>  parabola mean anomaly. (real scalar)
*             Returns:
*                  orbel_zget ==>  eccentric anomaly. (real scalar)
*
*     ALGORITHM: p. 70-72 of Fitzpatrick's book "Princ. of Cel. Mech."
*     REMARKS: For a parabola we can solve analytically.
*     AUTHOR: M. Duncan 
*     DATE WRITTEN: May 11, 1992.
*     REVISIONS: May 27 - corrected it for negative Q and use power
*	      series for small Q.
***********************************************************************

	real*8 function orbel_zget(q)

      include 'swift.inc'

c...  Inputs Only: 
	real*8 q

c...  Internals:
	integer iflag
	real*8 x,tmp

c----
c...  Executable code 

	iflag = 0
	if(q.lt.0.d0) then
	  iflag = 1
	  q = -q
	endif

	if (q.lt.1.d-3) then
	   orbel_zget = q*(1.d0 - (q*q/3.d0)*(1.d0 -q*q))
	else
	   x = 0.5d0*(3.d0*q + sqrt(9.d0*(q**2) +4.d0))
	   tmp = x**(1.d0/3.d0)
	   orbel_zget = tmp - 1.d0/tmp
	endif

	if(iflag .eq.1) then
           orbel_zget = -orbel_zget
	   q = -q
	endif
	
	return
	end    ! orbel_zget
c----------------------------------------------------------------------
c
c ##A4,1##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_SPL2.FOR    (ErikSoft  14 November 1999)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 2 March 2014)
c
c Given a character string STRING, of length LEN bytes, the routine finds 
c the beginnings and ends of NSUB substrings present in the original, and 
c delimited by spaces. The positions of the extremes of each substring are 
c returned in the array DELIMIT.
c Substrings are those which are separated by spaces or the = symbol.
c
c------------------------------------------------------------------------------
c
      subroutine mio_spl2 (len,string,nsub,delimit)
c
      implicit none
c
c Input/Output
c ##A19,140##
      integer len,nsub,delimit(2,1000)
c ##A19,140##
      character*1 string(len)
c
c Local
      integer j,k
      character*1 c
c
c------------------------------------------------------------------------------
c
      nsub = 0
      j = 0
      c = ' '
      delimit(1,1) = -1
c
c Find the start of string
  10  j = j + 1
      if (j.gt.len) goto 99
      c = string(j)
      if ((c.ne.'1'.and.c.ne.'2'.and.c.ne.'3'.and.c.ne.'4')
     %  .and.(c.ne.'5'.and.c.ne.'6'.and.c.ne.'7'.and.c.ne.'8')
     %  .and.(c.ne.'9'.and.c.ne.'0')) goto 10
c
c Find the end of string
      k = j
  20  k = k + 1
      if (k.gt.len) goto 30
      c = string(k)
      if ((c.eq.'1'.or.c.eq.'2'.or.c.eq.'3'.or.c.eq.'4')
     %  .or.(c.eq.'5'.or.c.eq.'6'.or.c.eq.'7'.or.c.eq.'8')
     %  .or.(c.eq.'9'.or.c.eq.'0')) goto 20
c
c Store details for this string
  30  nsub = nsub + 1
      delimit(1,nsub) = j
      delimit(2,nsub) = k - 1
c
      if (k.lt.len) then
        j = k
        goto 10
      end if
c
  99  continue
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A4,1##
c
c ##A4,4##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      REINDEX.FOR    (29 November 2013)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante)
c
c Dados os extremos de um intervalo de índices de corpos, a subrotina reindexa
c os mesmos para manter os corpos sempre dentro deste intervalo quando outros
c corpos são eliminados do sistema.
c
c------------------------------------------------------------------------------
c
      subroutine reindex (indmin,indmax,nelim,elim)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer indmin, indmax, nelim, elim(NMAX+1)
c
c Local
      integer k, indmin2, indmax2
c
c------------------------------------------------------------------------------
c
      if (indmin.le.indmax) then
        indmin2 = indmin
        indmax2 = indmax
        do k = 1, nelim
          if (elim(k).lt.indmin) then
            indmin2 = indmin2 - 1
            indmax2 = indmax2 - 1
          else if (elim(k).le.indmax) then
                 indmax2 = indmax2 - 1
          end if
        end do
        indmin = indmin2
        indmax = indmax2
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A4,4##
c
c ##A5,1##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c    MCE_STAT2.FOR    (ErikSoft   1 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 30 November 2013)
c
c Returns details of all close-encounter minima involving at least one Big
c body during a timestep. The routine estimates minima using the initial
c and final coordinates X(0),X(1) and velocities V(0),V(1) of the step, and
c the stepsize H.
c
c  ICLO, JCLO contain the indices of the objects
c  DCLO is their minimum separation
c  TCLO is the time of closest approach relative to current time
c
c The routine also checks for collisions/near misses given the physical radii 
c RPHYS, and returns the time THIT of the collision/near miss closest to the
c start of the timestep, and the identities IHIT and JHIT of the objects
c involved.
c
c  NHIT = +1 implies a collision
c         -1    "    a near miss
c
c N.B. All coordinates & velocities must be with respect to the central body!!
c ===
c------------------------------------------------------------------------------
c
      subroutine mce_stat2 (time,h,nbod,nbig,m,x0,v0,x1,v1,rce,rphys,
     %  nclo,iclo,jclo,dclo,tclo,ixvclo,jxvclo,stat,mem,lmem,opti,nbclo,
     %  bclo,aux,flagce)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,stat(nbod)
      integer nclo,iclo(CMAX),jclo(CMAX)
      integer lmem(NMESS)
      real*8 time,h,m(nbod),x0(3,nbod),v0(3,nbod)
      real*8 x1(3,nbod),v1(3,nbod),rce(nbod),rphys(nbod)
      real*8 dclo(CMAX),tclo(CMAX)
      real*8 ixvclo(6,CMAX),jxvclo(6,CMAX)
      character*80 mem(NMESS)
      integer opti(90),nbclo,bclo(nbod)
      character*1 aux(CMAX)
      integer flagce
c
c Local
      integer i,j
      real*8 d0,d1,d0t,d1t,hm1,tmp0,tmp1
      real*8 dx0,dy0,dz0,du0,dv0,dw0,dx1,dy1,dz1,du1,dv1,dw1
      real*8 xmin(NMAX),xmax(NMAX),ymin(NMAX),ymax(NMAX)
      real*8 d2min,d2ce,d2hit,temp,tmin
      integer i2,j2
c ##A17,3##
c      real*8 hill(nbod),a(nbod),rcei,rcej
c ##A17,3##
c
c------------------------------------------------------------------------------
c
      hm1 = 1.d0 / h
c
c Calculate maximum and minimum values of x and y coords for each object
      call mce_box (nbod,h,x0,v0,x1,v1,xmin,xmax,ymin,ymax)
c
c Adjust values by the maximum close-encounter radius plus a fudge factor
      do j = 2, nbod
        temp = rce(j) * 1.2d0
        xmin(j) = xmin(j)  -  temp
        xmax(j) = xmax(j)  +  temp
        ymin(j) = ymin(j)  -  temp
        ymax(j) = ymax(j)  +  temp
      end do
c
c ##A17,4##
c      if (opti(20).eq.1) then
c        call mce_hill (nbod,m,x0,v0,hill,a)
c      end if
c ##A17,4##
c
c Check for close encounters between each pair of objects
      do i = 2, nbig
        do j = i + 1, nbod
          if (   xmax(i).ge.xmin(j).and.xmax(j).ge.xmin(i)
     %      .and.ymax(i).ge.ymin(j).and.ymax(j).ge.ymin(i)
     %      .and.stat(i).ge.0.and.stat(j).ge.0) then
c
c If the X-Y boxes for this pair overlap, check circumstances more closely
            dx0 = x0(1,i) - x0(1,j)
            dy0 = x0(2,i) - x0(2,j)
            dz0 = x0(3,i) - x0(3,j)
            du0 = v0(1,i) - v0(1,j)
            dv0 = v0(2,i) - v0(2,j)
            dw0 = v0(3,i) - v0(3,j)
            d0t = (dx0*du0 + dy0*dv0 + dz0*dw0) * 2.d0
c
            dx1 = x1(1,i) - x1(1,j)
            dy1 = x1(2,i) - x1(2,j)
            dz1 = x1(3,i) - x1(3,j)
            du1 = v1(1,i) - v1(1,j)
            dv1 = v1(2,i) - v1(2,j)
            dw1 = v1(3,i) - v1(3,j)
            d1t = (dx1*du1 + dy1*dv1 + dz1*dw1) * 2.d0
c
c Estimate minimum separation during the time interval, using interpolation
            d0 = dx0*dx0 + dy0*dy0 + dz0*dz0
            d1 = dx1*dx1 + dy1*dy1 + dz1*dz1
            call mce_min (d0,d1,d0t,d1t,h,d2min,tmin)
            d2ce  = max (rce(i), rce(j))
c ##A17,5##
c            if (opti(20).eq.1) then
c              rcei = rce(i) / hill(i)
c              rcej = rce(j) / hill(j)
c              d2ce = max (rcei, rcej)
c            end if
c ##A17,5##
            d2hit = rphys(i) + rphys(j)
            d2ce   = d2ce  * d2ce
            d2hit  = d2hit * d2hit
c
c If the minimum separation qualifies as an encounter or if a collision
c is in progress, store details
            if (((d2min.le.d2ce.and.d0t*h.le.0.and.d1t*h.ge.0)
     %        .and.((i.ge.opti(4).and.i.le.opti(5))
     %        .or.(j.ge.opti(4).and.j.le.opti(5))))
     %        .or.(d2min.le.d2hit)) then
              nclo = nclo + 1
              if (nclo.le.CMAX) then
                if (d2min.le.d2hit) then
                  aux(nclo) = 'c'
                else
                  aux(nclo) = 'b'
                end if
                call bcloo (nbclo,bclo,i,nbod,i2,flagce)
                call bcloo (nbclo,bclo,j,nbod,j2,flagce)
                tclo(nclo) = tmin + time
                dclo(nclo) = sqrt (max(0.d0,d2min))
                iclo(nclo) = i2
                jclo(nclo) = j2
c
c Make sure the more massive body is listed first
                if (m(j).gt.m(i).and.j.le.nbig) then
                  iclo(nclo) = j2
                  jclo(nclo) = i2
                end if
c
c Make linear interpolation to get coordinates at time of closest approach
                tmp0 = 1.d0 + tmin*hm1
                tmp1 = -tmin*hm1
                ixvclo(1,nclo) = tmp0 * x0(1,i)  +  tmp1 * x1(1,i)
                ixvclo(2,nclo) = tmp0 * x0(2,i)  +  tmp1 * x1(2,i)
                ixvclo(3,nclo) = tmp0 * x0(3,i)  +  tmp1 * x1(3,i)
                ixvclo(4,nclo) = tmp0 * v0(1,i)  +  tmp1 * v1(1,i)
                ixvclo(5,nclo) = tmp0 * v0(2,i)  +  tmp1 * v1(2,i)
                ixvclo(6,nclo) = tmp0 * v0(3,i)  +  tmp1 * v1(3,i)
                jxvclo(1,nclo) = tmp0 * x0(1,j)  +  tmp1 * x1(1,j)
                jxvclo(2,nclo) = tmp0 * x0(2,j)  +  tmp1 * x1(2,j)
                jxvclo(3,nclo) = tmp0 * x0(3,j)  +  tmp1 * x1(3,j)
                jxvclo(4,nclo) = tmp0 * v0(1,j)  +  tmp1 * v1(1,j)
                jxvclo(5,nclo) = tmp0 * v0(2,j)  +  tmp1 * v1(2,j)
                jxvclo(6,nclo) = tmp0 * v0(3,j)  +  tmp1 * v1(3,j)
              end if
            end if
          end if
c
c Move on to the next pair of objects
        end do
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A5,1##
c
c ##A5,2##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      BCLOO.FOR    (8 December 2013)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante)
c
c Dados um vetor de índices e um índice, a subrotina verifica se esse índice
c encontra-se no vetor. Caso ele não se encontre no vetor a subrotina anexa-o
c ao final do mesmo.
c
c------------------------------------------------------------------------------
c
      subroutine bcloo (nbclo,bclo,ind,nbod,i,flagce)
c
      implicit none
c
c Input/Output
      integer nbod
      integer nbclo,bclo(nbod)
      integer ind,i
      integer flagce
c
c Local
      integer flag,k
c
c------------------------------------------------------------------------------
c
c ##A23,1##
c      if (flagce.eq.0) then
c        if (nbclo.eq.0) then
c          nbclo = 1
c          i = nbclo
c          bclo(nbclo) = ind
c        else
c          flag = 0
c          do k = 1, nbclo
c            if (ind.eq.bclo(k)) then
c              i = k
c              flag = 1
c            end if
c          end do
c          if (flag.eq.0) then
c            nbclo = nbclo + 1
c            i = nbclo
c            bclo(nbclo) = ind
c          end if
c        end if
c      else if (flagce.eq.1) then
c        i = ind - 1
c      end if
      if (flagce.eq.0) then
        if (nbclo.eq.0) then
          nbclo = nbod - 1
          do k = 1, nbclo
            bclo(k) = k + 1
          end do
        end if
      end if
      i = ind - 1
c ##A23,1##
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A5,2##
c
c ##A5,8##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_CESTORED.FOR    (ErikSoft   1 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 29 November 2013)
c
c Writes details of close encounter minima to an output file, and decides how
c to continue the integration depending upon the close-encounter option
c chosen by the user. Close encounter details are stored until either 100
c have been accumulated, or a data dump is done, at which point the stored
c encounter details are also output.
c
c For each encounter, the routine outputs the time and distance of closest
c approach, the identities of the objects involved, and the output
c variables of the objects at this time. The output variables are:
c expressed as
c  r = the radial distance
c  theta = polar angle
c  phi = azimuthal angle
c  fv = 1 / [1 + 2(ke/be)^2], where be and ke are the object's binding and
c                             kinetic energies. (Note that 0 < fv < 1).
c  vtheta = polar angle of velocity vector
c  vphi = azimuthal angle of the velocity vector
c
c------------------------------------------------------------------------------
c
c ##E5,4##
c ##E19,16##
      subroutine mio_cestored (rcen,rmax,nbod,m,nclo,iclo,jclo,opt,
     %  tclo,dclo,ixvclo,jxvclo,nstored,aux,cce,bclo,algor,optr)
c ##E19,16##
c ##E5,4##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,opt
      integer nclo,iclo(nclo),jclo(nclo),nstored
      real*8 rcen,rmax,m(nbod),tclo(nclo),dclo(nclo)
      real*8 ixvclo(6,nclo),jxvclo(6,nclo)
      character*1 aux(CMAX)
      character*107 cce(FMAX)
c ##E5,3##
      integer bclo(nbod)
c ##E5,3##
c ##E19,17##
      integer algor
      real*8 optr(76)
c ##E19,17##
c
c Local
      integer k
      real*8 rfac,fr,fv,theta,phi,vtheta,vphi
      character*8 mio_fl2c, mio_re2c
      integer nchar
c ##E19,4##
c      real*8 dmin,dmax
c ##E19,4##
c
c------------------------------------------------------------------------------
c
c Create the format list, FOUT, used when outputting the orbital elements
      if (opt.eq.1) nchar = 2
      if (opt.eq.2) nchar = 4
      if (opt.eq.3) nchar = 7
c ##E19,5##
c      dmin = rcen
c      dmax = 1.d1 * rmax
c      if (algor.ge.13) dmin = 0.1 * rcen
c
c Scaling factor (maximum possible range) for distances
c      rfac = log10 (rmax / rcen)
c      rfac = log10 (dmax / dmin)
      rfac = log10 (optr(50) / optr(49))
c ##E19,5##
c
c Store details of each new close-encounter minimum
c ##E12,14##
      do k = 1, min(nclo,CMAX)
c ##E12,14##
        nstored = nstored + 1
c
        cce(nstored)(1:1) = aux(k)(1:1)
c
        cce(nstored)(2:9) = mio_fl2c(tclo(k))
c
        cce(nstored)(10:17) =
     %  mio_re2c(dble(iclo(k)),0.d0,11239423.99d0)
c
        cce(nstored)(13:20) =
     %  mio_re2c(dble(jclo(k)),0.d0,11239423.99d0)
c
        cce(nstored)(16:23) = mio_fl2c(dclo(k))
        cce(nstored)(16+nchar:16+nchar) = cce(nstored)(23:23)
c
c ##E5,1##
c ##E19,6##
c        call mco_x2ov (rcen,rmax,m(1),m(bclo(iclo(k))),ixvclo(1,k),
c     %    ixvclo(2,k),ixvclo(3,k),ixvclo(4,k),ixvclo(5,k),ixvclo(6,k),
c     %    fr,theta,phi,fv,vtheta,vphi)
c        call mco_x2ov (dmin,dmax,m(1),m(bclo(iclo(k))),ixvclo(1,k),
c     %    ixvclo(2,k),ixvclo(3,k),ixvclo(4,k),ixvclo(5,k),ixvclo(6,k),
c     %    fr,theta,phi,fv,vtheta,vphi)
        call mco_x2ov (optr(49),optr(50),m(1),m(bclo(iclo(k))),
     %    ixvclo(1,k),ixvclo(2,k),ixvclo(3,k),ixvclo(4,k),ixvclo(5,k),
     %    ixvclo(6,k),fr,theta,phi,fv,vtheta,vphi)
c ##E19,6##
c ##E5,1##
c
        cce(nstored)(16+  nchar+1:23+  nchar+1) =
     %  mio_re2c (fr    , 0.d0, rfac)
c
        cce(nstored)(16+2*nchar+1:23+2*nchar+1) =
     %  mio_re2c (theta , 0.d0, PI)
c
        cce(nstored)(16+3*nchar+1:23+3*nchar+1) =
     %  mio_re2c (phi   , 0.d0, TWOPI)
c
        cce(nstored)(16+4*nchar+1:23+4*nchar+1) =
     %  mio_re2c (fv    , 0.d0, 1.d0)
c
        cce(nstored)(16+5*nchar+1:23+5*nchar+1) =
     %  mio_re2c (vtheta, 0.d0, PI)
c
        cce(nstored)(16+6*nchar+1:23+6*nchar+1) =
     %  mio_re2c (vphi  , 0.d0, TWOPI)
c
c ##E5,2##
c ##E19,7##
c        call mco_x2ov (rcen,rmax,m(1),m(bclo(jclo(k))),jxvclo(1,k),
c     %    jxvclo(2,k),jxvclo(3,k),jxvclo(4,k),jxvclo(5,k),jxvclo(6,k),
c     %    fr,theta,phi,fv,vtheta,vphi)
c        call mco_x2ov (dmin,dmax,m(1),m(bclo(jclo(k))),jxvclo(1,k),
c     %    jxvclo(2,k),jxvclo(3,k),jxvclo(4,k),jxvclo(5,k),jxvclo(6,k),
c     %    fr,theta,phi,fv,vtheta,vphi)
        call mco_x2ov (optr(49),optr(50),m(1),m(bclo(jclo(k))),
     %    jxvclo(1,k),jxvclo(2,k),jxvclo(3,k),jxvclo(4,k),jxvclo(5,k),
     %    jxvclo(6,k),fr,theta,phi,fv,vtheta,vphi)
c ##E19,7##
c ##E5,2##
c
        cce(nstored)(16+7*nchar+1:23+7*nchar+1) =
     %  mio_re2c (fr    , 0.d0, rfac)
c
        cce(nstored)(16+8*nchar+1:23+8*nchar+1) =
     %  mio_re2c (theta , 0.d0, PI)
c
        cce(nstored)(16+9*nchar+1:23+9*nchar+1) =
     %  mio_re2c (phi   , 0.d0, TWOPI)
c
        cce(nstored)(16+10*nchar+1:23+10*nchar+1) =
     %  mio_re2c (fv    , 0.d0, 1.d0)
c
        cce(nstored)(16+11*nchar+1:23+11*nchar+1) =
     %  mio_re2c (vtheta, 0.d0, PI)
c
        cce(nstored)(16+12*nchar+1:23+12*nchar+1) =
     %  mio_re2c (vphi  , 0.d0, TWOPI)
c
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A5,8##
c
c ##A5,12##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCE_HEADER.FOR    (ErikSoft   28 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 2 December 2013)
c
c Calculates close-approach limits RCE (in AU) and physical radii RPHYS
c (in AU) for all objects, given their masses M, coordinates X, velocities
c V, densities RHO, and close-approach limits RCEH (in Hill radii).
c
c Also calculates the changeover distance RCRIT, used by the hybrid
c symplectic integrator. RCRIT is defined to be the larger of N1*HILL and
c N2*H*VMAX, where HILL is the Hill radius, H is the timestep, VMAX is the
c largest expected velocity of any body, and N1, N2 are parameters (see
c section 4.2 of Chambers 1999, Monthly Notices, vol 304, p793-799).
c
c N.B. Designed to use heliocentric coordinates, but should be adequate using
c ===  barycentric coordinates.
c
c------------------------------------------------------------------------------
c
c ##A23,5##
c ##AN28,26##
c ##A32,22##
c ##A35,37##
      subroutine mce_header (tstart,algor,jcen,rcen,rmax,nbod,m,s,rho,
     %  id,opt,outfile,nbclo,bclo,nstored,nbig,K2,AU,MSUN,optr,idtag)
c ##A35,37##
c ##A32,22##
c ##AN28,26##
c ##A23,5##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nstored
      integer nbod,algor,opt(9)
      real*8 tstart,jcen(3),rcen,rmax,m(nbod)
      real*8 s(3,nbod),rho(nbod)
      character*8 id(nbod)
      character*80 outfile
      integer nbclo,bclo(nbod)
c ##A23,3##
      integer nbig
c ##A23,3##
c ##AN28,27##
      real*8 K2,AU,MSUN
c ##AN28,27##
c ##A32,23##
      real*8 optr(76)
c ##A32,23##
c ##A35,38##
      integer idtag(nbod)
c ##A35,38##
c
c Local
      integer j
      real*8 k_2,rhocgs,rcen_2
      character*160 header,c(NMAX)
      character*8 mio_re2c, mio_fl2c
c
c------------------------------------------------------------------------------
c
      rhocgs = AU * AU * AU * K2 / MSUN
      k_2 = 1.d0 / K2
      rcen_2 = 1.d0 / (rcen * rcen)
c
c Write list of object's identities to close-encounter output file
      header(1:8)   = mio_fl2c (tstart)
c ##A23,2##
c      header(9:16)  = mio_re2c (dble(nbclo),   0.d0, 11239423.99d0)
c      header(12:19) = mio_fl2c (m(1) * k_2)
c      header(20:27) = mio_fl2c (jcen(1) * rcen_2)
c      header(28:35) = mio_fl2c (jcen(2) * rcen_2 * rcen_2)
c      header(36:43) = mio_fl2c (jcen(3) * rcen_2 * rcen_2 * rcen_2)
c      header(44:51) = mio_fl2c (rcen)
c      header(52:59) = mio_fl2c (rmax)
c      header(60:67)  = mio_re2c (dble(nstored),   0.d0, 11239423.99d0)
      header(9:16)  = mio_re2c (dble(nbig - 1),   0.d0, 11239423.99d0)
      header(12:19) = mio_re2c (dble(nbod - nbig),0.d0, 11239423.99d0)
      header(15:22) = mio_fl2c (m(1) * k_2)
      header(23:30) = mio_fl2c (jcen(1) * rcen_2)
      header(31:38) = mio_fl2c (jcen(2) * rcen_2 * rcen_2)
      header(39:46) = mio_fl2c (jcen(3) * rcen_2 * rcen_2 * rcen_2)
c ##E19,23##
c      header(47:54) = mio_fl2c (rcen)
c      header(55:62) = mio_fl2c (rmax)
      header(47:54) = mio_fl2c (optr(49))
      header(55:62) = mio_fl2c (optr(50))
c ##E19,23##
      header(63:70)  = mio_re2c (dble(nstored),   0.d0, 11239423.99d0)
c ##A32,24##
      header(66:73) = mio_fl2c (TWOPI / optr(6))
c ##A32,24##
c ##AN28,136##
      header(74:81) = mio_fl2c (K2)
      header(82:89) = mio_fl2c (AU)
      header(90:97) = mio_fl2c (MSUN)
c ##AN28,136##
c ##A23,2##
c
      do j = 1, nbclo
c        c(j)(1:8) = mio_re2c (dble(j), 0.d0, 11239423.99d0)
        c(j)(1:8) = id(bclo(j))
        c(j)(9:16) = mio_fl2c (m(bclo(j)) * k_2)
        c(j)(17:24) = mio_fl2c (s(1,bclo(j)) * k_2)
        c(j)(25:32) = mio_fl2c (s(2,bclo(j)) * k_2)
        c(j)(33:40) = mio_fl2c (s(3,bclo(j)) * k_2)
        c(j)(41:48) = mio_fl2c (rho(bclo(j)) / rhocgs)
c ##A35,39##
        c(j)(49:56) = mio_re2c (dble(idtag(bclo(j))),   0.d0,
     %    11239423.99d0)
c ##A35,39##
      end do
c
c Write compressed output to file
c ##E9,3##
c  50  open (22, file=outfile, status='old', access='append', err=50)
c ##E9,3##
      if (nbclo.gt.0) then
c        write (22,'(2(a1),i2,a62,i1)') char(12),'a',algor,header(1:62),
c     %    opt(4)
c ##A23,4##
c ##A13,1##
c        write (22,'(2(a1),a62,i1,$)') char(12),'a',header(1:62),opt(4)
c ##A32,25##
c ##AN28,137##
c        write (22,'(2(a1),i2,a65,i1,$)') char(12),'a',algor,
c     %    header(1:65),opt(4)
c        write (22,'(2(a1),i2,a73,i1,$)') char(12),'a',algor,
c     %    header(1:73),opt(4)
        write (22,'(2(a1),i2,a97,i1,$)') char(12),'a',algor,
     %    header(1:97),opt(4)
c ##AN28,137##
c ##A32,25##
c ##A13,1##
c ##A23,4##
        do j = 1, nbclo
c ##A13,2##
c ##A35,40##
c          write (22,'(a48,$)') c(j)(1:48)
          write (22,'(a56,$)') c(j)(1:56)
c ##A35,40##
c ##A13,2##
        end do
      end if
c ##E9,4##
c      close (22)
c ##E9,4##
      nbclo = 0
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A5,12##
c
c ##A5,13##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_CEFLUSH.FOR    (ErikSoft   1 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 2 December 2013)
c
c Writes details of close encounter minima to an output file, and decides how
c to continue the integration depending upon the close-encounter option
c chosen by the user. Close encounter details are stored until either 100
c have been accumulated, or a data dump is done, at which point the stored
c encounter details are also output.
c
c For each encounter, the routine outputs the time and distance of closest
c approach, the identities of the objects involved, and the output
c variables of the objects at this time. The output variables are:
c expressed as
c  r = the radial distance
c  theta = polar angle
c  phi = azimuthal angle
c  fv = 1 / [1 + 2(ke/be)^2], where be and ke are the object's binding and
c                             kinetic energies. (Note that 0 < fv < 1).
c  vtheta = polar angle of velocity vector
c  vphi = azimuthal angle of the velocity vector
c
c------------------------------------------------------------------------------
c
      subroutine mio_ceflush (opt,outfile,nstored,c)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer opt
      integer nstored
      character*80 outfile
      character*107 c(FMAX)
c
c Local
      integer k
      integer len, nchar
c ##A13,3##
      character*8 fout
c ##A13,3##
      integer len2
c ##A13,4##
      character*7 fout2
c ##A13,4##
c
c------------------------------------------------------------------------------
c
c Create the format list, FOUT, used when outputting the orbital elements
      if (opt.eq.1) nchar = 2
      if (opt.eq.2) nchar = 4
      if (opt.eq.3) nchar = 7
c
      len = 16+13*nchar+1 - 1
c ##A13,5##
      fout(1:8) = '(a   ,$)'
c      if (len.lt.10) write (fout(3:3),'(i1)') len
      if (len.lt.100) write (fout(3:4),'(i2)') len
      if (len.ge.100) write (fout(3:5),'(i3)') len
c ##A13,5##
c
c ##A33,12##
c      len2 = 13+6*nchar - 1
c      len2 = 13+7*nchar - 1
      len2 = 16+6*nchar - 1
c ##A33,12##
c ##A13,6##
      fout2(1:7) = '(a  ,$)'
      write (fout2(3:4),'(i2)') len2
c ##A13,6##
c
c ##E9,5##
c  10  open (22, file=outfile, status='old', access='append',err=10)
c ##E9,5##
      do k = 1, nstored
c ##A22,29##
        if (c(k)(1:1).eq.'b'.or.c(k)(1:1).eq.'c'
     %    .or.c(k)(1:1).eq.'d'.or.c(k)(1:1).eq.'f') then
c ##A22,29##
c ##A13,7##
c          write (22,fout) char(12),c(k)(1:len)
          write (22,fout) c(k)(1:len)
c ##A13,7##
c ##ANO29,42##
c ##A44,9##
        else if (c(k)(1:1).eq.'e'.or.c(k)(1:1).eq.'h'
     %    .or.c(k)(1:1).eq.'p'.or.c(k)(1:1).eq.'r') then
c ##A44,9##
c ##ANO29,42##
c ##A13,8##
c               write (22,fout2) char(12),c(k)(1:len2)
               write (22,fout2) c(k)(1:len2)
c ##A13,8##
        end if
      end do
c ##E9,6##
c      close (22)
c ##E9,6##
      nstored = 0
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A5,13##
c
c ##A5,21##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_CESTORED2.FOR    (ErikSoft   1 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 9 December 2013)
c
c Writes details of close encounter minima to an output file, and decides how
c to continue the integration depending upon the close-encounter option
c chosen by the user. Close encounter details are stored until either 100
c have been accumulated, or a data dump is done, at which point the stored
c encounter details are also output.
c
c For each encounter, the routine outputs the time and distance of closest
c approach, the identities of the objects involved, and the output
c variables of the objects at this time. The output variables are:
c expressed as
c  r = the radial distance
c  theta = polar angle
c  phi = azimuthal angle
c  fv = 1 / [1 + 2(ke/be)^2], where be and ke are the object's binding and
c                             kinetic energies. (Note that 0 < fv < 1).
c  vtheta = polar angle of velocity vector
c  vphi = azimuthal angle of the velocity vector
c
c------------------------------------------------------------------------------
c
c ##E13,3##
c ##A33,6##
c ##E19,18##
      subroutine mio_cestored2 (nbod,m,jclo,opt,tclo,x,v,
     %  nstored,bclo,cce,ch,face,algor,optr)
c ##E19,18##
c ##A33,6##
c ##E13,3##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,opt
      integer jclo,nstored
c ##E13,4##
c      real*8 rcen,rmax,m(nbod),tclo
      real*8 m(nbod),tclo
c ##E13,4##
      real*8 x(3,nbod),v(3,nbod)
      character*107 cce(FMAX)
      integer bclo(nbod)
      character*1 ch
c ##A33,7##
      integer face
c ##A33,7##
c ##E19,19##
      integer algor
      real*8 optr(76)
c ##E19,19##
c
c Local
      real*8 rfac,fr,fv,theta,phi,vtheta,vphi
      character*8 mio_fl2c, mio_re2c
      integer nchar
c ##E19,8##
c      real*8 dmin,dmax
c ##E19,8##
c
c------------------------------------------------------------------------------
c
c Create the format list, FOUT, used when outputting the orbital elements
      if (opt.eq.1) nchar = 2
      if (opt.eq.2) nchar = 4
      if (opt.eq.3) nchar = 7
c ##E19,9##
c      dmin = rcen
c      dmax = 1.d1 * rmax
c      if (algor.ge.13) dmin = 0.1 * rcen
c
c Scaling factor (maximum possible range) for distances
c ##E13,5##
c      rfac = log10 (rmax / rcen)
c      rfac = log10 (HUGE / TINY)
c      rfac = log10 (dmax / dmin)
      rfac = log10 (optr(50) / optr(49))
c ##E13,5##
c ##E19,9##
c
c Store details of each new close-encounter minimum
      nstored = nstored + 1
c
      cce(nstored)(1:1) = ch
c
      cce(nstored)(2:9) = mio_fl2c(tclo)
c
      cce(nstored)(10:17) =
     %  mio_re2c(dble(jclo),0.d0,11239423.99d0)
c
c ##A33,10##
      cce(nstored)(13:20) =
     %  mio_re2c(dble(face),0.d0,11239423.99d0)
c ##A33,10##
c
c ##E13,6##
c ##E19,10##
c      call mco_x2ov (TINY,HUGE,m(1),m(bclo(jclo)),x(1,bclo(jclo)),
c     %  x(2,bclo(jclo)),x(3,bclo(jclo)),v(1,bclo(jclo)),
c     %  v(2,bclo(jclo)),v(3,bclo(jclo)),fr,theta,phi,fv,vtheta,vphi)
c      call mco_x2ov (dmin,dmax,m(1),m(bclo(jclo)),x(1,bclo(jclo)),
c     %  x(2,bclo(jclo)),x(3,bclo(jclo)),v(1,bclo(jclo)),
c     %  v(2,bclo(jclo)),v(3,bclo(jclo)),fr,theta,phi,fv,vtheta,vphi)
      call mco_x2ov (optr(49),optr(50),m(1),m(bclo(jclo)),
     %  x(1,bclo(jclo)),x(2,bclo(jclo)),x(3,bclo(jclo)),v(1,bclo(jclo)),
     %  v(2,bclo(jclo)),v(3,bclo(jclo)),fr,theta,phi,fv,vtheta,vphi)
c ##E19,10##
c ##E13,6##
c
c ##A33,11##
c      cce(nstored)(13:20) =
c     %  mio_re2c (fr    , 0.d0, rfac)
c
c      cce(nstored)(13+  nchar:20+  nchar) =
c     %  mio_re2c (theta , 0.d0, PI)
c
c      cce(nstored)(13+2*nchar:20+2*nchar) =
c     %  mio_re2c (phi   , 0.d0, TWOPI)
c
c      cce(nstored)(13+3*nchar:20+3*nchar) =
c     %  mio_re2c (fv    , 0.d0, 1.d0)
c
c      cce(nstored)(13+4*nchar:20+4*nchar) =
c     %  mio_re2c (vtheta, 0.d0, PI)
c
c      cce(nstored)(13+5*nchar:20+5*nchar) =
c     %  mio_re2c (vphi  , 0.d0, TWOPI)
c
      cce(nstored)(16:23) =
     %  mio_re2c (fr    , 0.d0, rfac)
c
      cce(nstored)(16+  nchar:23+  nchar) =
     %  mio_re2c (theta , 0.d0, PI)
c
      cce(nstored)(16+2*nchar:23+2*nchar) =
     %  mio_re2c (phi   , 0.d0, TWOPI)
c
      cce(nstored)(16+3*nchar:23+3*nchar) =
     %  mio_re2c (fv    , 0.d0, 1.d0)
c
      cce(nstored)(16+4*nchar:23+4*nchar) =
     %  mio_re2c (vtheta, 0.d0, PI)
c
      cce(nstored)(16+5*nchar:23+5*nchar) =
     %  mio_re2c (vphi  , 0.d0, TWOPI)
c ##A33,11##
c
c ##A33,8##
c      cce(nstored)(13+6*nchar:20+6*nchar) =
c     %  mio_re2c(dble(face),0.d0,11239423.99d0)
c ##A33,8##
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A5,21##
c
c ##A6,1##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c    MCE_STAT3.FOR    (ErikSoft   1 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 24 January 2014)
c
c Returns details of all close-encounter minima involving at least one Big
c body during a timestep. The routine estimates minima using the initial
c and final coordinates X(0),X(1) and velocities V(0),V(1) of the step, and
c the stepsize H.
c
c  ICLO, JCLO contain the indices of the objects
c  DCLO is their minimum separation
c  TCLO is the time of closest approach relative to current time
c
c The routine also checks for collisions/near misses given the physical radii 
c RPHYS, and returns the time THIT of the collision/near miss closest to the
c start of the timestep, and the identities IHIT and JHIT of the objects
c involved.
c
c  NHIT = +1 implies a collision
c         -1    "    a near miss
c
c N.B. All coordinates & velocities must be with respect to the central body!!
c ===
c------------------------------------------------------------------------------
c
      subroutine mce_stat3 (time,h,nbod,nbig,m,x0,v0,x1,v1,rce,rphys,
     %  nclo,iclo,jclo,dclo,tclo,ixvclo,jxvclo,stat,mem,lmem,opti,nbclo,
     %  bclo,aux,flagce,index,nbod2)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,stat(nbod)
      integer nclo,iclo(CMAX),jclo(CMAX)
      integer lmem(NMESS)
      real*8 time,h,m(nbod),x0(3,nbod),v0(3,nbod)
      real*8 x1(3,nbod),v1(3,nbod),rce(nbod),rphys(nbod)
      real*8 dclo(CMAX),tclo(CMAX)
      real*8 ixvclo(6,CMAX),jxvclo(6,CMAX)
      character*80 mem(NMESS)
      integer opti(90),nbclo,bclo(nbod)
      character*1 aux(CMAX)
      integer flagce
      integer index(NMAX)
      integer nbod2
c
c Local
      integer i,j
      real*8 d0,d1,d0t,d1t,hm1,tmp0,tmp1
      real*8 dx0,dy0,dz0,du0,dv0,dw0,dx1,dy1,dz1,du1,dv1,dw1
      real*8 xmin(NMAX),xmax(NMAX),ymin(NMAX),ymax(NMAX)
      real*8 d2min,d2ce,d2hit,temp,tmin
      integer i2,j2
c ##A17,6##
c      real*8 hill(nbod),a(nbod),rcei,rcej
c ##A17,6##
c
c------------------------------------------------------------------------------
c
      hm1 = 1.d0 / h
c
c Calculate maximum and minimum values of x and y coords for each object
      call mce_box (nbod,h,x0,v0,x1,v1,xmin,xmax,ymin,ymax)
c
c Adjust values by the maximum close-encounter radius plus a fudge factor
      do j = 2, nbod
        temp = rce(j) * 1.2d0
        xmin(j) = xmin(j)  -  temp
        xmax(j) = xmax(j)  +  temp
        ymin(j) = ymin(j)  -  temp
        ymax(j) = ymax(j)  +  temp
      end do
c
c ##A17,7##
c      if (opti(20).eq.1) then
c        call mce_hill (nbod,m,x0,v0,hill,a)
c      end if
c ##A17,7##
c
c Check for close encounters between each pair of objects
      do i = 2, nbig
        do j = i + 1, nbod
          if (   xmax(i).ge.xmin(j).and.xmax(j).ge.xmin(i)
     %      .and.ymax(i).ge.ymin(j).and.ymax(j).ge.ymin(i)
     %      .and.stat(i).ge.0.and.stat(j).ge.0) then
c
c If the X-Y boxes for this pair overlap, check circumstances more closely
            dx0 = x0(1,i) - x0(1,j)
            dy0 = x0(2,i) - x0(2,j)
            dz0 = x0(3,i) - x0(3,j)
            du0 = v0(1,i) - v0(1,j)
            dv0 = v0(2,i) - v0(2,j)
            dw0 = v0(3,i) - v0(3,j)
            d0t = (dx0*du0 + dy0*dv0 + dz0*dw0) * 2.d0
c
            dx1 = x1(1,i) - x1(1,j)
            dy1 = x1(2,i) - x1(2,j)
            dz1 = x1(3,i) - x1(3,j)
            du1 = v1(1,i) - v1(1,j)
            dv1 = v1(2,i) - v1(2,j)
            dw1 = v1(3,i) - v1(3,j)
            d1t = (dx1*du1 + dy1*dv1 + dz1*dw1) * 2.d0
c
c Estimate minimum separation during the time interval, using interpolation
            d0 = dx0*dx0 + dy0*dy0 + dz0*dz0
            d1 = dx1*dx1 + dy1*dy1 + dz1*dz1
            call mce_min (d0,d1,d0t,d1t,h,d2min,tmin)
            d2ce  = max (rce(i), rce(j))
c ##A17,8##
c            if (opti(20).eq.1) then
c              rcei = rce(i) / hill(i)
c              rcej = rce(j) / hill(j)
c              d2ce = max (rcei, rcej)
c            end if
c ##A17,8##
            d2hit = rphys(i) + rphys(j)
            d2ce   = d2ce  * d2ce
            d2hit  = d2hit * d2hit
c
c If the minimum separation qualifies as an encounter or if a collision
c is in progress, store details
            if (((d2min.le.d2ce.and.d0t*h.le.0.and.d1t*h.ge.0)
     %        .and.((index(i).ge.opti(4).and.index(i).le.opti(5))
     %        .or.(index(j).ge.opti(4).and.index(j).le.opti(5))))
     %        .or.(d2min.le.d2hit)) then
              nclo = nclo + 1
              if (nclo.le.CMAX) then
                if (d2min.le.d2hit) then
                  aux(nclo) = 'c'
                else
                  aux(nclo) = 'b'
                end if
                call bcloo (nbclo,bclo,index(i),nbod2,i2,flagce)
                call bcloo (nbclo,bclo,index(j),nbod2,j2,flagce)
                tclo(nclo) = tmin + time
                dclo(nclo) = sqrt (max(0.d0,d2min))
                iclo(nclo) = i2
                jclo(nclo) = j2
c
c Make sure the more massive body is listed first
                if (m(j).gt.m(i).and.j.le.nbig) then
                  iclo(nclo) = j2
                  jclo(nclo) = i2
                end if
c
c Make linear interpolation to get coordinates at time of closest approach
                tmp0 = 1.d0 + tmin*hm1
                tmp1 = -tmin*hm1
                ixvclo(1,nclo) = tmp0 * x0(1,i)  +  tmp1 * x1(1,i)
                ixvclo(2,nclo) = tmp0 * x0(2,i)  +  tmp1 * x1(2,i)
                ixvclo(3,nclo) = tmp0 * x0(3,i)  +  tmp1 * x1(3,i)
                ixvclo(4,nclo) = tmp0 * v0(1,i)  +  tmp1 * v1(1,i)
                ixvclo(5,nclo) = tmp0 * v0(2,i)  +  tmp1 * v1(2,i)
                ixvclo(6,nclo) = tmp0 * v0(3,i)  +  tmp1 * v1(3,i)
                jxvclo(1,nclo) = tmp0 * x0(1,j)  +  tmp1 * x1(1,j)
                jxvclo(2,nclo) = tmp0 * x0(2,j)  +  tmp1 * x1(2,j)
                jxvclo(3,nclo) = tmp0 * x0(3,j)  +  tmp1 * x1(3,j)
                jxvclo(4,nclo) = tmp0 * v0(1,j)  +  tmp1 * v1(1,j)
                jxvclo(5,nclo) = tmp0 * v0(2,j)  +  tmp1 * v1(2,j)
                jxvclo(6,nclo) = tmp0 * v0(3,j)  +  tmp1 * v1(3,j)
              end if
            end if
          end if
c
c Move on to the next pair of objects
        end do
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A6,1##
c
c ##AAR1,1##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_H2SABP.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante and A. Izidoro - 18 July 2014)
c
c Convert coordinates with respect to the central body to S(AB)-P coordinates.
c
c OBS: Para se ter uma idéia de como encontrar as equações das novas
c coordenadas veja as equações 9 e 16 da referência [2] e as equações 1 da
c referência [1] da implementação ##AAR1,n##. Sempre levando em conta o centro
c de massa do subsistema que está se considerando. Já para encontrar as
c equações dos novos momentos deve-se primeiro isolar as coordenadas antigas em
c função das novas usando as equações encontradas das novas coordenadas e
c depois usar o procedimento da função geradora descrito no apêndice da
c referência [2]. Os novos momentos podem ser encontrados na referência [1],
c equações 2.
c
c------------------------------------------------------------------------------
c
c ##A38,72##
      subroutine mco_h2sabp (time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,
     %  ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,72##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),xh(3,nbod),vh(3,nbod),x(3,nbod)
      real*8 v(3,nbod),ngf(4,nbod)
c ##A38,73##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,73##
c
c Local
      integer j
      real*8 msum,mvsum(3),temp,mbin,mbin_1,mtot_1
c
      real*8 mxsum(3),mtri,mvsum2(3)
c
c------------------------------------------------------------------------------
c
      msum = 0.d0
c
      mxsum(1) = 0.d0
      mxsum(2) = 0.d0
      mxsum(3) = 0.d0
c
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      mbin = m(1) + m(2)
      mbin_1 = 1.d0 / mbin
c
      mtri = mbin + m(3)
c
      x(1,2) = xh(1,2)
      x(2,2) = xh(2,2)
      x(3,2) = xh(3,2)
      temp = m(1) * mbin_1
      v(1,2) = temp * vh(1,2)
      v(2,2) = temp * vh(2,2)
      v(3,2) = temp * vh(3,2)
c
      do j = 4, nbod
        msum = msum + m(j)
c
        mxsum(1) = mxsum(1)  +  m(j) * xh(1,j)
        mxsum(2) = mxsum(2)  +  m(j) * xh(2,j)
        mxsum(3) = mxsum(3)  +  m(j) * xh(3,j)
c
        mvsum(1) = mvsum(1)  +  m(j) * vh(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * vh(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * vh(3,j)
      end do
c
      mtot_1 = 1.d0 / (msum + mbin)
c
      mxsum(1) = mtot_1 * (mxsum(1) + m(2)*xh(1,2))
      mxsum(2) = mtot_1 * (mxsum(2) + m(2)*xh(2,2))
      mxsum(3) = mtot_1 * (mxsum(3) + m(2)*xh(3,2))
      x(1,3) = xh(1,3)  -  mxsum(1)
      x(2,3) = xh(2,3)  -  mxsum(2)
      x(3,3) = xh(3,3)  -  mxsum(3)
      temp = 1.d0 / (msum + mtri)
      mvsum2(1) = temp * (mvsum(1) + m(2)*vh(1,2) + m(3)*vh(1,3))
      mvsum2(2) = temp * (mvsum(2) + m(2)*vh(2,2) + m(3)*vh(2,3))
      mvsum2(3) = temp * (mvsum(3) + m(2)*vh(3,2) + m(3)*vh(3,3))
      v(1,3) = vh(1,3)  -  mvsum2(1)
      v(2,3) = vh(2,3)  -  mvsum2(2)
      v(3,3) = vh(3,3)  -  mvsum2(3)
c
      mvsum(1) = mtot_1 * (mvsum(1) + m(2)*vh(1,2))
      mvsum(2) = mtot_1 * (mvsum(2) + m(2)*vh(2,2))
      mvsum(3) = mtot_1 * (mvsum(3) + m(2)*vh(3,2))
c
      temp = m(2) * mbin_1
      do j = 4, nbod
        x(1,j) = xh(1,j)  -  temp * xh(1,2)
        x(2,j) = xh(2,j)  -  temp * xh(2,2)
        x(3,j) = xh(3,j)  -  temp * xh(3,2)
        v(1,j) = vh(1,j)  -  mvsum(1)
        v(2,j) = vh(2,j)  -  mvsum(2)
        v(3,j) = vh(3,j)  -  mvsum(3)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##AAR1,1##
c
c ##AAR1,2##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_SABP2H.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante and A. Izidoro - 18 July 2014)
c
c Converts S(AB)-P coordinates to coordinates with respect to the central body.
c
c OBS: Para encontrar as equações das antigas coordenadas deve-se isolar as
c mesmas a partir das novas coordenadas (subrotina mco_h2sabp). Já para
c encontrar as equações dos antigos momentos deve-se usar as novas coordenadas
c no procedimento da função geradora descrito no apêndice da referência [2].
c
c------------------------------------------------------------------------------
c
c ##A38,75##
      subroutine mco_sabp2h (time,jcen,nbod,nbig,h,m,x,v,xh,vh,ngf,
     %  ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,75##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod),ngf(4,nbod)
c ##A38,76##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,76##
c
c Local
      integer j
      real*8 mvsum(3),temp,mbin,mbin_1,mcen_1
c
      real*8 msum,mxsum(3),temp2,temp3,mvsum2(3)
c
c------------------------------------------------------------------------------
c
      msum = 0.d0
      mxsum(1) = 0.d0
      mxsum(2) = 0.d0
      mxsum(3) = 0.d0
c
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      mbin = m(1) + m(2)
      mcen_1 = 1.d0 / m(1)
      mbin_1 = 1.d0 / mbin
c
      xh(1,2) = x(1,2)
      xh(2,2) = x(2,2)
      xh(3,2) = x(3,2)
      temp = mbin * mcen_1
      vh(1,2) = temp * v(1,2)
      vh(2,2) = temp * v(2,2)
      vh(3,2) = temp * v(3,2)
c
      do j = 4, nbod
c
        msum = msum + m(j)
        mxsum(1) = mxsum(1)  +  m(j) * x(1,j)
        mxsum(2) = mxsum(2)  +  m(j) * x(2,j)
        mxsum(3) = mxsum(3)  +  m(j) * x(3,j)
c
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
      temp = m(2) * mcen_1
      mvsum(1) = mbin_1 * mvsum(1)  +  temp * v(1,2)
      mvsum(2) = mbin_1 * mvsum(2)  +  temp * v(2,2)
      mvsum(3) = mbin_1 * mvsum(3)  +  temp * v(3,2)
c
      temp = m(2) * mbin_1
c
      temp2 = 1.d0 / (msum + mbin)
      mxsum(1) = temp2 * mxsum(1) + temp * x(1,2)
      mxsum(2) = temp2 * mxsum(2) + temp * x(2,2)
      mxsum(3) = temp2 * mxsum(3) + temp * x(3,2)
      xh(1,3) = x(1,3)  +  mxsum(1)
      xh(2,3) = x(2,3)  +  mxsum(2)
      xh(3,3) = x(3,3)  +  mxsum(3)
      temp3 = m(3) * temp2
      mvsum2(1) = mvsum(1) + temp3 * v(1,3)
      mvsum2(2) = mvsum(2) + temp3 * v(2,3)
      mvsum2(3) = mvsum(3) + temp3 * v(3,3)
      vh(1,3) = v(1,3)  +  mvsum2(1)
      vh(2,3) = v(2,3)  +  mvsum2(2)
      vh(3,3) = v(3,3)  +  mvsum2(3)
c
      do j = 4, nbod
        xh(1,j) = x(1,j)  +  temp * x(1,2)
        xh(2,j) = x(2,j)  +  temp * x(2,2)
        xh(3,j) = x(3,j)  +  temp * x(3,2)
        vh(1,j) = v(1,j)  +  mvsum(1)
        vh(2,j) = v(2,j)  +  mvsum(2)
        vh(3,j) = v(3,j)  +  mvsum(3)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##AAR1,2##
c
c ##AAR1,27##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c     MFO_SABP.FOR    (ErikSoft   2 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante and A. Izidoro - 19 July 2014)
c
c OBS: Essas equações das acelerações podem ser encontradas na referência [1],
c equações 4. Ou para se ter uma melhor idéia veja as equações 14, 15, 20 e 21
c da referência [2] (acelerações dos corpos nos integradores wide-binary e
c close-binary).
c
c------------------------------------------------------------------------------
c
      subroutine mfo_sabp (jcen,nbod,nbig,m,x,rcrit,a,stat)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod, nbig, stat(nbod)
      real*8 jcen(3), m(nbod), x(3,nbod), a(3,nbod), rcrit(nbod)
c
c Local
      integer k
      real*8 dx, dy, dz, s_1, s2, s_3, temp, tmp2, tmp3
      real*8 aobl(3,NMAX), acen(3), msum, xs(3), xsm3, xxs(3)
c
      real*8 mbin,tmp1,xs2(3),xs3(3)
c
c------------------------------------------------------------------------------
c
      mbin = m(1) + m(2)
c
c Initialize accelerations to zero
      msum = 0
      a(1,2) = 0.d0
      a(2,2) = 0.d0
      a(3,2) = 0.d0
c
      a(1,3) = 0.d0
      a(2,3) = 0.d0
      a(3,3) = 0.d0
c
      xs(1) = 0.d0
      xs(2) = 0.d0
      xs(3) = 0.d0
      xxs(1) = 0.d0
      xxs(2) = 0.d0
      xxs(3) = 0.d0
c
      do k = 4, nbod
        a(1,k) = 0.d0
        a(2,k) = 0.d0
        a(3,k) = 0.d0
        msum = msum + m(k)
        xs(1) = xs(1)  +  m(k) * x(1,k)
        xs(2) = xs(2)  +  m(k) * x(2,k)
        xs(3) = xs(3)  +  m(k) * x(3,k)
      end do
c
      temp = 1.d0 / (mbin + msum)
      xs(1) = xs(1) * temp  +  x(1,3)
      xs(2) = xs(2) * temp  +  x(2,3)
      xs(3) = xs(3) * temp  +  x(3,3)
c
      xs2(1) = xs(1) * mbin + m(2) * x(1,2)
      xs2(2) = xs(2) * mbin + m(2) * x(2,2)
      xs2(3) = xs(3) * mbin + m(2) * x(3,2)
      s2 = xs2(1) * xs2(1)  +  xs2(2) * xs2(2)  +  xs2(3) * xs2(3)
      s_1 = 1.d0 / sqrt(s2)
      xsm3 = s_1 * s_1 * s_1 
      xs2(1) = xs2(1) * xsm3
      xs2(2) = xs2(2) * xsm3
      xs2(3) = xs2(3) * xsm3
      xs3(1) = xs(1) * mbin - m(1) * x(1,2)
      xs3(2) = xs(2) * mbin - m(1) * x(2,2)
      xs3(3) = xs(3) * mbin - m(1) * x(3,2)
      s2 = xs3(1) * xs3(1)  +  xs3(2) * xs3(2)  +  xs3(3) * xs3(3)
      s_1 = 1.d0 / sqrt(s2)
      xsm3 = s_1 * s_1 * s_1 
      xs3(1) = xs3(1) * xsm3
      xs3(2) = xs3(2) * xsm3
      xs3(3) = xs3(3) * xsm3
c
c Direct terms
c      call mfo_drct (3,nbod,nbig,m,x,rcrit,a,stat)
c
c Add accelerations due to oblateness of the central body
c      if (jcen(1).ne.0.or.jcen(2).ne.0.or.jcen(3).ne.0) then
c        call mfo_obl (jcen,nbod,m,x,aobl,acen)
c        do k = 2, nbod
c          a(1,k) = a(1,k) + aobl(1,k) - acen(1)
c          a(2,k) = a(2,k) + aobl(2,k) - acen(2)
c          a(3,k) = a(3,k) + aobl(3,k) - acen(3)
c        end do
c      end if
c
c Add on terms due to the binary
      do k = 4, nbod
        dx = xs(1) - x(1,k)
        dy = xs(2) - x(2,k)
        dz = xs(3) - x(3,k)
        s2 = dx * dx  +  dy * dy  +  dz * dz
        s_1 = 1.d0 / sqrt(s2)
        s_3 = s_1 * s_1 * s_1
c
        temp = m(k) * s_3
        tmp3 = m(3) * s_3
c
        xxs(1) = xxs(1)  +  temp * dx
        xxs(2) = xxs(2)  +  temp * dy
        xxs(3) = xxs(3)  +  temp * dz
        a(1,k) = a(1,k)  +  tmp3 * dx
        a(2,k) = a(2,k)  +  tmp3 * dy
        a(3,k) = a(3,k)  +  tmp3 * dz
c
        s2 = x(1,k) * x(1,k)  +  x(2,k) * x(2,k)  +  x(3,k) * x(3,k)
        s_1 = 1.d0 / sqrt(s2)
        s_3 = s_1 * s_1 * s_1
        tmp1 = mbin * s_3
        a(1,k) = a(1,k)  +  tmp1 * x(1,k)
        a(2,k) = a(2,k)  +  tmp1 * x(2,k)
        a(3,k) = a(3,k)  +  tmp1 * x(3,k)
c
        dx = mbin * x(1,k)  +  m(2) * x(1,2)
        dy = mbin * x(2,k)  +  m(2) * x(2,2)
        dz = mbin * x(3,k)  +  m(2) * x(3,2)
        s2 = dx*dx + dy*dy + dz*dz
        s_1 = 1.d0 / sqrt(s2)
        s_3 = s_1 * s_1 * s_1
        tmp1 = mbin * mbin * m(1) * s_3
        tmp2 = mbin * m(1) * m(k) * s_3
        a(1,k) = a(1,k)  -  tmp1 * dx
        a(2,k) = a(2,k)  -  tmp1 * dy
        a(3,k) = a(3,k)  -  tmp1 * dz
        a(1,2) = a(1,2)  -  tmp2 * dx
        a(2,2) = a(2,2)  -  tmp2 * dy
        a(3,2) = a(3,2)  -  tmp2 * dz
c
        dx = mbin * x(1,k)  -  m(1) * x(1,2)
        dy = mbin * x(2,k)  -  m(1) * x(2,2)
        dz = mbin * x(3,k)  -  m(1) * x(3,2)
        s2 = dx*dx + dy*dy + dz*dz
        s_1 = 1.d0 / sqrt(s2)
        s_3 = s_1 * s_1 * s_1
        tmp1 = mbin * mbin * m(2) * s_3
        tmp2 = mbin * m(1) * m(k) * s_3
        a(1,k) = a(1,k)  -  tmp1 * dx
        a(2,k) = a(2,k)  -  tmp1 * dy
        a(3,k) = a(3,k)  -  tmp1 * dz
        a(1,2) = a(1,2)  +  tmp2 * dx
        a(2,2) = a(2,2)  +  tmp2 * dy
        a(3,2) = a(3,2)  +  tmp2 * dz
c
      end do
c
      temp = m(3) / (mbin + msum)
c
      tmp1 = mbin * mbin
      tmp2 = tmp1 * temp
      tmp3 = mbin * m(1) * m(3)
c
      do k = 4, nbod
        a(1,k) = a(1,k)-temp*xxs(1)-tmp2*(m(1)*xs2(1)+m(2)*xs3(1))
        a(2,k) = a(2,k)-temp*xxs(2)-tmp2*(m(1)*xs2(2)+m(2)*xs3(2))
        a(3,k) = a(3,k)-temp*xxs(3)-tmp2*(m(1)*xs2(3)+m(2)*xs3(3))
      end do
c
      s2 = x(1,3)*x(1,3) + x(2,3)*x(2,3) + x(3,3)*x(3,3)
      s_1 = 1.d0 / sqrt(s2)
      s_3 = s_1 * s_1 * s_1
      temp = (mbin + msum) * s_3
      a(1,3) = a(1,3)  +  temp * x(1,3)  -  xxs(1)
      a(2,3) = a(2,3)  +  temp * x(2,3)  -  xxs(2)
      a(3,3) = a(3,3)  +  temp * x(3,3)  -  xxs(3)
c
      a(1,3) = a(1,3)  -  tmp1 * (m(1) * xs2(1) + m(2) * xs3(1))
      a(2,3) = a(2,3)  -  tmp1 * (m(1) * xs2(2) + m(2) * xs3(2))
      a(3,3) = a(3,3)  -  tmp1 * (m(1) * xs2(3) + m(2) * xs3(3))
      a(1,2) = a(1,2)  -  tmp3 * (xs2(1) - xs3(1))
      a(2,2) = a(2,2)  -  tmp3 * (xs2(2) - xs3(2))
      a(3,2) = a(3,2)  -  tmp3 * (xs2(3) - xs3(3))
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##AAR1,27##
c
c ##AAR1,28##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MDT_SABP.FOR    (ErikSoft   13 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante and A. Izidoro - 20 July 2014)
c
c Integrates NBOD bodies (of which NBIG are Big) for one timestep H
c using a second-order hybrid S(AB)-P symplectic integrator. Uses
c different timesteps for the binary versus the planetary orbits.
c
c DTFLAG = 0 implies first ever call to this subroutine, 
c        = 1 implies first call since number/masses of objects changed.
c        = 2 normal call
c
c N.B. Input/output must be in S(AB)-P coordinates.
c ===
c
c------------------------------------------------------------------------------
c
c ##AAR1,29##
c ##A19,115##
c ##A22,44##
c ##E14,25##
c ##AN28,69##
c ##A35,80##
c ##A39,32## 
c ##A43,18##
      subroutine mdt_sabp (time,tstart,h0,tol,rmax,en,am,jcen,rcen,nbod,
     %  nbig,m,x,v,s,rphys,rcrit,rce,stat,id,ngf,algor,opt,dtflag,
     %  ngflag,opflag,colflag,nclo,iclo,jclo,dclo,tclo,ixvclo,jxvclo,
     %  outfile,mem,lmem,nclo2,iclo2,jclo2,dclo2,tclo2,ixvclo2,jxvclo2,
     %  nstored,nbclo,bclo,aux,cce,opti,rho,flagce,nov,nop,noc,xv,yv,zv,
     %  noe,kkk,dens,mc,xc,yc,zc,optr,apot,nelim,tcol,K2,AU,MSUN,coord,
     %  bcoord,idtag,chk,lapla2)
c ##A43,18##
c ##A39,32## 
c ##A35,80##
c ##AN28,69##
c ##E14,25##
c ##A22,44##
c ##A19,115##
c ##AAR1,29##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,stat(nbod),algor,opt(9),dtflag,ngflag,opflag
      integer colflag,lmem(NMESS),nclo,iclo(CMAX),jclo(CMAX)
      real*8 time,tstart,h0,tol,rmax,en(3),am(3),jcen(3),rcen
      real*8 m(nbod),x(3,nbod),v(3,nbod),s(3,nbod),rphys(nbod)
      real*8 rce(nbod),rcrit(nbod),ngf(4,nbod),tclo(CMAX),dclo(CMAX)
      real*8 ixvclo(6,CMAX),jxvclo(6,CMAX)
      character*80 outfile(4),mem(NMESS)
      character*8 id(nbod)
c ##AAR1,30##
      integer nclo2,iclo2(CMAX),jclo2(CMAX)
      real*8 dclo2(CMAX),tclo2(CMAX)
      real*8 ixvclo2(6,CMAX),jxvclo2(6,CMAX)
      integer nstored
      integer nbclo,bclo(nbod)
      character*1 aux(CMAX)
      character*107 cce(FMAX)
      integer opti(90)
      real*8 rho(nbod)
      integer flagce(2)
c ##AAR1,30##
c ##A19,116##
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      real*8 optr(76)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      external coord,bcoord
c ##A19,116##
c ##A22,45##
      integer nelim
c ##A22,45##
c ##E14,24##
      real*8 tcol
c ##E14,24##
c ##AN28,68##
      real*8 K2,AU,MSUN
c ##AN28,68##
c ##A35,81##
      integer idtag(nbod)
c ##A35,81##
c ##A39,19## 
      real*8 chk(3,nbod)
c ##A39,19## 
c ##A43,19##
      integer lapla2(nbod)
c ##A43,19##
c
c Local
      integer j,nce,ice(NMAX),jce(NMAX),ce(NMAX),iflag,isub,nsub
      real*8 a(3,NMAX),hby2,hrec,x0(3,NMAX),v0(3,NMAX),mvsum(3),temp
      real*8 mbin,hbin,gmbin,hsub,tmp0,tmp1,tmp2,abin,amin
c
      real*8 msum,hsabp,gmsabp
c
      external mfo_hkce
c
c------------------------------------------------------------------------------
c
      save a, hrec, nsub, hsub, hbin, gmbin, hsabp, gmsabp
      nclo = 0
c ##AAR1,31##
c      nclo2 = 0
c ##AAR1,31##
      colflag = 0
      mbin = m(1) + m(2)
      gmbin = m(1) * m(1) / mbin 
c gmbin = m(1) * m(1) / mbin. Para deduzir a equação dessa constante que é usada nas subrotinas mco_x2a e drift_one com as coordenadas e velocidades do corpo 2 temos que relacionar suas coordenadas heliocêntricas com suas coordenadas em close-binary.
c Temos que a coordenada e a velocidade antigas do corpo 2 para a implementação no mercury são dadas por X(2)=x(2) e V(2)=m(1)/mbin*v(2) (essa coordenada e essa velocidade são do movimento kleperiano (2 corpos), logo qualquer outra coordenada ou velocidade com indíce diferente de 2 deve ser setada como 0) respectivamente, onde X(2) e V(2) são a coordenada e a velocidade do corpo 2 em coordenadas close-binary e x(2) e v(2) são a coordenada e a velocidade do corpo 2 em coordenadas heliocêntricas.
c Vamos ver agora como ficam na subrotina mco_x2a as equações para o raio-vetor r e o semi-eixo maior a nas novas coordenadas. O raciocício é análogo para a subrotina drift_one.
c r(2) = (x(2)*x(2)+y(2)*y(2)+z(2)*z(2))^(1/2) = (X(2)*X(2)+Y(2)*Y(2)+Z(2)*Z(2))^(1/2) => r(2) = R(2).
c v(2)^2 = v(2)x*v(2)x+v(2)y*v(2)y+v(2)z*v(2)z => v(2)^2 = (m(1)/mbin)^2*V(2)^2.
c Para a equação do semi-eixo maior a temos que o gm antigo é dado por gm = m(1) + m(2) = mbin e de V(2)=m(1)/mbin*v(2) => v(2)=mbin/m(1)*V(2). Logo,
c a(2) = gm*r(2)/(2*gm-r(2)*v(2)^2) => A(2) = mbin*R(2)/(2*mbin-R(2)*(mbin/m(1))^2*V(2)^2) = mbin*R(2)/[(mbin/m(1))^2*(2*m(1)^2/mbin-R(2)*V(2)^2)] = m(1)^2/mbin*R(2)/(2*m(1)^2/mbin-R(2)*V(2)^2) => A(2) = gmbin*R(2)/(2*gmbin-R(2)*V(2)^2).
c O raciocínio é análogo para o caso do gmbin da subrotina mdt_wb, mas setando 0 nas coordenadas e velocidades dos corpos com índice diferente de 2.
      hby2 = h0 * .5d0
c
c Set the number of binary substeps per timestep
      if (dtflag.eq.0) then
        amin = HUGE
        call mco_x2a (gmbin,x(1,2),x(2,2),x(3,2),v(1,2),v(2,2),v(3,2),
     %    abin,tmp1,tmp2)
c
        do j = 4, nbod
          temp = m(1) + m(2) + m(j)
          call mco_x2a (temp,x(1,j),x(2,j),x(3,j),v(1,j),v(2,j),v(3,j),
     %      tmp0,tmp1,tmp2)
          amin = min(amin, tmp0)
        end do
c ##AAR1,32##
        if (nbod.eq.3) amin = min(amin, abin)
c ##AAR1,32##
        nsub = int(0.5d0 + (amin/abin)**1.5)
        hsub = hby2 / nsub
        hbin = hby2 / nsub * mbin / m(1)
      end if
c
c If accelerations from previous call are not valid, calculate them now
      if (dtflag.ne.2) then
        if (dtflag.eq.0) hrec = h0
        do j = 4, nbod
          a(1,j) = 0.d0
          a(2,j) = 0.d0
          a(3,j) = 0.d0
        end do
        call mfo_drct (4,nbod,nbig,m,x,rcrit,a,stat)
        dtflag = 2
      end if
c
c Advance direct-interaction Hamiltonian for H/2
c
      msum = 0.d0
c
      do j = 4, nbod
        v(1,j) = v(1,j)  +  hby2 * a(1,j)
        v(2,j) = v(2,j)  +  hby2 * a(2,j)
        v(3,j) = v(3,j)  +  hby2 * a(3,j)
c
        msum = msum + m(j)
c
      end do
c
c Advance Binary Kepler for H/(2N), then indirect Hamiltonian for H/(2N)
      do isub = 1, nsub
        call mfo_sabp (jcen,nbod,nbig,m,x,rcrit,a,stat)
        do j = 2, nbod
          v(1,j) = v(1,j)  +  hsub * a(1,j)
          v(2,j) = v(2,j)  +  hsub * a(2,j)
          v(3,j) = v(3,j)  +  hsub * a(3,j)
        end do
        call drift_one (gmbin,x(1,2),x(2,2),x(3,2),v(1,2),v(2,2),v(3,2),
     %    hbin,iflag)
c
        gmsabp = (mbin + msum) * (mbin + msum) / (mbin + m(3) + msum)
        hsabp = hby2 / nsub * (mbin + m(3) + msum) / (mbin + msum)
        call drift_one (gmsabp,x(1,3),x(2,3),x(3,3),v(1,3),v(2,3),
     %    v(3,3),hsabp,iflag)
c
      end do
c
c Advance solar Hamiltonian for H/2
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      do j = 4, nbod
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
      temp = hby2 / mbin
      mvsum(1) = temp * mvsum(1)
      mvsum(2) = temp * mvsum(2)
      mvsum(3) = temp * mvsum(3)
      do j = 4, nbod
        x(1,j) = x(1,j) + mvsum(1)
        x(2,j) = x(2,j) + mvsum(2)
        x(3,j) = x(3,j) + mvsum(3)
      end do
c
c Save the current coordinates and velocities
c ##A38,46##
      call mco_iden (time,jcen,nbod,nbig,h0,m,x,v,x0,v0,ngf,ngflag,opt,
     %  optr,opti,K2,AU,MSUN)
c ##A38,46##
c
c Advance H_K for H
      do j = 4, nbod
        iflag = 0
        call drift_one (mbin,x(1,j),x(2,j),x(3,j),v(1,j),v(2,j),
     %    v(3,j),h0,iflag)
      end do
c
c Check whether any object separations were < R_CRIT whilst advancing H_K
      call mce_snif (h0,4,nbod,nbig,x0,v0,x,v,rcrit,ce,nce,ice,jce)
c
c If objects had close encounters, advance H_K using Bulirsch-Stoer instead
      if (nce.gt.0) then
        do j = 4, nbod
          if (ce(j).ne.0) then
            x(1,j) = x0(1,j)
            x(2,j) = x0(2,j)
            x(3,j) = x0(3,j)
            v(1,j) = v0(1,j)
            v(2,j) = v0(2,j)
            v(3,j) = v0(3,j)
          end if
        end do
c ##AAR1,33##
c ##A19,120##
c ##A22,46##
c ##E14,23##
c ##ANEO27,15##
c ##AN28,67##
c ##A35,92##
c ##A39,69##
c ##A43,81##
        call mdt_hkce (time,tstart,h0,hrec,tol,rmax,en(3),jcen,rcen,
     %    nbod,nbig,m,x,v,s,rphys,rcrit,rce,stat,id,ngf,algor,opt,
     %    ngflag,colflag,ce,nce,ice,jce,nclo,iclo,jclo,dclo,tclo,ixvclo,
     %    jxvclo,outfile,mem,lmem,mfo_hkce,nclo2,iclo2,jclo2,dclo2,
     %    tclo2,ixvclo2,jxvclo2,nstored,nbclo,bclo,aux,cce,opti,rho,
     %    flagce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,
     %    apot,nelim,tcol,0,K2,AU,MSUN,coord,bcoord,idtag,chk,lapla2)
c ##A43,81##
c ##A39,69##
c ##A35,92##
c ##AN28,67##
c ##ANEO27,15##
c ##E14,23##
c ##A22,46##
c ##A19,120##
c ##AAR1,33##
      end if
c
c Advance solar Hamiltonian for H/2
      mvsum(1) = 0.d0
      mvsum(2) = 0.d0
      mvsum(3) = 0.d0
      do j = 4, nbod
        mvsum(1) = mvsum(1)  +  m(j) * v(1,j)
        mvsum(2) = mvsum(2)  +  m(j) * v(2,j)
        mvsum(3) = mvsum(3)  +  m(j) * v(3,j)
      end do
      temp = hby2 / mbin
      mvsum(1) = temp * mvsum(1)
      mvsum(2) = temp * mvsum(2)
      mvsum(3) = temp * mvsum(3)
c
      msum = 0.d0
c
      do j = 4, nbod
        x(1,j) = x(1,j) + mvsum(1)
        x(2,j) = x(2,j) + mvsum(2)
        x(3,j) = x(3,j) + mvsum(3)
c
        msum = msum + m(j)
c
      end do
c
c Advance Binary Kepler for H/(2N), then indirect Hamiltonian for H/(2N)
      do isub = 1, nsub
c
        gmsabp = (mbin + msum) * (mbin + msum) / (mbin + m(3) + msum)
        hsabp = hby2 / nsub * (mbin + m(3) + msum) / (mbin + msum)
        call drift_one (gmsabp,x(1,3),x(2,3),x(3,3),v(1,3),v(2,3),
     %    v(3,3),hsabp,iflag)
c
        call drift_one (gmbin,x(1,2),x(2,2),x(3,2),v(1,2),v(2,2),v(3,2),
     %    hbin,iflag)
        call mfo_sabp (jcen,nbod,nbig,m,x,rcrit,a,stat)
        do j = 2, nbod
          v(1,j) = v(1,j)  +  hsub * a(1,j)
          v(2,j) = v(2,j)  +  hsub * a(2,j)
          v(3,j) = v(3,j)  +  hsub * a(3,j)
        end do
      end do
c
c Advance interaction Hamiltonian for H/2
      do j = 4, nbod
        a(1,j) = 0.d0
        a(2,j) = 0.d0
        a(3,j) = 0.d0
      end do
      call mfo_drct (4,nbod,nbig,m,x,rcrit,a,stat)
      do j = 4, nbod
        v(1,j) = v(1,j)  +  hby2 * a(1,j)
        v(2,j) = v(2,j)  +  hby2 * a(2,j)
        v(3,j) = v(3,j)  +  hby2 * a(3,j)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##AAR1,28##
c
c ##A15,5##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_SYN2H.FOR    (22 July 2014)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Converts synodic coordinates to barycentric coordinates.
c
c------------------------------------------------------------------------------
c
      subroutine mco_syn2h (i0,flag,t,nbod,m,x,v,xh,vh,n)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod
      integer i0,flag
      real*8 t,n
      real*8 m(nbod),xh(3,nbod),vh(3,nbod),x(3,nbod),v(3,nbod)
c
c Local
      real*8 a0,mbin,gm,nn,gama,sg,cg
      integer j
      real*8 a,e,i,p,n1,l,q
c
c------------------------------------------------------------------------------
c
      save a0,i
c
c      mbin = m(1) + m(2)
c      nn = 0.d0
c
c Put Cartesian coordinates into element arrays
c      do j = i0, nbod
c
c Convert to Keplerian orbital elements
c        gm = m(1) + m(j)
c        if (i0.eq.3) gm = mbin + m(j)
c ##AAR1,40##
c        if (i0.eq.4) gm = mbin + m(3) + m(j)
c ##AAR1,40##
c        call mco_x2el (gm,x(1,j),x(2,j),x(3,j),v(1,j),v(2,j),
c     %    v(3,j),q,e,i,p,n1,l)
c        a = q / (1.d0 - e)
c        i = i / DR
c        i = 90 - i
c
c If orbit is hyperbolic, use the distance rather than the semi-major axis
c        if (a.le.0) a = sqrt(x(1,j)*x(1,j)+x(2,j)*x(2,j))
c
c Calculate average mean motion n in radians/days
c        n = sqrt(gm/a**3)
c        n = sign (n, i)
c        nn = nn + n
c
        if (flag.eq.0) then
          flag = 1
c          a0 = sqrt(x(1,i0)*x(1,i0)+x(2,i0)*x(2,i0))
c          a0 = acos(x(1,i0)/a0)
c          a0 = sign (a0, n)
          gm = m(1) + m(i0)
          call mco_x2el (gm,xh(1,i0),xh(2,i0),xh(3,i0),vh(1,i0),
     %      vh(2,i0),vh(3,i0),q,e,i,p,n1,l)
          a = q / (1.d0 - e)
          i = i / DR
          i = 90 - i
        end if
c      end do
c
c      n = nn / (nbod - (i0 - 1))
      n = sign (n, i)
      a0 = sign (a0, n)
      gama = n * t + a0
      call mco_sine (gama,sg,cg)
c
c Calculate the synodic coordinates and velocities
      do j = i0, nbod
        xh(1,j) =  x(1,j) * cg - x(2,j) * sg
        xh(2,j) =  x(1,j) * sg + x(2,j) * cg
        xh(3,j) =  x(3,j)
        vh(1,j) =  (v(1,j) - n * x(2,j)) * cg -
     %    (v(2,j) + n * x(1,j)) * sg
        vh(2,j) =  (v(1,j) - n * x(2,j)) * sg +
     %    (v(2,j) + n * x(1,j)) * cg
        vh(3,j) =  v(3,j)
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A15,5##
c
c ##A16,10##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_ORBIT2X.FOR    (27 December 2014)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Converte as coordenadas e velocidades de todos os corpos para um corpo de
c referência.
c
c------------------------------------------------------------------------------
c
      subroutine mco_orbit2x (i0,nbod,nbig,x0,v0,x,v,id,oid,lmem,mem)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer i0,nbod,nbig
      real*8 x0(3,nbod),v0(3,nbod),x(3,nbod),v(3,nbod)
      character*8 id(nbod),oid(nbod-1)
      integer lmem(NMESS)
      character*80 mem(NMESS)
c
c Local
      integer i,j,k
      integer oi(nbod-1),flag(nbod)
      real*8 xsum(3),vsum(3)
c
c------------------------------------------------------------------------------
c
      do i = 1, nbod-1
        do j = 1, nbod
          if (oid(i)(1:8).eq.id(j)(1:8)) oi(i) = j
        end do
      end do
c
      k = 1
      flag(1) = 1
      do i = 1, nbod-1
        if (i+1.gt.nbig) k = 2
        do j = 2, nbod
          flag(j) = 0
        end do
        flag(i+1) = 1
        j = oi(i)
        do while (j.ne.i0)
          if (flag(j).eq.1) then
            write (23,'(/,1x,a14,1x,a8,a,a8,1x,a13)') '(first object)',
     %      id(i+1),mem(207)(1:lmem(207)),id(j),'(last object)'
            call mio_err (23,mem(81),lmem(81),mem(115),lmem(115),
     %      id(i+1),8,mem(82+k),lmem(82+k))
          end if
          flag(j) = 1
          j = oi(j-1)
        end do
      end do
c
      do i = 1, nbod-1
        xsum(1) = x0(1,i+1)
        xsum(2) = x0(2,i+1)
        xsum(3) = x0(3,i+1)
        vsum(1) = v0(1,i+1)
        vsum(2) = v0(2,i+1)
        vsum(3) = v0(3,i+1)
        j = oi(i)
        do while (j.ne.i0)
          do k = 1, 3
            xsum(k) = xsum(k) + x0(k,j)
            vsum(k) = vsum(k) + v0(k,j)
          end do
          j = oi(j-1)
        end do
        do k = 1, 3
          x(k,i+1) = xsum(k)
          v(k,i+1) = vsum(k)
        end do
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A16,10##
c
c ##A16,11##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      ORB_OI.FOR    (27 December 2014)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Cria um vetor inteiro dos corpos que são orbitados.
c
c------------------------------------------------------------------------------
c
      subroutine orb_oi (nbod,id,oid,oi)
c
      implicit none
c
c Input/Output
      integer nbod
      character*8 id(nbod),oid(nbod-1)
      integer oi(nbod-1)
c
c Local
      integer i,j
c
c------------------------------------------------------------------------------
c
      do i = 1, nbod-1
        do j = 1, nbod
          if (oid(i)(1:8).eq.id(j)(1:8)) oi(i) = j
        end do
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A16,11##
c
c ##A16,12##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      ORB_VERIF.FOR    (27 December 2014)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Verifica se existe algum corpo orbitando uma sequência de corpos incorreta.
c
c------------------------------------------------------------------------------
c
      subroutine orb_verif (i0,i,nbod,nbig,oi,id,lmem,mem)

c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer i0,i,nbod,nbig
      integer oi(nbod-1)
      character*8 id(nbod)
      integer lmem(NMESS)
      character*80 mem(NMESS)
c
c Local
      integer j,k
      integer flag(nbod)
c
c------------------------------------------------------------------------------
c
      k = 1
      flag(1) = 1
      if (i+1.gt.nbig) k = 2
      do j = 2, nbod
        flag(j) = 0
      end do
      flag(i+1) = 1
      j = oi(i)
      do while (j.ne.i0)
        if (flag(j).eq.1) then
          write (23,'(/,1x,a14,1x,a8,a,a8,1x,a13)') '(first object)',
     %    id(i+1),mem(207)(1:lmem(207)),id(j),'(last object)'
          call mio_err (23,mem(81),lmem(81),mem(115),lmem(115),
     %    id(i+1),8,mem(82+k),lmem(82+k))
        end if
        flag(j) = 1
        j = oi(j-1)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A16,12##
c
c ##A16,13##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_ORB2X.FOR    (27 December 2014)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Converte as coordenadas e velocidades de um corpo para um corpo de referência.
c
c------------------------------------------------------------------------------
c
      subroutine mco_orb2x (i0,i,nbod,oi,x0,v0,x,v)
c
      implicit none
c
c Input/Output
      integer i0,i,nbod
      integer oi(nbod-1)
      real*8 x0(3,nbod),v0(3,nbod),x(3,nbod),v(3,nbod)
c
c Local
      integer j,k
      real*8 xsum(3),vsum(3)
c
c------------------------------------------------------------------------------
c
      xsum(1) = x0(1,i+1)
      xsum(2) = x0(2,i+1)
      xsum(3) = x0(3,i+1)
      vsum(1) = v0(1,i+1)
      vsum(2) = v0(2,i+1)
      vsum(3) = v0(3,i+1)
      j = oi(i)
      do while (j.ne.i0)
        do k = 1, 3
          xsum(k) = xsum(k) + x0(k,j)
          vsum(k) = vsum(k) + v0(k,j)
        end do
        j = oi(j-1)
      end do
      do k = 1, 3
        x(k,i+1) = xsum(k)
        v(k,i+1) = vsum(k)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A16,13##
c
c ##A19,20##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      READPOLYHEDRON.FOR    (15 March 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Read vertices, faces and compute normal faces of a polyhedron.
c
c Adapted by A. Amarante (Fortran 77)
c Brian Mirtich, "Fast and Accurate Computation of Polyhedral Mass Properties,
c " journal of graphics tools, volume 1, number 1, 1996.
c
c------------------------------------------------------------------------------
c
      subroutine readPolyhedron (infile,mem,lmem,nov,nop,xv,yv,zv,noe,k,
     %  norm,w,factor)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer lmem(NMESS)
      character*80 mem(NMESS)
c ##A21,2##
      character*80 infile(6)
c ##A21,2##
      integer nov,nop,noe,k
      real*8 xv(novmax),yv(novmax),zv(novmax)
      real*8 norm(nopmax,3),w(nopmax),factor
      dimension noe(nopmax)
      dimension k(nopmax,noed)
c
c Local
      logical test
      integer i,j,l
      character*80 filename
      real*8 dx1, dy1, dz1, dx2, dy2, dz2, nx, ny, nz, len
      integer lim(2,1000),nsub
      character*15000 string
      character*80 c80
      character*5 c5
      integer lineno
      integer flag
c
c------------------------------------------------------------------------------
c
      do j = 1, 80
        filename(j:j) = ' '
      end do
c
      do j = 4, 5
        filename = infile(j)
        inquire (file=filename, exist=test)
        if (.not.test) call mio_err (6,mem(81),lmem(81),mem(88),
     %    lmem(88),' ',1,filename,80)

  33    open  (10+j, file=filename, status='old', err=33)
c
        lineno = 0
        if (j.eq.4) then
c lê os vértices do poliedro
            i = 0
c          do 21 i = 1, nov
  40        lineno = lineno + 1
c            read (10+j,'(a15000)') string
            read (10+j,'(a15000)',end=2107) string
            if (string(1:1).eq.')') goto 40
            call mio_spl (15000,string,nsub,lim)
            if (lim(1,1).eq.-1) goto 40
            i = i + 1
            if (i.gt.novmax) call mio_err (23,mem(81),lmem(81),
     %        mem(118),lmem(118),' ',1,mem(82),lmem(82))
            c80 = string(lim(1,1):lim(2,1))
            read (c80,*,err=661) xv(i)
            c80 = string(lim(1,2):lim(2,2))
            read (c80,*,err=661) yv(i)
            c80 = string(lim(1,3):lim(2,3))
            read (c80,*,err=661) zv(i)
c            read(10+j,*) xv(i),yv(i),zv(i)
            xv(i) = xv(i) * factor
            yv(i) = yv(i) * factor
            zv(i) = zv(i) * factor
c  21      continue
            goto 40
 2107       nov = i
        end if
        if (j.eq.5) then
c lê as faces e o número de vértices por face do poliedro
            flag = 0
            i = 0
c          do 32 i=1,nop
  41        lineno = lineno + 1
c            read (10+j,'(a15000)') string
            read (10+j,'(a15000)',end=2108) string
            if (string(1:1).eq.')') goto 41
            call mio_spl (15000,string,nsub,lim)
            if (lim(1,1).eq.-1) goto 41
c            c80 = string(lim(1,1):lim(2,1))
c            read (c80,*,err=662) noe(i)
            i = i + 1
            if (i.gt.nopmax) call mio_err (23,mem(81),lmem(81),
     %        mem(119),lmem(119),' ',1,mem(82),lmem(82))
            noe(i) = nsub
            do l = 1, noe(i)
c              c80 = string(lim(1,l+1):lim(2,l+1))
              c80 = string(lim(1,l):lim(2,l))
              read (c80,*,err=662) k(i,l)
c              if (k(i,l).eq.0) goto 663
              if (k(i,l).eq.0) flag = 1
            end do
c lê a primeira coluna do arquivo 15 onde é guardado o número inteiro (de até 3 algarismos (i3), por exemplo, 120) de vértices por face no vetor noe(i). OBS: advance='no' faz com que read NÃO avance para a leitura da próxima coluna, isto é, faz com que o cursor fique posicionado após a leitura da primeira coluna
c            read(10+j,'(i3)',advance='no') noe(i)
c lê as colunas restantes das linhas onde são guardados as posições dos vértices das faces na matriz k(i,j)
c            read(10+j,*) (k(i,l),l=1,noe(i))
c  32      continue
            goto 41
 2108       nop = i
c
            if (flag.eq.1) then
              do i = 1, nop
                do l = 1, noe(i)
                  k(i,l) = k(i,l) + 1
                end do
              end do
            end if
        end if
        close (10+j)
      end do
c
c compute face normal and offset w from first 3 vertices
      do i = 1, nop
        dx1 = xv(k(i,2)) - xv(k(i,1))
        dy1 = yv(k(i,2)) - yv(k(i,1))
        dz1 = zv(k(i,2)) - zv(k(i,1))
        dx2 = xv(k(i,3)) - xv(k(i,2))
        dy2 = yv(k(i,3)) - yv(k(i,2))
        dz2 = zv(k(i,3)) - zv(k(i,2))
        nx = dy1 * dz2 - dy2 * dz1
        ny = dz1 * dx2 - dz2 * dx1
        nz = dx1 * dy2 - dx2 * dy1
        len = dsqrt(nx * nx + ny * ny + nz * nz)
        norm(i,1) = nx / len
        norm(i,2) = ny / len
        norm(i,3) = nz / len
        w(i) = - norm(i,1) * xv(k(i,1))
     %         - norm(i,2) * yv(k(i,1))
     %         - norm(i,3) * zv(k(i,1))
      end do
c
c------------------------------------------------------------------------------
c
      return
c
c Error reading from the input file containing integration parameters
 661  write (c5,'(i5)') lineno
      call mio_err (23,mem(81),lmem(81),mem(99),lmem(99),c5,5,
     %  mem(144),lmem(144))
c
 662  write (c5,'(i5)') lineno
      call mio_err (23,mem(81),lmem(81),mem(99),lmem(99),c5,5,
     %  mem(145),lmem(145))
c
 663  write (c5,'(i5)') lineno
      call mio_err (23,mem(81),lmem(81),mem(146),lmem(146),c5,5,
     %  mem(145),lmem(145))
c
      end
c
c ##A19,20##
