c ##A19,31##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      CUBE.FOR    (16 March 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c A cubic function.
c
c------------------------------------------------------------------------------
c
      function cube (x)
c
      implicit none
c
c Input/Output
      real*8 x,cube
c
c------------------------------------------------------------------------------
c
      cube = x * x * x
c
c------------------------------------------------------------------------------
c
      return
      end
