     %  CubicCoeffs(1),CubicCoeffs(2),CubicCoeffs(3),CubicCoeffs(4)
      write(unit,'(1x,a,4(/,2x,e35.25))') mem(242)(1:lmem(242)),
     %  CubicCoeffs(1),CubicCoeffs(2),CubicCoeffs(3),CubicCoeffs(4)
