c ##AAR1,46##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_B2H2.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by Andre Amarante - 26 March 2016)
c
c Converts barycentric coordinates to coordinates with respect to the central
c body.
c
c------------------------------------------------------------------------------
c
      subroutine mco_b2h2 (jcen,i,nbod,nbig,h,m,x,v,xh,vh)
c
      implicit none
c
c Input/Output
      integer nbod,nbig,i
      real*8 jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod)
c
c Local
      integer j
c
c------------------------------------------------------------------------------
c
      do j = nbig, nbod
        if (j.ne.i) then
          xh(1,j) = x(1,j) - x(1,1)
          xh(2,j) = x(2,j) - x(2,1)
          xh(3,j) = x(3,j) - x(3,1)
          vh(1,j) = v(1,j) - v(1,1)
          vh(2,j) = v(2,j) - v(2,1)
          vh(3,j) = v(3,j) - v(3,1)
        end if
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##AAR1,46##
c
c ##AAR1,47##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_H2B2.FOR    (ErikSoft   2 November 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by Andre Amarante - 26 March 2016)
c
c Converts coordinates with respect to the central body to barycentric
c coordinates.
c
c------------------------------------------------------------------------------
c
      subroutine mco_h2b2 (jcen,i,nbod,nbig,h,m,xh,vh,x,v)
c
      implicit none
c
c Input/Output
      integer nbod,nbig,i
      real*8 jcen(3),h,m(nbod),xh(3,nbod),vh(3,nbod),x(3,nbod),v(3,nbod)
c
c Local
      integer j
      real*8 mtot,temp
c
c------------------------------------------------------------------------------
c
      mtot = 0.d0
      x(1,1) = 0.d0
      x(2,1) = 0.d0
      x(3,1) = 0.d0
      v(1,1) = 0.d0
      v(2,1) = 0.d0
      v(3,1) = 0.d0
c
c Calculate coordinates and velocities of the central body
      do j = nbig, nbod
        if (j.ne.i) then
          mtot = mtot  +  m(j)
          x(1,1) = x(1,1)  +  m(j) * xh(1,j)
          x(2,1) = x(2,1)  +  m(j) * xh(2,j)
          x(3,1) = x(3,1)  +  m(j) * xh(3,j)
          v(1,1) = v(1,1)  +  m(j) * vh(1,j)
          v(2,1) = v(2,1)  +  m(j) * vh(2,j)
          v(3,1) = v(3,1)  +  m(j) * vh(3,j)
        endif
      enddo
c
      temp = 1.d0 / mtot
      x(1,1) = temp * x(1,1)
      x(2,1) = temp * x(2,1)
      x(3,1) = temp * x(3,1)
      v(1,1) = temp * v(1,1)
      v(2,1) = temp * v(2,1)
      v(3,1) = temp * v(3,1)
c
c Calculate the barycentric coordinates and velocities
c      do j = 2, nbod
c        x(1,j) = xh(1,j) + x(1,1)
c        x(2,j) = xh(2,j) + x(2,1)
c        x(3,j) = xh(3,j) + x(3,1)
c        v(1,j) = vh(1,j) + v(1,1)
c        v(2,j) = vh(2,j) + v(2,1)
c        v(3,j) = vh(3,j) + v(3,1)
c      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
