c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      READBINPOL.FOR    (24 March 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Read computed potentials from binary file.
c
c------------------------------------------------------------------------------
c
      subroutine readbinpol (binfile,mem,lmem,ninfile,xi,xf,yi,yf,zi,zf,
     %  dx,dy,dz,omg,apot,a2,b2,c2)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer lmem(NMESS)
      character*80 mem(NMESS)
      character*80 binfile(101)
      integer ninfile
      real*8 xi,xf,yi,yf,zi,zf
      real*8 dx,dy,dz,omg
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      real*8 a2,b2,c2
c
c Local
      integer i,l,nchar,precision,lenin,ix,iy,iz
      integer*4 nstored,nstoredmax,nline,j,line_grid
      integer*8 line_num,nc,ne
      character*1 check,c1
      character*5 fomg
      character*80 cc
      character*104 c(1000000)
      real*8 mio_c2re2, mio_c2fl2
      real*8 xp,yp,zp
      character*80 filename
      integer itmp,ifi
      integer lim(2,1000),nsub
      real*8 test
      real*8 xmin,xmax,ymin,ymax,zmin,zmax
      integer firstflag
c
c------------------------------------------------------------------------------
c
      firstflag = 0
c
      do i = 1, 80
        filename(i:i) = ' '
      end do
c
      call mio_spl (150,binfile(101),nsub,lim)
      filename(1:lim(2,1)) = binfile(101)(lim(1,1):lim(2,1))
      itmp = lim(2,1)
c
c  LOOP  OVER  EACH  INPUT  FILE  CONTAINING  INTEGRATION  DATA
c
      do l = 1, ninfile
        i = ninfile - l + 1
        line_num = 0
        write (*,'(a13,1x,a)') 'Reading file:',binfile(i)
        call mio_spl (150,binfile(i),nsub,lim)
        filename(itmp+1:itmp+lim(2,1)-lim(1,1)+1) =
     %    binfile(i)(lim(1,1):lim(2,1))
c
        open (10, file=filename, status='old', access='sequential')
c
        do ifi = itmp+1, itmp+lim(2,1)-lim(1,1)+1
          filename(ifi:ifi) = ' '
        end do
c
c Loop over each time slice
 100    continue
        nc = 0
        line_num = line_num + 1
        read (10,'(a1)',end=900,eor=900,err=666,advance='no') check
        if (ichar(check).ne.12) goto 666
c
c------------------------------------------------------------------------------
c
c  IF  SPECIAL  INPUT,  READ  TIME,  PARAMETERS,  NAMES,  MASSES  ETC.
c
        line_num = line_num + 1
        read (10,'(i1)',end=666,eor=666,err=666,advance='no')
     %  precision
        if (precision.eq.1) then
          nchar = 3
        else if (precision.eq.2) then
               nchar = 5
             else if (precision.eq.3) then
                    nchar = 8
                  else
                    goto 666
                  end if
        fomg(1:5) = '(12a)'
        lenin = 12
        read (10,fomg,end=666,eor=666,err=666,advance='no')
     %  (cc(nc:nc),nc=1,lenin)
        line_num = line_num + nc - 1
c
        nstored = int(.5d0 + mio_c2re2(cc(1:4), 0.d0,
     %  2517630976.d0, 4))
        omg = mio_c2fl2 (cc(5:12),8)
        lenin = 25+10*nchar-1
c
        nstoredmax = 0
        do j = 1, nstored
          do nc = 1, lenin
            read (10,'(a1)',end=667,eor=667,err=666,advance='no')
     %      c(j)(nc:nc)
            if (ichar(c(j)(nc:nc)).eq.12) then
              line_num = line_num - 1
              backspace 10
              do ne = 1, line_num + nc
                read (10,'(a1)',advance='no') c1
              end do
              line_num = line_num + 1
              goto 666
            end if
          end do
          nstoredmax = nstoredmax + 1
          line_num = line_num + nc - 1
        end do
c
        nline = 0
        do j = 1, nstoredmax
          xp = mio_c2fl2 (c(j)(1:8),8)
          yp = mio_c2fl2 (c(j)(9:16),8)
          zp = mio_c2fl2 (c(j)(17:24),8)
          test = xp*xp*a2+yp*yp*b2+zp*zp*c2-1.d0
          if(.not.(((xp.ge.xi.and.xp.le.xf).and.
     %    (yp.ge.yi.and.yp.le.yf).and.
     %    (zp.ge.zi.and.zp.le.zf).and.(test.gt.0.d0
     %    .or.test.eq.-1.d0)))) then
            goto 1001
          end if
c
          if (firstflag.eq.0) then
            xmin = xp
            xmax = xp
            ymin = yp
            ymax = yp
            zmin = zp
            zmax = zp
            firstflag = 1
          end if
          if (xp.lt.xmin) xmin = xp
          if (xp.gt.xmax) xmax = xp
          if (yp.lt.ymin) ymin = yp
          if (yp.gt.ymax) ymax = yp
          if (zp.lt.zmin) zmin = zp
          if (zp.gt.zmax) zmax = zp
c
          nline = nline + 1
c
          xp = xp * dx
          ix = ceiling (dabs(xp))
          yp = yp * dy
          iy = ceiling (dabs(yp))
          zp = zp * dz
          iz = ceiling (dabs(zp))
          if (ix.eq.0) ix = 1
          if (iy.eq.0) iy = 1
          if (iz.eq.0) iz = 1
c
          if (ix.gt.nopotx) call mio_err (23,mem(81),
     %      lmem(81),mem(340),lmem(340),' ',1,mem(82),lmem(82))
          if (iy.gt.nopoty) call mio_err (23,mem(81),
     %      lmem(81),mem(341),lmem(341),' ',1,mem(82),lmem(82))
          if (iz.gt.nopotz) call mio_err (23,mem(81),
     %      lmem(81),mem(342),lmem(342),' ',1,mem(82),lmem(82))
c
          if (xp.ge.0.d0.and.yp.ge.0.d0.and.zp.ge.0.d0) then
            apot(1,ix,iy,iz,1) = mio_c2fl2 (c(j)(25+nchar:25+
     %        2*nchar-1),nchar)
            apot(1,ix,iy,iz,2) = mio_c2fl2 (c(j)(25+2*nchar:25+
     %        3*nchar-1),nchar)
            apot(1,ix,iy,iz,3) = mio_c2fl2 (c(j)(25+3*nchar:25+
     %        4*nchar-1),nchar)
          else if (xp.lt.0.d0.and.yp.ge.0.d0.and.zp.ge.0.d0) then
            apot(2,ix,iy,iz,1) = mio_c2fl2 (c(j)(25+nchar:25+
     %        2*nchar-1),nchar)
            apot(2,ix,iy,iz,2) = mio_c2fl2 (c(j)(25+2*nchar:25+
     %        3*nchar-1),nchar)
            apot(2,ix,iy,iz,3) = mio_c2fl2 (c(j)(25+3*nchar:25+
     %        4*nchar-1),nchar)
          else if (xp.lt.0.d0.and.yp.lt.0.d0.and.zp.ge.0.d0) then
            apot(3,ix,iy,iz,1) = mio_c2fl2 (c(j)(25+nchar:25+
     %        2*nchar-1),nchar)
            apot(3,ix,iy,iz,2) = mio_c2fl2 (c(j)(25+2*nchar:25+
     %        3*nchar-1),nchar)
            apot(3,ix,iy,iz,3) = mio_c2fl2 (c(j)(25+3*nchar:25+
     %        4*nchar-1),nchar)
          else if (xp.ge.0.d0.and.yp.lt.0.d0.and.zp.ge.0.d0) then
            apot(4,ix,iy,iz,1) = mio_c2fl2 (c(j)(25+nchar:25+
     %        2*nchar-1),nchar)
            apot(4,ix,iy,iz,2) = mio_c2fl2 (c(j)(25+2*nchar:25+
     %        3*nchar-1),nchar)
            apot(4,ix,iy,iz,3) = mio_c2fl2 (c(j)(25+3*nchar:25+
     %        4*nchar-1),nchar)
          else if (xp.ge.0.d0.and.yp.ge.0.d0.and.zp.lt.0.d0) then
            apot(5,ix,iy,iz,1) = mio_c2fl2 (c(j)(25+nchar:25+
     %        2*nchar-1),nchar)
            apot(5,ix,iy,iz,2) = mio_c2fl2 (c(j)(25+2*nchar:25+
     %        3*nchar-1),nchar)
            apot(5,ix,iy,iz,3) = mio_c2fl2 (c(j)(25+3*nchar:25+
     %        4*nchar-1),nchar)
          else if (xp.lt.0.d0.and.yp.ge.0.d0.and.zp.lt.0.d0) then
            apot(6,ix,iy,iz,1) = mio_c2fl2 (c(j)(25+nchar:25+
     %        2*nchar-1),nchar)
            apot(6,ix,iy,iz,2) = mio_c2fl2 (c(j)(25+2*nchar:25+
     %        3*nchar-1),nchar)
            apot(6,ix,iy,iz,3) = mio_c2fl2 (c(j)(25+3*nchar:25+
     %        4*nchar-1),nchar)
          else if (xp.lt.0.d0.and.yp.lt.0.d0.and.zp.lt.0.d0) then
            apot(7,ix,iy,iz,1) = mio_c2fl2 (c(j)(25+nchar:25+
     %        2*nchar-1),nchar)
            apot(7,ix,iy,iz,2) = mio_c2fl2 (c(j)(25+2*nchar:25+
     %        3*nchar-1),nchar)
            apot(7,ix,iy,iz,3) = mio_c2fl2 (c(j)(25+3*nchar:25+
     %        4*nchar-1),nchar)
          else if (xp.ge.0.d0.and.yp.lt.0.d0.and.zp.lt.0.d0) then
            apot(8,ix,iy,iz,1) = mio_c2fl2 (c(j)(25+nchar:25+
     %        2*nchar-1),nchar)
            apot(8,ix,iy,iz,2) = mio_c2fl2 (c(j)(25+2*nchar:25+
     %        3*nchar-1),nchar)
            apot(8,ix,iy,iz,3) = mio_c2fl2 (c(j)(25+3*nchar:25+
     %        4*nchar-1),nchar)
          end if
c
 1001     continue
        end do
        if (nline.eq.0) goto 100
        line_grid = line_grid + nline
c
c------------------------------------------------------------------------------
c
c  IF  TYPE  IS  NOT  'a'  OR  'b',  THE  INPUT  FILE  IS  CORRUPTED
c
c Move on to the next time slice
        goto 100
c
c If input file is corrupted, try to continue from next uncorrupted time slice
 667    continue
        nc = nc - 1
 666    continue
        write (*,'(2a,/,a,i11)') mem(121)(1:lmem(121)),
     %    binfile(i)(1:60),mem(104)(1:lmem(104)),line_num + nc + 1
        if (nc.ne.0) line_num = line_num - 1
        line_num = line_num + nc
        c1 = ' '
        do while (ichar(c1).ne.12)
          line_num = line_num + 1
          read (10,'(a1)',end=900,eor=900,advance='no') c1
        end do
        line_num = line_num - 1
        backspace 10
        do ne = 1, line_num
          read (10,'(a1)',advance='no') c1
        end do
c
c ##ERROR Chambers##
c para procurar o próximo pedaço de tempo não corrompido no mesmo arquivo de saída e NÃO no próximo arquivo de saída
        goto 100
c ##ERROR Chambers##
c
c Move on to the next file containing integration data
 900    continue
        close (10)
      end do
c
      xi = xmin
      xf = xmax
      yi = ymin
      yf = ymax
      zi = zmin
      zf = zmax
c
      if(line_grid.eq.0) then
        write(6,'(/,3(1x),1(a,1x),/)') 'No point potential was found.'
      end if      
c termina a execução do programa
      write (6,'(a)') 'Process completed successfully!'
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A19,143##
c
c ##A19,144##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_C2FL2.FOR    (ErikSoft   5 June 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by Andre Amarante - 16 July 2013)
c
c CHARACTER*8 ASCII string into a REAL*8 variable.
c
c N.B. X will lie in the range -1.e112 < X < 1.e112
c ===
c
c------------------------------------------------------------------------------
c
      function mio_c2fl2 (c,nchar)
c
      implicit none
c
c Input/Output
      real*8 mio_c2fl2
      character*8 c
      integer nchar
c
c Local
      real*8 x,mio_c2re2
      integer ex
c
c------------------------------------------------------------------------------
c
      x = mio_c2re2 (c(1:nchar), 0.d0, 1.d0, nchar-1)
      x = x * 2.d0 - 1.d0
      ex = mod(ichar(c(nchar:nchar)) + 256, 256) - 32 - 112
      mio_c2fl2 = x * (10.d0**dble(ex))
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A19,144##
c
c ##A19,145##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_C2RE2.FOR    (ErikSoft   5 June 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Converts an ASCII string into a REAL*8 variable X, where XMIN <= X < XMAX,
c using the new format compression:
c
c X is assumed to be made up of NCHAR base-224 digits, each one represented
c by a character in the ASCII string. Each digit is given by the ASCII
c number of the character minus 32.
c The first 32 ASCII characters (CTRL characters) are avoided, because they
c cause problems when using some operating systems.
c
c------------------------------------------------------------------------------
c
      function mio_c2re2 (c,xmin,xmax,nchar)
c
      implicit none
c
c Input/output
      integer nchar
      real*8 xmin,xmax,mio_c2re2
      character*8 c
c
c Local
      integer j
      real*8 y
c
c------------------------------------------------------------------------------
c
      y = 0
      do j = nchar, 1, -1
        y = (y + dble(mod(ichar(c(j:j)) + 256, 256) - 32)) / 224.d0
      end do
c
      mio_c2re2 = xmin  +  y * (xmax - xmin)
c
c------------------------------------------------------------------------------
c
      return
      end
c
