c ##A20,8##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_ELAPSE.FOR    (FEG   30 April 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Print out elapsed time of Mercury integration.
c
c------------------------------------------------------------------------------
c
      subroutine mio_elapse (unit,treal,tuser,tsys,outfile,nmem,mem,
     %  lmem,flag)
c
      implicit none
      include 'mercury.inc'
c
c Input/output
      integer lmem(NMESS),unit,nmem,flag
      real*8 treal,tuser,tsys
      character*80 mem(NMESS),outfile
c
c Local
      integer tday,thour,tmin
      real*8 tsec
      character*1000 string
      integer size
c
c------------------------------------------------------------------------------
c
c      write(6,'(a)') mem(nmem)(1:lmem(nmem))
c      write(unit,'(a)') mem(nmem)(1:lmem(nmem))
      string(1:6) = 'echo '''
      string(7:6+lmem(nmem)) = mem(nmem)(1:lmem(nmem))
      if (flag.eq.0) then
        string(7+lmem(nmem):11+lmem(nmem)) = ''' >> '
        call command (string(1:11+lmem(nmem))//outfile,11+lmem(nmem)+
     %    79)
      else if (flag.eq.1) then
        string(7+lmem(nmem):10+lmem(nmem)) = ''' > '
        call command (string(1:10+lmem(nmem))//outfile,10+lmem(nmem)+
     %    79)
      end if
c
      call dhms(treal,tday,thour,tmin,tsec)
c      write(6,'(a,i5,a,2(i2,a),f6.3,a)') mem(275)(1:lmem(275)),tday,
c     %  mem(278)(1:lmem(278)),thour,mem(279)(1:lmem(279)),tmin,
c     %  mem(280)(1:lmem(280)),tsec,mem(281)(1:lmem(281))
c      write(unit,'(a,i5,a,2(i2,a),f6.3,a)') mem(275)(1:lmem(275)),
c     %  tday,mem(278)(1:lmem(278)),thour,mem(279)(1:lmem(279)),tmin,
c     %  mem(280)(1:lmem(280)),tsec,mem(281)(1:lmem(281))
      string(1:6) = 'echo '''
      size = 6+lmem(275)+5+lmem(278)+4+lmem(279)+lmem(280)+6+lmem(281)
      write(string(7:size),'(a,i5,a,2(i2,a),f6.3,a)')
     %  mem(275)(1:lmem(275)),tday,mem(278)(1:lmem(278)),thour,
     %  mem(279)(1:lmem(279)),tmin,mem(280)(1:lmem(280)),tsec,
     %  mem(281)(1:lmem(281))
      string(size+1:5+size) = ''' >> '
      call command (string(1:5+size)//outfile, 5+size+79)
c
      call dhms(tuser,tday,thour,tmin,tsec)
c      write(6,'(a,i5,a,2(i2,a),f6.3,a)') mem(276)(1:lmem(276)),tday,
c     %  mem(278)(1:lmem(278)),thour,mem(279)(1:lmem(279)),tmin,
c     %  mem(280)(1:lmem(280)),tsec,mem(281)(1:lmem(281))
c      write(unit,'(a,i5,a,2(i2,a),f6.3,a)') mem(276)(1:lmem(276)),
c     %  tday,mem(278)(1:lmem(278)),thour,mem(279)(1:lmem(279)),tmin,
c     %  mem(280)(1:lmem(280)),tsec,mem(281)(1:lmem(281))
      string(1:6) = 'echo '''
      size = 6+lmem(276)+5+lmem(278)+4+lmem(279)+lmem(280)+6+lmem(281)
      write(string(7:size),'(a,i5,a,2(i2,a),f6.3,a)')
     %  mem(276)(1:lmem(276)),tday,mem(278)(1:lmem(278)),thour,
     %  mem(279)(1:lmem(279)),tmin,mem(280)(1:lmem(280)),tsec,
     %  mem(281)(1:lmem(281))
      string(size+1:5+size) = ''' >> '
      call command (string(1:5+size)//outfile, 5+size+79)
c
      call dhms(tsys,tday,thour,tmin,tsec)
c      write(6,'(a,i5,a,2(i2,a),f6.3,a)') mem(277)(1:lmem(277)),tday,
c     %  mem(278)(1:lmem(278)),thour,mem(279)(1:lmem(279)),tmin,
c     %  mem(280)(1:lmem(280)),tsec,mem(281)(1:lmem(281))
c      write(unit,'(a,i5,a,2(i2,a),f6.3,a)') mem(277)(1:lmem(277)),
c     %  tday,mem(278)(1:lmem(278)),thour,mem(279)(1:lmem(279)),tmin,
c     %  mem(280)(1:lmem(280)),tsec,mem(281)(1:lmem(281))
      string(1:6) = 'echo '''
      size = 6+lmem(277)+5+lmem(278)+4+lmem(279)+lmem(280)+6+lmem(281)
      write(string(7:size),'(a,i5,a,2(i2,a),f6.3,a)')
     %  mem(277)(1:lmem(277)),tday,mem(278)(1:lmem(278)),thour,
     %  mem(279)(1:lmem(279)),tmin,mem(280)(1:lmem(280)),tsec,
     %  mem(281)(1:lmem(281))
      string(size+1:5+size) = ''' >> '
      call command (string(1:5+size)//outfile, 5+size+79)
c
c------------------------------------------------------------------------------
c
      return
      end
c
