c ##A20,9##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_REMAINING.FOR    (FEG   30 April 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Print out integration time remaining.
c
c------------------------------------------------------------------------------
c
      subroutine mio_remaining (unit,treal,time,tstart,tstop,outfile,
     %  mem,lmem)
c
      implicit none
      include 'mercury.inc'
c
c Input/output
      integer lmem(NMESS),unit
      real*8 treal,time,tstart,tstop
      character*80 mem(NMESS),outfile
c
c Local
      real*8 trem
      integer tday,thour,tmin
      real*8 tsec
      character*1000 string
      integer size
c
c------------------------------------------------------------------------------
c
      if ((time-tstart).ne.0.d0) then
        trem = treal * dabs((tstop-(time-tstart)) / (time-tstart))
        call dhms(trem,tday,thour,tmin,tsec)
c        write(6,'(a,i5,a,2(i2,a),f6.3,a)') mem(282)(1:lmem(282)),tday,
c     %    mem(278)(1:lmem(278)),thour,mem(279)(1:lmem(279)),tmin,
c     %    mem(280)(1:lmem(280)),tsec,mem(281)(1:lmem(281))
c        write(unit,'(a,i5,a,2(i2,a),f6.3,a)') mem(282)(1:lmem(282)),
c     %    tday,mem(278)(1:lmem(278)),thour,mem(279)(1:lmem(279)),tmin,
c     %    mem(280)(1:lmem(280)),tsec,mem(281)(1:lmem(281))
        string(1:6) = 'echo '''
        size = 6+lmem(282)+5+lmem(278)+4+lmem(279)+lmem(280)+6+lmem(281)
        write(string(7:size),'(a,i5,a,2(i2,a),f6.3,a)')
     %    mem(282)(1:lmem(282)),tday,mem(278)(1:lmem(278)),thour,
     %    mem(279)(1:lmem(279)),tmin,mem(280)(1:lmem(280)),tsec,
     %    mem(281)(1:lmem(281))
        string(size+1:5+size) = ''' >> '
        call command (string(1:5+size)//outfile, 5+size+79)
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A20,9##
c
c ##A20,10##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_SIZEOUT.FOR    (FEG   30 April 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Print out size of Mercury outfiles.
c
c------------------------------------------------------------------------------
c
      subroutine mio_sizeout (unit,opt,nbod,flag,tstart,tstop,dtout,
     %  outfile,mem,lmem)
c
      implicit none
      include 'mercury.inc'
c
c Input/output
      integer nbod,opt,flag,lmem(NMESS),unit
      real*8 tstart,tstop,dtout
      character*80 mem(NMESS),outfile(4)
c
c Local
      character*1000 string
      integer j,n,nchar
      integer*8 size,size0
c
c------------------------------------------------------------------------------
c
      if (flag.eq.-1) then
        if (opt.eq.1) nchar = 2
        if (opt.eq.2) nchar = 4
        if (opt.eq.3) nchar = 7
c
        size = 67+(nbod-1)*48
        n = int (abs (tstop-tstart) / dtout) + 1
        size0 = 9+(nbod-1)*(6*nchar)
        size0 = size0 * n
        size = size + size0
c
c        write(6,'(a,i15,1x,2(a),a80)') mem(283)(1:lmem(283)),size,
c     %    mem(285)(1:lmem(285)),mem(286)(1:lmem(286)),outfile(1)
        write(unit,'(a,i15,1x,2(a),a80)') mem(283)(1:lmem(283)),size,
     %    mem(285)(1:lmem(285)),mem(286)(1:lmem(286)),outfile(1)
c        string(1:6) = 'echo '''
c        string(7:6+lmem(283)) = mem(283)(1:lmem(283))
c        write(string(7+lmem(283):22+lmem(283)),'(i15)') size
c        string(23+lmem(283):22+lmem(283)+lmem(285)) =
c     %    mem(285)(1:lmem(285))
c        string(23+lmem(283)+lmem(285):22+lmem(283)+lmem(285)+
c     %    lmem(286)) = mem(286)(1:lmem(286))
c        string(23+lmem(283)+lmem(285)+lmem(286):102+lmem(283)+
c     %    lmem(285)+lmem(286)) = outfile(1)(1:80)
c        string(103+lmem(283)+lmem(285)+lmem(286):107+lmem(283)+
c     %    lmem(285)+lmem(286)) = ''' >> '
c        call command (string(1:107+lmem(283)+lmem(285)+lmem(286))//
c     %    outfile(4),186+lmem(283)+lmem(285)+lmem(286))
      else
c        write(6,'(a)') mem(284)(1:lmem(284))
        string(1:6) = 'echo '''
        string(7:6+lmem(284)) = mem(284)(1:lmem(284))
        string(7+lmem(284):11+lmem(284)) = ''' >> '
        call command (string(1:11+lmem(284))//outfile(4),90+lmem(284))
        do j = 1, 2
          string(1:6) = 'ls -l '
          string(7:87) = outfile(j)
          string(88:128) = '| awk ''{printf $5 " bytes -> " $9 "\n"}'''
c          call command ( string, 128 )
          string(129:132) = ' >> '
          call command (string(1:132)//outfile(4), 211)
        end do
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A20,10##
c
c ##A20,30##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MIO_PID.FOR    (FEG   30 April 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Print out PID process of Mercury.
c
c------------------------------------------------------------------------------
c
      subroutine mio_pid (outfile)
c
      implicit none
c
c Input/output
      character*80 outfile
c
c Local
      integer pid
      real*8 nbr
      integer ex
      character*1000 string
c
c------------------------------------------------------------------------------
c
      call get_pid (pid)
      string(1:6) = 'ps -p '
      nbr = pid
      if (nbr.ne.0) then
        ex = int(log10(nbr))
      else
        ex = 0
      end if
      ex = ex + 1
      write (string(7:7+ex-1),'(i0)') pid
      string(7+ex:43+ex) = ' -o %cpu,%mem,cputime,etime,bsdstart,'
      string(44+ex:66+ex) = 'pid,comm,state,ni,euser'
c      string(1:43) = 'ps -C mercury_guara4 -o %cpu,%mem,bsdstart,'
c      string(44:84) = 'bsdtime,c,comm,command,cp,cputime,egroup,'
c      string(85:125) = 'etime,euid,euser,gid,lstart,ni,pcpu,pgid,'
c      string(126:167) = 'pid,pmem,ppid,rss,ruid,size,start,sz,time,'
c      string(168:209) = 'tname,vsz,args,nice,rgroup,ruser,tty,user,'
c      string(210:251) = 'addr,atime,flags,pri,rgid,sid,state,stime,'
c      string(252:265) = 'uid,wchan,xpid'
c      call command ( string, 66+ex )
      string(67+ex:70+ex) = ' >> '
      call command (string(1:70+ex)//outfile, 70+ex+79)
c
c------------------------------------------------------------------------------
c
      return
      end
