c ##A20,31##
c
c ##A24,6##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCE_CRITERIA.FOR    (FEG   21 Jul 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Save close encounters, collisions and ejections after a criteria.
c
c------------------------------------------------------------------------------
c
c ##AN28,29##
      subroutine mce_criteria (time,tstart,nbod,algor,opt,m,id,
     %  opti,optr,mem,lmem,nbclo,nstored,K2)
c ##AN28,29##
c
      implicit none
      include 'mercury.inc'
c
c Input/output
      integer nbod,algor,opt,lmem(NMESS),nbclo,nstored
      integer opti(90)
      real*8 time,tstart,m(nbod)
      real*8 optr(76)
      character*8 id(nbod)
      character*80 mem(NMESS)
c ##AN28,30##
      real*8 K2
c ##AN28,30##
c
c Local
      integer j,flag,i0
      integer year,month
      real*8 k_2,t1,sum
c
c------------------------------------------------------------------------------
c
      k_2 = 1.d0 / K2
      flag = 0
      i0 = 2
      if (algor.eq.11.or.algor.eq.12) i0 = 3
      if (algor.eq.5) i0 = 4
c
      if (opti(31).eq.1) then
        flag = 1
        if (time.ge.optr(23)) then
          if (opt.eq.1) then
            call mio_jd2y (time,year,month,t1)
            write (23,'(/,3a,f18.5,a,a1,1x,a,i10,1x,i2,1x,f8.5,/)')
     %        mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %        mem(327)(1:lmem(327)),optr(23),mem(1)(1:lmem(1)),',',
     %        mem(71)(1:lmem(71)),year,month,t1
            write (*,'(/,3a,f18.7,a,a1,1x,a,i10,1x,i2,1x,f8.5,/)')
     %        mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %        mem(327)(1:lmem(327)),optr(23),mem(1)(1:lmem(1)),',',
     %        mem(71)(1:lmem(71)),year,month,t1
          else
            if (opt.eq.3) then
              t1 = (time - tstart) / 365.25d0
              write (23,'(/,3a,f18.5,a,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(327)(1:lmem(327)),optr(23),mem(1)(1:lmem(1)),',',
     %          mem(71)(1:lmem(71)),t1,mem(2)(1:lmem(2))
              write (*,'(/,3a,f18.7,a,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(327)(1:lmem(327)),optr(23),mem(1)(1:lmem(1)),',',
     %          mem(71)(1:lmem(71)),t1,mem(2)(1:lmem(2))
            else
              if (opt.eq.0) t1 = time
              if (opt.eq.2) t1 = time - tstart
              write (23,'(/,3a,f18.5,a,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(327)(1:lmem(327)),optr(23),mem(1)(1:lmem(1)),',',
     %          mem(71)(1:lmem(71)),t1,mem(1)(1:lmem(1))
              write (*,'(/,3a,f18.5,a,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(327)(1:lmem(327)),optr(23),mem(1)(1:lmem(1)),',',
     %          mem(71)(1:lmem(71)),t1,mem(1)(1:lmem(1))
            end if
          end if
          opti(31) = 0
          opti(32) = 0
          opti(33) = 0
          opti(34) = 0
        end if
      end if
c
      if (opti(32).eq.1) then
        flag = 1
        do j = i0, nbod
          if ((m(j).ge.optr(24))
     %      .and.(j.lt.opti(35).or.j.gt.opti(36))) then
            if (opt.eq.1) then
              call mio_jd2y (time,year,month,t1)
              write (23,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,
     %          f8.5,/)') mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %          mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),year,month,t1
              write (*,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,
     %          f8.5,/)') mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %          mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),year,month,t1
            else
              if (opt.eq.3) then
                t1 = (time - tstart) / 365.25d0
                write (23,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.7,a,
     %            /)') mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %            mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %            mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %            mem(2)(1:lmem(2))
                write (*,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.7,a,
     %            /)') mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %            mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %            mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %            mem(2)(1:lmem(2))
              else
                if (opt.eq.0) t1 = time
                if (opt.eq.2) t1 = time - tstart
                write (23,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.5,a,
     %            /)') mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %            mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %            mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %            mem(1)(1:lmem(1))
                write (*,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.5,a,
     %            /)') mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %            mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %            mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %            mem(1)(1:lmem(1))
              end if
            end if
            opti(31) = 0
            opti(32) = 0
            opti(33) = 0
            opti(34) = 0
            exit
          end if
        end do
      end if
c
      if (opti(33).eq.1) then
        flag = 1
        sum = 0
        do j = i0, nbod
          if (j.lt.opti(37).or.j.gt.opti(38)) sum = sum + m(j)
        end do
        if (sum.le.optr(25)) then
          if (opt.eq.1) then
            call mio_jd2y (time,year,month,t1)
            write (23,'(/,3a,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,f8.5,
     %        /)') mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %        mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %        mem(71)(1:lmem(71)),year,month,t1
            write (*,'(/,3a,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,f8.5,
     %        /)') mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %        mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %        mem(71)(1:lmem(71)),year,month,t1
          else
            if (opt.eq.3) then
              t1 = (time - tstart) / 365.25d0
              write (23,'(/,3a,1p1e12.6,0p,a,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %          mem(71)(1:lmem(71)),t1,mem(2)(1:lmem(2))
              write (*,'(/,3a,1p1e12.6,0p,a,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %          mem(71)(1:lmem(71)),t1,mem(2)(1:lmem(2))
            else
              if (opt.eq.0) t1 = time
              if (opt.eq.2) t1 = time - tstart
              write (23,'(/,3a,1p1e12.6,0p,a,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %          mem(71)(1:lmem(71)),t1,mem(1)(1:lmem(1))
              write (*,'(/,3a,1p1e12.6,0p,a,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %          mem(71)(1:lmem(71)),t1,mem(1)(1:lmem(1))
            end if
          end if
          opti(31) = 0
          opti(32) = 0
          opti(33) = 0
          opti(34) = 0
        end if
      end if
c
      if (opti(34).eq.1) then
        flag = 1
        if (nbod.le.opti(39)) then
          if (opt.eq.1) then
            call mio_jd2y (time,year,month,t1)
            write (23,'(/,3a,i7,a1,1x,a,i10,1x,i2,1x,f8.5,/)')
     %        mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %        mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %        year,month,t1
            write (*,'(/,3a,i7,a1,1x,a,i10,1x,i2,1x,f8.5,/)')
     %        mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %        mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %        year,month,t1
          else
            if (opt.eq.3) then
              t1 = (time - tstart) / 365.25d0
              write (23,'(/,3a,i7,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %          t1,mem(2)(1:lmem(2))
              write (*,'(/,3a,i7,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %          t1,mem(2)(1:lmem(2))
            else
              if (opt.eq.0) t1 = time
              if (opt.eq.2) t1 = time - tstart
              write (23,'(/,3a,i7,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %          t1,mem(1)(1:lmem(1))
              write (*,'(/,3a,i7,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(326)(1:lmem(326)),
     %          mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %          t1,mem(1)(1:lmem(1))
            end if
          end if
          opti(31) = 0
          opti(32) = 0
          opti(33) = 0
          opti(34) = 0
        end if
      end if
c
      if (flag.gt.0) then
        nbclo   = 0
        nstored = 0
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A24,6##
c
c ##A25,4##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      RAYCASTING.FOR    (6 September 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Given a point and a polyhedron, check if the point is inside (flag=1) or
c outside (flag=0) the polyhedron using the ray-casting algorithm.
c
c------------------------------------------------------------------------------
c
      subroutine raycasting (nov,nop,xv,yv,zv,noe,k,x,y,z,flag)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nov,nop,noe,k,flag
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 x,y,z
      dimension noe(nop)
      dimension k(nopmax,noed)
c
c Local
      integer i,j
      integer count,iflag
      integer is_odd
      real*8 Ax,Ay,Bx,By,Px,Py
c
c------------------------------------------------------------------------------
c
      count = 0
      do i = 1, nop
        do j = 1, noe(i)-1
          Ax = xv(k(i,j))
          Ay = yv(k(i,j))
          Bx = xv(k(i,j+1))
          By = yv(k(i,j+1))
          Px = x
          Py = y
          call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
          if (iflag.eq.1) count = count + 1
        end do
        Ax = xv(k(i,noe(i)))
        Ay = yv(k(i,noe(i)))
        Bx = xv(k(i,1))
        By = yv(k(i,1))
        Px = x
        Py = y
        call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
        if (iflag.eq.1) count = count + 1
      end do
      flag = is_odd(count)
      if (flag.eq.0) return
c
      count = 0
      do i = 1, nop
        do j = 1, noe(i)-1
          Ax = yv(k(i,j))
          Ay = zv(k(i,j))
          Bx = yv(k(i,j+1))
          By = zv(k(i,j+1))
          Px = y
          Py = z
          call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
          if (iflag.eq.1) count = count + 1
        end do
        Ax = yv(k(i,noe(i)))
        Ay = zv(k(i,noe(i)))
        Bx = yv(k(i,1))
        By = zv(k(i,1))
        Px = y
        Py = z
        call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
        if (iflag.eq.1) count = count + 1
      end do
      flag = is_odd(count)
      if (flag.eq.0) return
c
      count = 0
      do i = 1, nop
        do j = 1, noe(i)-1
          Ax = zv(k(i,j))
          Ay = xv(k(i,j))
          Bx = zv(k(i,j+1))
          By = xv(k(i,j+1))
          Px = z
          Py = x
          call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
          if (iflag.eq.1) count = count + 1
        end do
        Ax = zv(k(i,noe(i)))
        Ay = xv(k(i,noe(i)))
        Bx = zv(k(i,1))
        By = xv(k(i,1))
        Px = z
        Py = x
        call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
        if (iflag.eq.1) count = count + 1
      end do
      flag = is_odd(count)
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A25,4##
c
c ##A25,5##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      IS_ODD.FOR    (6 September 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Given a number, check if the number is an odd (1) or even (0) number.
c
c------------------------------------------------------------------------------
c
      function is_odd (n)
c
      implicit none
c
c Input/Output
      integer n
      integer is_odd
c
c------------------------------------------------------------------------------
c
      if (mod(n,2).eq.0) then
        is_odd = 0
      else
        is_odd = 1
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A25,5##
c
c ##A25,6##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      RAY_INTERSECTS_SEGMENT.FOR    (6 September 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Given a point and a polygon, check if the point is inside (flag=1) or
c outside (flag=0) the polygon using the ray-casting algorithm.
c
c    P : the point from which the ray starts
c    A : the end-point of the segment with the smallest y coordinate
c        (A must be "below" B)
c    B : the end-point of the segment with the greatest y coordinate
c        (B must be "above" A)
c
c------------------------------------------------------------------------------
c
      subroutine ray_intersects_segment (Ax,Ay,Bx,By,Px,Py,flag)
c
      implicit none
      include 'mercury.inc'
      real*8 EPS
      parameter (EPS = 0.00001)
c
c Input/Output
      integer flag
      real*8 Ax,Ay,Bx,By,Px,Py
c
c Local
      real*8 m_red,m_blue,C
c
c------------------------------------------------------------------------------
c
      if (Ay.gt.By) then
        C  = Ay
        Ay = By
        By = C
c
        C  = Ax
        Ax = Bx
        Bx = C
      end if
c
      if (Py.eq.Ay.or.Py.eq.By) Py = Py + EPS
      if (Py.lt.Ay.or.Py.gt.By) then
        flag = 0
      else if (Px.gt.max(Ax, Bx)) then 
        flag = 0
      else
        if (Px.lt.min(Ax, Bx)) then
          flag = 1
        else
          if (abs(Ax-Bx).gt.TINY) then
            m_red = (By - Ay)/(Bx - Ax)
          else
            m_red = HUGE
          end if
          if (abs(Ax-Px).gt.TINY) then
            m_blue = (Py - Ay)/(Px - Ax)
          else
            m_blue = HUGE
          end if
          if (m_blue.ge.m_red) then
            flag = 1
          else
            flag = 0
          end if
        end if
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A25,6##
c
c ##A25,12##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      TETRAH.FOR    (6 September 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Given a point and a polyhedron, check if the point is inside (iflag=1) or
c outside (iflag=0) the polyhedron using the tetrahedron method.
c
c------------------------------------------------------------------------------
c
      subroutine tetrah (nov,nop,xv,yv,zv,noe,k,x,y,z,iflag)
c
      implicit none
      include 'mercury.inc'
      real*8 EPS
      parameter (EPS = 0.00001)
c
c Input/Output
      integer nov,nop,noe,k,iflag
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 x,y,z
      dimension noe(nop)
      dimension k(nopmax,noed)
c
c Local
      integer i,j,flag,cross
      integer inout(5)
      real*8 A(4,4),D(5),Dt,b(4),Px,Py,Pz
      real*8 GETDET
c
c------------------------------------------------------------------------------
c
      Px = x
      Py = y
      Pz = z
c
1234  continue
      cross = 0
      do i = 1, nop
        A(1,1) = 0.d0
        A(1,2) = 0.d0
        A(1,3) = 0.d0
        A(1,4) = 1.d0
        do j = 1, noe(i)
          A(j+1,1) = xv(k(i,j))
          A(j+1,2) = yv(k(i,j))
          A(j+1,3) = zv(k(i,j))
          A(j+1,4) = 1.d0
        end do
        D(1) = GETDET(A,4)
        if (abs(D(1)).le.TINY) cycle
        inout(1) = int(sign(1.d0,D(1)))
c
        do j = 1, noe(i)
          if (j.eq.noe(i)) then
            A(j+1,1) = Px
            A(j+1,2) = Py
            A(j+1,3) = Pz
            A(j+1,4) = 1.d0
          else
            A(j+1,1) = xv(k(i,j))
            A(j+1,2) = yv(k(i,j))
            A(j+1,3) = zv(k(i,j))
            A(j+1,4) = 1.d0
          end if
        end do
        D(5) = GETDET(A,4)
        if (abs(D(5)).le.TINY) then
          Px = Px + EPS
          Py = Py + EPS
          Pz = Pz + EPS
          goto 1234
        end if
        inout(5) = int(sign(1.d0,D(5)))
c        b(4) = D(5)/D(1)
c
        do j = 1, noe(i)
          if (j.eq.noe(i)-1) then
            A(j+1,1) = Px
            A(j+1,2) = Py
            A(j+1,3) = Pz
            A(j+1,4) = 1.d0
          else
            A(j+1,1) = xv(k(i,j))
            A(j+1,2) = yv(k(i,j))
            A(j+1,3) = zv(k(i,j))
            A(j+1,4) = 1.d0
          end if
        end do
        D(4) = GETDET(A,4)
        if (abs(D(4)).le.TINY) then
          Px = Px + EPS
          Py = Py + EPS
          Pz = Pz + EPS
          goto 1234
        end if
        inout(4) = int(sign(1.d0,D(4)))
c        b(3) = D(4)/D(1)
c
        do j = 1, noe(i)
          if (j.eq.noe(i)-2) then
            A(j+1,1) = Px
            A(j+1,2) = Py
            A(j+1,3) = Pz
            A(j+1,4) = 1.d0
          else
            A(j+1,1) = xv(k(i,j))
            A(j+1,2) = yv(k(i,j))
            A(j+1,3) = zv(k(i,j))
            A(j+1,4) = 1.d0
          end if
        end do
        D(3) = GETDET(A,4)
        if (abs(D(3)).le.TINY) then
          Px = Px + EPS
          Py = Py + EPS
          Pz = Pz + EPS
          goto 1234
        end if
        inout(3) = int(sign(1.d0,D(3)))
c        b(2) = D(3)/D(1)
c
        A(1,1) = Px
        A(1,2) = Py
        A(1,3) = Pz
        A(1,4) = 1.d0
        do j = 1, noe(i)
          A(j+1,1) = xv(k(i,j))
          A(j+1,2) = yv(k(i,j))
          A(j+1,3) = zv(k(i,j))
          A(j+1,4) = 1.d0
        end do
        D(2) = GETDET(A,4)
        if (abs(D(2)).le.TINY) then
          Px = Px + EPS
          Py = Py + EPS
          Pz = Pz + EPS
          goto 1234
        end if
        inout(2) = int(sign(1.d0,D(2)))
c        b(1) = D(2)/D(1)
c
c        Dt = D(2)+D(3)+D(4)+D(5)
c
c        write(*,*) i,D(1),inout(1)
c        write(*,*) D(2),D(3),D(4),D(5)
c        write(*,*) inout(2),inout(3),inout(4),inout(5)
c        write(*,*) D(1),Dt
c        write(*,*) b(1),b(2),b(3),b(4)
c
        flag = 1
        do j = 2, 5
          if (inout(1)*inout(j).lt.0) flag = 0
        end do
c        if (flag.eq.1) exit
        if (flag.eq.1) cross = cross + 1
c
        if (cross.eq.1) exit
      end do
c
      iflag = 1
      if (mod(cross,2).eq.0) iflag = 0
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A25,12##
c
c ##A25,13##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      GETDET.FOR    (6 September 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
C A general purpose function written in FORTRAN77 to calculate determinant of a
C square matrix
C Passed parameters:
C A = the matrix
C N = dimension of the square matrix
C A modification of a code originally written by Ashwith J. Rego, available from
C http://www.dreamincode.net/code/snippet1273.htm
C Modified by Syeilendra Pramuditya, available from http://wp.me/p61TQ-zb
C Last modified on January 13, 2011
c
c------------------------------------------------------------------------------
c
      function GETDET (A,N)
c
      IMPLICIT REAL*8 (A-H,O-Z)
c
c Input/Output
      REAL*8 A(N,N)
      real*8 GETDET
c
c Local
      REAL*8 ELEM(N,N)
      REAL*8 M, TEMP
      INTEGER I, J, K, L
      LOGICAL DETEXISTS
c
c------------------------------------------------------------------------------
c
      DO I=1,N
        DO J=1,N
          ELEM(I,J)=A(I,J)
        END DO
      END DO
      DETEXISTS = .TRUE.
      L = 1
!CONVERT TO UPPER TRIANGULAR FORM
      DO K = 1, N-1
        IF (DABS(ELEM(K,K)).LE.1.0D-20) THEN
          DETEXISTS = .FALSE.
          DO I = K+1, N
            IF (ELEM(I,K).NE.0.0) THEN
              DO J = 1, N
                TEMP = ELEM(I,J)
                ELEM(I,J)= ELEM(K,J)
                ELEM(K,J) = TEMP
              END DO
              DETEXISTS = .TRUE.
              L=-L
              EXIT
            END IF
          END DO
          IF (DETEXISTS .EQV. .FALSE.) THEN
            GETDET = 0
            RETURN
          END IF
        END IF
        DO J = K+1, N
          M = ELEM(J,K)/ELEM(K,K)
          DO I = K+1, N
            ELEM(J,I) = ELEM(J,I) - M*ELEM(K,I)
          END DO
        END DO
      END DO
!CALCULATE DETERMINANT BY FINDING PRODUCT OF DIAGONAL ELEMENTS
      GETDET = L
      DO I = 1, N
        GETDET = GETDET * ELEM(I,I)
      END DO
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A25,13##
c
c ##A26,7##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_IDEN2.FOR    (ErikSoft   2 November 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 7 September 2015)
c
c Makes a new copy of a set of coordinates.
c
c------------------------------------------------------------------------------
c
      subroutine mco_iden2(time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,ngflag,
     %  opt)
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod),ngf(4,nbod)
c
c Local
      integer j
c
c------------------------------------------------------------------------------
c
      do j = nbig, nbod
        x(1,j) = xh(1,j)
        x(2,j) = xh(2,j)
        x(3,j) = xh(3,j)
        v(1,j) = vh(1,j)
        v(2,j) = vh(2,j)
        v(3,j) = vh(3,j)
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A26,7##
c
c ##ANEO27,4##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MDT_HYRA.FOR    (ErikSoft   2 March 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers  (adapted by A. Amarante, N. C. S. Araújo,
c E. V. Neto e O. C. Winter - 22 September 2016)
c
c Integrates NBOD bodies (of which NBIG are Big) for one timestep H0
c using a second-order hybrid-Everhart's RA15 integrator algorithm. The
c accelerations are calculated using the subroutine FORCE. The accuracy of the
c step is approximately determined by the tolerance parameter TOL.
c
c Based on RADAU by E. Everhart, Physics Department, University of Denver.
c Comments giving equation numbers refer to Everhart (1985) ``An Efficient
c Integrator that Uses Gauss-Radau Spacings'', in The Dynamics of Comets:
c Their Origin and Evolution, p185-202, eds. A. Carusi & G. B. Valsecchi,
c pub Reidel. (A listing of the original subroutine is also given in this 
c paper.)
c
c DTFLAG = 0 implies first ever call to this subroutine, 
c        = 1 implies first call since number/masses of objects changed.
c        = 2 normal call
c
c N.B. Input/output must be in coordinates with respect to the central body.
c ===
c
c------------------------------------------------------------------------------
c
c ##AN28,73##
c ##A35,72##
c ##A39,28## 
c ##A43,20##
      subroutine mdt_hyra (time,tstart,t,tdid,tol,rmax,en,am,jcen,
     %  rcen,nbod,nbig,mass,x1,v1,spin,rphys,rcrit,rce,stat,id,ngf,
     %  algor,opt,dtflag,ngflag,opflag,colflag,nclo,iclo,jclo,dclo,
     %  tclo,ixvclo,jxvclo,outfile,mem,lmem,force,nclo2,iclo2,jclo2,
     %  dclo2,tclo2,ixvclo2,jxvclo2,nstored,nbclo,bclo,aux,cce,opti,
     %  rho,flagce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xvc,yvc,zvc,
     %  optr,apot,nelim,tcol,nce,ice,jce,K2,AU,MSUN,coord,bcoord,
     %  idtag,chk,lapla2)
c ##A43,20##
c ##A39,28## 
c ##A35,72##
c ##AN28,73##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,nbig,dtflag,ngflag,opt(9),stat(nbod)
c      integer nce,ice(nce),jce(nce)
      real*8 time,t,tdid,tol,jcen(3),mass(nbod)
      real*8 x1(3*nbod),v1(3*nbod),spin(3*nbod)
      real*8 ngf(4,nbod),rphys(nbod),rcrit(nbod)
c
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xvc(noc),yvc(noc),zvc(noc),mc(noc),dens(noc)
      integer algor
      real*8 optr(76)
      integer opti(90)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      external coord,bcoord
c
      integer opflag,colflag,lmem(NMESS)
      integer nclo,iclo(CMAX),jclo(CMAX)
      real*8 tstart,rmax,en(3),am(3),rcen
      real*8 rce(nbod),tclo(CMAX),dclo(CMAX)
      real*8 ixvclo(6,CMAX),jxvclo(6,CMAX)
      character*80 outfile(4),mem(NMESS)
      character*8 id(nbod)
c
      integer nclo2,iclo2(CMAX),jclo2(CMAX)
      real*8 dclo2(CMAX),tclo2(CMAX)
      real*8 ixvclo2(6,CMAX),jxvclo2(6,CMAX)
      integer nstored
      integer nbclo,bclo(nbod)
      character*1 aux(CMAX)
      character*107 cce(FMAX)
      real*8 rho(nbod)
      integer flagce(2)
c
      integer nelim
      real*8 tcol
c ##AN28,72##
      real*8 K2,AU,MSUN
c ##AN28,72##
c
c ##A35,73##
      integer idtag(nbod)
c ##A35,73##
      external force
c ##A39,29## 
      real*8 chk(3,nbod)
c ##A39,29## 
c ##A43,21##
      integer lapla2(nbod)
c ##A43,21##
c
c Local
      integer nv,niter,j,j0,k,n
      real*8 x(3*NMAX),v(3*NMAX),a(3*NMAX),a1(3*NMAX)
      real*8 g(7,3*NMAX),b(7,3*NMAX),e(7,3*NMAX)
      real*8 h(8),xc(8),vc(7),c(21),d(21),r(28),s(9)
      real*8 q,q2,q3,q4,q5,q6,q7,temp,gk
c
      integer nce,ice(NMAX),jce(NMAX),ce(NMAX),iflag
      real*8 h0,hrec,x0(3*NMAX),v0(3*NMAX)
c ##A19,171##
      real*8 x2(3*NMAX),v2(3*NMAX)
      real*8 t0,hrec0
c ##A19,171##
c
c------------------------------------------------------------------------------
c
      save h,xc,vc,c,d,r,b,e
      save hrec,hrec0
c
      nclo = 0
      colflag = 0
c
c ##A19,172##
c
c Save the current coordinates and velocities
      t0 = t
c ##A38,47##
      call mco_iden (time,jcen,nbod,nbig,t,mass,x1,v1,x2,v2,ngf,ngflag,
     %  opt,optr,opti,K2,AU,MSUN)
c ##A38,47##
c ##A19,172##
c
c Gauss-Radau spacings for substeps within a sequence, for the 15th order 
c integrator. The sum of the H values should be 3.733333333333333
c
      data h/          0.d0,.0562625605369221d0,.1802406917368924d0,
     %  .3526247171131696d0,.5471536263305554d0,.7342101772154105d0,
     %  .8853209468390958d0,.9775206135612875d0/
c
c Constant coefficients used in series expansions for X and V
c  XC: 1/2,  1/6,  1/12, 1/20, 1/30, 1/42, 1/56, 1/72
c  VC: 1/2,  1/3,  1/4,  1/5,  1/6,  1/7,  1/8
      data xc/.5d0,.1666666666666667d0,.08333333333333333d0,.05d0,
     %  .03333333333333333d0,.02380952380952381d0,.01785714285714286d0,
     %  .01388888888888889d0/
      data vc/.5d0,.3333333333333333d0,.25d0,.2d0,
     %  .1666666666666667d0,.1428571428571429d0,.125d0/
c
c If this is first call to the subroutine, set values of the constant arrays
c (R = R21, R31, R32, R41, R42, R43 in Everhart's paper.)
      if (dtflag.eq.0) then
c
        hrec = t * h(2)
        hrec0= t
c
        n = 0
        do j = 2, 8
          do k = 1, j - 1
            n = n + 1
            r(n) = 1.d0 / (h(j) - h(k))
          end do
        end do
c
c Constants to convert between B and G arrays (C = C21, C31, C32, C41, C42...)
        c(1) = - h(2)
        d(1) =   h(2)
        n = 1
        do j = 3, 7
          n = n + 1
          c(n) = -h(j) * c(n-j+2)
          d(n) =  h(2) * d(n-j+2)
          do k = 3, j - 1
            n = n + 1
            c(n) = c(n-j+1)  -  h(j) * c(n-j+2)
            d(n) = d(n-j+1)  +  h(k) * d(n-j+2)
          end do
          n = n + 1
          c(n) = c(n-j+1) - h(j)
          d(n) = d(n-j+1) + h(j)
        end do
c
        dtflag = 1
      end if
c
      nv = 3 * nbod
  100 continue
c
c If this is first call to subroutine since number/masses of objects changed
c do 6 iterations and initialize B, E arrays, otherwise do 2 iterations.
      if (dtflag.eq.1) then
        niter = 6
        do j = 4, nv
          do k = 1, 7
            b (k,j) = 0.d0
            e (k,j) = 0.d0
          end do
        end do
      else
        niter = 2
      end if
c
c Save the current coordinates and velocities
c      call mco_iden (time,jcen,nbod,nbig,t,mass,x1,v1,x0,v0,ngf,ngflag,
c     %  opt)
c
c Calculate forces at the start of the sequence
c ##AN28,107##
c ##A38,127##
c ##A39,45##
      call force (time,jcen,nbod,nbig,mass,x1,v1,spin,rcrit,a1,stat,ngf,
     %  ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xvc,
     %  yvc,zvc,optr,opti,algor,apot,K2,AU,MSUN,chk,lapla2,tstart)
c ##A39,45##
c ##A38,127##
c ##AN28,107##
c
c Check whether any object separations were < R_CRIT whilst advancing H_K
c      call mce_snif (t,2,nbod,nbig,x0,v0,x1,v1,rcrit,ce,nce,ice,jce)
c
c If objects had close encounters, advance H_K using Bulirsch-Stoer instead
c      if (nce.gt.0) then
c        do j0 = 2, nbod
c          if (ce(j0).ne.0) then
c            x1(3*j0-2) = x0(3*j0-2)
c            x1(3*j0-1) = x0(3*j0-1)
c            x1(3*j0)   = x0(3*j0)
c            v1(3*j0-2) = v0(3*j0-2)
c            v1(3*j0-1) = v0(3*j0-1)
c            v1(3*j0)   = v0(3*j0)
c          end if
c        end do
c
c ##ANEO27,10##
c ##AN28,71##
c ##A35,93##
c        call mdt_hkce (time,tstart,t,hrec,tol,rmax,en(3),jcen,rcen,
c     %    nbod,nbig,mass,x1,v1,spin,rphys,rcrit,rce,stat,id,ngf,algor,
c     %    opt,ngflag,colflag,ce,nce,ice,jce,nclo,iclo,jclo,dclo,tclo,
c     %    ixvclo,jxvclo,outfile,mem,lmem,force,nclo2,iclo2,jclo2,dclo2,
c     %    tclo2,ixvclo2,jxvclo2,nstored,nbclo,bclo,aux,cce,opti,rho,
c     %    flagce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xvc,yvc,zvc,optr,
c     %    apot,nelim,tcol,1,K2,AU,MSUN,coord,bcoord,idtag)
c      end if
c ##A35,93##
c ##AN28,71##
c ##ANEO27,10##
c
c Find G values from B values predicted at the last call (Eqs. 7 of Everhart)
      do k = 4, nv
        g(1,k) = b(7,k)*d(16) + b(6,k)*d(11) + b(5,k)*d(7)
     %         + b(4,k)*d(4)  + b(3,k)*d(2)  + b(2,k)*d(1)  + b(1,k)
        g(2,k) = b(7,k)*d(17) + b(6,k)*d(12) + b(5,k)*d(8)
     %         + b(4,k)*d(5)  + b(3,k)*d(3)  + b(2,k)
        g(3,k) = b(7,k)*d(18) + b(6,k)*d(13) + b(5,k)*d(9)
     %         + b(4,k)*d(6)  + b(3,k)
        g(4,k) = b(7,k)*d(19) + b(6,k)*d(14) + b(5,k)*d(10) + b(4,k)
        g(5,k) = b(7,k)*d(20) + b(6,k)*d(15) + b(5,k)
        g(6,k) = b(7,k)*d(21) + b(6,k)
        g(7,k) = b(7,k)
      end do
c
c------------------------------------------------------------------------------
c
c  MAIN  LOOP  STARTS  HERE
c
c For each iteration (six for first call to subroutine, two otherwise)...
      do n = 1, niter
c
c For each substep within a sequence...
        do j = 2, 8
c
          if (j.eq.2) then
c ##A38,48##
            call mco_iden (time,jcen,nbod,nbig,h0,mass,x1,v1,x0,v0,ngf,
     %        ngflag,opt,optr,opti,K2,AU,MSUN)
          else
            call mco_iden (time,jcen,nbod,nbig,h0,mass,x,v,x0,v0,ngf,
     %        ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,48##
          end if
c
c Calculate position predictors using Eqn. 9 of Everhart
          s(1) = t * h(j)
          s(2) = s(1) * s(1) * .5d0
          s(3) = s(2) * h(j) * .3333333333333333d0
          s(4) = s(3) * h(j) * .5d0
          s(5) = s(4) * h(j) * .6d0
          s(6) = s(5) * h(j) * .6666666666666667d0
          s(7) = s(6) * h(j) * .7142857142857143d0
          s(8) = s(7) * h(j) * .75d0
          s(9) = s(8) * h(j) * .7777777777777778d0
c
          do k = 4, nv
            x(k) = s(9)*b(7,k) + s(8)*b(6,k) + s(7)*b(5,k)
     %           + s(6)*b(4,k) + s(5)*b(3,k) + s(4)*b(2,k)
     %           + s(3)*b(1,k) + s(2)*a1(k)  + s(1)*v1(k) + x1(k)
          end do
c
c If necessary, calculate velocity predictors too, from Eqn. 10 of Everhart
          if (ngflag.ne.0) then
            s(1) = t * h(j)
            s(2) = s(1) * h(j) * .5d0
            s(3) = s(2) * h(j) * .6666666666666667d0
            s(4) = s(3) * h(j) * .75d0
            s(5) = s(4) * h(j) * .8d0
            s(6) = s(5) * h(j) * .8333333333333333d0
            s(7) = s(6) * h(j) * .8571428571428571d0
            s(8) = s(7) * h(j) * .875d0
c
            do k = 4, nv
              v(k) = s(8)*b(7,k) + s(7)*b(6,k) + s(6)*b(5,k)
     %             + s(5)*b(4,k) + s(4)*b(3,k) + s(3)*b(2,k)
     %             + s(2)*b(1,k) + s(1)*a1(k)  + v1(k)
            end do
          end if
c
          h0 = t * h(j)
c
c Check whether any object separations were < R_CRIT whilst advancing H_K
          call mce_snif (h0,2,nbod,nbig,x0,v0,x,v,rcrit,ce,nce,ice,jce)
c
c If objects had close encounters, advance H_K using Bulirsch-Stoer instead
          if (nce.gt.0) then
            do j0 = 2, nbod
              if (ce(j0).ne.0) then
                x(3*j0-2) = x0(3*j0-2)
                x(3*j0-1) = x0(3*j0-1)
                x(3*j0)   = x0(3*j0)
                v(3*j0-2) = v0(3*j0-2)
                v(3*j0-1) = v0(3*j0-1)
                v(3*j0)   = v0(3*j0)
              end if
            end do
c
c ##A35,94##
c ##A39,70##
c ##A43,82##
            call mdt_hkce (time,tstart,h0,hrec,tol,rmax,en(3),jcen,
     %        rcen,nbod,nbig,mass,x,v,spin,rphys,rcrit,rce,stat,id,
     %        ngf,algor,opt,ngflag,colflag,ce,nce,ice,jce,nclo,iclo,
     %        jclo,dclo,tclo,ixvclo,jxvclo,outfile,mem,lmem,force,
     %        nclo2,iclo2,jclo2,dclo2,tclo2,ixvclo2,jxvclo2,nstored,
     %        nbclo,bclo,aux,cce,opti,rho,flagce,nov,nop,noc,xv,yv,zv,
     %        noe,kkk,dens,mc,xvc,yvc,zvc,optr,apot,nelim,tcol,1,K2,
     %        AU,MSUN,coord,bcoord,idtag,chk,lapla2)
c ##A43,82##
c ##A39,70##
c ##A35,94##
          end if
c
c Save the current coordinates and velocities
c          call mco_iden (time,jcen,nbod,nbig,t,mass,x,v,x0,v0,ngf,
c     %      ngflag,opt)
c
c Calculate forces at the current substep
c ##AN28,108##
c ##A38,128##
c ##A39,46##
          call force (time,jcen,nbod,nbig,mass,x,v,spin,rcrit,a,stat,
     %      ngf,ngflag,opt,nce,ice,jce,nov,nop,noc,xv,yv,zv,noe,kkk,
     %      dens,mc,xvc,yvc,zvc,optr,opti,algor,apot,K2,AU,MSUN,chk,
     %      lapla2,tstart)
c ##A39,46##
c ##A38,128##
c ##AN28,108##
c
c Check whether any object separations were < R_CRIT whilst advancing H_K
c          call mce_snif (t,2,nbod,nbig,x0,v0,x1,v1,rcrit,ce,nce,ice,jce)
c
c If objects had close encounters, advance H_K using Bulirsch-Stoer instead
c          if (nce.gt.0) then
c            do j0 = 2, nbod
c              if (ce(j0).ne.0) then
c                x(3*j0-2) = x0(3*j0-2)
c                x(3*j0-1) = x0(3*j0-1)
c                x(3*j0)   = x0(3*j0)
c                v(3*j0-2) = v0(3*j0-2)
c                v(3*j0-1) = v0(3*j0-1)
c                v(3*j0)   = v0(3*j0)
c              end if
c            end do
c
c ##ANEO27,11##
c ##AN28,70##
c ##A35,95##
c            call mdt_hkce (time,tstart,t,hrec,tol,rmax,en(3),jcen,rcen,
c     %        nbod,nbig,mass,x,v,spin,rphys,rcrit,rce,stat,id,ngf,algor,
c     %        opt,ngflag,colflag,ce,nce,ice,jce,nclo,iclo,jclo,dclo,
c     %        tclo,ixvclo,jxvclo,outfile,mem,lmem,force,nclo2,iclo2,
c     %        jclo2,dclo2,tclo2,ixvclo2,jxvclo2,nstored,nbclo,bclo,aux,
c     %        cce,opti,rho,flagce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,
c     %        xvc,yvc,zvc,optr,apot,nelim,tcol,1,K2,AU,MSUN,coord,
c     %        bcoord,idtag)
c          end if
c ##A35,95##
c ##AN28,70##
c ##ANEO27,11##
c
c Update G values using Eqs. 4 of Everhart, and update B values using Eqs. 5
          if (j.eq.2) then
            do k = 4, nv
              temp = g(1,k)
              g(1,k) = (a(k) - a1(k)) * r(1)
              b(1,k) = b(1,k) + g(1,k) - temp
            end do
            goto 300
          end if
          if (j.eq.3) then
            do k = 4, nv
              temp = g(2,k)
              gk = a(k) - a1(k)
              g(2,k) = (gk*r(2) - g(1,k))*r(3)
              temp = g(2,k) - temp
              b(1,k) = b(1,k)  +  temp * c(1)
              b(2,k) = b(2,k)  +  temp
            end do
            goto 300
          end if
          if (j.eq.4) then
            do k = 4, nv
              temp = g(3,k)
              gk = a(k) - a1(k)
              g(3,k) = ((gk*r(4) - g(1,k))*r(5) - g(2,k))*r(6)
              temp = g(3,k) - temp
              b(1,k) = b(1,k)  +  temp * c(2)
              b(2,k) = b(2,k)  +  temp * c(3)
              b(3,k) = b(3,k)  +  temp
            end do
            goto 300
          end if
          if (j.eq.5) then
            do k = 4, nv
              temp = g(4,k)
              gk = a(k) - a1(k)
              g(4,k) = (((gk*r(7) - g(1,k))*r(8) - g(2,k))*r(9)
     %               - g(3,k))*r(10)
              temp = g(4,k) - temp
              b(1,k) = b(1,k)  +  temp * c(4)
              b(2,k) = b(2,k)  +  temp * c(5)
              b(3,k) = b(3,k)  +  temp * c(6)
              b(4,k) = b(4,k)  +  temp
            end do
            goto 300
          end if
          if (j.eq.6) then
            do k = 4, nv
              temp = g(5,k)
              gk = a(k) - a1(k)
              g(5,k) =  ((((gk*r(11) - g(1,k))*r(12) - g(2,k))*r(13)
     %               - g(3,k))*r(14) - g(4,k))*r(15)
              temp = g(5,k) - temp
              b(1,k) = b(1,k)  +  temp * c(7)
              b(2,k) = b(2,k)  +  temp * c(8)
              b(3,k) = b(3,k)  +  temp * c(9)
              b(4,k) = b(4,k)  +  temp * c(10)
              b(5,k) = b(5,k)  +  temp
            end do
            goto 300
          end if
          if (j.eq.7) then
            do k = 4, nv
              temp = g(6,k)
              gk = a(k) - a1(k)
              g(6,k) = (((((gk*r(16) - g(1,k))*r(17) - g(2,k))*r(18)
     %               - g(3,k))*r(19) - g(4,k))*r(20) - g(5,k))*r(21)
              temp = g(6,k) - temp
              b(1,k) = b(1,k)  +  temp * c(11)
              b(2,k) = b(2,k)  +  temp * c(12)
              b(3,k) = b(3,k)  +  temp * c(13)
              b(4,k) = b(4,k)  +  temp * c(14)
              b(5,k) = b(5,k)  +  temp * c(15)
              b(6,k) = b(6,k)  +  temp
            end do
            goto 300
          end if
          if (j.eq.8) then
            do k = 4, nv
              temp = g(7,k)
              gk = a(k) - a1(k)
              g(7,k) = ((((((gk*r(22) - g(1,k))*r(23) - g(2,k))*r(24)
     %                - g(3,k))*r(25) - g(4,k))*r(26) - g(5,k))*r(27)
     %                - g(6,k))*r(28)
              temp = g(7,k) - temp
              b(1,k) = b(1,k)  +  temp * c(16)
              b(2,k) = b(2,k)  +  temp * c(17)
              b(3,k) = b(3,k)  +  temp * c(18)
              b(4,k) = b(4,k)  +  temp * c(19)
              b(5,k) = b(5,k)  +  temp * c(20)
              b(6,k) = b(6,k)  +  temp * c(21)
              b(7,k) = b(7,k)  +  temp
            end do
          end if
 300      continue
        end do
      end do
c
c------------------------------------------------------------------------------
c
c  END  OF  MAIN  LOOP
c
c Estimate suitable sequence size for the next call to subroutine (Eqs. 15, 16)
      temp = 0.d0
      do k = 4, nv
        temp = max( temp, abs( b(7,k) ) )
      end do
      temp = temp / (72.d0 * abs(t)**7)
      tdid = t
      if (temp.eq.0) then
        t = tdid * 1.4d0
      else
        t = sign( (tol/temp)**(1.d0/9.d0), tdid )
      end if
c
c If sequence size for the first subroutine call is too big, go back and redo
c the sequence using a smaller size.
      if (dtflag.eq.1.and.abs(t/tdid).lt.1) then
        t = t * .8d0
        goto 100
      end if
c
c If new sequence size is much bigger than the current one, reduce it
      if (abs(t/tdid).gt.1.4d0) t = tdid * 1.4d0
c
c Find new position and velocity values at end of the sequence (Eqs. 11, 12)
      temp = tdid * tdid
      do k = 4 , nv
        x1(k) = (xc(8)*b(7,k) + xc(7)*b(6,k) + xc(6)*b(5,k)
     %        +  xc(5)*b(4,k) + xc(4)*b(3,k) + xc(3)*b(2,k)
     %        +  xc(2)*b(1,k) + xc(1)*a1(k))*temp + v1(k)*tdid + x1(k)
c
        v1(k) = (vc(7)*b(7,k) + vc(6)*b(6,k) + vc(5)*b(5,k)
     %        +  vc(4)*b(4,k) + vc(3)*b(3,k) + vc(2)*b(2,k)
     %        +  vc(1)*b(1,k) + a1(k))*tdid + v1(k)
      end do
c
c Predict new B values to use at the start of the next sequence. The predicted
c values from the last call are saved as E. The correction, BD, between the
c actual and predicted values of B is applied in advance as a correction.
      q = t / tdid
      q2 = q  * q
      q3 = q  * q2
      q4 = q2 * q2
      q5 = q2 * q3
      q6 = q3 * q3
      q7 = q3 * q4
c
      do k = 4, nv
        s(1) = b(1,k) - e(1,k)
        s(2) = b(2,k) - e(2,k)
        s(3) = b(3,k) - e(3,k)
        s(4) = b(4,k) - e(4,k)
        s(5) = b(5,k) - e(5,k)
        s(6) = b(6,k) - e(6,k)
        s(7) = b(7,k) - e(7,k)
c
c Estimate B values for the next sequence (Eqs. 13 of Everhart).
        e(1,k) = q* (b(7,k)* 7.d0 + b(6,k)* 6.d0 + b(5,k)* 5.d0
     %         +     b(4,k)* 4.d0 + b(3,k)* 3.d0 + b(2,k)*2.d0 + b(1,k))
        e(2,k) = q2*(b(7,k)*21.d0 + b(6,k)*15.d0 + b(5,k)*10.d0
     %         +     b(4,k)* 6.d0 + b(3,k)* 3.d0 + b(2,k))
        e(3,k) = q3*(b(7,k)*35.d0 + b(6,k)*20.d0 + b(5,k)*10.d0
     %         +     b(4,k)*4.d0  + b(3,k))
        e(4,k) = q4*(b(7,k)*35.d0 + b(6,k)*15.d0 + b(5,k)*5.d0 + b(4,k))
        e(5,k) = q5*(b(7,k)*21.d0 + b(6,k)*6.d0  + b(5,k))
        e(6,k) = q6*(b(7,k)*7.d0  + b(6,k))
        e(7,k) = q7* b(7,k)
c
        b(1,k) = e(1,k) + s(1)
        b(2,k) = e(2,k) + s(2)
        b(3,k) = e(3,k) + s(3)
        b(4,k) = e(4,k) + s(4)
        b(5,k) = e(5,k) + s(5)
        b(6,k) = e(6,k) + s(6)
        b(7,k) = e(7,k) + s(7)
      end do
      dtflag = 2
c
c------------------------------------------------------------------------------
c
c ##A19,173##
      if (algor.eq.23) then
        nce = 0
        do j = 2, nbod
          temp = x2(3*j-2)*x2(3*j-2)+x2(3*j-1)*x2(3*j-1)+x2(3*j)*x2(3*j)
          if (temp.le.optr(26)) then
            ce(j) = 1
            nce = nce + 1
            ice(nce) = 1
            jce(nce) = j
          end if
        end do
c
c If objects had close encounters, advance H_K using Bulirsch-Stoer instead
        if (nce.gt.0) then
          do j0 = 2, nbod
            if (ce(j0).ne.0) then
              x(3*j0-2) = x2(3*j0-2)
              x(3*j0-1) = x2(3*j0-1)
              x(3*j0)   = x2(3*j0)
              v(3*j0-2) = v2(3*j0-2)
              v(3*j0-1) = v2(3*j0-1)
              v(3*j0)   = v2(3*j0)
            end if
          end do
c
c ##A35,96##
c ##A39,71##
c ##A43,83##
          call mdt_hkce (time,tstart,t0,hrec0,tol,rmax,en(3),jcen,rcen,
     %      nbod,nbig,mass,x,v,spin,rphys,rcrit,rce,stat,id,ngf,algor,
     %      opt,ngflag,colflag,ce,nce,ice,jce,nclo,iclo,jclo,dclo,tclo,
     %      ixvclo,jxvclo,outfile,mem,lmem,force,nclo2,iclo2,jclo2,
     %      dclo2,tclo2,ixvclo2,jxvclo2,nstored,nbclo,bclo,aux,cce,opti,
     %      rho,flagce,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xvc,yvc,zvc,
     %      optr,apot,nelim,tcol,1,K2,AU,MSUN,coord,bcoord,idtag,chk,
     %      lapla2)
c ##A43,83##
c ##A39,71##
c ##A35,96##
c
        end if
      end if
c ##A19,173##
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##ANEO27,4##
c
c ##A19,174##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      CROSS_AST.FOR    (4 October 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Computes cross product of faces.
c
c------------------------------------------------------------------------------
c
      subroutine cross_ast (nov,nop,noe,k,xv,yv,zv,face)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nov,nop,noe,k
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 face(nop)
      dimension noe(nop)
      dimension k(nopmax,noed)
c Local
      integer i,j
      real*8 AB(3,noed),norm(3)
      real*8 prod,temp,temp1,temp2,xc(3)
c
c------------------------------------------------------------------------------
c
      do i = 1, nop
        do j = 1, noe(i)-1
          AB(1,j) = xv(k(i,j+1))-xv(k(i,j))
          AB(2,j) = yv(k(i,j+1))-yv(k(i,j))
          AB(3,j) = zv(k(i,j+1))-zv(k(i,j))
        end do
        norm(1) = AB(2,1)*AB(3,2)-AB(3,1)*AB(2,2)
        norm(2) = AB(3,1)*AB(1,2)-AB(1,1)*AB(3,2)
        norm(3) = AB(1,1)*AB(2,2)-AB(2,1)*AB(1,2)
c        prod = xv(k(i,1))*norm(1)+yv(k(i,1))*norm(2)+
c     %    zv(k(i,1))*norm(3)
        xc(1)   = (xv(k(i,1))+xv(k(i,2))+xv(k(i,3)))/3.d0
        xc(2)   = (yv(k(i,1))+yv(k(i,2))+yv(k(i,3)))/3.d0
        xc(3)   = (zv(k(i,1))+zv(k(i,2))+zv(k(i,3)))/3.d0
        prod = xc(1)*norm(1)+xc(2)*norm(2)+xc(3)*norm(3)
c        temp1 = dsqrt(xv(k(i,1))*xv(k(i,1))+yv(k(i,1))*yv(k(i,1))+
c     %    zv(k(i,1))*zv(k(i,1)))
c        temp1 = dsqrt(xc(1)*xc(1)+xc(2)*xc(2)+xc(3)*xc(3))
c        temp2 = dsqrt(norm(1)*norm(1)+norm(2)*norm(2)+norm(3)*norm(3))
c        temp = prod/(temp1*temp2)
c        temp = acos(temp)
c        temp = temp / DR
c        write(*,*) i,temp
        face(i) = sign(1.d0,prod)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A19,174##
c
c ##A19,175##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      REORIENTATION.FOR    (4 October 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Reorientate faces.
c
c------------------------------------------------------------------------------
c
      subroutine reorientation (face1,face2,nov,nop,noe,k)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nov,nop,noe,k
      real*8 face1(nop),face2(nop)
      dimension noe(nop)
      dimension k(nopmax,noed)
c Local
      integer i,j,l,n
      integer k0
      dimension k0(nopmax,noed)
c
c------------------------------------------------------------------------------
c
      n = 0
      do i = 1, nop
        if (face1(i).ne.face2(i)) n = n + 1
      end do
c
      if (n.eq.nop) then
        do i = 1, nop
          l = 0
          do j = noe(i), 1, -1
            l = l + 1
            k0(i,l) = k(i,j)
          end do
          do j = 1, noe(i)
            k(i,j) = k0(i,j)
          end do
        end do
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A19,175##
c
c ##ANO29,9##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      PSS.FOR    (12 October 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Make Poincare Surface Section.
c
c------------------------------------------------------------------------------
c
c ##A35,82##
c ##A39,75##
c ##A43,80##
      subroutine pss (time,h1,tol,jcen,nbod,nbig,m,x,v,s,rphy,rcrit,ngf,
     %  stat,dtflag,ngflag,opt,nce,ice,jce,force,nov,nop,noc,xv,yv,zv,
     %  noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,apot,K2,AU,MSUN,ps,id,
     %  rce,bsflag,nbclo,bclo,nstored,cce,flagce,mem,lmem,idtag,chk,
     %  lapla2,tstart)
c ##A43,80##
c ##A39,75##
c ##A35,82##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod, nbig, opt(9), stat(nbod), dtflag, ngflag
      integer nce, ice(nce), jce(nce)
      real*8 time,h1,tol,jcen(3),m(nbod),x(3,nbod),v(3,nbod)
      real*8 s(3,nbod),ngf(4,nbod),rphy(nbod),rcrit(nbod)
c
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(noc),yc(noc),zc(noc),mc(noc),dens(noc)
      integer algor
      real*8 optr(76)
      integer opti(90)
      real*8 apot(8,nopotx,nopoty,nopotz,3)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      real*8 K2,AU,MSUN
c
      integer ps(nbod)
      real*8 rce(nbod)
      character*8 id(nbod)
      integer bsflag
c
      integer nbclo,bclo(nbod)
      integer nstored
      character*107 cce(FMAX)
      integer flagce
c
      integer lmem(NMESS)
      character*80 mem(NMESS)
c
c ##A35,83##
      integer idtag(nbod)
c ##A35,83##
      external force
c ##A39,74##
      real*8 chk(3,nbod)
c ##A39,74##
c ##A43,78##
      integer lapla2(nbod)
      real*8 tstart
c ##A43,78##
c
c Local
      integer iback(nbod),index(nbod),ibs(nce),jbs(nce)
      integer j,k,nbs,nbsbig,statbs(2)
      real*8 tlocal,hlocal,hdid,tmp0
      real*8 mbs(2),xbs(6),vbs(6),sbs(6)
      real*8 rcritbs(2),rcebs(2),rphybs(2)
      real*8 ngfbs(8),x0(6),v0(6)
      character*8 idbs(2)
c
      integer statps(nbod)
      real*8 mps(nbod),xps(3,nbod),vps(3,nbod),sps(3,nbod)
      real*8 rcritps(nbod),rceps(nbod),rphyps(nbod)
      character*8 idps(nbod)
      integer nps
      real*8 psflag(2)
      integer j2,int
      real*8 h0
      real*8 err,errx,erry,errz
c ##A39,73##
      real*8 chks(3,nbod)
c ##A39,73##
c ##A43,79##
      integer lapla2s(nbod)
c ##A43,79##
c
c------------------------------------------------------------------------------
c
      h0 = h1 * .5d0
c
      nbs = 2
      nbsbig = 1
      mbs(1) = m(1)
      if (algor.eq.11.or.algor.eq.5) mbs(1) = m(1) + m(2)
      sbs(1) = s(1,1)
      sbs(2) = s(2,1)
      sbs(3) = s(3,1)
c
      xbs(1) = x(1,1)
      xbs(2) = x(2,1)
      xbs(3) = x(3,1)
      vbs(1) = v(1,1)
      vbs(2) = v(2,1)
      vbs(3) = v(3,1)
      rcebs(1) = rceps(1)
      rphybs(1) = rphyps(1)
      statbs(1) = statps(1)
      rcritbs(1) = rcritps(1)
      idbs(1) = id(1)
c
c Put data for close-encounter bodies into local arrays for use with BS routine
      nps = 0
      do j = 2, nbod
        if (ps(j).ne.0) then
          nps = nps + 1
          mps(nps)   = m(j)
          xps(1,nps) = x(1,j)
          xps(2,nps) = x(2,j)
          xps(3,nps) = x(3,j)
          vps(1,nps) = v(1,j)
          vps(2,nps) = v(2,j)
          vps(3,nps) = v(3,j)
          sps(1,nps) = s(1,j)
          sps(2,nps) = s(2,j)
          sps(3,nps) = s(3,j)
          rceps(nps) = rce(j)
          rphyps(nps) = rphy(j)
          statps(nps) = stat(j)
          rcritps(nps) = rcrit(j)
          idps(nps) = id(j)
          index(nps) = j
          iback(j) = nps
c ##A39,72##
          chks(1,nps) = chk(1,j)
          chks(2,nps) = chk(2,j)
          chks(3,nps) = chk(3,j)
c ##A39,72##
        end if
      end do
c
      do k = 1, nce
        ibs(k) = iback(ice(k))
        jbs(k) = iback(jce(k))
      end do
c
      do j = 1, nps
        mbs(2)   = mps(j)
        xbs(4) = xps(1,j)
        xbs(5) = xps(2,j)
        xbs(6) = xps(3,j)
        vbs(4) = vps(1,j)
        vbs(5) = vps(2,j)
        vbs(6) = vps(3,j)
        sbs(4) = sps(1,j)
        sbs(5) = sps(2,j)
        sbs(6) = sps(3,j)
        rcebs(2) = rceps(j)
        rphybs(2) = rphyps(j)
        statbs(2) = statps(j)
        rcritbs(2) = rcritps(j)
        idbs(2) = idps(j)
c
        tlocal = 0.d0
c        hlocal = sign(hrec,h0)
        hlocal = sign(h0,h1)
        int = 0
c
c Begin the Bulirsch-Stoer integration
  50    continue
c          tmp0 = abs(h1) - abs(tlocal)
c          hrec = hlocal
c          if (abs(hlocal).gt.tmp0) hlocal = sign (tmp0, h1)
c
c Save old coordinates and integrate
c ##A38,49##
          call mco_iden (time,jcen,nbs,0,h0,mbs,xbs,vbs,x0,v0,ngf,
     %      ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,49##
c
          if (bsflag.eq.0) then
c ##A35,63##
c ##A39,22## 
            call mdt_bs2 (time,hlocal,hdid,tol,jcen,nbs,nbsbig,mbs,xbs,
     %        vbs,sbs,rphybs,rcritbs,ngfbs,statbs,dtflag,ngflag,opt,nce,
     %        ibs,jbs,force,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,
     %        zc,optr,opti,algor,apot,K2,AU,MSUN,idtag,chks,lapla2s,
     %        tstart)
          else if (bsflag.eq.1) then
            call mdt_bs1 (time,hlocal,hdid,tol,jcen,nbs,nbsbig,mbs,xbs,
     %        vbs,sbs,rphybs,rcritbs,ngfbs,statbs,dtflag,ngflag,opt,nce,
     %        ibs,jbs,force,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,xc,yc,
     %        zc,optr,opti,algor,apot,K2,AU,MSUN,idtag,chks,lapla2s,
     %        tstart)
c ##A39,22## 
c ##A35,63##
          end if
c
          tlocal = tlocal + hdid
c
          psflag(1) = sign(1.d0,optr(29)*x0(4)+optr(30)*x0(5)
     %      +optr(31)*x0(6)+optr(32))
          psflag(2) = sign(1.d0,optr(29)*xbs(4)+optr(30)*xbs(5)
     %      +optr(31)*xbs(6)+optr(32))
c
          if (psflag(1)*psflag(2).le.0) then
            int = int + 1
            errx = dabs((x0(4)-xbs(4))/xbs(4))
            erry = dabs((x0(5)-xbs(5))/xbs(5))
            errz = dabs((x0(6)-xbs(6))/xbs(6))
            if (dabs(x0(4)-xbs(4)).lt.TINY) errx = 0.d0
            if (dabs(x0(5)-xbs(5)).lt.TINY) erry = 0.d0
            if (dabs(x0(6)-xbs(6)).lt.TINY) errz = 0.d0
            err  = dsqrt(errx*errx+erry*erry+errz*errz)
            if (err.le.optr(33)) goto 51
            if (int.gt.opti(46)) call mio_err (23,mem(81),lmem(81),
     %        mem(148),lmem(148),id(index(j)),8,' ',1)
            hlocal = hdid * .5d0
            tlocal = tlocal - hdid
c ##A38,50##
            call mco_iden (time,jcen,nbs,0,h0,mbs,x0,v0,xbs,vbs,ngf,
     %        ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,50##
          end if
c
c If necessary, continue integrating objects undergoing close encounters
c        if ((tlocal - h1)*h1.lt.0) goto 50
        goto 50
c
 51     continue
        x(1,index(j)) = xbs(4)
        x(2,index(j)) = xbs(5)
        x(3,index(j)) = xbs(6)
        v(1,index(j)) = vbs(4)
        v(2,index(j)) = vbs(5)
        v(3,index(j)) = vbs(6)
c
        call bcloo (nbclo,bclo,index(j),nbod,j2,flagce)
c ##A33,9##
c ##E19,20##
        call mio_cestored2 (nbod,m,j2,opt(4),time+tlocal,x,v,nstored,
     %    bclo,cce,'p',0,algor,optr)
c ##E19,20##
c ##A33,9##
c
      end do
c
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##ANO29,9##
c
c ##ANO29,15##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      JC.FOR    (12 October 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Calculate relative Jacobi Constant error.
c
c------------------------------------------------------------------------------
c
c ##A38,113##
      subroutine jc (nbod,j,algor,opti,optr,mem,lmem,id,xh,vh,m,tstart,
     %  time,jcen,ngf,ngflag,opt,maxjc,nov,nop,noc,xv,yv,zv,noe,kkk,
     %  dens,mc,xc,yc,zc,K2,AU,MSUN)
c ##A38,113##
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod,j,algor,ngflag
      real*8 optr(76)
      real*8 xh(3,nbod),vh(3,nbod),m(nbod),time,tstart
      real*8 maxjc
      integer lmem(NMESS)
      character*80 mem(NMESS)
      character*8 id(nbod)
      real*8 ngf(4,nbod),jcen(3)
      integer opt(9)
      integer opti(90)
c ##A38,114##
      real*8 K2,AU,MSUN
c ##A38,114##
c
      integer nov,nop,noc,noe,kkk
      real*8 xv(novmax),yv(novmax),zv(novmax)
      real*8 xc(nocen),yc(nocen),zc(nocen),mc(nocen),dens(nocen)
      dimension noe(nopmax)
      dimension kkk(nopmax,noed)
c
c Local
      real*8 djc,nn,mi,temp,a,r,v2,r1,r2,errc
      real*8 x(3,nbod),v(3,nbod)
      real*8 Upot,vpot
      real*8 s_1, s2
      integer novl,nopl,noel,kl
      real*8 xl(novmax),yl(novmax),zl(novmax)
      integer ilay,l0,j1
      real*8 vx,vy,vz,del,inc
      real*8 dx,dy,dz
      dimension noel(nopmax)
      dimension kl(nopmax,noed)
      integer i0
      integer year,month
      real*8 t1
      character*46 fstop
      character*6 tstring
c
c------------------------------------------------------------------------------
c
      djc = 0.d0
c
      if (optr(35).eq.0.or.(j.ge.opti(47).and.j.le.opti(48))) goto 123
c
      temp = m(1)
      if (algor.eq.11.or.algor.eq.5) temp = temp + m(2)
c
c      if (algor.ge.13) then
        temp = temp + m(j)
      if (algor.ge.13) then
        nn = optr(6)*optr(6)
      else
        call mco_x2a (temp,xh(1,j),xh(2,j),xh(3,j),vh(1,j),vh(2,j),
     %    vh(3,j),a,r,v2)
        if (a.le.0) a = r
        nn = temp / (a*a*a)
        mi = m(2)/(m(1)+m(2))
      end if
c
c ##A38,54##
      call mco_h2ast (time,jcen,j,j,dsqrt(nn),m,xh,vh,x,v,ngf,
     %  ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,54##
c
      del = 1.d0 / opti(21)
c central point (origin)
      xl(1) = 0.0
      yl(1) = 0.0
      zl(1) = 0.0
c
      if (algor.ge.13) then
          vpot = 0.d0
c
c------------------------------------------------------------------------------
c
c polyhedron method
          if (algor.eq.13.or.algor.eq.16.or.algor.eq.19) then
            if (opti(22).eq.0.and.opti(21).eq.1) then
              call polyhedron2 (nov,nop,xv,yv,zv,noe,kkk,
     %          dens(opti(21)),x(1,j),x(2,j),x(3,j),vpot,K2)
            else
              do i0 = 1, nop
                l0 = 1
c compute new vertices
                do ilay = 1, opti(21)
                  inc = del * ilay
                  do j1 = 1, noe(i0)
                    l0 = l0 + 1
                    xl(l0) = xv(kkk(i0,j1)) * inc
                    yl(l0) = yv(kkk(i0,j1)) * inc
                    zl(l0) = zv(kkk(i0,j1)) * inc
                  enddo
                enddo
                novl = l0
c compute new faces
                l0 = 1
c compute top face of pyramid
                do j1 = 1, noe(i0)
                  kl(l0,j1) = j1 + 1
                enddo
                noel(l0) = noe(i0)
c compute lateral faces of pyramid
                do j1 = 1, noe(i0)-1
                  l0 = l0 + 1
                  kl(l0,1) = 1
                  kl(l0,2) = j1 + 2
                  kl(l0,3) = j1 + 1
                  noel(l0) = 3
                enddo
c compute last lateral face of pyramid
                l0 = l0 + 1
                kl(l0,1) = 1
                kl(l0,2) = 2
                kl(l0,3) = noe(i0) + 1
                noel(l0) = 3
c compute pyramid's potential
                nopl = l0
                call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %            dens(1),x(1,j),x(2,j),x(3,j),vpot,K2)
c compute faces of pyramidal frustums
                do ilay = 2, opti(21)
                  l0 = 1
c compute bottom face (reverse)
                  do j1 = 1, noe(i0)
                    kl(l0,j1) = (ilay-2)*noe(i0) + (noe(i0)-j1) + 2
                  enddo
                  noel(l0) = noe(i0)
c compute lateral faces
                  do j1 = 1, noe(i0)-1
                    l0 = l0 + 1
                    kl(l0,1) = (ilay-2)*noe(i0) + j1 + 1
                    kl(l0,2) = kl(l0,1) + 1
                    kl(l0,3) = ((ilay-1)*noe(i0) + j1) + 2
                    kl(l0,4) = kl(l0,3) - 1
                    noel(l0) = 4
                  enddo
c compute last lateral face
                  l0 = l0 + 1
                  kl(l0,1) = (ilay-1)*noe(i0) + 1
                  kl(l0,2) = kl(l0,1) - (noe(i0)-1)
                  kl(l0,3) = ilay*noe(i0) - (noe(i0)-1) + 1
                  kl(l0,4) = ilay*noe(i0) + 1
                  noel(l0) = 4
c compute top face (no reverse)
                  l0 = l0 + 1
                  do j1 = 1, noe(i0)
                    kl(l0,j1) = (ilay-1)*noe(i0) + j1 + 1
                  enddo
                  noel(l0) = noe(i0)
c compute pyramidal frustum's potential
                  nopl = l0
                  call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %              dens(ilay),x(1,j),x(2,j),x(3,j),vpot,K2)
                enddo
              enddo
            end if
            Upot = -vpot
c
c------------------------------------------------------------------------------
c
c mascon method
          else if (algor.eq.14.or.algor.eq.17.or.algor.eq.20) then
            do j1 = 1, noc
              dx = x(1,j) - xc(j1)
              dy = x(2,j) - yc(j1)
              dz = x(3,j) - zc(j1)
              s2 = dx*dx + dy*dy + dz*dz
              s_1 = 1.d0 / sqrt(s2)
              temp = s_1 * mc(j1)
              vpot = vpot - temp
            end do
            Upot = vpot
c
c------------------------------------------------------------------------------
c
c hybrid method
          else if (algor.eq.15.or.algor.eq.18.or.algor.eq.21
     %      .or.algor.eq.22) then
            temp = x(1,j)*x(1,j) + x(2,j)*x(2,j) + x(3,j)*x(3,j)
c newtonian method
            if (temp.ge.optr(7)) then
              r1 = (x(1,j)+mi)*(x(1,j)+mi)+x(2,j)*x(2,j)
     %          +x(3,j)*x(3,j)
              r2 = (x(1,j)-(1.d0-mi))*(x(1,j)-(1.d0-mi))
     %          +x(2,j)*x(2,j)+x(3,j)*x(3,j)
              Upot = (1.d0-mi)/r1 + mi/r2
              Upot = -Upot
            else
c mascon method
              if (temp.ge.optr(8)) then
                do j1 = 1, noc
                  dx = x(1,j) - xc(j1)
                  dy = x(2,j) - yc(j1)
                  dz = x(3,j) - zc(j1)
                  s2 = dx*dx + dy*dy + dz*dz
                  s_1 = 1.d0 / sqrt(s2)
                  temp = s_1 * mc(j1)
                  vpot = vpot - temp
                end do
                Upot = vpot
c
              else
c polyhedron method
                if (opti(22).eq.0.and.opti(21).eq.1) then
                  call polyhedron2 (nov,nop,xv,yv,zv,noe,kkk,
     %              dens(opti(21)),x(1,j),x(2,j),x(3,j),vpot,K2)
                else
                  do i0 = 1, nop
                    l0 = 1
c compute new vertices
                    do ilay = 1, opti(21)
                      inc = del * ilay
                      do j1 = 1, noe(i0)
                        l0 = l0 + 1
                        xl(l0) = xv(kkk(i0,j1)) * inc
                        yl(l0) = yv(kkk(i0,j1)) * inc
                        zl(l0) = zv(kkk(i0,j1)) * inc
                      enddo
                    enddo
                    novl = l0
c compute new faces
                    l0 = 1
c compute top face of pyramid
                    do j1 = 1, noe(i0)
                      kl(l0,j1) = j1 + 1
                    enddo
                    noel(l0) = noe(i0)
c compute lateral faces of pyramid
                    do j1 = 1, noe(i0)-1
                      l0 = l0 + 1
                      kl(l0,1) = 1
                      kl(l0,2) = j1 + 2
                      kl(l0,3) = j1 + 1
                      noel(l0) = 3
                    enddo
c compute last lateral face of pyramid
                    l0 = l0 + 1
                    kl(l0,1) = 1
                    kl(l0,2) = 2
                    kl(l0,3) = noe(i0) + 1
                    noel(l0) = 3
c compute pyramid's potential
                    nopl = l0
                    call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %                dens(1),x(1,j),x(2,j),x(3,j),vpot,K2)
c compute faces of pyramidal frustums
                    do ilay = 2, opti(21)
                      l0 = 1
c compute bottom face (reverse)
                      do j1 = 1, noe(i0)
                        kl(l0,j1) = (ilay-2)*noe(i0) + (noe(i0)-j1) + 2
                      enddo
                      noel(l0) = noe(i0)
c compute lateral faces
                      do j1 = 1, noe(i0)-1
                        l0 = l0 + 1
                        kl(l0,1) = (ilay-2)*noe(i0) + j1 + 1
                        kl(l0,2) = kl(l0,1) + 1
                        kl(l0,3) = ((ilay-1)*noe(i0) + j1) + 2
                        kl(l0,4) = kl(l0,3) - 1
                        noel(l0) = 4
                      enddo
c compute last lateral face
                      l0 = l0 + 1
                      kl(l0,1) = (ilay-1)*noe(i0) + 1
                      kl(l0,2) = kl(l0,1) - (noe(i0)-1)
                      kl(l0,3) = ilay*noe(i0) - (noe(i0)-1) + 1
                      kl(l0,4) = ilay*noe(i0) + 1
                      noel(l0) = 4
c compute top face (no reverse)
                      l0 = l0 + 1
                      do j1 = 1, noe(i0)
                        kl(l0,j1) = (ilay-1)*noe(i0) + j1 + 1
                      enddo
                      noel(l0) = noe(i0)
c compute pyramidal frustum's potential
                      nopl = l0
                      call polyhedron2 (novl,nopl,xl,yl,zl,noel,kl,
     %                  dens(ilay),x(1,j),x(2,j),x(3,j),vpot,K2)
                    enddo
                  enddo
                end if
                Upot = -vpot
              end if
            end if
          end if
c
      else
        r1 = (x(1,j)+mi)*(x(1,j)+mi)+x(2,j)*x(2,j)
     %    +x(3,j)*x(3,j)
        r2 = (x(1,j)-(1.d0-mi))*(x(1,j)-(1.d0-mi))
     %    +x(2,j)*x(2,j)+x(3,j)*x(3,j)
        Upot = (1.d0-mi)/r1 + mi/r2
        Upot = -Upot
      end if
c
      djc = -nn * (x(1,j) * x(1,j) + x(2,j) * x(2,j)) + 2.d0 * Upot
     %  -v(1,j)*v(1,j) -v(2,j)*v(2,j) -v(3,j)*v(3,j) -optr(27)
c
c      else
c        r1 = x*x+y*y+z*z
c        r2 = (x2-x)*(x2-x)+(y2-y)*(y2-y)+(z2-z)*(z2-z)
c        temp = temp + m(j)
c        call mco_x2a (temp,x,y,z,u,v,w,a,r,v2)
c        if (a.le.0) a = r
c        nn = dsqrt(temp / (a*a*a))
c        mi = m(2)/(m(1)+m(2))
c        djc = 2.d0 * ((1.d0-mi)/r1+mi/r2) + 2.0 * nn * (x * v - y * u)
c     %    -u*u -v*v -w*w -optr(27)
c      end if
c
      errc = dabs(djc/optr(27))
      if (errc.gt.maxjc) maxjc = errc
c
      if (errc.ge.optr(35)) then
        if (opt(3).eq.1) then
          fstop = '(/,2a,/,a,1x,1p1e12.5,0p,1x,i10,1x,i2,1x,f4.1)'
          call mio_jd2y (time,year,month,t1)
          write (23,fstop) mem(121)(1:lmem(121)),
     %      mem(149)(1:lmem(149)),id(j)(1:8),errc,year,month,t1
          write (*,fstop) mem(121)(1:lmem(121)),
     %      mem(149)(1:lmem(149)),id(j)(1:8),errc,year,month,t1
c Otherwise...
        else
          if (opt(3).eq.3) then
            tstring = mem(2)
            fstop = '(/,2a,/,a,1x,1p1e12.5,0p,1x,f14.3,a)'
            t1 = (time - tstart) / 365.25d0
          else
            tstring = mem(1)
            fstop = '(/,2a,/,a,1x,1p1e12.5,0p,1x,f14.1,a)'
            if (opt(3).eq.0) t1 = time
            if (opt(3).eq.2) t1 = time - tstart
          end if
          write (23,fstop) mem(121)(1:lmem(121)),
     %      mem(149)(1:lmem(149)),id(j)(1:8),errc,t1,tstring
          write (*,fstop) mem(121)(1:lmem(121)),
     %      mem(149)(1:lmem(149)),id(j)(1:8),errc,t1,tstring
        end if
      end if
c
 123  continue
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##ANO29,15##
c
c ##ANO29,25##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      POLYHEDRON2.FOR    (FEG   13 October 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c------------------------------------------------------------------------------
c
      subroutine polyhedron2 (nov,nop,x2,y2,z2,noe,k,d,xp,yp,zp,
     %  v,K2)
c
c------------------------------------------------------------------------------
c
c******************************************************************************
c CHANGES IN VERSION 3 (23 July 2013)
c******************************************************************************
c
c Author:
c
c Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c O polyhedron.f foi modificado.
c As alterações foram feitas através dos marcadores ##Am##.
c
c-------------------------------------------------------------------------------
c
c Copyright notice for SEG distribution:
c
c Copyright (c) 2012 by the Society of Exploration Geophysicists.
c For more information, go to http://software.seg.org/2012/0001 .
c You must read and accept usage terms at:
c http://software.seg.org/disclaimer.txt before use.
c
c-------------------------------------------------------------------------------


c	PROGRAMM "polyhedron.f"
c
c	D.Tsoulis                        Thessaloniki, June 2010
c	
c
c	This programm computes the potential, its first
c	and second derivatives of a homogenous polyhedron
c	according to Petrovic (J of G, 1996). The triple
c	integrals of V, Vi and Vij (i,j=1..3) are transformed
c	twice by means of the divergence theorem of Gauss. The
c	transission from volume integrals into line integrals
c	is accomplished in two steps as follows:
c
c	                      GAUSS
c	1. Volume Integral  ----------> Surface Integral
c	2. Surface Integral ----------> Line Integral
c
c
c	Literature:
c	-----------
c	1. Petrovic S. (1996): Determination of the potential of
c	     homogeneous polyhedral bodies using line integrals, 
c	     Journal of Geodesy 71, 44 - 52.
c	2. Werner R.A. and D.J. Scheeres (1997): Exterior gravitation
c	     of a polyhedron derived and compared with harmonic and
c	     mascon gravitation representations of asteroid 4769
c	     Castalia, Celestial Mechanics and Dynamical Astronomy 65,
c	     313 - 344.
c
c	One has to calculate:
c	--------------------
c
c	1. h(P)       : The distance of point P from the plane p (PP')
c	2. s(P)       : -1, 1
c	3. h(PQ)      : The distance of P' from line segment pq (P'P'')
c 	4. s(PQ)      : -1, 1
c	5. cos(Np,ei) : Np is the plane normal to plane p
c	6. cos(npq,ei): npq is the line normal to line segment pq
c	7. LNpq, ANpq : (Transcendental Functions of the
c	                coordinates of the body's vertices)
c
c
c	ALL of the above quantities are computed automatically
c	using only the following three files:
c	1. file 'xyz' which contains the coordinates x(i), y(i) and
c	   z(i) of the i vertices of the polyhedron
c	2. file 'dat' is a line whith (nop) elements, which declare
c	   the number of edges building each of the (nop) planes,
c	   in the same order that they appear in file 'topology'
c	3. file 'topology' where the number of vertices belonging
c 	   at each facet is given, in such an order that the plane
c	   normal is always pointing outside the body
c
c	EXAMPLES FOR THESE FILES
c	------------------------
c
c	file 'xyz':
c
c	  10  10  20
c       30  10  20
c       30  20  20
c       10  20  20
c       10  10  10
c	  30  10  10
c	  30  20  10
c	  10  20  10
c
c	file 'topology':
c
c	  1 2 4 
c	  2 3 4
c	  6 5 8 7
c	  8 5 1 4
c	  6 7 3 2
c	  5 6 2 1
c	  7 8 4 3
c
c	file 'dat':
c
c	  3 3 4 4 4 4 4
c
c
c

c
c	IMPORTANT NOTICE
c	----------------
c
c	The origin of the reference coordinate system (ei) is 
c	situated at P, i.e.:  
c
c	                      Xp = Yp = Zp = 0
c
c	Thus, the coordinates of all vertices of the polyhedron 
c	in file 'xyz' refer to P.
c
c


c
c
c	parameter       stands for
c       --------------------------
c	nop         :   Number of planes
c	nov         :   Number of vertices
c	noe(i)      :   Number of edges (varying from facet to
c			facet according to the information given
c			in file 'dat'. As starting value for 
c			parameter (noe) we choose a conveniently
c			big value (noed), sufficient for our matrices 
c			definitions
c
c
c
c     Parameters 'nop' and 'nov' have to be edited by the user
c
c
c


	implicit real*8 (a-h,o-z)
c ##A5##
        include 'mercury.inc'
c      include 'polyhedron.inc'
c
c Input/Output
c      character*80 infile(4),outfile(1),dumpfile(2),mem(NMESS)
c      integer nov,nop,opt(1),lmem(NMESS)
c      integer*4 nograd,nflush,opflag,l
c      real*8 d0,d,T,omg,x2(novmax),y2(novmax),z2(novmax),xp,yp,zp,J
        integer nov,nop
c ##A19,132##
        real*8 d,x2(nov),y2(nov),z2(nov),xp,yp,zp,gc
c ##A19,132##
c ##AN28,28##
        real*8 K2
c ##AN28,28##
c
c	Edit number of planes (nop) and number of vertices (nov)
c
c ##A1##
c	parameter(nop=7,nov=8,noed=100)


	dimension e(3,3)
c ##A19,133##
	dimension noe(nop)
c ##A19,133##
	dimension x(novmax),y(novmax),z(novmax),h(nopmax),s(nopmax),
     %  cs(nopmax,3)
	dimension xo(nopmax),yo(nopmax),zo(nopmax)
	dimension xx(nopmax),yy(nopmax),zz(nopmax)
	dimension xxx(nopmax,noed),yyy(nopmax,noed),zzz(nopmax,noed)
c ##A19,134##
	dimension k(nopmax,noed)
c ##A19,134##
	dimension g(nopmax,noed,3)
	dimension plnorm(nopmax,3),segnorm(nopmax,noed,3)
	dimension dcnp(nopmax,3),dcnpq(nopmax,noed,3)
	dimension hh(nopmax,noed),ss(nopmax,noed)
	dimension cspq(nopmax,noed,3)
	dimension vij(3,3)

	snorm(xipq,yipq,zipq)=dsqrt(xipq*xipq+yipq*yipq+zipq*zipq)
	fln(aa,bb,cc,dd)=dlog((aa+bb)/(cc+dd))
	fan(ee,f,gg,t,yf,w)=datan((ee*t)/(f*w))-datan((ee*gg)/(f*yf))

c ##A2##
c	open(10,file='xyzposnew',form='formatted',status='unknown')
c	open(11,file='topoaut',form='formatted',status='unknown')
c	open(12,file='dataut',form='formatted',status='unknown')
c      open(13,file='polaut2_out',form='formatted',access='append')

c ##A3## chama a subrotina mio_in para verificar os nomes e as existências dos arquivos de entrada (.in), saída (.out) e despejo (.dmp), criar os arquivos de saída e despejo e prosseguir com a integração no ponto onde ela foi interrompida
c      call mio_in (infile,outfile,dumpfile,mem,lmem,nov,nop,
c     %  nograd,nflush,opt,d0,T,x2,y2,z2,noe,k,opflag)

c ##A19##
c	read(12,*) (noe(j),j=1,nop)



c ##A20## converte a densidade d de g/cm^3 para kg/km^3. OBS: os vértices devem estar em quilômetros
c        d=d0*(1000.0d0*100.0d0)**3/1000.0d0
c ##A21## encontra a velocidade de rotação omg do asteróide tendo o seu período de rotação T
c        omg=2.0d0*pi/(T*3600.0d0)

c ##A22## abre o arquivo dos pontos em que se pretende calcular o potencial e suas derivadas (13)
c 450  open  (10+3, file=infile(3), status='old', err=450)
c ##A23## posiciona a função read para ler o ponto inicial do próximo intervalo a partir do qual se pretendia calcular o potencial e suas derivadas quando a integração foi interrompida
c      opflag = opflag + 1
c      do 20 l=0,opflag-1
c        read(10+3,*) xp,yp,zp
c  20  continue

c ##A24##
c	do 20 i=1,nov
c	read(10,*) x(i),y(i),z(i)
c20	continue


c	do 30 i=1,nop
c	read(11,*) (k(i,j),j=1,noe(i))
c30	continue


c
c	Vector basis (ei) situated at P
c

	e(1,1)=1
	e(1,2)=0
	e(1,3)=0
	e(2,1)=0
	e(2,2)=1
	e(2,3)=0
	e(3,1)=0
	e(3,2)=0
	e(3,3)=1


c
c	Constants
c
c ##A18##
c	gc=6.67259e-08
c	d=2.67
c	pi=4.*atan(1.)

c ##A25## lê os pontos em que se pretende calcular o potencial e suas derivadas iniciando sempre do sucessor do último ponto do último intervalo em que a integração parou
c      nstored = 0
c      do 2013 l=opflag,nograd-1
c	read(10+3,*,end=2020) xp,yp,zp

c ##A19,135##
        gc = K2
c ##A19,135##
c ##A26## no programa original o potencial e suas derivadas são sempre calculados na origem, isto é, no ponto de coordenadas (0,0,0). Logo, para calcularmos o potencial e suas derivadas em qualquer outro ponto P devemos ter nossa origem nesse novo ponto P e para isso basta transladarmos todas as coordenadas dos pontos do poliedro, subtraindo-as das coordenadas do ponto P
	do 2014 i=1,nov
	x(i)=x2(i)-xp
        y(i)=y2(i)-yp
        z(i)=z2(i)-zp
2014	continue
c
c
c	Building vectors Gij // Equation (17)
c
c

	v=0
c	vx=0
c	vy=0
c	vz=0
	do 100 i=1,nop
c	do 80 i=1,nop
	do 70 j=1,noe(i)

	if(j.eq.noe(i)) then 

	g(i,j,1)=x(k(i,1))-x(k(i,j))
	g(i,j,2)=y(k(i,1))-y(k(i,j))
	g(i,j,3)=z(k(i,1))-z(k(i,j))


	else


	g(i,j,1)=x(k(i,j+1))-x(k(i,j))
	g(i,j,2)=y(k(i,j+1))-y(k(i,j))
	g(i,j,3)=z(k(i,j+1))-z(k(i,j))

	end if


70	continue

c
c
c	Computation of plane Normals (Np) // Equation (18)
c
c

c	do 80 i=1,nop
	call cross (g(i,1,1),g(i,1,2),g(i,1,3),g(i,2,1),g(i,2,2),
     $g(i,2,3),plnorm(i,1),plnorm(i,2),plnorm(i,3))
	qnorm=snorm(plnorm(i,1),plnorm(i,2),plnorm(i,3))
	plnorm(i,1)=plnorm(i,1)/qnorm
	plnorm(i,2)=plnorm(i,2)/qnorm
	plnorm(i,3)=plnorm(i,3)/qnorm


c
c	Direction cosines computation
c
c
c	Notice: We computed a normed vector, i.e. Np's 
c	        x, y and z components are at the same time
c	        its direction cosines with the three axes.
c

	dcnp(i,1)=plnorm(i,1)
	dcnp(i,2)=plnorm(i,2)
	dcnp(i,3)=plnorm(i,3)


c80	continue



c
c
c	Computation of line segment normals (npq) // Equation (19)
c
c

c	do 90 i=1,nop
	do 90 j=1,noe(i)
	call cross (g(i,j,1),g(i,j,2),g(i,j,3),plnorm(i,1),
     $plnorm(i,2),plnorm(i,3),segnorm(i,j,1),
     $segnorm(i,j,2),segnorm(i,j,3))
	qnorm=snorm(segnorm(i,j,1),segnorm(i,j,2),segnorm(i,j,3))
	segnorm(i,j,1)=segnorm(i,j,1)/qnorm
	segnorm(i,j,2)=segnorm(i,j,2)/qnorm
	segnorm(i,j,3)=segnorm(i,j,3)/qnorm


c
c	Direction cosines computation
c
c
c	Notice: We are computing a normed vector, i.e. npq's 
c	        x, y and z components are at the same time
c	        its direction cosines with the three axes.
c
	dcnpq(i,j,1)=segnorm(i,j,1)
	dcnpq(i,j,2)=segnorm(i,j,2)
	dcnpq(i,j,3)=segnorm(i,j,3)


90	continue



c
c
c	cos(Np,ei), cos(npq,ei)
c
c
c	cs(i,j) = dcnp(i,j)
c
c	and
c
c	cspq(i,j,m) = dcnpq(i,j,m), m = 1,2,3
c
c

c	do 23 i=1,nop
	qnorm1=snorm(plnorm(i,1),plnorm(i,2),plnorm(i,3))
	do 23 j=1,3
	qnorm2=snorm(e(j,1),e(j,2),e(j,3))
	call dot (plnorm(i,1),plnorm(i,2),plnorm(i,3),e(j,1),e(j,2),
     $e(j,3),dotnpi)
	cs(i,j)=dotnpi/(qnorm1*qnorm2)


23	continue
	
c	do 24 i=1,nop
	do 24 j=1,noe(i)
 	do 24 m=1,3
	qnorm1=snorm(segnorm(i,j,1),segnorm(i,j,2),segnorm(i,j,3))
	qnorm2=snorm(e(m,1),e(m,2),e(m,3))
	call dot (segnorm(i,j,1),segnorm(i,j,2),segnorm(i,j,3),e(m,1),
     $e(m,2),e(m,3),dotnpq)
	cspq(i,j,m)=dotnpq/(qnorm1*qnorm2)


24	continue

c
c
c	Distances of P from planes Sp ( h(i) ) 
c	by subroutine 'planedist'
c
c	xo(i), yo(i) and zo(i) are the intersections of Sp(i)
c	with axes x, y and z respectively
c
c	and 
c
c	plane normal orientation ( s(i) ) // Equation (20)
c
c

c	do 60 i=1,nop
	call planedist (x,y,z,k(i,1),k(i,2),k(i,3),h(i),xo(i),yo(i),
     $zo(i))


c60	continue



c	do 41 i=1,nop
	call dot (plnorm(i,1),plnorm(i,2),plnorm(i,3),-x(k(i,1)),
     $-y(k(i,1)),-z(k(i,1)),plnrmor)
	if (plnrmor.gt.0) then
	s(i)=-1
	else if (plnrmor.lt.0) then
	s(i)=1
	else if (plnrmor.eq.0) then
	s(i)=0
	end if


c41	continue





c
c
c	Computation of the projections of P on the 'p' planes
c	of the polyhedron. [P'(x',y',z')]
c
c	xx(i), yy(i), zz(i) // Equation (21)
c
c

c	do 31 i=1,nop

	if (xo(i).ge.0.and.yo(i).ge.0.and.zo(i).ge.0) then
	xx(i)=abs(dcnp(i,1)*h(i))
	yy(i)=abs(dcnp(i,2)*h(i))
	zz(i)=abs(dcnp(i,3)*h(i))

	else if (xo(i).lt.0.and.yo(i).lt.0.and.zo(i).lt.0) then

	 if (dcnp(i,1).gt.0) then
	 xx(i)=-dcnp(i,1)*h(i)
	 else
	 xx(i)=dcnp(i,1)*h(i)
	 end if

	 if (dcnp(i,2).gt.0) then
	 yy(i)=-dcnp(i,2)*h(i)
	 else
	 yy(i)=dcnp(i,2)*h(i)
	 end if

	 if (dcnp(i,3).gt.0) then
	 zz(i)=-dcnp(i,3)*h(i)
	 else
	 zz(i)=dcnp(i,3)*h(i)
	 end if

	else if (xo(i).lt.0.and.yo(i).lt.0) then

	 if (dcnp(i,1).gt.0) then
	 xx(i)=-dcnp(i,1)*h(i)
	 else
	 xx(i)=dcnp(i,1)*h(i)
	 end if

	 if (dcnp(i,2).gt.0) then
	 yy(i)=-dcnp(i,2)*h(i)
	 else
	 yy(i)=dcnp(i,2)*h(i)
	 end if

	zz(i)=abs(dcnp(i,3)*h(i))

	else if (yo(i).lt.0.and.zo(i).lt.0) then
	xx(i)=abs(dcnp(i,1)*h(i))

	 if (dcnp(i,2).gt.0) then
	 yy(i)=-dcnp(i,2)*h(i)
	 else
	 yy(i)=dcnp(i,2)*h(i)
	 end if

	 if (dcnp(i,3).gt.0) then
	 zz(i)=-dcnp(i,3)*h(i)
	 else
	 zz(i)=dcnp(i,3)*h(i)
	 end if

	else if (xo(i).lt.0.and.zo(i).lt.0) then

	 if (dcnp(i,1).gt.0) then
	 xx(i)=-dcnp(i,1)*h(i)
	 else
	 xx(i)=dcnp(i,1)*h(i)
	 end if

	yy(i)=abs(dcnp(i,2)*h(i))

	 if (dcnp(i,3).gt.0) then
	 zz(i)=-dcnp(i,3)*h(i)
	 else
	 zz(i)=dcnp(i,3)*h(i)
	 end if

	else if (xo(i).lt.0) then

	 if (dcnp(i,1).gt.0) then
	 xx(i)=-dcnp(i,1)*h(i)
	 else
	 xx(i)=dcnp(i,1)*h(i)
	 end if

	yy(i)=abs(dcnp(i,2)*h(i))
	zz(i)=abs(dcnp(i,3)*h(i))

	else if (yo(i).lt.0) then
	xx(i)=abs(dcnp(i,1)*h(i))

	 if (dcnp(i,2).gt.0) then
	 yy(i)=-dcnp(i,2)*h(i)
	 else
	 yy(i)=dcnp(i,2)*h(i)
	 end if

	zz(i)=abs(dcnp(i,3)*h(i))

	else if (zo(i).lt.0) then
	xx(i)=abs(dcnp(i,1)*h(i))
	yy(i)=abs(dcnp(i,2)*h(i))

	 if (dcnp(i,3).gt.0) then
	 zz(i)=-dcnp(i,3)*h(i)
	 else
	 zz(i)=dcnp(i,3)*h(i)
	 end if

	end if


c31	continue




c
c	segment normal orientation	
c
c	senrmor = npq (dot) Gpq(ij-->P') // Equation (22)
c

c	do 42 i=1,nop
	do 42 j=1,noe(i)
	call dot (segnorm(i,j,1),segnorm(i,j,2),segnorm(i,j,3),
     $xx(i)-x(k(i,j)),yy(i)-y(k(i,j)),zz(i)-z(k(i,j)),senrmor)
	if (abs(senrmor).lt.1e-10) then
	ss(i,j)=0
	go to 42
	else if (senrmor.gt.0) then
	ss(i,j)=-1
	else if (senrmor.lt.0) then
	ss(i,j)=1
	else if (senrmor.eq.0) then
	ss(i,j)=0
	end if


42	continue



c
c
c	Distances of P' from line segments Gpq (hpq) 
c
c	hh(i,j)
c
c	Computation of the projections of P' on each
c	line segment Gpq, i.e. P''(x'',y''',z''')
c	by calling subroutine 'segmproj'
c
c	xxx(i,j), yyy(i,j), zzz(i,j) // Equations (23) - (25)
c
c

c	do 32 i=1,nop
	do 32 j=1,noe(i)

	if (j.eq.noe(i)) then

	if (ss(i,j).eq.0) then
	hh(i,j)=0
	xxx(i,j)=xx(i)
	yyy(i,j)=yy(i)
	zzz(i,j)=zz(i)
	go to 131
	end if

	call segmproj (x(k(i,j)),y(k(i,j)),z(k(i,j)),
     $x(k(i,1)),y(k(i,1)),z(k(i,1)),
     $xx(i),yy(i),zz(i),xseg,yseg,zseg)
	hh(i,j)=snorm(xseg-xx(i),yseg-yy(i),zseg-zz(i))


	xxx(i,j)=xseg
	yyy(i,j)=yseg
	zzz(i,j)=zseg
	go to 131

	end if

	if (ss(i,j).eq.0) then
	hh(i,j)=0
	xxx(i,j)=xx(i)
	yyy(i,j)=yy(i)
	zzz(i,j)=zz(i)
	go to 131
	end if

	call segmproj (x(k(i,j)),y(k(i,j)),z(k(i,j)),
     $x(k(i,j+1)),y(k(i,j+1)),z(k(i,j+1)),
     $xx(i),yy(i),zz(i),xseg,yseg,zseg)
	hh(i,j)=snorm(xseg-xx(i),yseg-yy(i),zseg-zz(i))


	xxx(i,j)=xseg
	yyy(i,j)=yseg
	zzz(i,j)=zseg

131	continue




32	continue



c
c
c	Computation of V and Vi
c
c

c	v=0
c	vx=0
c	vy=0
c	vz=0

c	do 100 i=1,nop

	sum1=0
	sum2=0
	singarea=0
	singsegm=0
	singvert=0
	
	do 200 j=1,noe(i)




	thisvert=0

	gpqnorm=snorm(g(i,j,1),g(i,j,2),g(i,j,3))

c	
c	check if P' lays inside the polygon Np(i)
c

	if (ss(i,j).eq.1) then
	singarea=singarea+1
	end if

c
c	check if P' lays inside the segment Gpq 
c
c	or
c
c	on the vertex (i,j)
c
c	Condition controlled is  
c
c	ss(i,j) = 0
c

	if (ss(i,j).eq.0) then



	 if(j.eq.noe(i)) then 

	 gx1=xx(i)-x(k(i,1))
	 gx2=xx(i)-x(k(i,j))
	 gy1=yy(i)-y(k(i,1))
	 gy2=yy(i)-y(k(i,j))
	 gz1=zz(i)-z(k(i,1))
	 gz2=zz(i)-z(k(i,j))

	 else  

	 gx2=xx(i)-x(k(i,j))
	 gx1=xx(i)-x(k(i,j+1))
	 gy2=yy(i)-y(k(i,j))
	 gy1=yy(i)-y(k(i,j+1))
	 gz2=zz(i)-z(k(i,j))
	 gz1=zz(i)-z(k(i,j+1))

	 end if

	 enorm1=snorm(gx1,gy1,gz1)
	 enorm2=snorm(gx2,gy2,gz2)




c
c	check for the Vertex (i,j) 
c

	  if (enorm1.eq.0) then

	  singvert=singvert+1

	  thisvert=thisvert+1

	   	if (j.eq.noe(i)) then

	   g1norm=snorm(g(i,j,1),g(i,j,2),g(i,j,3))
	   g2norm=snorm(g(i,1,1),g(i,1,2),g(i,1,3))

	call dot(-g(i,j,1),-g(i,j,2),-g(i,j,3),g(i,1,1),g(i,1,2),
     $g(i,1,3),gdot)

	     		if (gdot.eq.0) then

	     theta=pi/2

	     		else

	     theta=dacos(gdot/(g1norm*g2norm))

	     		end if

	   	else

	   g1norm=snorm(g(i,j,1),g(i,j,2),g(i,j,3))
	   g2norm=snorm(g(i,j+1,1),g(i,j+1,2),g(i,j+1,3))

	call dot(-g(i,j,1),-g(i,j,2),-g(i,j,3),g(i,j+1,1),g(i,j+1,2),
     $g(i,j+1,3),gdot)

	     		if (gdot.eq.0) then

	     theta=pi/2

	     		else

	     theta=dacos(gdot/(g1norm*g2norm))

	     		end if

	   	end if

	  end if


	  if (enorm2.eq.0) then

	  singvert=singvert+1

	  thisvert=thisvert+1

	   	if (j.eq.1) then

	   g1norm=snorm(g(i,noe(i),1),g(i,noe(i),2),g(i,noe(i),3))
	   g2norm=snorm(g(i,1,1),g(i,1,2),g(i,1,3))

	call dot(-g(i,noe(i),1),-g(i,noe(i),2),-g(i,noe(i),3),
     $g(i,1,1),g(i,1,2),g(i,1,3),gdot)
     
	     		if (gdot.eq.0) then

	     theta=pi/2

	     		else

	     theta=dacos(gdot/(g1norm*g2norm))

	     		end if

	   	else

	   g1norm=snorm(g(i,j-1,1),g(i,j-1,2),g(i,j-1,3))
	   g2norm=snorm(g(i,j,1),g(i,j,2),g(i,j,3))

	call dot(-g(i,j-1,1),-g(i,j-1,2),-g(i,j-1,3),g(i,j,1),g(i,j,2),
     $g(i,j,3),gdot)

	     		if (gdot.eq.0) then

	     theta=pi/2

	     		else

	     theta=dacos(gdot/(g1norm*g2norm))

	     		end if

	   	end if

	  end if




	      if (enorm1.lt.gpqnorm.and.enorm2.lt.gpqnorm) then

	      singsegm=singsegm+1

	      end if




	end if









c
c
c	d1, d2 (i.e. s1, s2) are the distances of P'' (projection
c	of P' on Gpq) from the segments' Gpq vertices.
c	P'' is taken
c	as the origin of a 1-dimensional local coordinate system
c	on Gpq.
c	f1, f2 (i.e. r1, r2) are the 3d-distances of the vertices 
c	of Gpq from field point P.
c
c						



	if (j.eq.noe(i)) then

	d1=snorm(xxx(i,j)-x(k(i,j)),yyy(i,j)-y(k(i,j)),
     $zzz(i,j)-z(k(i,j)))
	d2=snorm(xxx(i,j)-x(k(i,1)),yyy(i,j)-y(k(i,1)),
     $zzz(i,j)-z(k(i,1)))
	f1=snorm(x(k(i,j)),y(k(i,j)),z(k(i,j)))
	f2=snorm(x(k(i,1)),y(k(i,1)),z(k(i,1)))

	if (abs(d1-f1).lt.1e-10.and.abs(d2-f2).lt.1e-10) then
	go to 1968
	end if


	else 

	d1=snorm(xxx(i,j)-x(k(i,j)),yyy(i,j)-y(k(i,j)),
     $zzz(i,j)-z(k(i,j)))
	d2=snorm(xxx(i,j)-x(k(i,j+1)),yyy(i,j)-y(k(i,j+1)),
     $zzz(i,j)-z(k(i,j+1)))
	f1=snorm(x(k(i,j)),y(k(i,j)),z(k(i,j)))
	f2=snorm(x(k(i,j+1)),y(k(i,j+1)),z(k(i,j+1)))


	if (abs(d1-f1).lt.1e-10.and.abs(d2-f2).lt.1e-10) then
	go to 1968
	end if



	end if



c	
c	check if P'' is located inside the segment Gpq
c

	if (d1.lt.gpqnorm.and.d2.lt.gpqnorm) then
	s1=-d1
	s2=d2
	r1=f1
	r2=f2
	go to 1972
	end if

	if (d1.lt.d2) then

	s1=d1
	s2=d2
	r1=f1
	r2=f2

	else if (d2.lt.d1) then

	s1=-d1
	s2=-d2
	r1=f1
	r2=f2

	end if


	go to 1972






1968	if (d1.lt.d2) then

	s1=d1
	s2=d2
	r1=f1
	r2=f2

	else if (d2.lt.d1) then

	s1=-d1
	s2=-d2
	r1=-f1
	r2=-f2

	else if (d1.eq.d2) then

	s1=-d1
	s2=d2
	r1=-f1
	r2=f2

	end if


1972	continue


	if (h(i).eq.0) then

