	c1=0
	c2=0
	go to 1973
	end if

	c1=fln(s2,r2,s1,r1)
	c2=0

	
	go to 1973

	end if


	if (thisvert.gt.0) then
	c1=0
	else
	c1=fln(s2,r2,s1,r1)
	end if

	if (hh(i,j).eq.0) then
	c2=0
	else
	c2=fan(h(i),hh(i,j),s1,s2,r1,r2)
	end if

1973	continue

	sum1=sum1+ss(i,j)*hh(i,j)*c1
	sum2=sum2+ss(i,j)*c2



200	continue


