c ##ANO29,30##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      REN.FOR    (14 October 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Renormalisation of Lyapunov Characterist Expoent.
c
c------------------------------------------------------------------------------
c
      subroutine ren (nbod,id,x,v,optr)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nbod
      real*8 optr(76)
      real*8 x(3,nbod),v(3,nbod)
      character*8 id(nbod)
c
c Local
      integer ly(nbod)
      real*8 dinit,d,r
      integer j,j1,k,itmp
c
c------------------------------------------------------------------------------
c
      do j = 1, nbod
        ly(j) = 0
      end do
c
      do j = 2, nbod-1
        do j1 = j+1, nbod
          do k = 1, 8
            itmp = 0
            if(id(j)(k:k).ne.id(j1)(k:k)) itmp = 1
            if (itmp.eq.0) then
              if(id(j1)(k+1:k+1).eq.'-') then
                ly(j) = j1
                exit
              end if
            else
              exit
            end if
          end do
        end do
      end do
c
      dinit = dsqrt(2.d0*optr(34)*optr(34)+2.d0*optr(36)*optr(36)
     %  +2.d0*optr(37)*optr(37))
c
      do j = 2, nbod
        if (ly(j).ne.0) then
          d = dsqrt((x(1,j)-x(1,ly(j)))*(x(1,j)-x(1,ly(j)))
     %      +(x(2,j)-x(2,ly(j)))*(x(2,j)-x(2,ly(j)))
     %      +(x(3,j)-x(3,ly(j)))*(x(3,j)-x(3,ly(j)))
     %      +(v(1,j)-v(1,ly(j)))*(v(1,j)-v(1,ly(j)))
     %      +(v(2,j)-v(2,ly(j)))*(v(2,j)-v(2,ly(j)))
     %      +(v(3,j)-v(3,ly(j)))*(v(3,j)-v(3,ly(j))))
c
          r = dinit / d
          x(1,ly(j)) = x(1,j) + ((x(1,ly(j))-x(1,j)) * r)
          x(2,ly(j)) = x(2,j) + ((x(2,ly(j))-x(2,j)) * r)
          x(3,ly(j)) = x(3,j) + ((x(3,ly(j))-x(3,j)) * r)
          v(1,ly(j)) = v(1,j) + ((v(1,ly(j))-v(1,j)) * r)
          v(2,ly(j)) = v(2,j) + ((v(2,ly(j))-v(2,j)) * r)
          v(3,ly(j)) = v(3,j) + ((v(3,ly(j))-v(3,j)) * r)
        end if
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
