c
c ##AN28,131##
      subroutine mce_criteria2 (time,tstart,nbod,algor,opt,m,id,
     %  opti,optr,mem,lmem,K2)
c ##AN28,131##
c
      implicit none
      include 'mercury.inc'
c
c Input/output
      integer nbod,algor,opt,lmem(NMESS),nbclo,nstored
      integer opti(90)
      real*8 time,tstart,m(nbod)
      real*8 optr(76)
      character*8 id(nbod)
      character*80 mem(NMESS)
c ##AN28,132##
      real*8 K2
c ##AN28,132##
c
c Local
      integer j,flag(4),i0
      integer year,month
      real*8 k_2,t1,sum,m0
c
c------------------------------------------------------------------------------
c
      k_2 = 1.d0 / K2
c
      flag(1) = 0
      flag(2) = 0
      flag(3) = 0
      flag(4) = 0
c
      i0 = 2
      if (algor.eq.11.or.algor.eq.12) i0 = 3
      if (algor.eq.5) i0 = 4
c
      if (opti(52).ge.1) then
        if ((time*sign(1.d0,optr(39)-optr(38)).ge.
     %    optr(38)*sign(1.d0,optr(39)-optr(38)))
     %    .and.(time*sign(1.d0,optr(39)-optr(38))
     %    .le.optr(39)*sign(1.d0,optr(39)-optr(38)))) then
          flag(1) = 1
          if (opti(52).eq.1) then
          if (opt.eq.1) then
            call mio_jd2y (time,year,month,t1)
            write (23,'(/,3a,f18.5,1x,f18.5,a,a1,1x,a,i10,1x,i2,1x,
     %        f8.5,/)')
     %        mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %        mem(327)(1:lmem(327)),optr(38),optr(39),mem(1)(1:lmem(1)),
     %        ',',mem(71)(1:lmem(71)),year,month,t1
            write (*,'(/,3a,f18.7,1x,f18.7,a,a1,1x,a,i10,1x,i2,1x,
     %        f8.5,/)')
     %        mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %        mem(327)(1:lmem(327)),optr(38),optr(39),mem(1)(1:lmem(1)),
     %        ',',mem(71)(1:lmem(71)),year,month,t1
          else
            if (opt.eq.3) then
              t1 = (time - tstart) / 365.25d0
              write (23,'(/,3a,f18.5,1x,f18.5,a,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(327)(1:lmem(327)),optr(38),optr(39),
     %          mem(1)(1:lmem(1)),',',mem(71)(1:lmem(71)),t1,
     %          mem(2)(1:lmem(2))
              write (*,'(/,3a,f18.7,1x,f18.7,a,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(327)(1:lmem(327)),optr(38),optr(39),
     %          mem(1)(1:lmem(1)),',',mem(71)(1:lmem(71)),t1,
     %          mem(2)(1:lmem(2))
            else
              if (opt.eq.0) t1 = time
              if (opt.eq.2) t1 = time - tstart
              write (23,'(/,3a,f18.5,1x,f18.5,a,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(327)(1:lmem(327)),optr(38),optr(39),
     %          mem(1)(1:lmem(1)),',',mem(71)(1:lmem(71)),t1,
     %          mem(1)(1:lmem(1))
              write (*,'(/,3a,f18.5,1x,f18.5,a,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(327)(1:lmem(327)),optr(38),optr(39),
     %          mem(1)(1:lmem(1)),',',mem(71)(1:lmem(71)),t1,
     %          mem(1)(1:lmem(1))
            end if
          end if
            opti(52) = 2
          end if
        end if
      end if
c
      if (opti(53).ge.1) then
        do j = i0, nbod
          if ((m(j).ge.optr(40).and.m(j).le.optr(41))
     %      .and.(j.lt.opti(56).or.j.gt.opti(57))) then
            flag(2) = 1
            m0 = m(j)
            if (opti(53).eq.1) then
            if (opt.eq.1) then
              call mio_jd2y (time,year,month,t1)
              write (23,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,
     %          f8.5,/)') mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %          mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),year,month,t1
              write (*,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,
     %          f8.5,/)') mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %          mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),year,month,t1
            else
              if (opt.eq.3) then
                t1 = (time - tstart) / 365.25d0
                write (23,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.7,a,
     %            /)') mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %            mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %            mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %            mem(2)(1:lmem(2))
                write (*,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.7,a,
     %            /)') mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %            mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %            mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %            mem(2)(1:lmem(2))
              else
                if (opt.eq.0) t1 = time
                if (opt.eq.2) t1 = time - tstart
                write (23,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.5,a,
     %            /)') mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %            mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %            mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %            mem(1)(1:lmem(1))
                write (*,'(/,3a,a8,a1,1x,1p1e12.6,0p,a,a1,1x,a,f18.5,a,
     %            /)') mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %            mem(328)(1:lmem(328)),id(j),',',m(j)*k_2,
     %            mem(3)(1:lmem(3)),',',mem(71)(1:lmem(71)),t1,
     %            mem(1)(1:lmem(1))
              end if
            end if
              opti(53) = 2
            end if
            exit
          end if
        end do
      end if
c
      if (opti(54).ge.1) then
        sum = 0
        do j = i0, nbod
          if (j.lt.opti(58).or.j.gt.opti(59)) sum = sum + m(j)
        end do
        if (sum.le.optr(42).and.sum.ge.optr(43)) then
          flag(3) = 1
          if (opti(54).eq.1) then
          if (opt.eq.1) then
            call mio_jd2y (time,year,month,t1)
            write (23,'(/,3a,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,f8.5,
     %        /)') mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %        mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %        mem(71)(1:lmem(71)),year,month,t1
            write (*,'(/,3a,1p1e12.6,0p,a,a1,1x,a,i10,1x,i2,1x,f8.5,
     %        /)') mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %        mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %        mem(71)(1:lmem(71)),year,month,t1
          else
            if (opt.eq.3) then
              t1 = (time - tstart) / 365.25d0
              write (23,'(/,3a,1p1e12.6,0p,a,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %          mem(71)(1:lmem(71)),t1,mem(2)(1:lmem(2))
              write (*,'(/,3a,1p1e12.6,0p,a,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %          mem(71)(1:lmem(71)),t1,mem(2)(1:lmem(2))
            else
              if (opt.eq.0) t1 = time
              if (opt.eq.2) t1 = time - tstart
              write (23,'(/,3a,1p1e12.6,0p,a,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %          mem(71)(1:lmem(71)),t1,mem(1)(1:lmem(1))
              write (*,'(/,3a,1p1e12.6,0p,a,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(329)(1:lmem(329)),sum*k_2,mem(3)(1:lmem(3)),',',
     %          mem(71)(1:lmem(71)),t1,mem(1)(1:lmem(1))
            end if
          end if
            opti(54) = 2
          end if
        end if
      end if
c
      if (opti(55).ge.1) then
        if (nbod.le.opti(60).and.nbod.ge.opti(61)) then
          flag(4) = 1
          if (opti(55).eq.1) then
          if (opt.eq.1) then
            call mio_jd2y (time,year,month,t1)
            write (23,'(/,3a,i7,a1,1x,a,i10,1x,i2,1x,f8.5,/)')
     %        mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %        mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %        year,month,t1
            write (*,'(/,3a,i7,a1,1x,a,i10,1x,i2,1x,f8.5,/)')
     %        mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %        mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %        year,month,t1
          else
            if (opt.eq.3) then
              t1 = (time - tstart) / 365.25d0
              write (23,'(/,3a,i7,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %          t1,mem(2)(1:lmem(2))
              write (*,'(/,3a,i7,a1,1x,a,f18.7,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %          t1,mem(2)(1:lmem(2))
            else

              if (opt.eq.0) t1 = time
              if (opt.eq.2) t1 = time - tstart
              write (23,'(/,3a,i7,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %          t1,mem(1)(1:lmem(1))
              write (*,'(/,3a,i7,a1,1x,a,f18.5,a,/)')
     %          mem(121)(1:lmem(121)),mem(336)(1:lmem(336)),
     %          mem(330)(1:lmem(330)),nbod-1,',',mem(71)(1:lmem(71)),
     %          t1,mem(1)(1:lmem(1))
            end if
          end if
            opti(55) = 2
          end if
        end if
      end if
c
      do j = 1, 4
        if (opti(62).ge.1) then
          if (j.eq.opti(64)) then
            if (flag(j).gt.0) then
              opti(62) = 2
            else
              opti(62) = 1
            end if
          end if
        end if
c
        if (opti(63).ge.1) then
          if (j.eq.opti(65)) then
            if (flag(j).gt.0) then
              opti(63) = 2
            else
              opti(63) = 1
            end if
          end if
        end if
      end do
c
c      if (opti(64).eq.0.and.opti(62).eq.1) opti(62) = 2
c      if (opti(65).eq.0.and.opti(63).eq.1) opti(63) = 2
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A32,1##
c
c ##A33,3##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      INTERSEC.FOR    (4 November 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Find intersection point between line and plane.
c
c------------------------------------------------------------------------------
c
      subroutine intersec (nov,nop,xv,yv,zv,noe,k,x0,y0,z0,x1,y1,z1,
     %  x,y,z,f)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nov,nop,noe,k
      integer f
      real*8 x0,y0,z0,x1,y1,z1
      real*8 x,y,z
      real*8 xv(nov),yv(nov),zv(nov)
      dimension noe(nop)
      dimension k(nopmax,noed)
c
c Local
      integer i,j
      integer count,iflag
      integer is_odd
      real*8 Ax,Ay,Bx,By,Px,Py
      real*8 AB(3,noed),norm(3),LL(3)
      real*8 t,Q1,Q2,D
      integer indflag
      real*8 xmin,ymin,zmin,dist,dmin
c
c------------------------------------------------------------------------------
c
      LL(1) = x1-x0
      LL(2) = y1-y0
      LL(3) = z1-z0
c
      indflag = 0
      do i = 1, nop
        do j = 1, noe(i)-1
          AB(1,j) = xv(k(i,j+1))-xv(k(i,j))
          AB(2,j) = yv(k(i,j+1))-yv(k(i,j))
          AB(3,j) = zv(k(i,j+1))-zv(k(i,j))
        end do
        norm(1) = AB(2,1)*AB(3,2)-AB(3,1)*AB(2,2)
        norm(2) = AB(3,1)*AB(1,2)-AB(1,1)*AB(3,2)
        norm(3) = AB(1,1)*AB(2,2)-AB(2,1)*AB(1,2)
        D = -(norm(1)*xv(k(i,1))+norm(2)*yv(k(i,1))+norm(3)*zv(k(i,1)))
        Q1= -(norm(1)*x0+norm(2)*y0+norm(3)*z0+D)
        Q2= norm(1)*LL(1)+norm(2)*LL(2)+norm(3)*LL(3)
        if (abs(Q2).gt.TINY) then
          t = Q1/Q2
        else
          goto 1234
        end if
        x = x0 + t*LL(1)
        y = y0 + t*LL(2)
        z = z0 + t*LL(3)
c
        if (t.ge.0.and.t.le.1.d0) then
        count = 0
        do j = 1, noe(i)-1
          Ax = xv(k(i,j))
          Ay = yv(k(i,j))
          Bx = xv(k(i,j+1))
          By = yv(k(i,j+1))
          Px = x
          Py = y
          call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
          if (iflag.eq.1) count = count + 1
        end do
        Ax = xv(k(i,noe(i)))
        Ay = yv(k(i,noe(i)))
        Bx = xv(k(i,1))
        By = yv(k(i,1))
        Px = x
        Py = y
        call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
        if (iflag.eq.1) count = count + 1
        iflag = is_odd(count)
        if (iflag.eq.0) goto 1234
c
        count = 0
        do j = 1, noe(i)-1
          Ax = yv(k(i,j))
          Ay = zv(k(i,j))
          Bx = yv(k(i,j+1))
          By = zv(k(i,j+1))
          Px = y
          Py = z
          call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
          if (iflag.eq.1) count = count + 1
        end do
        Ax = yv(k(i,noe(i)))
        Ay = zv(k(i,noe(i)))
        Bx = yv(k(i,1))
        By = zv(k(i,1))
        Px = y
        Py = z
        call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
        if (iflag.eq.1) count = count + 1
        iflag = is_odd(count)
        if (iflag.eq.0) goto 1234
c
        count = 0
        do j = 1, noe(i)-1
          Ax = zv(k(i,j))
          Ay = xv(k(i,j))
          Bx = zv(k(i,j+1))
          By = xv(k(i,j+1))
          Px = z
          Py = x
          call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
          if (iflag.eq.1) count = count + 1
        end do
        Ax = zv(k(i,noe(i)))
        Ay = xv(k(i,noe(i)))
        Bx = zv(k(i,1))
        By = xv(k(i,1))
        Px = z
        Py = x
        call ray_intersects_segment(Ax,Ay,Bx,By,Px,Py,iflag)
        if (iflag.eq.1) count = count + 1
        iflag = is_odd(count)
        if (iflag.eq.0) goto 1234
c
c        dist = (x-x0)*(x-x0)+(y-y0)*(y-y0)+(z-z0)*(z-z0)
c        if (indflag.eq.0) then
c          f = i
c          xmin = x
c          ymin = y
c          zmin = z
c          dmin = dist
c          indflag = 1
c        end if
c        if (dist.lt.dmin) then
c          f = i
c          xmin = x
c          ymin = y
c          zmin = z
c          dmin = dist
c        end if
c
        f = i
        exit
        end if
 1234   continue
      end do
c
c      x = xmin
c      y = ymin
c      z = zmin
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A33,3##
c
c ##A19,183##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_ASTROT.FOR    (FEG   20 December 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Rotates polyhedron vertices.
c
c------------------------------------------------------------------------------
c
      subroutine mco_astrot (nov,time,h,xv0,yv0,zv0,xv,yv,zv)
c
      implicit none
c
c Input/Output
      integer nov
      real*8 time,h
      real*8 xv0(nov),yv0(nov),zv0(nov)
      real*8 xv(nov),yv(nov),zv(nov)
c
c Local
      integer k
      real*8 gama,sg,cg
c
c------------------------------------------------------------------------------
c
      gama = h * time
      call mco_sine (gama,sg,cg)
c
c Calculate the synodic coordinates and velocities
      do k = 1, nov
        xv(k) =  xv0(k) * cg - yv0(k) * sg
        yv(k) =  xv0(k) * sg + yv0(k) * cg
        zv(k) =  zv0(k)
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A19,183##
c
c ##A39,8##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MFO_CHK.FOR    (FEG   26 May 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Calculates centrifugal corrective accelerations for a set
c of NBOD bodies (affect only small bodies).
c
c N.B. All coordinates and velocities must be with respect to central body!!!!
c ===
c------------------------------------------------------------------------------
c
      subroutine mfo_chk (time,nbod,j0,c0,m,x,v,a,opt,optr,opti,x0,stat,
     %  norm)
c
      implicit none
c
c Input/Output
      real*8 time
      integer nbod, j0, c0
      real*8 m(nbod), x(3,nbod), v(3,nbod), a(3,nbod)
      integer opt(9)
      real*8 optr(76)
      integer opti(90)
      real*8 x0(3,nbod)
      integer stat(nbod)
      real*8 norm(3)
c
c Local
      integer j
      real*8 r, dx, dy, dz
      real*8 x10(3,1),x11(3,1)
      real*8 r0,ang0,ang1,rp
c
c------------------------------------------------------------------------------
c
c      do j = 1, nbod
c        a(1,j) = 0.d0
c        a(2,j) = 0.d0
c        a(3,j) = 0.d0
c      end do
c
      do j = j0, nbod
c        dx = x(1,j) - x0(1,j)
c        dy = x(2,j) - x0(2,j)
c        dz = x(3,j) - x0(3,j)
c        r = dx * dx + dy * dy + dz * dz
        dx = x0(1,j) - x0(1,c0)
        dy = x0(2,j) - x0(2,c0)
        dz = x0(3,j) - x0(3,c0)
        r0 = dsqrt(dx * dx + dy * dy + dz * dz)
        ang0=atan2(dz,dsqrt(dx*dx+dy*dy))
        dx = x(1,j) - x(1,c0)
        dy = x(2,j) - x(2,c0)
        dz = x(3,j) - x(3,c0)
        r = dsqrt(dx * dx + dy * dy + dz * dz)
        ang1=atan2(dz,dsqrt(dx*dx+dy*dy))
        rp = r * cos(ang1-ang0)
        r = dabs(rp - r0)
c
        if (r.ge.optr(62).and.(stat(j).ge.0.and.stat(j).ne.10)) then
c          a(1,j) = a(1,j) + optr(6) * optr(6) * x(1,j)
c          a(2,j) = a(2,j) + optr(6) * optr(6) * x(2,j)
          stat(j) = 10
c          x10(1,1) = x0(1,j) - x(1,c0)
c          x10(2,1) = x0(2,j) - x(2,c0)
c          x10(3,1) = x0(3,j) - x(3,c0)
c          call mco_rot (time-optr(64),1,1,optr(6),x10,x11)
c          v(1,j) = -optr(6) * x11(2,1)
c          v(2,j) =  optr(6) * x11(1,1)
c          v(3,j) = 0.d0
          x11(1,1) = x(1,j) - x(1,c0)
          x11(2,1) = x(2,j) - x(2,c0)
          x11(3,1) = rp * sin(ang0)
          v(1,j) = norm(2) * x11(3,1) - x11(2,1) * norm(3)
          v(2,j) = norm(3) * x11(1,1) - x11(3,1) * norm(1)
          v(3,j) = norm(1) * x11(2,1) - x11(1,1) * norm(2)
          v(1,j) = v(1,j) + v(1,c0)
          v(2,j) = v(2,j) + v(2,c0)
          v(3,j) = v(3,j) + v(3,c0)
          x(1,j) = x(1,c0) + x11(1,1)
          x(2,j) = x(2,c0) + x11(2,1)
          x(3,j) = x(3,c0) + x11(3,1)
        end if
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A39,8##
c
c ##A39,54##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c    MCE_CRITERIA3.FOR    (ErikSoft   3 October 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 26 May 2017)
c
c Given initial and final coordinates and velocities X and V, and a timestep 
c H, the routine estimates which objects were involved in a close encounter
c during the timestep. The routine examines all objects with indices I >= I0.
c
c Returns an array CE, which for each object is: 
c                           0 if it will undergo no encounters
c                           2 if it will pass within RCRIT of a Big body
c
c Also returns arrays ICE and JCE, containing the indices of each pair of
c objects estimated to have undergone an encounter.
c
c N.B. All coordinates must be with respect to the central body!!!!
c ===
c
c------------------------------------------------------------------------------
c
      subroutine mce_criteria3 (h,i0,nbod,nbig,x0,v0,x1,v1,rce,stat,
     %  flag,ice)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer i0,nbod,nbig,flag,stat(nbod),ice(2)
      real*8 x0(3,nbod),v0(3,nbod),x1(3,nbod),v1(3,nbod),h,rce(nbod)
c
c Local
      integer i,j
      real*8 d0,d1,d0t,d1t,d2min,temp,tmin,rc,rc2
      real*8 dx0,dy0,dz0,du0,dv0,dw0,dx1,dy1,dz1,du1,dv1,dw1
      real*8 xmin(NMAX),xmax(NMAX),ymin(NMAX),ymax(NMAX)
c
c------------------------------------------------------------------------------
c
      if (i0.le.0) i0 = 2
c
c Calculate maximum and minimum values of x and y coordinates
      call mce_box (nbod,h,x0,v0,x1,v1,xmin,xmax,ymin,ymax)
c
c Adjust values for the Big bodies by symplectic close-encounter distance
      do j = i0, nbig
        temp = rce(j) * 1.2d0
        xmin(j) = xmin(j)  -  temp
        xmax(j) = xmax(j)  +  temp
        ymin(j) = ymin(j)  -  temp
        ymax(j) = ymax(j)  +  temp
      end do
c
c Identify pairs whose X-Y boxes overlap, and calculate minimum separation
      do i = i0, nbig-1
        do j = i + 1, nbig
c          if (xmax(i).ge.xmin(j).and.xmax(j).ge.xmin(i)
c     %      .and.ymax(i).ge.ymin(j).and.ymax(j).ge.ymin(i)) then
          if (xmax(i).ge.xmin(j).and.xmax(j).ge.xmin(i)
     %      .and.ymax(i).ge.ymin(j).and.ymax(j).ge.ymin(i)
     %      .and.stat(i).ge.0.and.stat(j).ge.0) then
c
c Determine the maximum separation that would qualify as an encounter
            rc = max(rce(i), rce(j))
            rc2 = rc * rc
c
c Calculate initial and final separations
            dx0 = x0(1,i) - x0(1,j)
            dy0 = x0(2,i) - x0(2,j)
            dz0 = x0(3,i) - x0(3,j)
            dx1 = x1(1,i) - x1(1,j)
            dy1 = x1(2,i) - x1(2,j)
            dz1 = x1(3,i) - x1(3,j)
            d0 = dx0*dx0 + dy0*dy0 + dz0*dz0
            d1 = dx1*dx1 + dy1*dy1 + dz1*dz1
c
c Check for a possible minimum in between
            du0 = v0(1,i) - v0(1,j)
            dv0 = v0(2,i) - v0(2,j)
            dw0 = v0(3,i) - v0(3,j)
            du1 = v1(1,i) - v1(1,j)
            dv1 = v1(2,i) - v1(2,j)
            dw1 = v1(3,i) - v1(3,j)
            d0t = (dx0*du0 + dy0*dv0 + dz0*dw0) * 2.d0
            d1t = (dx1*du1 + dy1*dv1 + dz1*dw1) * 2.d0
c
c If separation derivative changes sign, find the minimum separation
            d2min = HUGE
            if (d0t*h.le.0.and.d1t*h.ge.0) call mce_min (d0,d1,d0t,d1t,
     %        h,d2min,tmin)
c
c If minimum separation is small enough, flag this as a possible encounter
            temp = min (d0,d1,d2min)
            if (temp.le.rc2) then
              if (flag.eq.1) then
                flag = 2
                ice(1) = i
                ice(2) = j
              end if
            else
              if (flag.eq.3) flag = 0
            end if
          end if
        end do
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A39,54##
c
c ##A39,78##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_ROT.FOR    (FEG   27 May 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Rotates coordinates.
c
c------------------------------------------------------------------------------
c
      subroutine mco_rot (time,j0,nbod,w,x0,x)
c
      implicit none
c
c Input/Output
      integer nbod,j0
      real*8 time,w
      real*8 x0(3,nbod),x(3,nbod)
c
c Local
      integer k
      real*8 gama,sg,cg
c
c------------------------------------------------------------------------------
c
      gama = w * time
      call mco_sine (gama,sg,cg)
c
c Calculate the synodic coordinates and velocities
      do k = j0, nbod
        x(1,k) =  x0(1,k) * cg - x0(2,k) * sg
        x(2,k) =  x0(1,k) * sg + x0(2,k) * cg
        x(3,k) =  x0(3,k)
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A39,78##
c
c ##A39,115##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      CHK_DUMP.FOR    (ErikSoft   21 February 2001)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers (adapted by A. Amarante - 28 May 2017)
c
c Writes masses, coordinates, velocities etc. of all objects, and integration
c parameters, to dump files. Also updates a restart file containing other
c variables used internally by MERCURY.
c
c N.B. All coordinates and velocities must be with respect to central body!!!!
c ===
c------------------------------------------------------------------------------
c
      subroutine chk_dump (nbod,chk,opti,optr,dumpfile)
c
      implicit none
c
c Input/Output
      integer nbod
      character*80 dumpfile(5)
      real*8 optr(76)
      integer opti(90)
      real*8 chk(3,nbod)
c
c Local
      integer idp,j
c
c------------------------------------------------------------------------------
c
      do idp = 1, 2
c
c Create new version of the restart file
  60    if (idp.eq.1) open (35, file='./dmp/chk.tmp',
     %    status='unknown',err=60)
  65    if (idp.eq.2) open (35, file=dumpfile(5), status='old', err=65)
        write (35,*) optr(64)
        do j = 2, nbod
          write(35,'(1p,3(1x,e22.15),1x,i8)') chk(1,j),chk(2,j),chk(3,j)
        end do
        close (35)
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A39,115##
c
c ##A39,116##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c    CHK_ROT.FOR    (FEG   29 May 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante)
c
c Set bodies at same plane.
c
c N.B. All coordinates must be with respect to the body i0!!!!
c      All output coordinates will be with respect to the central body!!!!
c ===
c
c------------------------------------------------------------------------------
c
      subroutine chk_rot (nbod,j0,i0,c0,m,x,v,xp,vp,opti,optr,norm)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer j0,i0,c0,nbod
      real*8 optr(76)
      integer opti(90)
      real*8 x(3,nbod),v(3,nbod),xp(3,nbod),vp(3,nbod),m(nbod)
      real*8 norm(3)
c
c Local
      integer j,k
      real*8 gm,q,a,e,i,p,n,l
      real*8 dx,dy,dz,du,dv,dw
      real*8 x1(3,nbod),v1(3,nbod),x2(3,nbod),v2(3,nbod)
      real*8 x3,y3,z3,u3,v3,w3,ver
c
c------------------------------------------------------------------------------
c
      gm = m(j0) + m(i0)
      dx = x(1,i0) - x(1,j0)
      dy = x(2,i0) - x(2,j0)
      dz = x(3,i0) - x(3,j0)
      du = v(1,i0) - v(1,j0)
      dv = v(2,i0) - v(2,j0)
      dw = v(3,i0) - v(3,j0)
      call mco_x2el (gm,dx,dy,dz,du,dv,dw,q,e,i,p,n,l)
      p = p - n
c
      k = 0
      do j = c0, nbod
        k = k + 1
        call mco_rotz (p,j,j,x,x1)
        call mco_rotx (i,j,j,x1,x2)
        call mco_rotz (n,j,j,x2,x1)
        call mco_rotz (p,j,j,v,v1)
        call mco_rotx (i,j,j,v1,v2)
        call mco_rotz (n,j,j,v2,v1)
        xp(1,k) = x1(1,j) + x(1,i0)
        xp(2,k) = x1(2,j) + x(2,i0)
        xp(3,k) = x1(3,j) + x(3,i0)
        vp(1,k) = v1(1,j) + v(1,i0)
        vp(2,k) = v1(2,j) + v(2,i0)
        vp(3,k) = v1(3,j) + v(3,i0)
      end do
c
      call mco_el2x (gm,q,e,i,p+n,n,l+1.0E-6,x3,y3,z3,u3,v3,
     %  w3)
      norm(1) = dy * z3 - y3 * dz
      norm(2) = dz * x3 - z3 * dx
      norm(3) = dx * y3 - x3 * dy
      ver     = dsqrt(norm(1)*norm(1)+norm(2)*norm(2)+norm(3)*norm(3))
      ver     = 1.d0 / ver
      norm(1) = norm(1) * ver
      norm(2) = norm(2) * ver
      norm(3) = norm(3) * ver
      norm(1) = norm(1) * optr(6)
      norm(2) = norm(2) * optr(6)
      norm(3) = norm(3) * optr(6)
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A39,116##
c
c ##A39,117##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_ROTZ.FOR    (FEG   29 May 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Rotates coordinates about Z-axis.
c
c------------------------------------------------------------------------------
c
      subroutine mco_rotz (gama,j0,nbod,x0,x)
c
      implicit none
c
c Input/Output
      integer nbod,j0
      real*8 gama,x0(3,nbod),x(3,nbod)
c
c Local
      integer k
      real*8 sg,cg
c
c------------------------------------------------------------------------------
c
      call mco_sine (gama,sg,cg)
c
c Calculate the synodic coordinates and velocities
      do k = j0, nbod
        x(1,k) =  x0(1,k) * cg - x0(2,k) * sg
        x(2,k) =  x0(1,k) * sg + x0(2,k) * cg
        x(3,k) =  x0(3,k)
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A39,117##
c
c ##A39,118##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_ROTX.FOR    (FEG   29 May 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Rotates coordinates about X-axis.
c
c------------------------------------------------------------------------------
c
      subroutine mco_rotx (gama,j0,nbod,x0,x)
c
      implicit none
c
c Input/Output
      integer nbod,j0
      real*8 gama,x0(3,nbod),x(3,nbod)
c
c Local
      integer k
      real*8 sg,cg
c
c------------------------------------------------------------------------------
c
      call mco_sine (gama,sg,cg)
c
c Calculate the synodic coordinates and velocities
      do k = j0, nbod
        x(1,k) =  x0(1,k)
        x(2,k) =  x0(2,k) * cg - x0(3,k) * sg
        x(3,k) =  x0(2,k) * sg + x0(3,k) * cg
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A39,118##
c
c ##A39,119##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_ROTY.FOR    (FEG   29 May 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Rotates coordinates about Y-axis.
c
c------------------------------------------------------------------------------
c
      subroutine mco_roty (gama,j0,nbod,x0,x)
c
      implicit none
c
c Input/Output
      integer nbod,j0
      real*8 gama,x0(3,nbod),x(3,nbod)
c
c Local
      integer k
      real*8 sg,cg
c
c------------------------------------------------------------------------------
c
      call mco_sine (gama,sg,cg)
c
c Calculate the synodic coordinates and velocities
      do k = j0, nbod
        x(1,k) =  x0(1,k) * cg + x0(3,k) * sg
        x(2,k) =  x0(2,k)
        x(3,k) = -x0(1,k) * sg + x0(3,k) * cg
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A39,119##
c
c ##A19,187##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MASC_ROT1.FOR    (7 October 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Translates vertices to the center of mass.
c
c------------------------------------------------------------------------------
c
      subroutine masc_rot1 (nov,xv,yv,zv,xc,yc,zc)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nov
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc,yc,zc
c
c Local
      integer i,j,k
      real*8 x(2,3),xcm(3)
c
c------------------------------------------------------------------------------
c
      xcm(1) = xc
      xcm(2) = yc
      xcm(3) = zc
c
c computes transposed matrix
c      do i = 1, 3
c        do j = 1, 3
c          TT(i,j) = T(j,i)
c        enddo
c      enddo

c
      do i = 1, nov
c
c translate
        x(1,1) = xv(i)
        x(1,2) = yv(i)
        x(1,3) = zv(i)
c
        do j = 1, 3
          x(1,j) = x(1,j) - xcm(j)
        enddo
c
        xv(i) = x(1,1)
        yv(i) = x(1,2)
        zv(i) = x(1,3)
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A19,187##
c
c ##A19,188##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MASC_ROT2.FOR    (7 October 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Rotates to the main inertia axes.
c
c------------------------------------------------------------------------------
c
      subroutine masc_rot2 (nov,xv,yv,zv,T)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nov
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 T(3,3)
c
c Local
      integer i,j,k
      real*8 x(2,3),TT(3,3)
c
c------------------------------------------------------------------------------
c
      do i = 1, nov
c
c translate
        x(1,1) = xv(i)
        x(1,2) = yv(i)
        x(1,3) = zv(i)
c
c rotate
        do j = 1, 3
          x(2,j) = 0.d0
          do k = 1, 3
c            x(2,j) = x(2,j) + TT(j,k) * x(1,k)
            x(2,j) = x(2,j) + T(j,k) * x(1,k)
          enddo
        enddo
        xv(i) = x(2,1)
        yv(i) = x(2,2)
        zv(i) = x(2,3)
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A19,188##
c
c ##A19,189##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      REORIENTATION2.FOR    (9 October 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Reorientate faces.
c
c------------------------------------------------------------------------------
c
      subroutine reorientation2 (face1,face2,nov,nop,noe,k)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer nov,nop,noe,k
      real*8 face1(nop),face2(nop)
      dimension noe(nop)
      dimension k(nopmax,noed)
c Local
      integer i,j,l
      integer k0
      dimension k0(nopmax,noed)
c
c------------------------------------------------------------------------------
c
      do i = 1, nop
        if (face1(i)*face2(i).eq.-1) then
          l = 0
          do j = noe(i), 1, -1
            l = l + 1
            k0(i,l) = k(i,j)
          end do
          do j = 1, noe(i)
            k(i,j) = k0(i,j)
          end do
        end if
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A19,189##
c
c ##A41,5##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MASC_LAYER2.FOR    (9 October 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Calculates the pieces of masses of each pyramidal frustum layer of a polyhedron.
c Also calculates the volumens, centroids and inertia tensor of each pyramidal
c frustum layer.
c

c------------------------------------------------------------------------------
c
      subroutine masc_layer2 (nov,nop,xv,yv,zv,noe,k,d,lay,m,mt,vt,
     %  xc,yc,zc,mem,lmem,l0,T1t,T2t,TPt,Jt,cubx0,cuby0,cubz0)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer lmem(NMESS)
      character*80 mem(NMESS)
      integer nov,nop,noe,k,lay,l0
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(nocen),yc(nocen),zc(nocen),m(nocen),d(nocen),mt,vt
      real*8 T1t(3),T2t(3),TPt(3),Jt(3,3)
      real*8 cubx0,cuby0,cubz0
      dimension noe(nopmax)
      dimension k(nopmax,noed)
c
c Local
      integer i,j,l,ilay,novl,nopl
      integer noel,kl
      real*8 del,inc,nx,ny,nz
      real*8 xl(nov),yl(nov),zl(nov)
      real*8 norm(nopmax,3),wfac(nopmax)
      real*8 T0,T1(3),T2(3),TP(3)
      real*8 fvt,fmt,vol,vol1,vol2
      real*8 J0(3,3)
      real*8 xmin,xmax,ymin,ymax,zmin,zmax
      real*8 xstep,ystep,zstep,xcoor,ycoor,zcoor
      integer astflag1,astflag2
      real*8 xvc(8),yvc(8),zvc(8)
      real*8 cubx,cuby,cubz
      real*8 xl2(nov),yl2(nov),zl2(nov)
      dimension noel(nopmax)
      dimension kl(nopmax,noed)
c
c------------------------------------------------------------------------------
c
      del = 1.d0 / lay
      vt = 0.d0
      mt = 0.d0
      l0 = 0
c
      T1t(1) = 0.0
      T1t(2) = 0.0
      T1t(3) = 0.0
      T2t(1) = 0.0
      T2t(2) = 0.0
      T2t(3) = 0.0
      TPt(1) = 0.0
      TPt(2) = 0.0
      TPt(3) = 0.0
c central point (origin)
      xl(1) = 0.0
      yl(1) = 0.0
      zl(1) = 0.0
c
      cubx = 1.d0 / cubx0
      cuby = 1.d0 / cuby0
      cubz = 1.d0 / cubz0
c      cubx = cubx0
c      cuby = cuby0
c      cubz = cubz0
c
c compute xmin, xmax, ymin, ymax, zmin e zmax
      do i = 1, nov
        if (i.eq.1) then
          xmin=xv(i)
          xmax=xv(i)
          ymin=yv(i)
          ymax=yv(i)
          zmin=zv(i)
          zmax=zv(i)
        end if
c
        if(xv(i).lt.xmin) xmin = xv(i)
        if(xv(i).gt.xmax) xmax = xv(i)
        if(yv(i).lt.ymin) ymin = yv(i)
        if(yv(i).gt.ymax) ymax = yv(i)
        if(zv(i).lt.zmin) zmin = zv(i)
        if(zv(i).gt.zmax) zmax = zv(i)
      end do
c
      do ilay = 1, lay
        inc = del * ilay
c
        do i = 1, nov
c
c compute new vertices
          xl(i) = xv(i) * inc
          yl(i) = yv(i) * inc
          zl(i) = zv(i) * inc
          if (ilay.gt.1) then
            xl2(i) = xv(i) * del * (ilay-1)
            yl2(i) = yv(i) * del * (ilay-1)
            zl2(i) = zv(i) * del * (ilay-1)
          end if
c
c          if (i.eq.1) then
c            xmin=xl(i)
c            xmax=xl(i)
c            ymin=yl(i)
c            ymax=yl(i)
c            zmin=zl(i)
c            zmax=zl(i)
c          end if
c
c          if(xl(i).lt.xmin) xmin = xl(i)
c          if(xl(i).gt.xmax) xmax = xl(i)
c          if(yl(i).lt.ymin) ymin = yl(i)
c          if(yl(i).gt.ymax) ymax = yl(i)
c          if(zl(i).lt.zmin) zmin = zl(i)
c          if(zl(i).gt.zmax) zmax = zl(i)
        end do
c
        fvt = 0.d0
        fmt = 0.d0
c
        zstep = zmin
        do while (zstep.lt.zmax)
          ystep = ymin
          do while (ystep.lt.ymax)
            xstep = xmin
            do while (xstep.lt.xmax)
              xcoor = xstep + 0.5d0 * cubx
              ycoor = ystep + 0.5d0 * cuby
              zcoor = zstep + 0.5d0 * cubz
c check if the point is inside (iflag=1) or outside (iflag=0) the polyhedron using the tetrahedron method
              call tetrah (nov,nop,xl,yl,zl,noe,k,xcoor,ycoor,zcoor,
     %          astflag1)
c
              if (astflag1.eq.1) then
                if (ilay.le.1) then
                  astflag2 = 0
                else
c check if the point is inside (iflag=1) or outside (iflag=0) the polyhedron using the tetrahedron method
                  call tetrah (nov,nop,xl2,yl2,zl2,noe,k,
     %              xcoor,ycoor,zcoor,astflag2)
                end if
                if (astflag2.eq.0) then
c compute cubic vertices
                xvc(1) = xstep
                yvc(1) = ystep
                zvc(1) = zstep
                xvc(2) = xstep + cubx
                yvc(2) = ystep
                zvc(2) = zstep
                xvc(3) = xstep + cubx
                yvc(3) = ystep + cuby
                zvc(3) = zstep
                xvc(4) = xstep
                yvc(4) = ystep + cuby
                zvc(4) = zstep
                xvc(5) = xstep
                yvc(5) = ystep
                zvc(5) = zstep + cubz
                xvc(6) = xstep + cubx
                yvc(6) = ystep
                zvc(6) = zstep + cubz
                xvc(7) = xstep + cubx
                yvc(7) = ystep + cuby
                zvc(7) = zstep + cubz
                xvc(8) = xstep
                yvc(8) = ystep + cuby
                zvc(8) = zstep + cubz
c
c compute cubic's faces
                noel(1) = 4
                kl(1,1) = 4
                kl(1,2) = 3
                kl(1,3) = 2
                kl(1,4) = 1
c
                noel(2) = 4
                kl(2,1) = 1
                kl(2,2) = 2
                kl(2,3) = 6
                kl(2,4) = 5
c
                noel(3) = 4
                kl(3,1) = 2
                kl(3,2) = 3
                kl(3,3) = 7
                kl(3,4) = 6
c
                noel(4) = 4
                kl(4,1) = 3
                kl(4,2) = 4
                kl(4,3) = 8
                kl(4,4) = 7
c
                noel(5) = 4
                kl(5,1) = 4
                kl(5,2) = 1
                kl(5,3) = 5
                kl(5,4) = 8
c
                noel(6) = 4
                kl(6,1) = 5
                kl(6,2) = 6
                kl(6,3) = 7
                kl(6,4) = 8
c
c compute volumens
                nopl = 6
c compute normal faces and w vector
                do j = 1, nopl
                  call compnormalface (nov,nop,j,xvc,yvc,zvc,kl,
     %              nx,ny,nz)
                  norm(j,1) = nx
                  norm(j,2) = ny
                  norm(j,3) = nz
                  wfac(j) = - norm(j,1) * xvc(kl(j,1))
     %                      - norm(j,2) * yvc(kl(j,1))
     %                      - norm(j,3) * zvc(kl(j,1))
                enddo
c compute volumen of a cube
                call compVolumeIntegrals (nov,nop,nopl,xvc,yvc,zvc,
     %            noel,kl,norm,wfac,T0,T1,T2,TP)
                fvt = fvt + T0
                T1t(1) = T1t(1) + T1(1)
                T1t(2) = T1t(2) + T1(2)
                T1t(3) = T1t(3) + T1(3)
                T2t(1) = T2t(1) + T2(1)
                T2t(2) = T2t(2) + T2(2)
                T2t(3) = T2t(3) + T2(3)
                TPt(1) = TPt(1) + TP(1)
                TPt(2) = TPt(2) + TP(2)
                TPt(3) = TPt(3) + TP(3)
c compute pieces of masses
                l0 = l0 + 1
                m(l0) = d(ilay) * T0
                fmt = fmt + m(l0)
c compute center of masses of a cube
                call compcenpolyhedron (d(ilay),m(l0),T0,T1,
     %            T2,TP,xc(l0),yc(l0),zc(l0),J0)
                Jt(1,1) = Jt(1,1) + J0(1,1)
                Jt(1,2) = Jt(1,2) + J0(1,2)
                Jt(1,3) = Jt(1,3) + J0(1,3)
                Jt(2,1) = Jt(2,1) + J0(2,1)
                Jt(2,2) = Jt(2,2) + J0(2,2)
                Jt(2,3) = Jt(2,3) + J0(2,3)
                Jt(3,1) = Jt(3,1) + J0(3,1)
                Jt(3,2) = Jt(3,2) + J0(3,2)
                Jt(3,3) = Jt(3,3) + J0(3,3)
              end if
              end if
              xstep = xstep + cubx
            end do
            ystep = ystep + cuby
          end do
          zstep = zstep + cubz
        end do
c
        vt = vt + fvt
        mt = mt + fmt
        if (l0.gt.nocen) call mio_err (6,mem(81),lmem(81),mem(117),
     %    lmem(117),' ',1,mem(82),lmem(82))
      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A41,5##
c
c ##A41,6##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      READBINPOL2.FOR    (16 October 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Read computed center of mass from cube file.
c
c------------------------------------------------------------------------------
c
      subroutine readbinpol2 (binfile,mem,lmem,ninfile,noc,mcenb,vc,J0,
     %  xc,yc,zc,mc,xct,yct,zct,mcen,T1b,T2,TP)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer lmem(NMESS)
      character*80 mem(NMESS)
      character*80 binfile(101)
      integer ninfile
      real*8 xc(noc),yc(noc),zc(noc),mc(noc)
      real*8 mcen,vc,J0(3,3),mcenb
      integer noc
      real*8 xct,yct,zct
      real*8 T1b(3),T2(3),TP(3)
c
c Local
      character*80 filename
      integer lim(2,1000),nsub
      integer i,l,j,itmp
      character*15000 string
      character*80 c80
      integer lineno
      character*7 c7
c
c------------------------------------------------------------------------------
c
      do i = 1, 80
        filename(i:i) = ' '
      end do
c
      call mio_spl (150,binfile(101),nsub,lim)
      filename(1:lim(2,1)) = binfile(101)(lim(1,1):lim(2,1))
      itmp = lim(2,1)
c
c  LOOP  OVER  EACH  INPUT  FILE  CONTAINING  INTEGRATION  DATA
c
      do l = 1, ninfile
        i = ninfile - l + 1
        lineno = 0
        write (*,'(a13,1x,a)') 'Reading file:',binfile(i)
        call mio_spl (150,binfile(i),nsub,lim)
        filename(itmp+1:itmp+lim(2,1)-lim(1,1)+1) =
     %    binfile(i)(lim(1,1):lim(2,1))
c
        open (10, file=filename, status='old', access='sequential')
c
  40    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 40
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 40
        c80 = string(lim(1,1):lim(2,1))
        read (c80,*,err=661,end=667) noc
        c80 = string(lim(1,2):lim(2,2))
        read (c80,*,err=661,end=667) mcenb
        c80 = string(lim(1,3):lim(2,3))
        read (c80,*,err=661,end=667) vc
c
  50    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 50
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 50
c
  80    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 80
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 80
        c80 = string(lim(1,1):lim(2,1))
        read (c80,*,err=661,end=667) xct
        c80 = string(lim(1,2):lim(2,2))
        read (c80,*,err=661,end=667) yct
        c80 = string(lim(1,3):lim(2,3))
        read (c80,*,err=661,end=667) zct
        c80 = string(lim(1,4):lim(2,4))
        read (c80,*,err=661,end=667) mcen
c
        do j = 1, 3
  60      read (10,'(a15000)',end=667) string
          lineno = lineno + 1
          if (string(1:1).eq.')') goto 60
          call mio_spl (15000,string,nsub,lim)
          if (lim(1,1).eq.-1) goto 60
          c80 = string(lim(1,1):lim(2,1))
          read (c80,*,err=661,end=667) J0(j,1)
          c80 = string(lim(1,2):lim(2,2))
          read (c80,*,err=661,end=667) J0(j,2)
          c80 = string(lim(1,3):lim(2,3))
          read (c80,*,err=661,end=667) J0(j,3)
        end do
c
  61    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 61
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 61
        c80 = string(lim(1,1):lim(2,1))
        read (c80,*,err=661,end=667) T1b(1)
        c80 = string(lim(1,2):lim(2,2))
        read (c80,*,err=661,end=667) T1b(2)
        c80 = string(lim(1,3):lim(2,3))
        read (c80,*,err=661,end=667) T1b(3)
  62    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 62
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 62
        c80 = string(lim(1,1):lim(2,1))
        read (c80,*,err=661,end=667) T2(1)
        c80 = string(lim(1,2):lim(2,2))
        read (c80,*,err=661,end=667) T2(2)
        c80 = string(lim(1,3):lim(2,3))
        read (c80,*,err=661,end=667) T2(3)
  63    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 63
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 63
        c80 = string(lim(1,1):lim(2,1))
        read (c80,*,err=661,end=667) TP(1)
        c80 = string(lim(1,2):lim(2,2))
        read (c80,*,err=661,end=667) TP(2)
        c80 = string(lim(1,3):lim(2,3))
        read (c80,*,err=661,end=667) TP(3)
c
        do j = 1, noc
  70      read (10,'(a15000)',end=667) string
          lineno = lineno + 1
          if (string(1:1).eq.')') goto 70
          call mio_spl (15000,string,nsub,lim)
          if (lim(1,1).eq.-1) goto 70
          c80 = string(lim(1,1):lim(2,1))
          read (c80,*,err=661,end=667) xc(j)
          c80 = string(lim(1,2):lim(2,2))
          read (c80,*,err=661,end=667) yc(j)
          c80 = string(lim(1,3):lim(2,3))
          read (c80,*,err=661,end=667) zc(j)
          c80 = string(lim(1,4):lim(2,4))
          read (c80,*,err=661,end=667) mc(j)
        end do
        close (10)
      end do
c
 667  continue
      if(lineno.eq.0) then
        write(6,'(/,3(1x),2(a,1x),/)') 'Error:',
     %    'No center mass point was found.'
        stop
      end if      
c
c termina a execução do programa
      write (6,'(a)') 'Process completed successfully!'
c
c------------------------------------------------------------------------------
c
      return
c
c------------------------------------------------------------------------------
c
c Error reading from the input file containing integration parameters
 661  write (c7,'(i7)') lineno
      call mio_err (6,mem(81),lmem(81),mem(99),lmem(99),c7,7,
     %  mem(85),lmem(85))
c
c------------------------------------------------------------------------------
c
      end
c
c------------------------------------------------------------------------------
c
c ##A41,6##
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCO_IDEN3.FOR    (ErikSoft   2 November 2000)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Makes a new copy of a set of coordinates.
c
c------------------------------------------------------------------------------
c
c ##A38,31##
      subroutine mco_iden3 (time,jcen,nbod,nbig,h,m,xh,vh,x,v,ngf,
     %  ngflag,opt,optr,opti,K2,AU,MSUN)
c ##A38,31##
c
      implicit none
c
c Input/Output
      integer nbod,nbig,ngflag,opt(9)
      real*8 time,jcen(3),h,m(nbod),x(3,nbod),v(3,nbod),xh(3,nbod)
      real*8 vh(3,nbod),ngf(4,nbod)
c ##A38,32##
      real*8 optr(76)
      integer opti(90)
      real*8 K2,AU,MSUN
c ##A38,32##
c
c Local
      integer j
c
c------------------------------------------------------------------------------
c
      do j = nbig, nbod
        x(1,j) = xh(1,j)
        x(2,j) = xh(2,j)
        x(3,j) = xh(3,j)
        v(1,j) = vh(1,j)
        v(2,j) = vh(2,j)
        v(3,j) = vh(3,j)
      enddo
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A19,229##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MCE_SPIN.FOR    (ErikSoft  2 December 1999)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: John E. Chambers
c
c Calculates the spin rate (in rotations per day) for a fluid body given
c its mass, spin angular momentum and density. The routine assumes the
c body is a MacClaurin ellipsoid, whose axis ratio is defined by the
c quantity SS = SQRT(A^2/C^2 - 1), where A and C are the
c major and minor axes.
c
c OBS: o spin rate (rote) é dado como uma frequência f, ou seja, w=2*pi/T ->
c T=2*pi/w -> 1/T=w/(2*pi) -> f=w/(2*pi) -> rote=w/(2*pi) -> w=rote*(2*pi),
c onde w é a velocidade de rotação, que é dada na mesma unidade de tempo que o K2.
c
c------------------------------------------------------------------------------
c
      subroutine mce_spin (g,mass,spin,rho,rote)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      real*8 g,mass,spin,rho,rote
c
c Local
      integer k
      real*8 ss,s2,f,df,z,dz,tmp0,tmp1,t23
c
c------------------------------------------------------------------------------
c
      t23 = 2.d0 / 3.d0
      tmp1 = spin * spin / (2.d0 * PI * rho * g) 
     %     * ( 250.d0*PI*PI*rho*rho / (9.d0*mass**5) )**t23
c
c Calculate SS using Newton's method
      ss = 1.d0
      do k = 1, 20
        s2 = ss * ss
        tmp0 = (1.d0 + s2)**t23
        call m_sfunc (ss,z,dz)
        f = z * tmp0  -  tmp1
        df = tmp0 * ( dz  +  4.d0 * ss * z / (3.d0*(1.d0 + s2)) )
        ss = ss - f/df
      end do
c
c A Eq. 5-141 de 140_the_Maclaurin_Ellipsoid.pdf diz que (com ss=e', subrotina m_sfunc):
c w^2 / (2 * pi * g * rho) = [ (3 + ss^2) * arctan(ss) - 3 * ss ] / ss^3 = z (subrotina m_sfunc); w é a velocidade de rotação, g a constante gravitacional e rho a densidade.
c Logo, w^2 / (2 * pi * g * rho) = z -> w^2 = 2 * pi * g * rho * z -> w = (2 * pi * g * rho * z)^(1/2).
c Mas, w=2*pi/T -> T=2*pi/w -> 1/T=w/(2*pi) -> f=w/(2*pi) -> rote=w/(2*pi) ->
c rote=(2 * pi * g * rho * z)^(1/2) / (2*pi), onde w é a velocidade de rotação, que é dada na mesma unidade de tempo que o K2. Pois, da equação
c w^2 / (2 * pi * g * rho) = z, se fizermos a análise dimensional com d=distância, m=massa, t=tempo, temos:
c w^2 / (2 * pi * [d^3/m/t^2] * [m/d^3]) = z -> w^2 / (2 * pi) * [t^2] = z. Como w tem dimensão de [1/t]. Então,
c [1/t]^2 / (2 * pi) * [t^2] = z -> z = 1 / (2 * pi), ou seja, z é um parâmetro adimensional.
c Da equação w^2 / (2 * pi) * [t^2] = z, temos que: w^2 = 2 * pi * z / [t^2] -> w = (2 * pi * z)^(1/2) / [t], isto é,
c w tem dimensão de inverso de tempo, como era esperado. Como, este tempo vem da constante gravitacional g, que por sua vez
c está relacionada com o K2, então a velocidade de rotação também estará na mesma unidade de tempo que o K2.
c No caso dessa subrotina g = 1.0, pois o K2 já está embutido na densidade rho por meio da constante rhocgs = AU * AU * AU * K2 / MSUN,
c que converte a densidade rho de g/cm^3 nas unidades convenientes escolhidas do Mercury, além de multiplicar a densidade por K2.
c
c rote = f = w / (2 * pi) = (2 * pi * g * rho * z)^(1/2) / (2 * pi) -> w = rote * (2 * pi)
      rote = sqrt(TWOPI * g * rho * z) / TWOPI
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      M_SFUNC.FOR     (ErikSoft  14 November 1998)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Calculates Z = [ (3 + S^2)arctan(S) - 3S ] / S^3 and its derivative DZ,
c for S > 0.
c
c------------------------------------------------------------------------------
c
      subroutine m_sfunc (s,z,dz)
c
      implicit none
c
c Input/Output
      real*8 s, z, dz
c
c Local
      real*8 s2,s4,s6,s8,a
c
c------------------------------------------------------------------------------
c
      s2 = s * s
c
      if (s.gt.1.d-2) then
        a  = atan(s)
        z  = ((3.d0 + s2)*a - 3.d0*s) / (s * s2)
        dz = (2.d0*s*a - 3.d0 + (3.d0+s2)/(1.d0+s2)) / (s * s2)
     %     - 3.d0 * z / s
      else
        s4 = s2 * s2
        s6 = s2 * s4
        s8 = s4 * s4
        z  = - .1616161616161616d0*s8
     %       + .1904761904761905d0*s6
     %       - .2285714285714286d0*s4
     %       + .2666666666666667d0*s2
        dz = s * (- 1.292929292929293d0*s6
     %            + 1.142857142857143d0*s4
     %            - 0.914285714285714d0*s2
     %            + 0.533333333333333d0)
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A19,229##
c
c ##A44,7##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MXX_ROTBRUP.FOR    (FEG   22 June 2018)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Do rotational breakup.
c
c N.B. All coordinates must be with respect to the central body!!
c ===
c
c------------------------------------------------------------------------------
c
      subroutine mxx_rotbrup (time,tstart,en,am,jcen,nbod,nbig,m,x,v,s,
     %    rotflag,outfile,mem,lmem,opti,nbclo,bclo,nstored,cce,flagce,
     %    algor,stopflag,optr,nov,nop,noc,xv,yv,zv,noe,kkk,dens,mc,
     %    xc,yc,zc,K2,rphys,opt,stat,id,rho)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      real*8 time, tstart
      character*8 id(nbod)
      integer stat(nbod), opt(9)
      integer nbod, nbig, rotflag, lmem(NMESS)
      real*8 en(3), am(3), jcen(3)
      real*8 m(nbod), x(3,nbod), v(3,nbod), s(3,nbod)
      character*80 outfile, mem(NMESS)
      integer opti(90)
      integer nbclo,bclo(nbod)
      integer nstored
      character*107 cce(FMAX)
      integer flagce
      integer algor
      integer stopflag
      real*8 optr(76)
      integer nov,nop,noc,noe,kkk
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(nocen),yc(nocen),zc(nocen),mc(noc),dens(noc)
      dimension noe(nop)
      dimension kkk(nopmax,noed)
      real*8 K2
      real*8 rphys(nbod)
      real*8 rho(nbod)
c
c Local
      integer j, year, month
      real*8 t1,e,l
      real*8 ls,omg,omgb
      integer j2
      real*8 breakup
      character*41 flost
      character*6 tstring
      real*8 tmp0
      character*38 fstop
c
c------------------------------------------------------------------------------
c
      rotflag = 0
c
c Calculate initial energy and angular momentum
c      call mxx_en (jcen,nbod,nbig,m,x,v,s,e,l,nov,nop,noc,
c     %  xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,K2,rho)
      call mxx_en (jcen,nbod,nbig,m,x,v,s,e,l,nov,nop,noc,
     %  xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,K2,rho)
c
c Flag each object which is ejected, and set its mass to zero
      do j = 2, nbod
        ls = sqrt(s(1,j)*s(1,j) + s(2,j)*s(2,j) + s(3,j)*s(3,j))
c        omg= ls / (m(j) * rphys(j) * rphys(j))
        if (ls.gt.0) then 
          call mce_spin (1.d0,m(j),ls,rho(j),omg)
        else
          omg = 0.d0
        end if
c na subrotina mce_spin, omg é a frequência (f=w/(2*pi)), aqui precisamos da velocidade de rotação (2*pi*f=w)
        omg = omg * TWOPI
c v=Ds/Dt; Ds/R=Dtheta -> Ds=R*Dtheta; v=R*Dtheta/Dt=R*w (w é a velocidade de rotação). A força centrífuga Fc que uma partícula de massa m sente na superfície de um corpo esférico de raio R e massa M em rotação é dada por:
c Fc=m*v^2/R=m*(R*w)^2/R -> Fc=m*R*w^2. Já a força gravitacional Fg que uma partícula de massa m sente na superfície de um corpo esférico de raio R e massa M em rotação é dada por:
c Fg=G*M*m/R^2. Daí, quando Fc=Fg -> m*R*w^2=G*M*m/R^2 -> R*w^2=G*M/R^2 -> w^2=G*M/R^3 -> w=(G*M/R^3)^(1/2).
        omgb=sqrt(m(j) / (rphys(j) * rphys(j) * rphys(j)))
        breakup=omg-omgb
        if (breakup.gt.0) then
          call bcloo (nbclo,bclo,j,nbod,j2,flagce)
          call mio_cestored2 (nbod,m,j2,opt(4),time,x,v,
     %    nstored,bclo,cce,'r',0,algor,optr)
          rotflag = 1
          stat(j) = -5
          m(j) = 0.d0
          s(1,j) = 0.d0
          s(2,j) = 0.d0
          s(3,j) = 0.d0
c
c If new encounter minima have occurred, decide whether to stop integration
          stopflag = 0
          if (opt(1).eq.1) then
c If time style is Gregorian date then...
            tmp0 = time
            if (opt(3).eq.1) then
              fstop = '(3a,/,9x,a,i10,1x,i2,1x,f4.1)'
              call mio_jd2y (tmp0,year,month,t1)
              write (23,fstop) mem(121)(1:lmem(121)),mem(77)
     %          (1:lmem(77)),id(j),mem(71)(1:lmem(71)),year,month,t1
              write (*,fstop) mem(121)(1:lmem(121)),mem(77)
     %          (1:lmem(77)),id(j),mem(71)(1:lmem(71)),year,month,t1
c Otherwise...
            else
              if (opt(3).eq.3) then
                tstring = mem(2)
                fstop = '(3a,/,9x,a,f14.3,a)'
                t1 = (tmp0 - tstart) / 365.25d0
              else
                tstring = mem(1)
                fstop = '(3a,/,9x,a,f14.1,a)'
                if (opt(3).eq.0) t1 = tmp0
                if (opt(3).eq.2) t1 = tmp0 - tstart
              end if
              write (23,fstop) mem(121)(1:lmem(121)),mem(77)
     %          (1:lmem(77)),id(j),mem(71)(1:lmem(71)),t1,tstring
              write (*,fstop) mem(121)(1:lmem(121)),mem(77)
     %          (1:lmem(77)),id(j),mem(71)(1:lmem(71)),t1,tstring
            end if
            stopflag = 1
            return
          end if
c
c Write message to information file
          opti(15) = opti(15) - 1
          opti(17) = opti(17) + 1
          if (opt(3).eq.1) then
            call mio_jd2y (time,year,month,t1)
            flost = '(1x,a8,a,a,i10,1x,i2,1x,f8.5,3x,4(1x,i7))'
            write (23,flost) id(j),mem(74)(1:lmem(74)),
     %        mem(71)(1:lmem(71)),year,month,t1,
     %        opti(15),opti(16),opti(17),opti(18)
          else
            if (opt(3).eq.3) then
              t1 = (time - tstart) / 365.25d0
              tstring = mem(2)
              flost = '(1x,a8,a,a,f18.7,a,3x,4(1x,i7))'
            else
              if (opt(3).eq.0) t1 = time
              if (opt(3).eq.2) t1 = time - tstart
              tstring = mem(1)
              flost = '(1x,a8,a,a,f18.5,a,3x,4(1x,i7))'
            end if
            write (23,flost) id(j),mem(74)(1:lmem(74)),
     %        mem(71)(1:lmem(71)),t1,tstring,
     %        opti(15),opti(16),opti(17),opti(18)
          end if
        end if
      end do
c
c If ejections occurred, update ELOST and LLOST
      if (rotflag.ne.0) then
        call mxx_en (jcen,nbod,nbig,m,x,v,s,en(2),am(2),nov,nop,noc,
     %    xv,yv,zv,noe,kkk,dens,mc,xc,yc,zc,optr,opti,algor,K2,rho)
        en(3) = en(3) + (e - en(2))
        am(3) = am(3) + (l - am(2))
      end if
c
c------------------------------------------------------------------------------
c
      return
      end
c
c ##A44,7##
c
c ##A43,54##
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      POLYHEDRON.FOR    (FEG   7 March 2016)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c------------------------------------------------------------------------------
c
      subroutine polyhedron3 (nov,nop,x2,y2,z2,noe,k,d,xp,yp,zp,
     %  vx,vy,vz,K2,lapla)
c
c------------------------------------------------------------------------------
c
c******************************************************************************
c CHANGES IN VERSION 3 (23 July 2013)
c******************************************************************************
c
c Author:
c
c Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c O polyhedron.f foi modificado.
c As alterações foram feitas através dos marcadores ##Am##.
c
c-------------------------------------------------------------------------------
c
c Copyright notice for SEG distribution:
c
c Copyright (c) 2012 by the Society of Exploration Geophysicists.
c For more information, go to http://software.seg.org/2012/0001 .
c You must read and accept usage terms at:
c http://software.seg.org/disclaimer.txt before use.
c
c-------------------------------------------------------------------------------


c	PROGRAMM "polyhedron.f"
c
c	D.Tsoulis                        Thessaloniki, June 2010
c	
c
c	This programm computes the potential, its first
c	and second derivatives of a homogenous polyhedron
c	according to Petrovic (J of G, 1996). The triple
c	integrals of V, Vi and Vij (i,j=1..3) are transformed
c	twice by means of the divergence theorem of Gauss. The
c	transission from volume integrals into line integrals
c	is accomplished in two steps as follows:
c
c	                      GAUSS
c	1. Volume Integral  ----------> Surface Integral
c	2. Surface Integral ----------> Line Integral
c
c
c	Literature:
c	-----------
c	1. Petrovic S. (1996): Determination of the potential of
c	     homogeneous polyhedral bodies using line integrals, 
c	     Journal of Geodesy 71, 44 - 52.
c	2. Werner R.A. and D.J. Scheeres (1997): Exterior gravitation
c	     of a polyhedron derived and compared with harmonic and
c	     mascon gravitation representations of asteroid 4769
c	     Castalia, Celestial Mechanics and Dynamical Astronomy 65,
c	     313 - 344.
c
c	One has to calculate:
c	--------------------
c
c	1. h(P)       : The distance of point P from the plane p (PP')
c	2. s(P)       : -1, 1
c	3. h(PQ)      : The distance of P' from line segment pq (P'P'')
c 	4. s(PQ)      : -1, 1
c	5. cos(Np,ei) : Np is the plane normal to plane p
c	6. cos(npq,ei): npq is the line normal to line segment pq
c	7. LNpq, ANpq : (Transcendental Functions of the
c	                coordinates of the body's vertices)
c
c
c	ALL of the above quantities are computed automatically
c	using only the following three files:
c	1. file 'xyz' which contains the coordinates x(i), y(i) and
c	   z(i) of the i vertices of the polyhedron
c	2. file 'dat' is a line whith (nop) elements, which declare
c	   the number of edges building each of the (nop) planes,
c	   in the same order that they appear in file 'topology'
c	3. file 'topology' where the number of vertices belonging
c 	   at each facet is given, in such an order that the plane
c	   normal is always pointing outside the body
c
c	EXAMPLES FOR THESE FILES
c	------------------------
c
c	file 'xyz':
c
c	  10  10  20
c       30  10  20
c       30  20  20
c       10  20  20
c       10  10  10
c	  30  10  10
c	  30  20  10
c	  10  20  10
c
c	file 'topology':
c
c	  1 2 4 
c	  2 3 4
c	  6 5 8 7
c	  8 5 1 4
c	  6 7 3 2
c	  5 6 2 1
c	  7 8 4 3
c
c	file 'dat':
c
c	  3 3 4 4 4 4 4
c
c
c

c
c	IMPORTANT NOTICE
c	----------------
c
c	The origin of the reference coordinate system (ei) is 
c	situated at P, i.e.:  
c
c	                      Xp = Yp = Zp = 0
c
c	Thus, the coordinates of all vertices of the polyhedron 
c	in file 'xyz' refer to P.
c
c


c
c
c	parameter       stands for
c       --------------------------
c	nop         :   Number of planes
c	nov         :   Number of vertices
c	noe(i)      :   Number of edges (varying from facet to
c			facet according to the information given
c			in file 'dat'. As starting value for 
c			parameter (noe) we choose a conveniently
c			big value (noed), sufficient for our matrices 
c			definitions
c
c
c
c     Parameters 'nop' and 'nov' have to be edited by the user
c
c
c


	implicit real*8 (a-h,o-z)
c ##A5##
        include 'mercury.inc'
c      include 'polyhedron.inc'
c
c Input/Output
c      character*80 infile(4),outfile(1),dumpfile(2),mem(NMESS)
c      integer nov,nop,opt(1),lmem(NMESS)
c      integer*4 nograd,nflush,opflag,l
c      real*8 d0,d,T,omg,x2(novmax),y2(novmax),z2(novmax),xp,yp,zp,J
        integer nov,nop
c ##A19,132##
        real*8 d,x2(nov),y2(nov),z2(nov),xp,yp,zp,gc
c ##A19,132##
c ##AN28,28##
        real*8 K2
c ##AN28,28##
        integer lapla
        real*8 lapla0
c
c	Edit number of planes (nop) and number of vertices (nov)
c
c ##A1##
c	parameter(nop=7,nov=8,noed=100)


	dimension e(3,3)
c ##A19,133##
	dimension noe(nop)
c ##A19,133##
	dimension x(novmax),y(novmax),z(novmax),h(nopmax),s(nopmax),
     %  cs(nopmax,3)
	dimension xo(nopmax),yo(nopmax),zo(nopmax)
	dimension xx(nopmax),yy(nopmax),zz(nopmax)
	dimension xxx(nopmax,noed),yyy(nopmax,noed),zzz(nopmax,noed)
c ##A19,134##
	dimension k(nopmax,noed)
c ##A19,134##
	dimension g(nopmax,noed,3)
	dimension plnorm(nopmax,3),segnorm(nopmax,noed,3)
	dimension dcnp(nopmax,3),dcnpq(nopmax,noed,3)
	dimension hh(nopmax,noed),ss(nopmax,noed)
	dimension cspq(nopmax,noed,3)
	dimension vij(3,3)

	snorm(xipq,yipq,zipq)=dsqrt(xipq*xipq+yipq*yipq+zipq*zipq)
	fln(aa,bb,cc,dd)=dlog((aa+bb)/(cc+dd))
	fan(ee,f,gg,t,yf,w)=datan((ee*t)/(f*w))-datan((ee*gg)/(f*yf))

c ##A2##
c	open(10,file='xyzposnew',form='formatted',status='unknown')
c	open(11,file='topoaut',form='formatted',status='unknown')
c	open(12,file='dataut',form='formatted',status='unknown')
c      open(13,file='polaut2_out',form='formatted',access='append')

c ##A3## chama a subrotina mio_in para verificar os nomes e as existências dos arquivos de entrada (.in), saída (.out) e despejo (.dmp), criar os arquivos de saída e despejo e prosseguir com a integração no ponto onde ela foi interrompida
c      call mio_in (infile,outfile,dumpfile,mem,lmem,nov,nop,
c     %  nograd,nflush,opt,d0,T,x2,y2,z2,noe,k,opflag)

c ##A19##
c	read(12,*) (noe(j),j=1,nop)



c ##A20## converte a densidade d de g/cm^3 para kg/km^3. OBS: os vértices devem estar em quilômetros
c        d=d0*(1000.0d0*100.0d0)**3/1000.0d0
c ##A21## encontra a velocidade de rotação omg do asteróide tendo o seu período de rotação T
c        omg=2.0d0*pi/(T*3600.0d0)

c ##A22## abre o arquivo dos pontos em que se pretende calcular o potencial e suas derivadas (13)
c 450  open  (10+3, file=infile(3), status='old', err=450)
c ##A23## posiciona a função read para ler o ponto inicial do próximo intervalo a partir do qual se pretendia calcular o potencial e suas derivadas quando a integração foi interrompida
c      opflag = opflag + 1
c      do 20 l=0,opflag-1
c        read(10+3,*) xp,yp,zp
c  20  continue

c ##A24##
c	do 20 i=1,nov
c	read(10,*) x(i),y(i),z(i)
c20	continue


c	do 30 i=1,nop
c	read(11,*) (k(i,j),j=1,noe(i))
c30	continue


c
c	Vector basis (ei) situated at P
c

	e(1,1)=1
	e(1,2)=0
	e(1,3)=0
	e(2,1)=0
	e(2,2)=1
	e(2,3)=0
	e(3,1)=0
	e(3,2)=0
	e(3,3)=1


c
c	Constants
c
c ##A18##
c	gc=6.67259e-08
c	d=2.67
c	pi=4.*atan(1.)

c ##A25## lê os pontos em que se pretende calcular o potencial e suas derivadas iniciando sempre do sucessor do último ponto do último intervalo em que a integração parou
c      nstored = 0
c      do 2013 l=opflag,nograd-1
c	read(10+3,*,end=2020) xp,yp,zp

c ##A19,135##
        gc = K2
c ##A19,135##
c ##A26## no programa original o potencial e suas derivadas são sempre calculados na origem, isto é, no ponto de coordenadas (0,0,0). Logo, para calcularmos o potencial e suas derivadas em qualquer outro ponto P devemos ter nossa origem nesse novo ponto P e para isso basta transladarmos todas as coordenadas dos pontos do poliedro, subtraindo-as das coordenadas do ponto P
	do 2014 i=1,nov
	x(i)=x2(i)-xp
        y(i)=y2(i)-yp
        z(i)=z2(i)-zp
2014	continue
c
c
c	Building vectors Gij // Equation (17)
c
c

c	v=0
	vx=0
	vy=0
	vz=0
	do 100 i=1,nop
c	do 80 i=1,nop
	do 70 j=1,noe(i)

	if(j.eq.noe(i)) then 

	g(i,j,1)=x(k(i,1))-x(k(i,j))
	g(i,j,2)=y(k(i,1))-y(k(i,j))
	g(i,j,3)=z(k(i,1))-z(k(i,j))


	else


	g(i,j,1)=x(k(i,j+1))-x(k(i,j))
	g(i,j,2)=y(k(i,j+1))-y(k(i,j))
	g(i,j,3)=z(k(i,j+1))-z(k(i,j))

	end if


70	continue

c
c
c	Computation of plane Normals (Np) // Equation (18)
c
c

c	do 80 i=1,nop
	call cross (g(i,1,1),g(i,1,2),g(i,1,3),g(i,2,1),g(i,2,2),
     $g(i,2,3),plnorm(i,1),plnorm(i,2),plnorm(i,3))
	qnorm=snorm(plnorm(i,1),plnorm(i,2),plnorm(i,3))
	plnorm(i,1)=plnorm(i,1)/qnorm
	plnorm(i,2)=plnorm(i,2)/qnorm
	plnorm(i,3)=plnorm(i,3)/qnorm


c
c	Direction cosines computation
c
c
c	Notice: We computed a normed vector, i.e. Np's 
c	        x, y and z components are at the same time
c	        its direction cosines with the three axes.
c

	dcnp(i,1)=plnorm(i,1)
	dcnp(i,2)=plnorm(i,2)
	dcnp(i,3)=plnorm(i,3)


c80	continue



c
c
c	Computation of line segment normals (npq) // Equation (19)
c
c

c	do 90 i=1,nop
	do 90 j=1,noe(i)
	call cross (g(i,j,1),g(i,j,2),g(i,j,3),plnorm(i,1),
     $plnorm(i,2),plnorm(i,3),segnorm(i,j,1),
     $segnorm(i,j,2),segnorm(i,j,3))
	qnorm=snorm(segnorm(i,j,1),segnorm(i,j,2),segnorm(i,j,3))
	segnorm(i,j,1)=segnorm(i,j,1)/qnorm
	segnorm(i,j,2)=segnorm(i,j,2)/qnorm
	segnorm(i,j,3)=segnorm(i,j,3)/qnorm


c
c	Direction cosines computation
c
c
c	Notice: We are computing a normed vector, i.e. npq's 
c	        x, y and z components are at the same time
c	        its direction cosines with the three axes.
c
	dcnpq(i,j,1)=segnorm(i,j,1)
	dcnpq(i,j,2)=segnorm(i,j,2)
	dcnpq(i,j,3)=segnorm(i,j,3)


90	continue



c
c
c	cos(Np,ei), cos(npq,ei)
c
c
c	cs(i,j) = dcnp(i,j)
c
c	and
c
c	cspq(i,j,m) = dcnpq(i,j,m), m = 1,2,3
c
c

c	do 23 i=1,nop
	qnorm1=snorm(plnorm(i,1),plnorm(i,2),plnorm(i,3))
	do 23 j=1,3
	qnorm2=snorm(e(j,1),e(j,2),e(j,3))
	call dot (plnorm(i,1),plnorm(i,2),plnorm(i,3),e(j,1),e(j,2),
     $e(j,3),dotnpi)
	cs(i,j)=dotnpi/(qnorm1*qnorm2)


23	continue
	
c	do 24 i=1,nop
	do 24 j=1,noe(i)
 	do 24 m=1,3
	qnorm1=snorm(segnorm(i,j,1),segnorm(i,j,2),segnorm(i,j,3))
	qnorm2=snorm(e(m,1),e(m,2),e(m,3))
	call dot (segnorm(i,j,1),segnorm(i,j,2),segnorm(i,j,3),e(m,1),
     $e(m,2),e(m,3),dotnpq)
	cspq(i,j,m)=dotnpq/(qnorm1*qnorm2)


24	continue

c
c
c	Distances of P from planes Sp ( h(i) ) 
c	by subroutine 'planedist'
c
c	xo(i), yo(i) and zo(i) are the intersections of Sp(i)
c	with axes x, y and z respectively
c
c	and 
c
c	plane normal orientation ( s(i) ) // Equation (20)
c
c

c	do 60 i=1,nop
	call planedist (x,y,z,k(i,1),k(i,2),k(i,3),h(i),xo(i),yo(i),
     $zo(i))


c60	continue



c	do 41 i=1,nop
	call dot (plnorm(i,1),plnorm(i,2),plnorm(i,3),-x(k(i,1)),
     $-y(k(i,1)),-z(k(i,1)),plnrmor)
	if (plnrmor.gt.0) then
	s(i)=-1
	else if (plnrmor.lt.0) then
	s(i)=1
	else if (plnrmor.eq.0) then
	s(i)=0
	end if


c41	continue





c
c
c	Computation of the projections of P on the 'p' planes
c	of the polyhedron. [P'(x',y',z')]
c
c	xx(i), yy(i), zz(i) // Equation (21)
c
c

c	do 31 i=1,nop

	if (xo(i).ge.0.and.yo(i).ge.0.and.zo(i).ge.0) then
	xx(i)=abs(dcnp(i,1)*h(i))
	yy(i)=abs(dcnp(i,2)*h(i))
	zz(i)=abs(dcnp(i,3)*h(i))

	else if (xo(i).lt.0.and.yo(i).lt.0.and.zo(i).lt.0) then

	 if (dcnp(i,1).gt.0) then
	 xx(i)=-dcnp(i,1)*h(i)
	 else
	 xx(i)=dcnp(i,1)*h(i)
	 end if

	 if (dcnp(i,2).gt.0) then
	 yy(i)=-dcnp(i,2)*h(i)
	 else
	 yy(i)=dcnp(i,2)*h(i)
	 end if

	 if (dcnp(i,3).gt.0) then
	 zz(i)=-dcnp(i,3)*h(i)
	 else
	 zz(i)=dcnp(i,3)*h(i)
	 end if

	else if (xo(i).lt.0.and.yo(i).lt.0) then

	 if (dcnp(i,1).gt.0) then
	 xx(i)=-dcnp(i,1)*h(i)
	 else
	 xx(i)=dcnp(i,1)*h(i)
	 end if

	 if (dcnp(i,2).gt.0) then
	 yy(i)=-dcnp(i,2)*h(i)
	 else
	 yy(i)=dcnp(i,2)*h(i)
	 end if

	zz(i)=abs(dcnp(i,3)*h(i))

	else if (yo(i).lt.0.and.zo(i).lt.0) then
	xx(i)=abs(dcnp(i,1)*h(i))

	 if (dcnp(i,2).gt.0) then
	 yy(i)=-dcnp(i,2)*h(i)
	 else
	 yy(i)=dcnp(i,2)*h(i)
	 end if

	 if (dcnp(i,3).gt.0) then
	 zz(i)=-dcnp(i,3)*h(i)
	 else
	 zz(i)=dcnp(i,3)*h(i)
	 end if

	else if (xo(i).lt.0.and.zo(i).lt.0) then

	 if (dcnp(i,1).gt.0) then
	 xx(i)=-dcnp(i,1)*h(i)
	 else
	 xx(i)=dcnp(i,1)*h(i)
	 end if

	yy(i)=abs(dcnp(i,2)*h(i))

	 if (dcnp(i,3).gt.0) then
	 zz(i)=-dcnp(i,3)*h(i)
	 else
	 zz(i)=dcnp(i,3)*h(i)
	 end if

	else if (xo(i).lt.0) then

	 if (dcnp(i,1).gt.0) then
	 xx(i)=-dcnp(i,1)*h(i)
	 else
	 xx(i)=dcnp(i,1)*h(i)
	 end if

	yy(i)=abs(dcnp(i,2)*h(i))
	zz(i)=abs(dcnp(i,3)*h(i))

	else if (yo(i).lt.0) then
	xx(i)=abs(dcnp(i,1)*h(i))

	 if (dcnp(i,2).gt.0) then
	 yy(i)=-dcnp(i,2)*h(i)
	 else
	 yy(i)=dcnp(i,2)*h(i)
	 end if

	zz(i)=abs(dcnp(i,3)*h(i))

	else if (zo(i).lt.0) then
	xx(i)=abs(dcnp(i,1)*h(i))
	yy(i)=abs(dcnp(i,2)*h(i))

	 if (dcnp(i,3).gt.0) then
	 zz(i)=-dcnp(i,3)*h(i)
	 else
	 zz(i)=dcnp(i,3)*h(i)
	 end if

	end if


c31	continue




c
c	segment normal orientation	
c
c	senrmor = npq (dot) Gpq(ij-->P') // Equation (22)
c

c	do 42 i=1,nop
	do 42 j=1,noe(i)
	call dot (segnorm(i,j,1),segnorm(i,j,2),segnorm(i,j,3),
     $xx(i)-x(k(i,j)),yy(i)-y(k(i,j)),zz(i)-z(k(i,j)),senrmor)
	if (abs(senrmor).lt.1e-10) then
	ss(i,j)=0
	go to 42
	else if (senrmor.gt.0) then
	ss(i,j)=-1
	else if (senrmor.lt.0) then
	ss(i,j)=1
	else if (senrmor.eq.0) then
	ss(i,j)=0
	end if


42	continue



c
c
c	Distances of P' from line segments Gpq (hpq) 
c
c	hh(i,j)
c
c	Computation of the projections of P' on each
c	line segment Gpq, i.e. P''(x'',y''',z''')
c	by calling subroutine 'segmproj'
c
c	xxx(i,j), yyy(i,j), zzz(i,j) // Equations (23) - (25)
c
c

c	do 32 i=1,nop
	do 32 j=1,noe(i)

	if (j.eq.noe(i)) then

	if (ss(i,j).eq.0) then
	hh(i,j)=0
	xxx(i,j)=xx(i)
	yyy(i,j)=yy(i)
	zzz(i,j)=zz(i)
	go to 131
	end if

	call segmproj (x(k(i,j)),y(k(i,j)),z(k(i,j)),
     $x(k(i,1)),y(k(i,1)),z(k(i,1)),
     $xx(i),yy(i),zz(i),xseg,yseg,zseg)
	hh(i,j)=snorm(xseg-xx(i),yseg-yy(i),zseg-zz(i))


	xxx(i,j)=xseg
	yyy(i,j)=yseg
	zzz(i,j)=zseg
	go to 131

	end if

	if (ss(i,j).eq.0) then
	hh(i,j)=0
	xxx(i,j)=xx(i)
	yyy(i,j)=yy(i)
	zzz(i,j)=zz(i)
	go to 131
	end if

	call segmproj (x(k(i,j)),y(k(i,j)),z(k(i,j)),
     $x(k(i,j+1)),y(k(i,j+1)),z(k(i,j+1)),
     $xx(i),yy(i),zz(i),xseg,yseg,zseg)
	hh(i,j)=snorm(xseg-xx(i),yseg-yy(i),zseg-zz(i))


	xxx(i,j)=xseg
	yyy(i,j)=yseg
	zzz(i,j)=zseg

131	continue




32	continue



c
c
c	Computation of V and Vi
c
c

c	v=0
c	vx=0
c	vy=0
c	vz=0

c	do 100 i=1,nop

	sum1=0
	sum2=0
	singarea=0
	singsegm=0
	singvert=0
	
	do 200 j=1,noe(i)




	thisvert=0

	gpqnorm=snorm(g(i,j,1),g(i,j,2),g(i,j,3))

c	
c	check if P' lays inside the polygon Np(i)
c

	if (ss(i,j).eq.1) then
	singarea=singarea+1
	end if

c
c	check if P' lays inside the segment Gpq 
c
c	or
c
c	on the vertex (i,j)
c
c	Condition controlled is  
c
c	ss(i,j) = 0
c

	if (ss(i,j).eq.0) then



	 if(j.eq.noe(i)) then 

	 gx1=xx(i)-x(k(i,1))
	 gx2=xx(i)-x(k(i,j))
	 gy1=yy(i)-y(k(i,1))
	 gy2=yy(i)-y(k(i,j))
	 gz1=zz(i)-z(k(i,1))
	 gz2=zz(i)-z(k(i,j))

	 else  

	 gx2=xx(i)-x(k(i,j))
	 gx1=xx(i)-x(k(i,j+1))
	 gy2=yy(i)-y(k(i,j))
	 gy1=yy(i)-y(k(i,j+1))
	 gz2=zz(i)-z(k(i,j))
	 gz1=zz(i)-z(k(i,j+1))

	 end if

	 enorm1=snorm(gx1,gy1,gz1)
	 enorm2=snorm(gx2,gy2,gz2)




c
c	check for the Vertex (i,j) 
c

	  if (enorm1.eq.0) then

	  singvert=singvert+1

	  thisvert=thisvert+1

	   	if (j.eq.noe(i)) then

	   g1norm=snorm(g(i,j,1),g(i,j,2),g(i,j,3))
	   g2norm=snorm(g(i,1,1),g(i,1,2),g(i,1,3))

	call dot(-g(i,j,1),-g(i,j,2),-g(i,j,3),g(i,1,1),g(i,1,2),
     $g(i,1,3),gdot)

	     		if (gdot.eq.0) then

	     theta=pi/2

	     		else

	     theta=dacos(gdot/(g1norm*g2norm))

	     		end if

	   	else

	   g1norm=snorm(g(i,j,1),g(i,j,2),g(i,j,3))
	   g2norm=snorm(g(i,j+1,1),g(i,j+1,2),g(i,j+1,3))

	call dot(-g(i,j,1),-g(i,j,2),-g(i,j,3),g(i,j+1,1),g(i,j+1,2),
     $g(i,j+1,3),gdot)

	     		if (gdot.eq.0) then

	     theta=pi/2

	     		else

	     theta=dacos(gdot/(g1norm*g2norm))

	     		end if

	   	end if

	  end if


	  if (enorm2.eq.0) then

	  singvert=singvert+1

	  thisvert=thisvert+1

	   	if (j.eq.1) then

	   g1norm=snorm(g(i,noe(i),1),g(i,noe(i),2),g(i,noe(i),3))
	   g2norm=snorm(g(i,1,1),g(i,1,2),g(i,1,3))

	call dot(-g(i,noe(i),1),-g(i,noe(i),2),-g(i,noe(i),3),
     $g(i,1,1),g(i,1,2),g(i,1,3),gdot)
     
	     		if (gdot.eq.0) then

	     theta=pi/2

	     		else

	     theta=dacos(gdot/(g1norm*g2norm))

	     		end if

	   	else

	   g1norm=snorm(g(i,j-1,1),g(i,j-1,2),g(i,j-1,3))
	   g2norm=snorm(g(i,j,1),g(i,j,2),g(i,j,3))

	call dot(-g(i,j-1,1),-g(i,j-1,2),-g(i,j-1,3),g(i,j,1),g(i,j,2),
     $g(i,j,3),gdot)

	     		if (gdot.eq.0) then

	     theta=pi/2

	     		else

	     theta=dacos(gdot/(g1norm*g2norm))

	     		end if

	   	end if

	  end if




	      if (enorm1.lt.gpqnorm.and.enorm2.lt.gpqnorm) then

	      singsegm=singsegm+1

	      end if




	end if









c
c
c	d1, d2 (i.e. s1, s2) are the distances of P'' (projection
c	of P' on Gpq) from the segments' Gpq vertices.
c	P'' is taken
c	as the origin of a 1-dimensional local coordinate system
c	on Gpq.
c	f1, f2 (i.e. r1, r2) are the 3d-distances of the vertices 
c	of Gpq from field point P.
c
c						



	if (j.eq.noe(i)) then

	d1=snorm(xxx(i,j)-x(k(i,j)),yyy(i,j)-y(k(i,j)),
     $zzz(i,j)-z(k(i,j)))
	d2=snorm(xxx(i,j)-x(k(i,1)),yyy(i,j)-y(k(i,1)),
     $zzz(i,j)-z(k(i,1)))
	f1=snorm(x(k(i,j)),y(k(i,j)),z(k(i,j)))
	f2=snorm(x(k(i,1)),y(k(i,1)),z(k(i,1)))

	if (abs(d1-f1).lt.1e-10.and.abs(d2-f2).lt.1e-10) then
	go to 1968
	end if


	else 

	d1=snorm(xxx(i,j)-x(k(i,j)),yyy(i,j)-y(k(i,j)),
     $zzz(i,j)-z(k(i,j)))
	d2=snorm(xxx(i,j)-x(k(i,j+1)),yyy(i,j)-y(k(i,j+1)),
     $zzz(i,j)-z(k(i,j+1)))
	f1=snorm(x(k(i,j)),y(k(i,j)),z(k(i,j)))
	f2=snorm(x(k(i,j+1)),y(k(i,j+1)),z(k(i,j+1)))


	if (abs(d1-f1).lt.1e-10.and.abs(d2-f2).lt.1e-10) then
	go to 1968
	end if



	end if



c	
c	check if P'' is located inside the segment Gpq
c

	if (d1.lt.gpqnorm.and.d2.lt.gpqnorm) then
	s1=-d1
	s2=d2
	r1=f1
	r2=f2
	go to 1972
	end if

	if (d1.lt.d2) then

	s1=d1
	s2=d2
	r1=f1
	r2=f2

	else if (d2.lt.d1) then

	s1=-d1
	s2=-d2
	r1=f1
	r2=f2

	end if


	go to 1972






1968	if (d1.lt.d2) then

	s1=d1
	s2=d2
	r1=f1
	r2=f2

	else if (d2.lt.d1) then

	s1=-d1
	s2=-d2
	r1=-f1
	r2=-f2

	else if (d1.eq.d2) then

	s1=-d1
	s2=d2
	r1=-f1
	r2=f2

	end if


1972	continue


	if (h(i).eq.0) then

	   if (thisvert.gt.0) then
	   c1=0
	   c2=0
	   go to 1973
	   end if


	if ((s1+s2).lt.1e-10.and.(r1+r2).lt.1e-10) then
	c1=0
	c2=0
	go to 1973
	end if

	c1=fln(s2,r2,s1,r1)
	c2=0

	
	go to 1973

	end if


	if (thisvert.gt.0) then
	c1=0
	else
	c1=fln(s2,r2,s1,r1)
	end if

	if (hh(i,j).eq.0) then
	c2=0
	else
	c2=fan(h(i),hh(i,j),s1,s2,r1,r2)
	end if

1973	continue

	sum1=sum1+ss(i,j)*hh(i,j)*c1
	sum2=sum2+ss(i,j)*c2



200	continue


c
c	If P' lays inside the polygon Ap then
c	ALL of ss(i,j) = 1. In that case sing = noe(i)
c	and the following correction has to be applied
c
c	Ap = lim (Ap) = Ap - 2*pi*h(i)
c	       R->0
c
c	If P' lays on an edge Gpq the above correction term is
c	
c	                   - pi*h(i)
c
c	and finally when P' is located on a vertex of Ap we get
c
c	                   - theta*h(i) 
c	where
c
c	theta = arccos{ (g1 (dot) g2) / (|g1||g2|) }, g1 and g2 are
c	the two vectors Gpq meeting at the vertex.
c
c	theta has already been computed (see above)
c


	if (singarea.eq.noe(i)) then
	area=2*pi*h(i)
	else
	area=0
	end if

	if (singsegm.gt.0) then
	edge=pi*h(i)
	else 
	edge=0
	end if

	if (singvert.gt.0) then
	vertex=theta*h(i)
	else
	vertex=0
	end if


c     
c     Final computation of Equations (10) and (11)
c


c	v=v+s(i)*h(i)*(sum1+h(i)*sum2-area-edge-vertex)
	vx=vx+cs(i,1)*(sum1+h(i)*sum2-area-edge-vertex)
	vy=vy+cs(i,2)*(sum1+h(i)*sum2-area-edge-vertex)
	vz=vz+cs(i,3)*(sum1+h(i)*sum2-area-edge-vertex)




100	continue

c ##A27##
c	v=(v*gc*d)/2
c	vx=abs(vx*gc*d)
c	vy=abs(vy*gc*d)
c	vz=abs(vz*gc*d)
c	v=(v*abs(gc*d))/2
	vx=vx*abs(gc*d)
	vy=vy*abs(gc*d)
	vz=vz*abs(gc*d)




c
c
c	Computation of Vij
c
c
	do 901 i=1,3
c	do 901 j=1,3
        j = i
	vij(i,j)=0
901	continue

	do 400 i=1,3
        j = i
c	do 500 j=1,3


		do 600 m=1,nop

		sum1=0
		sum2=0

		singarea=0
		singsegm=0
		singvert=0



		do 700 n=1,noe(m)

		thisvert=0

		gpqnorm=snorm(g(m,n,1),g(m,n,2),g(m,n,3))

c	
c		check if P' lays inside the polygon Np(m)
c

		if (ss(m,n).eq.1) then
		singarea=singarea+1
		end if



c
c		check if P' lays inside the segment Gpq
c
c		or
c
c		on the vertex (m,n)
c
c		Condition controlled is  
c
		ss(m,n) = 0
c

		if (ss(m,n).eq.0) then

		if (n.eq.noe(m)) then 

		gx1=xx(m)-x(k(m,1))
		gx2=xx(m)-x(k(m,n))
		gy1=yy(m)-y(k(m,1))
		gy2=yy(m)-y(k(m,n))
		gz1=zz(m)-z(k(m,1))
		gz2=zz(m)-z(k(m,n))

		else  

		gx2=xx(m)-x(k(m,n))
		gx1=xx(m)-x(k(m,n+1))
		gy2=yy(m)-y(k(m,n))
		gy1=yy(m)-y(k(m,n+1))
		gz2=zz(m)-z(k(m,n))
		gz1=zz(m)-z(k(m,n+1))

		end if

		enorm1=snorm(gx1,gy1,gz1)
		enorm2=snorm(gx2,gy2,gz2)



c
c		check if P' lays on the Vertex (m,n) 
c

		if (enorm1.eq.0) then

		singvert=singvert+1

		thisvert=thisvert+1

		if (n.eq.noe(m)) then

		g1norm=snorm(g(m,n,1),g(m,n,2),g(m,n,3))
		g2norm=snorm(g(m,1,1),g(m,1,2),g(m,1,3))

	


	call dot(-g(m,n,1),-g(m,n,2),-g(m,n,3),g(m,1,1),g(m,1,2),
     $g(m,1,3),gdot)

			if (gdot.eq.0) then

			theta=pi/2

			else

			theta=dacos(gdot/(g1norm*g2norm))

			end if

		else

		g1norm=snorm(g(m,n,1),g(m,n,2),g(m,n,3))
		g2norm=snorm(g(m,n+1,1),g(m,n+1,2),g(m,n+1,3))




	call dot(-g(m,n,1),-g(m,n,2),-g(m,n,3),g(m,n+1,1),g(m,n+1,2),
     $g(m,n+1,3),gdot)

			if (gdot.eq.0) then

			theta=pi/2

			else

			theta=dacos(gdot/(g1norm*g2norm))

			end if

		end if

		end if



		if (enorm2.eq.0) then

		singvert=singvert+1

		thisvert=thisvert+1

		if (n.eq.1) then

	g1norm=snorm(g(m,noe(m),1),g(m,noe(m),2),g(m,noe(m),3))
	g2norm=snorm(g(m,1,1),g(m,1,2),g(m,1,3))


	call dot(-g(m,noe(m),1),-g(m,noe(m),2),-g(m,noe(m),3),
     $g(m,1,1),g(m,1,2),g(m,1,3),gdot)

			if (gdot.eq.0) then

			theta=pi/2

			else

			theta=dacos(gdot/(g1norm*g2norm))

			end if

		else

	g1norm=snorm(g(m,n-1,1),g(m,n-1,2),g(m,n-1,3))
	g2norm=snorm(g(m,n,1),g(m,n,2),g(m,n,3))


	call dot(-g(m,n-1,1),-g(m,n-1,2),-g(m,n-1,3),g(m,n,1),g(m,n,2),
     $g(m,n,3),gdot)

			if (gdot.eq.0) then

			theta=pi/2

			else

			theta=dacos(gdot/(g1norm*g2norm))

			end if

		end if

		end if

		if (enorm1.lt.gpqnorm.and.enorm2.lt.gpqnorm) then

		singsegm=singsegm+1

		end if

		end if





c
c
c	d1, d2 (i.e. s1, s2) are the distances of P'' (projection
c	of P' on Gpq) from the segments' Gpq vertices.
c	P'' is taken
c	as the origin of a 1-dimensional local coordinate system
c	on Gpq.
c	f1, f2 (i.e. r1, r2) are the 3d-distances of the vertices 
c	of Gpq from filed point P.
c
c



		if (n.eq.noe(m)) then

		d1=snorm(xxx(m,n)-x(k(m,n)),yyy(m,n)-
     $y(k(m,n)),
     $zzz(m,n)-z(k(m,n)))
		d2=snorm(xxx(m,n)-x(k(m,1)),yyy(m,n)-
     $y(k(m,1)),
     $zzz(m,n)-z(k(m,1)))
		f1=snorm(x(k(m,n)),y(k(m,n)),z(k(m,n)))
		f2=snorm(x(k(m,1)),y(k(m,1)),z(k(m,1)))


	if (abs(d1-f1).lt.1e-10.and.abs(d2-f2).lt.1e-10) then
	go to 1958
	end if

		else

		d1=snorm(xxx(m,n)-x(k(m,n)),yyy(m,n)-
     $y(k(m,n)),
     $zzz(m,n)-z(k(m,n)))
		d2=snorm(xxx(m,n)-x(k(m,n+1)),
     $yyy(m,n)-y(k(m,n+1)),zzz(m,n)-z(k(m,n+1)))
		f1=snorm(x(k(m,n)),y(k(m,n)),z(k(m,n)))
		f2=snorm(x(k(m,n+1)),y(k(m,n+1)),z(k(m,n+1)))


	if (abs(d1-f1).lt.1e-10.and.abs(d2-f2).lt.1e-10) then
	go to 1958
	end if

		end if



c	
c	check if P'' is located inside the segment Gpq
c

	if (d1.lt.gpqnorm.and.d2.lt.gpqnorm) then
	s1=-d1
	s2=d2
	r1=f1
	r2=f2
	go to 1982
	end if

c
c	1-D Coordinate system orientation
c

	if (d1.lt.d2) then

	s1=d1
	s2=d2
	r1=f1
	r2=f2

	else if (d2.lt.d1) then

	s1=-d1
	s2=-d2
	r1=f1
	r2=f2

	end if

	go to 1982

1958	if (d1.lt.d2) then

	s1=d1
	s2=d2
	r1=f1
	r2=f2

	else if (d2.lt.d1) then

	s1=-d1
	s2=-d2
	r1=-f1
	r2=-f2

	end if


1982	continue

	if (h(m).eq.0) then

	   if (thisvert.gt.0) then
	   c1=0
	   c2=0
	   go to 1983
	   end if

	c1=fln(s2,r2,s1,r1)
	c2=0

	go to 1983

	end if


	if (thisvert.gt.0) then
	c1=0
	else
	c1=fln(s2,r2,s1,r1)
	end if

	if (hh(m,n).eq.0) then
	c2=0
	else
	c2=fan(h(m),hh(m,n),s1,s2,r1,r2)
	end if

1983	continue




		sum1=sum1+cspq(m,n,j)*c1
		sum2=sum2+ss(m,n)*c2



700	continue



c
c	If P' lays inside the polygon Ap then
c	ALL of ss(m,n) = 1. In that case sing = noe(m)
c	and the following correction has to be applied
c
c	Ap = lim (Ap) = Ap - 2*pi*h(m)
c	       R->0
c
c	If P' lays on an edge Gpq the above correction term is
c	
c	                   - pi*h(m)
c
c	and finally when P' is located on a vertex of Ap we get
c
c	                   - theta*h(m) 
c	where
c
c	theta = arccos{(g1 (dot) g2) / (|g1||g2|)}, g1 and g2 are
c	the two vectors Gpq meeting at the vertex.
c


	if (singarea.eq.noe(m)) then
	area=2*pi
	else
	area=0
	end if

	if (singsegm.gt.0) then
	edge=pi
	else 
	edge=0
	end if

	if (singvert.gt.0) then
	vertex=theta
	else
	vertex=0
	end if


c     
c     Final computation of Equations (12)
c

	
	vij(i,j)=vij(i,j)+cs(m,i)*(sum1+s(m)*cs(m,j)*(sum2-area
     $-edge-vertex))



600	continue

c500	continue
400	continue


	do 900 i=1,3
c	do 900 j=1,3
        j = i
c	vij(i,j)=vij(i,j)*gc*d
	vij(i,j)=vij(i,j)*abs(gc*d)
900	continue
c
        lapla0 = vij(1,1)+vij(2,2)+vij(3,3)
        if (dabs(lapla0).le.TINY) then
          lapla = 0
        else
          lapla = 1
        end if
c
c ##A28##
c	write(13,*) 'V = ',v
c	write(13,*) 'Vx = ',vx
c	write(13,*) 'Vy = ',vy
c	write(13,*) 'Vz = ',vz
c	write(13,*) 'Vxx = ',vij(1,1)
c	write(13,*) 'Vyy = ',vij(2,2)
c	write(13,*) 'Vzz = ',vij(3,3)
c	write(13,*) 'Vxy = ',vij(1,2)
c	write(13,*) 'Vxz = ',vij(1,3)
c	write(13,*) 'Vyz = ',vij(2,3)

c ##A29## cálculo do pseudo potencial (D. J. SCHEERES AND S. J. OSTRO - Orbits Close to Asteroid 4769 Castalia (equações 18 e 19))
c        J = -omg*omg*(xp*xp + yp*yp)/2.0d0 -v

c ##A33##
c Output data for all bodies
c      call mio_out (opt,nstored,l,xp,yp,zp,v,vx,vy,vz,
c     %  vij,omg,nflush,nograd,outfile,dumpfile,mem,lmem,nov,
c     %  nop,d0,T)

c ##A30## fim da leitura dos pontos em que se pretende calcular o potencial e suas derivadas
c2013  continue
c ##A31## fecha o arquivo de entrada dos pontos em que se pretende calcular o potencial e suas derivadas (13)
c2020    close (10+3)
c ##A32## termina a execução do programa
c      write (*,'(a)') mem(10)(1:lmem(10))
c	stop
c1001	format(3i4)
c1002	format(7(4i2)/)

        return
	end
c
c ##A43,54##
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      READBINPOL2C2.FOR    (16 October 2017)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Read computed center of mass from cube file.
c
c------------------------------------------------------------------------------
c
      subroutine readbinpol2c2 (binfile,mem,lmem,ninfile,noc,mcen,vcb,
     %  J0,xc,yc,zc,mc,xct,yct,zct,T1b,T2,TP)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer lmem(NMESS)
      character*80 mem(NMESS)
      character*80 binfile(101)
      integer ninfile
      real*8 xc(noc),yc(noc),zc(noc),mc(noc)
      real*8 mcen,vc,J0(3,3),mcenb
      integer noc
      real*8 xct,yct,zct
      real*8 T1b(3),T2(3),TP(3)
c
c Local
      character*80 filename
      integer lim(2,1000),nsub
      integer i,l,j,itmp
      character*15000 string
      character*80 c80
      integer lineno
      character*7 c7
      real*8 xctb,yctb,zctb,vcb,cubx,cuby,cubz
c
c------------------------------------------------------------------------------
c
      do i = 1, 80
        filename(i:i) = ' '
      end do
c
      call mio_spl (150,binfile(101),nsub,lim)
      filename(1:lim(2,1)) = binfile(101)(lim(1,1):lim(2,1))

      itmp = lim(2,1)
c
c  LOOP  OVER  EACH  INPUT  FILE  CONTAINING  INTEGRATION  DATA
c
      do l = 1, ninfile
        i = ninfile - l + 1
        lineno = 0
        write (*,'(a13,1x,a)') 'Reading file:',binfile(i)
        call mio_spl (150,binfile(i),nsub,lim)
        filename(itmp+1:itmp+lim(2,1)-lim(1,1)+1) =
     %    binfile(i)(lim(1,1):lim(2,1))
c
        open (10, file=filename, status='old', access='sequential')
c
  40    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 40
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 40
        c80 = string(lim(1,1):lim(2,1))
        read (c80,*,err=661,end=667) noc
        c80 = string(lim(1,2):lim(2,2))
        read (c80,*,err=661,end=667) mcenb
        c80 = string(lim(1,3):lim(2,3))
        read (c80,*,err=661,end=667) vcb
        c80 = string(lim(1,4):lim(2,4))
        read (c80,*,err=661,end=667) xctb
        c80 = string(lim(1,5):lim(2,5))
        read (c80,*,err=661,end=667) yctb
        c80 = string(lim(1,6):lim(2,6))
        read (c80,*,err=661,end=667) zctb
c
  50    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 50
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 50
        c80 = string(lim(1,1):lim(2,1))
        read (c80,*,err=661,end=667) cubx
        c80 = string(lim(1,2):lim(2,2))
        read (c80,*,err=661,end=667) cuby
        c80 = string(lim(1,3):lim(2,3))
        read (c80,*,err=661,end=667) cubz
c
  80    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 80
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 80
        c80 = string(lim(1,1):lim(2,1))
        read (c80,*,err=661,end=667) xct
        c80 = string(lim(1,2):lim(2,2))
        read (c80,*,err=661,end=667) yct
        c80 = string(lim(1,3):lim(2,3))
        read (c80,*,err=661,end=667) zct
        c80 = string(lim(1,4):lim(2,4))
        read (c80,*,err=661,end=667) mcen
        c80 = string(lim(1,5):lim(2,5))
        read (c80,*,err=661,end=667) vc
c
        do j = 1, 3
  60      read (10,'(a15000)',end=667) string
          lineno = lineno + 1
          if (string(1:1).eq.')') goto 60
          call mio_spl (15000,string,nsub,lim)
          if (lim(1,1).eq.-1) goto 60
          c80 = string(lim(1,1):lim(2,1))
          read (c80,*,err=661,end=667) J0(j,1)
          c80 = string(lim(1,2):lim(2,2))
          read (c80,*,err=661,end=667) J0(j,2)
          c80 = string(lim(1,3):lim(2,3))
          read (c80,*,err=661,end=667) J0(j,3)
        end do
c
  61    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 61
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 61
        c80 = string(lim(1,1):lim(2,1))
        read (c80,*,err=661,end=667) T1b(1)
        c80 = string(lim(1,2):lim(2,2))
        read (c80,*,err=661,end=667) T1b(2)
        c80 = string(lim(1,3):lim(2,3))
        read (c80,*,err=661,end=667) T1b(3)
  62    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 62
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 62
        c80 = string(lim(1,1):lim(2,1))
        read (c80,*,err=661,end=667) T2(1)
        c80 = string(lim(1,2):lim(2,2))
        read (c80,*,err=661,end=667) T2(2)
        c80 = string(lim(1,3):lim(2,3))
        read (c80,*,err=661,end=667) T2(3)
  63    read (10,'(a15000)',end=667) string
        lineno = lineno + 1
        if (string(1:1).eq.')') goto 63
        call mio_spl (15000,string,nsub,lim)
        if (lim(1,1).eq.-1) goto 63
        c80 = string(lim(1,1):lim(2,1))
        read (c80,*,err=661,end=667) TP(1)
        c80 = string(lim(1,2):lim(2,2))
        read (c80,*,err=661,end=667) TP(2)
        c80 = string(lim(1,3):lim(2,3))
        read (c80,*,err=661,end=667) TP(3)
c
        do j = 1, noc
  70      read (10,'(a15000)',end=667) string
          lineno = lineno + 1
          if (string(1:1).eq.')') goto 70
          call mio_spl (15000,string,nsub,lim)
          if (lim(1,1).eq.-1) goto 70
          c80 = string(lim(1,1):lim(2,1))
          read (c80,*,err=661,end=667) xc(j)
          c80 = string(lim(1,2):lim(2,2))
          read (c80,*,err=661,end=667) yc(j)
          c80 = string(lim(1,3):lim(2,3))
          read (c80,*,err=661,end=667) zc(j)
          c80 = string(lim(1,4):lim(2,4))
          read (c80,*,err=661,end=667) mc(j)
        end do
        close (10)
      end do
c
 667  continue
      if(lineno.eq.0) then
        write(6,'(/,3(1x),2(a,1x),/)') 'Error:',
     %    'No center mass point was found.'
        stop
      end if      
c
c termina a execução do programa
      write (6,'(a)') 'Process completed successfully!'
c
c------------------------------------------------------------------------------
c
      return
c
c------------------------------------------------------------------------------
c
c Error reading from the input file containing integration parameters
 661  write (c7,'(i7)') lineno
      call mio_err (6,mem(81),lmem(81),mem(99),lmem(99),c7,7,
     %  mem(85),lmem(85))
c
c------------------------------------------------------------------------------
c
      end
c
c------------------------------------------------------------------------------
c
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MASC_LAYER3.FOR    (27 Ago 2020)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Calculates the pieces of masses of each pyramidal frustum layer of a polyhedron.
c Also calculates the volumens, centroids and inertia tensor of each pyramidal
c frustum layer.
c

c------------------------------------------------------------------------------
c
      subroutine masc_layer3 (nov,nop,xv,yv,zv,noe,k,d,
     %  fmt,fvt,xc,yc,zc,mem,lmem,l0,cubx,cuby,cubz,mc)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer lmem(NMESS)
      character*80 mem(NMESS)
      integer nov,nop,noe,k,l0
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(nocen),yc(nocen),zc(nocen),d,mc(nocen)
      real*8 cubx,cuby,cubz
      dimension noe(nopmax)
      dimension k(nopmax,noed)
c
c Local
      integer i
c      integer i,j,l,ilay,novl,nopl
c      integer noel,kl
c      real*8 del,inc,nx,ny,nz
c      real*8 xl(nov),yl(nov),zl(nov)
c      real*8 norm(nopmax,3),wfac(nopmax)
c      real*8 T0,T1(3),T2(3),TP(3)
c      real*8 fvt,fmt,vol,vol1,vol2
c      real*8 J0(3,3)
      real*8 fvt,fmt
      real*8 xmin,xmax,ymin,ymax,zmin,zmax
      real*8 xstep,ystep,zstep,xcoor,ycoor,zcoor,mass,vol
      integer astflag1
c      integer astflag1,astflag2
c      real*8 xvc(8),yvc(8),zvc(8)
c      real*8 cubx,cuby,cubz
c      real*8 xl2(nov),yl2(nov),zl2(nov)
c      dimension noel(nopmax)
c      dimension kl(nopmax,noed)
c
c------------------------------------------------------------------------------
c
c      del = 1.d0 / lay
c      vt = 0.d0
c      mt = 0.d0
      l0 = 0
c
c      T1t(1) = 0.0
c      T1t(2) = 0.0
c      T1t(3) = 0.0
c      T2t(1) = 0.0
c      T2t(2) = 0.0
c      T2t(3) = 0.0
c      TPt(1) = 0.0
c      TPt(2) = 0.0
c      TPt(3) = 0.0
c central point (origin)
c      xl(1) = 0.0
c      yl(1) = 0.0
c      zl(1) = 0.0
c
c      cubx = 1.d0 / cubx0
c      cuby = 1.d0 / cuby0
c      cubz = 1.d0 / cubz0
c      cubx = cubx0
c      cuby = cuby0
c      cubz = cubz0
c
c compute xmin, xmax, ymin, ymax, zmin e zmax
      do i = 1, nov
        if (i.eq.1) then
          xmin=xv(i)
          xmax=xv(i)
          ymin=yv(i)
          ymax=yv(i)
          zmin=zv(i)
          zmax=zv(i)
        end if
c
        if(xv(i).lt.xmin) xmin = xv(i)
        if(xv(i).gt.xmax) xmax = xv(i)
        if(yv(i).lt.ymin) ymin = yv(i)
        if(yv(i).gt.ymax) ymax = yv(i)
        if(zv(i).lt.zmin) zmin = zv(i)
        if(zv(i).gt.zmax) zmax = zv(i)
      end do
c
c      do ilay = 1, lay
c        inc = del * ilay
c
c        do i = 1, nov
c
c compute new vertices
c          xl(i) = xv(i) * inc
c          yl(i) = yv(i) * inc
c          zl(i) = zv(i) * inc
c          if (ilay.gt.1) then
c            xl2(i) = xv(i) * del * (ilay-1)
c            yl2(i) = yv(i) * del * (ilay-1)
c            zl2(i) = zv(i) * del * (ilay-1)
c          end if
c
c          if (i.eq.1) then
c            xmin=xl(i)
c            xmax=xl(i)
c            ymin=yl(i)
c            ymax=yl(i)
c            zmin=zl(i)
c            zmax=zl(i)
c          end if
c
c          if(xl(i).lt.xmin) xmin = xl(i)
c          if(xl(i).gt.xmax) xmax = xl(i)
c          if(yl(i).lt.ymin) ymin = yl(i)
c          if(yl(i).gt.ymax) ymax = yl(i)
c          if(zl(i).lt.zmin) zmin = zl(i)
c          if(zl(i).gt.zmax) zmax = zl(i)
c        end do
c
        fvt = 0.d0
        fmt = 0.d0
c
        zstep = zmin
        do while (zstep.lt.zmax)
          ystep = ymin
          do while (ystep.lt.ymax)
            xstep = xmin
            do while (xstep.lt.xmax)
              xcoor = xstep + 0.5d0 * cubx
              ycoor = ystep + 0.5d0 * cuby
              zcoor = zstep + 0.5d0 * cubz
c check if the point is inside (iflag=1) or outside (iflag=0) the polyhedron using the tetrahedron method
              call tetrah (nov,nop,xv,yv,zv,noe,k,xcoor,ycoor,zcoor,
     %          astflag1)
c
              if (astflag1.eq.1) then
c                if (ilay.le.1) then
c                  astflag2 = 0
c                else
c check if the point is inside (iflag=1) or outside (iflag=0) the polyhedron using the tetrahedron method
c                  call tetrah (nov,nop,xl2,yl2,zl2,noe,k,
c     %              xcoor,ycoor,zcoor,astflag2)
c                end if
c                if (astflag2.eq.0) then
c compute cubic vertices
c                xvc(1) = xstep
c                yvc(1) = ystep
c                zvc(1) = zstep
c                xvc(2) = xstep + cubx
c                yvc(2) = ystep
c                zvc(2) = zstep
c                xvc(3) = xstep + cubx
c                yvc(3) = ystep + cuby
c                zvc(3) = zstep
c                xvc(4) = xstep
c                yvc(4) = ystep + cuby
c                zvc(4) = zstep
c                xvc(5) = xstep
c                yvc(5) = ystep
c                zvc(5) = zstep + cubz
c                xvc(6) = xstep + cubx
c                yvc(6) = ystep
c                zvc(6) = zstep + cubz
c                xvc(7) = xstep + cubx
c                yvc(7) = ystep + cuby
c                zvc(7) = zstep + cubz
c                xvc(8) = xstep
c                yvc(8) = ystep + cuby
c                zvc(8) = zstep + cubz
c
c compute cubic's faces
c                noel(1) = 4
c                kl(1,1) = 4
c                kl(1,2) = 3
c                kl(1,3) = 2
c                kl(1,4) = 1
c
c                noel(2) = 4
c                kl(2,1) = 1
c                kl(2,2) = 2
c                kl(2,3) = 6
c                kl(2,4) = 5
c
c                noel(3) = 4
c                kl(3,1) = 2
c                kl(3,2) = 3
c                kl(3,3) = 7
c                kl(3,4) = 6
c
c                noel(4) = 4
c                kl(4,1) = 3
c                kl(4,2) = 4
c                kl(4,3) = 8
c                kl(4,4) = 7
c
c                noel(5) = 4
c                kl(5,1) = 4
c                kl(5,2) = 1
c                kl(5,3) = 5
c                kl(5,4) = 8
c
c                noel(6) = 4
c                kl(6,1) = 5
c                kl(6,2) = 6
c                kl(6,3) = 7
c                kl(6,4) = 8
c
c compute volumens
c                nopl = 6
c compute normal faces and w vector
c                do j = 1, nopl
c                  call compnormalface (nov,nop,j,xvc,yvc,zvc,kl,
c     %              nx,ny,nz)
c                  norm(j,1) = nx
c                  norm(j,2) = ny
c                  norm(j,3) = nz
c                  wfac(j) = - norm(j,1) * xvc(kl(j,1))
c     %                      - norm(j,2) * yvc(kl(j,1))
c     %                      - norm(j,3) * zvc(kl(j,1))
c                enddo
c compute volumen of a cube
c                call compVolumeIntegrals (nov,nop,nopl,xvc,yvc,zvc,
c     %            noel,kl,norm,wfac,T0,T1,T2,TP)
c                fvt = fvt + T0
c                T1t(1) = T1t(1) + T1(1)
c                T1t(2) = T1t(2) + T1(2)
c                T1t(3) = T1t(3) + T1(3)
c                T2t(1) = T2t(1) + T2(1)
c                T2t(2) = T2t(2) + T2(2)
c                T2t(3) = T2t(3) + T2(3)
c                TPt(1) = TPt(1) + TP(1)
c                TPt(2) = TPt(2) + TP(2)
c                TPt(3) = TPt(3) + TP(3)
c compute pieces of masses
                l0 = l0 + 1
                vol = cubx * cuby * cubz
c                m(l0) = d(ilay) * T0
c                fmt = fmt + m(l0)
                mass = d * vol
                mc(l0) = mass
                fmt = fmt + mass
                fvt = fvt + vol
                xc(l0) = xcoor
                yc(l0) = ycoor
                zc(l0) = zcoor
c compute center of masses of a cube
c                call compcenpolyhedron (d(ilay),m(l0),T0,T1,
c     %            T2,TP,xc(l0),yc(l0),zc(l0),J0)
c                Jt(1,1) = Jt(1,1) + J0(1,1)
c                Jt(1,2) = Jt(1,2) + J0(1,2)
c                Jt(1,3) = Jt(1,3) + J0(1,3)
c                Jt(2,1) = Jt(2,1) + J0(2,1)
c                Jt(2,2) = Jt(2,2) + J0(2,2)
c                Jt(2,3) = Jt(2,3) + J0(2,3)
c                Jt(3,1) = Jt(3,1) + J0(3,1)
c                Jt(3,2) = Jt(3,2) + J0(3,2)
c                Jt(3,3) = Jt(3,3) + J0(3,3)
c              end if
              end if
              xstep = xstep + cubx
            end do
            ystep = ystep + cuby
          end do
          zstep = zstep + cubz
        end do
c
c        vt = vt + fvt
c        mt = mt + fmt
        if (l0.gt.nocen) call mio_err (6,mem(1),lmem(1),mem(24),
     %    lmem(24),' ',1,mem(2),lmem(2))
c
c compute mascons' masses
c        do i = 1, l0
c          m(i) = mcen / l0
c        enddo
c
c      end do
c
c------------------------------------------------------------------------------
c
      return
      end
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c      MASC_LAYER4B.FOR    (28 Ago 2020)
c
c%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
c
c Author: Andre Amarante (A. Amarante) - andre.amarante@unesp.br
c
c Calculates the pieces of masses of each pyramidal frustum layer of a polyhedron.
c Also calculates the volumens, centroids and inertia tensor of each pyramidal
c frustum layer.
c

c------------------------------------------------------------------------------
c
      subroutine masc_layer4b (nov,nop,xv,yv,zv,noe,k,d,
     %  fmt,fvt,xc,yc,zc,mem,lmem,l0,cubx,cuby,cubz,mc)
c
      implicit none
      include 'mercury.inc'
c
c Input/Output
      integer lmem(NMESS)
      character*80 mem(NMESS)
      integer nov,nop,noe,k,l0
      real*8 xv(nov),yv(nov),zv(nov)
      real*8 xc(nocen),yc(nocen),zc(nocen),d,mc(nocen)
      real*8 cubx,cuby,cubz,eixa,eixb,eixc
      dimension noe(nopmax)
      dimension k(nopmax,noed)
c
c Local
      integer i
      real*8 fvt,fmt
      real*8 xmin,xmax,ymin,ymax,zmin,zmax
      real*8 xstep,ystep,zstep,xcoor,ycoor,zcoor,mass,vol
      integer astflag1
c      real*8 a2,b2,c2,test
c
c------------------------------------------------------------------------------
c
      l0 = 0
c
c compute xmin, xmax, ymin, ymax, zmin e zmax
      do i = 1, nov
        if (i.eq.1) then
          xmin=xv(i)
          xmax=xv(i)
          ymin=yv(i)
          ymax=yv(i)
          zmin=zv(i)
          zmax=zv(i)
        end if
c
        if(xv(i).lt.xmin) xmin = xv(i)
        if(xv(i).gt.xmax) xmax = xv(i)
        if(yv(i).lt.ymin) ymin = yv(i)
        if(yv(i).gt.ymax) ymax = yv(i)
        if(zv(i).lt.zmin) zmin = zv(i)
        if(zv(i).gt.zmax) zmax = zv(i)
      end do
c
        fvt = 0.d0
        fmt = 0.d0
c
c      if (eixa.eq.0.d0) then
c        a2 = 0.d0
c      else
c        a2 = 1.d0/eixa
c      end if
c      if (eixb.eq.0.d0) then
c        b2 = 0.d0
c      else
c        b2 = 1.d0/eixb
c      end if
c      if (eixc.eq.0.d0) then
c        c2 = 0.d0
c      else
c        c2 = 1.d0/eixc
c      end if
c
c 1º Octante
c        write(6,'(a21)') 'Starting 1 Octant...'
        zstep = 0.d0
        do while (zstep.lt.zmax)
          ystep = 0.d0
          do while (ystep.lt.ymax)
            xstep = 0.d0
            do while (xstep.lt.xmax)
              xcoor = xstep + 0.5d0 * cubx
              ycoor = ystep + 0.5d0 * cuby
              zcoor = zstep + 0.5d0 * cubz
c check if the point is inside (iflag=1) or outside (iflag=0) the polyhedron using the tetrahedron method
c              astflag1 = 1
c              test = xcoor*xcoor*a2+ycoor*ycoor*b2+zcoor*zcoor*c2 -1.d0
c              if (test.gt.0.d0.or.test.eq.-1.d0) then
              call tetrah (nov,nop,xv,yv,zv,noe,k,xcoor,ycoor,zcoor,
     %          astflag1)
c              endif
c
              if (astflag1.eq.1) then
c compute pieces of masses
                l0 = l0 + 1
                vol = cubx * cuby * cubz
                mass = d * vol
                mc(l0) = mass
                fmt = fmt + mass
                fvt = fvt + vol
                xc(l0) = xcoor
                yc(l0) = ycoor
                zc(l0) = zcoor
              end if
              xstep = xstep + cubx
            end do
            ystep = ystep + cuby
          end do
          zstep = zstep + cubz
        end do
c
c 2º Octante
c        write(6,'(a21)') 'Starting 2 Octant...'
        zstep = 0.d0
        do while (zstep.lt.zmax)
          ystep = 0.d0
          do while (ystep.lt.ymax)
            xstep = 0.d0
            do while (xstep.gt.xmin)
